def current_single_layer_compile_source_prompt_rules(
    source_bundle: dict[str, Any],
) -> list[str]:
    """Bind a compile repair Agent to the source bytes currently on disk.

    Compile-repair prompts can contain older source snapshots as evidence.  A
    complete replacement copied from one of those snapshots can silently
    discard a previously applied semantic fix, so the current source identity
    and a small local context are repeated immediately before the Agent call.
    """

    editable_contract = (
        source_bundle.get("editable_contract", {})
        if isinstance(source_bundle.get("editable_contract"), dict)
        else {}
    )
    paths = [
        Path(str(value)).resolve()
        for value in editable_contract.get("allowed_exact_files", [])
        if str(value)
    ]
    rules = [
        "The following source binding is newer than every historical document in this prompt and is authoritative for this turn.",
        "Never copy a complete SystemVerilog file, expected hash, or sideband wiring from historical evidence or an older Agent result.",
        "For a localized compile error, prefer operation=replace_text with content='' and exact unique old_text/new_text anchors.",
        "The replacement must preserve all current lines outside the named compile-error connection. Do not restore or remove an unrelated earlier repair.",
    ]
    for path in paths:
        if not path.is_file():
            continue
        try:
            lines = path.read_text(encoding="utf-8").splitlines()
        except (OSError, UnicodeError):
            continue
        anchor = next(
            (index for index, line in enumerate(lines) if "Linear_4 down (" in line),
            None,
        )
        if anchor is None:
            anchor = 0
        start = max(0, anchor - 4)
        end = min(len(lines), anchor + 25)
        excerpt = "\n".join(
            f"{index + 1}: {lines[index]}" for index in range(start, end)
        )
        rules.append(
            "Current editable source binding: "
            f"path={path}. Current local context:\n"
            f"{excerpt}"
        )
    return rules


def _direct_applied_source_transition(
    run_dir: Path,
    target: Path,
    before_sha256: str,
    after_sha256: str,
) -> dict[str, Any] | None:
    """Find a successful recorded edit that directly produced current bytes."""

    report_paths = [run_dir / "repair_execution" / "agent_patch_application.json"]
    report_paths.extend(
        sorted(
            (run_dir / "repair_execution" / "loop").glob(
                "iteration_*/*agent_patch_application*.json"
            ),
            reverse=True,
        )
    )
    resolved_target = target.resolve()
    for report_path in report_paths:
        report = read_json_if_exists(report_path)
        if report.get("status") != "pass" or report.get("blockers"):
            continue
        for row in report.get("files", []):
            if not isinstance(row, dict):
                continue
            row_path = Path(str(row.get("path") or ""))
            row_path = (
                row_path if row_path.is_absolute() else Path.cwd() / row_path
            ).resolve()
            if (
                row_path == resolved_target
                and row.get("before_sha256") == before_sha256
                and row.get("after_sha256") == after_sha256
            ):
                return {
                    "path": str(report_path),
                    "sha256": sha256_file(report_path),
                    "source_change": copy.deepcopy(row),
                }
    return None


def rebase_stale_single_layer_compile_agent_output(
    output: dict[str, Any],
    compile_context: dict[str, Any],
    run_dir: Path,
) -> tuple[dict[str, Any], dict[str, Any]]:
    """Rebase an Agent-approved undefined-port removal onto current source.

    This is intentionally narrower than a three-way source merge.  It applies
    only when real VCS identified undefined named ports, the Agent removed
    those exact connections, and a successful recorded Agent edit proves that
    the stale source hash is the direct parent of the current file.  All other
    current lines are retained byte-for-byte.
    """

    result = copy.deepcopy(output)
    edits = result.get("file_edits", [])
    diagnostic = (
        compile_context.get("diagnostic", {})
        if isinstance(compile_context.get("diagnostic"), dict)
        else {}
    )
    missing_ports = [
        str(row.get("port") or "")
        for row in diagnostic.get("missing_ports", [])
        if isinstance(row, dict) and str(row.get("port") or "")
    ]
    source_path = Path(str(diagnostic.get("source_path") or ""))
    source_path = (
        source_path if source_path.is_absolute() else run_dir / source_path
    ).resolve()
    report: dict[str, Any] = {
        "schema_version": "spatialaccagent.single_layer_compile_source_rebase.v1",
        "status": "not_required",
        "blockers": [],
        "rebased_files": [],
        "policy": {
            "real_vcs_undefined_ports_only": True,
            "direct_recorded_source_ancestry_required": True,
            "current_unrelated_lines_preserved": True,
            "agent_root_cause_and_repair_intent_unchanged": True,
        },
    }
    if result.get("status") != "ready_to_apply" or not isinstance(edits, list):
        return result, report

    stale_edits: list[tuple[int, dict[str, Any], Path, str]] = []
    for index, edit in enumerate(edits):
        if not isinstance(edit, dict) or edit.get("operation") == "create":
            continue
        target = Path(str(edit.get("path") or ""))
        target = (target if target.is_absolute() else Path.cwd() / target).resolve()
        if not target.is_file():
            continue
        actual = sha256_file(target)
        expected = str(edit.get("expected_sha256") or "")
        if expected and expected != actual:
            stale_edits.append((index, edit, target, actual))
    if not stale_edits:
        return result, report

    blockers: list[str] = []
    if "Undefined port in module instantiation" not in str(diagnostic.get("error") or ""):
        blockers.append("current compiler diagnostic is not an undefined named-port error")
    if not missing_ports:
        blockers.append("current compiler diagnostic contains no missing named ports")
    if len(stale_edits) != 1:
        blockers.append("undefined-port source rebase requires exactly one stale Agent edit")

    for index, edit, target, actual in stale_edits:
        expected = str(edit.get("expected_sha256") or "")
        proposed = str(edit.get("content") or "")
        if target != source_path:
            blockers.append("stale Agent edit does not target the diagnostic source")
            continue
        if edit.get("operation") != "replace" or not proposed:
            blockers.append("stale Agent edit is not a complete source replacement")
            continue
        ancestry = _direct_applied_source_transition(
            run_dir, target, expected, actual
        )
        if ancestry is None:
            blockers.append(
                "stale Agent source is not the recorded direct parent of current source"
            )
            continue
        current = target.read_text(encoding="utf-8")
        replacements: list[dict[str, str]] = []
        for port in missing_ports:
            connection = re.compile(
                rf"(?m)^[ \t]*\.{re.escape(port)}[ \t]*\([^;\n]*\),?[ \t]*(?:\n|$)"
            )
            current_matches = list(connection.finditer(current))
            if len(current_matches) != 1:
                blockers.append(
                    f"current diagnostic port connection {port} occurs {len(current_matches)} times"
                )
                continue
            if connection.search(proposed) is not None:
                blockers.append(
                    f"Agent replacement did not remove diagnostic port connection {port}"
                )
                continue
            replacements.append(
                {"old_text": current_matches[0].group(0), "new_text": ""}
            )
        if blockers:
            continue
        result["file_edits"][index] = {
            **{
                key: copy.deepcopy(value)
                for key, value in edit.items()
                if key not in {"operation", "expected_sha256", "content", "text_replacements"}
            },
            "path": str(target),
            "operation": "replace_text",
            "expected_sha256": actual,
            "content": "",
            "text_replacements": replacements,
        }
        report["rebased_files"].append(
            {
                "path": str(target),
                "stale_agent_expected_sha256": expected,
                "current_sha256": actual,
                "removed_named_ports": missing_ports,
                "direct_source_transition": ancestry,
            }
        )

    if blockers:
        report["status"] = "blocked"
        report["blockers"] = list(dict.fromkeys(blockers))
        return output, report
    report["status"] = "pass"
    return result, report


def retryable_single_layer_compile_repair_record(
    out_dir: Path,
    run_dir: Path,
    step: dict[str, Any],
    compile_context: dict[str, Any],
) -> dict[str, Any] | None:
    """Recover a trusted Agent result rejected only for stale source identity."""

    expected_checkpoint = repair_step_checkpoint(step).get("fingerprint_sha256")
    loop_root = out_dir / "loop"
    for iteration_path in sorted(
        loop_root.glob("iteration_*/iteration_record.json"), reverse=True
    ):
        iteration = read_json_if_exists(iteration_path)
        snapshots = iteration.get("evidence_snapshots", [])
        if not isinstance(snapshots, list):
            continue
        by_role = {
            str(row.get("role")): Path(str(row.get("snapshot_path")))
            for row in snapshots
            if isinstance(row, dict) and row.get("snapshot_path")
        }
        patch_path = by_role.get("agent_patch_application")
        record_path = by_role.get("llm_record")
        prompt_path = by_role.get("request_path")
        if not all(
            path is not None and path.is_file()
            for path in (patch_path, record_path, prompt_path)
        ):
            continue
        patch = read_json_if_exists(patch_path)
        blockers = patch.get("blockers", [])
        if (
            patch.get("status") != "blocked"
            or patch.get("files") != []
            or patch.get("agent_status") != "ready_to_apply"
            or not isinstance(blockers, list)
            or len(blockers) != 1
            or "must bind the current source SHA-256" not in str(blockers[0])
            or patch.get("repair_checkpoint", {}).get("fingerprint_sha256")
            != expected_checkpoint
        ):
            continue
        record = read_json_if_exists(record_path)
        if (
            record.get("agent") != SINGLE_LAYER_COMPILE_RTL_REPAIR_AGENT
            or record.get("mode") != "llm"
            or record.get("used_fallback") is True
            or record.get("error") is not None
            or record.get("prompt_hash") != sha256_file(prompt_path)
        ):
            continue
        output = record.get("output", {})
        try:
            validate_schema(output, IMPLEMENTATION_REPAIR_SCHEMA)
        except ValueError:
            continue
        normalized, rebase = rebase_stale_single_layer_compile_agent_output(
            output, compile_context, run_dir
        )
        if rebase.get("status") != "pass":
            continue
        recovered = copy.deepcopy(record)
        recovered["output"] = normalized
        recovered["result_path"] = str(record_path)
        recovered["request_path"] = str(prompt_path)
        recovered["single_layer_compile_source_rebase"] = rebase
        return recovered
    return None


def write_text(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8")


def read_text(path: Path) -> str:
    return path.read_text(encoding="utf-8")


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def is_sha256(value: Any) -> bool:
    text = str(value or "")
    return len(text) == 64 and all(character in "0123456789abcdef" for character in text)


