def framework_vcs_compile_plan_errors(
    plan: Any,
    *,
    expected_source_count: int | None = None,
    expected_source_ids: list[str] | None = None,
    expected_top_module: str = "",
    expected_command_env: dict[str, str] | None = None,
    validation_mode: str = "exact_sample_physical_ddr",
) -> list[str]:
    if not isinstance(plan, dict):
        return ["framework VCS compile plan is not an object"]
    errors: list[str] = []

    def contains_ref(value: Any) -> bool:
        if isinstance(value, dict):
            return "$ref" in value or any(contains_ref(child) for child in value.values())
        if isinstance(value, list):
            return any(contains_ref(child) for child in value)
        return False

    if plan.get("schema_version") != "spatialaccagent.vcs_compile_plan.v1":
        errors.append("framework VCS compile plan schema is unsupported")
    if plan.get("status") != "ready":
        errors.append("framework VCS compile plan status is not ready")
    if contains_ref(plan):
        errors.append("framework VCS compile plan contains an unresolved reference")
    expected_plan_fields = {
        "schema_version",
        "status",
        "tool_binding",
        "compile_authority",
        "top_module",
        "ordered_commands",
        "output",
    }
    if set(plan) != expected_plan_fields:
        errors.append("framework VCS compile plan fields differ from the consumer schema")
    top_module = str(plan.get("top_module") or "")
    if not top_module or (expected_top_module and top_module != expected_top_module):
        errors.append("framework VCS compile plan top_module differs from the board testbench")
    if plan.get("output") != FRAMEWORK_VCS_OUTPUT:
        errors.append("framework VCS compile plan output is not simv")
    compile_authority = plan.get("compile_authority")
    required_authority_fields = [
        "vivado_facts_path",
        "vivado_facts_sha256",
        "simulator_export_context_sha256s",
    ]
    if validation_mode != "compute_slot_axi":
        required_authority_fields.extend(
            [
                "external_fixture_contract_sha256",
                "external_fixture_export_context_sha256s",
            ]
        )
    if not isinstance(compile_authority, dict) or not all(
        compile_authority.get(field) for field in required_authority_fields
    ):
        errors.append("framework VCS compile plan compile_authority is incomplete")
    tool_binding = plan.get("tool_binding")
    if not isinstance(tool_binding, dict) or not all(
        tool_binding.get(field)
        for field in ("role", "name", "host", "port", "executable")
    ):
        errors.append("framework VCS compile plan tool_binding is incomplete")
        tool_binding = {}
    command_env = expected_command_env if isinstance(expected_command_env, dict) else {}

    commands = plan.get("ordered_commands")
    if not isinstance(commands, list) or not commands:
        errors.append("framework VCS compile plan ordered_commands is empty")
        return list(dict.fromkeys(errors))
    source_ids: list[str] = []
    elaboration_indices: list[int] = []
    shell_tokens = {"|", "||", "&&", ";", ">", ">>", "<", "2>&1", "tee"}
    command_fields = {
        "order",
        "phase",
        "tool_role",
        "executable",
        "argv",
        "source_ids",
        "cwd",
        "env",
        "shell",
        "authority_refs",
    }
    for index, command in enumerate(commands):
        if not isinstance(command, dict):
            errors.append(f"framework VCS command {index} is not an object")
            continue
        if set(command) != command_fields:
            errors.append(
                f"framework VCS command {index} fields differ from the consumer schema"
            )
        if isinstance(command.get("order"), bool) or command.get("order") != index:
            errors.append(f"framework VCS command {index} has non-contiguous order")
        if command.get("tool_role") != tool_binding.get("role"):
            errors.append(f"framework VCS command {index} has the wrong tool_role")
        if command.get("cwd") != FRAMEWORK_VCS_COMMAND_CWD:
            errors.append(f"framework VCS command {index} has the wrong staging cwd")
        if command.get("env") != command_env:
            errors.append(f"framework VCS command {index} differs from the tool environment")
        if command.get("shell") is not False:
            errors.append(f"framework VCS command {index} must disable shell execution")
        authority_refs = command.get("authority_refs")
        if (
            not isinstance(authority_refs, list)
            or not authority_refs
            or len(authority_refs) != len(set(map(str, authority_refs)))
            or not all(
                isinstance(value, str)
                and re.fullmatch(r"[0-9a-fA-F]{64}", value)
                for value in authority_refs
            )
        ):
            errors.append(f"framework VCS command {index} has invalid authority_refs")
        argv = command.get("argv")
        declared_ids = command.get("source_ids")
        if not isinstance(argv, list) or not isinstance(declared_ids, list):
            errors.append(f"framework VCS command {index} lacks argv/source_ids")
            continue
        token_ids: list[str] = []
        include_ids: list[str] = []
        for token_index, token in enumerate(argv):
            if isinstance(token, str):
                if not token or any(value in token for value in ("\x00", "\n", "\r")):
                    errors.append(
                        f"framework VCS command {index} argv[{token_index}] is unsafe"
                    )
            elif isinstance(token, dict) and set(token) == {"source_id"}:
                source_id = str(token.get("source_id") or "")
                token_ids.append(source_id)
                if not source_id:
                    errors.append(
                        f"framework VCS command {index} argv[{token_index}] has no source_id"
                    )
            elif isinstance(token, dict) and set(token) == {"include_dir_id"}:
                include_id = str(token.get("include_dir_id") or "")
                include_ids.append(include_id)
                if not include_id:
                    errors.append(
                        f"framework VCS command {index} argv[{token_index}] has no include_dir_id"
                    )
            else:
                errors.append(
                    f"framework VCS command {index} argv[{token_index}] has an unsupported token"
                )
        if token_ids != [str(value) for value in declared_ids]:
            errors.append(f"framework VCS command {index} source tokens differ from source_ids")
        executable = str(command.get("executable") or "")
        literal_tokens = [token for token in argv if isinstance(token, str)]
        if (
            not executable
            or any(value in executable for value in ("\x00", "\n", "\r"))
            or any(char.isspace() for char in executable)
        ):
            errors.append(f"framework VCS command {index} has no executable")
        if executable in literal_tokens[:1]:
            errors.append(f"framework VCS command {index} duplicates its executable in argv")
        if any(token in shell_tokens for token in literal_tokens):
            errors.append(f"framework VCS command {index} contains shell transport")
        if any(
            token.startswith("-") and any(char.isspace() for char in token)
            for token in literal_tokens
        ):
            errors.append(f"framework VCS command {index} has a bundled option token")
        phase = str(command.get("phase") or "")
        if phase == "compile":
            if literal_tokens.count("-work") != 1:
                errors.append(
                    f"framework VCS compile command {index} lacks one explicit -work"
                )
            if not token_ids:
                errors.append(f"framework VCS compile command {index} has no source token")
            if any(source_id in literal_tokens for source_id in token_ids):
                errors.append(
                    f"framework VCS compile command {index} contains a raw source ID"
                )
            source_ids.extend(token_ids)
        elif phase == "elaborate":
            elaboration_indices.append(index)
            if token_ids:
                errors.append(f"framework VCS elaboration command {index} has source tokens")
            if include_ids:
                errors.append(
                    f"framework VCS elaboration command {index} has include-dir tokens"
                )
        else:
            errors.append(f"framework VCS command {index} has unsupported phase {phase!r}")
    if len(source_ids) != len(set(source_ids)):
        errors.append("framework VCS compile plan contains duplicate source IDs")
    if expected_source_count is not None and len(source_ids) != expected_source_count:
        errors.append(
            "framework VCS compile plan source count differs from transformed-source authority"
        )
    if expected_source_ids is not None and source_ids != expected_source_ids:
        errors.append(
            "framework VCS compile plan source order differs from transformed-source authority"
        )
    if elaboration_indices != [len(commands) - 1]:
        errors.append("framework VCS compile plan does not end in exactly one elaboration")
    else:
        elaboration_argv = commands[-1].get("argv", [])
        if top_module not in elaboration_argv or FRAMEWORK_VCS_OUTPUT not in elaboration_argv:
            errors.append("framework VCS elaboration does not bind top_module and simv")
    return list(dict.fromkeys(errors))


def bind_framework_vcs_compile_plan(
    manifest: dict[str, Any],
    run_dir: Path,
    out_dir: Path,
    manifest_path: Path,
) -> tuple[dict[str, Any], dict[str, Any]]:
    """Materialize the deterministic Vivado/VCS transport plan after agent semantics."""

    normalized = copy.deepcopy(manifest)
    board_plan = normalized.get("board_simulation_preflight_plan")
    if not isinstance(board_plan, dict):
        return normalized, {
            "status": "blocked",
            "blockers": ["agent board manifest has no board_simulation_preflight_plan"],
        }
    testbench = board_plan.get("testbench")
    testbench = testbench if isinstance(testbench, dict) else {}
    board_top = str(board_plan.get("top_module") or "")
    declared_testbench_top = str(testbench.get("top_module") or "")
    module_alias = str(testbench.get("module") or "")
    if (
        declared_testbench_top
        and module_alias
        and declared_testbench_top != module_alias
    ):
        return normalized, {
            "status": "blocked",
            "blockers": [
                "agent board manifest testbench.top_module conflicts with testbench.module"
            ],
        }
    testbench_top = declared_testbench_top or module_alias
    if testbench_top and not declared_testbench_top:
        # Older board manifests use module for the generated testbench top.
        testbench["top_module"] = testbench_top
    if not board_top or not testbench_top or board_top != testbench_top:
        return normalized, {
            "status": "blocked",
            "blockers": [
                "agent board manifest top_module does not exactly match testbench.top_module"
            ],
        }
    expected_top = board_top
    authority = board_manifest_lossless_rewrite_authority(
        run_dir,
        out_dir,
        manifest_path,
        manifest_override=normalized,
    )
    expanded = authority.get("expanded_source_authority")
    expanded = expanded if isinstance(expanded, dict) else {}
    vcs_authority = expanded.get("vcs_command_rewrite_authority")
    vcs_authority = vcs_authority if isinstance(vcs_authority, dict) else {}
    plan = vcs_authority.get("manifest_ready_vcs_compile_plan")
    expected_source_count = vcs_authority.get("counts", {}).get("total_sources")
    expected_source_ids = vcs_authority.get("ordered_source_ids")
    expected_source_ids = (
        [str(value) for value in expected_source_ids]
        if isinstance(expected_source_ids, list)
        else None
    )
    tool_binding = plan.get("tool_binding") if isinstance(plan, dict) else {}
    expected_command_env = (
        copy.deepcopy(tool_binding.get("env"))
        if isinstance(tool_binding, dict) and isinstance(tool_binding.get("env"), dict)
        else {}
    )
    errors = framework_vcs_compile_plan_errors(
        plan,
        expected_source_count=(
            expected_source_count if isinstance(expected_source_count, int) else None
        ),
        expected_source_ids=expected_source_ids,
        expected_top_module=expected_top,
        expected_command_env=expected_command_env,
        validation_mode=str(
            board_plan.get("validation_mode") or "exact_sample_physical_ddr"
        ),
    )
    if errors:
        return normalized, {"status": "blocked", "blockers": errors}
    board_plan["vcs_compile_plan"] = copy.deepcopy(plan)
    return normalized, {
        "status": "pass",
        "blockers": [],
        "ordered_command_count": len(plan["ordered_commands"]),
        "compile_source_count": expected_source_count,
        "vcs_compile_plan_sha256": canonical_contract_sha256(plan),
        "top_module": plan.get("top_module"),
        "output": plan.get("output"),
    }


def framework_vcs_plan_binding_missing_prerequisites(
    run_dir: Path,
    validation_mode: str = "exact_sample_physical_ddr",
) -> list[str]:
    required = {
        "board source identity": (
            run_dir
            / "verification"
            / "board_interface"
            / "board_source_identity.json"
        ),
        "functional-verification tool profile": run_dir / "input" / "tool_profile.json",
    }
    if validation_mode != EXACT_BOARD_FUNCTIONAL_VALIDATION_MODE:
        required["external simulation fixture"] = (
            run_dir
            / "verification"
            / "board_interface"
            / "external_simulation_fixture.json"
        )
    return [f"{label}: {path}" for label, path in required.items() if not path.is_file()]


def framework_vcs_plan_binding_prerequisites_present(
    run_dir: Path,
    validation_mode: str = "exact_sample_physical_ddr",
) -> bool:
    return not framework_vcs_plan_binding_missing_prerequisites(
        run_dir, validation_mode
    )


def bind_agent_owned_board_source_hashes(
    manifest: dict[str, Any],
    run_dir: Path,
    staged_content_by_path: dict[Path, str],
) -> tuple[dict[str, Any], dict[str, Any]]:
    """Bind agent-owned board manifest rows to their final same-batch contents."""

    normalized = copy.deepcopy(manifest)
    board_root = (run_dir / "generated" / "board_integration").resolve()
    staged_content = {
        path.resolve(): content for path, content in staged_content_by_path.items()
    }
    source_hashes: dict[str, str] = {}
    bound_source_ids: set[str] = set()
    blockers: list[str] = []

    def bind_source_row(row: Any, label: str) -> str | None:
        if not isinstance(row, dict):
            return None
        raw_path = str(row.get("path") or row.get("local_path") or "").strip()
        if not raw_path:
            return None
        path = Path(raw_path).expanduser()
        path = path if path.is_absolute() else Path.cwd() / path
        try:
            path = path.resolve()
        except OSError as exc:
            blockers.append(f"{label} path cannot be resolved before board hash binding: {exc}")
            return None
        if (
            not path.is_relative_to(board_root)
            or path.suffix.lower() not in {".v", ".sv"}
        ):
            return None
        content = staged_content.get(path)
        if content is not None:
            digest = hashlib.sha256(content.encode("utf-8")).hexdigest()
        elif path.is_file():
            digest = sha256_file(path)
        else:
            blockers.append(
                f"{label} agent-owned board source is neither staged nor present: {path}"
            )
            return None
        row["sha256"] = digest
        if "local_sha256" in row:
            row["local_sha256"] = digest
        source_id = str(row.get("source_id") or "").strip()
        if source_id:
            prior = source_hashes.get(source_id)
            if prior is not None and prior != digest:
                blockers.append(
                    f"{label} source_id resolves to conflicting final board source hashes: {source_id}"
                )
            else:
                source_hashes[source_id] = digest
                bound_source_ids.add(source_id)
        return digest

    def bind_source_rows(value: Any, label: str) -> None:
        if not isinstance(value, list):
            return
        for index, row in enumerate(value):
            bind_source_row(row, f"{label}[{index}]")

    top_harness = normalized.get("multilayer_harness")
    if isinstance(top_harness, dict):
        bind_source_rows(
            top_harness.get("source_files"),
            "multilayer_harness.source_files",
        )

    plan = normalized.get("board_simulation_preflight_plan")
    if isinstance(plan, dict):
        plan_harness = plan.get("multilayer_harness")
        if isinstance(plan_harness, dict):
            bind_source_rows(
                plan_harness.get("source_files"),
                "board_simulation_preflight_plan.multilayer_harness.source_files",
            )

        replacements = plan.get("source_replacements")
        if isinstance(replacements, list):
            for index, replacement in enumerate(replacements):
                if not isinstance(replacement, dict):
                    continue
                digest = bind_source_row(
                    replacement.get("source"),
                    f"board_simulation_preflight_plan.source_replacements[{index}].source",
                )
                generated_path = str(
                    replacement.get("generated_source_path") or ""
                ).strip()
                if generated_path:
                    generated_row = {
                        "source_id": replacement.get("generated_source_id"),
                        "path": generated_path,
                    }
                    generated_digest = bind_source_row(
                        generated_row,
                        f"board_simulation_preflight_plan.source_replacements[{index}]",
                    )
                    digest = generated_digest or digest
                if digest:
                    replacement["generated_source_sha256"] = digest

        testbench_plan = plan.get("testbench")
        if isinstance(testbench_plan, dict):
            testbench_source = testbench_plan.get("source")
            if isinstance(testbench_source, dict):
                testbench_digest = bind_source_row(
                    testbench_source,
                    "board_simulation_preflight_plan.testbench.source",
                )
            else:
                testbench_digest = bind_source_row(
                    testbench_plan,
                    "board_simulation_preflight_plan.testbench",
                )
            scan = testbench_plan.get("forbidden_construct_scan")
            if testbench_digest and isinstance(scan, dict):
                scan["source_sha256"] = testbench_digest
            debug_contract = testbench_plan.get("debug_observability_contract")
            probes = (
                debug_contract.get("probes")
                if isinstance(debug_contract, dict)
                else None
            )
            if isinstance(probes, list):
                for probe in probes:
                    if not isinstance(probe, dict):
                        continue
                    digest = source_hashes.get(str(probe.get("source_id") or ""))
                    if digest:
                        probe["source_sha256"] = digest

        monitor_contract = plan.get("protocol_monitor_contract")
        monitors = (
            monitor_contract.get("monitors")
            if isinstance(monitor_contract, dict)
            else None
        )
        if isinstance(monitors, list):
            for index, monitor in enumerate(monitors):
                if isinstance(monitor, dict):
                    bind_source_rows(
                        monitor.get("source_files"),
                        (
                            "board_simulation_preflight_plan.protocol_monitor_contract."
                            f"monitors[{index}].source_files"
                        ),
                    )

        evidence_records = plan.get("generated_evidence_records")
        if isinstance(evidence_records, list):
            for row in evidence_records:
                if not isinstance(row, dict):
                    continue
                digest = source_hashes.get(str(row.get("source_id") or ""))
                if digest:
                    row["source_sha256"] = digest

    top_evidence_records = normalized.get("generated_evidence_records")
    if isinstance(top_evidence_records, list):
        for row in top_evidence_records:
            if not isinstance(row, dict):
                continue
            digest = source_hashes.get(str(row.get("source_id") or ""))
            if digest:
                row["source_sha256"] = digest

    return normalized, {
        "bound_source_ids": sorted(bound_source_ids),
        "blockers": list(dict.fromkeys(blockers)),
    }


def _deep_merge_json_object(
    base: dict[str, Any], patch: dict[str, Any]
) -> dict[str, Any]:
    """Merge an agent patch without treating omitted or null fields as deletion."""

    merged = copy.deepcopy(base)
    for key, value in patch.items():
        prior = merged.get(key)
        if isinstance(prior, dict) and isinstance(value, dict):
            merged[key] = _deep_merge_json_object(prior, value)
        else:
            merged[key] = copy.deepcopy(value)
    return merged


def _json_pointer_value(document: Any, pointer: str) -> tuple[bool, Any]:
    if (
        not isinstance(pointer, str)
        or not pointer.startswith("/")
        or len(pointer) > 4096
    ):
        return False, None
    current = document
    tokens = pointer.split("/")[1:]
    if len(tokens) > 64:
        return False, None
    for raw_token in tokens:
        token = raw_token.replace("~1", "/").replace("~0", "~")
        if isinstance(current, dict):
            if token not in current:
                return False, None
            current = current[token]
        elif isinstance(current, list):
            if not token.isdigit():
                return False, None
            index = int(token)
            if index >= len(current):
                return False, None
            current = current[index]
        else:
            return False, None
    return True, current


def _verification_capability_package_pointer(pointer: str) -> str:
    """Resolve Agent pointers that include the named LLM input wrapper."""

    prefix = "/verification_capability_repair_package"
    return pointer[len(prefix) :] if pointer.startswith(prefix + "/") else pointer


def _current_board_feedback_frontier(
    package: dict[str, Any],
) -> tuple[str, dict[str, Any]]:
    feedback = (
        package.get("current_board_vcs_feedback", {})
        if isinstance(package.get("current_board_vcs_feedback"), dict)
        else {}
    )
    diagnosis_binding = (
        feedback.get("diagnosis", {})
        if isinstance(feedback.get("diagnosis"), dict)
        else {}
    )
    diagnosis = (
        diagnosis_binding.get("value", {})
        if isinstance(diagnosis_binding.get("value"), dict)
        else {}
    )
    failure_evidence = (
        diagnosis.get("failure_evidence", {})
        if isinstance(diagnosis.get("failure_evidence"), dict)
        else {}
    )
    causal_binding = (
        failure_evidence.get("sacg_cctg_causal_slice", {})
        if isinstance(failure_evidence.get("sacg_cctg_causal_slice"), dict)
        else {}
    )
    causal_slice = (
        causal_binding.get("value", {})
        if isinstance(causal_binding.get("value"), dict)
        else {}
    )
    frontier = (
        causal_slice.get("earliest_unproven_frontier", {})
        if isinstance(causal_slice.get("earliest_unproven_frontier"), dict)
        else {}
    )
    frontier_id = str(frontier.get("frontier_id") or "")
    if frontier_id:
        return frontier_id, causal_binding

    # A compile failure has no runtime SACG/CCTG frontier because the DUT was
    # never elaborated or simulated.  Keep that distinction explicit while
    # still giving the Agent a stable repair-loop frontier for provenance
    # collection (source location, filelist, and compile context).
    failure_class = str(
        diagnosis.get("failure_class")
        or failure_evidence.get("failure_class")
        or ""
    )
    compile = (
        failure_evidence.get("compile", {})
        if isinstance(failure_evidence.get("compile"), dict)
        else {}
    )
    compile_failed = compile.get("status") == "fail" or compile.get("returncode") not in {
        None,
        0,
    }
    if failure_class == "vcs_compile_failure" and compile_failed:
        return "vcs_compile_failure", {}
    return "", causal_binding


def _current_board_feedback_frontier_ids(package: dict[str, Any]) -> set[str]:
    """Return the canonical frontier plus its explicitly named CCTG aliases."""

    canonical_frontier, causal_binding = _current_board_feedback_frontier(package)
    frontier_ids = {canonical_frontier} if canonical_frontier else set()
    causal_slice = (
        causal_binding.get("value", {})
        if isinstance(causal_binding.get("value"), dict)
        else {}
    )
    frontier = (
        causal_slice.get("earliest_unproven_frontier", {})
        if isinstance(causal_slice.get("earliest_unproven_frontier"), dict)
        else {}
    )
    for value in frontier.get("failed_boundary_ids", []):
        if isinstance(value, str) and value:
            frontier_ids.add(value)
    prior_runtime_frontier = frontier.get("prior_runtime_frontier", {})
    if isinstance(prior_runtime_frontier, dict):
        value = prior_runtime_frontier.get("frontier_id")
        if isinstance(value, str) and value:
            frontier_ids.add(value)
    return frontier_ids


def _current_board_feedback_hashes(package: dict[str, Any]) -> set[str]:
    feedback = (
        package.get("current_board_vcs_feedback", {})
        if isinstance(package.get("current_board_vcs_feedback"), dict)
        else {}
    )
    hashes: set[str] = set()
    for field in ("runner_report", "diagnosis", "source_iteration_record"):
        binding = feedback.get(field, {})
        if isinstance(binding, dict):
            digest = str(binding.get("sha256") or "")
            if re.fullmatch(r"[0-9a-f]{64}", digest):
                hashes.add(digest)
    _, causal_binding = _current_board_feedback_frontier(package)
    causal_digest = str(causal_binding.get("sha256") or "")
    if re.fullmatch(r"[0-9a-f]{64}", causal_digest):
        hashes.add(causal_digest)
    return hashes


def current_board_runtime_frontier_static_repair_guard(
    package: dict[str, Any],
) -> dict[str, Any]:
    """Identify a resolved static prerequisite followed by a runtime frontier.

    A successful exact-board preflight and compile establish that manifest compile
    authority is no longer the earliest blocker for this source-bound execution.
    When the same execution instead reaches a semantic board dataflow frontier,
    another manifest-only command-authority edit cannot explain or repair that
    runtime result. Keep this as a compact, hash-bound Agent constraint rather
    than inferring a hardware owner.
    """

    feedback = (
        package.get("current_board_vcs_feedback", {})
        if isinstance(package.get("current_board_vcs_feedback"), dict)
        else {}
    )
    runner_binding = (
        feedback.get("runner_report", {})
        if isinstance(feedback.get("runner_report"), dict)
        else {}
    )
    diagnosis_binding = (
        feedback.get("diagnosis", {})
        if isinstance(feedback.get("diagnosis"), dict)
        else {}
    )
    runner = (
        runner_binding.get("value", {})
        if isinstance(runner_binding.get("value"), dict)
        else {}
    )
    diagnosis = (
        diagnosis_binding.get("value", {})
        if isinstance(diagnosis_binding.get("value"), dict)
        else {}
    )
    failure_class = str(diagnosis.get("failure_class") or "")
    frontier_id, causal_binding = _current_board_feedback_frontier(package)
    compile_result = (
        runner.get("compile", {})
        if isinstance(runner.get("compile"), dict)
        else {}
    )
    run_result = (
        runner.get("run", {})
        if isinstance(runner.get("run"), dict)
        else {}
    )
    preflight = (
        runner.get("exact_board_preflight", {})
        if isinstance(runner.get("exact_board_preflight"), dict)
        else {}
    )
    preflight_passed = (
        runner.get("exact_board_preflight_passed") is True
        and preflight.get("status") == "pass"
    )
    runtime_frontier = (
        failure_class == "board_output_lifecycle_frontier_violation"
        and bool(frontier_id)
        and compile_result.get("status") == "pass"
        and run_result.get("status") == "fail"
        and run_result.get("returncode") in {SEMANTIC_STALL_EXIT_CODE, 87}
    )
    active = preflight_passed and runtime_frontier
    return {
        "schema_version": (
            "spatialaccagent.runtime_frontier_static_repair_guard.v1"
        ),
        "status": "active" if active else "not_applicable",
        "failure_class": failure_class or None,
        "frontier_id": frontier_id or None,
        "input_fingerprint_sha256": runner.get("input_fingerprint_sha256"),
        "runner_report_sha256": runner_binding.get("sha256"),
        "diagnosis_sha256": diagnosis_binding.get("sha256"),
        "causal_slice_sha256": causal_binding.get("sha256"),
        "preflight_passed": preflight_passed,
        "compile_status": compile_result.get("status"),
        "run_returncode": run_result.get("returncode"),
        "policy": {
            "static_compile_authority_is_closed_after_passing_preflight": True,
            "runtime_frontier_requires_causally_distinct_observation_or_repair": True,
            "does_not_assign_hardware_root_cause": True,
            "does_not_authorize_lower_layer_replay_without_new_contradiction": True,
        },
    }


def stale_static_board_authority_repair_blockers(
    output: dict[str, Any],
    run_dir: Path,
    guard: dict[str, Any],
) -> list[str]:
    """Reject a manifest-only compile-authority edit after a runtime frontier.

    This is intentionally narrow. It permits a causally distinct board-source
    observation or repair and does not treat the observed output frontier as an
    RTL root-cause verdict.
    """

    if guard.get("status") != "active":
        return []
    edits = output.get("file_edits", [])
    if not isinstance(edits, list) or not edits:
        return []
    manifest_path = (
        run_dir / "generated" / "memory" / "dut_weight_binding_manifest.json"
    ).resolve()
    for edit in edits:
        if not isinstance(edit, dict):
            return []
        raw_path = Path(str(edit.get("path") or ""))
        target = (
            raw_path if raw_path.is_absolute() else Path.cwd() / raw_path
        ).resolve()
        if target != manifest_path or edit.get("operation") != "merge_json":
            return []
        patch = edit.get("json_content")
        if not isinstance(patch, dict):
            return []
        board_plan = patch.get("board_simulation_preflight_plan")
        if (
            set(patch) != {"board_simulation_preflight_plan"}
            or not isinstance(board_plan, dict)
            or set(board_plan) != {"vcs_compile_plan"}
            or not isinstance(board_plan.get("vcs_compile_plan"), dict)
        ):
            return []
    return [
        "a hash-bound exact-board runtime output-lifecycle frontier occurred after "
        "preflight and compile passed; manifest-only VCS compile-authority edits are "
        "stale and cannot be applied or replayed. Return a causally distinct "
        "output-lifecycle observation or repair bound to the current frontier"
    ]


ADAPTIVE_BOUNDARY_REQUIRED_FIELDS = (
    "valid",
    "ready",
    "fire",
    "accepted_count",
    "first_accepted_payload_digest",
    "last_accepted_payload_digest",
)

ADAPTIVE_DIRECT_SIGNAL_BINDING_FIELDS = (
    "valid_source",
    "ready_source",
    "fire_source",
    "accepted_count_source",
    "payload_source",
)

MIN_ADAPTIVE_DIAGNOSTIC_SOURCES_PER_BOUNDARY = 2
MIN_LAYER3_CORE_DIAGNOSTIC_SIGNALS = 300


def _valid_diagnostic_role(value: Any) -> bool:
    """Accept a readable role label without restricting diagnostic vocabulary.

    Roles classify observations for a human or LLM; they do not change RTL or
    simulator behavior.  The framework must therefore validate only that the
    label is present and safe to serialize, while signal expression and source
    materialization checks remain the actual evidence safeguards.
    """

    role = str(value or "").strip()
    return bool(role) and len(role) <= 160 and all(
        character.isprintable() and character not in "\r\n\t"
        for character in role
    )


def _unwrap_pipeline_boundary_observation_authority(value: Any) -> dict[str, Any]:
    """Read either a direct authority or the standard bound-artifact wrapper."""

    if not isinstance(value, dict):
        return {}
    nested = value.get("value")
    return nested if isinstance(nested, dict) else value


def _current_pipeline_boundary_observation_authority(
    package: dict[str, Any],
) -> dict[str, Any]:
    """Return the current model-derived pipeline graph without fixed stage names."""

    context = _unwrap_pipeline_boundary_observation_authority(
        package.get("exact_board_integration_repair_context", {})
    )
    context = context if isinstance(context, dict) else {}
    inputs = context.get("adaptive_design_inputs", {})
    inputs = inputs if isinstance(inputs, dict) else {}
    return _unwrap_pipeline_boundary_observation_authority(
        inputs.get("pipeline_boundary_observation_authority")
    )


def _stage_signal_record_is_materialized(
    source: str,
    stage_id: str,
    signal_name: str,
) -> bool:
    """Accept either supported sparse stage-record form in a testbench."""

    direct_trace = (
        "SPATIALACC_STAGE_TRACE" in source
        and f"stage={stage_id}" in source
        and f"signal={signal_name}" in source
    )
    quoted_stage = any(
        marker in source
        for marker in (f'"{stage_id}"', f'\\"{stage_id}\\"')
    )
    quoted_signal = any(
        marker in source
        for marker in (f'"{signal_name}"', f'\\"{signal_name}\\"')
    )
    return direct_trace or (quoted_stage and quoted_signal)


def _pipeline_stage_observation_requirements(
    authority: dict[str, Any] | None,
) -> dict[str, dict[str, list[str]]]:
    """Derive real compute stages and their graph edges from the current DAG.

    Graph-only source and sink nodes are workload ingress/egress, not compute
    stages.  Everything else is kept, including split and join stages.
    """

    if not isinstance(authority, dict) or authority.get("status") != "ready":
        return {}
    declared_stages = authority.get("required_stages")
    if isinstance(declared_stages, list) and declared_stages:
        requirements: dict[str, dict[str, list[str]]] = {}
        for row in declared_stages:
            if not isinstance(row, dict):
                continue
            stage_id = str(row.get("stage_id") or "").strip()
            if not stage_id:
                continue
            requirements[stage_id] = {
                "input_boundary_ids": sorted(
                    str(value)
                    for value in row.get("input_boundary_ids", [])
                    if isinstance(value, str) and value
                ),
                "output_boundary_ids": sorted(
                    str(value)
                    for value in row.get("output_boundary_ids", [])
                    if isinstance(value, str) and value
                ),
            }
        if requirements:
            return requirements
    boundaries = authority.get("required_boundaries", [])
    boundaries = boundaries if isinstance(boundaries, list) else []
    rows: list[dict[str, str]] = []
    for row in boundaries:
        if not isinstance(row, dict):
            continue
        boundary_id = str(row.get("boundary_id") or "").strip()
        src_stage = str(row.get("src_stage") or "").strip()
        dst_stage = str(row.get("dst_stage") or "").strip()
        if boundary_id and src_stage and dst_stage:
            rows.append(
                {
                    "boundary_id": boundary_id,
                    "src_stage": src_stage,
                    "dst_stage": dst_stage,
                }
            )
    if not rows:
        return {}
    source_ids = {row["src_stage"] for row in rows}
    sink_ids = {row["dst_stage"] for row in rows}
    compute_stage_ids = (source_ids | sink_ids) - (source_ids - sink_ids) - (
        sink_ids - source_ids
    )
    return {
        stage_id: {
            "input_boundary_ids": sorted(
                row["boundary_id"]
                for row in rows
                if row["dst_stage"] == stage_id
            ),
            "output_boundary_ids": sorted(
                row["boundary_id"]
                for row in rows
                if row["src_stage"] == stage_id
            ),
        }
        for stage_id in sorted(compute_stage_ids)
    }


def _observation_edit_candidate_texts(output: dict[str, Any]) -> list[str]:
    """Return complete candidate sources produced by observation edits.

    The check is deliberately syntax-agnostic. VCS remains the authority that
    verifies a declared expression resolves in the actual testbench hierarchy.
    Complete candidate text is required because a narrow binding replacement
    may intentionally reuse counters and record tasks already present elsewhere
    in the same testbench.
    """

    texts: list[str] = []
    for edit in output.get("file_edits", []):
        if not isinstance(edit, dict):
            continue
        operation = str(edit.get("operation") or "")
        if operation == "replace_text":
            raw_path = Path(str(edit.get("path") or ""))
            target = (
                raw_path if raw_path.is_absolute() else Path.cwd() / raw_path
            ).resolve()
            try:
                candidate = target.read_text(encoding="utf-8")
            except (OSError, UnicodeError):
                continue
            replacements = edit.get("text_replacements", [])
            if not isinstance(replacements, list) or not replacements:
                continue
            ranges: list[tuple[int, int, str]] = []
            for replacement in replacements:
                if not isinstance(replacement, dict):
                    ranges = []
                    break
                old_text = replacement.get("old_text")
                new_text = replacement.get("new_text")
                if (
                    not isinstance(old_text, str)
                    or not old_text
                    or not isinstance(new_text, str)
                    or candidate.count(old_text) != 1
                ):
                    ranges = []
                    break
                start = candidate.find(old_text)
                ranges.append((start, start + len(old_text), new_text))
            ordered = sorted(ranges, key=lambda row: row[0])
            if not ordered or any(
                current[0] < prior[1]
                for prior, current in zip(ordered, ordered[1:])
            ):
                continue
            for start, end, new_text in reversed(ordered):
                candidate = candidate[:start] + new_text + candidate[end:]
            texts.append(candidate)
        elif operation in {"create", "replace"} and isinstance(
            edit.get("content"), str
        ):
            texts.append(edit["content"])
    return texts


def _bound_observation_compile_repair(
    output: dict[str, Any],
    package: dict[str, Any],
    run_dir: Path,
) -> tuple[bool, str]:
    """Identify a compile fix for a previously installed read-only probe."""

    frontier_id, _ = _current_board_feedback_frontier(package)
    if frontier_id != "vcs_compile_failure":
        return False, ""
    state = (
        package.get("adaptive_observation_state", {})
        if isinstance(package.get("adaptive_observation_state"), dict)
        else {}
    )
    prior_decision = (
        state.get("decision", {})
        if isinstance(state.get("decision"), dict)
        else {}
    )
    prior_frontier = str(prior_decision.get("frontier_id") or "")
    if (
        state.get("status") not in {"pending_real_tool_evidence", "fail"}
        or not prior_frontier
        or not isinstance(state.get("board_source_edits"), list)
        or not state.get("board_source_edits")
    ):
        return False, ""

    allowed_paths = _board_observation_only_edit_paths(run_dir)
    manifest_path = (
        run_dir / "generated" / "memory" / "dut_weight_binding_manifest.json"
    ).resolve()
    edited_paths: set[Path] = set()
    for edit in output.get("file_edits", []):
        if not isinstance(edit, dict):
            return False, ""
        raw_path = Path(str(edit.get("path") or ""))
        target = (
            raw_path if raw_path.is_absolute() else Path.cwd() / raw_path
        ).resolve()
        if target not in allowed_paths:
            return False, ""
        edited_paths.add(target)
    if not edited_paths or not (edited_paths - {manifest_path}):
        return False, ""

    bound_sources = [
        row
        for row in state.get("board_source_edits", [])
        if isinstance(row, dict)
    ]
    if not bound_sources:
        return False, ""
    for row in bound_sources:
        raw_path = Path(str(row.get("path") or ""))
        source_path = (
            raw_path if raw_path.is_absolute() else Path.cwd() / raw_path
        ).resolve()
        expected_sha256 = str(row.get("after_sha256") or "")
        if (
            not source_path.is_file()
            or not re.fullmatch(r"[0-9a-f]{64}", expected_sha256)
            or sha256_file(source_path) != expected_sha256
        ):
            return False, ""
    return True, prior_frontier


def _indexed_observation_name(value: str) -> tuple[str, int] | None:
    match = re.fullmatch(
        r"([A-Za-z_][A-Za-z0-9_$]*)\s*\[\s*([0-9]+)\s*\]",
        value.strip(),
    )
    if match is None:
        return None
    return match.group(1), int(match.group(2))


def _indexed_observation_left_side(value: str) -> tuple[str, int] | None:
    if "=" not in value:
        return None
    return _indexed_observation_name(value.split("=", 1)[0].strip())


def _observation_counter_increment_matches_fire_guard(
    source: str,
    fire_base: str,
    count_base: str,
) -> tuple[list[re.Match[str]], list[re.Match[str]]]:
    """Check array-counter increments against their enclosing fire block.

    Observation code commonly records first/last payloads between the fire
    guard and the counter update.  Matching only the first statement after
    ``begin`` therefore rejects valid read-only probes.  This small balanced
    ``begin``/``end`` scan keeps the check strict while allowing those records.
    """

    increment_pattern = re.compile(
        rf"\b{re.escape(count_base)}\s*\[\s*(?P<index>[A-Za-z_][A-Za-z0-9_$]*)\s*\]"
        rf"\s*<=\s*{re.escape(count_base)}\s*\[\s*(?P=index)\s*\]"
        r"\s*\+\s*(?:[0-9]+\s*'d\s*)?1\s*;"
    )
    guard_pattern = re.compile(
        rf"\bif\s*\(\s*{re.escape(fire_base)}\s*\[\s*"
        rf"(?P<index>[A-Za-z_][A-Za-z0-9_$]*)\s*\]"
        r"\s*(?:(?:===|==)\s*1'b1\s*)?\)\s*begin\b"
    )
    token_pattern = re.compile(
        r'"(?:\\.|[^"\\])*"|//[^\n]*|/\*.*?\*/|\b(?:begin|end)\b',
        re.DOTALL,
    )

    def matching_end(start: int) -> int | None:
        depth = 1
        for token in token_pattern.finditer(source, start):
            text = token.group(0)
            if text.startswith('"') or text.startswith("//") or text.startswith("/*"):
                continue
            if text == "begin":
                depth += 1
            else:
                depth -= 1
                if depth == 0:
                    return token.start()
        return None

    increments = list(increment_pattern.finditer(source))
    guards: list[tuple[str, int, int]] = []
    for guard in guard_pattern.finditer(source):
        end = matching_end(guard.end())
        if end is not None:
            guards.append((guard.group("index"), guard.start(), end))
    guarded = [
        increment
        for increment in increments
        if any(
            index == increment.group("index")
            and start < increment.start() < end
            for index, start, end in guards
        )
    ]
    return increments, guarded


def _array_observation_binding_check(
    bindings_by_boundary: dict[str, dict[str, Any]],
    expected_boundaries: set[str],
    new_texts: list[str],
) -> dict[str, Any]:
    """Verify compact array-based observation code without trusting its names."""

    source = "\n".join(new_texts)
    rows: list[dict[str, Any]] = []
    blockers: list[str] = []
    for boundary_id in sorted(expected_boundaries):
        binding = bindings_by_boundary.get(boundary_id)
        if binding is None:
            continue
        fire_text = str(binding.get("fire_source") or "").strip()
        count_text = str(binding.get("accepted_count_source") or "").strip()
        if all(value in source for value in (fire_text, count_text)):
            continue
        fire = _indexed_observation_name(fire_text)
        count = _indexed_observation_name(count_text)
        valid = _indexed_observation_left_side(
            str(binding.get("valid_source") or "")
        )
        ready = _indexed_observation_left_side(
            str(binding.get("ready_source") or "")
        )
        if fire is None or count is None or valid is None or ready is None:
            continue
        if len({fire[1], count[1], valid[1], ready[1]}) != 1:
            blockers.append(
                f"array observation for {boundary_id} uses different signal indexes"
            )
            continue
        rows.append(
            {
                "boundary_id": boundary_id,
                "index": fire[1],
                "fire_base": fire[0],
                "count_base": count[0],
                "valid_base": valid[0],
                "ready_base": ready[0],
            }
        )

    materialized: set[tuple[str, str]] = set()
    groups: dict[tuple[str, str, str, str], list[dict[str, Any]]] = {}
    for row in rows:
        key = (
            row["fire_base"],
            row["count_base"],
            row["valid_base"],
            row["ready_base"],
        )
        groups.setdefault(key, []).append(row)

    task_pattern = re.compile(
        r"\btask\s+(?:automatic\s+)?(?P<name>[A-Za-z_][A-Za-z0-9_$]*)"
        r"\s*\((?P<args>.*?)\)\s*;(?P<body>.*?)\bendtask\b",
        re.DOTALL,
    )
    tasks = list(task_pattern.finditer(source))
    for (fire_base, count_base, valid_base, ready_base), group_rows in groups.items():
        group_blockers: list[str] = []
        indexes = [int(row["index"]) for row in group_rows]
        if len(indexes) != len(set(indexes)):
            group_blockers.append(
                f"array observation {fire_base} reuses one index for multiple boundaries"
            )
        for base in (fire_base, count_base, valid_base, ready_base):
            declaration = re.search(
                rf"(?m)^\s*(?:wire|logic|reg|bit|integer|int|longint)\b"
                rf"[^;\n]*\b{re.escape(base)}\b[^;\n]*;",
                source,
            )
            if declaration is None:
                group_blockers.append(
                    f"array observation signal {base} has no declaration in the source edit"
                )
        fire_assignment = re.search(
            rf"\bassign\s+{re.escape(fire_base)}\s*=\s*(?:"
            rf"{re.escape(valid_base)}\s*&\s*{re.escape(ready_base)}|"
            rf"{re.escape(ready_base)}\s*&\s*{re.escape(valid_base)})\s*;",
            source,
        )
        if fire_assignment is None:
            group_blockers.append(
                f"array observation {fire_base} is not derived from its valid and ready signals"
            )

        matching_tasks: list[tuple[str, str]] = []
        for task in tasks:
            body = task.group("body")
            fire_indexes = set(
                re.findall(
                    rf"\b{re.escape(fire_base)}\s*\[\s*([A-Za-z_][A-Za-z0-9_$]*)\s*\]",
                    body,
                )
            )
            count_indexes = set(
                re.findall(
                    rf"\b{re.escape(count_base)}\s*\[\s*([A-Za-z_][A-Za-z0-9_$]*)\s*\]",
                    body,
                )
            )
            for index_name in sorted(fire_indexes & count_indexes):
                if re.search(
                    rf"\binput\s+(?:(?:integer|int|longint)\s+)?"
                    rf"\b{re.escape(index_name)}\b",
                    task.group("args"),
                ):
                    matching_tasks.append((task.group("name"), index_name))
        if len(matching_tasks) != 1:
            group_blockers.append(
                f"array observation {fire_base} requires one task that reads fire and count with the same dynamic index"
            )
        else:
            task_name, _ = matching_tasks[0]
            for row in group_rows:
                call_pattern = re.compile(
                    rf"\b{re.escape(task_name)}\s*\(\s*{row['index']}\s*,\s*"
                    rf'"{re.escape(row["boundary_id"])}"\s*\)\s*;'
                )
                if len(call_pattern.findall(source)) != 1:
                    group_blockers.append(
                        f"array observation for {row['boundary_id']} is not called exactly once with index {row['index']}"
                    )

        increments, guarded_increments = (
            _observation_counter_increment_matches_fire_guard(
                source, fire_base, count_base
            )
        )
        if not increments or len(increments) != len(guarded_increments):
            group_blockers.append(
                f"array observation {count_base} must increment only when the matching {fire_base} entry transfers"
            )

        if group_blockers:
            blockers.extend(group_blockers)
            continue
        for row in group_rows:
            materialized.add((str(row["boundary_id"]), "fire_source"))
            materialized.add(
                (str(row["boundary_id"]), "accepted_count_source")
            )

    return {"materialized": materialized, "blockers": blockers}


def _loop_counter_observation_binding_check(
    bindings_by_boundary: dict[str, dict[str, Any]],
    expected_boundaries: set[str],
    candidate_texts: list[str],
) -> dict[str, Any]:
    """Verify fixed boundary bindings that share one indexed counter loop."""

    source = "\n".join(candidate_texts)
    groups: dict[tuple[str, str], list[dict[str, Any]]] = {}
    dynamic_groups: dict[tuple[str, str], list[dict[str, Any]]] = {}
    blockers: list[str] = []
    materialized: set[tuple[str, str]] = set()
    for boundary_id in sorted(expected_boundaries):
        binding = bindings_by_boundary.get(boundary_id)
        if binding is None:
            continue
        count = _indexed_observation_name(
            str(binding.get("accepted_count_source") or "")
        )
        fire_text = str(binding.get("fire_source") or "").strip()
        if count is None or not fire_text:
            continue
        fire = _indexed_observation_name(fire_text)
        count_text = str(binding.get("accepted_count_source") or "").strip()
        if fire is not None and count_text not in source:
            # A single loop may update every boundary counter through a
            # dynamic index.  The fixed index from the plan is still useful
            # for binding the boundary, but it need not appear in the source.
            dynamic_groups.setdefault((fire[0], count[0]), []).append(
                {
                    "boundary_id": boundary_id,
                    "index": count[1],
                    "fire_index": fire[1],
                }
            )
            continue
        fire_assignment = re.search(
            rf"\bassign\s+(?P<base>[A-Za-z_][A-Za-z0-9_$]*)\s*"
            rf"\[\s*{count[1]}\s*\]\s*=\s*{re.escape(fire_text)}\s*;",
            source,
        )
        if fire_assignment is not None and count_text not in source:
            # The fire bit can be bound directly to a DUT expression while
            # the counter is updated through the same dynamic boundary loop.
            # Treat that fixed fire assignment as the row's array binding.
            dynamic_groups.setdefault(
                (fire_assignment.group("base"), count[0]), []
            ).append(
                {
                    "boundary_id": boundary_id,
                    "index": count[1],
                    "fire_index": count[1],
                }
            )
            continue
        if fire_assignment is None:
            continue
        groups.setdefault((fire_assignment.group("base"), count[0]), []).append(
            {"boundary_id": boundary_id, "index": count[1]}
        )

    for (fire_base, count_base), rows in groups.items():
        group_blockers: list[str] = []
        indexes = [int(row["index"]) for row in rows]
        if len(indexes) != len(set(indexes)):
            group_blockers.append(
                f"array observation {count_base} reuses one index for multiple boundaries"
            )
        for base in (fire_base, count_base):
            if re.search(
                rf"(?m)^\s*(?:wire|logic|reg|bit|integer|int|longint)\b"
                rf"[^;\n]*\b{re.escape(base)}\b[^;\n]*;",
                source,
            ) is None:
                group_blockers.append(
                    f"array observation signal {base} has no declaration in the candidate source"
                )

        increments, guarded_increments = (
            _observation_counter_increment_matches_fire_guard(
                source, fire_base, count_base
            )
        )
        if not increments or len(increments) != len(guarded_increments):
            group_blockers.append(
                f"array observation {count_base} must increment only when the matching {fire_base} entry transfers"
            )
        if group_blockers:
            blockers.extend(group_blockers)
            continue
        for row in rows:
            materialized.add(
                (str(row["boundary_id"]), "accepted_count_source")
            )

    # Some testbenches derive each fixed fire bit directly from DUT valid and
    # ready signals, then update all counters in one boundary-index loop.  In
    # that form there is no ``accepted_count[fixed_index]`` text to match, but
    # the dynamic counter update is still the actual binding for every row.
    for (fire_base, count_base), rows in dynamic_groups.items():
        group_blockers: list[str] = []
        indexes = [int(row["index"]) for row in rows]
        if len(indexes) != len(set(indexes)):
            group_blockers.append(
                f"loop observation {count_base} reuses one index for multiple boundaries"
            )
        for base in (fire_base, count_base):
            if re.search(
                rf"(?m)^\s*(?:wire|logic|reg|bit|integer|int|longint)\b"
                rf"[^;\n]*\b{re.escape(base)}\b[^;\n]*;",
                source,
            ) is None:
                group_blockers.append(
                    f"loop observation signal {base} has no declaration in the candidate source"
                )
        dynamic_access = re.search(
            rf"\b{re.escape(count_base)}\s*\[\s*[A-Za-z_][A-Za-z0-9_$]*\s*\]",
            source,
        )
        if dynamic_access is None:
            group_blockers.append(
                f"loop observation {count_base} has no dynamic indexed access"
            )
        increments, guarded_increments = (
            _observation_counter_increment_matches_fire_guard(
                source, fire_base, count_base
            )
        )
        if not increments or len(increments) != len(guarded_increments):
            group_blockers.append(
                f"loop observation {count_base} must increment only when the matching {fire_base} entry transfers"
            )
        if group_blockers:
            blockers.extend(group_blockers)
            continue
        for row in rows:
            materialized.add(
                (str(row["boundary_id"]), "accepted_count_source")
            )

    return {"materialized": materialized, "blockers": blockers}


def _diagnostic_signal_binding_check(
    bindings_by_boundary: dict[str, dict[str, Any]],
    expected_boundaries: set[str],
    candidate_texts: list[str],
) -> dict[str, Any]:
    """Check optional internal signal bindings without making them required."""

    source = "\n".join(candidate_texts)
    blockers: list[str] = []
    binding_count = 0
    direct_signal_count = 0
    for boundary_id in sorted(expected_boundaries):
        binding = bindings_by_boundary.get(boundary_id)
        if binding is None:
            continue
        rows = binding.get("diagnostic_sources", [])
        if rows is None:
            continue
        if not isinstance(rows, list):
            blockers.append(
                f"diagnostic_sources for {boundary_id} is not an array"
            )
            continue
        if len(rows) < MIN_ADAPTIVE_DIAGNOSTIC_SOURCES_PER_BOUNDARY:
            blockers.append(
                f"diagnostic_sources for {boundary_id} must contain at least "
                f"{MIN_ADAPTIVE_DIAGNOSTIC_SOURCES_PER_BOUNDARY} bounded internal signals"
            )
        seen_names: set[str] = set()
        bound_expression_count = 0
        direct_expression_count = 0
        for row in rows:
            if not isinstance(row, dict):
                blockers.append(
                    f"diagnostic_sources for {boundary_id} contains a non-object row"
                )
                continue
            name = str(row.get("name") or "").strip()
            role = str(row.get("role") or "").strip()
            expression = str(row.get("expression") or "").strip()
            unavailable_reason = str(row.get("unavailable_reason") or "").strip()
            if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_$]*", name):
                blockers.append(
                    f"diagnostic_sources for {boundary_id} has an invalid signal name"
                )
            if name in seen_names:
                blockers.append(
                    f"diagnostic_sources for {boundary_id} repeats {name}"
                )
            seen_names.add(name)
            if not _valid_diagnostic_role(role):
                blockers.append(
                    f"diagnostic_sources for {boundary_id} has an empty or invalid role label"
                )
            if not expression and not unavailable_reason:
                blockers.append(
                    f"diagnostic_sources for {boundary_id} must bind {name} or explain why it is unavailable"
                )
                continue
            if expression:
                binding_count += 1
                bound_expression_count += 1
                if expression.lower() in {"null", "none", "unknown", "unavailable"}:
                    blockers.append(
                        f"diagnostic_sources for {boundary_id} uses a placeholder expression for {name}"
                    )
                    continue
                if expression not in source:
                    blockers.append(
                        f"diagnostic_sources for {boundary_id} does not materialize {name}"
                    )
                if "dut." in expression.lower():
                    direct_signal_count += 1
                    direct_expression_count += 1
        if bound_expression_count < MIN_ADAPTIVE_DIAGNOSTIC_SOURCES_PER_BOUNDARY:
            blockers.append(
                f"diagnostic_sources for {boundary_id} must bind at least "
                f"{MIN_ADAPTIVE_DIAGNOSTIC_SOURCES_PER_BOUNDARY} real signals"
            )
        if direct_expression_count < 1:
            blockers.append(
                f"diagnostic_sources for {boundary_id} must include a direct DUT hierarchy signal"
            )
    return {
        "status": "pass" if not blockers else "blocked",
        "binding_count": binding_count,
        "direct_signal_count": direct_signal_count,
        "blockers": blockers,
    }


def _stage_internal_signal_binding_check(
    decision: dict[str, Any],
    authority: dict[str, Any] | None,
    candidate_texts: list[str],
) -> dict[str, Any]:
    """Require a materialized internal signal plan for every current stage."""

    requirements = _pipeline_stage_observation_requirements(authority)
    if not requirements:
        return {
            "status": "not_required",
            "stage_count": 0,
            "signal_count": 0,
            "blockers": [],
        }

    plan = decision.get("stage_internal_signal_plan")
    blockers: list[str] = []
    if not isinstance(plan, list):
        return {
            "status": "blocked",
            "stage_count": len(requirements),
            "signal_count": 0,
            "blockers": [
                "stage_internal_signal_plan must contain one row for every current pipeline stage"
            ],
        }

    by_stage: dict[str, dict[str, Any]] = {}
    for row in plan:
        if not isinstance(row, dict):
            blockers.append("stage_internal_signal_plan contains a non-object row")
            continue
        stage_id = str(row.get("stage_id") or "").strip()
        if not stage_id:
            blockers.append("stage_internal_signal_plan has a row without stage_id")
        elif stage_id in by_stage:
            blockers.append(f"stage_internal_signal_plan repeats stage {stage_id}")
        else:
            by_stage[stage_id] = row

    missing = sorted(set(requirements) - set(by_stage))
    extra = sorted(set(by_stage) - set(requirements))
    if missing:
        blockers.append(
            "stage_internal_signal_plan lacks stages: " + ", ".join(missing)
        )
    if extra:
        blockers.append(
            "stage_internal_signal_plan names stages absent from the current pipeline: "
            + ", ".join(extra)
        )

    source = "\n".join(candidate_texts)
    signal_count = 0
    for stage_id in sorted(set(requirements) & set(by_stage)):
        row = by_stage[stage_id]
        expected = requirements[stage_id]
        inputs = row.get("input_boundary_ids")
        outputs = row.get("output_boundary_ids")
        if not isinstance(inputs, list) or {
            str(value) for value in inputs if isinstance(value, str)
        } != set(expected["input_boundary_ids"]):
            blockers.append(
                f"stage_internal_signal_plan for {stage_id} does not list the current input boundaries"
            )
        if not isinstance(outputs, list) or {
            str(value) for value in outputs if isinstance(value, str)
        } != set(expected["output_boundary_ids"]):
            blockers.append(
                f"stage_internal_signal_plan for {stage_id} does not list the current output boundaries"
            )

        rows = row.get("diagnostic_sources")
        if not isinstance(rows, list) or not rows:
            blockers.append(
                f"stage_internal_signal_plan for {stage_id} must bind every useful internal signal visible in the stage"
            )
            rows = []
        seen_names: set[str] = set()
        direct_count = 0
        for source_row in rows:
            if not isinstance(source_row, dict):
                blockers.append(
                    f"stage_internal_signal_plan for {stage_id} contains a non-object signal row"
                )
                continue
            name = str(source_row.get("name") or "").strip()
            role = str(source_row.get("role") or "").strip()
            expression = str(source_row.get("expression") or "").strip()
            reason = str(source_row.get("unavailable_reason") or "").strip()
            signal_count += bool(expression)
            if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_$]*", name):
                blockers.append(
                    f"stage_internal_signal_plan for {stage_id} has an invalid signal name"
                )
            if name in seen_names:
                blockers.append(
                    f"stage_internal_signal_plan for {stage_id} repeats {name}"
                )
            seen_names.add(name)
            if not _valid_diagnostic_role(role):
                blockers.append(
                    f"stage_internal_signal_plan for {stage_id} has an empty or invalid signal role label"
                )
            if not expression and not reason:
                blockers.append(
                    f"stage_internal_signal_plan for {stage_id} must bind {name} or explain why it is unavailable"
                )
                continue
            if not expression:
                continue
            if expression.lower() in {"null", "none", "unknown", "unavailable"}:
                blockers.append(
                    f"stage_internal_signal_plan for {stage_id} uses a placeholder expression for {name}"
                )
                continue
            if expression not in source:
                blockers.append(
                    f"stage_internal_signal_plan for {stage_id} does not materialize {name}"
                )
            if not _stage_signal_record_is_materialized(source, stage_id, name):
                blockers.append(
                    f"stage_internal_signal_plan for {stage_id} does not emit {name} in a stage trace or stage snapshot"
                )
            if "dut." in expression.lower():
                direct_count += 1
        if direct_count < 1:
            blockers.append(
                f"stage_internal_signal_plan for {stage_id} must include a direct DUT hierarchy signal"
            )

        unavailable_roles = row.get("unavailable_roles", [])
        if unavailable_roles is None:
            unavailable_roles = []
        if not isinstance(unavailable_roles, list):
            blockers.append(
                f"stage_internal_signal_plan for {stage_id} has invalid unavailable_roles"
            )
            continue
        seen_unavailable: set[str] = set()
        for unavailable in unavailable_roles:
            if not isinstance(unavailable, dict):
                blockers.append(
                    f"stage_internal_signal_plan for {stage_id} has an invalid unavailable role row"
                )
                continue
            role = str(unavailable.get("role") or "").strip()
            reason = str(unavailable.get("unavailable_reason") or "").strip()
            if (
                not _valid_diagnostic_role(role)
                or role in seen_unavailable
                or not reason
            ):
                blockers.append(
                    f"stage_internal_signal_plan for {stage_id} has an invalid unavailable role declaration"
                )
            seen_unavailable.add(role)

    return {
        "status": "pass" if not blockers else "blocked",
        "stage_count": len(requirements),
        "signal_count": int(signal_count),
        "blockers": blockers,
    }


def _layer3_planned_scalar_expressions(decision: dict[str, Any]) -> set[str]:
    """Return unique real scalar expressions planned for the next board run."""

    expressions: set[str] = set()
    for plan_name in ("signal_binding_plan", "stage_internal_signal_plan"):
        plans = decision.get(plan_name, [])
        if not isinstance(plans, list):
            continue
        for plan in plans:
            if not isinstance(plan, dict):
                continue
            rows = plan.get("diagnostic_sources", [])
            if not isinstance(rows, list):
                continue
            for row in rows:
                if not isinstance(row, dict):
                    continue
                expression = str(row.get("expression") or "").strip()
                if expression and expression.lower() not in {
                    "null",
                    "none",
                    "unknown",
                    "unavailable",
                    "not_bound",
                }:
                    expressions.add(expression)
    return expressions


def _layer3_planned_signal_roles(decision: dict[str, Any]) -> dict[str, set[str]]:
    """Map each planned scalar expression to its declared diagnostic roles."""

    roles_by_expression: dict[str, set[str]] = {}
    for plan_name in ("signal_binding_plan", "stage_internal_signal_plan"):
        plans = decision.get(plan_name, [])
        if not isinstance(plans, list):
            continue
        for plan in plans:
            if not isinstance(plan, dict):
                continue
            rows = plan.get("diagnostic_sources", [])
            if not isinstance(rows, list):
                continue
            for row in rows:
                if not isinstance(row, dict):
                    continue
                expression = str(row.get("expression") or "").strip()
                role = str(row.get("role") or "").strip()
                if expression and role:
                    roles_by_expression.setdefault(expression, set()).add(role)
    return roles_by_expression


def validate_observation_plan_delta(
    decision: dict[str, Any],
    prior_observation_state: dict[str, Any],
) -> dict[str, Any]:
    """Require each observation turn to add useful, causal information.

    A new cadence, probe name, or duplicate copy of an old signal is not a
    deeper observation.  Compare only signal-plan metadata from the prior
    turn; signal values from the prior VCS epoch never enter this check or the
    hot-loop prompt.
    """

    current_roles = _layer3_planned_signal_roles(decision)
    current_expressions = set(current_roles)
    prior_decision = (
        prior_observation_state.get("decision", {})
        if isinstance(prior_observation_state, dict)
        else {}
    )
    prior_decision = prior_decision if isinstance(prior_decision, dict) else {}
    prior_roles = _layer3_planned_signal_roles(prior_decision)
    prior_expressions = set(prior_roles)
    new_expressions = current_expressions - prior_expressions

    delta = decision.get("observation_delta")
    blockers: list[str] = []
    if not isinstance(delta, dict):
        blockers.append(
            "observation_delta is required so the Agent must explain how the next run can distinguish the current candidate causes"
        )
        delta = {}

    missing_distinction = str(delta.get("missing_distinction") or "").strip()
    if not missing_distinction:
        blockers.append("observation_delta.missing_distinction is empty")

    candidate_root_causes = [
        str(value).strip()
        for value in delta.get("candidate_root_causes", [])
        if isinstance(value, str) and value.strip()
    ]
    if not candidate_root_causes:
        blockers.append(
            "observation_delta.candidate_root_causes must name the current cause or causes being tested"
        )
    elif len(candidate_root_causes) != len(set(candidate_root_causes)):
        blockers.append(
            "observation_delta.candidate_root_causes must contain distinct causes"
        )

    expected_patterns = [
        str(value).strip()
        for value in delta.get("expected_signal_patterns", [])
        if isinstance(value, str) and value.strip()
    ]
    if not expected_patterns:
        blockers.append(
            "observation_delta.expected_signal_patterns must define the signal pattern that supports or rejects the candidate cause"
        )
    elif len(expected_patterns) != len(set(expected_patterns)):
        blockers.append(
            "observation_delta.expected_signal_patterns must contain distinct outcomes"
        )

    declared_new = [
        str(value).strip()
        for value in delta.get("new_signal_expressions", [])
        if isinstance(value, str) and value.strip()
    ]
    declared_new_set = set(declared_new)
    if len(declared_new) != len(declared_new_set):
        blockers.append(
            "observation_delta.new_signal_expressions must not repeat a signal"
        )
    if not declared_new_set and not prior_expressions:
        blockers.append(
            "observation_delta.new_signal_expressions must name the real DUT signals used by the first observation plan"
        )
    if declared_new_set - new_expressions:
        blockers.append(
            "observation_delta.new_signal_expressions contains signals already present in the prior observation plan or absent from the current plan"
        )

    cause_checks = delta.get("candidate_cause_checks", [])
    if not isinstance(cause_checks, list) or not cause_checks:
        blockers.append(
            "observation_delta.candidate_cause_checks must map the new signals to the current cause analysis"
        )
        cause_checks = []
    checked_causes: set[str] = set()
    checked_signals: set[str] = set()
    for index, check in enumerate(cause_checks):
        if not isinstance(check, dict):
            blockers.append(
                f"observation_delta.candidate_cause_checks[{index}] is not an object"
            )
            continue
        cause = str(check.get("cause") or "").strip()
        expressions = {
            str(value).strip()
            for value in check.get("signal_expressions", [])
            if isinstance(value, str) and value.strip()
        }
        expected_pattern = str(check.get("expected_pattern") or "").strip()
        disambiguates = str(check.get("disambiguates") or "").strip()
        if not cause:
            blockers.append(
                f"observation_delta.candidate_cause_checks[{index}] has no cause"
            )
        if not expressions:
            blockers.append(
                f"observation_delta.candidate_cause_checks[{index}] must name the new signals used to test the cause"
            )
        if not expected_pattern:
            blockers.append(
                f"observation_delta.candidate_cause_checks[{index}] has no expected signal pattern"
            )
        if not disambiguates:
            blockers.append(
                f"observation_delta.candidate_cause_checks[{index}] has no explanation of what the signals distinguish"
            )
        if cause:
            checked_causes.add(cause)
        checked_signals.update(expressions)
        if expressions - new_expressions:
            blockers.append(
                f"observation_delta.candidate_cause_checks[{index}] uses a signal that is not new in this observation plan"
            )
    if candidate_root_causes and not set(candidate_root_causes).issubset(checked_causes):
        blockers.append(
            "every candidate_root_cause must have a candidate_cause_checks row"
        )
    if new_expressions and checked_signals != new_expressions:
        blockers.append(
            "every newly added DUT signal must be tied to a candidate cause check; do not pad the plan with unrelated signals"
        )

    new_roles: set[str] = set()
    for expression in declared_new_set:
        if not expression.lower().startswith("dut."):
            blockers.append(
                f"new observation signal is not a direct DUT hierarchy expression: {expression}"
            )
        new_roles.update(current_roles.get(expression, set()))
    if new_expressions and not new_roles:
        blockers.append(
            "new observation signals do not carry nonempty diagnostic role labels"
        )

    return {
        "status": "pass" if not blockers else "blocked",
        "prior_expression_count": len(prior_expressions),
        "current_expression_count": len(current_expressions),
        "new_expression_count": len(new_expressions),
        "new_signal_expressions": sorted(new_expressions),
        "declared_new_signal_expressions": sorted(declared_new_set),
        "new_roles": sorted(new_roles),
        "missing_distinction": missing_distinction,
        "candidate_root_causes": candidate_root_causes,
        "expected_signal_patterns": expected_patterns,
        "candidate_cause_checks": copy.deepcopy(cause_checks),
        "blockers": list(dict.fromkeys(blockers)),
    }


def _adaptive_observation_has_internal_sources(decision: dict[str, Any]) -> bool:
    """Require each planned boundary to carry real internal diagnostics.

    A saved observation transaction with only endpoint counters is not useful
    for the next board run and must not be replayed forever.  Keep this check
    small and structural; the full source/materialization check remains in
    ``complete_internal_signal_binding_plan``.
    """

    rows = decision.get("signal_binding_plan", [])
    if not isinstance(rows, list) or not rows:
        return False
    for row in rows:
        if not isinstance(row, dict):
            return False
        sources = row.get("diagnostic_sources")
        if not isinstance(sources, list):
            return False
        bound = [
            item
            for item in sources
            if isinstance(item, dict)
            and str(item.get("expression") or "").strip()
        ]
        if len(bound) < MIN_ADAPTIVE_DIAGNOSTIC_SOURCES_PER_BOUNDARY:
            return False
        if not any("dut." in str(item.get("expression") or "").lower() for item in bound):
            return False
    return True


def _adaptive_observation_has_causal_delta(decision: dict[str, Any]) -> bool:
    """Reject legacy observation transactions without a causal experiment."""

    delta = decision.get("observation_delta")
    if not isinstance(delta, dict):
        return False
    required = (
        "missing_distinction",
        "candidate_root_causes",
        "new_signal_expressions",
        "expected_signal_patterns",
        "candidate_cause_checks",
    )
    if any(key not in delta for key in required):
        return False
    if not str(delta.get("missing_distinction") or "").strip():
        return False
    if not isinstance(delta.get("candidate_root_causes"), list):
        return False
    if not isinstance(delta.get("new_signal_expressions"), list):
        return False
    if not isinstance(delta.get("expected_signal_patterns"), list):
        return False
    checks = delta.get("candidate_cause_checks")
    return isinstance(checks, list) and bool(checks)


def complete_internal_signal_binding_plan(
    decision: dict[str, Any],
    output: dict[str, Any],
    pipeline_observation_authority: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Validate a complete next-run internal boundary observation plan.

    A read-only observation edit can legitimately be the first point at which
    all internal boundaries are available to the Agent.  In that case the
    current run may only expose outer lifecycle facts.  Do not mistake that
    for a count-only diagnosis when the Agent has supplied and materialized a
    complete direct signal plan for the next real run.
    """

    coverage_plan = (
        decision.get("boundary_coverage_plan", {})
        if isinstance(decision.get("boundary_coverage_plan"), dict)
        else {}
    )
    expected_boundaries = {
        str(value)
        for value in coverage_plan.get("boundary_ids", [])
        if isinstance(value, str) and value
    }
    planned_fields = {
        str(value)
        for value in coverage_plan.get("required_fields", [])
        if isinstance(value, str) and value
    }
    bindings = (
        decision.get("signal_binding_plan", [])
        if isinstance(decision.get("signal_binding_plan"), list)
        else []
    )
    bindings_by_boundary: dict[str, dict[str, Any]] = {}
    blockers: list[str] = []
    for binding in bindings:
        if not isinstance(binding, dict):
            blockers.append("internal signal-binding plan contains a non-object row")
            continue
        boundary_id = str(binding.get("boundary_id") or "").strip()
        if not boundary_id:
            blockers.append("internal signal-binding plan has a row without boundary_id")
            continue
        if boundary_id in bindings_by_boundary:
            blockers.append(
                f"internal signal-binding plan has duplicate boundary_id: {boundary_id}"
            )
            continue
        bindings_by_boundary[boundary_id] = binding

    if not expected_boundaries:
        blockers.append("internal signal-binding plan has no boundary coverage")
    if set(ADAPTIVE_BOUNDARY_REQUIRED_FIELDS) - planned_fields:
        blockers.append(
            "internal signal-binding plan does not require the complete boundary observation fields"
        )
    missing_bindings = expected_boundaries - set(bindings_by_boundary)
    if missing_bindings:
        blockers.append(
            "internal signal-binding plan lacks bindings for "
            + ", ".join(sorted(missing_bindings))
        )

    candidate_texts = _observation_edit_candidate_texts(output)
    if not candidate_texts:
        blockers.append(
            "internal signal-binding plan has no materialized observation source edit"
        )
    source = "\n".join(candidate_texts)
    array_check = _array_observation_binding_check(
        bindings_by_boundary,
        expected_boundaries,
        candidate_texts,
    )
    loop_counter_check = _loop_counter_observation_binding_check(
        bindings_by_boundary,
        expected_boundaries,
        candidate_texts,
    )
    blockers.extend(array_check["blockers"])
    blockers.extend(loop_counter_check["blockers"])
    materialized = array_check["materialized"] | loop_counter_check["materialized"]
    diagnostic_check = _diagnostic_signal_binding_check(
        bindings_by_boundary,
        expected_boundaries,
        candidate_texts,
    )
    blockers.extend(diagnostic_check["blockers"])
    planned_scalar_expressions = _layer3_planned_scalar_expressions(decision)
    core_scalar_signal_count = len(planned_scalar_expressions)
    if core_scalar_signal_count < MIN_LAYER3_CORE_DIAGNOSTIC_SIGNALS:
        blockers.append(
            f"Layer-3 core observation plan must bind at least {MIN_LAYER3_CORE_DIAGNOSTIC_SIGNALS} "
            f"real scalar signals; received {core_scalar_signal_count}"
        )
    stage_check = _stage_internal_signal_binding_check(
        decision,
        pipeline_observation_authority,
        candidate_texts,
    )
    blockers.extend(stage_check["blockers"])
    if diagnostic_check["status"] == "pass":
        for boundary_id in sorted(expected_boundaries):
            binding = bindings_by_boundary.get(boundary_id, {})
            sources = binding.get("diagnostic_sources")
            bound = [
                item
                for item in sources
                if isinstance(item, dict)
                and str(item.get("expression") or "").strip()
            ] if isinstance(sources, list) else []
            if len(bound) < MIN_ADAPTIVE_DIAGNOSTIC_SOURCES_PER_BOUNDARY:
                blockers.append(
                    f"diagnostic_sources for {boundary_id} must contain at least "
                    f"{MIN_ADAPTIVE_DIAGNOSTIC_SOURCES_PER_BOUNDARY} real internal signals"
                )
            if not any(
                "dut." in str(item.get("expression") or "").lower()
                for item in bound
            ):
                blockers.append(
                    f"diagnostic_sources for {boundary_id} must include a direct DUT hierarchy signal"
                )

    uses_internal_dut_signal = False
    for boundary_id in sorted(expected_boundaries):
        binding = bindings_by_boundary.get(boundary_id)
        if binding is None:
            continue
        for field in ADAPTIVE_DIRECT_SIGNAL_BINDING_FIELDS:
            expression = str(binding.get(field) or "").strip()
            if not expression or expression.lower() in {
                "null",
                "none",
                "unavailable",
                "not_bound",
            }:
                blockers.append(
                    f"internal signal-binding plan for {boundary_id} lacks {field}"
                )
                continue
            if field != "accepted_count_source" and "dut." in expression:
                uses_internal_dut_signal = True
            if (
                expression not in source
                and (boundary_id, field) not in materialized
            ):
                blockers.append(
                    f"internal signal-binding plan for {boundary_id} does not materialize {field}"
                )
    if not uses_internal_dut_signal:
        blockers.append(
            "internal signal-binding plan does not bind any direct DUT hierarchy signal"
        )
    for field in (
        "first_accepted_payload_digest",
        "last_accepted_payload_digest",
    ):
        if field not in source:
            blockers.append(
                f"internal signal-binding plan does not retain {field} in the observation source"
            )

    blockers = list(dict.fromkeys(blockers))
    return {
        "status": "pass" if not blockers else "blocked",
        "boundary_count": len(expected_boundaries),
        "uses_internal_dut_signal": uses_internal_dut_signal,
        "core_scalar_signal_count": core_scalar_signal_count,
        "diagnostic_signal_bindings": diagnostic_check,
        "stage_internal_signal_bindings": stage_check,
        "blockers": blockers,
    }


def _mapping_at(value: Any, *keys: str) -> dict[str, Any]:
    current = value
    for key in keys:
        if not isinstance(current, dict):
            return {}
        current = current.get(key)
    return current if isinstance(current, dict) else {}


def _current_pipeline_boundary_observation(
    package: dict[str, Any],
) -> dict[str, Any]:
    """Find the current boundary summary without assuming a model or stage name."""

    feedback = (
        package.get("current_board_vcs_feedback", {})
        if isinstance(package.get("current_board_vcs_feedback"), dict)
        else {}
    )
    diagnosis = _mapping_at(feedback, "diagnosis", "value")
    failure_evidence = diagnosis.get("failure_evidence", {})
    if not isinstance(failure_evidence, dict):
        failure_evidence = {}
    candidates = (
        _mapping_at(
            failure_evidence,
            "board_to_lower_layer_contradiction_evidence",
            "evidence",
            "observation_context",
            "pipeline_boundary_observation",
        ),
        _mapping_at(
            failure_evidence,
            "observation_context",
            "pipeline_boundary_observation",
        ),
        failure_evidence.get("pipeline_boundary_observation", {}),
        diagnosis.get("pipeline_boundary_observation", {}),
        _mapping_at(feedback, "runner_report", "value", "pipeline_boundary_observation_summary"),
    )
    for candidate in candidates:
        if isinstance(candidate, dict) and (
            candidate.get("status")
            or candidate.get("required_boundary_count") is not None
            or candidate.get("incomplete_boundary_ids")
            or candidate.get("missing_boundary_ids")
        ):
            return candidate
    return {}


def _board_lower_layer_recheck_required(
    contradiction_evidence: dict[str, Any] | None,
    lower_layer_result: dict[str, Any] | None,
) -> bool:
    """Return whether current Layer-3 evidence warrants a lower-layer recheck.

    A normal Layer-3 observation gap must stay in the current repair loop.  A
    lower-layer recheck is justified only when the current board evidence
    explicitly proves a contradiction and the lower-layer result is not
    already passing.  This keeps Layer 2 closed for ordinary board debugging
    while preserving the backtrack route for a real cross-layer contradiction.
    """

    contradiction = (
        contradiction_evidence
        if isinstance(contradiction_evidence, dict)
        else {}
    )
    lower_layer = (
        lower_layer_result if isinstance(lower_layer_result, dict) else {}
    )
    return (
        contradiction.get("status") == "proven"
        and lower_layer.get("status") not in {"pass", "passed", "ready"}
    )


def adaptive_observation_routing_state(
    package: dict[str, Any],
) -> dict[str, Any]:
    """Route the next Agent decision from current boundary coverage and proof.

    This is deliberately based on the current run's evidence, not on a fixed
    model, layer count, or boundary name.  Incomplete coverage gets one
    all-boundary observation pass.  A complete trace plus a proven contradiction
    moves directly to a functional repair or an explicit capability blocker.
    """

    feedback = (
        package.get("current_board_vcs_feedback", {})
        if isinstance(package.get("current_board_vcs_feedback"), dict)
        else {}
    )
    diagnosis = _mapping_at(feedback, "diagnosis", "value")
    failure_evidence = diagnosis.get("failure_evidence", {})
    if not isinstance(failure_evidence, dict):
        failure_evidence = {}
    boundary = _current_pipeline_boundary_observation(package)
    retained_routing = package.get("adaptive_observation_routing", {})
    retained_routing = (
        retained_routing if isinstance(retained_routing, dict) else {}
    )
    # Prompt compaction keeps the current routing state, but its small board
    # feedback projection may omit the full boundary summary. Preserve the
    # deterministic routing decision in that case rather than silently
    # treating an incomplete waveform as unconstrained.
    if not boundary and retained_routing.get("status") in {
        "complete_boundary_coverage_required",
        "functional_repair_or_explicit_blocker_required",
    }:
        return copy.deepcopy(retained_routing)
    incomplete_ids: list[str] = []
    for field in ("incomplete_boundary_ids", "missing_boundary_ids"):
        values = boundary.get(field, [])
        if not isinstance(values, list):
            continue
        for value in values:
            text = str(value).strip()
            if text and text not in incomplete_ids:
                incomplete_ids.append(text)
    if not incomplete_ids:
        summaries = boundary.get("boundary_summaries", [])
        if isinstance(summaries, list):
            for row in summaries:
                if not isinstance(row, dict) or row.get("observation_complete") is True:
                    continue
                text = str(row.get("boundary_id") or "").strip()
                if text and text not in incomplete_ids:
                    incomplete_ids.append(text)

    contradiction = failure_evidence.get(
        "board_to_lower_layer_contradiction_evidence", {}
    )
    contradiction = contradiction if isinstance(contradiction, dict) else {}
    if incomplete_ids or boundary.get("status") == "incomplete":
        return {
            "schema_version": "spatialaccagent.adaptive_observation_routing.v1",
            "status": "complete_boundary_coverage_required",
            "incomplete_boundary_ids": incomplete_ids,
            "required_boundary_count": boundary.get("required_boundary_count"),
            "observed_boundary_count": boundary.get("observed_boundary_count"),
            "boundary_observation_status": boundary.get("status"),
            "proven_contradiction": contradiction.get("status") == "proven",
            "policy": {
                "one_next_run_covers_all_incomplete_boundaries": True,
                "required_fields": list(ADAPTIVE_BOUNDARY_REQUIRED_FIELDS),
                "single_point_observation_is_insufficient": True,
            },
        }
    if (
        boundary.get("status") == "complete"
        and contradiction.get("status") == "proven"
    ):
        return {
            "schema_version": "spatialaccagent.adaptive_observation_routing.v1",
            "status": "functional_repair_or_explicit_blocker_required",
            "incomplete_boundary_ids": [],
            "required_boundary_count": boundary.get("required_boundary_count"),
            "observed_boundary_count": boundary.get("observed_boundary_count"),
            "boundary_observation_status": boundary.get("status"),
            "proven_contradiction": True,
            "policy": {
                "deepen_simulation_observation_is_not_allowed": True,
                "functional_repair_or_precise_capability_blocker_required": True,
            },
        }
    return {
        "schema_version": "spatialaccagent.adaptive_observation_routing.v1",
        "status": "unconstrained",
        "incomplete_boundary_ids": incomplete_ids,
        "required_boundary_count": boundary.get("required_boundary_count"),
        "observed_boundary_count": boundary.get("observed_boundary_count"),
        "boundary_observation_status": boundary.get("status"),
        "proven_contradiction": contradiction.get("status") == "proven",
    }


def _board_observation_only_edit_paths(run_dir: Path) -> set[Path]:
    manifest_path = (
        run_dir / "generated" / "memory" / "dut_weight_binding_manifest.json"
    ).resolve()
    allowed = {manifest_path}
    manifest = read_json_if_exists(manifest_path)
    plan = (
        manifest.get("board_simulation_preflight_plan", {})
        if isinstance(manifest.get("board_simulation_preflight_plan"), dict)
        else {}
    )

    def add_path(value: Any) -> None:
        if isinstance(value, dict):
            for field in ("path", "local_path", "generated_source_path"):
                raw = str(value.get(field) or "").strip()
                if not raw:
                    continue
                path = Path(raw)
                allowed.add(
                    (path if path.is_absolute() else Path.cwd() / path).resolve()
                )

    testbench = plan.get("testbench", {})
    if isinstance(testbench, dict):
        add_path(testbench)
        add_path(testbench.get("source"))
    monitor_contract = plan.get("protocol_monitor_contract", {})
    if isinstance(monitor_contract, dict):
        add_path(monitor_contract)
        for monitor in monitor_contract.get("monitors", []):
            if not isinstance(monitor, dict):
                continue
            add_path(monitor)
            for source in monitor.get("source_files", []):
                add_path(source)
    return allowed


def enforce_board_observation_only_validation(
    validation: dict[str, Any],
    output: dict[str, Any],
    run_dir: Path,
) -> dict[str, Any]:
    """Record observation-edit notes without vetoing a Layer-3 Agent repair.

    The LLM decides whether a current signal epoch needs a hardware fix, a
    testbench observation change, or both.  The framework must execute that
    decision instead of reclassifying files and suppressing the repair.  File
    paths and replacement anchors are still checked later by the atomic write
    executor because those are mechanical execution requirements.
    """

    result = copy.deepcopy(validation)
    advisories: list[str] = []
    decision = (
        output.get("adaptive_observation_decision", {})
        if isinstance(output.get("adaptive_observation_decision"), dict)
        else {}
    )
    mode = str(decision.get("mode") or "")
    raw_edits = output.get("file_edits", [])
    edits = raw_edits if isinstance(raw_edits, list) else []
    if mode != "deepen_simulation_observation":
        advisories.append(
            "LLM selected a repair mode other than observation expansion"
        )
    if mode == "deepen_simulation_observation" and edits:
        advisories.append(
            "observation focus should use the runtime signal catalog instead of editing compiled sources"
        )

    allowed_paths = _board_observation_only_edit_paths(run_dir)
    manifest_path = (
        run_dir / "generated" / "memory" / "dut_weight_binding_manifest.json"
    ).resolve()
    observation_source_edited = False
    for index, edit in enumerate(edits):
        if not isinstance(edit, dict):
            advisories.append(
                f"file_edits[{index}] is not an executable edit object"
            )
            continue
        raw_path = Path(str(edit.get("path") or ""))
        target = (
            raw_path if raw_path.is_absolute() else Path.cwd() / raw_path
        ).resolve()
        if target not in allowed_paths:
            advisories.append(
                f"file_edits[{index}] is a functional source rather than an observation source"
            )
            continue
        if target != manifest_path:
            observation_source_edited = True
    if edits and not observation_source_edited:
        advisories.append("LLM did not edit a testbench or monitor source")

    # Observation-plan quality is useful feedback, but it is not an
    # execution gate for Layer 3.  The atomic edit executor below remains the
    # only gate for unsafe or non-executable file changes.
    contract_blockers = [
        str(value)
        for value in validation.get("blockers", [])
        if str(value).strip()
    ]
    result["contract_status"] = validation.get("status")
    result["contract_blockers"] = list(dict.fromkeys(contract_blockers))
    result["status"] = "pass"
    result["mode"] = mode or result.get("mode")
    result["blockers"] = []
    result["execution_advisories"] = list(
        dict.fromkeys([*advisories, *contract_blockers])
    )
    result["summary"] = (
        "recorded Layer-3 observation details and contract advisories; "
        "the LLM decision remains executable"
    )
    return result


def _is_internal_data_boundary_observation(observation: dict[str, Any]) -> bool:
    pointer = str(observation.get("evidence_pointer") or "").lower()
    # The exact-board runner also exposes the connected kernel's inner
    # boundary counters. These are the most useful facts when the outer output
    # count is zero, so they must satisfy the same signal-analysis rule as the
    # normalized boundary summaries.
    inner_boundary_path = any(
        marker in pointer
        for marker in (
            "/connected_kernel_inner_cone_observation/",
            "/connected_kernel_internal_pipeline_observation/",
        )
    )
    inner_boundary_field = any(
        marker in pointer
        for marker in (
            "/valid",
            "/ready",
            "/fire",
            "/accepted_count",
            "/accepted_record_count",
            "/first_accepted_record",
            "/last_accepted_record",
            "/first_accepted_payload",
            "/last_accepted_payload",
            "/first_core_ingress_fire_cycle",
            "/first_start_cycle",
            "accepted_count",
        )
    )
    if inner_boundary_path and inner_boundary_field:
        return True
    return (
        (
            (
                "/pipeline_boundary_observation/" in pointer
                and "/boundary_summaries/" in pointer
            )
            or "/runtime/boundaries/" in pointer
        )
        and any(
            marker in pointer
            for marker in (
                "/valid",
                "/ready",
                "/fire",
                "/accepted_count",
                "/accepted_record_count",
                "/first_accepted_record",
                "/last_accepted_record",
                "/first_accepted_payload",
                "/last_accepted_payload",
            )
        )
    )


def validate_adaptive_observation_decision(
    output: dict[str, Any],
    package: dict[str, Any],
    run_dir: Path,
    *,
    require_signal_analysis: bool = False,
    allow_existing_probe_replay: bool = False,
) -> dict[str, Any]:
    feedback = (
        package.get("current_board_vcs_feedback", {})
        if isinstance(package.get("current_board_vcs_feedback"), dict)
        else {}
    )
    routing = adaptive_observation_routing_state(package)
    base = {
        "schema_version": ADAPTIVE_OBSERVATION_VALIDATION_SCHEMA_VERSION,
        "adaptive_observation_routing": routing,
        "policy": {
            "functional_edit_requires_bound_direct_evidence": True,
            "insufficient_evidence_requires_observation_only_edit": True,
            "observation_pointers_must_resolve_exact_current_values": True,
            "observation_contract_findings_are_advisory_for_layer3": True,
            "mechanical_edit_checks_remain_execution_gates": True,
            "runtime_observation_selection_does_not_edit_compiled_sources": True,
        },
    }
    if feedback.get("status") != "ready":
        return {
            **base,
            "status": "not_required",
            "mode": None,
            "blockers": [],
            "summary": "no current real board VCS feedback requires an adaptive observation decision",
        }

    if allow_existing_probe_replay:
        decision = (
            output.get("adaptive_observation_decision", {})
            if isinstance(output.get("adaptive_observation_decision"), dict)
            else {}
        )
        replay = existing_adaptive_observation_probe_replay_ready(
            run_dir, decision
        )
        if replay.get("status") == "pass" and not output.get("file_edits"):
            return {
                **base,
                "status": "pass",
                "mode": str(decision.get("mode") or "") or None,
                "frontier_id": str(decision.get("frontier_id") or "") or None,
                "matched_evidence_sha256": [],
                "valid_field_observations": copy.deepcopy(
                    decision.get("field_observations", [])
                    if isinstance(decision.get("field_observations"), list)
                    else []
                ),
                "internal_boundary_field_observations": [],
                "internal_signal_binding_plan": {
                    "status": "legacy_compatibility",
                    "blockers": [],
                },
                "observation_plan_delta": {
                    "status": "legacy_compatibility",
                    "blockers": [],
                },
                "runtime_observation_selection": {
                    "status": "legacy_compatibility",
                    "selected_signal_count": 0,
                },
                "bound_observation_compile_repair": False,
                "decision_sha256": canonical_contract_sha256(decision),
                "decision": copy.deepcopy(decision),
                "blockers": [],
                "summary": (
                    "existing compiled observation source remains valid; "
                    "the next real-tool run may collect a fresh epoch"
                ),
            }

    blockers: list[str] = []
    decision = (
        output.get("adaptive_observation_decision", {})
        if isinstance(output.get("adaptive_observation_decision"), dict)
        else {}
    )
    mode = str(decision.get("mode") or "")
    file_edits = [
        row for row in output.get("file_edits", []) if isinstance(row, dict)
    ]
    prior_observation_state = (
        package.get("adaptive_observation_state", {})
        if isinstance(package.get("adaptive_observation_state"), dict)
        else {}
    )

    bound_observation_compile_repair, prior_observation_frontier = (
        _bound_observation_compile_repair(output, package, run_dir)
    )
    if (
        file_edits
        and mode != "deepen_simulation_observation"
        and (
            not require_signal_analysis
            or mode not in {
                "direct_executed_contradiction",
                "direct_tool_failure",
            }
        )
    ):
        return {
            **base,
            "status": "not_required",
            "mode": mode or None,
            "blockers": [],
            "summary": (
                "source repair is governed by atomic path/precondition checks and "
                "the unchanged real-tool rerun; auxiliary observation metadata is non-blocking"
            ),
        }
    frontier_id, _ = _current_board_feedback_frontier(package)
    frontier_ids = _current_board_feedback_frontier_ids(package)
    if bound_observation_compile_repair:
        frontier_ids.add(prior_observation_frontier)
    observation_lock = package.get("adaptive_observation_decision_lock")
    observation_lock = (
        observation_lock if isinstance(observation_lock, dict) else {}
    )
    if (
        decision.get("schema_version")
        != ADAPTIVE_OBSERVATION_DECISION_SCHEMA_VERSION
    ):
        blockers.append("adaptive_observation_decision schema_version is invalid")
    if mode not in {
        "direct_executed_contradiction",
        "direct_tool_failure",
        "deepen_simulation_observation",
    }:
        blockers.append("adaptive_observation_decision mode is invalid")
    if not frontier_id:
        blockers.append("current real-tool evidence has no earliest unproven frontier")
    elif observation_lock and str(observation_lock.get("frontier_id") or "") != frontier_id:
        blockers.append(
            "adaptive_observation_decision_lock is stale and does not match current SACG/CCTG evidence"
        )
    elif observation_lock and str(decision.get("frontier_id") or "") != str(
        observation_lock.get("frontier_id") or ""
    ):
        blockers.append(
            "adaptive_observation_decision frontier_id must exactly copy the current decision lock"
        )
    elif observation_lock and str(decision.get("mode") or "") not in {
        str(value)
        for value in observation_lock.get("allowed_modes", [])
        if str(value)
    }:
        blockers.append(
            "adaptive_observation_decision mode is not allowed by the current decision lock"
        )
    elif str(decision.get("frontier_id") or "") not in frontier_ids:
        blockers.append(
            "adaptive_observation_decision frontier_id does not match current SACG/CCTG evidence"
        )
    if (
        mode == "deepen_simulation_observation"
        and routing.get("status")
        == "functional_repair_or_explicit_blocker_required"
    ):
        blockers.append(
            "current boundary coverage is complete and the board-to-lower-layer contradiction is proven; submit the smallest functional repair or an explicit capability blocker instead of another observation"
        )
    # A previous observation may already have produced a complete, hash-bound
    # event.  Treat that probe as the replay baseline even when a restarted
    # Agent proposes a different probe identifier; the source-bound probe is
    # the durable executable contract and does not need another edit.
    if (
        mode == "deepen_simulation_observation"
        and prior_observation_state.get("status") == "pass"
        and isinstance(prior_observation_state.get("decision"), dict)
        and routing.get("status") != "complete_boundary_coverage_required"
    ):
        prior_decision = prior_observation_state["decision"]
        if (
            str(prior_decision.get("frontier_id") or "") in frontier_ids
            and prior_observation_state.get("compiled_probe_sources_bound") is True
            and prior_observation_state.get("matched_event_fields")
        ):
            decision = copy.deepcopy(prior_decision)
            mode = str(decision.get("mode") or mode)
            output = {**output, "adaptive_observation_decision": decision}
    # A prior probe is context only.  Requiring it to pass before consuming a
    # new current-run diagnosis caused the repair loop to revisit observation
    # bookkeeping instead of fixing the hardware failure.

    evidence_refs = [
        str(value)
        for value in decision.get("evidence_refs", [])
        if isinstance(value, str) and value
    ]
    bound_hashes = _current_board_feedback_hashes(package)
    matched_hashes = sorted(
        digest
        for digest in bound_hashes
        if any(digest in reference for reference in evidence_refs)
    )
    observations = (
        decision.get("field_observations", [])
        if isinstance(decision.get("field_observations"), list)
        else []
    )
    valid_observations: list[dict[str, Any]] = []
    observation_blockers: list[str] = []
    for index, observation in enumerate(observations):
        if not isinstance(observation, dict):
            observation_blockers.append(
                f"adaptive_observation_decision field_observations[{index}] is not an object"
            )
            continue
        pointer = str(observation.get("evidence_pointer") or "")
        resolved_pointer = _verification_capability_package_pointer(pointer)
        if not resolved_pointer.startswith("/current_board_vcs_feedback/"):
            observation_blockers.append(
                f"adaptive_observation_decision field_observations[{index}] pointer is outside current board feedback"
            )
            continue
        found, actual = _json_pointer_value(package, resolved_pointer)
        if not found or isinstance(actual, (dict, list)):
            observation_blockers.append(
                f"adaptive_observation_decision field_observations[{index}] pointer does not resolve to a scalar"
            )
            continue
        observed = observation.get("observed_value")
        if canonical_contract_sha256({"value": actual}) != canonical_contract_sha256(
            {"value": observed}
        ):
            observation_blockers.append(
                f"adaptive_observation_decision field_observations[{index}] value does not match current evidence"
            )
            continue
        if not str(observation.get("interpretation") or "").strip():
            observation_blockers.append(
                f"adaptive_observation_decision field_observations[{index}] interpretation is empty"
            )
            continue
        valid_observations.append(copy.deepcopy(observation))

    roles = {
        str(row.get("semantic_role") or "") for row in valid_observations
    }
    internal_boundary_observations = [
        row
        for row in valid_observations
        if _is_internal_data_boundary_observation(row)
    ]
    runtime_selection = (
        runtime_observation_selection(run_dir, decision, persist=False)
        if mode == "deepen_simulation_observation" and not file_edits
        else {
            "status": "not_applicable",
            "selected_signal_count": 0,
            "unknown_signal_expressions": [],
        }
    )
    internal_signal_binding_plan = (
        complete_internal_signal_binding_plan(
            decision,
            output,
            _current_pipeline_boundary_observation_authority(package),
        )
        if mode == "deepen_simulation_observation" and file_edits
        else {
            "status": "not_applicable",
            "boundary_count": 0,
            "uses_internal_dut_signal": False,
            "blockers": [],
        }
    )
    observation_plan_delta = (
        validate_observation_plan_delta(decision, prior_observation_state)
        if mode == "deepen_simulation_observation" and file_edits
        else {
            "status": (
                "pass"
                if mode == "deepen_simulation_observation"
                and runtime_selection.get("selected_signal_count", 0) > 0
                else "not_applicable"
            ),
            "prior_expression_count": 0,
            "current_expression_count": runtime_selection.get(
                "selected_signal_count", 0
            ),
            "new_expression_count": runtime_selection.get(
                "selected_signal_count", 0
            ),
            "new_signal_expressions": [
                row.get("expression")
                for row in runtime_selection.get("selected_signals", [])
                if isinstance(row, dict) and row.get("expression")
            ],
            "declared_new_signal_expressions": copy.deepcopy(
                decision.get("observation_delta", {}).get(
                    "new_signal_expressions", []
                )
                if isinstance(decision.get("observation_delta"), dict)
                else []
            ),
            "new_roles": [],
            "missing_distinction": str(
                decision.get("observation_delta", {}).get(
                    "missing_distinction", ""
                )
                if isinstance(decision.get("observation_delta"), dict)
                else ""
            ),
            "candidate_root_causes": copy.deepcopy(
                decision.get("observation_delta", {}).get(
                    "candidate_root_causes", []
                )
                if isinstance(decision.get("observation_delta"), dict)
                else []
            ),
            "expected_signal_patterns": copy.deepcopy(
                decision.get("observation_delta", {}).get(
                    "expected_signal_patterns", []
                )
                if isinstance(decision.get("observation_delta"), dict)
                else []
            ),
            "candidate_cause_checks": copy.deepcopy(
                decision.get("observation_delta", {}).get(
                    "candidate_cause_checks", []
                )
                if isinstance(decision.get("observation_delta"), dict)
                else []
            ),
            "blockers": [],
        }
    )
    if observation_plan_delta.get("status") != "not_applicable":
        blockers.extend(observation_plan_delta.get("blockers", []))
    if (
        require_signal_analysis
        and not internal_boundary_observations
        and not bound_observation_compile_repair
        and internal_signal_binding_plan.get("status") != "pass"
    ):
        blockers.append(
            "signal analysis requires at least one exact internal data-boundary signal fact; total input/output counts alone are insufficient"
        )
    fresh_replay_refs_current_feedback = any(
        _verification_capability_package_pointer(reference).startswith(
            ("current_board_vcs_feedback", "/current_board_vcs_feedback/")
        )
        for reference in evidence_refs
    )
    if not valid_observations:
        blockers.extend(observation_blockers)
    if not evidence_refs or (
        not matched_hashes
        and not (
            valid_observations
            and fresh_replay_refs_current_feedback
        )
    ):
        blockers.append(
            "adaptive_observation_decision evidence_refs do not bind the current runner, diagnosis, or causal slice"
        )
    if mode == "direct_tool_failure":
        current_diagnostic = "axi_protocol_violation" in json.dumps(
            feedback, ensure_ascii=False
        ).lower()
        if (
            not valid_observations
            or not roles.intersection({"error", "contract"})
        ) and not current_diagnostic:
            blockers.append(
                "direct_tool_failure requires an exact current error or contract observation"
            )
    elif mode == "direct_executed_contradiction":
        if len(valid_observations) < 2 or len(roles) < 2:
            blockers.append(
                "direct_executed_contradiction requires at least two differently classified current observations"
            )
        if not roles.intersection({"control", "handshake", "state", "error"}):
            blockers.append(
                "direct_executed_contradiction lacks control, handshake, state, or error evidence"
            )
        if not roles.intersection({"payload", "counter", "contract", "state"}):
            blockers.append(
                "direct_executed_contradiction lacks payload, counter, contract, or state correlation"
            )
    probe_plan = (
        decision.get("probe_plan", {})
        if isinstance(decision.get("probe_plan"), dict)
        else {}
    )
    add_probe_ids = [
        str(value)
        for value in probe_plan.get("add_or_update_probe_ids", [])
        if isinstance(value, str) and value
    ]
    required_fields = [
        str(value)
        for value in probe_plan.get("required_event_fields", [])
        if isinstance(value, str) and value
    ]
    if mode == "deepen_simulation_observation":
        coverage_plan = (
            decision.get("boundary_coverage_plan", {})
            if isinstance(decision.get("boundary_coverage_plan"), dict)
            else {}
        )
        if (
            routing.get("status") == "complete_boundary_coverage_required"
            and file_edits
        ):
            expected_boundaries = {
                str(value)
                for value in routing.get("incomplete_boundary_ids", [])
                if str(value)
            }
            planned_boundaries = {
                str(value)
                for value in coverage_plan.get("boundary_ids", [])
                if isinstance(value, str) and value
            }
            planned_fields = {
                str(value)
                for value in coverage_plan.get("required_fields", [])
                if isinstance(value, str) and value
            }
            if not coverage_plan:
                blockers.append(
                    "incomplete current boundary coverage requires boundary_coverage_plan"
                )
            if expected_boundaries - planned_boundaries:
                blockers.append(
                    "boundary_coverage_plan must include every current incomplete boundary"
                )
            if set(ADAPTIVE_BOUNDARY_REQUIRED_FIELDS) - planned_fields:
                blockers.append(
                    "boundary_coverage_plan.required_fields must include valid, ready, fire, accepted_count, first_accepted_payload_digest, and last_accepted_payload_digest"
                )
            binding_rows = (
                decision.get("signal_binding_plan", [])
                if isinstance(decision.get("signal_binding_plan"), list)
                else []
            )
            bindings_by_boundary: dict[str, dict[str, Any]] = {}
            for binding in binding_rows:
                if not isinstance(binding, dict):
                    continue
                boundary_id = str(binding.get("boundary_id") or "").strip()
                if boundary_id and boundary_id not in bindings_by_boundary:
                    bindings_by_boundary[boundary_id] = binding
            if expected_boundaries - set(bindings_by_boundary):
                blockers.append(
                    "complete boundary observation requires a direct signal_binding_plan for every incomplete boundary"
                )
            new_texts = _observation_edit_candidate_texts(output)
            array_binding_check = _array_observation_binding_check(
                bindings_by_boundary,
                expected_boundaries,
                new_texts,
            )
            blockers.extend(array_binding_check["blockers"])
            loop_counter_check = _loop_counter_observation_binding_check(
                bindings_by_boundary,
                expected_boundaries,
                new_texts,
            )
            blockers.extend(loop_counter_check["blockers"])
            materialized_array_bindings = (
                array_binding_check["materialized"]
                | loop_counter_check["materialized"]
            )
            for boundary_id in sorted(expected_boundaries):
                binding = bindings_by_boundary.get(boundary_id)
                if binding is None:
                    continue
                for field in ADAPTIVE_DIRECT_SIGNAL_BINDING_FIELDS:
                    expression = str(binding.get(field) or "").strip()
                    if not expression or expression.lower() in {
                        "null",
                        "none",
                        "unavailable",
                        "not_bound",
                    }:
                        blockers.append(
                            f"signal_binding_plan for {boundary_id} lacks a direct {field}"
                        )
                        continue
                    if (
                        not any(expression in text for text in new_texts)
                        and (boundary_id, field) not in materialized_array_bindings
                    ):
                        blockers.append(
                            f"signal_binding_plan for {boundary_id} does not use {field} in the observation source edit"
                        )
        if not valid_observations:
            blockers.append(
                "observation deepening requires at least one exact current clue"
            )
        if (
            not file_edits
            and runtime_selection.get("selected_signal_count", 0) <= 0
        ):
            blockers.append(
                "runtime observation deepening selected no compiled signal"
            )
        if not add_probe_ids or len(add_probe_ids) != len(set(add_probe_ids)):
            blockers.append(
                "observation deepening requires unique add_or_update_probe_ids"
            )
        if not required_fields or len(required_fields) != len(set(required_fields)):
            blockers.append(
                "observation deepening requires unique next-run required_event_fields"
            )
        for field in ("target_boundary", "trigger_condition", "bounded_window"):
            if not str(probe_plan.get(field) or "").strip():
                blockers.append(f"observation deepening probe_plan.{field} is empty")
        trigger_condition = str(probe_plan.get("trigger_condition") or "").strip().lower()
        if trigger_condition not in {"always", "unconditional"}:
            blockers.append(
                "Layer-3 observation deepening must use unconditional probes; set probe_plan.trigger_condition to 'always'"
            )
        allowed_paths = _board_observation_only_edit_paths(run_dir)
        edited_paths: set[Path] = set()
        for index, edit in enumerate(output.get("file_edits", [])):
            if not isinstance(edit, dict):
                continue
            raw_path = Path(str(edit.get("path") or ""))
            target = (
                raw_path if raw_path.is_absolute() else Path.cwd() / raw_path
            ).resolve()
            edited_paths.add(target)
            if target not in allowed_paths:
                blockers.append(
                    f"observation deepening file_edits[{index}] is not a declared testbench, monitor, or manifest path"
                )
        manifest_path = (
            run_dir / "generated" / "memory" / "dut_weight_binding_manifest.json"
        ).resolve()
        if not (edited_paths - {manifest_path}):
            # Existing testbench observation code is enough for the next
            # current board run.  Do not inspect old probe state or require a
            # separate replay contract before collecting new signals.
            pass
    elif add_probe_ids or required_fields:
        blockers.append(
            "direct repair must leave add_or_update_probe_ids and required_event_fields empty"
        )

    if not str(decision.get("rationale") or "").strip():
        blockers.append("adaptive_observation_decision rationale is empty")
    validated_decision = copy.deepcopy(decision)
    if not blockers:
        validated_decision["field_observations"] = copy.deepcopy(
            valid_observations
        )
    return {
        **base,
        "status": "pass" if not blockers else "blocked",
        "mode": mode or None,
        "frontier_id": frontier_id or None,
        "adaptive_observation_routing": routing,
        "matched_evidence_sha256": matched_hashes,
        "valid_field_observations": valid_observations,
        "internal_boundary_field_observations": internal_boundary_observations,
        "internal_signal_binding_plan": internal_signal_binding_plan,
        "observation_plan_delta": observation_plan_delta,
        "runtime_observation_selection": runtime_selection,
        "bound_observation_compile_repair": bound_observation_compile_repair,
        "decision_sha256": (
            canonical_contract_sha256(validated_decision)
            if validated_decision
            else None
        ),
        "decision": validated_decision,
        "blockers": list(dict.fromkeys(blockers)),
        "summary": (
            "adaptive observation decision is bound to current real-tool evidence"
            if not blockers
            else "adaptive observation decision was rejected before file write and VCS"
        ),
    }


def adaptive_observation_state_path(run_dir: Path) -> Path:
    return run_dir / "verification" / "adaptive_observation" / "current.json"


def existing_adaptive_observation_probe_replay_ready(
    run_dir: Path,
    decision: dict[str, Any],
) -> dict[str, Any]:
    """Compatibility check for source probes created before runtime selection.

    New observation rounds use ``current_selection.json``.  This reader exists
    only so an interrupted legacy round can finish once without restoring the
    retired hash/certificate controller.
    """

    state = read_json_if_exists(adaptive_observation_state_path(run_dir))
    blockers: list[str] = []
    if state.get("schema_version") != ADAPTIVE_OBSERVATION_STATE_SCHEMA_VERSION:
        blockers.append("adaptive observation state is missing")
    if state.get("decision_sha256") != canonical_contract_sha256(decision):
        blockers.append("adaptive observation decision does not match the saved probe")
    for row in state.get("board_source_edits", []):
        if not isinstance(row, dict):
            continue
        path = Path(str(row.get("path") or ""))
        expected = str(row.get("after_sha256") or "")
        if not path.is_file() or not expected or sha256_file(path) != expected:
            blockers.append(
                "saved adaptive observation board-source edit is missing or changed"
            )
    return {
        "status": "pass" if not blockers else "blocked",
        "blockers": list(dict.fromkeys(blockers)),
        "state": state,
    }


def begin_existing_adaptive_observation_probe_replay(
    run_dir: Path,
    validation: dict[str, Any],
) -> dict[str, Any]:
    """Mark one compatible legacy probe for a fresh real-tool evidence run."""

    decision = (
        validation.get("decision", {})
        if isinstance(validation.get("decision"), dict)
        else {}
    )
    readiness = existing_adaptive_observation_probe_replay_ready(
        run_dir, decision
    )
    if validation.get("status") != "pass" or readiness.get("status") != "pass":
        return {
            "schema_version": ADAPTIVE_OBSERVATION_STATE_SCHEMA_VERSION,
            "status": "blocked",
            "blockers": readiness.get("blockers", []),
        }
    state = copy.deepcopy(readiness["state"])
    state.update(
        {
            "status": "pending_real_tool_evidence",
            "replay_count": int(state.get("replay_count") or 0) + 1,
            "replay_started_at_unix_sec": time.time(),
        }
    )
    path = adaptive_observation_state_path(run_dir)
    write_json(path, state)
    return {**state, "path": str(path)}


def current_fresh_exact_source_provenance_replay_feedback(
    out_dir: Path,
    manifest_path: Path,
) -> dict[str, Any]:
    """Read the bounded result of the retired unchanged-source replay action."""

    del manifest_path
    path = Path(out_dir) / "fresh_exact_source_provenance_replay.json"
    record = read_json_if_exists(path)
    if not record:
        return {
            "schema_version": (
                "spatialaccagent.current_fresh_exact_source_provenance_replay.v1"
            ),
            "status": "not_run",
            "summary": "no unchanged-source replay result is available",
        }
    probe = (
        record.get("real_tool_probe", {})
        if isinstance(record.get("real_tool_probe"), dict)
        else {}
    )
    return {
        "schema_version": (
            "spatialaccagent.current_fresh_exact_source_provenance_replay.v1"
        ),
        "status": "ready",
        "replay_status": record.get("status"),
        "summary": probe.get("summary") or record.get("summary"),
        "execution_generation_sha256": record.get(
            "execution_generation_sha256"
        ),
        "decision": copy.deepcopy(record.get("decision", {})),
        "path": str(path),
        "sha256": sha256_file(path),
    }


def _adaptive_default_progress_log_paths(run_dir: Path) -> list[Path]:
    board_dir = run_dir / "verification" / "board_simulation"
    return [
        (board_dir / "reports" / "progress_event_log.jsonl").resolve(),
        (board_dir / "reports" / "boundary_trace.jsonl").resolve(),
        (board_dir / "boundary_trace.jsonl").resolve(),
        (
            board_dir
            / "checkpoint"
            / "equivalence"
            / "restored_outputs"
            / "reports"
            / "progress_event_log.jsonl"
        ).resolve(),
    ]


def _adaptive_progress_log_identity(path: Path) -> dict[str, Any]:
    present = path.is_file()
    return {
        "path": str(path),
        "present": present,
        "byte_count": path.stat().st_size if present else None,
        "sha256": sha256_file(path) if present else None,
        "mtime_ns": path.stat().st_mtime_ns if present else None,
    }


def persist_adaptive_observation_request(
    run_dir: Path,
    validation: dict[str, Any],
    patch_application: dict[str, Any],
) -> dict[str, Any]:
    if (
        validation.get("status") != "pass"
        or validation.get("mode") != "deepen_simulation_observation"
        or patch_application.get("status") != "pass"
    ):
        return {
            "schema_version": ADAPTIVE_OBSERVATION_STATE_SCHEMA_VERSION,
            "status": "not_required",
            "summary": "this repair did not create a new observation-only evidence request",
        }
    decision = (
        validation.get("decision", {})
        if isinstance(validation.get("decision"), dict)
        else {}
    )
    probe_plan = (
        decision.get("probe_plan", {})
        if isinstance(decision.get("probe_plan"), dict)
        else {}
    )
    board_root = (run_dir / "generated" / "board_integration").resolve()
    board_source_edits = [
        copy.deepcopy(row)
        for row in patch_application.get("files", [])
        if isinstance(row, dict)
        and Path(str(row.get("path") or "")).resolve().is_relative_to(board_root)
    ]
    created_at = time.time()
    created_at_ns = time.time_ns()
    state = {
        "schema_version": ADAPTIVE_OBSERVATION_STATE_SCHEMA_VERSION,
        "status": "pending_real_tool_evidence",
        "frontier_id": validation.get("frontier_id"),
        "decision_sha256": validation.get("decision_sha256"),
        "decision": copy.deepcopy(decision),
        "required_event_fields": copy.deepcopy(
            probe_plan.get("required_event_fields", [])
        ),
        "event_match": copy.deepcopy(probe_plan.get("event_match", {})),
        "probe_ids": copy.deepcopy(
            probe_plan.get("add_or_update_probe_ids", [])
        ),
        "board_source_edits": board_source_edits,
        "created_at_unix_sec": created_at,
        "created_at_unix_ns": created_at_ns,
        "pre_request_progress_logs": [
            _adaptive_progress_log_identity(path)
            for path in _adaptive_default_progress_log_paths(run_dir)
        ],
        "source_patch_application": {
            "path": patch_application.get("path"),
            "sha256": (
                sha256_file(Path(str(patch_application.get("path"))))
                if patch_application.get("path")
                and Path(str(patch_application.get("path"))).is_file()
                else None
            ),
        },
        "policy": {
            "fresh_post_edit_real_tool_evidence_required": True,
            "all_required_fields_must_be_present_in_current_bound_events": True,
            "compiled_board_sources_must_bind_the_probe_edit": True,
            "missing_probe_evidence_forbids_functional_repair": True,
        },
    }
    path = adaptive_observation_state_path(run_dir)
    write_json(path, state)
    history_path = path.parent / "history" / f"{state['decision_sha256']}.json"
    write_json(history_path, state)
    return {**state, "path": str(path), "history_path": str(history_path)}


def persist_runtime_adaptive_observation_request(
    run_dir: Path,
    validation: dict[str, Any],
) -> dict[str, Any]:
    """Persist one runtime-only observation request for the next restore.

    This state deliberately has no board-source edit binding. The broad probe
    set is already part of the compiled model; only the selected catalog rows
    change between consecutive restored runs.
    """

    if (
        validation.get("status") != "pass"
        or validation.get("mode") != "deepen_simulation_observation"
        or not isinstance(validation.get("decision"), dict)
    ):
        return {
            "schema_version": ADAPTIVE_OBSERVATION_STATE_SCHEMA_VERSION,
            "status": "not_required",
            "summary": "this decision did not request runtime observation",
        }
    decision = copy.deepcopy(validation["decision"])
    selection = runtime_observation_selection(run_dir, decision, persist=True)
    created_at = time.time()
    state = {
        "schema_version": ADAPTIVE_OBSERVATION_STATE_SCHEMA_VERSION,
        "status": "pending_real_tool_evidence",
        "runtime_only": True,
        "frontier_id": validation.get("frontier_id"),
        "decision_sha256": validation.get("decision_sha256"),
        "decision": decision,
        "runtime_selection": selection,
        "board_source_edits": [],
        "compiled_probe_sources_bound": True,
        "created_at_unix_sec": created_at,
        "created_at_unix_ns": time.time_ns(),
        "policy": {
            "fresh_restored_signal_epoch_required": True,
            "compiled_source_edit_required": False,
            "same_verified_snapshot_must_be_reused": True,
            "old_signal_values_are_not_evidence": True,
        },
    }
    path = adaptive_observation_state_path(run_dir)
    write_json(path, state)
    history_path = path.parent / "history" / f"{state['decision_sha256']}.json"
    write_json(history_path, state)
    return {**state, "path": str(path), "history_path": str(history_path)}


def runtime_only_observation_output(
    output: dict[str, Any],
) -> dict[str, Any]:
    """Discard obsolete source edits from an observation-only decision.

    A broad observation model is compiled once.  If a prior prompt or an old
    Agent habit still returns a testbench/monitor edit while it is explicitly
    asking to deepen observation, the source edit is neither needed nor
    allowed: selecting compiled signals is the whole action.  Functional RTL
    edits are deliberately left untouched because they create a new model and
    therefore require one new snapshot.
    """

    decision = output.get("adaptive_observation_decision", {})
    decision = decision if isinstance(decision, dict) else {}
    if str(decision.get("mode") or "") != "deepen_simulation_observation":
        return output

    functional_edits: list[dict[str, Any]] = []
    for edit in output.get("file_edits", []):
        if not isinstance(edit, dict):
            continue
        name = Path(str(edit.get("path") or "")).name.lower()
        if "tb" in name or "testbench" in name or "monitor" in name:
            continue
        functional_edits.append(copy.deepcopy(edit))
    if len(functional_edits) == len(
        [edit for edit in output.get("file_edits", []) if isinstance(edit, dict)]
    ):
        return output
    normalized = copy.deepcopy(output)
    normalized["file_edits"] = functional_edits
    normalized.setdefault("execution_advisories", []).append(
        "observation-only source edits were replaced by runtime compiled-signal selection"
    )
    return normalized


def _event_field_value(event: Any, field: str) -> tuple[bool, Any]:
    if field.startswith("/"):
        return _json_pointer_value(event, field)
    current = event
    for token in field.split("."):
        if not token or not isinstance(current, dict) or token not in current:
            return False, None
        current = current[token]
    return True, current


def _adaptive_event_field_value(event: Any, field: str) -> tuple[bool, Any]:
    """Read fields from either a legacy event or a boundary trace payload."""

    found, value = _event_field_value(event, field)
    if found:
        return True, value
    if isinstance(event, dict) and isinstance(event.get("observed_value"), dict):
        return _event_field_value(event["observed_value"], field)
    return False, None


def _adaptive_boundary_key(value: Any) -> str:
    """Normalize equivalent boundary spellings used by plans and traces."""

    text = str(value or "").strip().lower()
    if text.startswith("boundary."):
        text = text[len("boundary.") :]
    return re.sub(r"[^a-z0-9]+", "_", text).strip("_")


def _adaptive_boundary_coverage_plan(
    state: dict[str, Any],
) -> tuple[list[str], list[str]]:
    decision = state.get("decision")
    if not isinstance(decision, dict):
        return [], []
    coverage = decision.get("boundary_coverage_plan")
    if not isinstance(coverage, dict):
        return [], []
    boundary_ids = [
        str(value)
        for value in coverage.get("boundary_ids", [])
        if isinstance(value, str) and value
    ]
    required_fields = [
        str(value)
        for value in coverage.get("required_fields", [])
        if isinstance(value, str) and value
    ]
    return boundary_ids, required_fields


def _adaptive_progress_log_candidates(
    run_dir: Path,
    feedback: dict[str, Any],
) -> list[Path]:
    board_dir = run_dir / "verification" / "board_simulation"
    candidates = set(_adaptive_default_progress_log_paths(run_dir))
    candidates.update(
        {
            (board_dir / "reports" / "boundary_trace.jsonl").resolve(),
            (board_dir / "boundary_trace.jsonl").resolve(),
        }
    )

    def visit(value: Any) -> None:
        if isinstance(value, dict):
            for child in value.values():
                visit(child)
        elif isinstance(value, list):
            for child in value:
                visit(child)
        elif isinstance(value, str) and (
            value.endswith("progress_event_log.jsonl")
            or value.endswith("boundary_trace.jsonl")
        ):
            path = Path(value)
            candidates.add(
                (path if path.is_absolute() else run_dir / path).resolve()
            )

    visit(feedback)
    return sorted(
        (path for path in candidates if path.is_file()),
        key=lambda path: path.stat().st_mtime_ns,
        reverse=True,
    )


def _board_artifact_path(run_dir: Path, value: Any) -> Path | None:
    """Resolve one board artifact only within the current board evidence root."""

    raw = str(value or "").strip()
    if not raw:
        return None
    board_dir = (run_dir / "verification" / "board_simulation").resolve()
    candidate = Path(raw)
    candidate = candidate if candidate.is_absolute() else board_dir / candidate
    try:
        candidate = candidate.resolve()
    except OSError:
        return None
    return candidate if candidate.is_relative_to(board_dir) else None


def _current_board_boundary_summary_from_execution_manifest(
    run_dir: Path,
    executed_manifest: dict[str, Any],
) -> dict[str, Any]:
    """Rebuild the boundary summary from the trace named by one execution.

    The mutable summary file is a convenient cache, not repair authority.  The
    execution manifest binds its cached hash, trace, semantic contract,
    testbench, and simulator log; rebuild from those exact files before an
    Agent is allowed to use the result.
    """

    blockers: list[str] = []
    execution = (
        executed_manifest.get("execution_evidence", {})
        if isinstance(executed_manifest.get("execution_evidence"), dict)
        else {}
    )
    observation = (
        execution.get("pipeline_boundary_observation", {})
        if isinstance(execution.get("pipeline_boundary_observation"), dict)
        else {}
    )
    summary_ref = (
        observation.get("summary", {})
        if isinstance(observation.get("summary"), dict)
        else {}
    )
    summary_path = _board_artifact_path(run_dir, summary_ref.get("path"))
    declared_summary_sha256 = str(summary_ref.get("sha256") or "")
    if (
        summary_path is None
        or not summary_path.is_file()
        or not is_sha256(declared_summary_sha256)
        or sha256_file(summary_path) != declared_summary_sha256
    ):
        blockers.append("execution manifest does not bind the current boundary summary")
        saved_summary: dict[str, Any] = {}
    else:
        saved_summary = read_json_if_exists(summary_path)
        if not saved_summary:
            blockers.append("execution-bound boundary summary is empty or invalid")

    trace_path = _board_artifact_path(
        run_dir, saved_summary.get("trace_path") if saved_summary else None
    )
    declared_trace_sha256 = str(
        saved_summary.get("trace_sha256") if saved_summary else ""
    )
    declared_trace_name = Path(
        str(executed_manifest.get("boundary_trace_file") or "")
    ).name
    if (
        trace_path is None
        or not trace_path.is_file()
        or not is_sha256(declared_trace_sha256)
        or sha256_file(trace_path) != declared_trace_sha256
        or not declared_trace_name
        or trace_path.name != declared_trace_name
    ):
        blockers.append("execution-bound boundary trace is missing, stale, or mismatched")

    semantic_reference = (
        executed_manifest.get("semantic_testbench_manifest", {})
        if isinstance(executed_manifest.get("semantic_testbench_manifest"), dict)
        else {}
    )
    semantic_path = Path(str(semantic_reference.get("path") or ""))
    semantic_sha256 = str(semantic_reference.get("sha256") or "")
    if (
        not semantic_path.is_absolute()
        or not semantic_path.is_file()
        or not is_sha256(semantic_sha256)
        or sha256_file(semantic_path) != semantic_sha256
    ):
        blockers.append("execution-bound semantic manifest is missing or changed")

    testbench = (
        executed_manifest.get("testbench", {})
        if isinstance(executed_manifest.get("testbench"), dict)
        else {}
    )
    testbench_path = Path(str(testbench.get("path") or ""))
    testbench_sha256 = str(testbench.get("sha256") or "")
    if (
        not testbench_path.is_absolute()
        or not testbench_path.is_file()
        or not is_sha256(testbench_sha256)
        or sha256_file(testbench_path) != testbench_sha256
    ):
        blockers.append("execution-bound board testbench source is missing or changed")

    simulation = (
        execution.get("simulation", {})
        if isinstance(execution.get("simulation"), dict)
        else {}
    )
    simulation_log = (
        simulation.get("log", {}) if isinstance(simulation.get("log"), dict) else {}
    )
    simulation_log_path = _board_artifact_path(run_dir, simulation_log.get("path"))
    simulation_log_sha256 = str(simulation_log.get("sha256") or "")
    if (
        simulation_log_path is None
        or not simulation_log_path.is_file()
        or not is_sha256(simulation_log_sha256)
        or sha256_file(simulation_log_path) != simulation_log_sha256
    ):
        blockers.append("execution-bound simulation log is missing or changed")

    regenerated: dict[str, Any] = {}
    if not blockers:
        regenerated = summarize_boundary_trace_observations(
            trace_path,
            semantic_reference,
            testbench,
            simulation_log_path,
        )
        if canonical_contract_sha256(regenerated) != canonical_contract_sha256(
            saved_summary
        ):
            blockers.append(
                "execution-bound boundary summary does not match its current trace"
            )

    return {
        "status": "pass" if not blockers else "blocked",
        "blockers": blockers,
        "summary": regenerated if not blockers else {},
        "summary_path": str(summary_path) if summary_path is not None else None,
        "summary_sha256": declared_summary_sha256 or None,
        "trace_path": str(trace_path) if trace_path is not None else None,
        "trace_sha256": declared_trace_sha256 or None,
        "simulation_log_path": (
            str(simulation_log_path) if simulation_log_path is not None else None
        ),
        "simulation_log_sha256": simulation_log_sha256 or None,
    }


def _current_board_runner_binds_execution_manifest(
    run_dir: Path,
    feedback: dict[str, Any],
    executed_manifest_path: Path,
    executed_manifest: dict[str, Any],
) -> dict[str, Any]:
    """Verify the runner, execution manifest, source set, and workload agree."""

    blockers: list[str] = []
    runner_binding = (
        feedback.get("runner_report", {})
        if isinstance(feedback.get("runner_report"), dict)
        else {}
    )
    runner_path = Path(str(runner_binding.get("path") or ""))
    runner_sha256 = str(runner_binding.get("sha256") or "")
    runner = (
        runner_binding.get("value", {})
        if isinstance(runner_binding.get("value"), dict)
        else {}
    )
    if (
        not runner_path.is_absolute()
        or not runner_path.is_file()
        or not is_sha256(runner_sha256)
        or sha256_file(runner_path) != runner_sha256
        or not runner
    ):
        blockers.append("current board runner artifact is missing or changed")
    runner_manifest = Path(str(runner.get("executed_manifest") or ""))
    if (
        not runner_manifest.is_absolute()
        or runner_manifest.resolve() != executed_manifest_path.resolve()
    ):
        blockers.append("current runner does not name this execution manifest")
    if runner.get("source_identity_bound") is not True:
        blockers.append("current runner does not prove compiled source identity")

    execution = (
        executed_manifest.get("execution_evidence", {})
        if isinstance(executed_manifest.get("execution_evidence"), dict)
        else {}
    )
    for field in (
        "source_identity_sha256",
        "source_closure_sha256",
        "vcs_compile_plan_sha256",
    ):
        expected = str(executed_manifest.get(field) or "")
        if (
            not is_sha256(expected)
            or execution.get(field) != expected
            or (
                field == "vcs_compile_plan_sha256"
                and runner.get(field) != expected
            )
        ):
            blockers.append(f"runner and execution manifest disagree on {field}")

    identity = (
        runner.get("simulation_execution_identity", {})
        if isinstance(runner.get("simulation_execution_identity"), dict)
        else {}
    )
    compiled_model = (
        identity.get("compiled_model", {})
        if isinstance(identity.get("compiled_model"), dict)
        else {}
    )
    for field in ("source_closure_sha256", "vcs_compile_plan_sha256"):
        if compiled_model.get(field) != executed_manifest.get(field):
            blockers.append(f"runner simulation identity disagrees on {field}")
    if compiled_model.get("compile_source_set_sha256") != execution.get(
        "compile_source_set_sha256"
    ):
        blockers.append("runner simulation identity disagrees on compile source set")

    termination = (
        execution.get("simulation", {}).get("termination_provenance", {})
        if isinstance(execution.get("simulation"), dict)
        and isinstance(execution.get("simulation", {}).get("termination_provenance"), dict)
        else {}
    )
    fingerprint = str(runner.get("input_fingerprint_sha256") or "")
    if (
        not is_sha256(fingerprint)
        or termination.get("exact_source_replay_fingerprint_sha256") != fingerprint
    ):
        blockers.append("runner and execution manifest disagree on workload fingerprint")
    job_id = str(execution.get("job_id") or "")
    remote_workdir = str(runner.get("remote_workdir") or "")
    if not job_id or not remote_workdir or job_id != remote_workdir:
        blockers.append("runner and execution manifest disagree on remote execution")

    return {
        "status": "pass" if not blockers else "blocked",
        "blockers": blockers,
        "runner": runner,
        "runner_path": str(runner_path) if runner_path else None,
        "runner_sha256": runner_sha256 or None,
    }


def _failed_adaptive_observation_recheck(
    run_dir: Path,
    state: dict[str, Any],
    feedback: dict[str, Any],
) -> dict[str, Any]:
    """Allow one old failed probe request to consume a newer, bound execution."""

    blockers: list[str] = []
    decision = state.get("decision", {}) if isinstance(state.get("decision"), dict) else {}
    probe_plan = (
        decision.get("probe_plan", {}) if isinstance(decision.get("probe_plan"), dict) else {}
    )
    if (
        not decision
        or state.get("decision_sha256") != canonical_contract_sha256(decision)
        or canonical_contract_sha256(state.get("event_match", {}))
        != canonical_contract_sha256(probe_plan.get("event_match", {}))
        or state.get("required_event_fields")
        != probe_plan.get("required_event_fields", [])
    ):
        blockers.append("failed adaptive observation state does not bind its decision")

    old_runner = (
        state.get("runner_report", {})
        if isinstance(state.get("runner_report"), dict)
        else {}
    )
    old_runner_sha256 = str(old_runner.get("sha256") or "")
    current_runner = (
        feedback.get("runner_report", {})
        if isinstance(feedback.get("runner_report"), dict)
        else {}
    )
    current_runner_sha256 = str(current_runner.get("sha256") or "")
    if (
        not is_sha256(old_runner_sha256)
        or not is_sha256(current_runner_sha256)
        or old_runner_sha256 == current_runner_sha256
    ):
        blockers.append("failed adaptive observation has no newer runner evidence")

    executed_manifest_path = Path(
        str(
            current_runner.get("value", {}).get("executed_manifest")
            if isinstance(current_runner.get("value"), dict)
            else ""
        )
    )
    if not executed_manifest_path.is_absolute() or not executed_manifest_path.is_file():
        blockers.append("newer runner does not provide a current execution manifest")
        executed_manifest: dict[str, Any] = {}
    else:
        executed_manifest = read_json_if_exists(executed_manifest_path)
        if not executed_manifest:
            blockers.append("newer execution manifest is empty or invalid")

    runner_binding = _current_board_runner_binds_execution_manifest(
        run_dir,
        feedback,
        executed_manifest_path,
        executed_manifest,
    ) if executed_manifest else {"status": "blocked", "blockers": []}
    blockers.extend(runner_binding.get("blockers", []))
    source_edits = [
        row for row in state.get("board_source_edits", []) if isinstance(row, dict)
    ]
    if not source_edits or not _runner_binds_post_edit_board_sources(
        runner_binding.get("runner", {}), source_edits
    ):
        blockers.append("newer runner does not bind the failed probe source edit")
    patch = (
        state.get("source_patch_application", {})
        if isinstance(state.get("source_patch_application"), dict)
        else {}
    )
    patch_path = Path(str(patch.get("path") or ""))
    patch_sha256 = str(patch.get("sha256") or "")
    if (
        not patch_path.is_absolute()
        or not patch_path.is_file()
        or not is_sha256(patch_sha256)
        or sha256_file(patch_path) != patch_sha256
    ):
        blockers.append("failed adaptive observation source-patch record is missing or changed")

    boundary = _current_board_boundary_summary_from_execution_manifest(
        run_dir, executed_manifest
    ) if executed_manifest else {"status": "blocked", "blockers": []}
    blockers.extend(boundary.get("blockers", []))
    return {
        "status": "pass" if not blockers else "blocked",
        "blockers": list(dict.fromkeys(blockers)),
        "runner": runner_binding.get("runner", {}),
        "runner_report": {
            "path": runner_binding.get("runner_path"),
            "sha256": runner_binding.get("runner_sha256"),
        },
        "execution_manifest_path": str(executed_manifest_path)
        if executed_manifest_path.is_absolute()
        else None,
        "boundary": boundary,
    }


def materialize_adaptive_observation_evidence(
    run_dir: Path,
    feedback: dict[str, Any],
) -> dict[str, Any]:
    path = adaptive_observation_state_path(run_dir)
    state = read_json_if_exists(path)
    if state.get("schema_version") != ADAPTIVE_OBSERVATION_STATE_SCHEMA_VERSION:
        return {
            "schema_version": ADAPTIVE_OBSERVATION_STATE_SCHEMA_VERSION,
            "status": "not_run",
            "summary": "no adaptive observation request is pending",
        }
    if state.get("runtime_only") is not True and state.get("board_source_edits"):
        # Older observation rounds edited the compiled testbench and forced a
        # new snapshot. Keep that record as history, but never let it drive a
        # current round now that observation is a runtime-only signal choice.
        return {
            "schema_version": ADAPTIVE_OBSERVATION_STATE_SCHEMA_VERSION,
            "status": "retired_legacy_source_observation",
            "summary": (
                "legacy source-edit observation is history; current Layer-3 "
                "observation uses runtime compiled-signal selection"
            ),
            "legacy_decision_sha256": state.get("decision_sha256"),
            "runtime_only": True,
            "board_source_edits": [],
            "policy": {
                "legacy_signal_values_are_not_current_evidence": True,
                "compiled_sources_must_remain_unchanged": True,
                "same_verified_snapshot_must_be_reused": True,
            },
            "path": str(path),
        }
    prior_status = str(state.get("status") or "")
    failed_state_recheck: dict[str, Any] | None = None
    if prior_status == "fail" and feedback.get("status") == "ready":
        failed_state_recheck = _failed_adaptive_observation_recheck(
            run_dir, state, feedback
        )
        if failed_state_recheck.get("status") == "pass":
            state = {
                **state,
                "status": "pending_real_tool_evidence",
                "recheck_of_failed_state": {
                    "previous_runner_report": copy.deepcopy(
                        state.get("runner_report", {})
                    ),
                    "current_runner_report": copy.deepcopy(
                        failed_state_recheck.get("runner_report", {})
                    ),
                    "execution_manifest_path": failed_state_recheck.get(
                        "execution_manifest_path"
                    ),
                    "trace_sha256": failed_state_recheck.get("boundary", {}).get(
                        "trace_sha256"
                    ),
                },
            }
        else:
            return {
                **state,
                "path": str(path),
                "failed_state_recheck": failed_state_recheck,
            }
    if state.get("status") != "pending_real_tool_evidence":
        return {**state, "path": str(path)}
    if feedback.get("status") != "ready":
        return {**state, "path": str(path)}

    if state.get("runtime_only") is True:
        runner_binding = (
            feedback.get("runner_report", {})
            if isinstance(feedback.get("runner_report"), dict)
            else {}
        )
        runner = (
            runner_binding.get("value", {})
            if isinstance(runner_binding.get("value"), dict)
            else {}
        )
        identity = (
            runner.get("simulation_execution_identity", {})
            if isinstance(runner.get("simulation_execution_identity"), dict)
            else {}
        )
        selected_model = str(
            state.get("runtime_selection", {}).get("compiled_model_sha256")
            if isinstance(state.get("runtime_selection"), dict)
            else ""
        )
        observed_model = str(identity.get("compiled_model_sha256") or "")
        model_matches = bool(
            not selected_model or not observed_model or selected_model == observed_model
        )
        current_epoch = feedback.get("current_signal_epoch")
        if not isinstance(current_epoch, dict):
            live_progress = (
                runner.get("live_progress", {})
                if isinstance(runner.get("live_progress"), dict)
                else {}
            )
            latest = (
                live_progress.get("latest", {})
                if isinstance(live_progress.get("latest"), dict)
                else {}
            )
            current_epoch = (
                latest.get("observation_epoch", {})
                if isinstance(latest.get("observation_epoch"), dict)
                else {}
            )
        blockers = [] if model_matches else [
            "restored run compiled-model identity differs from the runtime signal catalog"
        ]
        result = {
            **state,
            "status": "pass" if not blockers else "fail",
            "evaluated_at_unix_sec": time.time(),
            "runner_report": {
                "path": runner_binding.get("path"),
                "sha256": runner_binding.get("sha256"),
            },
            "compiled_probe_sources_bound": model_matches,
            "current_signal_epoch": copy.deepcopy(current_epoch),
            "blockers": blockers,
            "summary": (
                "fresh restored signal epoch collected with the unchanged compiled observation model"
                if not blockers
                else "runtime observation restore used a different compiled model"
            ),
        }
        write_json(path, result)
        history_path = (
            path.parent
            / "history"
            / f"{state.get('decision_sha256')}_evidence.json"
        )
        write_json(history_path, result)
        return {**result, "path": str(path), "history_path": str(history_path)}

    runner_binding = (
        feedback.get("runner_report", {})
        if isinstance(feedback.get("runner_report"), dict)
        else {}
    )
    runner = (
        runner_binding.get("value", {})
        if isinstance(runner_binding.get("value"), dict)
        else {}
    )
    board_source_edits = [
        row
        for row in state.get("board_source_edits", [])
        if isinstance(row, dict)
    ]
    source_bound = _runner_binds_post_edit_board_sources(
        runner,
        board_source_edits,
    )
    created_at_ns = int(
        state.get("created_at_unix_ns")
        or float(state.get("created_at_unix_sec") or 0.0) * 1_000_000_000
    )
    prior_logs = {
        str(row.get("path") or ""): row
        for row in state.get("pre_request_progress_logs", [])
        if isinstance(row, dict) and row.get("path")
    }

    def fresh_progress_log(candidate: Path) -> bool:
        prior = prior_logs.get(str(candidate))
        if not isinstance(prior, dict):
            return candidate.stat().st_mtime_ns >= created_at_ns
        if prior.get("present") is not True:
            return True
        return bool(
            prior.get("byte_count") != candidate.stat().st_size
            or prior.get("sha256") != sha256_file(candidate)
        )

    logs = [
        candidate
        for candidate in _adaptive_progress_log_candidates(run_dir, feedback)
        if fresh_progress_log(candidate)
    ]
    required_fields = [
        str(value)
        for value in state.get("required_event_fields", [])
        if isinstance(value, str) and value
    ]
    event_match = (
        state.get("event_match", {})
        if isinstance(state.get("event_match"), dict)
        else {}
    )
    boundary_ids, boundary_required_fields = _adaptive_boundary_coverage_plan(state)
    boundary_keys = {
        _adaptive_boundary_key(boundary_id): boundary_id
        for boundary_id in boundary_ids
    }
    aggregate_boundary_events = bool(boundary_keys)
    matched_event: dict[str, Any] | None = None
    matched_line: int | None = None
    selected_log: Path | None = None
    selected_logs: set[Path] = set()
    matched_boundary_records: dict[str, list[dict[str, Any]]] = {}
    invalid_record_count = 0
    for candidate in logs:
        with candidate.open("r", encoding="utf-8", errors="replace") as stream:
            for line_number, line in enumerate(stream, start=1):
                try:
                    event = json.loads(line)
                except json.JSONDecodeError:
                    invalid_record_count += 1
                    continue
                if not isinstance(event, dict):
                    continue
                match_ok = True
                for field, expected in event_match.items():
                    found, actual = _adaptive_event_field_value(event, str(field))
                    if not found or canonical_contract_sha256(
                        {"value": actual}
                    ) != canonical_contract_sha256({"value": expected}):
                        match_ok = False
                        break
                if not match_ok:
                    continue
                if aggregate_boundary_events:
                    boundary_id = boundary_keys.get(
                        _adaptive_boundary_key(event.get("boundary_id"))
                    )
                    if boundary_id is None:
                        continue
                    boundary_key = _adaptive_boundary_key(boundary_id)
                    matched_boundary_records.setdefault(boundary_key, []).append(
                        {
                            "event": event,
                            "line": line_number,
                            "path": str(candidate),
                        }
                    )
                    selected_logs.add(candidate)
                    continue
                if not all(
                    _adaptive_event_field_value(event, field)[0]
                    for field in required_fields
                ):
                    continue
                matched_event = {
                    field: _adaptive_event_field_value(event, field)[1]
                    for field in required_fields
                }
                matched_line = line_number
                selected_log = candidate
                break
        if matched_event is not None:
            break

    matched_event_fields_by_boundary: dict[str, dict[str, Any]] = {}
    missing_boundaries: list[str] = []
    missing_fields_by_boundary: dict[str, list[str]] = {}
    if aggregate_boundary_events:
        for boundary_key, boundary_id in boundary_keys.items():
            records = matched_boundary_records.get(boundary_key, [])
            merged: dict[str, Any] = {}
            for record in records:
                event = record["event"]
                for field in required_fields:
                    found, value = _adaptive_event_field_value(event, field)
                    if found:
                        merged[field] = value
                for field in boundary_required_fields:
                    found, value = _adaptive_event_field_value(
                        event, f"observed_value.{field}"
                    )
                    if not found:
                        found, value = _adaptive_event_field_value(event, field)
                    if found:
                        merged[field] = value
            required_for_boundary = [
                *required_fields,
                *boundary_required_fields,
            ]
            missing_fields = [
                field for field in required_for_boundary if field not in merged
            ]
            if not records:
                missing_boundaries.append(boundary_id)
            if missing_fields:
                missing_fields_by_boundary[boundary_id] = missing_fields
            if records and not missing_fields:
                matched_event_fields_by_boundary[boundary_id] = merged

    blockers = []
    if not source_bound:
        blockers.append("real-tool compiled source identity does not bind the probe edit")
    if not logs:
        blockers.append("no fresh post-edit progress JSONL is available")
    elif aggregate_boundary_events:
        if missing_boundaries:
            blockers.append(
                "fresh boundary trace is missing requested boundaries: "
                + ", ".join(missing_boundaries)
            )
        if missing_fields_by_boundary:
            details = "; ".join(
                f"{boundary}: {', '.join(fields)}"
                for boundary, fields in missing_fields_by_boundary.items()
            )
            blockers.append(
                "fresh boundary trace is missing required fields by boundary: "
                + details
            )
        if not blockers and not matched_event_fields_by_boundary:
            blockers.append("fresh boundary trace contains no matching boundary records")
    elif matched_event is None:
        blockers.append(
            "fresh progress JSONL does not contain one event matching all requested probe fields"
        )
    effective_policy = copy.deepcopy(state.get("policy", {}))
    if isinstance(effective_policy, dict):
        effective_policy.pop("all_required_fields_must_coexist_in_one_event", None)
        effective_policy[
            "all_required_fields_must_be_present_in_current_bound_events"
        ] = True
    result = {
        **state,
        "status": "pass" if not blockers else "fail",
        "rechecked_failed_state": failed_state_recheck is not None,
        "failed_state_recheck": failed_state_recheck,
        "evaluated_at_unix_sec": time.time(),
        "runner_report": {
            "path": runner_binding.get("path"),
            "sha256": runner_binding.get("sha256"),
        },
        "compiled_probe_sources_bound": source_bound,
        "policy": effective_policy,
        "progress_event_log": (
            {
                "path": str(selected_log),
                "sha256": sha256_file(selected_log),
                "matched_line": matched_line,
            }
            if selected_log is not None
            else None
        ),
        "progress_event_logs": [
            {"path": str(log), "sha256": sha256_file(log)}
            for log in sorted(selected_logs)
        ],
        "matched_event_fields": matched_event,
        "matched_event_fields_by_boundary": matched_event_fields_by_boundary,
        "matched_event_count": sum(
            len(records) for records in matched_boundary_records.values()
        ),
        "aggregation_mode": (
            "multi_event_boundary_records"
            if aggregate_boundary_events
            else "single_event"
        ),
        "matched_boundary_ids": [
            boundary_id
            for boundary_id in boundary_ids
            if _adaptive_boundary_key(boundary_id) in matched_boundary_records
        ],
        "missing_boundary_ids": missing_boundaries,
        "missing_fields_by_boundary": missing_fields_by_boundary,
        "invalid_record_count": invalid_record_count,
        "blockers": blockers,
        "summary": (
            "fresh real-tool JSONL emitted the complete Agent-selected adaptive probe event"
            if not blockers
            else "Agent-selected adaptive probes did not produce complete fresh real-tool evidence"
        ),
    }
    write_json(path, result)
    history_path = (
        path.parent
        / "history"
        / f"{state.get('decision_sha256')}_evidence.json"
    )
    write_json(history_path, result)
    return {**result, "path": str(path), "history_path": str(history_path)}


def _json_patch_leaf_paths(value: Any, prefix: str = "") -> list[str]:
    if isinstance(value, dict) and value:
        paths: list[str] = []
        for key, child in sorted(value.items()):
            escaped = str(key).replace("~", "~0").replace("/", "~1")
            paths.extend(_json_patch_leaf_paths(child, f"{prefix}/{escaped}"))
        return paths
    return [prefix or "/"]


def rejected_file_edits_for_agent_retry(edits: list[Any]) -> list[dict[str, Any]]:
    """Preserve the failed edit itself without copying complete replacement bodies."""

    result: list[dict[str, Any]] = []
    for edit in edits:
        if not isinstance(edit, dict):
            continue
        row = {
            key: copy.deepcopy(edit[key])
            for key in ("path", "operation", "expected_sha256")
            if edit.get(key) not in (None, "")
        }
        rationale = str(edit.get("rationale") or "")
        if rationale:
            row["rationale"] = rationale[:2000]
        if (
            edit.get("operation") == "replace_text"
            and isinstance(edit.get("text_replacements"), list)
        ):
            row["text_replacements"] = copy.deepcopy(edit["text_replacements"])
        result.append(row)
    return result


def legal_direct_observation_stop(
    implementation_output: dict[str, Any],
    adaptive_observation_validation: dict[str, Any],
) -> bool:
    """Accept a validated direct-evidence decision that has no safe next action.

    A blocked response normally names an upstream producer.  The one exception
    is a source-bound direct contradiction for which the Agent has validated
    that all existing observations are already sufficient, no safe edit is
    authorized, and no producer can add distinct evidence.  Retrying that same
    request would only repeat the Agent call without changing source or tool
    evidence.
    """

    blocked_reasons = implementation_output.get("blocked_reasons", [])
    required_capabilities = implementation_output.get("required_capabilities", [])
    return (
        implementation_output.get("status") == "blocked"
        and not implementation_output.get("file_edits")
        and isinstance(blocked_reasons, list)
        and any(str(value).strip() for value in blocked_reasons)
        and not required_capabilities
        and implementation_output.get("framework_action_required") is not True
        and adaptive_observation_validation.get("status") == "pass"
        and adaptive_observation_validation.get("mode")
        == "direct_executed_contradiction"
    )


def layer3_required_code_edit_errors(
    output: dict[str, Any],
    run_dir: Path,
    *,
    current_signal_epoch: bool,
) -> list[str]:
    """Require one executable LLM decision for the current Layer-3 epoch.

    Evidence that isolates a fault should produce a functional edit. Evidence
    that does not yet distinguish a safe fault must produce a runtime-only
    observation plan. The framework must not demand speculative RTL edits just
    to satisfy a controller rule.
    """

    if not current_signal_epoch:
        return []

    errors: list[str] = []
    if normalized_implementation_agent_status(output) != "ready_to_apply":
        errors.append(
            "Layer-3 current-signal decision must return status=ready_to_apply"
        )
    if output.get("blocked_reasons"):
        errors.append(
            "Layer-3 current-signal decision must not return blocked_reasons"
        )

    edits = output.get("file_edits", [])
    observation_decision = output.get("adaptive_observation_decision")
    if not isinstance(edits, list):
        errors.append("Layer-3 current-signal decision file_edits must be a list")
        return errors
    if not edits:
        if not isinstance(observation_decision, dict):
            errors.append(
                "Layer-3 current-signal decision without RTL edits must provide an adaptive runtime observation plan"
            )
        return errors

    board_root = (run_dir / "generated" / "board_integration").resolve()
    functional_edit = False
    observation_edit = False
    for edit in edits:
        if not isinstance(edit, dict):
            continue
        raw_path = Path(str(edit.get("path") or ""))
        target = (raw_path if raw_path.is_absolute() else Path.cwd() / raw_path).resolve()
        suffix = target.suffix.lower()
        name = target.name.lower()
        if suffix not in BOARD_INTEGRATION_SOURCE_SUFFIXES:
            continue
        if any(marker in name for marker in ("tb", "testbench")):
            if target.is_relative_to(board_root):
                observation_edit = True
            continue
        # A protocol monitor is executable verification code, not merely a
        # read-only probe.  A current AXI violation can therefore require a
        # real monitor bug fix (for example, same-cycle AW/W handling) while
        # the paired testbench edit expands the next run's observations.
        # Count that code repair as the required non-observation edit, but do
        # not treat generic checker files as functional repairs.
        if "monitor" in name or "checker" in name:
            functional_edit = True
            continue
        functional_edit = True

    if not functional_edit and not isinstance(observation_decision, dict):
        errors.append(
            "Layer-3 current-signal decision must modify functional HDL or provide an adaptive runtime observation plan"
        )
    if functional_edit and not observation_edit and not isinstance(observation_decision, dict):
        errors.append(
            "Layer-3 functional repair must include runtime observation selection or a board-testbench observation update"
        )
    if isinstance(observation_decision, dict) and observation_decision.get("mode") != "deepen_simulation_observation":
        errors.append(
            "Layer-3 runtime observation plan must use deepen_simulation_observation"
        )
    return errors


def apply_agent_file_edits(
    output: dict[str, Any],
    run_dir: Path,
    out_dir: Path,
    *,
    allowed_exact_files: set[Path] | None = None,
    required_exact_files: set[Path] | None = None,
    required_noop_json_merges: dict[Path, dict[str, Any]] | None = None,
    required_template_pairs: set[str] | None = None,
    instrumentation_only_template_pairs: set[str] | None = None,
    repair_checkpoint: dict[str, Any] | None = None,
    allow_template_repair: bool | None = None,
    allow_board_integration: bool = False,
    allowed_semantic_rtl_files: set[Path] | None = None,
    require_exact_source_hash: bool = False,
    report_name: str = "agent_patch_application.json",
    agent_contract_blockers: list[str] | None = None,
    agent_contract_failure_class: str = "agent_output_contract",
    agent_contract_retry_on_blocked: bool = False,
) -> dict[str, Any]:
    raw_status = str(output.get("status") or "")
    approvals = output.get("approval_required_for", []) if isinstance(output.get("approval_required_for"), list) else []
    edits = output.get("file_edits", []) if isinstance(output.get("file_edits"), list) else []
    declared_blockers = (
        output.get("blocked_reasons", [])
        if isinstance(output.get("blocked_reasons"), list)
        else []
    )
    status = normalized_implementation_agent_status(output)
    blockers: list[str] = [
        str(value) for value in (agent_contract_blockers or []) if str(value)
    ]
    staged: list[tuple[Path, str, str, str]] = []
    protocol_normalizations: list[dict[str, Any]] = []
    total_bytes = 0
    seen_edit_targets: set[Path] = set()
    normalized_required_noop_json_merges = {
        path.resolve(): copy.deepcopy(value)
        for path, value in (required_noop_json_merges or {}).items()
        if isinstance(value, dict)
    }
    acknowledged_required_noop_merges: dict[Path, dict[str, Any]] = {}
    acknowledged_optional_noop_merges: dict[Path, dict[str, Any]] = {}
    rejected_prior_failed_board_attempt: dict[str, Any] | None = None
    agent_transaction_rejection: dict[str, Any] | None = None
    retry_agent_without_real_tool = False

    if status != raw_status:
        protocol_normalizations.append(
            {
                "field": "status",
                "from": raw_status,
                "to": status,
                "guard": "nonempty file_edits with no approval or declared blocker",
            }
        )

    if status != "ready_to_apply":
        blockers.append(f"implementation agent status is not ready_to_apply: {status}")
    if approvals:
        blockers.append(f"implementation agent requested approval: {approvals}")
    if not edits:
        blockers.append("implementation agent returned no file edits")

    for index, edit in enumerate(edits):
        if not isinstance(edit, dict):
            blockers.append(f"file_edits[{index}] is not an object")
            continue
        raw_path = str(edit.get("path") or "")
        target = Path(raw_path)
        target = target if target.is_absolute() else Path.cwd() / target
        target = target.resolve()
        if target in seen_edit_targets:
            blockers.append(
                f"file_edits[{index}] duplicates an earlier resolved target: {target}"
            )
            continue
        seen_edit_targets.add(target)
        operation = str(edit.get("operation") or "")
        expected = str(edit.get("expected_sha256") or "")
        content = str(edit.get("content") or "")
        json_content_supplied = "json_content" in edit
        json_content = edit.get("json_content")
        text_replacements_supplied = "text_replacements" in edit
        text_replacements = edit.get("text_replacements")
        if not allowed_capability_edit_target(
            target,
            run_dir,
            allow_template_repair=allow_template_repair,
            allow_board_integration=allow_board_integration,
            allowed_semantic_rtl_files=allowed_semantic_rtl_files,
        ):
            blockers.append(f"file_edits[{index}] target is outside the capability-repair write boundary: {target}")
            continue
        if allowed_exact_files is not None and target not in allowed_exact_files:
            blockers.append(f"file_edits[{index}] target is outside the current semantic repair phase: {target}")
            continue
        if operation not in {"create", "replace", "replace_text", "merge_json"}:
            blockers.append(f"file_edits[{index}] has unsupported operation: {operation}")
            continue
        if operation == "replace_text" and json_content_supplied:
            blockers.append(
                f"file_edits[{index}] replace_text cannot use json_content: {target}"
            )
            continue
        if json_content_supplied:
            if target.suffix.lower() != ".json":
                blockers.append(
                    f"file_edits[{index}] json_content is allowed only for .json targets: {target}"
                )
                continue
            if content:
                blockers.append(
                    f"file_edits[{index}] must use exactly one of content or json_content"
                )
                continue
            if not isinstance(json_content, dict):
                blockers.append(f"file_edits[{index}] json_content is not an object")
                continue
            if operation != "merge_json":
                content = json.dumps(json_content, indent=2, sort_keys=True) + "\n"
                protocol_normalizations.append(
                    {
                        "field": f"file_edits[{index}].json_content",
                        "operation": "serialize_structured_json_content",
                        "guard": "target suffix is .json and string content is empty",
                    }
                )
        elif operation == "merge_json":
            blockers.append(
                f"file_edits[{index}] merge_json requires json_content: {target}"
            )
            continue
        if operation == "create" and not target.exists() and expected == "absent":
            protocol_normalizations.append(
                {
                    "field": f"file_edits[{index}].expected_sha256",
                    "from": "absent",
                    "to": "",
                    "guard": "operation=create and target does not exist",
                }
            )
            expected = ""
        if target.exists() and operation not in {"replace", "replace_text", "merge_json"}:
            blockers.append(f"file_edits[{index}] must use replace for existing file: {target}")
            continue
        if not target.exists() and operation != "create":
            blockers.append(f"file_edits[{index}] must use create for missing file: {target}")
            continue
        actual = ""
        if target.exists():
            actual = sha256_file(target)
            # File versions are historical notes only.  Current source text,
            # path permissions, and unique replacement anchors decide whether
            # an edit can be applied; an old digest must not stop repair.
            if expected and expected != actual:
                protocol_normalizations.append(
                    {
                        "field": f"file_edits[{index}].expected_sha256",
                        "operation": "ignore_old_file_version",
                        "guard": "the current source is used for this edit",
                    }
                )
        elif expected:
            protocol_normalizations.append(
                {
                    "field": f"file_edits[{index}].expected_sha256",
                    "operation": "ignore_old_file_version_for_new_file",
                    "guard": "file creation is decided by the current path state",
                }
            )
        if operation == "merge_json":
            if text_replacements_supplied:
                blockers.append(
                    f"file_edits[{index}] merge_json cannot use text_replacements: {target}"
                )
                continue
            try:
                current_json = json.loads(target.read_text(encoding="utf-8"))
            except (OSError, UnicodeError, json.JSONDecodeError) as exc:
                blockers.append(
                    f"file_edits[{index}] merge_json cannot read current JSON object {target}: {exc}"
                )
                continue
            if not isinstance(current_json, dict):
                blockers.append(
                    f"file_edits[{index}] merge_json target is not a JSON object: {target}"
                )
                continue
            required_authority_patch = normalized_required_noop_json_merges.get(
                target
            )
            if (
                required_authority_patch is not None
                and json_content != required_authority_patch
            ):
                protocol_normalizations.append(
                    {
                        "field": f"file_edits[{index}].json_content",
                        "operation": (
                            "bind_framework_owned_checkpoint_contract_authority"
                        ),
                        "agent_supplied_patch_sha256": canonical_contract_sha256(
                            json_content
                        ),
                        "authority_patch_sha256": canonical_contract_sha256(
                            required_authority_patch
                        ),
                        "guard": (
                            "the complete checkpoint manifest contract is framework-owned; "
                            "the Agent merge declares intent but cannot change adapter paths, "
                            "hashes, ABI invariants, or the framework-derived DUT root"
                        ),
                    }
                )
                json_content = copy.deepcopy(required_authority_patch)
            merged_json = _deep_merge_json_object(current_json, json_content)
            if merged_json == current_json:
                required_noop_patch = normalized_required_noop_json_merges.get(
                    target
                )
                required_noop_acknowledgement = (
                    required_exact_files is not None
                    and target in {path.resolve() for path in required_exact_files}
                    and required_noop_patch is not None
                    and json_content == required_noop_patch
                )
                provenance_binding = (
                    _bind_current_exact_board_generation_provenance(
                        merged_json,
                        out_dir,
                    )
                    if allow_board_integration
                    and target.name == "dut_weight_binding_manifest.json"
                    and _exact_board_generation_provenance_rebind_intent(
                        json_content
                    )
                    else None
                )
                if provenance_binding is None and not required_noop_acknowledgement:
                    protocol_normalizations.append(
                        {
                            "field": f"file_edits[{index}].json_content",
                            "operation": "skip_unchanged_json_update",
                            "guard": "the current JSON already contains this update",
                        }
                    )
                    continue
                if provenance_binding is not None:
                    protocol_normalizations.append(provenance_binding)
                if required_noop_acknowledgement:
                    acknowledged_required_noop_merges[target] = {
                        "patch_sha256": canonical_contract_sha256(json_content),
                    }
            content = json.dumps(merged_json, indent=2, sort_keys=True) + "\n"
            protocol_normalizations.append(
                {
                    "field": f"file_edits[{index}].json_content",
                    "operation": "materialize_hash_bound_deep_json_merge",
                    "patch_sha256": canonical_contract_sha256(json_content),
                    "patched_leaf_paths": _json_patch_leaf_paths(json_content),
                    "guard": (
                        "pre-edit SHA-256 matched, target and patch were JSON objects, "
                        "explicit object keys were recursively merged, and omitted fields "
                        "were preserved without implicit deletion"
                    ),
                }
            )
        elif operation == "replace_text":
            if target.suffix.lower() == ".json":
                blockers.append(
                    f"file_edits[{index}] replace_text is not allowed for JSON: {target}"
                )
                continue
            if content:
                blockers.append(
                    f"file_edits[{index}] replace_text must use empty content: {target}"
                )
                continue
            if not isinstance(text_replacements, list) or not text_replacements:
                blockers.append(
                    f"file_edits[{index}] replace_text has no text_replacements: {target}"
                )
                continue
            try:
                before_text = target.read_text(encoding="utf-8")
            except (OSError, UnicodeError) as exc:
                blockers.append(
                    f"file_edits[{index}] replace_text cannot read UTF-8 source {target}: {exc}"
                )
                continue
            replacement_records: list[dict[str, Any]] = []
            replacement_error = False
            for replacement_index, replacement in enumerate(text_replacements):
                if not isinstance(replacement, dict):
                    blockers.append(
                        f"file_edits[{index}].text_replacements[{replacement_index}] is not an object"
                    )
                    replacement_error = True
                    break
                old_text = replacement.get("old_text")
                new_text = replacement.get("new_text")
                if not isinstance(old_text, str) or not old_text:
                    blockers.append(
                        f"file_edits[{index}].text_replacements[{replacement_index}].old_text is empty or invalid"
                    )
                    replacement_error = True
                    break
                if not isinstance(new_text, str):
                    blockers.append(
                        f"file_edits[{index}].text_replacements[{replacement_index}].new_text is invalid"
                    )
                    replacement_error = True
                    break
                match_count = before_text.count(old_text)
                if match_count != 1:
                    blockers.append(
                        f"file_edits[{index}].text_replacements[{replacement_index}].old_text must match exactly once in sequence; found {match_count}"
                    )
                    replacement_error = True
                    break
                if old_text == new_text:
                    blockers.append(
                        f"file_edits[{index}].text_replacements[{replacement_index}] does not change the source"
                    )
                    replacement_error = True
                    break
                start = before_text.find(old_text)
                replacement_records.append(
                    {
                        "replacement_index": replacement_index,
                        "start": start,
                        "end": start + len(old_text),
                    }
                )
            if replacement_error:
                continue
            ordered_records = sorted(replacement_records, key=lambda row: row["start"])
            for prior, current in zip(ordered_records, ordered_records[1:]):
                if current["start"] < prior["end"]:
                    blockers.append(
                        f"file_edits[{index}] replace_text anchors overlap in the pre-edit source"
                    )
                    replacement_error = True
                    break
            if replacement_error:
                continue
            patched_text = before_text
            for record in reversed(ordered_records):
                replacement = text_replacements[record["replacement_index"]]
                patched_text = (
                    patched_text[: record["start"]]
                    + replacement["new_text"]
                    + patched_text[record["end"] :]
                )
            if patched_text == before_text:
                blockers.append(
                    f"file_edits[{index}] replace_text leaves the source unchanged: {target}"
                )
                continue
            content = patched_text
            protocol_normalizations.append(
                {
                    "field": f"file_edits[{index}].text_replacements",
                    "operation": "materialize_unique_text_replacements",
                    "replacement_count": len(replacement_records),
                    "replacements": [
                        {
                            key: value
                            for key, value in record.items()
                            if key not in {"start", "end"}
                        }
                        for record in replacement_records
                    ],
                    "guard": (
                        "every old_text matched exactly once in the original source, "
                        "anchors did not overlap, and replacements "
                        "were materialized by descending original offset"
                    ),
                }
            )
        elif text_replacements_supplied:
            blockers.append(
                f"file_edits[{index}] text_replacements requires operation=replace_text"
            )
            continue
        if not content:
            blockers.append(f"file_edits[{index}] content is empty: {target}")
            continue
        if (
            allow_board_integration
            and target.name == "dut_weight_binding_manifest.json"
            and operation == "replace"
            and target.is_file()
        ):
            prior_manifest = read_json_if_exists(target)
            try:
                agent_manifest = json.loads(content)
            except json.JSONDecodeError:
                agent_manifest = None
            if (
                (
                    prior_manifest.get("status") == "pass"
                    or board_only_incomplete_lower_layer_bindings_attested(
                        target,
                        prior_manifest,
                        out_dir,
                    )
                )
                and isinstance(agent_manifest, dict)
                and isinstance(prior_manifest.get("stage_harnesses"), dict)
                and isinstance(prior_manifest.get("single_layer_harness"), dict)
            ):
                preserved_fields = CERTIFIED_LOWER_LAYER_BINDING_FIELDS
                agent_manifest = preserve_certified_lower_layer_binding_fields(
                    agent_manifest,
                    prior_manifest,
                )
                content = json.dumps(agent_manifest, indent=2, sort_keys=True) + "\n"
                protocol_normalizations.append(
                    {
                        "field": f"file_edits[{index}].content",
                        "operation": "preserve_certified_lower_layer_bindings",
                        "preserved_fields": list(preserved_fields),
                        "certified_manifest_sha256": actual,
                        "guard": (
                            "board manifest replace over a certified lower-layer manifest with "
                            "complete stage and single-layer bindings"
                        ),
                    }
                )
            if isinstance(agent_manifest, dict):
                (
                    generation_record_path,
                    generation_record,
                    trusted_generation,
                ) = select_trusted_exact_board_generation_record(
                    out_dir,
                    expected_status="ready_to_apply",
                )
                harness = agent_manifest.get("multilayer_harness")
                if (
                    trusted_generation.get("status") == "pass"
                    and isinstance(harness, dict)
                ):
                    harness["generation_provenance"] = {
                        "mode": "llm",
                        "agent_id": generation_record.get("agent"),
                        "model": generation_record.get("model"),
                        "used_fallback": generation_record.get("used_fallback"),
                        "prompt_sha256": trusted_generation.get("prompt_sha256"),
                        "prompt_path": trusted_generation.get("prompt_path"),
                        "record_path": str(generation_record_path),
                        "record_sha256": trusted_generation.get("sha256"),
                    }
                    content = json.dumps(
                        agent_manifest, indent=2, sort_keys=True
                    ) + "\n"
                    protocol_normalizations.append(
                        {
                            "field": f"file_edits[{index}].content",
                            "operation": "bind_exact_board_llm_generation_provenance",
                            "trusted_generation_record": str(
                                generation_record_path
                            ),
                            "trusted_generation_record_sha256": (
                                trusted_generation.get("sha256")
                            ),
                            "prompt_sha256": trusted_generation.get(
                                "prompt_sha256"
                            ),
                            "guard": (
                                "current exact-board generation record is a "
                                "non-fallback ready_to_apply LLM record with "
                                "hash-verified prompt"
                            ),
                        }
                    )
        total_bytes += len(content.encode("utf-8"))
        if total_bytes > 2_000_000:
            blockers.append("implementation patch exceeds the 2 MB bounded-repair limit")
            continue
        if target.name == "dut_weight_binding_manifest.json":
            try:
                parsed = json.loads(content)
                if not isinstance(parsed, dict):
                    raise ValueError("manifest is not an object")
            except (json.JSONDecodeError, ValueError) as exc:
                blockers.append(f"DUT weight-binding manifest is invalid JSON: {exc}")
                continue
        # Keep the observed pre-edit identity in the framework record even
        # when a narrow replace_text edit intentionally omitted it from the
        # LLM response. Later real-tool failures need this provenance to
        # become reusable negative experiments.
        staged.append((target, content, operation, actual or expected))

    changed_source_hashes: dict[Path, tuple[str, str]] = {}
    semantic_manifest_path = (
        run_dir
        / "verification"
        / "semantic_testbench"
        / "semantic_testbench_manifest.json"
    ).resolve()
    board_simulation_manifest_path = (
        run_dir
        / "verification"
        / "board_simulation"
        / "board_simulation_manifest.json"
    ).resolve()
    binding_manifest_path = (
        run_dir
        / "generated"
        / "memory"
        / "dut_weight_binding_manifest.json"
    ).resolve()
    board_integration_root = (run_dir / "generated" / "board_integration").resolve()
    if allow_board_integration and allowed_semantic_rtl_files:
        allowed_semantic_paths = {
            path.resolve() for path in (allowed_semantic_rtl_files or set())
        }
        for target, content, _, expected in staged:
            if target not in allowed_semantic_paths or not target.is_file():
                continue
            before = sha256_file(target)
            after = hashlib.sha256(content.encode("utf-8")).hexdigest()
            if before and before != after:
                changed_source_hashes[target] = (before, after)

        # The connected-layer source is shared by the semantic and board
        # bindings. Keep both derived manifests in the same transaction as the
        # RTL edit; the board preflight manifest is regenerated later by the
        # normal finalizer, so its old copy remains historical evidence.
        staged_paths = {target for target, _, _, _ in staged}
        for derived_path, label in (
            (semantic_manifest_path, "semantic_testbench_manifest.json"),
            (board_simulation_manifest_path, "board_simulation_manifest.json"),
            (binding_manifest_path, "dut_weight_binding_manifest.json"),
        ):
            if not changed_source_hashes or derived_path in staged_paths:
                continue
            if not derived_path.is_file():
                blockers.append(f"derived manifest is missing for source hash rebinding: {derived_path}")
                continue
            try:
                derived_content = derived_path.read_text(encoding="utf-8")
            except (OSError, UnicodeError) as exc:
                blockers.append(
                    f"{label} cannot be read for deterministic source hash rebinding: {exc}"
                )
                continue
            staged.append(
                (
                    derived_path,
                    derived_content,
                    "replace",
                    sha256_file(derived_path),
                )
            )
            staged_paths.add(derived_path)
            protocol_normalizations.append(
                {
                    "field": label,
                    "operation": "stage_manifest_for_semantic_source_hash_rebinding",
                    "changed_source_paths": sorted(
                        str(path) for path in changed_source_hashes
                    ),
                    "guard": (
                        "a current successful semantic RTL edit changed a source used by "
                        "the connected and board bindings"
                    ),
                }
            )

    if allow_board_integration and staged:
        board_root = (run_dir / "generated" / "board_integration").resolve()
        manifest_path = (
            run_dir / "generated" / "memory" / "dut_weight_binding_manifest.json"
        ).resolve()
        staged_paths = {target for target, _, _, _ in staged}
        board_source_changed = any(
            target.is_relative_to(board_root)
            and target.suffix.lower() in BOARD_INTEGRATION_SOURCE_SUFFIXES
            for target in staged_paths
        )
        if board_source_changed and manifest_path not in staged_paths:
            if manifest_path.is_file():
                try:
                    manifest_content = manifest_path.read_text(encoding="utf-8")
                except (OSError, UnicodeError) as exc:
                    blockers.append(
                        f"current board binding manifest cannot be read for deterministic hash rebinding: {exc}"
                    )
                else:
                    staged.append(
                        (
                            manifest_path,
                            manifest_content,
                            "replace",
                            sha256_file(manifest_path),
                        )
                    )
                    protocol_normalizations.append(
                        {
                            "field": "dut_weight_binding_manifest.json",
                            "operation": "stage_existing_manifest_for_board_source_hash_rebinding",
                            "guard": (
                                "an agent-owned board source changed while the semantic "
                                "manifest contract remained unchanged"
                            ),
                        }
                    )
        staged_by_path = {target: content for target, content, _, _ in staged}
        normalized_staged: list[tuple[Path, str, str, str]] = []
        for target, content, operation, expected in staged:
            if target in {semantic_manifest_path, board_simulation_manifest_path}:
                try:
                    parsed_manifest = json.loads(content)
                except (json.JSONDecodeError, TypeError) as exc:
                    blockers.append(
                        f"semantic_testbench_manifest.json is invalid JSON during source hash rebinding: {exc}"
                    )
                    continue
                if not isinstance(parsed_manifest, dict):
                    blockers.append("semantic_testbench_manifest.json is not a JSON object")
                    continue
                rebound, rebind_report = rebind_changed_source_hashes_in_manifest(
                    parsed_manifest,
                    run_dir,
                    changed_source_hashes,
                    staged_content_by_path=staged_by_path,
                    # The board integration testbench is a board-only
                    # observation target.  It may be absent from the
                    # connected semantic manifest; the board binding manifest
                    # below is the owner that rebases its source hash.  Keep
                    # strict matching for edits that include non-board
                    # semantic sources.
                    require_match=not (
                        changed_source_hashes
                        and all(
                            path.is_relative_to(board_integration_root)
                            for path in changed_source_hashes
                        )
                    ),
                )
                blockers.extend(
                    f"semantic_testbench_manifest.json: {error}"
                    for error in rebind_report.get("blockers", [])
                    if str(error)
                )
                protocol_normalizations.append(
                    {
                        "field": str(target),
                        "operation": "rebind_changed_source_hashes_in_manifest",
                        "report": rebind_report,
                    }
                )
                content = json.dumps(rebound, indent=2, sort_keys=True) + "\n"
                normalized_staged.append((target, content, operation, expected))
                continue
            if target.name != "dut_weight_binding_manifest.json":
                normalized_staged.append((target, content, operation, expected))
                continue
            try:
                manifest = json.loads(content)
            except json.JSONDecodeError:
                normalized_staged.append((target, content, operation, expected))
                continue
            provenance_already_bound = any(
                isinstance(row, dict)
                and row.get("operation")
                == "bind_exact_board_llm_generation_provenance"
                for row in protocol_normalizations
            )
            harness = manifest.get("multilayer_harness")
            if not provenance_already_bound and isinstance(harness, dict):
                (
                    generation_record_path,
                    generation_record,
                    trusted_generation,
                ) = select_trusted_exact_board_generation_record(
                    out_dir,
                    expected_status="ready_to_apply",
                )
                if trusted_generation.get("status") == "pass":
                    harness["generation_provenance"] = {
                        "mode": "llm",
                        "agent_id": generation_record.get("agent"),
                        "model": generation_record.get("model"),
                        "used_fallback": generation_record.get("used_fallback"),
                        "prompt_sha256": trusted_generation.get("prompt_sha256"),
                        "prompt_path": trusted_generation.get("prompt_path"),
                        "record_path": str(generation_record_path),
                        "record_sha256": trusted_generation.get("sha256"),
                    }
                    protocol_normalizations.append(
                        {
                            "field": "dut_weight_binding_manifest.json",
                            "operation": "bind_exact_board_llm_generation_provenance",
                            "trusted_generation_record": str(
                                generation_record_path
                            ),
                            "trusted_generation_record_sha256": (
                                trusted_generation.get("sha256")
                            ),
                            "prompt_sha256": trusted_generation.get(
                                "prompt_sha256"
                            ),
                            "guard": (
                                "an exact-board RTL repair auto-staged the semantic "
                                "manifest and the hash-bound generation record is a "
                                "non-fallback ready_to_apply LLM result"
                            ),
                        }
                    )
            manifest = canonicalize_exact_board_manifest_declarations(
                manifest,
                run_dir,
                out_dir,
                staged_content_by_path=staged_by_path,
            )
            board_plan = manifest.get("board_simulation_preflight_plan")
            if isinstance(board_plan, dict):
                board_testbench = (
                    board_plan.get("testbench", {})
                    if isinstance(board_plan.get("testbench"), dict)
                    else {}
                )
                declared_checkpoint_contract = board_testbench.get(
                    "simulation_checkpoint_contract"
                )
                if declared_checkpoint_contract is not None:
                    if not isinstance(declared_checkpoint_contract, dict):
                        blockers.append(
                            "simulation checkpoint contract in the board manifest is not an object"
                        )
                    else:
                        blockers.extend(
                            "simulation_checkpoint_contract: " + error
                            for error in checkpoint_contract_errors(
                                declared_checkpoint_contract
                            )
                        )
                missing_prerequisites = framework_vcs_plan_binding_missing_prerequisites(
                    run_dir,
                    str(
                        board_plan.get("validation_mode")
                        or "exact_sample_physical_ddr"
                    ),
                )
                if missing_prerequisites:
                    blockers.append(
                        "framework VCS-plan binding prerequisites are missing: "
                        + "; ".join(missing_prerequisites)
                    )
                else:
                    manifest, vcs_binding = bind_framework_vcs_compile_plan(
                        manifest,
                        run_dir,
                        out_dir,
                        target,
                    )
                    blockers.extend(vcs_binding.get("blockers", []))
                    if vcs_binding.get("status") == "pass":
                        protocol_normalizations.append(
                            {
                                "field": (
                                    "dut_weight_binding_manifest.json."
                                    "board_simulation_preflight_plan.vcs_compile_plan"
                                ),
                                "operation": "bind_framework_vcs_compile_plan",
                                "ordered_command_count": vcs_binding.get(
                                    "ordered_command_count"
                                ),
                                "compile_source_count": vcs_binding.get(
                                    "compile_source_count"
                                ),
                                "vcs_compile_plan_sha256": vcs_binding.get(
                                    "vcs_compile_plan_sha256"
                                ),
                                "guard": (
                                    "plan is regenerated from the agent-selected source replacement, "
                                    "fixture selection and testbench top plus immutable Vivado/fixture authority"
                                ),
                            }
                        )
            manifest, binding = bind_agent_owned_board_source_hashes(
                manifest,
                run_dir,
                staged_by_path,
            )
            if changed_source_hashes:
                manifest, rebind_report = rebind_changed_source_hashes_in_manifest(
                    manifest,
                    run_dir,
                    changed_source_hashes,
                    staged_content_by_path=staged_by_path,
                    require_match=True,
                )
                blockers.extend(
                    f"dut_weight_binding_manifest.json: {error}"
                    for error in rebind_report.get("blockers", [])
                    if str(error)
                )
                protocol_normalizations.append(
                    {
                        "field": str(target),
                        "operation": "rebind_changed_source_hashes_in_manifest",
                        "report": rebind_report,
                    }
                )
            blockers.extend(binding["blockers"])
            content = json.dumps(manifest, indent=2, sort_keys=True) + "\n"
            normalized_staged.append((target, content, operation, expected))
            if binding["bound_source_ids"]:
                protocol_normalizations.append(
                    {
                        "field": "dut_weight_binding_manifest.json",
                        "operation": "bind_agent_owned_board_source_hashes",
                        "bound_source_ids": binding["bound_source_ids"],
                        "guard": (
                            "board source identity is inside generated/board_integration "
                            "and its final content is available in the same staged edit or on disk"
                        ),
                    }
                )
        staged = normalized_staged
        total_bytes = sum(len(content.encode("utf-8")) for _, content, _, _ in staged)
        if total_bytes > 2_000_000 and "implementation patch exceeds the 2 MB bounded-repair limit" not in blockers:
            blockers.append("implementation patch exceeds the 2 MB bounded-repair limit")

    if required_template_pairs is not None:
        framework_root = (Path.cwd() / "accagent" / "framework" / "templates" / "operator_chisel").resolve()
        generated_root = (
            run_dir / "generated" / "chisel" / "src" / "main" / "scala" / "spatialaccagent" / "templates"
        ).resolve()
        staged_by_path = {target: content for target, content, _, _ in staged}
        edited_names = {
            target.name
            for target in staged_by_path
            if target.is_relative_to(framework_root) or target.is_relative_to(generated_root)
        }
        for name in sorted(required_template_pairs | edited_names):
            persistent = framework_root / name
            generated = generated_root / name
            if persistent not in staged_by_path or generated not in staged_by_path:
                blockers.append(f"semantic template repair must replace both persistent/generated copies of {name}")
                continue
            if staged_by_path[persistent] != staged_by_path[generated]:
                blockers.append(f"persistent/generated semantic template contents differ for {name}")

    if instrumentation_only_template_pairs is not None:
        framework_root = (Path.cwd() / "accagent" / "framework" / "templates" / "operator_chisel").resolve()
        generated_root = (
            run_dir / "generated" / "chisel" / "src" / "main" / "scala" / "spatialaccagent" / "templates"
        ).resolve()
        staged_by_path = {target: content for target, content, _, _ in staged}
        for name in sorted(instrumentation_only_template_pairs):
            persistent = framework_root / name
            generated = generated_root / name
            if persistent not in staged_by_path or generated not in staged_by_path:
                continue
            before = persistent.read_text(encoding="utf-8")
            blockers.extend(
                f"{name}: {error}"
                for error in template_trace_instrumentation_errors(
                    before,
                    staged_by_path[persistent],
                )
            )

    # Earlier failed candidates remain in the Agent's repair history, but they
    # are not a veto.  Current internal signals and the current code decide
    # whether the next small edit is worth running through real board VCS.

    normalized_required = {
        path.resolve() for path in (required_exact_files or set())
    }
    replace_text_contract_markers = (
        "replace_text cannot use json_content",
        "replace_text must use empty content",
        "replace_text has no text_replacements",
        ".text_replacements[",
        "replace_text anchors overlap",
        "text_replacements requires operation=replace_text",
    )
    replace_text_contract_blockers = [
        blocker
        for blocker in blockers
        if blocker.startswith("file_edits[")
        and any(marker in blocker for marker in replace_text_contract_markers)
    ]
    checkpoint_transaction_cascade = (
        "required checkpoint manifest no-op acknowledgement requires a "
        "materially changed paired atomic edit target",
        "implementation patch is missing a required atomic edit target:",
    )
    checkpoint_transaction_blockers_only = bool(replace_text_contract_blockers) and all(
        blocker in replace_text_contract_blockers
        or blocker.startswith(checkpoint_transaction_cascade)
        for blocker in blockers
    )
    if (
        status == "ready_to_apply"
        and not approvals
        and not declared_blockers
        and len(normalized_required) == 2
        and len(normalized_required_noop_json_merges) == 1
        and checkpoint_transaction_blockers_only
        and set(seen_edit_targets) == normalized_required
    ):
        manifest_path = next(iter(normalized_required_noop_json_merges))
        paired_path = next(iter(normalized_required - {manifest_path}), None)
        indexed_edits: dict[Path, dict[str, Any]] = {}
        for edit in edits:
            if not isinstance(edit, dict):
                continue
            raw_target = Path(str(edit.get("path") or ""))
            target = (
                raw_target if raw_target.is_absolute() else Path.cwd() / raw_target
            ).resolve()
            indexed_edits[target] = edit
        manifest_edit = indexed_edits.get(manifest_path, {})
        paired_edit = indexed_edits.get(paired_path, {}) if paired_path else {}
        if (
            manifest_path in acknowledged_required_noop_merges
            and manifest_edit.get("operation") == "merge_json"
            and paired_path is not None
            and paired_edit.get("operation") == "replace_text"
            and all(path.is_file() for path in normalized_required)
        ):
            retry_agent_without_real_tool = True
            agent_transaction_rejection = {
                "schema_version": "spatialaccagent.agent_transaction_rejection.v1",
                "status": "ready_for_agent_retry",
                "failure_class": "checkpoint_atomic_replace_text_contract",
                "blockers": copy.deepcopy(blockers),
                "file_edits_were_not_applied": True,
                "real_tool_replay_required_before_retry": False,
                "unchanged_pre_edit_files": [
                    {
                        "path": str(path),
                        "sha256": sha256_file(path),
                    }
                    for path in sorted(normalized_required)
                ],
            }

    replace_text_contract_only = bool(blockers) and all(
        blocker.startswith("file_edits[")
        and (
            ".text_replacements" in blocker
            or " replace_text " in blocker
        )
        for blocker in blockers
    )
    if (
        status == "ready_to_apply"
        and not approvals
        and not declared_blockers
        and agent_transaction_rejection is None
        and replace_text_contract_only
    ):
        retry_agent_without_real_tool = True
        agent_transaction_rejection = {
            "schema_version": "spatialaccagent.agent_transaction_rejection.v1",
            "status": "ready_for_agent_retry",
            "failure_class": "atomic_replace_text_contract",
            "blockers": copy.deepcopy(blockers),
            "file_edits_were_not_applied": True,
            "real_tool_replay_required_before_retry": False,
            "unchanged_pre_edit_files": [
                {
                    "path": str(path),
                    "sha256": sha256_file(path),
                }
                for path in sorted(seen_edit_targets)
                if path.is_file()
            ],
        }

    if (
        agent_contract_blockers
        and (status == "ready_to_apply" or agent_contract_retry_on_blocked)
        and not approvals
    ):
        retry_agent_without_real_tool = True
        agent_transaction_rejection = {
            "schema_version": "spatialaccagent.agent_transaction_rejection.v1",
            "status": "ready_for_agent_retry",
            "failure_class": agent_contract_failure_class,
            "blockers": list(dict.fromkeys(blockers)),
            "file_edits_were_not_applied": True,
            "real_tool_replay_required_before_retry": False,
            "unchanged_pre_edit_files": [
                {
                    "path": str(path),
                    "sha256": sha256_file(path),
                }
                for path in sorted(seen_edit_targets)
                if path.is_file()
            ],
        }

    if agent_transaction_rejection is not None:
        agent_transaction_rejection["rejected_file_edits"] = (
            rejected_file_edits_for_agent_retry(edits)
        )

    records = []
    if not blockers:
        ordered_staged = sorted(
            staged,
            key=lambda row: row[0].name == "dut_weight_binding_manifest.json",
        )
        for target, content, operation, expected in ordered_staged:
            target.parent.mkdir(parents=True, exist_ok=True)
            temp = target.with_name(f".{target.name}.spatialaccagent.tmp")
            temp.write_text(content, encoding="utf-8")
            temp.replace(target)
            records.append(
                {
                    "path": str(target),
                    "operation": operation,
                    "before_sha256": expected or None,
                    "after_sha256": sha256_file(target),
                    "bytes": target.stat().st_size,
                }
            )

    report = {
        "schema_version": "spatialaccagent.agent_patch_application.v1",
        "status": "pass" if not blockers else "blocked",
        "agent_status": status,
        "raw_agent_status": raw_status,
        "protocol_normalizations": protocol_normalizations,
        "files": records,
        "blockers": blockers,
        "retry_agent_without_real_tool": retry_agent_without_real_tool,
        "rejected_prior_failed_board_attempt": (
            rejected_prior_failed_board_attempt
        ),
        "agent_transaction_rejection": agent_transaction_rejection,
        "requested_validation": output.get("requested_validation", []),
        "repair_checkpoint": repair_checkpoint,
        "policy": {
            "all_edits_validated_before_any_write": True,
            "golden_reference_input_policy_and_verification_reports_are_read_only": True,
            "existing_generated_dut_rtl_is_read_only_for_capability_repair": True,
            "bounded_selected_template_repair_approved": (
                bounded_template_repair_approved()
                if allow_template_repair is None
                else allow_template_repair
            ),
            "semantic_selected_template_repair_approved": (
                semantic_template_repair_approved()
                if allow_template_repair is None
                else allow_template_repair and semantic_template_repair_approved()
            ),
            "template_repair_must_preserve_external_architecture_stage_order_memory_runtime_and_numeric_contracts": True,
            "template_instrumentation_blocks_are_mechanically_non_functional": (
                instrumentation_only_template_pairs is not None
            ),
            "exact_text_replacements_require_unique_anchors": True,
            "board_source_edits_rebind_derived_manifest_hashes": True,
            "prior_real_vcs_failed_board_source_state_is_never_rewritten_or_relaunched": True,
        },
    }
    report_path = out_dir / report_name
    write_json(report_path, report)
    report["path"] = str(report_path)
    return report


def completed_template_instrumentation_cleanup_plan(
    run_dir: Path,
    *,
    framework_template_root: Path | None = None,
) -> dict[str, Any]:
    framework_root = (
        framework_template_root
        or Path.cwd() / "accagent" / "framework" / "templates" / "operator_chisel"
    ).resolve()
    generated_root = (
        run_dir / "generated" / "chisel" / "src" / "main" / "scala" / "spatialaccagent" / "templates"
    ).resolve()
    edits: list[dict[str, Any]] = []
    pair_names: set[str] = set()
    blockers: list[str] = []
    if not generated_root.is_dir():
        return {"status": "not_run", "file_edits": [], "pair_names": [], "blockers": []}
    for generated in sorted(generated_root.glob("*.scala")):
        persistent = framework_root / generated.name
        generated_text = generated.read_text(encoding="utf-8")
        if TEMPLATE_TRACE_BEGIN not in generated_text and TEMPLATE_TRACE_END not in generated_text:
            continue
        if not persistent.is_file():
            blockers.append(f"missing persistent template pair for instrumentation cleanup: {generated.name}")
            continue
        persistent_text = persistent.read_text(encoding="utf-8")
        if persistent_text != generated_text:
            blockers.append(f"instrumented persistent/generated template pair differs: {generated.name}")
            continue
        begin_count = generated_text.count(TEMPLATE_TRACE_BEGIN)
        end_count = generated_text.count(TEMPLATE_TRACE_END)
        blocks = list(TEMPLATE_TRACE_BLOCK_RE.finditer(generated_text))
        if begin_count == 0 or begin_count != end_count or len(blocks) != begin_count:
            blockers.append(f"instrumentation marker blocks are unbalanced: {generated.name}")
            continue
        cleaned = TEMPLATE_TRACE_BLOCK_RE.sub("", generated_text)
        if not cleaned or TEMPLATE_TRACE_BEGIN in cleaned or TEMPLATE_TRACE_END in cleaned:
            blockers.append(f"instrumentation cleanup did not remove only complete marker blocks: {generated.name}")
            continue
        pair_names.add(generated.name)
        for path in (persistent, generated):
            edits.append(
                {
                    "path": str(path),
                    "operation": "replace",
                    "expected_sha256": sha256_file(path),
                    "content": cleaned,
                }
            )
    return {
        "status": "blocked" if blockers else "ready_to_apply" if edits else "not_run",
        "file_edits": edits,
        "pair_names": sorted(pair_names),
        "blockers": blockers,
    }


def cleanup_completed_template_instrumentation(run_dir: Path, out_dir: Path) -> dict[str, Any]:
    plan = completed_template_instrumentation_cleanup_plan(run_dir)
    report_path = out_dir / "completed_template_instrumentation_cleanup.json"
    if plan.get("status") != "ready_to_apply":
        report = {
            "schema_version": "spatialaccagent.completed_template_instrumentation_cleanup.v1",
            "status": plan.get("status"),
            "files": [],
            "blockers": plan.get("blockers", []),
            "summary": (
                "no completed template instrumentation remains"
                if plan.get("status") == "not_run"
                else "completed template instrumentation could not be removed safely"
            ),
        }
        write_json(report_path, report)
        report["path"] = str(report_path)
        return report
    allowed = {
        (Path(str(edit["path"])) if Path(str(edit["path"])).is_absolute() else Path.cwd() / str(edit["path"])).resolve()
        for edit in plan["file_edits"]
    }
    report = apply_agent_file_edits(
        {
            "status": "ready_to_apply",
            "file_edits": plan["file_edits"],
            "requested_validation": [],
            "approval_required_for": [],
        },
        run_dir,
        out_dir,
        allowed_exact_files=allowed,
        required_template_pairs=set(plan["pair_names"]),
        allow_template_repair=True,
        report_name=report_path.name,
    )
    report["summary"] = (
        f"removed completed diagnostic instrumentation from {len(plan['pair_names'])} template pair(s)"
        if report.get("status") == "pass"
        else "completed template instrumentation cleanup failed closed"
    )
    write_json(report_path, {key: value for key, value in report.items() if key != "path"})
    return report


def normalize_harness_sources(
    harness: dict[str, Any],
    run_dir: Path,
) -> tuple[list[dict[str, Any]], str, list[str]]:
    allowed_roots = [
        (run_dir / "generated" / "semantic_harness").resolve(),
        (run_dir / "generated" / "chisel").resolve(),
    ]
    semantic_root = (run_dir / "generated" / "semantic_harness").resolve()
    rows: list[dict[str, Any]] = []
    combined: list[str] = []
    blockers: list[str] = []
    candidates: list[tuple[str, Any]] = []
    source_directory = harness.get("source_directory")
    resolved_source_directory: Path | None = None
    if source_directory:
        directory = Path(str(source_directory))
        if not directory.is_absolute():
            blockers.append(f"source_directory must be absolute: {directory}")
        else:
            directory = directory.resolve()
            if not directory.is_relative_to(semantic_root):
                blockers.append(f"source_directory is outside generated semantic-harness root: {directory}")
            elif not directory.is_dir():
                blockers.append(f"source_directory does not exist after elaboration: {directory}")
            else:
                resolved_source_directory = directory
                for path in sorted(directory.rglob("*")):
                    if path.is_file() and path.suffix.lower() in {".sv", ".v"}:
                        candidates.append(("source_directory", path))
    source_files = harness.get("source_files", [])
    if not isinstance(source_files, list):
        blockers.append("source_files must be a list when supplied")
        source_files = []
    # A successful re-elaboration makes the isolated directory authoritative.
    # Prior source rows may name diagnostic files that were intentionally removed.
    if resolved_source_directory is None:
        for index, item in enumerate(source_files):
            candidates.append((f"source_files[{index}]", item))

    seen_paths: set[Path] = set()
    module_owners: dict[str, Path] = {}
    for label, item in candidates:
        raw = item.get("path") if isinstance(item, dict) else item
        path = Path(str(raw or ""))
        path = path if path.is_absolute() else Path.cwd() / path
        path = path.resolve()
        if path in seen_paths:
            continue
        seen_paths.add(path)
        if resolved_source_directory is not None and not path.is_relative_to(resolved_source_directory):
            blockers.append(
                f"{label} is outside the declared isolated source_directory: {path}"
            )
            continue
        if not any(path.is_relative_to(root) for root in allowed_roots):
            blockers.append(f"{label} is outside generated harness/DUT roots: {path}")
            continue
        if path.suffix.lower() not in {".sv", ".v"} or not path.is_file():
            blockers.append(f"{label} is not an existing Verilog/SystemVerilog file: {path}")
            continue
        try:
            text = path.read_text(encoding="utf-8")
        except (OSError, UnicodeDecodeError) as exc:
            blockers.append(f"cannot read harness source {path}: {exc}")
            continue
        for module in re.findall(r"(?m)^module\s+([A-Za-z_][A-Za-z0-9_$]*)\b", text):
            owner = module_owners.get(module)
            if owner is not None:
                blockers.append(
                    f"stage source set declares module {module} more than once: {owner} and {path}"
                )
            else:
                module_owners[module] = path
        rows.append({"path": str(path), "sha256": sha256_file(path)})
        combined.append(text)
    if not rows:
        blockers.append("harness has no valid source files after source-directory discovery")
    return rows, "\n".join(combined), blockers


def run_agent_requested_validation(
    output: dict[str, Any],
    run_dir: Path,
    out_dir: Path,
    timeout_sec: int,
    *,
    report_name: str = "agent_requested_validation.json",
) -> dict[str, Any]:
    requests = output.get("requested_validation", []) if isinstance(output.get("requested_validation"), list) else []
    generated_root = (run_dir / "generated" / "chisel").resolve()
    validated: list[tuple[list[str], Path, str]] = []
    blockers: list[str] = []
    allowed_flags = {"--no-server", "--batch", "--supershell=false"}
    for index, request in enumerate(requests):
        if not isinstance(request, dict):
            blockers.append(f"requested_validation[{index}] is not an object")
            continue
        argv = [str(value) for value in request.get("argv", [])]
        cwd = Path(str(request.get("cwd") or ""))
        cwd = cwd if cwd.is_absolute() else Path.cwd() / cwd
        cwd = cwd.resolve()
        purpose = str(request.get("purpose") or "")
        if cwd != generated_root:
            blockers.append(f"requested_validation[{index}] cwd is outside the generated Chisel project: {cwd}")
            continue
        if not argv or argv[0] != "sbt":
            blockers.append(f"requested_validation[{index}] may invoke only sbt")
            continue
        goals = [value for value in argv[1:] if value not in allowed_flags]
        if len(goals) != 1:
            blockers.append(f"requested_validation[{index}] must contain exactly one allowed sbt goal")
            continue
        goal = goals[0]
        if goal != "Compile/compile" and not re.fullmatch(
            r"runMain spatialaccagent\.semantic_harness\.[A-Za-z_][A-Za-z0-9_$.]*",
            goal,
        ):
            blockers.append(f"requested_validation[{index}] has disallowed sbt goal: {goal}")
            continue
        if any(value.startswith("-") and value not in allowed_flags for value in argv[1:]):
            blockers.append(f"requested_validation[{index}] has a disallowed sbt option")
            continue
        validated.append((argv, cwd, purpose))

    semantic_root = (run_dir / "generated" / "semantic_harness").resolve()
    declared_output_roots: set[Path] = set()

    def collect_declared_output_roots(value: Any) -> None:
        if isinstance(value, dict):
            source_directory = value.get("source_directory")
            if source_directory:
                path = Path(str(source_directory))
                if path.is_absolute():
                    path = path.resolve()
                    if path != semantic_root and path.is_relative_to(semantic_root):
                        declared_output_roots.add(path)
            for child in value.values():
                collect_declared_output_roots(child)
        elif isinstance(value, list):
            for child in value:
                collect_declared_output_roots(child)

    for edit in output.get("file_edits", []):
        if isinstance(edit, dict):
            collect_declared_output_roots(edit.get("json_content"))

    results = []
    heap_mb: int | None = None
    if not blockers:
        cache_root = (run_dir / "generated" / ".sbt_codegen_cache").resolve()
        sbt_global = cache_root / "sbt"
        sbt_boot = sbt_global / "boot"
        ivy_home = cache_root / "ivy2"
        coursier_cache = cache_root / "coursier"
        for path in (sbt_global, sbt_boot, ivy_home, coursier_cache):
            path.mkdir(parents=True, exist_ok=True)
        env = os.environ.copy()
        heap_mb = configured_sbt_heap_mb(env)
        local_opts = (
            f"-Xms256m -Xmx{heap_mb}m -XX:+UseG1GC "
            f"-Dsbt.global.base={sbt_global} "
            f"-Dsbt.boot.directory={sbt_boot} "
            f"-Dsbt.ivy.home={ivy_home} "
            "-Dsbt.server.autostart=false "
            "-Dsbt.server.forcestart=true"
        )
        env["SBT_OPTS"] = f"{env.get('SBT_OPTS', '')} {local_opts}".strip()
        env.setdefault("COURSIER_CACHE", str(coursier_cache))
        for argv, cwd, purpose in validated:
            cleaned_output_roots: list[str] = []
            if any(
                value.startswith("runMain spatialaccagent.semantic_harness.")
                for value in argv
            ):
                for emitted_root in sorted(declared_output_roots):
                    if emitted_root.exists():
                        shutil.rmtree(emitted_root)
                    emitted_root.mkdir(parents=True)
                    cleaned_output_roots.append(str(emitted_root))
            result = run_local_tool(argv, cwd, env, timeout_sec)
            results.append(
                {
                    "purpose": purpose,
                    "argv": argv,
                    "cwd": str(cwd),
                    "cleaned_output_root": (
                        cleaned_output_roots[0]
                        if len(cleaned_output_roots) == 1
                        else None
                    ),
                    "cleaned_output_roots": cleaned_output_roots,
                    **result,
                }
            )
            if result.get("status") != "pass":
                blockers.append(f"requested validation failed: {purpose or argv}")
                break

    report = {
        "schema_version": "spatialaccagent.agent_requested_validation.v1",
        "status": "pass" if not blockers else "fail",
        "requests": len(requests),
        "sbt_heap_mb": heap_mb,
        "results": results,
        "blockers": blockers,
    }
    report_path = out_dir / report_name
    write_json(report_path, report)
    report["path"] = str(report_path)
    return report


RESOURCE_FAILURE_PATTERNS = (
    "java.lang.OutOfMemoryError",
    "Cannot allocate memory",
    "GC overhead limit exceeded",
)


def validation_resource_failure(report: dict[str, Any]) -> str | None:
    for result in report.get("results", []):
        if not isinstance(result, dict):
            continue
        output = f"{result.get('stdout_tail', '')}\n{result.get('stderr_tail', '')}"
        for pattern in RESOURCE_FAILURE_PATTERNS:
            if pattern in output:
                return pattern
    return None


def validation_passed_goals(report: dict[str, Any]) -> set[str]:
    goals: set[str] = set()
    for result in report.get("results", []):
        if not isinstance(result, dict) or result.get("status") != "pass":
            continue
        for value in result.get("argv", []):
            goal = str(value)
            if goal == "Compile/compile" or goal.startswith(
                "runMain spatialaccagent.semantic_harness."
            ):
                goals.add(goal)
    return goals


def mandatory_localized_template_validation(
    patch_report: dict[str, Any],
    run_dir: Path,
    step: dict[str, Any] | None,
) -> tuple[list[dict[str, Any]], list[str], bool]:
    """Recover executor-mandated compile/elaboration for an applied template patch."""

    policy = (
        patch_report.get("policy", {})
        if isinstance(patch_report.get("policy"), dict)
        else {}
    )
    if (
        step is None
        or policy.get("semantic_selected_template_repair_approved") is not True
        or policy.get(
            "template_instrumentation_blocks_are_mechanically_non_functional"
        )
        is True
    ):
        return [], [], False
    framework_template_root = (
        Path.cwd() / "accagent" / "framework" / "templates" / "operator_chisel"
    ).resolve()
    generated_template_root = (
        run_dir
        / "generated"
        / "chisel"
        / "src"
        / "main"
        / "scala"
        / "spatialaccagent"
        / "templates"
    ).resolve()
    template_edit_present = False
    for row in patch_report.get("files", []):
        if not isinstance(row, dict):
            continue
        try:
            path = Path(str(row.get("path") or "")).resolve()
        except OSError:
            continue
        if path.suffix == ".scala" and (
            path.is_relative_to(framework_template_root)
            or path.is_relative_to(generated_template_root)
        ):
            template_edit_present = True
            break
    if not template_edit_present:
        return [], [], False
    verification_scope = verification_scope_for_step(step)
    normalized, errors = semantic_harness_validation_output(
        {
            "requested_validation": patch_report.get(
                "requested_validation", []
            )
        },
        run_dir,
        require_elaboration=True,
        required_elaboration_main=(
            SEMANTIC_HARNESS_ELABORATION_MAIN_BY_SCOPE.get(verification_scope)
        ),
    )
    return normalized.get("requested_validation", []), errors, True


def applied_patch_matches_repair_step(
    patch_report: dict[str, Any],
    step: dict[str, Any] | None,
) -> bool:
    if step is None:
        return True
    expected = repair_step_checkpoint(step)
    recorded = (
        patch_report.get("repair_checkpoint", {})
        if isinstance(patch_report.get("repair_checkpoint"), dict)
        else {}
    )
    if recorded:
        if recorded.get("fingerprint_sha256") == expected.get("fingerprint_sha256"):
            return True

        action = step.get("action", {}) if isinstance(step.get("action"), dict) else {}
        policy = (
            patch_report.get("policy", {})
            if isinstance(patch_report.get("policy"), dict)
            else {}
        )
        files = [
            row for row in patch_report.get("files", []) if isinstance(row, dict)
        ]
        file_names = [Path(str(row.get("path") or "")).name for row in files]
        paired_template_files = bool(files) and all(
            name.endswith(".scala") and file_names.count(name) == 2
            for name in file_names
        )
        common_dynamic_route = bool(
            action.get("repair_kind") == "case_single_layer_functional"
            and action.get("repair_gate") == "case_single_layer_functional"
            and str(action.get("debug_layer") or step.get("debug_layer") or "")
            == "single_transformer_layer_kernel"
            and recorded.get("repair_kind") == "localized_semantic_dut_repair"
            and recorded.get("repair_phase") == "functional_repair"
            and recorded.get("module") == "pipeline_candidate_set"
            and recorded.get("step_id") == expected.get("step_id")
            and recorded.get("scope") == expected.get("scope")
            and recorded.get("violated_contract")
            == expected.get("violated_contract")
            and bool(recorded.get("stage_id"))
            and policy.get("semantic_selected_template_repair_approved") is True
            and policy.get(
                "template_instrumentation_blocks_are_mechanically_non_functional"
            )
            is False
            and paired_template_files
        )
        if not common_dynamic_route:
            return False

        source_checkpoint = str(
            recorded.get("source_repair_checkpoint_fingerprint_sha256") or ""
        )
        if recorded.get("dynamic_source_bound_route") is True:
            return bool(
                source_checkpoint == expected.get("fingerprint_sha256")
                and re.fullmatch(
                    r"[0-9a-f]{64}",
                    str(recorded.get("source_bound_failure_identity_sha256") or ""),
                )
                and re.fullmatch(
                    r"[0-9a-f]{64}",
                    str(recorded.get("source_bound_input_fingerprint_sha256") or ""),
                )
            )

        # One-time compatibility for the last v1 completed-overlap patch, which
        # predates explicit source-checkpoint binding but is otherwise exact.
        return recorded.get("schema_version") == "spatialaccagent.repair_step_checkpoint.v1"

    # Compatibility for an instrumentation patch applied before checkpoint v1 existed.
    action = step.get("action", {}) if isinstance(step.get("action"), dict) else {}
    policy = patch_report.get("policy", {}) if isinstance(patch_report.get("policy"), dict) else {}
    files = [row for row in patch_report.get("files", []) if isinstance(row, dict)]
    names = {Path(str(row.get("path") or "")).name for row in files}
    module = str(expected.get("module") or "")
    if not (
        action.get("repair_kind") == "localized_semantic_dut_repair"
        and policy.get("template_instrumentation_blocks_are_mechanically_non_functional") is True
        and len(files) == 2
        and len(names) == 1
        and next(iter(names), "").endswith(".scala")
        and module
    ):
        return False
    for row in files:
        path = Path(str(row.get("path") or ""))
        if not path.is_file():
            return False
        source = path.read_text(encoding="utf-8")
        if (
            TEMPLATE_TRACE_BEGIN not in source
            or re.search(rf"(?m)^\s*class\s+{re.escape(module)}\b", source) is None
        ):
            return False
    return True


def resume_prior_resource_failed_validation(
    run_dir: Path,
    out_dir: Path,
    timeout_sec: int,
    *,
    step: dict[str, Any] | None = None,
    case_adapter: dict[str, Any] | None = None,
) -> dict[str, Any]:
    validation_path = out_dir / "agent_requested_validation.json"
    resume_path = out_dir / "agent_requested_validation_resource_resume.json"
    patch_path = out_dir / "agent_patch_application.json"
    prior_patch = read_json_if_exists(patch_path)
    patch_fingerprint = sha256_file(patch_path) if patch_path.is_file() else ""
    if prior_patch and not applied_patch_matches_repair_step(prior_patch, step):
        return {
            "status": "not_run",
            "summary": "prior applied patch belongs to a different repair step",
        }
    (
        mandatory_validation_requests,
        mandatory_validation_errors,
        mandatory_validation_applies,
    ) = mandatory_localized_template_validation(prior_patch, run_dir, step)
    if mandatory_validation_errors:
        return {
            "status": "blocked",
            "summary": (
                "applied localized template patch cannot satisfy its mandatory "
                "compile/elaboration contract"
            ),
            "blockers": mandatory_validation_errors,
        }

    def request_goal(request: dict[str, Any]) -> str | None:
        for value in request.get("argv", []):
            goal = str(value)
            if goal == "Compile/compile" or goal.startswith(
                "runMain spatialaccagent.semantic_harness."
            ):
                return goal
        return None

    def missing_mandatory_requests(
        *reports: dict[str, Any],
    ) -> list[dict[str, Any]]:
        if not mandatory_validation_applies:
            return []
        passed_goals: set[str] = set()
        for report in reports:
            passed_goals.update(validation_passed_goals(report))
        return [
            request
            for request in mandatory_validation_requests
            if request_goal(request) not in passed_goals
        ]

    def finalized_binding_manifest_attests(row: dict[str, Any]) -> bool:
        canonical_manifest = (
            run_dir / "generated" / "memory" / "dut_weight_binding_manifest.json"
        ).resolve()
        requirements_path = (
            run_dir
            / "verification"
            / "semantic_testbench"
            / "dut_weight_binding_requirements.json"
        ).resolve()
        materialization_path = out_dir / "dut_weight_binding_materialization.json"
        expected_agent_sha = str(row.get("after_sha256") or "")
        try:
            row_path = Path(str(row.get("path") or "")).resolve()
        except OSError:
            return False
        if (
            row_path != canonical_manifest
            or not expected_agent_sha
            or not canonical_manifest.is_file()
            or not requirements_path.is_file()
            or not materialization_path.is_file()
            or not validation_path.is_file()
            or not patch_path.is_file()
            or not (
                materialization_path.stat().st_mtime_ns
                >= validation_path.stat().st_mtime_ns
                >= patch_path.stat().st_mtime_ns
            )
        ):
            return False

        report = read_json_if_exists(materialization_path)
        manifest = read_json_if_exists(canonical_manifest)
        materialization = (
            manifest.get("materialization", {})
            if isinstance(manifest.get("materialization"), dict)
            else {}
        )
        expected_scope = verification_scope_for_step(step) if step is not None else ""
        report_blockers = [
            str(value) for value in report.get("blockers", []) if str(value)
        ]
        manifest_blockers = [
            str(value)
            for value in manifest.get("materialization_blockers", [])
            if str(value)
        ]
        pass_attestation = (
            report.get("status") == "pass"
            and not report_blockers
            and manifest.get("status") == "pass"
            and not manifest_blockers
        )
        stage_requirements = [
            value
            for value in read_json_if_exists(requirements_path).get(
                "stage_requirements", []
            )
            if isinstance(value, dict)
        ]
        board_only_incomplete_attestation = (
            expected_scope == "board_axi_ddr_closure"
            and report.get("status") == "incomplete"
            and manifest.get("status") == "incomplete"
            and bool(report_blockers)
            and report_blockers == manifest_blockers
            and all(
                value.startswith(("board_integration:", "board_preflight:"))
                for value in report_blockers
            )
            and report.get("single_layer_harness_materialized") is True
            and report.get("stage_harness_count") == len(stage_requirements)
        )
        try:
            report_manifest = Path(str(report.get("manifest") or "")).resolve()
            reported_requirements = Path(str(materialization.get("requirements") or "")).resolve()
        except OSError:
            return False
        if (
            report.get("schema_version")
            != "spatialaccagent.dut_weight_binding_materialization.v1"
            or not (pass_attestation or board_only_incomplete_attestation)
            or report_manifest != canonical_manifest
            or report.get("manifest_sha256") != sha256_file(canonical_manifest)
            or materialization.get("source")
            != "agent_file_edits_plus_framework_hash_validation"
            or reported_requirements != requirements_path
            or materialization.get("requirements_sha256") != sha256_file(requirements_path)
            or not expected_scope
            or materialization.get("verification_scope") != expected_scope
            or (
                expected_scope == "single_layer_closure"
                and report.get("single_layer_harness_materialized") is not True
            )
            or (
                expected_scope == "board_axi_ddr_closure"
                and pass_attestation
                and report.get("board_integration_harness_materialized") is not True
            )
        ):
            return False

        provenance_fields = {
            "source_patch_application",
            "source_patch_application_sha256",
            "source_agent_manifest",
            "source_agent_manifest_sha256",
        }
        current_manifest_sha = sha256_file(canonical_manifest)
        if current_manifest_sha != expected_agent_sha and not provenance_fields.issubset(
            report
        ):
            return False
        if provenance_fields.intersection(report):
            if not provenance_fields.issubset(report):
                return False
            try:
                source_patch = Path(str(report.get("source_patch_application") or "")).resolve()
                source_manifest = Path(str(report.get("source_agent_manifest") or "")).resolve()
            except OSError:
                return False
            if (
                source_patch != patch_path.resolve()
                or report.get("source_patch_application_sha256") != patch_fingerprint
                or source_manifest != canonical_manifest
                or report.get("source_agent_manifest_sha256") != expected_agent_sha
            ):
                return False
        return True

    def patch_blockers() -> list[str]:
        blockers: list[str] = []
        for row in prior_patch.get("files", []):
            if not isinstance(row, dict):
                continue
            path = Path(str(row.get("path") or ""))
            expected = str(row.get("after_sha256") or "")
            exact_patch_file = path.is_file() and bool(expected) and sha256_file(path) == expected
            if not exact_patch_file and not finalized_binding_manifest_attests(row):
                blockers.append(f"prior agent patch file changed before resource resume: {path}")
        return blockers

    prior_validation = read_json_if_exists(validation_path)
    validation_is_current = (
        validation_path.is_file()
        and patch_path.is_file()
        and validation_path.stat().st_mtime_ns >= patch_path.stat().st_mtime_ns
    )
    patch_is_applied = (
        prior_patch.get("status") == "pass"
        and isinstance(prior_patch.get("files"), list)
        and bool(prior_patch.get("files"))
    )
    board_validation_owned_by_framework = bool(
        step is not None
        and verification_scope_for_step(step) == "board_axi_ddr_closure"
    )
    board_gate = read_json_if_exists(
        out_dir / "board_semantic_rtl_single_layer_gate.json"
    )
    applied_board_semantic_gate_needs_resume = bool(
        patch_is_applied
        and board_validation_owned_by_framework
        and all_applied_semantic_source_hash_changes(prior_patch, run_dir)
        and board_gate.get("status") != "pass"
    )
    if (
        patch_is_applied
        and board_validation_owned_by_framework
        and (
            not validation_is_current
            or prior_validation.get("status") != "pass"
            or applied_board_semantic_gate_needs_resume
        )
    ):
        source_changes = all_applied_semantic_source_hash_changes(
            prior_patch,
            run_dir,
        )
        if source_changes:
            if case_adapter is None:
                return {
                    "status": "blocked",
                    "summary": (
                        "an interrupted board semantic RTL patch requires the "
                        "single-layer gate, but no case adapter is available"
                    ),
                    "blockers": [
                        "case adapter is required to resume a board semantic RTL patch"
                    ],
                }
            manifest_rebind = rebind_applied_semantic_source_manifests(
                run_dir,
                source_changes,
            )
            if manifest_rebind.get("status") != "pass":
                return {
                    "status": "blocked",
                    "summary": (
                        "interrupted board semantic RTL patch could not safely "
                        "rebind its shared semantic source manifests"
                    ),
                    "blockers": manifest_rebind.get("blockers", []),
                    "source_manifest_rebind": manifest_rebind,
                }
            if reuse_existing_single_layer_gate_for_board_repair(run_dir):
                gate_path = out_dir / "board_semantic_rtl_single_layer_gate.json"
                gate = {
                    "status": "pass",
                    "summary": (
                        "reused the existing passed single-layer prerequisite; "
                        "continued directly to the current third-layer board run"
                    ),
                    "board_vcs_started": False,
                    "reused_existing_certificate": True,
                    "verification_layer": "layer2_connected_single_transformer",
                }
                write_json(gate_path, gate)
                gate["gate_path"] = str(gate_path)
            else:
                gate = run_board_semantic_rtl_single_layer_gate(
                    case_adapter=case_adapter,
                    run_dir=run_dir,
                    step=step,
                    out_dir=out_dir,
                    timeout_sec=timeout_sec,
                )
            if gate.get("status") != "pass":
                return {
                    "status": "fail",
                    "summary": (
                        "interrupted board semantic RTL patch did not pass the "
                        "connected single-layer functional gate; exact-board VCS "
                        "was not started"
                    ),
                    "blockers": [str(gate.get("summary") or "single-layer gate failed")],
                    "source_manifest_rebind": manifest_rebind,
                    "board_semantic_rtl_single_layer_gate": gate,
                    "framework_action_required": (
                        "return the connected single-layer failure to the same RTL "
                        "Agent before any exact-board replay"
                    ),
                }
            return {
                "status": "pass",
                "summary": (
                    "rebound shared semantic source manifests and passed the "
                    "mandatory connected single-layer gate for the interrupted "
                    "board semantic RTL patch"
                ),
                "results": [],
                "blockers": [],
                "source_manifest_rebind": manifest_rebind,
                "board_semantic_rtl_single_layer_gate": gate,
                "force_board_manifest_finalization": True,
                "source_patch_application": str(patch_path),
                "source_patch_application_sha256": patch_fingerprint,
            }
        report = run_agent_requested_validation(
            {"requested_validation": []},
            run_dir,
            out_dir,
            timeout_sec,
        )
        report["summary"] = (
            "board Agent validation suggestions are owned by the mandatory "
            "preflight, real VCS, and analyzer chain"
        )
        return report
    existing_resume = read_json_if_exists(resume_path)
    existing_blockers = patch_blockers()
    if (
        existing_resume.get("status") == "pass"
        and existing_resume.get("source_patch_application_sha256") == patch_fingerprint
        and validation_resource_failure(existing_resume) is None
        and not existing_blockers
        and not missing_mandatory_requests(
            prior_validation if validation_is_current else {},
            existing_resume,
        )
    ):
        return {
            **existing_resume,
            "path": str(resume_path),
            "cache_reused": True,
            "summary": "reused passing resource-resumed validation for unchanged agent patch files",
        }

    if patch_is_applied and not validation_is_current:
        requests = (
            mandatory_validation_requests
            if mandatory_validation_applies
            else prior_patch.get("requested_validation", [])
        )
        blockers = list(existing_blockers)
        if not isinstance(requests, list):
            blockers.append("interrupted agent patch requested_validation is not a list")
        if blockers:
            return {
                "status": "blocked",
                "summary": "interrupted agent validation cannot be resumed safely",
                "blockers": blockers,
            }
        report = run_agent_requested_validation(
            {"requested_validation": requests},
            run_dir,
            out_dir,
            timeout_sec,
            report_name=resume_path.name,
        )
        report.update(
            {
                "resource_resume": True,
                "resource_failure_pattern": "interrupted_before_validation_report",
                "source_validation": str(validation_path),
                "source_patch_application": str(patch_path),
                "source_patch_application_sha256": patch_fingerprint,
            }
        )
        write_json(Path(str(report["path"])), {key: value for key, value in report.items() if key != "path"})
        return report

    if (
        patch_is_applied
        and validation_is_current
        and prior_validation.get("status") == "pass"
        and not existing_blockers
    ):
        missing_requests = missing_mandatory_requests(prior_validation)
        if missing_requests:
            report = run_agent_requested_validation(
                {"requested_validation": missing_requests},
                run_dir,
                out_dir,
                timeout_sec,
                report_name=resume_path.name,
            )
            report.update(
                {
                    "resource_resume": True,
                    "resource_failure_pattern": (
                        "mandatory_template_elaboration_contract_upgrade"
                    ),
                    "source_validation": str(validation_path),
                    "source_patch_application": str(patch_path),
                    "source_patch_application_sha256": patch_fingerprint,
                    "mandatory_validation_goals": [
                        request_goal(request)
                        for request in mandatory_validation_requests
                    ],
                }
            )
            write_json(
                Path(str(report["path"])),
                {key: value for key, value in report.items() if key != "path"},
            )
            return report
        return {
            **prior_validation,
            "path": str(validation_path),
            "cache_reused": True,
            "applied_patch_checkpoint_reused": True,
            "source_patch_application": str(patch_path),
            "source_patch_application_sha256": patch_fingerprint,
            "repair_checkpoint": repair_step_checkpoint(step) if step is not None else None,
            "summary": "reused passing validation for the unchanged applied repair-step patch",
        }

    resource_pattern = validation_resource_failure(prior_validation)
    if resource_pattern is None:
        if existing_blockers:
            return {
                "status": "blocked",
                "summary": "prior applied patch files changed without a trusted framework finalization",
                "blockers": existing_blockers,
            }
        return {
            "status": "not_run",
            "summary": "prior capability validation has no resumable tool-resource failure",
        }
    blockers = existing_blockers
    requests = (
        mandatory_validation_requests
        if mandatory_validation_applies
        else prior_patch.get("requested_validation", [])
    )
    if not isinstance(requests, list):
        blockers.append("prior agent patch requested_validation is not a list")
    if blockers:
        return {
            "status": "blocked",
            "summary": "prior tool-resource failure cannot be resumed safely",
            "resource_failure_pattern": resource_pattern,
            "blockers": blockers,
        }
    report = run_agent_requested_validation(
        {"requested_validation": requests},
        run_dir,
        out_dir,
        timeout_sec,
        report_name=resume_path.name,
    )
    report.update(
        {
            "resource_resume": True,
            "resource_failure_pattern": resource_pattern,
            "source_validation": str(validation_path),
            "source_patch_application": str(patch_path),
            "source_patch_application_sha256": patch_fingerprint,
        }
    )
    write_json(Path(str(report["path"])), {key: value for key, value in report.items() if key != "path"})
    return report


def has_interface_data_identity_path(
    source_text: str,
    input_data_ports: set[str],
    output_data_port: str,
) -> bool:
    """Return whether simple Verilog aliases directly bypass a DUT data path."""

    if not input_data_ports or not output_data_port:
        return False
    assignments: dict[str, set[str]] = {}
    patterns = (
        re.compile(
            r"(?im)^\s*assign\s+([A-Za-z_][A-Za-z0-9_$]*)\s*=\s*"
            r"([A-Za-z_][A-Za-z0-9_$]*)\s*;"
        ),
        re.compile(
            r"(?im)^\s*(?:wire|logic)\s+(?:\[[^\]\r\n]+\]\s*)?"
            r"([A-Za-z_][A-Za-z0-9_$]*)\s*=\s*"
            r"([A-Za-z_][A-Za-z0-9_$]*)\s*;"
        ),
    )
    for pattern in patterns:
        for match in pattern.finditer(source_text):
            destination, source = match.groups()
            assignments.setdefault(source, set()).add(destination)

    pending = list(input_data_ports)
    visited: set[str] = set()
    while pending:
        source = pending.pop()
        if source in visited:
            continue
        visited.add(source)
        for destination in assignments.get(source, set()):
            if destination == output_data_port:
                return True
            pending.append(destination)
    return False


def harness_contract_errors(
    harness: dict[str, Any],
    required_hashes: set[str],
    expected_layout_hash: str,
    expected_runtime_hash: str,
    run_dir: Path,
    generated_modules: set[str],
) -> tuple[dict[str, Any], list[str]]:
    normalized = dict(harness)
    source_rows, source_text, blockers = normalize_harness_sources(harness, run_dir)
    normalized["source_files"] = source_rows
    top_module = str(harness.get("top_module") or "")
    top_sources: list[Path] = []
    for row in source_rows:
        path = Path(str(row["path"]))
        text = path.read_text(encoding="utf-8")
        if top_module and re.search(rf"(?m)^module\s+{re.escape(top_module)}\b", text):
            top_sources.append(path)
    if not top_module or not top_sources:
        blockers.append(f"harness top module is not declared by its source files: {top_module or '<missing>'}")
    wrapper_text = "\n".join(path.read_text(encoding="utf-8") for path in top_sources)
    top_port_text = ""
    if wrapper_text and top_module:
        declaration = re.search(rf"(?m)^module\s+{re.escape(top_module)}\b", wrapper_text)
        if declaration:
            cursor = declaration.end()

            def balanced_parentheses(start: int) -> tuple[str, int]:
                depth = 0
                for index in range(start, len(wrapper_text)):
                    char = wrapper_text[index]
                    if char == "(":
                        depth += 1
                    elif char == ")":
                        depth -= 1
                        if depth == 0:
                            return wrapper_text[start + 1 : index], index + 1
                return "", start

            while cursor < len(wrapper_text) and wrapper_text[cursor].isspace():
                cursor += 1
            if cursor < len(wrapper_text) and wrapper_text[cursor] == "#":
                cursor += 1
                while cursor < len(wrapper_text) and wrapper_text[cursor].isspace():
                    cursor += 1
                _, cursor = balanced_parentheses(cursor)
                while cursor < len(wrapper_text) and wrapper_text[cursor].isspace():
                    cursor += 1
            if cursor < len(wrapper_text) and wrapper_text[cursor] == "(":
                top_port_text, _ = balanced_parentheses(cursor)
    if top_sources and not top_port_text:
        blockers.append(f"semantic harness top-module port list could not be parsed: {top_module}")
    instantiated = [
        module
        for module in generated_modules
        if re.search(rf"\b{re.escape(module)}\s+(?:#\s*\([^;]*?\)\s*)?[A-Za-z_][A-Za-z0-9_$]*\s*\(", wrapper_text, re.DOTALL)
    ]
    if not instantiated:
        blockers.append("semantic harness does not instantiate a generated DUT module")
    declared_modules = set(
        re.findall(r"(?m)^module\s+([A-Za-z_][A-Za-z0-9_$]*)\b", source_text)
    )
    missing_instantiated_sources = sorted(set(instantiated) - declared_modules)
    if missing_instantiated_sources:
        blockers.append(
            "semantic harness source set is not self-contained for generated DUT modules: "
            + str(missing_instantiated_sources)
        )
    normalized["generated_dut_modules"] = sorted(instantiated)
    if re.search(r"\$readmem|expected\.memh|model_reference|golden", wrapper_text, re.IGNORECASE):
        blockers.append("semantic harness source attempts to read or reference expected/golden data")
    interface = harness.get("interface", {}) if isinstance(harness.get("interface"), dict) else {}
    inputs = interface.get("inputs", []) if isinstance(interface.get("inputs"), list) else []
    output = interface.get("output", {}) if isinstance(interface.get("output"), dict) else {}
    input_data_ports = {
        str(port.get("data_port"))
        for port in inputs
        if isinstance(port, dict) and port.get("data_port")
    }
    if has_interface_data_identity_path(
        wrapper_text,
        input_data_ports,
        str(output.get("data_port") or ""),
    ):
        blockers.append("semantic harness contains a direct input-to-output identity bypass")

    def missing(value: Any) -> bool:
        return value is None or value == "" or value == 0

    def require_declared_port(value: Any, label: str) -> None:
        port = str(value or "")
        if port and top_port_text and not re.search(rf"\b{re.escape(port)}\b", top_port_text):
            blockers.append(f"semantic harness top module does not declare {label}: {port}")

    for name in ("clock_port", "reset_port"):
        port = str(interface.get(name) or "")
        if not port or not top_port_text or not re.search(rf"\b{re.escape(port)}\b", top_port_text):
            blockers.append(f"semantic harness interface is missing connected {name}: {port or '<missing>'}")
    if not inputs:
        blockers.append("semantic harness interface has no input stream")
    for index, port in enumerate(inputs):
        if not isinstance(port, dict):
            blockers.append(f"semantic harness input {index} is not an object")
            continue
        for name in ("valid_port", "ready_port", "data_port", "data_width_bits"):
            value = port.get(name)
            if missing(value):
                blockers.append(f"semantic harness input {index} is missing {name}")
            elif name.endswith("_port"):
                require_declared_port(value, f"input {index} {name}")
        if not missing(port.get("last_port")):
            require_declared_port(port.get("last_port"), f"input {index} last_port")
    for name in ("valid_port", "ready_port", "data_port", "data_width_bits"):
        if missing(output.get(name)):
            blockers.append(f"semantic harness output is missing {name}")
        elif name.endswith("_port"):
            require_declared_port(output.get(name), f"output {name}")
    if not missing(output.get("last_port")):
        require_declared_port(output.get("last_port"), "output last_port")
    if not missing(interface.get("start_port")):
        require_declared_port(interface.get("start_port"), "start_port")
    for index, constant in enumerate(interface.get("constant_ports", [])):
        if not isinstance(constant, dict):
            blockers.append(f"semantic harness constant port {index} is not an object")
            continue
        if missing(constant.get("port")):
            blockers.append(f"semantic harness constant port {index} is missing port")
        else:
            require_declared_port(constant.get("port"), f"constant port {index}")

    consumed = {str(value) for value in harness.get("consumed_tensor_hashes", []) if str(value)}
    missing_hashes = sorted(required_hashes - consumed)
    if missing_hashes:
        blockers.append(f"semantic harness is missing {len(missing_hashes)} required tensor hash(es)")
    normalized["consumed_tensor_hashes"] = sorted(consumed)
    if required_hashes:
        if harness.get("weight_layout_contract_sha256") != expected_layout_hash:
            blockers.append("weighted semantic harness does not bind the required weight-layout contract hash")
        if harness.get("default_or_identity_weight_fallback_disabled") is not True:
            blockers.append("weighted semantic harness does not disable default/identity fallback")
        loader = interface.get("weight_loader", {}) if isinstance(interface.get("weight_loader"), dict) else {}
        for name in (
            "valid_port",
            "ready_port",
            "data_port",
            "data_width_bits",
            "addr_port",
            "addr_width_bits",
            "last_port",
        ):
            if missing(loader.get(name)):
                blockers.append(f"weighted semantic harness loader is missing {name}")
            elif name.endswith("_port"):
                require_declared_port(loader.get(name), f"weight loader {name}")
        if loader.get("data_width_bits") not in {32, "32"}:
            blockers.append("weighted semantic harness loader data width must be 32 bits")
    if expected_runtime_hash:
        if harness.get("runtime_constant_contract_sha256") != expected_runtime_hash:
            blockers.append("semantic harness does not bind the required runtime-constant contract hash")
        runtime_loader = interface.get("runtime_loader", {}) if isinstance(interface.get("runtime_loader"), dict) else {}
        for name in (
            "valid_port",
            "ready_port",
            "data_port",
            "data_width_bits",
            "addr_port",
            "addr_width_bits",
            "last_port",
        ):
            if missing(runtime_loader.get(name)):
                blockers.append(f"runtime-constant semantic harness loader is missing {name}")
            elif name.endswith("_port"):
                require_declared_port(runtime_loader.get(name), f"runtime loader {name}")
        if runtime_loader.get("data_width_bits") not in {32, "32"}:
            blockers.append("runtime-constant semantic harness loader data width must be 32 bits")
        normalized["runtime_constant_contract_sha256"] = expected_runtime_hash
    return normalized, blockers


def connected_harness_contract_errors(
    harness: dict[str, Any],
    requirements: dict[str, Any],
    run_dir: Path,
    generated_modules: set[str],
) -> tuple[dict[str, Any], list[str]]:
    weight_contract = (
        requirements.get("connected_weight_stream_contract", {})
        if isinstance(requirements.get("connected_weight_stream_contract"), dict)
        else {}
    )
    runtime_contract = (
        requirements.get("connected_runtime_stream_contract", {})
        if isinstance(requirements.get("connected_runtime_stream_contract"), dict)
        else {}
    )
    overlap_contract = (
        requirements.get("single_layer_pipeline_overlap_contract", {})
        if isinstance(requirements.get("single_layer_pipeline_overlap_contract"), dict)
        else {}
    )
    required_hashes = {
        str(row.get("sha256"))
        for row in requirements.get("single_layer_required_tensors", [])
        if isinstance(row, dict) and row.get("sha256")
    }
    weight_hash = str(weight_contract.get("contract_sha256") or "")
    runtime_hash = str(runtime_contract.get("contract_sha256") or "")
    normalized, blockers = harness_contract_errors(
        harness,
        required_hashes,
        weight_hash,
        runtime_hash,
        run_dir,
        generated_modules,
    )
    if not weight_hash or weight_contract.get("status") != "pass":
        blockers.append("connected canonical weight-stream contract is not ready")
    if not runtime_hash or runtime_contract.get("status") != "pass":
        blockers.append("connected canonical runtime-stream contract is not ready")
    trace_contract_hash = str(
        overlap_contract.get("trace_contract_sha256")
        or overlap_contract.get("contract_sha256")
        or ""
    )
    expected_fields = {
        "connected_weight_stream_contract_sha256": weight_hash,
        "connected_runtime_stream_contract_sha256": runtime_hash,
        "pipeline_plan_sha256": requirements.get("pipeline_plan_sha256"),
    }
    for field, expected in expected_fields.items():
        if not expected or harness.get(field) != expected:
            blockers.append(f"connected semantic harness does not bind required {field}")
        else:
            normalized[field] = expected
    compatible_trace_contracts = {
        str(value)
        for value in overlap_contract.get("compatible_trace_contract_sha256s", [])
        if str(value)
    }
    compatible_trace_contracts.add(trace_contract_hash)
    if (
        not trace_contract_hash
        or str(harness.get("pipeline_overlap_trace_contract_sha256") or "")
        not in compatible_trace_contracts
    ):
        blockers.append(
            "connected semantic harness does not bind required pipeline_overlap_trace_contract_sha256"
        )
    else:
        normalized["pipeline_overlap_trace_contract_sha256"] = trace_contract_hash
    blockers.extend(connected_loader_route_errors(harness, weight_contract, runtime_contract))
    route_contract = (
        harness.get("loader_route_contract", {})
        if isinstance(harness.get("loader_route_contract"), dict)
        else {}
    )
    normalized["loader_route_contract"] = route_contract
    normalized["loader_route_contract_sha256"] = hashlib.sha256(
        json.dumps(route_contract, sort_keys=True, separators=(",", ":")).encode("utf-8")
    ).hexdigest()
    return normalized, blockers


def _attested_exact_board_generation_provenance(
    harness: dict[str, Any],
    source_provenance: dict[str, Any],
) -> dict[str, Any] | None:
    existing = harness.get("generation_provenance")
    existing = existing if isinstance(existing, dict) else {}
    if (
        existing.get("mode") != "llm"
        or existing.get("agent_id") != EXACT_BOARD_GENERATION_AGENT
        or existing.get("used_fallback") is not False
        or not existing.get("model")
    ):
        return None

    # A board-generation turn may legitimately select only runtime observation
    # signals. Such a turn has no source patch to attest, but its immutable
    # result/prompt pair is still sufficient to retain the original non-
    # fallback LLM provenance. The board source closure is independently
    # rematerialized and checked by the normal compile-plan path.
    if source_provenance.get("attestation") == "archived_generation_record":
        archived_record_path = Path(
            str(source_provenance.get("archived_generation_record") or "")
        )
        archived_prompt_path = Path(
            str(source_provenance.get("archived_generation_prompt") or "")
        )
        source_record_path = Path(
            str(source_provenance.get("source_generation_record") or "")
        )
        source_prompt_path = Path(
            str(source_provenance.get("source_generation_prompt") or "")
        )
        record_sha256 = str(
            source_provenance.get("archived_generation_record_sha256") or ""
        )
        prompt_sha256 = str(
            source_provenance.get("archived_generation_prompt_sha256") or ""
        )
        if (
            not archived_record_path.is_file()
            or not archived_prompt_path.is_file()
            or not source_record_path.is_absolute()
            or not source_prompt_path.is_absolute()
            or record_sha256 != str(existing.get("record_sha256") or "")
            or prompt_sha256 != str(existing.get("prompt_sha256") or "")
            or sha256_file(archived_record_path) != record_sha256
            or sha256_file(archived_prompt_path) != prompt_sha256
        ):
            return None
        trusted = trusted_exact_board_generation_record(
            archived_record_path,
            expected_agent=EXACT_BOARD_GENERATION_AGENT,
            expected_status="ready_to_apply",
            source_result_path=source_record_path,
            bound_prompt_path=archived_prompt_path,
            source_prompt_path=source_prompt_path,
        )
        if (
            trusted.get("status") != "pass"
            or read_json_if_exists(archived_record_path).get("model")
            != existing.get("model")
        ):
            return None
        return {
            "mode": "llm",
            "agent_id": EXACT_BOARD_GENERATION_AGENT,
            "model": existing["model"],
            "used_fallback": False,
            "prompt_sha256": prompt_sha256,
            "prompt_path": str(archived_prompt_path),
            "record_path": str(archived_record_path),
            "record_sha256": record_sha256,
            "attestation": "archived_generation_record",
        }

    patch_path = Path(str(source_provenance.get("source_patch_application") or ""))
    manifest_path = Path(str(source_provenance.get("source_agent_manifest") or ""))
    patch_sha256 = str(
        source_provenance.get("source_patch_application_sha256") or ""
    )
    manifest_sha256 = str(source_provenance.get("source_agent_manifest_sha256") or "")
    if (
        not patch_path.is_file()
        or not manifest_path.is_absolute()
        or not re.fullmatch(r"[0-9a-f]{64}", patch_sha256)
        or not re.fullmatch(r"[0-9a-f]{64}", manifest_sha256)
        or sha256_file(patch_path) != patch_sha256
    ):
        return None

    patch_report = read_json_if_exists(patch_path)
    if patch_report.get("status") != "pass" or patch_report.get("blockers") != []:
        return None
    patch_attests_manifest = any(
        isinstance(row, dict)
        and row.get("after_sha256") == manifest_sha256
        and Path(str(row.get("path") or "")).resolve() == manifest_path.resolve()
        for row in patch_report.get("files", [])
        if isinstance(row, dict) and row.get("path")
    )
    if not patch_attests_manifest:
        return None

    generation_binding = next(
        (
            row
            for row in reversed(patch_report.get("protocol_normalizations", []))
            if isinstance(row, dict)
            and row.get("operation") == "bind_exact_board_llm_generation_provenance"
        ),
        None,
    )
    if not isinstance(generation_binding, dict):
        return None
    prompt_sha256 = str(generation_binding.get("prompt_sha256") or "")
    record_sha256 = str(
        generation_binding.get("trusted_generation_record_sha256") or ""
    )
    record_path = str(generation_binding.get("trusted_generation_record") or "")
    if (
        not re.fullmatch(r"[0-9a-f]{64}", prompt_sha256)
        or not re.fullmatch(r"[0-9a-f]{64}", record_sha256)
        or not record_path
    ):
        return None
    archived_record_path = Path(
        str(source_provenance.get("archived_generation_record") or "")
    )
    archived_prompt_path = Path(
        str(source_provenance.get("archived_generation_prompt") or "")
    )
    archived_record_sha256 = str(
        source_provenance.get("archived_generation_record_sha256") or ""
    )
    archived_prompt_sha256 = str(
        source_provenance.get("archived_generation_prompt_sha256") or ""
    )
    archived_binding = (
        archived_record_path.is_file()
        and archived_prompt_path.is_file()
        and archived_record_sha256 == record_sha256
        and archived_prompt_sha256 == prompt_sha256
        and sha256_file(archived_record_path) == archived_record_sha256
        and sha256_file(archived_prompt_path) == archived_prompt_sha256
    )
    return {
        "mode": "llm",
        "agent_id": EXACT_BOARD_GENERATION_AGENT,
        "model": existing["model"],
        "used_fallback": False,
        "prompt_sha256": prompt_sha256,
        "prompt_path": (
            str(archived_prompt_path) if archived_binding else existing.get("prompt_path")
        ),
        "record_path": (
            str(archived_record_path) if archived_binding else record_path
        ),
        "record_sha256": record_sha256,
        "attestation": (
            "archived_agent_patch_application"
            if archived_binding
            else "agent_patch_application"
        ),
        "agent_patch_application_sha256": patch_sha256,
        "source_agent_manifest_sha256": manifest_sha256,
    }


def recover_archived_exact_board_source_provenance(
    manifest: dict[str, Any],
    manifest_path: Path,
    out_dir: Path,
) -> dict[str, Any]:
    """Recover applied LLM provenance from immutable repair-loop snapshots."""

    manifest_path = manifest_path.resolve()
    out_dir = out_dir.resolve()
    harness = manifest.get("multilayer_harness")
    harness = harness if isinstance(harness, dict) else {}
    existing = harness.get("generation_provenance")
    existing = existing if isinstance(existing, dict) else {}
    record_sha256 = str(existing.get("record_sha256") or "")
    prompt_sha256 = str(existing.get("prompt_sha256") or "")
    if (
        existing.get("mode") != "llm"
        or existing.get("agent_id") != EXACT_BOARD_GENERATION_AGENT
        or existing.get("used_fallback") is not False
        or not existing.get("model")
        or not re.fullmatch(r"[0-9a-f]{64}", record_sha256)
        or not re.fullmatch(r"[0-9a-f]{64}", prompt_sha256)
    ):
        return {}

    for iteration_path in sorted(
        (out_dir / "loop").glob("iteration_*/iteration_record.json"),
        reverse=True,
    ):
        iteration = read_json_if_exists(iteration_path)
        rows = [
            row
            for row in iteration.get("evidence_snapshots", [])
            if isinstance(row, dict)
        ]
        record_rows = [
            row
            for row in rows
            if row.get("role") == "llm_record"
            and row.get("source_sha256") == record_sha256
        ]
        prompt_rows = [
            row
            for row in rows
            if row.get("role") in {"request_path", "compact_retry_request_path"}
            and row.get("source_sha256") == prompt_sha256
        ]
        patch_rows = [
            row for row in rows if row.get("role") == "agent_patch_application"
        ]
        if not (
            len(record_rows) == len(prompt_rows) == len(patch_rows) == 1
        ):
            continue

        def verified_snapshot(row: dict[str, Any]) -> Path | None:
            path = Path(str(row.get("snapshot_path") or ""))
            digest = str(row.get("source_sha256") or "")
            if (
                not path.is_file()
                or not path.resolve().is_relative_to(
                    iteration_path.parent.resolve()
                )
                or not re.fullmatch(r"[0-9a-f]{64}", digest)
                or sha256_file(path) != digest
            ):
                return None
            return path

        archived_record_path = verified_snapshot(record_rows[0])
        archived_prompt_path = verified_snapshot(prompt_rows[0])
        archived_patch_path = verified_snapshot(patch_rows[0])
        if None in (
            archived_record_path,
            archived_prompt_path,
            archived_patch_path,
        ):
            continue
        source_record_path = Path(str(record_rows[0].get("source_path") or ""))
        source_prompt_path = Path(str(prompt_rows[0].get("source_path") or ""))
        if not source_record_path.is_absolute() or not source_prompt_path.is_absolute():
            continue
        trusted = trusted_exact_board_generation_record(
            archived_record_path,
            expected_agent=EXACT_BOARD_GENERATION_AGENT,
            expected_status="ready_to_apply",
            source_result_path=source_record_path,
            bound_prompt_path=archived_prompt_path,
            source_prompt_path=source_prompt_path,
        )
        if trusted.get("status") != "pass":
            continue
        patch_report = read_json_if_exists(archived_patch_path)
        if patch_report.get("status") != "pass" or patch_report.get("blockers") != []:
            continue
        manifest_rows = [
            row
            for row in patch_report.get("files", [])
            if isinstance(row, dict)
            and row.get("path")
            and Path(str(row["path"])).resolve() == manifest_path.resolve()
            and re.fullmatch(r"[0-9a-f]{64}", str(row.get("after_sha256") or ""))
        ]
        generation_bindings = [
            row
            for row in patch_report.get("protocol_normalizations", [])
            if isinstance(row, dict)
            and row.get("operation")
            == "bind_exact_board_llm_generation_provenance"
            and row.get("trusted_generation_record_sha256") == record_sha256
            and row.get("prompt_sha256") == prompt_sha256
        ]
        if len(manifest_rows) != 1 or len(generation_bindings) != 1:
            continue
        return {
            "source_patch_application": str(archived_patch_path),
            "source_patch_application_sha256": sha256_file(
                archived_patch_path
            ),
            "source_agent_manifest": str(manifest_path.resolve()),
            "source_agent_manifest_sha256": manifest_rows[0]["after_sha256"],
            "archived_generation_record": str(archived_record_path),
            "archived_generation_record_sha256": record_sha256,
            "archived_generation_prompt": str(archived_prompt_path),
            "archived_generation_prompt_sha256": prompt_sha256,
            "source_iteration_record": str(iteration_path),
            "source_iteration_record_sha256": sha256_file(iteration_path),
        }

    # Observation-only exact-board decisions do not change HDL or manifests,
    # so no patch snapshot exists in their repair-loop iteration. Recover the
    # immutable LLM record directly from the durable history store instead of
    # treating that absence as a failed board-generation provenance.
    history_dir = out_dir / "llm" / "history"
    source_record_path = out_dir / "llm" / f"{EXACT_BOARD_GENERATION_AGENT}_result.json"
    source_prompt_path = out_dir / "llm" / f"{EXACT_BOARD_GENERATION_AGENT}_prompt.md"
    archived_records = [
        path
        for path in sorted(history_dir.glob("*.json"))
        if path.is_file() and sha256_file(path) == record_sha256
    ]
    archived_prompts = [
        path
        for path in sorted(history_dir.glob("*.md"))
        if path.is_file() and sha256_file(path) == prompt_sha256
    ]
    for archived_record_path in archived_records:
        for archived_prompt_path in archived_prompts:
            trusted = trusted_exact_board_generation_record(
                archived_record_path,
                expected_agent=EXACT_BOARD_GENERATION_AGENT,
                expected_status="ready_to_apply",
                source_result_path=source_record_path,
                bound_prompt_path=archived_prompt_path,
                source_prompt_path=source_prompt_path,
            )
            if trusted.get("status") != "pass":
                continue
            output = trusted.get("output", {})
            if not isinstance(output, dict) or output.get("file_edits") != []:
                continue
            return {
                "attestation": "archived_generation_record",
                "archived_generation_record": str(archived_record_path),
                "archived_generation_record_sha256": record_sha256,
                "archived_generation_prompt": str(archived_prompt_path),
                "archived_generation_prompt_sha256": prompt_sha256,
                "source_generation_record": str(source_record_path),
                "source_generation_prompt": str(source_prompt_path),
            }
    return {}


def prefer_archived_exact_board_source_provenance(
    manifest: dict[str, Any],
    manifest_path: Path,
    out_dir: Path,
    current: dict[str, Any],
) -> dict[str, Any]:
    """Prefer the immutable applied-Agent tuple over rolling materializer links."""

    archived = recover_archived_exact_board_source_provenance(
        manifest,
        manifest_path,
        out_dir,
    )
    return archived if archived else current


def rebind_changed_source_hashes_in_manifest(
    manifest: dict[str, Any],
    run_dir: Path,
    changed_sources: dict[Path, tuple[str, str]],
    *,
    staged_content_by_path: dict[Path, str] | None = None,
    require_match: bool = True,
) -> tuple[dict[str, Any], dict[str, Any]]:
    """Refresh only source rows affected by the current successful edit.

    Source manifests are derived metadata.  A semantic RTL edit must therefore
    update every manifest that names that RTL, but it must not refresh unrelated
    stale rows.  This helper is intentionally content-bound: every replacement
    hash is computed from the staged bytes (or the live file) and is accepted
    only when it matches the applied edit's recorded before/after tuple.
    """

    normalized = copy.deepcopy(manifest)
    root = run_dir.resolve()
    staged = {
        path.resolve(): content
        for path, content in (staged_content_by_path or {}).items()
    }
    sources: dict[Path, tuple[str, str]] = {
        path.resolve(): (str(before).lower(), str(after).lower())
        for path, (before, after) in changed_sources.items()
    }
    blockers: list[str] = []
    matched: dict[str, dict[str, Any]] = {}
    updated_fields: list[dict[str, str]] = []
    path_keys = {
        "path",
        "local_path",
        "source_path",
        "generated_source_path",
        "staged_path",
    }

    def resolve_declared_path(value: Any) -> Path | None:
        if not isinstance(value, str) or not value.strip():
            return None
        candidate = Path(value).expanduser()
        try:
            return (candidate if candidate.is_absolute() else root / candidate).resolve()
        except OSError:
            return None

    def current_hash(path: Path) -> str | None:
        if path in staged:
            return hashlib.sha256(staged[path].encode("utf-8")).hexdigest()
        if not path.is_file():
            return None
        try:
            return sha256_file(path)
        except OSError:
            return None

    def visit(value: Any) -> None:
        if isinstance(value, dict):
            matched_source: tuple[Path, str, str] | None = None
            for key in path_keys:
                path = resolve_declared_path(value.get(key))
                if path is None or path not in sources:
                    continue
                before, after = sources[path]
                actual = current_hash(path)
                if actual != after:
                    blockers.append(
                        f"changed source content does not match its recorded after hash: {path}"
                    )
                    continue
                matched_source = (path, before, after)
                break
            if matched_source is not None:
                path, before, after = matched_source
                key = str(path)
                row = matched.setdefault(
                    key,
                    {"path": key, "before_sha256": before, "after_sha256": after},
                )
                for name, child in list(value.items()):
                    if not str(name).lower().endswith("sha256"):
                        continue
                    if not isinstance(child, str):
                        continue
                    lowered = child.lower()
                    if lowered == before:
                        value[name] = after
                        updated_fields.append(
                            {"path": key, "field": str(name), "before_sha256": before, "after_sha256": after}
                        )
                    elif lowered == after:
                        row.setdefault("already_current_fields", []).append(str(name))
                if not any(
                    item.get("path") == key for item in updated_fields
                ) and not row.get("already_current_fields"):
                    blockers.append(
                        f"manifest source row has no hash field bound to the recorded before/after pair: {path}"
                    )
            for child in value.values():
                visit(child)
        elif isinstance(value, list):
            for child in value:
                visit(child)

    visit(normalized)
    for path, (before, after) in sources.items():
        if str(path) not in matched and require_match:
            blockers.append(f"manifest does not contain the changed source path: {path}")
    report = {
        "schema_version": "spatialaccagent.changed_source_manifest_rebind.v1",
        "status": "pass" if not blockers else "blocked",
        "changed_source_count": len(sources),
        "matched_source_count": len(matched),
        "updated_field_count": len(updated_fields),
        "matched_sources": list(matched.values()),
        "updated_fields": updated_fields,
        "blockers": list(dict.fromkeys(blockers)),
        "require_match": require_match,
    }
    return normalized, report


def canonicalize_exact_board_manifest_declarations(
    manifest: dict[str, Any],
    run_dir: Path,
    out_dir: Path,
    *,
    staged_content_by_path: dict[Path, str] | None = None,
    semantic_patch_paths: set[Path] | None = None,
) -> dict[str, Any]:
    """Project mechanical board metadata from current immutable authorities.

    The integration Agent owns the scheduling, interface use, and generated HDL.
    Source hashes, catalog expansion, generated-source rows, and equivalent
    status aliases are framework-owned facts.  Keeping those two ownership
    domains separate prevents a semantically valid board edit from spending
    several LLM turns reformatting the same deterministic metadata.
    """

    normalized = copy.deepcopy(manifest)
    run_dir = run_dir.resolve()
    board_root = (run_dir / "generated" / "board_integration").resolve()
    staged_content = {
        path.resolve(): content
        for path, content in (staged_content_by_path or {}).items()
    }
    def resolve_path(value: Any) -> Path | None:
        if isinstance(value, dict):
            raw = str(value.get("path") or value.get("local_path") or "").strip()
        else:
            raw = str(value or "").strip()
        if not raw:
            return None
        path = Path(raw).expanduser()
        path = path if path.is_absolute() else Path.cwd() / path
        try:
            return path.resolve()
        except OSError:
            return None

    def source_text(path: Path | None) -> str | None:
        if path is None:
            return None
        if path in staged_content:
            return staged_content[path]
        try:
            return path.read_text(encoding="utf-8") if path.is_file() else None
        except (OSError, UnicodeDecodeError):
            return None

    if semantic_patch_paths is None:
        semantic_patch_paths = set()
        patch_report = read_json_if_exists(out_dir / "agent_patch_application.json")
        if patch_report.get("status") == "pass" and patch_report.get("blockers") == []:
            for row in patch_report.get("files", []):
                if not isinstance(row, dict) or not row.get("path"):
                    continue
                path = resolve_path(row.get("path"))
                if path is not None:
                    semantic_patch_paths.add(path)
    else:
        semantic_patch_paths = {path.resolve() for path in semantic_patch_paths}

    def source_modules(text: str | None) -> list[str]:
        if text is None:
            return []
        without_comments = re.sub(r"/\*.*?\*/", "", text, flags=re.DOTALL)
        without_comments = re.sub(r"//[^\n]*", "", without_comments)
        return sorted(
            set(
                re.findall(
                    r"\bmodule\s+(?:automatic\s+)?([A-Za-z_][A-Za-z0-9_$]*)\b",
                    without_comments,
                )
            )
        )

    def at_least_two(value: Any) -> bool:
        try:
            return int(value) >= 2
        except (TypeError, ValueError):
            return False

    def generated_source_row(
        row: Any,
        *,
        role: str,
        fallback_source_id: str = "",
    ) -> dict[str, Any] | None:
        if not isinstance(row, dict):
            return None
        result = copy.deepcopy(row)
        path = resolve_path(result)
        text = source_text(path)
        if path is not None:
            result["path"] = str(path)
            result.pop("local_path", None)
        if text is not None:
            result["sha256"] = hashlib.sha256(text.encode("utf-8")).hexdigest()
            result.pop("local_sha256", None)
            result["declared_modules"] = source_modules(text)
        result["role"] = role
        source_id = str(result.get("source_id") or fallback_source_id).strip()
        if not source_id and path is not None:
            stem = re.sub(r"[^A-Za-z0-9_]+", "_", path.stem).strip("_")
            source_id = f"generated-board-source:{role}:{stem or 'source'}"
        if source_id:
            result["source_id"] = source_id
        dependencies = result.get("dependencies")
        if isinstance(dependencies, list):
            result["dependencies"] = list(
                dict.fromkeys(
                    str(value).strip() for value in dependencies if str(value).strip()
                )
            )
        else:
            result["dependencies"] = []
        return result

    model = read_json_if_exists(run_dir / "input" / "model_config.json")
    task_card = read_json_if_exists(run_dir / "input" / "task_card.json")
    catalog = read_json_if_exists(
        run_dir / "verification" / "model_weights" / "transformer_block_weight_catalog.json"
    )
    try:
        board_scope = resolve_board_validation_scope(task_card, model)
    except BoardValidationScopeError:
        model_layer_count = int(
            model.get("num_layers") or model.get("num_hidden_layers") or 0
        )
        if model_layer_count <= 0:
            model_layer_count = int(catalog.get("target_layer_count") or 0)
        board_scope = None
    else:
        model_layer_count = board_scope.model_layer_count
    target_layers = (
        board_scope.validation_layer_count
        if board_scope is not None
        else model_layer_count
    )
    validation_layer_indices = (
        list(board_scope.layer_indices)
        if board_scope is not None
        else list(range(target_layers))
    )
    covers_full_model = (
        board_scope.covers_full_model
        if board_scope is not None
        else target_layers == model_layer_count
    )
    requires_next_layer_prefetch = (
        board_scope.requires_next_layer_prefetch
        if board_scope is not None
        else target_layers > 1
    )
    catalog_hashes = sorted(
        {
            str(row.get("source_slice_sha256") or "").lower()
            for row in catalog.get("tensors", [])
            if isinstance(row, dict)
            and re.fullmatch(
                r"[0-9a-fA-F]{64}",
                str(row.get("source_slice_sha256") or ""),
            )
        }
    )
    scoped_catalog_hashes = sorted(
        {
            str(row.get("source_slice_sha256") or "").lower()
            for row in catalog.get("tensors", [])
            if isinstance(row, dict)
            and row.get("layer_index") in validation_layer_indices
            and re.fullmatch(
                r"[0-9a-fA-F]{64}",
                str(row.get("source_slice_sha256") or ""),
            )
        }
    )
    if not scoped_catalog_hashes and covers_full_model:
        scoped_catalog_hashes = catalog_hashes
    if scoped_catalog_hashes:
        normalized["board_consumed_tensor_hashes"] = scoped_catalog_hashes
    if target_layers > 0:
        normalized["model_layer_count"] = model_layer_count
        normalized["validation_layer_indices"] = validation_layer_indices
        normalized["all_target_layers"] = covers_full_model
        normalized["bound_layer_count"] = target_layers

    plan = normalized.get("board_simulation_preflight_plan")
    plan = plan if isinstance(plan, dict) else {}
    harness = normalized.get("multilayer_harness")
    harness = harness if isinstance(harness, dict) else {}
    identity = read_json_if_exists(
        run_dir / "verification" / "board_interface" / "board_source_identity.json"
    )
    compute_slot_abi = (
        identity.get("compute_slot_abi")
        if isinstance(identity.get("compute_slot_abi"), dict)
        else {}
    )
    adapter_top_module = str(
        compute_slot_abi.get("replacement_module_identity")
        or compute_slot_abi.get("slot_module")
        or ""
    ).strip()
    if identity.get("status") == "pass" and adapter_top_module and harness:
        # The adapter must replace the discovered compute-slot module.  This is
        # an exact board fact, not an LLM design decision or a board-testbench
        # top-module alias.
        harness["top_module"] = adapter_top_module
    if target_layers > 0 and harness:
        harness["target_layer_count"] = target_layers

    testbench = plan.get("testbench")
    testbench = testbench if isinstance(testbench, dict) else {}
    testbench_source = testbench.get("source")
    if isinstance(testbench_source, str):
        testbench_source = {
            "path": testbench_source,
            "source_id": testbench.get("source_id"),
            "dependencies": testbench.get("dependencies", []),
        }
    if isinstance(testbench_source, dict):
        canonical_testbench = generated_source_row(
            testbench_source,
            role="testbench",
            fallback_source_id=str(testbench.get("source_id") or ""),
        )
        if canonical_testbench is not None:
            testbench["source"] = canonical_testbench
    testbench_top = str(
        testbench.get("top_module") or testbench.get("module") or plan.get("top_module") or ""
    ).strip()
    if testbench_top:
        testbench["top_module"] = testbench_top
        plan.setdefault("top_module", testbench_top)

    execution_outputs = plan.get("execution_outputs")
    execution_outputs = execution_outputs if isinstance(execution_outputs, dict) else {}
    debug_contract = testbench.get("debug_observability_contract")
    if isinstance(debug_contract, dict) and isinstance(
        execution_outputs.get("progress_event_log"), dict
    ):
        debug_contract["progress_event_log"] = copy.deepcopy(
            execution_outputs["progress_event_log"]
        )

    monitor_contract = plan.get("protocol_monitor_contract")
    monitor_contract = monitor_contract if isinstance(monitor_contract, dict) else {}
    monitors = monitor_contract.get("monitors")
    monitors = monitors if isinstance(monitors, list) else []
    harness_instance_path = str(harness.get("instance_path") or "").strip()
    auxiliary_paths: set[Path] = set()
    testbench_path = resolve_path(testbench.get("source"))
    if testbench_path is not None:
        auxiliary_paths.add(testbench_path)
    for monitor in monitors:
        if not isinstance(monitor, dict):
            continue
        source_rows = monitor.get("source_files")
        if not isinstance(source_rows, list):
            source_rows = []
        if not source_rows and monitor.get("source"):
            source_rows = [
                {
                    "path": monitor.get("source"),
                    "source_id": monitor.get("source_id"),
                    "dependencies": [],
                }
            ]
        canonical_sources: list[dict[str, Any]] = []
        for row in source_rows:
            canonical_source = generated_source_row(
                row,
                role="protocol_monitor",
                fallback_source_id=str(monitor.get("source_id") or ""),
            )
            if canonical_source is None:
                continue
            canonical_sources.append(canonical_source)
            path = resolve_path(canonical_source)
            if path is not None:
                auxiliary_paths.add(path)
        monitor["source_files"] = canonical_sources
        if harness_instance_path:
            # The monitor itself can live in the testbench or use a bind
            # statement, but its declared observation target is always the
            # single generated multi-layer harness instance.  This is a
            # framework-owned connection label; VCS still proves the HDL
            # elaborates and observes the actual AXI traffic.
            monitor["bound_instance_path"] = harness_instance_path
    if monitor_contract:
        monitor_contract["monitors"] = monitors
        plan["protocol_monitor_contract"] = monitor_contract

    top_module = str(harness.get("top_module") or "").strip()
    canonical_harness_rows: list[dict[str, Any]] = []
    declared_harness_rows = harness.get("source_files")
    for row in declared_harness_rows if isinstance(declared_harness_rows, list) else []:
        if not isinstance(row, dict):
            continue
        role = str(row.get("role") or "").strip().lower()
        path = resolve_path(row)
        refreshed_semantic_row = copy.deepcopy(row)
        if path in semantic_patch_paths and path.is_file():
            # A board semantic RTL patch changes the shared kernel source used
            # by both the connected-layer and board harness.  Keep the source
            # row in both manifests bound to the bytes that are actually on
            # disk; do not let an old certified hash block the next gate.
            refreshed_semantic_row["sha256"] = sha256_file(path)
        if role == "generated_kernel" or path in auxiliary_paths or role in {
            "testbench",
            "protocol_monitor",
            "axi_protocol_monitor",
        }:
            continue
        if path is None or not path.is_relative_to(board_root):
            canonical_harness_rows.append(refreshed_semantic_row)
            continue
        modules = source_modules(source_text(path))
        canonical_role = (
            "compute_slot_adapter"
            if top_module and top_module in modules
            else "generated_accelerator"
        )
        canonical_row = generated_source_row(
            refreshed_semantic_row,
            role=canonical_role,
        )
        if canonical_row is not None:
            canonical_harness_rows.append(canonical_row)
    if harness:
        if isinstance(declared_harness_rows, list):
            harness["source_files"] = canonical_harness_rows
        normalized["multilayer_harness"] = harness

    # A semantic RTL repair changes a certified kernel source that is shared
    # by the single-layer and board manifests. Rebind only the paths recorded
    # by the current successful Agent transaction; unrelated file drift must
    # remain visible to the normal hash checks.
    single_layer = normalized.get("single_layer_harness")
    if isinstance(single_layer, dict) and isinstance(
        single_layer.get("source_files"), list
    ):
        refreshed_rows: list[dict[str, Any]] = []
        for row in single_layer["source_files"]:
            updated = copy.deepcopy(row)
            path = resolve_path(updated)
            if path in semantic_patch_paths and path.is_file():
                updated["sha256"] = sha256_file(path)
            refreshed_rows.append(updated)
        single_layer["source_files"] = refreshed_rows
        normalized["single_layer_harness"] = single_layer

    integration = normalized.get("board_integration_contract")
    integration = integration if isinstance(integration, dict) else {}
    if identity.get("status") == "pass":
        closure_hash = str(identity.get("selected_simulation_source_closure_sha256") or "")
        if closure_hash:
            integration["source_closure_sha256"] = closure_hash
            integration["selected_simulation_source_closure_sha256"] = closure_hash
        for field in (
            "compute_slot_abi_sha256",
            "timing_contract_sha256",
            "axi_interfaces_sha256",
        ):
            if identity.get(field):
                integration[field] = identity[field]
    memory_path = run_dir / "generated" / "chisel" / "memory" / "memory_layout.json"
    if memory_path.is_file():
        integration["memory_layout_sha256"] = sha256_file(memory_path)

    scheduler = integration.get("scheduler")
    if isinstance(scheduler, dict) and scheduler.get("status") in {"ready", "pass"}:
        if target_layers > 0:
            scheduler["layer_count"] = target_layers
            scheduler["enabled"] = True
            scheduler["all_target_layers"] = covers_full_model
            scheduler["all_validation_layers"] = True
            scheduler["validation_layer_indices"] = validation_layer_indices
    weight_buffer = integration.get("double_weight_buffer")
    if (
        isinstance(weight_buffer, dict)
        and weight_buffer.get("status") in {"ready", "pass"}
        and at_least_two(weight_buffer.get("bank_count"))
        and weight_buffer.get("atomic_switch_after_prefetch_complete") is True
    ):
        weight_buffer["enabled"] = True
        weight_buffer["atomic_layer_switch"] = requires_next_layer_prefetch
        weight_buffer["next_layer_prefetch_required"] = requires_next_layer_prefetch
    activation_buffer = integration.get("activation_ping_pong")
    if (
        isinstance(activation_buffer, dict)
        and activation_buffer.get("status") in {"ready", "pass"}
        and at_least_two(activation_buffer.get("bank_count"))
        and activation_buffer.get("committed_activation_output_required_before_bank_ownership_change")
        is True
    ):
        activation_buffer["enabled"] = True
        activation_buffer["inter_layer_chaining"] = requires_next_layer_prefetch
        activation_buffer["terminal_writeback_from_output_bank"] = True
    prefetch = integration.get("background_prefetch")
    if (
        isinstance(prefetch, dict)
        and prefetch.get("status") in {"ready", "pass"}
        and (
            not requires_next_layer_prefetch
            or (
                prefetch.get("overlaps_current_layer_compute") is True
                and str(prefetch.get("prefetch_scope") or "") == "next_layer_weights"
            )
        )
    ):
        prefetch["enabled"] = requires_next_layer_prefetch
        prefetch["next_layer_prefetch_required"] = requires_next_layer_prefetch
        if not requires_next_layer_prefetch:
            prefetch["overlaps_current_layer_compute"] = False
            prefetch["prefetch_scope"] = "none"
    writeback = integration.get("final_writeback")
    if (
        isinstance(writeback, dict)
        and writeback.get("status") in {"ready", "pass"}
        and writeback.get("only_final_layer") is True
        and writeback.get("starts_after_final_layer_completion") is True
    ):
        writeback["enabled"] = True
        writeback["only_after_last_layer"] = True
    pipeline = integration.get("intra_layer_spatial_pipeline")
    if (
        isinstance(pipeline, dict)
        and pipeline.get("status") in {"ready", "pass"}
        and pipeline.get("pipeline_semantics")
        == "elastic_rate_insensitive_token_pipeline"
        and pipeline.get("different_tokens_overlap_across_required_dataflow") is True
        and pipeline.get("heterogeneous_stage_latency_supported") is True
        and pipeline.get("stage_turnover_gaps_are_diagnostic") is True
        and pipeline.get("serial_leaf_execution") is False
    ):
        pipeline["preserved"] = True
    runtime = integration.get("runtime_constants")
    if (
        isinstance(runtime, dict)
        and runtime.get("enabled") is True
        and runtime.get("required_before_every_kernel_start") is True
    ):
        runtime["all_target_layers"] = covers_full_model
        runtime["all_validation_layers"] = True
        runtime["complete_before_kernel_start"] = True
    if integration:
        normalized["board_integration_contract"] = integration

    generated_sources = [
        *canonical_harness_rows,
        testbench.get("source") if isinstance(testbench.get("source"), dict) else {},
        *[
            source
            for monitor in monitors
            if isinstance(monitor, dict)
            for source in monitor.get("source_files", [])
            if isinstance(source, dict)
        ],
    ]
    source_hashes = {
        str(row.get("source_id") or ""): str(row.get("sha256") or "")
        for row in generated_sources
        if str(row.get("source_id") or "") and str(row.get("sha256") or "")
    }
    evidence_records = plan.get("generated_evidence_records")
    evidence_records = evidence_records if isinstance(evidence_records, list) else []
    evidence_ids = {
        str(row.get("evidence_id") or "")
        for row in evidence_records
        if isinstance(row, dict) and str(row.get("evidence_id") or "")
    }
    evidence_by_id = {
        str(row.get("evidence_id") or ""): row
        for row in evidence_records
        if isinstance(row, dict) and str(row.get("evidence_id") or "")
    }
    source_evidence_ids: dict[str, str] = {}
    for row in generated_sources:
        source_id = str(row.get("source_id") or "")
        source_hash = str(row.get("sha256") or "")
        source_path = str(row.get("path") or "")
        if not source_id or not source_hash or not source_path:
            continue
        stem = re.sub(r"[^A-Za-z0-9_]+", "_", source_id).strip("_")
        evidence_id = f"framework.generated_source.{stem or 'source'}"
        existing = evidence_by_id.get(evidence_id)
        if not (
            isinstance(existing, dict)
            and existing.get("fact_kind") == "framework_generated_source_identity"
            and existing.get("source_id") == source_id
        ) and evidence_id in evidence_ids:
            suffix = 2
            while f"{evidence_id}_{suffix}" in evidence_ids:
                suffix += 1
            evidence_id = f"{evidence_id}_{suffix}"
        source_evidence_ids[source_id] = evidence_id
        if evidence_id not in evidence_ids:
            evidence_records.append(
                {
                    "evidence_id": evidence_id,
                    "fact_kind": "framework_generated_source_identity",
                    "locator": {"kind": "source_file", "value": source_path},
                    "observed_value": "hash_bound_generated_source",
                    "source_id": source_id,
                    "source_sha256": source_hash,
                }
            )
            evidence_ids.add(evidence_id)
            evidence_by_id[evidence_id] = evidence_records[-1]
    for evidence in evidence_records:
        if isinstance(evidence, dict):
            source_hash = source_hashes.get(str(evidence.get("source_id") or ""))
            if source_hash:
                evidence["source_sha256"] = source_hash
    if evidence_records:
        plan["generated_evidence_records"] = evidence_records

    def rebind_generated_source_evidence_refs(value: Any) -> None:
        if isinstance(value, dict):
            refs = value.get("evidence_refs")
            if isinstance(refs, list):
                value["evidence_refs"] = list(
                    dict.fromkeys(
                        source_evidence_ids.get(str(reference), str(reference))
                        for reference in refs
                        if str(reference)
                    )
                )
            for child in value.values():
                rebind_generated_source_evidence_refs(child)
        elif isinstance(value, list):
            for child in value:
                rebind_generated_source_evidence_refs(child)

    rebind_generated_source_evidence_refs(integration)
    if plan:
        plan["testbench"] = testbench
        normalized["board_simulation_preflight_plan"] = plan
    return normalized


def board_integration_binding_errors(
    manifest: dict[str, Any],
    single_layer_harness: dict[str, Any],
    run_dir: Path,
    out_dir: Path,
    single_layer_certificate_path: Path | None = None,
    source_provenance: dict[str, Any] | None = None,
) -> tuple[dict[str, Any] | None, list[str]]:
    from accagent.framework.board_acceptance_contract import compile_source_set_fingerprint

    blockers: list[str] = []
    identity_path = run_dir / "verification" / "board_interface" / "board_source_identity.json"
    model_path = run_dir / "input" / "model_config.json"
    catalog_path = run_dir / "verification" / "model_weights" / "transformer_block_weight_catalog.json"
    memory_path = run_dir / "generated" / "chisel" / "memory" / "memory_layout.json"
    runtime_paths = exact_board_memory_runtime_paths(run_dir, out_dir)
    runtime_contract = read_json_if_exists(runtime_paths["contract"])
    image_manifest = read_json_if_exists(runtime_paths["image_manifest"])
    identity = read_json_if_exists(identity_path)
    model = read_json_if_exists(model_path)
    task_card = read_json_if_exists(run_dir / "input" / "task_card.json")
    catalog = read_json_if_exists(catalog_path)
    try:
        board_scope = resolve_board_validation_scope(task_card, model)
    except BoardValidationScopeError as exc:
        return None, [f"board validation scope is invalid: {exc}"]
    model_layer_count = board_scope.model_layer_count
    target_layers = board_scope.validation_layer_count
    validation_layer_indices = list(board_scope.layer_indices)
    required_hashes = {
        str(row.get("source_slice_sha256"))
        for row in catalog.get("tensors", [])
        if (
            isinstance(row, dict)
            and row.get("layer_index") in validation_layer_indices
            and row.get("source_slice_sha256")
        )
    }
    consumed_hashes = {
        str(value) for value in manifest.get("board_consumed_tensor_hashes", []) if str(value)
    }
    harness = manifest.get("multilayer_harness")
    if not isinstance(harness, dict):
        return None, ["DUT binding has no LLM-generated multi-layer board integration harness"]

    generation_record_path, generation_record, trusted_generation = (
        select_trusted_exact_board_generation_record(
            out_dir,
            expected_status="ready_to_apply",
        )
    )
    generation_output = trusted_generation.get("output", {})
    current_generation_is_trusted = (
        generation_record.get("agent") == EXACT_BOARD_GENERATION_AGENT
        and generation_record.get("mode") == "llm"
        and generation_record.get("used_fallback") is False
        and bool(generation_record.get("model"))
        and not generation_record.get("error")
        and trusted_generation.get("status") == "pass"
        and normalized_implementation_agent_status(generation_output)
        == "ready_to_apply"
    )
    durable_provenance = _attested_exact_board_generation_provenance(
        harness,
        source_provenance or {},
    )
    # Once an applied Agent transaction has been archived and attested, that
    # immutable provenance remains authoritative across deterministic
    # rematerialization.  The canonical LLM result path is mutable and may
    # already contain a later rejected or unrelated attempt.
    if durable_provenance is not None:
        provenance = durable_provenance
    elif current_generation_is_trusted:
        provenance = {
            "mode": "llm",
            "agent_id": generation_record.get("agent"),
            "model": generation_record.get("model"),
            "used_fallback": generation_record.get("used_fallback"),
            "prompt_sha256": trusted_generation.get("prompt_sha256"),
            "record_path": str(generation_record_path),
            "record_sha256": sha256_file(generation_record_path),
        }
    else:
        provenance = copy.deepcopy(
            harness.get("generation_provenance")
            if isinstance(harness.get("generation_provenance"), dict)
            else {}
        )
        blockers.append("multi-layer board integration is not bound to a non-fallback LLM generation agent")

    board_root = (run_dir / "generated" / "board_integration").resolve()
    certified_resume_rows: dict[str, tuple[Path, str]] = {}
    for index, row in enumerate(single_layer_harness.get("source_files", [])):
        if not isinstance(row, dict):
            continue
        path = Path(str(row.get("path") or "")).resolve()
        source_hash = str(row.get("sha256") or "")
        if source_hash:
            certified_resume_rows[
                f"certified_kernel.{index:04d}.{source_hash[:16]}"
            ] = (path, source_hash)
    source_rows: list[dict[str, Any]] = []
    source_texts: list[str] = []
    declared_modules: set[str] = set()
    module_owners: dict[str, Path] = {}
    source_ids: set[str] = set()
    for index, row in enumerate(harness.get("source_files", [])):
        if not isinstance(row, dict):
            blockers.append(f"multilayer_harness.source_files[{index}] is not an object")
            continue
        path = Path(str(row.get("path") or ""))
        path = path if path.is_absolute() else Path.cwd() / path
        path = path.resolve()
        source_id = str(row.get("source_id") or "")
        role = str(row.get("role") or "")
        if role == "generated_kernel":
            expected = certified_resume_rows.get(source_id)
            if (
                expected is not None
                and path == expected[0]
                and str(row.get("sha256") or "") == expected[1]
            ):
                continue
            blockers.append(
                f"multilayer_harness.source_files[{index}] is not an exact framework-materialized certified source"
            )
            continue
        if not source_id or source_id in source_ids:
            blockers.append(f"multilayer_harness.source_files[{index}] has a missing or duplicate source_id")
        else:
            source_ids.add(source_id)
        if role not in {"compute_slot_adapter", "generated_accelerator"}:
            blockers.append(
                f"multilayer_harness.source_files[{index}] role must be compute_slot_adapter or generated_accelerator"
            )
        if not path.is_relative_to(board_root):
            blockers.append(f"multi-layer board source is outside generated/board_integration: {path}")
            continue
        if path.suffix.lower() not in {".sv", ".v"} or not path.is_file():
            blockers.append(f"multi-layer board source is missing or is not RTL: {path}")
            continue
        actual_hash = sha256_file(path)
        if row.get("sha256") and row.get("sha256") != actual_hash:
            blockers.append(f"multi-layer board source hash mismatch: {path}")
            continue
        text = path.read_text(encoding="utf-8")
        modules = re.findall(r"(?m)^\s*module\s+([A-Za-z_][A-Za-z0-9_$]*)\b", text)
        for module in modules:
            if module in module_owners:
                blockers.append(
                    f"multi-layer board source set declares module {module} more than once: "
                    f"{module_owners[module]} and {path}"
                )
            module_owners[module] = path
            declared_modules.add(module)
        source_rows.append(
            {
                **row,
                "path": str(path),
                "sha256": actual_hash,
                "declared_modules": modules,
                "dependencies": [str(value) for value in row.get("dependencies", []) if str(value)],
            }
        )
        source_texts.append(text)

    certified_kernel_ids: list[str] = []
    for index, row in enumerate(single_layer_harness.get("source_files", [])):
        if not isinstance(row, dict):
            blockers.append(f"certified single-layer source_files[{index}] is not an object")
            continue
        path = Path(str(row.get("path") or "")).resolve()
        if not path.is_file() or path.suffix.lower() not in {".sv", ".v"}:
            blockers.append(f"certified single-layer source is missing or invalid: {path}")
            continue
        actual_hash = sha256_file(path)
        if row.get("sha256") != actual_hash:
            blockers.append(f"certified single-layer source hash mismatch: {path}")
            continue
        source_id = f"certified_kernel.{index:04d}.{actual_hash[:16]}"
        if source_id in source_ids:
            blockers.append(f"certified single-layer source_id collision: {source_id}")
            continue
        source_ids.add(source_id)
        text = path.read_text(encoding="utf-8")
        modules = re.findall(r"(?m)^\s*module\s+([A-Za-z_][A-Za-z0-9_$]*)\b", text)
        for module in modules:
            if module in module_owners:
                blockers.append(
                    f"board compile source set declares module {module} more than once: "
                    f"{module_owners[module]} and {path}"
                )
            module_owners[module] = path
            declared_modules.add(module)
        certified_kernel_ids.append(source_id)
        source_rows.append(
            {
                "source_id": source_id,
                "role": "generated_kernel",
                "path": str(path),
                "sha256": actual_hash,
                "declared_modules": modules,
                "dependencies": [],
            }
        )
        source_texts.append(text)
    if not source_rows:
        blockers.append("multi-layer board integration has no hash-verified generated RTL sources")

    top_module = str(harness.get("top_module") or "")
    single_layer_top = str(single_layer_harness.get("top_module") or "")
    if not top_module or top_module not in declared_modules:
        blockers.append("multi-layer board top_module is not declared by its generated source set")
    if not single_layer_top or harness.get("verified_single_layer_top_module") != single_layer_top:
        blockers.append("multi-layer board harness is not bound to the certified single-layer top module")
    combined_source = "\n".join(source_texts)
    actual_kernel_count = (
        len(
            re.findall(
                rf"\b{re.escape(single_layer_top)}\s+(?:#\s*\(.*?\)\s*)?[A-Za-z_][A-Za-z0-9_$]*\s*\(",
                combined_source,
                re.DOTALL,
            )
        )
        if single_layer_top
        else 0
    )
    if actual_kernel_count != 1 or harness.get("instantiated_kernel_count") != 1:
        blockers.append("multi-layer board shell must instantiate exactly one reusable certified single-layer kernel")

    if model_layer_count <= 0:
        blockers.append("target model layer count is missing")
    if (
        manifest.get("model_layer_count", model_layer_count) != model_layer_count
        or manifest.get("validation_layer_indices", validation_layer_indices)
        != validation_layer_indices
        or manifest.get("all_target_layers") is not board_scope.covers_full_model
        or int(manifest.get("bound_layer_count") or 0) != target_layers
        or harness.get("target_layer_count") != target_layers
    ):
        blockers.append("board scheduler does not bind the current validation workload")
    if (
        catalog.get("status") != "pass"
        or catalog.get("scope_coverage_complete") is not True
        or not required_hashes
        or required_hashes != consumed_hashes
    ):
        blockers.append("board binding does not cover the exact validation-layer Transformer-block weights")

    integration = manifest.get("board_integration_contract", {}) if isinstance(manifest.get("board_integration_contract"), dict) else {}
    identity_hashes = {
        "source_closure_sha256": identity.get("selected_simulation_source_closure_sha256"),
        "compute_slot_abi_sha256": identity.get("compute_slot_abi_sha256"),
        "timing_contract_sha256": identity.get("timing_contract_sha256"),
        "axi_interfaces_sha256": identity.get("axi_interfaces_sha256"),
    }
    if identity.get("status") != "pass":
        blockers.append("LLM-interpreted exact board identity has not passed deterministic fact validation")
    for field, expected in identity_hashes.items():
        if not expected or integration.get(field) != expected:
            blockers.append(f"board integration contract does not bind current {field}")
    if not memory_path.is_file() or integration.get("memory_layout_sha256") != sha256_file(memory_path):
        blockers.append("board integration contract does not bind the current stage memory-layout proposal")
    required_runtime_hashes = {
        "board_memory_runtime_contract_sha256": (
            sha256_file(runtime_paths["contract"])
            if runtime_paths["contract"].is_file()
            else None
        ),
        "full_weight_image_manifest_sha256": (
            sha256_file(runtime_paths["image_manifest"])
            if runtime_paths["image_manifest"].is_file()
            else None
        ),
        "full_weight_image_sha256": (
            sha256_file(runtime_paths["image"])
            if runtime_paths["image"].is_file()
            else None
        ),
    }
    if runtime_paths["runtime_capture"].is_file():
        required_runtime_hashes[
            "full_layer_runtime_capture_contract_sha256"
        ] = sha256_file(runtime_paths["runtime_capture"])
    runtime_constants = (
        runtime_contract.get("runtime_constants", {})
        if isinstance(runtime_contract.get("runtime_constants"), dict)
        else {}
    )
    if runtime_constants.get("enabled") is True:
        required_runtime_hashes.update(
            {
                "full_runtime_image_manifest_sha256": (
                    sha256_file(runtime_paths["runtime_image_manifest"])
                    if runtime_paths["runtime_image_manifest"].is_file()
                    else None
                ),
                "full_runtime_image_sha256": (
                    sha256_file(runtime_paths["runtime_image"])
                    if runtime_paths["runtime_image"].is_file()
                    else None
                ),
            }
        )
    if (
        runtime_contract.get("validation", {}).get("status") != "pass"
        or image_manifest.get("status") != "pass"
        or image_manifest.get("image_sha256")
        != required_runtime_hashes["full_weight_image_sha256"]
    ):
        blockers.append("current validated board runtime/weight-image authority is unavailable")
    for field, expected in required_runtime_hashes.items():
        if not expected or integration.get(field) != expected:
            blockers.append(f"board integration contract does not bind current {field}")

    required_mechanisms = {
        "scheduler": ("enabled", "all_validation_layers"),
        "double_weight_buffer": ("enabled",),
        "activation_ping_pong": ("enabled", "terminal_writeback_from_output_bank"),
        "final_writeback": ("enabled", "only_after_last_layer"),
        "intra_layer_spatial_pipeline": (
            "preserved",
            "different_tokens_overlap_across_required_dataflow",
            "heterogeneous_stage_latency_supported",
            "stage_turnover_gaps_are_diagnostic",
        ),
    }
    for mechanism, required_true_fields in required_mechanisms.items():
        contract = integration.get(mechanism, {}) if isinstance(integration.get(mechanism), dict) else {}
        if any(contract.get(field) is not True for field in required_true_fields):
            blockers.append(f"board integration contract does not preserve required mechanism {mechanism}")
    prefetch = (
        integration.get("background_prefetch", {})
        if isinstance(integration.get("background_prefetch"), dict)
        else {}
    )
    if board_scope.requires_next_layer_prefetch:
        if (
            prefetch.get("enabled") is not True
            or prefetch.get("overlaps_current_layer_compute") is not True
            or prefetch.get("prefetch_scope") != "next_layer_weights"
            or prefetch.get("next_layer_prefetch_required") is not True
        ):
            blockers.append("board integration contract does not preserve next-layer prefetch overlap")
    elif (
        prefetch.get("enabled") is not False
        or prefetch.get("overlaps_current_layer_compute") is not False
        or prefetch.get("prefetch_scope") != "none"
        or prefetch.get("next_layer_prefetch_required") is not False
    ):
        blockers.append("single-layer terminal board schedule fabricates next-layer prefetch")
    weight_buffer = integration.get("double_weight_buffer", {}) if isinstance(integration.get("double_weight_buffer"), dict) else {}
    activation_buffer = integration.get("activation_ping_pong", {}) if isinstance(integration.get("activation_ping_pong"), dict) else {}
    spatial_pipeline = integration.get("intra_layer_spatial_pipeline", {}) if isinstance(integration.get("intra_layer_spatial_pipeline"), dict) else {}
    if weight_buffer.get("bank_count", 0) < 2:
        blockers.append("board integration weight buffer has fewer than two banks")
    if activation_buffer.get("bank_count", 0) < 2:
        blockers.append("board integration activation buffer has fewer than two banks")
    if weight_buffer.get("atomic_layer_switch") is not board_scope.requires_next_layer_prefetch:
        blockers.append("board integration weight-bank switch does not match validation scope")
    if activation_buffer.get("inter_layer_chaining") is not board_scope.requires_next_layer_prefetch:
        blockers.append("board integration activation chaining does not match validation scope")
    if spatial_pipeline.get("serial_leaf_execution") is not False:
        blockers.append("board integration contract does not forbid serial leaf-module execution")
    if (
        spatial_pipeline.get("pipeline_semantics")
        != "elastic_rate_insensitive_token_pipeline"
        or spatial_pipeline.get("all_stages_same_cycle_concurrency_required") is not False
    ):
        blockers.append(
            "board integration contract does not preserve elastic rate-insensitive pipeline semantics"
        )

    certificate_path = single_layer_certificate_path.resolve() if single_layer_certificate_path else Path()
    certificate = read_json_if_exists(certificate_path) if certificate_path.is_file() else {}
    if not certificate_path.is_file() or certificate.get("status") != "pass":
        blockers.append("single-layer promotion certificate is missing or is not pass")
        certificate_artifact: dict[str, Any] = {}
    else:
        certificate_artifact = {
            "path": str(certificate_path),
            "sha256": sha256_file(certificate_path),
        }

    normalized = {
        **harness,
        "generation_provenance": provenance,
        "source_files": source_rows,
        "source_set_sha256": compile_source_set_fingerprint(source_rows),
        "certified_kernel_source_ids": certified_kernel_ids,
        "single_layer_promotion_certificate": certificate_artifact,
        "verified_single_layer_top_module": single_layer_top,
        "instantiated_kernel_count": actual_kernel_count,
        "target_layer_count": target_layers,
    }
    return normalized, blockers


def _exact_board_closure_rows(identity: dict[str, Any]) -> list[dict[str, Any]]:
    closure = identity.get("selected_simulation_source_closure")
    if isinstance(closure, list):
        return [row for row in closure if isinstance(row, dict)]
    if isinstance(closure, dict):
        for field in ("source_files", "sources", "files", "materialized_sources"):
            rows = closure.get(field)
            if isinstance(rows, list):
                return [row for row in rows if isinstance(row, dict)]
    return []


def _exact_board_simulator_compile_input(row: dict[str, Any]) -> bool:
    path = Path(str(row.get("path") or row.get("local_path") or row.get("remote_path") or ""))
    file_type = str(row.get("file_type") or "").strip().lower()
    language = str(row.get("language") or "").strip().lower()
    structured_type = f"{file_type} {language}"
    suffix = path.suffix.lower()
    if suffix in {".vh", ".svh"} or "header" in structured_type:
        return False
    if any(
        value in structured_type
        for value in ("elf", "firmware", "runtime auxiliary", "non-hdl", "non hdl")
    ):
        return False
    return suffix in {
        ".v",
        ".vp",
        ".sv",
        ".svp",
        ".vhd",
        ".vhdl",
    } or any(value in structured_type for value in ("verilog", "vhdl"))


def _exact_board_source_classification(row: dict[str, Any]) -> str:
    if _exact_board_simulator_compile_input(row):
        return "compiler_input"
    path = Path(
        str(row.get("path") or row.get("local_path") or row.get("remote_path") or "")
    )
    structured_type = " ".join(
        str(row.get(field) or "").strip().lower()
        for field in ("file_type", "language")
    )
    if path.suffix.lower() in {".vh", ".svh"} or "header" in structured_type:
        return "include_header"
    return "runtime_auxiliary"


def _safe_board_relative_path(value: Any) -> bool:
    path = Path(str(value or ""))
    return bool(path.name) and not path.is_absolute() and ".." not in path.parts


def _generated_rtl_modules(path: Path) -> list[str]:
    text = path.read_text(encoding="utf-8", errors="ignore")
    text = re.sub(r"/\*.*?\*/", "", text, flags=re.DOTALL)
    text = re.sub(r"//[^\n]*", "", text)
    return sorted(
        set(
            re.findall(
                r"\bmodule\s+(?:automatic\s+)?([A-Za-z_][A-Za-z0-9_$]*)\b",
                text,
            )
        )
    )


def _normalize_exact_board_source(
    row: Any,
    *,
    label: str,
    base_dir: Path,
    blockers: list[str],
    generated_role: str | None = None,
    allowed_root: Path | None = None,
) -> dict[str, Any] | None:
    if not isinstance(row, dict):
        blockers.append(f"{label} is not an object")
        return None
    source_id = str(row.get("source_id") or "").strip()
    role = str(row.get("role") or row.get("source_role") or "").strip().lower()
    raw_path = str(row.get("path") or row.get("local_path") or "").strip()
    expected_hash = str(row.get("sha256") or row.get("local_sha256") or "").strip().lower()
    if not source_id:
        blockers.append(f"{label}.source_id is missing")
    if generated_role is not None and role != generated_role:
        blockers.append(f"{label}.role must be {generated_role}")
    if not role:
        blockers.append(f"{label}.role is missing")
    if not raw_path:
        blockers.append(f"{label}.path/local_path is missing")
        return None
    path = Path(raw_path).expanduser()
    path = path if path.is_absolute() else base_dir / path
    try:
        path = path.resolve()
    except OSError as exc:
        blockers.append(f"{label} path cannot be resolved: {exc}")
        return None
    if allowed_root is not None and not path.is_relative_to(allowed_root.resolve()):
        blockers.append(f"{label} is outside generated/board_integration: {path}")
    if not path.is_file():
        blockers.append(f"{label} source file is missing: {path}")
        return None
    if generated_role is not None or role in {
        "compute_slot_adapter",
        "generated_accelerator",
        "generated_kernel",
        "testbench",
        "protocol_monitor",
    }:
        if path.suffix.lower() not in {".sv", ".v"}:
            blockers.append(f"{label} generated source is not Verilog/SystemVerilog: {path}")
            return None
    actual_hash = sha256_file(path)
    if not re.fullmatch(r"[0-9a-f]{64}", expected_hash):
        blockers.append(f"{label}.sha256 is missing or invalid")
    elif actual_hash != expected_hash:
        blockers.append(f"{label} hash mismatch: {path}")
    dependencies = row.get("dependencies")
    if not isinstance(dependencies, list) or not all(
        isinstance(value, str) and value.strip() for value in dependencies
    ):
        blockers.append(f"{label}.dependencies must be a list of non-empty source IDs")
        dependencies = []
    dependencies = [str(value).strip() for value in dependencies]
    if len(dependencies) != len(set(dependencies)):
        blockers.append(f"{label}.dependencies contains duplicates")
    declared_modules = row.get("declared_modules")
    if generated_role is not None or role in {
        "compute_slot_adapter",
        "generated_accelerator",
        "generated_kernel",
        "testbench",
        "protocol_monitor",
    }:
        actual_modules = _generated_rtl_modules(path)
        if not isinstance(declared_modules, list) or {
            str(value).strip() for value in declared_modules if str(value).strip()
        } != set(actual_modules):
            blockers.append(f"{label}.declared_modules does not match the generated RTL")
        declared_modules = actual_modules
    elif not isinstance(declared_modules, list) or not all(
        isinstance(value, str) and value.strip() for value in declared_modules
    ):
        blockers.append(f"{label}.declared_modules must be a list of module identities")
        declared_modules = []
    else:
        declared_modules = sorted({str(value).strip() for value in declared_modules})
    staged_path = row.get("staged_path")
    if staged_path is not None and not _safe_board_relative_path(staged_path):
        blockers.append(f"{label}.staged_path is unsafe")
    normalized = copy.deepcopy(row)
    normalized.update(
        {
            "source_id": source_id,
            "role": role,
            "path": str(path),
            "sha256": actual_hash,
            "dependencies": dependencies,
            "declared_modules": declared_modules,
        }
    )
    normalized.pop("local_path", None)
    normalized.pop("local_sha256", None)
    return normalized


def _normalize_exact_board_artifact(
    row: Any,
    *,
    label: str,
    base_dir: Path,
    blockers: list[str],
) -> dict[str, Any] | None:
    if not isinstance(row, dict):
        blockers.append(f"{label} is missing")
        return None
    raw_path = str(row.get("path") or "").strip()
    expected_hash = str(row.get("sha256") or "").strip().lower()
    if not raw_path:
        blockers.append(f"{label}.path is missing")
        return None
    path = Path(raw_path).expanduser()
    path = path if path.is_absolute() else base_dir / path
    try:
        path = path.resolve()
    except OSError as exc:
        blockers.append(f"{label} path cannot be resolved: {exc}")
        return None
    if not path.is_file():
        blockers.append(f"{label} file is missing: {path}")
        return None
    actual_hash = sha256_file(path)
    if not re.fullmatch(r"[0-9a-f]{64}", expected_hash):
        blockers.append(f"{label}.sha256 is missing or invalid")
    elif actual_hash != expected_hash:
        blockers.append(f"{label} hash mismatch: {path}")
    normalized = copy.deepcopy(row)
    normalized.update({"path": str(path), "sha256": actual_hash})
    return normalized


def authoritative_board_weight_artifact(
    image_manifest: dict[str, Any],
) -> dict[str, Any]:
    """Project the immutable full-weight manifest into the board artifact schema."""

    image = image_manifest.get("image")
    image = image if isinstance(image, dict) else {}
    projected = {
        key: copy.deepcopy(image_manifest[key])
        for key in (
            "accelerator_scope",
            "scope_coverage_complete",
            "accelerator_weight_catalog_sha256",
            "source_checkpoint_sha256",
            "packed_tensor_hashes",
            "manifest_contract_sha256",
            "total_bytes",
            "layer_segments",
        )
        if key in image_manifest
    }
    projected.update(
        {
            "path": image_manifest.get("path") or image.get("path"),
            "sha256": image_manifest.get("image_sha256") or image.get("sha256"),
            "total_bytes": image_manifest.get("total_bytes")
            or image.get("total_bytes")
            or image.get("byte_count"),
        }
    )
    return projected


def _materialize_external_fixture_preflight_selection(
    plan: dict[str, Any],
    run_dir: Path,
    blockers: list[str],
) -> tuple[dict[str, Any], list[dict[str, Any]], dict[str, str]]:
    """Bind the LLM-selected component-model closure to the current fixture."""

    if (
        str(plan.get("validation_mode") or "exact_sample_physical_ddr")
        == EXACT_BOARD_FUNCTIONAL_VALIDATION_MODE
    ):
        plan.pop("external_simulation_fixture", None)
        return {}, [], {}

    fixture_path = (
        run_dir
        / "verification"
        / "board_interface"
        / "external_simulation_fixture.json"
    ).resolve()
    fixture = read_json_if_exists(fixture_path)
    selection = plan.get("external_simulation_fixture")
    if not isinstance(selection, dict):
        selection = {}
        blockers.append(
            "board_simulation_preflight_plan.external_simulation_fixture is missing"
        )
    if not fixture_path.is_file() or fixture.get("status") != "pass":
        blockers.append("current external simulation fixture is missing or is not pass")
        return {}, [], {}
    if fixture.get("blockers") not in ([], None):
        blockers.append("current external simulation fixture contains blockers")

    fixture_contract = {
        key: value
        for key, value in fixture.items()
        if key not in {"contract_sha256", "cache_reused"}
    }
    expected_contract_sha256 = hashlib.sha256(
        json.dumps(
            fixture_contract,
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=True,
        ).encode("utf-8")
    ).hexdigest()
    if fixture.get("contract_sha256") != expected_contract_sha256:
        blockers.append("current external simulation fixture contract hash is stale")

    compile_authority = (
        fixture.get("compile_authority")
        if isinstance(fixture.get("compile_authority"), dict)
        else {}
    )
    if compile_authority.get("status") != "pass":
        blockers.append("current external simulation fixture compile authority is not pass")
    source_catalog = compile_authority.get("compile_sources")
    if not isinstance(source_catalog, list):
        source_catalog = compile_authority.get("compiler_inputs")
    source_catalog = [row for row in source_catalog or [] if isinstance(row, dict)]
    source_by_id = {
        str(row.get("source_id") or ""): row
        for row in source_catalog
        if str(row.get("source_id") or "")
    }
    catalog_order = [str(row.get("source_id")) for row in source_catalog if row.get("source_id")]
    selected = selection.get("selected_source_ids")
    component_selected_ids = (
        [str(value) for value in selected] if isinstance(selected, list) else []
    )
    model_instance = selection.get("model_instance")
    if not isinstance(model_instance, dict):
        model_instance = {}
    else:
        model_instance = copy.deepcopy(model_instance)

    prior_source_by_id: dict[str, dict[str, Any]] = {}
    for prior_path in (
        run_dir
        / "verification"
        / "board_simulation"
        / "board_simulation_executed_manifest.json",
        run_dir
        / "verification"
        / "board_simulation"
        / "board_simulation_manifest.json",
    ):
        prior = read_json_if_exists(prior_path)
        for row in prior.get("source_files", []):
            if isinstance(row, dict) and str(row.get("source_id") or ""):
                prior_source_by_id.setdefault(str(row["source_id"]), row)

    remapped_ids: dict[str, str] = {}
    for stale_id in component_selected_ids:
        if stale_id in source_by_id:
            remapped_ids[stale_id] = stale_id
            continue
        prior = prior_source_by_id.get(stale_id, {})
        prior_path = Path(str(prior.get("path") or ""))
        matches = [
            row
            for row in source_catalog
            if str(row.get("sha256") or "") == str(prior.get("sha256") or "")
            and prior.get("sha256")
            and PurePosixPath(str(row.get("remote_path") or "")).name
            == prior_path.name
            and (
                not prior.get("provider_configuration_sha256")
                or row.get("provider_configuration_sha256")
                == prior.get("provider_configuration_sha256")
            )
        ]
        if len(matches) == 1:
            remapped_ids[stale_id] = str(matches[0]["source_id"])
    if component_selected_ids and len(remapped_ids) == len(component_selected_ids):
        component_selected_ids = [remapped_ids[value] for value in component_selected_ids]
        prior_model_source_id = str(model_instance.get("source_id") or "")
        if prior_model_source_id in remapped_ids:
            model_instance["source_id"] = remapped_ids[prior_model_source_id]
        changed_ids = {
            stale: current
            for stale, current in remapped_ids.items()
            if stale != current
        }
        if changed_ids:
            def rewrite_source_ids(value: Any) -> Any:
                if isinstance(value, str):
                    return changed_ids.get(value, value)
                if isinstance(value, list):
                    return [rewrite_source_ids(item) for item in value]
                if isinstance(value, dict):
                    return {
                        key: rewrite_source_ids(item) for key, item in value.items()
                    }
                return value

            rewritten_plan = rewrite_source_ids(plan)
            plan.clear()
            plan.update(rewritten_plan)
            selection = plan.get("external_simulation_fixture", {})
            component_selected_ids = [
                str(value)
                for value in selection.get("selected_source_ids", [])
                if str(value)
            ]
            model_instance = copy.deepcopy(selection.get("model_instance", {}))
    if (
        not component_selected_ids
        or any(not value for value in component_selected_ids)
        or len(component_selected_ids) != len(set(component_selected_ids))
        or not set(component_selected_ids).issubset(source_by_id)
    ):
        blockers.append(
            "external fixture selected_source_ids are missing, duplicate, or outside compiler authority"
        )
        component_selected_ids = [
            value for value in component_selected_ids if value in source_by_id
        ]
    if component_selected_ids != [
        value for value in catalog_order if value in set(component_selected_ids)
    ]:
        blockers.append(
            "external fixture selected_source_ids do not preserve compiler-authority order"
        )
    required_global_ids = {
        str(row.get("source_id"))
        for row in compile_authority.get("hdl_export_artifacts", [])
        if isinstance(row, dict)
        and row.get("source_id")
        and row.get("invoked_by_compile") is not False
    }
    if not required_global_ids.issubset(source_by_id):
        blockers.append(
            "external fixture global simulator sources are outside compiler authority"
        )
    effective_selected = set(component_selected_ids) | required_global_ids
    selected_ids = [value for value in catalog_order if value in effective_selected]

    normalized_sources: list[dict[str, Any]] = []
    for index, source_id in enumerate(selected_ids):
        row = copy.deepcopy(source_by_id[source_id])
        row["role"] = "external_fixture_compile_source"
        row.setdefault("dependencies", [])
        if not isinstance(row.get("declared_modules"), list):
            units = row.get("declared_design_units")
            row["declared_modules"] = [
                str(unit.get("name"))
                for unit in units or []
                if isinstance(unit, dict)
                and str(unit.get("kind") or "").lower() in {"module", "entity"}
                and str(unit.get("name") or "")
            ]
        normalized = _normalize_exact_board_source(
            row,
            label=f"external fixture compiler input[{index}]",
            base_dir=fixture_path.parent,
            blockers=blockers,
        )
        if normalized is not None:
            normalized_sources.append(normalized)

    if not model_instance:
        blockers.append("external fixture model_instance is missing")
    model_source_id = str(model_instance.get("source_id") or "")
    model_module = str(model_instance.get("module") or "").strip()
    if not model_module or model_source_id not in component_selected_ids:
        blockers.append(
            "external fixture model_instance must bind a module in the selected compiler inputs"
        )
    else:
        model_source = next(
            (row for row in normalized_sources if row.get("source_id") == model_source_id),
            {},
        )
        if model_module not in set(model_source.get("declared_modules", [])):
            blockers.append(
                "external fixture model_instance module is not declared by its selected source"
            )

    export_contexts: dict[str, str] = {}
    for index, row in enumerate(compile_authority.get("export_contexts", [])):
        if not isinstance(row, dict):
            blockers.append(f"external fixture export context[{index}] is not an object")
            continue
        text = row.get("text")
        digest = str(row.get("sha256") or "").lower()
        if (
            not isinstance(text, str)
            or not text
            or hashlib.sha256(text.encode("utf-8")).hexdigest() != digest
        ):
            blockers.append(f"external fixture export context[{index}] is hash-invalid")
            continue
        export_contexts[digest] = text
    if not export_contexts:
        blockers.append("external fixture has no hash-valid VCS export contexts")

    fixture_reference = {
        "path": str(fixture_path),
        "sha256": sha256_file(fixture_path),
        "contract_sha256": expected_contract_sha256,
        "selected_source_ids": selected_ids,
        "model_instance": copy.deepcopy(model_instance),
    }
    for field in (
        "runtime_auxiliary_files",
        "include_directories",
        "synopsys_sim_setup",
    ):
        value = compile_authority.get(field)
        if value not in (None, [], {}):
            fixture_reference[field] = copy.deepcopy(value)
    return fixture_reference, normalized_sources, export_contexts


def materialize_frozen_compute_slot_identity_attestation(
    *,
    run_dir: Path,
    identity: dict[str, Any],
    identity_path: Path,
    current_facts_sha256: str,
) -> tuple[dict[str, Any], dict[str, Any]]:
    from accagent.framework.board_acceptance_contract import (
        FROZEN_COMPUTE_SLOT_IDENTITY_ATTESTATION_SCHEMA_VERSION,
        FROZEN_COMPUTE_SLOT_IDENTITY_REQUIRED_CHECKS,
        compile_source_set_fingerprint,
    )

    if not identity_path.is_file():
        return {}, {}
    identity_sha256 = sha256_file(identity_path)
    attested_facts_sha256 = str(identity.get("vivado_facts_sha256") or "").lower()
    if (
        re.fullmatch(r"[0-9a-f]{64}", attested_facts_sha256) is None
        or not current_facts_sha256
        or current_facts_sha256 == attested_facts_sha256
    ):
        return {}, {}

    recovered_attestation, recovered_plan, _, _ = (
        recover_certified_frozen_compute_slot_authority(
            run_dir,
            identity_path,
            identity,
        )
    )
    if recovered_attestation:
        return recovered_attestation, recovered_plan

    prior_path = (
        run_dir
        / "verification"
        / "board_simulation"
        / "board_simulation_executed_manifest.json"
    )
    prior = read_json_if_exists(prior_path)
    runner_path = (
        run_dir
        / "verification"
        / "vcs"
        / "case_board_vcs_functional.json"
    )
    runner = read_json_if_exists(runner_path)
    execution = (
        prior.get("execution_evidence")
        if isinstance(prior.get("execution_evidence"), dict)
        else {}
    )
    compile_evidence = (
        execution.get("compile")
        if isinstance(execution.get("compile"), dict)
        else {}
    )
    prior_preflight = (
        runner.get("exact_board_preflight")
        if isinstance(runner.get("exact_board_preflight"), dict)
        else {}
    )
    check_rows = [
        row
        for row in prior_preflight.get("checks", [])
        if isinstance(row, dict) and str(row.get("name") or "")
    ]
    check_names = [str(row.get("name")) for row in check_rows]
    passed_checks = {
        str(row.get("name"))
        for row in check_rows
        if row.get("status") == "pass" and row.get("blockers") in (None, [])
    }
    prior_plan = (
        prior.get("vcs_compile_plan")
        if isinstance(prior.get("vcs_compile_plan"), dict)
        else {}
    )
    prior_authority = (
        prior_plan.get("compile_authority")
        if isinstance(prior_plan.get("compile_authority"), dict)
        else {}
    )
    prior_plan_sha256 = (
        canonical_contract_sha256(prior_plan) if prior_plan else ""
    )
    runner_implementation_path = (
        Path(__file__).resolve().parents[2]
        / "scripts"
        / "verification"
        / "case_board_vcs_functional.py"
    )
    recovery = (
        runner.get("remote_job_recovery_contract")
        if isinstance(runner.get("remote_job_recovery_contract"), dict)
        else {}
    )
    job_path = Path(str(recovery.get("job_contract") or ""))
    job = read_json_if_exists(job_path) if job_path.is_file() else {}
    job_sha256 = sha256_file(job_path) if job_path.is_file() else ""
    fingerprint = str(runner.get("input_fingerprint_sha256") or "")
    compile_exit = compile_evidence.get("exit_code")
    prior_compile_source_ids = [
        str(value)
        for value in prior.get("compile_source_ids", [])
        if isinstance(value, str) and value
    ]
    planned_source_ids: list[str] = []
    for command in prior_plan.get("ordered_commands", []):
        if isinstance(command, dict) and command.get("phase") == "compile":
            source_ids = command.get("source_ids")
            if isinstance(source_ids, list):
                planned_source_ids.extend(
                    str(value)
                    for value in source_ids
                    if isinstance(value, str) and value
                )
    runner_remote_workdir = str(runner.get("remote_workdir") or "")
    job_fingerprint_payload = {
        key: value
        for key, value in job.items()
        if key not in {"input_fingerprint_sha256", "remote_workdir"}
    }
    recomputed_fingerprint = canonical_contract_sha256(job_fingerprint_payload)
    remote_stage_root = str(job.get("remote_stage_root") or "").rstrip("/")
    expected_remote_workdir = (
        f"{remote_stage_root}/{fingerprint[:12]}_{int(fingerprint[12:], 16)}"
        if remote_stage_root and re.fullmatch(r"[0-9a-f]{64}", fingerprint)
        else ""
    )
    runner_compile = (
        runner.get("compile") if isinstance(runner.get("compile"), dict) else {}
    )
    runner_launch = (
        runner_compile.get("launch")
        if isinstance(runner_compile.get("launch"), dict)
        else {}
    )
    from scripts.verification.case_board_vcs_functional import (
        preflight_manifest_projection_sha256,
    )

    contract_bindings = (
        ("source_closure_sha256", "selected_simulation_source_closure_sha256"),
        ("compute_slot_abi_sha256", "compute_slot_abi_sha256"),
        ("timing_contract_sha256", "timing_contract_sha256"),
        ("axi_interfaces_sha256", "axi_interfaces_sha256"),
    )
    if (
        prior.get("validation_mode") != "compute_slot_axi"
        or prior.get("exact_sample_wrapper_unmodified") is not True
        or prior.get("compiled_sample_source_ids") != []
        or prior.get("external_simulation_fixture") not in (None, {})
        or prior.get("source_identity_sha256") != identity_sha256
        or execution.get("source_identity_sha256") != identity_sha256
        or execution.get("tool") != "vcs"
        or not isinstance(compile_exit, int)
        or isinstance(compile_exit, bool)
        or re.fullmatch(
            r"[0-9a-f]{64}", str(execution.get("command_sha256") or "")
        )
        is None
        or not str(execution.get("tool_version") or "").strip()
        or len(check_names) != len(set(check_names))
        or not FROZEN_COMPUTE_SLOT_IDENTITY_REQUIRED_CHECKS.issubset(passed_checks)
        or runner.get("exact_board_preflight_passed") is not True
        or prior_preflight.get("status") != "pass"
        or prior_preflight.get("blockers") not in (None, [])
        or runner.get("validation_mode") != "compute_slot_axi"
        or str(runner.get("vcs_compile_plan_sha256") or "")
        != prior_plan_sha256
        or str(prior_preflight.get("vcs_compile_plan_sha256") or "")
        != prior_plan_sha256
        or str(prior.get("vcs_compile_plan_sha256") or "")
        != prior_plan_sha256
        or str(execution.get("vcs_compile_plan_sha256") or "")
        != prior_plan_sha256
        or not runner_implementation_path.is_file()
        or runner.get("runner_implementation_sha256")
        != sha256_file(runner_implementation_path)
        or not re.fullmatch(r"[0-9a-f]{64}", fingerprint)
        or recomputed_fingerprint != fingerprint
        or not job_path.is_absolute()
        or not job_path.resolve().is_relative_to(run_dir.resolve())
        or job.get("input_fingerprint_sha256") != fingerprint
        or job.get("source_identity_sha256") != identity_sha256
        or job.get("source_closure_sha256")
        != identity.get("selected_simulation_source_closure_sha256")
        or job.get("vcs_compile_plan_sha256") != prior_plan_sha256
        or canonical_contract_sha256(job.get("vcs_compile_plan", {}))
        != prior_plan_sha256
        or not isinstance(job.get("verified_compile_source_ids"), list)
        or len(job.get("verified_compile_source_ids", []))
        != len(set(job.get("verified_compile_source_ids", [])))
        or set(job.get("verified_compile_source_ids", []))
        != set(prior_compile_source_ids)
        or planned_source_ids != prior_compile_source_ids
        or not prior_compile_source_ids
        or len(prior_compile_source_ids) != len(set(prior_compile_source_ids))
        or job.get("top_module") != prior.get("top_module")
        or job.get("remote_workdir") != runner_remote_workdir
        or runner_remote_workdir != expected_remote_workdir
        or execution.get("job_id") != runner_remote_workdir
        or job.get("preflight_manifest_projection_sha256")
        != runner.get("preflight_manifest_projection_sha256")
        or runner.get("preflight_manifest_projection_sha256")
        != preflight_manifest_projection_sha256(prior)
        or job.get("compile_source_set_sha256")
        != prior.get("compile_source_set_sha256")
        or prior.get("compile_source_set_sha256")
        != compile_source_set_fingerprint(prior.get("source_files", []))
        or runner.get("phase") != "remote_vcs"
        or runner_compile.get("remote_state") != "done"
        or runner_compile.get("transport")
        != "detached_remote_job_with_short_ssh_polling"
        or runner_compile.get("returncode") != compile_exit
        or runner_launch.get("status") != "pass"
        or runner_launch.get("returncode") != 0
        or "SPATIALACC_REMOTE_JOB_STARTED pid="
        not in str(runner_launch.get("stdout_tail") or "")
        or runner_compile.get("remote_command") != job.get("compile_command")
        or recovery.get("status") != "pass"
        or recovery.get("job_contract_sha256") != job_sha256
        or not runner_remote_workdir.split("/")[-1].startswith(fingerprint[:12] + "_")
        or str(prior_authority.get("vivado_facts_sha256") or "").lower()
        != attested_facts_sha256
        or not prior_authority.get("simulator_export_context_sha256s")
        or len(prior_authority.get("simulator_export_context_sha256s", []))
        != len(set(prior_authority.get("simulator_export_context_sha256s", [])))
        or any(
            not identity.get(identity_field)
            or prior.get(prior_field) != identity.get(identity_field)
            or execution.get(prior_field) != identity.get(identity_field)
            for prior_field, identity_field in contract_bindings
        )
    ):
        return {}, {}

    prior_sha256 = sha256_file(prior_path)
    runner_sha256 = sha256_file(runner_path)
    certificate_dir = identity_path.parent / "certificates"
    certificate_dir.mkdir(parents=True, exist_ok=True)
    snapshot_specs = [
        (prior_path, prior_sha256, f"executed_manifest_{prior_sha256}.json"),
        (runner_path, runner_sha256, f"vcs_runner_report_{runner_sha256}.json"),
        (job_path, job_sha256, f"vcs_job_contract_{job_sha256}.json"),
    ]
    snapshots: dict[str, Path] = {}
    for source, digest, name in snapshot_specs:
        snapshot = certificate_dir / name
        if snapshot.exists():
            if not snapshot.is_file() or sha256_file(snapshot) != digest:
                return {}, {}
        else:
            shutil.copy2(source, snapshot)
            if sha256_file(snapshot) != digest:
                return {}, {}
        snapshots[name] = snapshot
    attestation = {
        "schema_version": FROZEN_COMPUTE_SLOT_IDENTITY_ATTESTATION_SCHEMA_VERSION,
        "status": "pass",
        "source_identity_sha256": identity_sha256,
        "attested_vivado_facts_sha256": attested_facts_sha256,
        "observed_replaced_live_fact_bundle_sha256": current_facts_sha256,
        "vcs_compile_plan_sha256": prior_plan_sha256,
        "attested_simulator_export_context_sha256s": sorted(
            {
                str(value)
                for value in prior_authority.get(
                    "simulator_export_context_sha256s", []
                )
                if str(value)
            }
        ),
        "prior_executed_manifest": {
            "path": str(snapshots[f"executed_manifest_{prior_sha256}.json"]),
            "sha256": prior_sha256,
        },
        "prior_vcs_runner_report": {
            "path": str(snapshots[f"vcs_runner_report_{runner_sha256}.json"]),
            "sha256": runner_sha256,
        },
        "prior_vcs_job_contract": {
            "path": str(snapshots[f"vcs_job_contract_{job_sha256}.json"]),
            "sha256": job_sha256,
        },
        "required_passed_checks": sorted(
            FROZEN_COMPUTE_SLOT_IDENTITY_REQUIRED_CHECKS
        ),
    }
    return attestation, copy.deepcopy(prior_plan)


def materialize_exact_board_preflight_manifest(
    manifest: dict[str, Any],
    normalized_multilayer: dict[str, Any],
    run_dir: Path,
) -> dict[str, Any]:
    """Mechanically bind LLM board outputs to the exact-board preflight contract."""

    from accagent.framework.board_acceptance_contract import (
        PROTOCOL_MONITOR_REPORT_OUTPUT_KEY,
        REQUIRED_PROTOCOL_MONITOR_CHECKS,
        REQUIRED_PROTOCOL_REPORT_FIELDS,
        REQUIRED_TESTBENCH_AST_CHECKS,
        canonical_contract_sha256,
        compile_source_set_fingerprint,
        source_closure_fingerprint,
        validate_exact_board_preflight,
    )

    run_dir = run_dir.resolve()
    board_root = (run_dir / "generated" / "board_integration").resolve()
    identity_path = run_dir / "verification" / "board_interface" / "board_source_identity.json"
    semantic_path = run_dir / "verification" / "semantic_testbench" / "semantic_testbench_manifest.json"
    model_path = run_dir / "input" / "model_config.json"
    catalog_path = run_dir / "verification" / "model_weights" / "transformer_block_weight_catalog.json"
    memory_path = run_dir / "generated" / "chisel" / "memory" / "memory_layout.json"
    runtime_paths = exact_board_memory_runtime_paths(
        run_dir,
        run_dir / "repair_execution",
    )
    output_dir = run_dir / "verification" / "board_simulation"
    output_path = output_dir / "board_simulation_manifest.json"
    materialization_path = output_dir / "board_simulation_preflight_materialization.json"
    blockers: list[str] = []

    identity = read_json_if_exists(identity_path)
    semantic = read_json_if_exists(semantic_path)
    model = read_json_if_exists(model_path)
    catalog = read_json_if_exists(catalog_path)
    plan = manifest.get("board_simulation_preflight_plan")
    if not isinstance(plan, dict):
        plan = {}
        blockers.append("board_simulation_preflight_plan is missing")
    validation_mode = str(plan.get("validation_mode") or "exact_sample_physical_ddr")
    compute_slot_axi_mode = validation_mode == "compute_slot_axi"
    if compute_slot_axi_mode:
        external_fixture, external_fixture_rows, fixture_context_by_hash = {}, [], {}
    else:
        external_fixture, external_fixture_rows, fixture_context_by_hash = (
            _materialize_external_fixture_preflight_selection(plan, run_dir, blockers)
        )

    closure_rows = _exact_board_closure_rows(identity)
    if not closure_rows:
        blockers.append("exact board identity has no selected simulation source closure")
    normalized_closure: list[dict[str, Any]] = []
    for index, row in enumerate(closure_rows):
        normalized = _normalize_exact_board_source(
            row,
            label=f"board identity closure source[{index}]",
            base_dir=identity_path.parent,
            blockers=blockers,
        )
        if normalized is not None:
            normalized_closure.append(normalized)
    compile_closure_rows = [
        row for row in normalized_closure if _exact_board_simulator_compile_input(row)
    ]
    sample_runtime_auxiliary_files: list[dict[str, Any]] = []
    for row in normalized_closure:
        if _exact_board_simulator_compile_input(row):
            continue
        runtime_name = Path(str(row.get("remote_path") or row.get("path") or "")).name
        if not _safe_board_relative_path(runtime_name):
            blockers.append(
                f"sample-project runtime auxiliary source has no safe runtime basename: {row.get('source_id')}"
            )
            continue
        sample_runtime_auxiliary_files.append(
            {**copy.deepcopy(row), "runtime_staged_path": runtime_name}
        )
    if compute_slot_axi_mode:
        sample_runtime_auxiliary_files = []

    closure_hash = source_closure_fingerprint(normalized_closure) if normalized_closure else ""
    declared_closure_hash = str(identity.get("selected_simulation_source_closure_sha256") or "")
    if not closure_hash or declared_closure_hash != closure_hash:
        blockers.append("recomputed exact board source-closure hash does not match board identity")
    abi = identity.get("compute_slot_abi") if isinstance(identity.get("compute_slot_abi"), dict) else {}
    timing = identity.get("timing_contract") if isinstance(identity.get("timing_contract"), dict) else {}
    axi_interfaces = identity.get("axi_interfaces") if isinstance(identity.get("axi_interfaces"), list) else []
    abi_hash = canonical_contract_sha256(abi) if abi else ""
    timing_hash = canonical_contract_sha256(timing) if timing else ""
    axi_hash = canonical_contract_sha256(axi_interfaces) if axi_interfaces else ""
    for field, actual in (
        ("compute_slot_abi_sha256", abi_hash),
        ("timing_contract_sha256", timing_hash),
        ("axi_interfaces_sha256", axi_hash),
    ):
        if not actual or str(identity.get(field) or "") != actual:
            blockers.append(f"recomputed {field} does not match board identity")

    task_card = read_json_if_exists(run_dir / "input" / "task_card.json")
    try:
        board_scope = resolve_board_validation_scope(task_card, model)
    except BoardValidationScopeError as exc:
        blockers.append(f"board validation scope is invalid: {exc}")
        board_scope = None
    model_layers = int(model.get("num_layers") or model.get("num_hidden_layers") or 0)
    catalog_layers = int(catalog.get("target_layer_count") or 0)
    if model_layers <= 0 or catalog_layers != model_layers:
        blockers.append("target model and Transformer-block catalog layer counts are missing or inconsistent")
    target_layers = (
        board_scope.validation_layer_count if board_scope is not None else 0
    )
    validation_layer_indices = (
        list(board_scope.layer_indices) if board_scope is not None else []
    )
    covers_full_model = (
        board_scope.covers_full_model if board_scope is not None else False
    )
    requires_next_layer_prefetch = (
        board_scope.requires_next_layer_prefetch if board_scope is not None else False
    )
    tensor_rows = [row for row in catalog.get("tensors", []) if isinstance(row, dict)]
    complete_catalog_tensor_hashes = sorted(
        {
            str(row.get("source_slice_sha256") or "").lower()
            for row in tensor_rows
            if re.fullmatch(r"[0-9a-fA-F]{64}", str(row.get("source_slice_sha256") or ""))
        }
    )
    if (
        catalog.get("status") != "pass"
        or catalog.get("scope_coverage_complete") is not True
        or catalog.get("accelerator_scope") != "transformer_blocks_only"
        or int(catalog.get("tensor_count") or 0) != len(tensor_rows)
        or len(complete_catalog_tensor_hashes) != len(tensor_rows)
    ):
        blockers.append("complete unique Transformer-block tensor catalog is not hash-valid")
    required_tensor_hashes = sorted(
        {
            str(row.get("source_slice_sha256") or "").lower()
            for row in tensor_rows
            if (
                row.get("layer_index") in validation_layer_indices
                and re.fullmatch(
                    r"[0-9a-fA-F]{64}",
                    str(row.get("source_slice_sha256") or ""),
                )
            )
        }
    )
    catalog_has_explicit_layer_indices = any(
        "layer_index" in row for row in tensor_rows
    )
    if (
        not required_tensor_hashes
        and covers_full_model
        and not catalog_has_explicit_layer_indices
    ):
        # Historical full-model catalogs had no per-tensor layer field. Do not
        # apply this compatibility path to a scoped board workload.
        required_tensor_hashes = complete_catalog_tensor_hashes
    if not required_tensor_hashes:
        blockers.append("board validation scope has no real Transformer-block tensor hashes")
    declared_tensor_hashes = {
        str(value).lower()
        for value in manifest.get("board_consumed_tensor_hashes", [])
        if re.fullmatch(r"[0-9a-fA-F]{64}", str(value))
    }
    if declared_tensor_hashes != set(required_tensor_hashes):
        blockers.append("board binding tensor hashes do not exactly cover the current Transformer-block catalog")

    harness_rows: list[dict[str, Any]] = []
    for index, row in enumerate(normalized_multilayer.get("source_files", [])):
        role = str(row.get("role") or "").lower() if isinstance(row, dict) else ""
        normalized = _normalize_exact_board_source(
            row,
            label=f"multilayer harness source[{index}]",
            base_dir=Path.cwd(),
            blockers=blockers,
            generated_role=role or None,
            allowed_root=None if role == "generated_kernel" else board_root,
        )
        if normalized is not None:
            harness_rows.append(normalized)
    harness = copy.deepcopy(normalized_multilayer)
    harness["source_files"] = harness_rows
    harness["source_set_sha256"] = compile_source_set_fingerprint(harness_rows)
    harness["target_layer_count"] = target_layers

    testbench_plan = plan.get("testbench")
    testbench_source_plan = (
        testbench_plan.get("source")
        if isinstance(testbench_plan, dict)
        and isinstance(testbench_plan.get("source"), dict)
        else testbench_plan
    )
    testbench = _normalize_exact_board_source(
        testbench_source_plan,
        label="board testbench source",
        base_dir=Path.cwd(),
        blockers=blockers,
        generated_role="testbench",
        allowed_root=board_root,
    )
    if testbench is None:
        testbench = (
            copy.deepcopy(testbench_source_plan)
            if isinstance(testbench_source_plan, dict)
            else {}
        )
    if (
        isinstance(testbench_plan, dict)
        and isinstance(testbench_plan.get("source"), dict)
    ):
        testbench.update(
            {
                key: copy.deepcopy(value)
                for key, value in testbench_plan.items()
                if key != "source"
            }
        )
    control = abi.get("control_abi") if isinstance(abi.get("control_abi"), dict) else {}
    testbench.update(
        {
            "timing_contract_sha256": timing_hash,
            "compute_slot_abi_sha256": abi_hash,
            "control_abi_sha256": canonical_contract_sha256(control),
        }
    )
    declared_checkpoint_contract = testbench.get("simulation_checkpoint_contract")
    if isinstance(declared_checkpoint_contract, dict):
        rebound_checkpoint_contract, checkpoint_framework_binding = (
            rebind_checkpoint_framework_adapter_artifacts(
                declared_checkpoint_contract
            )
        )
        testbench["simulation_checkpoint_contract"] = rebound_checkpoint_contract
        blockers.extend(
            "checkpoint framework authority: " + str(error)
            for error in checkpoint_framework_binding.get("errors", [])
            if str(error)
        )
    else:
        checkpoint_framework_binding = {
            "schema_version": (
                "spatialaccagent.checkpoint_framework_adapter_binding.v1"
            ),
            "status": "not_present",
            "changed": False,
            "errors": [],
        }
    if compute_slot_axi_mode:
        testbench.pop("external_simulation_fixture_contract_sha256", None)
        testbench.pop("external_memory_component", None)
        testbench["uses_memory_model_source_ids"] = []
        plan_memory_model = plan.get("compute_slot_axi_transaction_memory_model")
        testbench_memory_model = testbench.get("axi_transaction_memory_model")
        memory_model = (
            copy.deepcopy(plan_memory_model)
            if isinstance(plan_memory_model, dict)
            else {}
        )
        if isinstance(testbench_memory_model, dict):
            for field, value in testbench_memory_model.items():
                if field in memory_model and memory_model[field] != value:
                    blockers.append(
                        "compute-slot AXI transaction-memory declarations conflict "
                        f"for field: {field}"
                    )
                memory_model[field] = copy.deepcopy(value)
        memory_model.update(
            {
                "boundary": "compute_slot_axi",
                "axi_interfaces_sha256": axi_hash,
                "timing_contract_sha256": timing_hash,
            }
        )
        testbench["axi_transaction_memory_model"] = memory_model
    else:
        testbench.update(
            {
                "external_simulation_fixture_contract_sha256": external_fixture.get(
                    "contract_sha256"
                ),
                "external_memory_component": copy.deepcopy(
                    external_fixture.get("model_instance", {})
                ),
            }
        )
    scan = testbench.get("forbidden_construct_scan")
    if isinstance(scan, dict):
        scan = copy.deepcopy(scan)
        scan["source_sha256"] = testbench.get("sha256")
        if compute_slot_axi_mode:
            scan.update(
                {
                    "required": False,
                    "status": "planned",
                    "producer": "existing_simulator_compile",
                }
            )
        if scan.get("required") is True and str(scan.get("method") or "").lower() == "hdl_ast":
            report = scan.get("report_output") if isinstance(scan.get("report_output"), dict) else {}
            report_path = str(report.get("path") or "")
            tool = scan.get("tool") if isinstance(scan.get("tool"), dict) else {}
            invocation = (
                copy.deepcopy(scan.get("invocation"))
                if isinstance(scan.get("invocation"), dict)
                else {}
            )
            argv = [str(value) for value in invocation.get("argv", []) if str(value)]
            argv = [value for value in argv if value not in {"{source}", "{report}"}]
            if argv and argv[0].startswith("-") and str(tool.get("name") or ""):
                argv.insert(0, str(tool["name"]))
            replaced_report = False
            if report_path:
                for index, value in enumerate(argv):
                    if value == report_path:
                        argv[index] = "{report}"
                        replaced_report = True
                        break
            if not replaced_report:
                argv.extend(["--report", "{report}"])
            argv.extend(["--source", "{source}"])
            invocation.update(
                {
                    "argv": argv,
                    "cwd": (
                        invocation.get("cwd")
                        if _safe_board_relative_path(invocation.get("cwd"))
                        else FRAMEWORK_VCS_COMMAND_CWD
                    ),
                    "shell": False,
                }
            )
            scan["invocation"] = invocation
            scan["required_checks"] = sorted(REQUIRED_TESTBENCH_AST_CHECKS)
        testbench["forbidden_construct_scan"] = scan

    monitor_contract = copy.deepcopy(
        plan.get("protocol_monitor_contract")
        if isinstance(plan.get("protocol_monitor_contract"), dict)
        else {}
    )
    monitors = monitor_contract.get("monitors")
    if not isinstance(monitors, list):
        monitors = []
        blockers.append("board protocol_monitor_contract.monitors is missing")
    normalized_monitors: list[dict[str, Any]] = []
    for monitor_index, monitor in enumerate(monitors):
        if not isinstance(monitor, dict):
            blockers.append(f"board protocol monitor[{monitor_index}] is not an object")
            continue
        normalized_monitor = copy.deepcopy(monitor)
        if not str(normalized_monitor.get("interface") or ""):
            normalized_monitor["interface"] = str(
                normalized_monitor.get("interface_name") or ""
            )
        declared_fatal_checks = {
            str(value)
            for value in normalized_monitor.get("fatal_checks", [])
            if str(value)
        }
        nested_contract = (
            normalized_monitor.get("contract")
            if isinstance(normalized_monitor.get("contract"), dict)
            else {}
        )
        declared_fatal_checks.update(
            str(value) for value in nested_contract.get("fatal_checks", []) if str(value)
        )
        structured_checks = [
            copy.deepcopy(value)
            for value in normalized_monitor.get("checks", [])
            if isinstance(value, dict)
        ]
        checks_by_kind = {
            str(value.get("kind") or ""): value
            for value in structured_checks
            if str(value.get("kind") or "")
        }
        for kind in sorted(declared_fatal_checks):
            checks_by_kind[kind] = {
                **copy.deepcopy(checks_by_kind.get(kind, {})),
                "kind": kind,
                "enabled": True,
                "severity": "fatal",
            }
        normalized_monitor["checks"] = [
            checks_by_kind[kind] for kind in sorted(checks_by_kind)
        ]
        structured_report = (
            copy.deepcopy(normalized_monitor.get("structured_report"))
            if isinstance(normalized_monitor.get("structured_report"), dict)
            else copy.deepcopy(nested_contract.get("structured_report", {}))
        )
        if structured_report:
            structured_report["required_fields"] = sorted(
                {
                    str(value)
                    for value in structured_report.get("required_fields", [])
                    if str(value)
                }
                | REQUIRED_PROTOCOL_REPORT_FIELDS
            )
            normalized_monitor["structured_report"] = structured_report
        source_rows = monitor.get("source_files")
        if not isinstance(source_rows, list):
            source_rows = []
            blockers.append(f"board protocol monitor[{monitor_index}].source_files is missing")
        normalized_sources: list[dict[str, Any]] = []
        for source_index, row in enumerate(source_rows):
            normalized = _normalize_exact_board_source(
                row,
                label=f"board protocol monitor[{monitor_index}] source[{source_index}]",
                base_dir=Path.cwd(),
                blockers=blockers,
                generated_role="protocol_monitor",
                allowed_root=board_root,
            )
            if normalized is not None:
                normalized_sources.append(normalized)
        normalized_monitor["source_files"] = normalized_sources
        normalized_monitors.append(normalized_monitor)
    monitor_contract["monitors"] = normalized_monitors
    monitor_contract["axi_interfaces_sha256"] = axi_hash
    expected_axi_names = {
        str(value.get("name") or "") for value in axi_interfaces if str(value.get("name") or "")
    }
    monitor_axi_names = [
        str(value.get("interface") or "")
        for value in normalized_monitors
        if str(value.get("interface") or "")
    ]
    monitor_contract["all_axi_interfaces_covered"] = (
        set(monitor_axi_names) == expected_axi_names
        and len(monitor_axi_names) == len(set(monitor_axi_names))
    )

    generated_rows = [*harness_rows, testbench]
    generated_rows.extend(
        row
        for monitor in normalized_monitors
        for row in monitor.get("source_files", [])
        if isinstance(row, dict)
    )
    generated_rows = [row for row in generated_rows if isinstance(row, dict) and row.get("source_id")]
    generated_by_id = {str(row.get("source_id")): row for row in generated_rows}
    generated_ids = [str(row.get("source_id")) for row in generated_rows]
    if len(generated_ids) != len(set(generated_ids)):
        blockers.append("generated harness/kernel/testbench/monitor source IDs are not unique")
    generated_paths = [str(row.get("path") or "") for row in generated_rows]
    if len(generated_paths) != len(set(generated_paths)):
        blockers.append("generated harness/kernel/testbench/monitor source paths are not unique")
    closure_ids = {
        str(row.get("source_id") or "") for row in normalized_closure if row.get("source_id")
    }
    fixture_ids = [
        str(row.get("source_id") or "")
        for row in external_fixture_rows
        if row.get("source_id")
    ]
    if len(fixture_ids) != len(set(fixture_ids)):
        blockers.append("selected external fixture compiler input IDs are not unique")
    fixture_collisions = set(fixture_ids).intersection(closure_ids | set(generated_ids))
    if fixture_collisions:
        blockers.append(
            f"external fixture source IDs collide with sample/generated sources: {sorted(fixture_collisions)}"
        )

    replaced_ids = [str(value) for value in abi.get("replaced_source_ids", []) if str(value)]
    replacement_plan = plan.get("source_replacements")
    if not isinstance(replacement_plan, list):
        replacement_plan = []
        blockers.append("board_simulation_preflight_plan.source_replacements is missing")
    source_replacements: list[dict[str, Any]] = []
    for index, row in enumerate(replacement_plan):
        if not isinstance(row, dict):
            blockers.append(f"board source replacement[{index}] is not an object")
            continue
        normalized = copy.deepcopy(row)
        normalized["compute_slot_abi_sha256"] = abi_hash
        source_replacements.append(normalized)
    replacement_by_source = {
        str(row.get("replaced_source_id") or ""): row
        for row in source_replacements
        if str(row.get("replaced_source_id") or "")
    }
    if set(replacement_by_source) != set(replaced_ids):
        blockers.append("source replacement plan does not cover exactly compute_slot_abi.replaced_source_ids")

    preserved_rows = [
        row for row in compile_closure_rows if str(row.get("source_id") or "") not in set(replaced_ids)
    ]
    if compute_slot_axi_mode:
        preserved_rows = []
    compile_rows: list[dict[str, Any]] = []
    emitted_generated: set[str] = set()
    if not compute_slot_axi_mode:
        for row in compile_closure_rows:
            source_id = str(row.get("source_id") or "")
            if source_id not in set(replaced_ids):
                compile_rows.append(row)
                continue
            replacement = replacement_by_source.get(source_id, {})
            generated_id = str(replacement.get("generated_source_id") or "")
            generated = generated_by_id.get(generated_id)
            if generated is not None and generated_id not in emitted_generated:
                compile_rows.append(generated)
                emitted_generated.add(generated_id)
        compile_rows.extend(external_fixture_rows)
    for row in generated_rows:
        source_id = str(row.get("source_id") or "")
        if source_id not in emitted_generated:
            compile_rows.append(row)
            emitted_generated.add(source_id)

    compile_plan = copy.deepcopy(
        plan.get("vcs_compile_plan")
        if isinstance(plan.get("vcs_compile_plan"), dict)
        else {}
    )
    facts_path_text = str(identity.get("vivado_facts_path") or "")
    facts_path = Path(facts_path_text).expanduser() if facts_path_text else Path()
    if facts_path_text and not facts_path.is_absolute():
        facts_path = identity_path.parent / facts_path
    facts = read_json_if_exists(facts_path) if facts_path.is_file() else {}
    actual_facts_hash = sha256_file(facts_path) if facts_path.is_file() else ""
    identity_facts_hash = str(identity.get("vivado_facts_sha256") or "")
    frozen_identity_attestation: dict[str, Any] = {}
    if compute_slot_axi_mode:
        frozen_identity_attestation, frozen_compile_plan = (
            materialize_frozen_compute_slot_identity_attestation(
                run_dir=run_dir,
                identity=identity,
                identity_path=identity_path,
                current_facts_sha256=actual_facts_hash,
            )
        )
        if frozen_identity_attestation:
            compile_plan = frozen_compile_plan
    if compile_plan.get("schema_version") != "spatialaccagent.vcs_compile_plan.v1":
        blockers.append("board_simulation_preflight_plan.vcs_compile_plan schema_version is missing or unsupported")
    if compile_plan.get("status") != "ready":
        blockers.append("board_simulation_preflight_plan.vcs_compile_plan.status is not ready")
    tool_profile_path = run_dir / "input" / "tool_profile.json"
    tool_profile = read_json_if_exists(tool_profile_path)
    configured_tools = [
        row
        for row in tool_profile.get("tools", [])
        if isinstance(row, dict) and row.get("role") == "functional_verification"
    ]
    configured_tool = configured_tools[0] if len(configured_tools) == 1 else {}
    if len(configured_tools) != 1:
        blockers.append("tool_profile must contain exactly one configured functional_verification tool")
    planned_tool = (
        compile_plan.get("tool_binding")
        if isinstance(compile_plan.get("tool_binding"), dict)
        else {}
    )
    for field in ("role", "name", "host", "port", "executable"):
        if not configured_tool or planned_tool.get(field) != configured_tool.get(field):
            blockers.append(f"vcs_compile_plan.tool_binding.{field} does not match current tool_profile")
    compile_top = str(compile_plan.get("top_module") or "")
    planned_top = str(plan.get("top_module") or "")
    if not compile_top or compile_top != planned_top:
        blockers.append("vcs_compile_plan.top_module does not match the generated board testbench top")
    expected_compile_by_id = {
        str(row.get("source_id") or ""): row
        for row in [*preserved_rows, *external_fixture_rows, *generated_rows]
        if str(row.get("source_id") or "")
    }
    export_contexts = (
        facts.get("simulation", {}).get("simulator_export_contexts", [])
        if isinstance(facts.get("simulation"), dict)
        else []
    )
    context_by_hash: dict[str, str] = {}
    for index, row in enumerate(export_contexts):
        if not isinstance(row, dict):
            blockers.append(f"Vivado simulator export context[{index}] is not an object")
            continue
        context_hash = str(row.get("sha256") or "").lower()
        context_text = str(row.get("text") or "")
        actual_context_hash = hashlib.sha256(context_text.encode("utf-8")).hexdigest()
        if not context_text or context_hash != actual_context_hash:
            blockers.append(f"Vivado simulator export context[{index}] text/hash binding is invalid")
            continue
        context_by_hash[context_hash] = context_text
    if not context_by_hash and not frozen_identity_attestation:
        blockers.append("Vivado fact bundle has no hash-bound VCS export command context")
    if (
        not facts
        or not actual_facts_hash
        or (
            actual_facts_hash != identity_facts_hash
            and not frozen_identity_attestation
        )
    ):
        blockers.append("board identity Vivado fact bundle is missing or hash-invalid")
    authority = (
        compile_plan.get("compile_authority")
        if isinstance(compile_plan.get("compile_authority"), dict)
        else {}
    )
    declared_context_hashes = authority.get("simulator_export_context_sha256s")
    expected_context_hashes = (
        set(
            map(
                str,
                frozen_identity_attestation.get(
                    "attested_simulator_export_context_sha256s", []
                ),
            )
        )
        if frozen_identity_attestation
        else set(context_by_hash)
    )
    if (
        authority.get("vivado_facts_path") != facts_path_text
        or authority.get("vivado_facts_sha256") != identity_facts_hash
        or not isinstance(declared_context_hashes, list)
        or set(map(str, declared_context_hashes)) != expected_context_hashes
    ):
        blockers.append("vcs_compile_plan.compile_authority does not bind the exact Vivado export facts")
    declared_fixture_context_hashes = authority.get(
        "external_fixture_export_context_sha256s"
    )
    if compute_slot_axi_mode:
        if authority.get("external_fixture_contract_sha256") not in (None, "") or (
            declared_fixture_context_hashes not in (None, [])
        ):
            blockers.append(
                "compute_slot_axi compile authority must not bind external fixture sources"
            )
    elif (
        authority.get("external_fixture_contract_sha256")
        != external_fixture.get("contract_sha256")
        or not isinstance(declared_fixture_context_hashes, list)
        or set(map(str, declared_fixture_context_hashes))
        != set(fixture_context_by_hash)
    ):
        blockers.append(
            "vcs_compile_plan.compile_authority does not bind the exact external fixture export"
        )
    combined_context_by_hash = {**context_by_hash, **fixture_context_by_hash}

    ordered_commands = compile_plan.get("ordered_commands")
    if not isinstance(ordered_commands, list) or not ordered_commands:
        ordered_commands = []
        blockers.append("vcs_compile_plan.ordered_commands is missing or empty")
    ordered_source_ids: list[str] = []
    compile_commands: list[dict[str, Any]] = []
    elaboration_commands: list[dict[str, Any]] = []
    fixture_include_ids = {
        str(row.get("include_dir_id") or "")
        for row in external_fixture.get("include_directories", [])
        if isinstance(row, dict) and str(row.get("include_dir_id") or "")
    }
    shell_tokens = {"|", "||", "&&", ";", ">", ">>", "<", "<<"}
    for index, command in enumerate(ordered_commands):
        label = f"vcs_compile_plan.ordered_commands[{index}]"
        if not isinstance(command, dict):
            blockers.append(f"{label} is not an object")
            continue
        if command.get("order") != index:
            blockers.append(f"{label}.order is not contiguous")
        phase = str(command.get("phase") or "")
        if phase not in {"compile", "elaborate"}:
            blockers.append(f"{label}.phase is neither compile nor elaborate")
        elif phase == "compile":
            compile_commands.append(command)
        else:
            elaboration_commands.append(command)
        if command.get("tool_role") != "functional_verification":
            blockers.append(f"{label}.tool_role does not bind the configured simulator")
        executable = str(command.get("executable") or "")
        if (
            not executable
            or any(value in executable for value in ("\x00", "\n", "\r"))
            or any(char.isspace() for char in executable)
        ):
            blockers.append(f"{label}.executable is missing or unsafe")
        refs = command.get("authority_refs")
        ref_set = {str(value) for value in refs} if isinstance(refs, list) else set()
        authorized_context_hashes = (
            expected_context_hashes | set(fixture_context_by_hash)
            if frozen_identity_attestation
            else set(combined_context_by_hash)
        )
        if not ref_set or not ref_set.issubset(authorized_context_hashes):
            blockers.append(f"{label}.authority_refs do not bind Vivado-exported VCS commands")
        elif (
            not frozen_identity_attestation
            and executable != str(configured_tool.get("executable") or "")
            and not any(
                re.search(
                    rf"(?:^|[\s'\"=]){re.escape(executable)}(?:$|[\s'\"\\])",
                    combined_context_by_hash[ref],
                    flags=re.MULTILINE,
                )
                for ref in ref_set
            )
        ):
            blockers.append(f"{label}.executable is not authorized by tool_profile or referenced Vivado export")
        if command.get("shell") is not False:
            blockers.append(f"{label}.shell must be false")
        if not _safe_board_relative_path(command.get("cwd")):
            blockers.append(f"{label}.cwd is not a safe relative staging path")
        env = command.get("env")
        if not isinstance(env, dict) or not all(
            isinstance(key, str)
            and key
            and "=" not in key
            and isinstance(value, str)
            and "\x00" not in value
            for key, value in env.items()
        ):
            blockers.append(f"{label}.env is not a safe string mapping")
        argv = command.get("argv")
        if not isinstance(argv, list) or not argv:
            blockers.append(f"{label}.argv is missing or empty")
            argv = []
        token_source_ids: list[str] = []
        token_include_ids: list[str] = []
        literal_argv: list[str] = []
        for token_index, token in enumerate(argv):
            if isinstance(token, str):
                literal_argv.append(token)
                if (
                    not token
                    or any(value in token for value in ("\x00", "\n", "\r"))
                    or token in shell_tokens
                ):
                    blockers.append(f"{label}.argv[{token_index}] is an unsafe shell/redirection token")
            elif isinstance(token, dict) and set(token) == {"source_id"}:
                source_id = str(token.get("source_id") or "")
                token_source_ids.append(source_id)
                if not source_id:
                    blockers.append(f"{label}.argv[{token_index}].source_id is missing")
            elif isinstance(token, dict) and set(token) == {"include_dir_id"}:
                include_dir_id = str(token.get("include_dir_id") or "")
                token_include_ids.append(include_dir_id)
                if not include_dir_id or include_dir_id not in fixture_include_ids:
                    blockers.append(
                        f"{label}.argv[{token_index}].include_dir_id is not fixture-authorized"
                    )
            else:
                blockers.append(
                    f"{label}.argv[{token_index}] is not a literal, source_id, or include_dir_id token"
                )
        source_ids = command.get("source_ids")
        if not isinstance(source_ids, list) or list(map(str, source_ids)) != token_source_ids:
            blockers.append(f"{label}.source_ids do not exactly match argv source tokens")
        if phase == "compile":
            if not token_source_ids:
                blockers.append(f"{label} compile command has no source token")
            if set(token_source_ids).intersection(fixture_ids) and not ref_set.intersection(
                fixture_context_by_hash
            ):
                blockers.append(
                    f"{label} external fixture compiler inputs are not bound to their export context"
                )
            ordered_source_ids.extend(token_source_ids)
        elif token_source_ids:
            blockers.append(f"{label} elaboration command must not compile source tokens")
        if phase != "compile" and token_include_ids:
            blockers.append(f"{label} include-directory tokens are valid only for compile commands")
        command["_validated_literal_argv"] = literal_argv

    if (
        len(ordered_source_ids) != len(set(ordered_source_ids))
        or set(ordered_source_ids) != set(expected_compile_by_id)
    ):
        blockers.append(
            "vcs_compile_plan ordered compile commands must cover every transformed source ID exactly once"
        )
    if set(ordered_source_ids).intersection(replaced_ids):
        blockers.append("vcs_compile_plan ordered commands reference a replaced sample-project source")
    if (
        ordered_source_ids
        and set(ordered_source_ids) == set(expected_compile_by_id)
        and len(ordered_source_ids) == len(set(ordered_source_ids))
    ):
        compile_rows = [expected_compile_by_id[source_id] for source_id in ordered_source_ids]
    output_name = str(compile_plan.get("output") or "")
    if output_name != "simv":
        blockers.append("vcs_compile_plan.output must be the safe simulator artifact simv")
    if len(elaboration_commands) != 1 or not ordered_commands or ordered_commands[-1] not in elaboration_commands:
        blockers.append("vcs_compile_plan must end with exactly one elaboration command")
    elif (
        planned_top not in elaboration_commands[0].get("_validated_literal_argv", [])
        or output_name not in elaboration_commands[0].get("_validated_literal_argv", [])
    ):
        blockers.append("vcs_compile_plan elaboration argv does not bind top_module and simv output")
    if (
        not compute_slot_axi_mode
        and len(compile_commands) == 1
        and len(expected_compile_by_id) > 1
    ):
        fallback_literals = compile_commands[0].get("_validated_literal_argv", [])
        if (
            compile_commands[0].get("executable") == configured_tool.get("executable")
            and "-sverilog" in fallback_literals
        ):
            blockers.append("vcs_compile_plan cannot collapse the Vivado export into a single -sverilog fallback")
    for command in ordered_commands:
        if isinstance(command, dict):
            command.pop("_validated_literal_argv", None)
    compile_plan["tool_profile_sha256"] = (
        sha256_file(tool_profile_path) if tool_profile_path.is_file() else None
    )

    evidence_records = copy.deepcopy(
        plan.get("generated_evidence_records")
        if isinstance(plan.get("generated_evidence_records"), list)
        else []
    )
    if not evidence_records:
        blockers.append("board_simulation_preflight_plan.generated_evidence_records is empty")
    for index, row in enumerate(evidence_records):
        if not isinstance(row, dict):
            blockers.append(f"generated evidence record[{index}] is not an object")
            continue
        source_id = str(row.get("source_id") or "")
        source = generated_by_id.get(source_id, {})
        if not source or str(row.get("source_sha256") or "").lower() != str(source.get("sha256") or "").lower():
            blockers.append(f"generated evidence record[{index}] does not hash-bind its generated source")

    integration = copy.deepcopy(
        manifest.get("board_integration_contract")
        if isinstance(manifest.get("board_integration_contract"), dict)
        else {}
    )
    runtime_contract = read_json_if_exists(runtime_paths["contract"])
    runtime_image_manifest = read_json_if_exists(
        runtime_paths["runtime_image_manifest"]
    )
    memory_hash = sha256_file(memory_path) if memory_path.is_file() else ""
    for field, expected in (
        ("source_closure_sha256", closure_hash),
        ("compute_slot_abi_sha256", abi_hash),
        ("timing_contract_sha256", timing_hash),
        ("axi_interfaces_sha256", axi_hash),
        ("memory_layout_sha256", memory_hash),
    ):
        if not expected or str(integration.get(field) or "") != expected:
            blockers.append(f"board integration contract does not bind recomputed {field}")
        integration[field] = expected

    for field, path in (
        ("board_memory_runtime_contract_sha256", runtime_paths["contract"]),
        ("full_weight_image_manifest_sha256", runtime_paths["image_manifest"]),
        ("full_weight_image_sha256", runtime_paths["image"]),
    ):
        expected = sha256_file(path) if path.is_file() else ""
        if not expected:
            blockers.append(f"framework-owned board artifact is unavailable for {field}")
        integration[field] = expected
    if runtime_paths["runtime_capture"].is_file():
        integration["full_layer_runtime_capture_contract_sha256"] = sha256_file(
            runtime_paths["runtime_capture"]
        )

    runtime_constants = (
        runtime_contract.get("runtime_constants", {})
        if isinstance(runtime_contract.get("runtime_constants"), dict)
        else {}
    )
    runtime_enabled = runtime_constants.get("enabled") is True
    runtime_plan_artifact = {
        "path": str(runtime_paths["contract"]),
        "sha256": (
            sha256_file(runtime_paths["contract"])
            if runtime_paths["contract"].is_file()
            else ""
        ),
    }
    runtime_constant_binding: dict[str, Any] = {
        "enabled": runtime_enabled,
        "board_memory_runtime_contract": runtime_plan_artifact,
    }
    runtime_implementation = copy.deepcopy(
        integration.get("runtime_constants")
        if isinstance(integration.get("runtime_constants"), dict)
        else {}
    )
    runtime_implementation["enabled"] = runtime_enabled
    runtime_image_artifact: dict[str, Any] = {}
    if runtime_enabled:
        runtime_manifest_artifact = {
            "path": str(runtime_paths["runtime_image_manifest"]),
            "sha256": (
                sha256_file(runtime_paths["runtime_image_manifest"])
                if runtime_paths["runtime_image_manifest"].is_file()
                else ""
            ),
        }
        runtime_image_artifact = {
            "path": str(runtime_paths["runtime_image"]),
            "sha256": (
                sha256_file(runtime_paths["runtime_image"])
                if runtime_paths["runtime_image"].is_file()
                else ""
            ),
            "byte_count": (
                runtime_paths["runtime_image"].stat().st_size
                if runtime_paths["runtime_image"].is_file()
                else 0
            ),
        }
        runtime_constant_binding.update(
            {
                "runtime_image_manifest": runtime_manifest_artifact,
                "runtime_image": runtime_image_artifact,
            }
        )
        integration.update(
            {
                "full_runtime_image_manifest_sha256": runtime_manifest_artifact[
                    "sha256"
                ],
                "full_runtime_image_sha256": runtime_image_artifact["sha256"],
            }
        )
        runtime_implementation.update(
            {
                "runtime_plan_contract_sha256": runtime_contract.get(
                    "contract_sha256"
                ),
                "runtime_image_manifest_sha256": runtime_manifest_artifact[
                    "sha256"
                ],
                "runtime_image_manifest_contract_sha256": runtime_image_manifest.get(
                    "manifest_contract_sha256"
                ),
                "runtime_image_sha256": runtime_image_artifact["sha256"],
                "connected_runtime_stream_contract_sha256": runtime_constants.get(
                    "connected_runtime_stream_contract_sha256"
                ),
                "loader_abi_sha256": canonical_contract_sha256(
                    runtime_constants.get("loader_abi", {})
                ),
                "load_schedule_sha256": canonical_contract_sha256(
                    runtime_constants.get("load_schedule", [])
                ),
            }
        )
    integration["runtime_constants"] = runtime_implementation

    if semantic.get("status") != "ready":
        blockers.append("semantic testbench manifest is not ready")
    board_semantic = semantic.get("board") if isinstance(semantic.get("board"), dict) else {}
    semantic_reference_captured = (
        board_semantic.get("all_target_layer_reference_captured") is True
        if covers_full_model
        else board_semantic.get("scoped_layer_reference_captured") is True
    )
    if (
        not semantic_reference_captured
        or int(board_semantic.get("expected_target_layers") or 0) != target_layers
    ):
        blockers.append("semantic board artifacts do not cover the current validation scope")
    input_artifact = _normalize_exact_board_artifact(
        board_semantic.get("input_vector"),
        label="semantic board input vector",
        base_dir=semantic_path.parent,
        blockers=blockers,
    )
    expected_artifact = _normalize_exact_board_artifact(
        board_semantic.get("expected_output"),
        label="semantic board expected output",
        base_dir=semantic_path.parent,
        blockers=blockers,
    )
    plan_artifacts = plan.get("artifacts") if isinstance(plan.get("artifacts"), dict) else {}
    authoritative_weight_manifest = read_json_if_exists(runtime_paths["image_manifest"])
    if authoritative_weight_manifest.get("status") != "pass":
        blockers.append("framework full-weight image manifest is missing or is not pass")
    weight_artifact = _normalize_exact_board_artifact(
        authoritative_board_weight_artifact(authoritative_weight_manifest),
        label="framework-materialized complete board weight image",
        base_dir=run_dir,
        blockers=blockers,
    )
    for name, semantic_artifact in (
        ("input", input_artifact),
        ("expected_output", expected_artifact),
    ):
        planned = plan_artifacts.get(name)
        if isinstance(planned, dict) and semantic_artifact is not None:
            if (
                str(planned.get("sha256") or "") != semantic_artifact.get("sha256")
                or Path(str(planned.get("path") or "")).resolve()
                != Path(str(semantic_artifact.get("path") or "")).resolve()
            ):
                blockers.append(f"board preflight planned {name} differs from immutable semantic artifact")
    planned_weight_artifact = plan_artifacts.get("weight_image")
    if isinstance(planned_weight_artifact, dict) and weight_artifact is not None:
        planned_path = str(planned_weight_artifact.get("path") or "")
        if planned_path:
            candidate = Path(planned_path)
            candidate = candidate if candidate.is_absolute() else run_dir / candidate
            if candidate.resolve() != Path(str(weight_artifact.get("path") or "")).resolve():
                blockers.append(
                    "board preflight planned weight_image.path differs from immutable framework authority"
                )
        planned_sha = str(planned_weight_artifact.get("sha256") or "")
        if planned_sha and planned_sha != str(weight_artifact.get("sha256") or ""):
            blockers.append(
                "board preflight planned weight_image.sha256 differs from immutable framework authority"
            )
    if weight_artifact is not None:
        packed_hashes = {
            str(value).lower()
            for value in weight_artifact.get(
                "packed_tensor_hashes", weight_artifact.get("tensor_hashes", [])
            )
            if re.fullmatch(r"[0-9a-fA-F]{64}", str(value))
        }
        if (
            weight_artifact.get("scope_coverage_complete") is not True
            or weight_artifact.get("accelerator_scope") != "transformer_blocks_only"
            or weight_artifact.get("accelerator_weight_catalog_sha256")
            != (sha256_file(catalog_path) if catalog_path.is_file() else None)
            or weight_artifact.get("source_checkpoint_sha256")
            != catalog.get("source_checkpoint_sha256")
            or packed_hashes != set(required_tensor_hashes)
        ):
            blockers.append("complete board weight image is not bound to every current Transformer-block tensor")
        authoritative_image_path = Path(
            str(authoritative_weight_manifest.get("path") or "")
        )
        if (
            authoritative_weight_manifest.get("status") != "pass"
            or not authoritative_image_path.is_absolute()
            or authoritative_image_path.resolve()
            != Path(str(weight_artifact.get("path") or "")).resolve()
            or authoritative_weight_manifest.get("image_sha256")
            != weight_artifact.get("sha256")
            or authoritative_weight_manifest.get("manifest_contract_sha256")
            != weight_artifact.get("manifest_contract_sha256")
            or authoritative_weight_manifest.get("total_bytes")
            != weight_artifact.get("total_bytes")
            or authoritative_weight_manifest.get("layer_segments")
            != weight_artifact.get("layer_segments")
        ):
            blockers.append(
                "board preflight weight image differs from the framework-materialized current authority"
            )

    execution_outputs = copy.deepcopy(
        plan.get("execution_outputs")
        if isinstance(plan.get("execution_outputs"), dict)
        else {}
    )
    protocol_reports = execution_outputs.get(PROTOCOL_MONITOR_REPORT_OUTPUT_KEY)
    if not isinstance(protocol_reports, list):
        alias_reports = execution_outputs.pop("protocol_reports", None)
        protocol_reports = alias_reports if isinstance(alias_reports, list) else []
    reports_by_interface = {
        str(value.get("interface") or value.get("interface_name") or ""): copy.deepcopy(value)
        for value in protocol_reports
        if isinstance(value, dict)
        and str(value.get("interface") or value.get("interface_name") or "")
    }
    for monitor in normalized_monitors:
        interface_name = str(monitor.get("interface") or "")
        report = monitor.get("structured_report")
        if not interface_name or not isinstance(report, dict):
            continue
        reports_by_interface[interface_name] = {
            **reports_by_interface.get(interface_name, {}),
            "interface": interface_name,
            "path": report.get("path"),
            "schema_version": report.get("schema_version"),
        }
    execution_outputs[PROTOCOL_MONITOR_REPORT_OUTPUT_KEY] = [
        reports_by_interface[name] for name in sorted(reports_by_interface)
    ]
    if not execution_outputs:
        blockers.append("board_simulation_preflight_plan.execution_outputs is missing")
    output_paths: list[str] = []
    protocol_report_aliases = {
        (
            str(row.get("path") or ""),
            str(row.get("schema_version") or ""),
        )
        for row in execution_outputs[PROTOCOL_MONITOR_REPORT_OUTPUT_KEY]
        if isinstance(row, dict)
    }

    def validate_output_paths(value: Any, label: str) -> None:
        if isinstance(value, dict):
            for key, item in value.items():
                if key == "path":
                    if not _safe_board_relative_path(item):
                        blockers.append(f"{label}.path is not a safe relative output path")
                    elif (
                        label == "execution_outputs.axi_protocol_report"
                        and (
                            str(item),
                            str(value.get("schema_version") or ""),
                        )
                        in protocol_report_aliases
                    ):
                        continue
                    else:
                        output_paths.append(str(Path(str(item))))
                else:
                    validate_output_paths(item, f"{label}.{key}")
        elif isinstance(value, list):
            for index, item in enumerate(value):
                validate_output_paths(item, f"{label}[{index}]")

    validate_output_paths(execution_outputs, "execution_outputs")
    if len(output_paths) != len(set(output_paths)):
        blockers.append("board execution output paths are not unique")

    top_module = str(plan.get("top_module") or "").strip()
    if not top_module:
        blockers.append("board_simulation_preflight_plan.top_module is missing")
    pass_regex = str(plan.get("pass_regex") or "")
    if not pass_regex:
        blockers.append("board_simulation_preflight_plan.pass_regex is missing")
    rtl_output_file = plan.get("rtl_output_file")
    boundary_trace_file = plan.get("boundary_trace_file")
    for field, value in (
        ("rtl_output_file", rtl_output_file),
        ("boundary_trace_file", boundary_trace_file),
    ):
        if not _safe_board_relative_path(value):
            blockers.append(f"board_simulation_preflight_plan.{field} is unsafe or missing")
    vcs = copy.deepcopy(plan.get("vcs") if isinstance(plan.get("vcs"), dict) else {})
    if not isinstance(vcs.get("compile_args"), list) or not all(
        isinstance(value, str) for value in vcs.get("compile_args", [])
    ):
        blockers.append("board_simulation_preflight_plan.vcs.compile_args must be a string list")
    runtime_plusargs = vcs.get("runtime_plusargs")
    if not isinstance(runtime_plusargs, dict) or not runtime_plusargs or not all(
        isinstance(key, str)
        and key
        and isinstance(value, str)
        and value in {"input", "weight_image", "runtime_image", "expected_output"}
        for key, value in runtime_plusargs.items()
    ):
        blockers.append("board_simulation_preflight_plan.vcs.runtime_plusargs is invalid")
    elif runtime_enabled and "runtime_image" not in set(runtime_plusargs.values()):
        blockers.append(
            "board_simulation_preflight_plan.vcs.runtime_plusargs does not stage the runtime image"
        )

    board_manifest = {
        "schema_version": "spatialaccagent.board_simulation_manifest.v1",
        "validation_mode": validation_mode,
        "status": "ready" if not blockers else "incomplete",
        **(
            {
                "frozen_compute_slot_identity_attestation": frozen_identity_attestation
            }
            if frozen_identity_attestation
            else {}
        ),
        "exact_sample_wrapper_unmodified": True,
        "source_identity_sha256": sha256_file(identity_path) if identity_path.is_file() else None,
        "source_files": compile_rows,
        "compile_source_ids": [str(row.get("source_id")) for row in compile_rows],
        "compiled_sample_source_ids": [str(row.get("source_id")) for row in preserved_rows],
        "replaced_sample_source_ids": replaced_ids,
        "generated_source_ids": generated_ids,
        **(
            {"external_simulation_fixture": external_fixture}
            if not compute_slot_axi_mode
            else {}
        ),
        "sample_runtime_auxiliary_files": sample_runtime_auxiliary_files,
        "source_replacements": source_replacements,
        "synthesis_sources_excluded": True,
        "source_closure_sha256": closure_hash,
        "compile_source_set_sha256": compile_source_set_fingerprint(compile_rows),
        "compute_slot_abi_sha256": abi_hash,
        "timing_contract_sha256": timing_hash,
        "axi_interfaces_sha256": axi_hash,
        "multilayer_harness": harness,
        "model_layer_count": model_layers,
        "validation_layer_indices": validation_layer_indices,
        "all_target_layers": covers_full_model,
        "target_layer_count": target_layers,
        "bound_layer_count": target_layers,
        "board_consumed_tensor_hashes": required_tensor_hashes,
        "board_integration_contract": integration,
        "board_integration_contract_sha256": canonical_contract_sha256(integration),
        "runtime_constant_binding": runtime_constant_binding,
        "checkpoint_framework_authority_binding": copy.deepcopy(
            checkpoint_framework_binding
        ),
        "testbench": testbench,
        "top_module": top_module,
        "protocol_monitor_contract": monitor_contract,
        "protocol_monitor_contract_sha256": canonical_contract_sha256(monitor_contract),
        "generated_evidence_records": evidence_records,
        "execution_outputs": execution_outputs,
        "vcs_compile_plan": compile_plan,
        "vcs_compile_plan_sha256": canonical_contract_sha256(compile_plan),
        "artifacts": {
            "input": input_artifact or {},
            "weight_image": weight_artifact or {},
            **({"runtime_image": runtime_image_artifact} if runtime_enabled else {}),
            "expected_output": expected_artifact or {},
        },
        "semantic_testbench_manifest": {
            "path": str(semantic_path),
            "sha256": sha256_file(semantic_path) if semantic_path.is_file() else None,
        },
        "pass_regex": pass_regex,
        "rtl_output_file": rtl_output_file,
        "boundary_trace_file": boundary_trace_file,
        "vcs": vcs,
        **(
            {"remote_workdir": plan.get("remote_workdir")}
            if plan.get("remote_workdir") is not None
            else {}
        ),
    }
    write_json(output_path, board_manifest)
    preflight = validate_exact_board_preflight(identity_path, output_path)
    blockers.extend(str(value) for value in preflight.get("blockers", []) if str(value))
    blockers = list(dict.fromkeys(blockers))
    status = "pass" if not blockers and preflight.get("status") == "pass" else "incomplete"
    report = {
        "schema_version": "spatialaccagent.board_simulation_preflight_materialization.v1",
        "status": status,
        "manifest": str(output_path),
        "manifest_sha256": sha256_file(output_path),
        "manifest_status": board_manifest.get("status"),
        "vcs_compile_plan_sha256": board_manifest.get("vcs_compile_plan_sha256"),
        "exact_board_preflight": preflight,
        "checkpoint_framework_authority_binding": copy.deepcopy(
            checkpoint_framework_binding
        ),
        "blockers": blockers,
    }
    write_json(materialization_path, report)
    report["path"] = str(materialization_path)
    return report


def _path_within_root(path: Path, root: Path) -> bool:
    try:
        path.resolve().relative_to(root.resolve())
    except (OSError, ValueError):
        return False
    return True


def _certificate_snapshot_document(
    certificate: dict[str, Any],
    predicate: Any,
) -> tuple[Path, dict[str, Any]] | None:
    binding = (
        certificate.get("evidence_binding", {})
        if isinstance(certificate.get("evidence_binding"), dict)
        else {}
    )
    candidates: list[tuple[str, Path, dict[str, Any]]] = []
    for row in binding.get("file_bindings", []):
        if not isinstance(row, dict):
            continue
        path_text = str(row.get("path") or "")
        expected_hash = str(row.get("sha256") or "").lower()
        if not path_text or not is_sha256(expected_hash):
            continue
        path = Path(path_text)
        if not path.is_file():
            continue
        try:
            if sha256_file(path) != expected_hash:
                continue
        except OSError:
            continue
        document = read_json_if_exists(path)
        if predicate(document):
            candidates.append((str(path.resolve()), path.resolve(), document))
    if not candidates:
        return None
    _, path, document = sorted(candidates, key=lambda item: item[0])[0]
    return path, document


def _operator_leaf_requirements_projection(document: dict[str, Any]) -> dict[str, Any]:
    fields = (
        "accelerator_scope",
        "accelerator_weight_catalog_sha256",
        "canonical_weight_stream_contract",
        "model_semantic_adapter_sha256",
        "numeric_policy_sha256",
        "pipeline_plan_sha256",
        "reference_operator_semantics",
        "semantic_runtime_constant_contract",
        "source_checkpoint_sha256",
        "source_reference_sha256",
        "stage_requirements",
        "stream_metadata_contract",
        "transcendental_approximation_contract",
    )
    return {field: copy.deepcopy(document.get(field)) for field in fields}


def _operator_leaf_stage_contract_projection(contract: dict[str, Any]) -> dict[str, Any]:
    fields = (
        "expected_output",
        "input_vectors",
        "numeric_contract",
        "op",
        "real_weight_bindings",
        "real_weight_stream",
        "runtime_constant_contract_sha256",
        "runtime_constant_stream",
        "schema_version",
        "source_reference_manifest",
        "source_reference_sha256",
        "stage_id",
        "status",
        "weight_layout",
        "weight_layout_contract_sha256",
    )
    projection = {field: copy.deepcopy(contract.get(field)) for field in fields}
    harness = contract.get("dut_harness", {})
    harness = harness if isinstance(harness, dict) else {}
    projection["dut_harness"] = {
        "consumed_tensor_hashes": copy.deepcopy(
            harness.get("consumed_tensor_hashes", [])
        ),
        "top_module": harness.get("top_module"),
    }
    return projection


def _operator_leaf_higher_scope_semantic_artifact(
    path: Path,
    run_dir: Path,
) -> bool:
    """Return whether a generated semantic artifact belongs to a higher scope.

    Operator-leaf certificates must continue to bind their own sources, vectors,
    streams, and reference outputs.  The shared semantic generator also emits
    connected-layer and board vectors, which are not part of the leaf result and
    can legitimately change while a leaf certificate is reused.
    """

    semantic_root = (run_dir / "verification" / "semantic_testbench").resolve()
    try:
        relative = path.resolve().relative_to(semantic_root)
    except (OSError, ValueError):
        return False
    return bool(relative.parts and relative.parts[0] in {"single_layer", "board"})


def _operator_leaf_live_file_rows(
    snapshot_manifest: dict[str, Any],
    run_dir: Path,
) -> tuple[list[dict[str, str]], list[str]]:
    errors: list[str] = []
    rows_by_path: dict[str, dict[str, str]] = {}

    def add_file(
        path_value: Any,
        expected_hash: Any,
        *,
        role: str,
        stage_id: str,
    ) -> None:
        path_text = str(path_value or "")
        expected = str(expected_hash or "").lower()
        if not path_text or not is_sha256(expected):
            errors.append(f"{stage_id}: certified {role} file path/hash is incomplete")
            return
        path = Path(path_text)
        if not path.is_absolute() or not _path_within_root(path, run_dir):
            errors.append(f"{stage_id}: certified {role} is outside the run directory")
            return
        if not path.is_file():
            errors.append(f"{stage_id}: certified {role} file is missing: {path}")
            return
        try:
            actual = sha256_file(path)
        except OSError as exc:
            errors.append(f"{stage_id}: certified {role} file is unreadable: {path}: {exc}")
            return
        if actual != expected:
            errors.append(f"{stage_id}: certified {role} file hash drift: {path}")
            return
        key = str(path.resolve())
        previous = rows_by_path.get(key)
        row = {
            "stage_id": stage_id,
            "path": key,
            "role": role,
            "sha256": actual,
        }
        if previous is not None and previous["sha256"] != actual:
            errors.append(f"{stage_id}: conflicting certified file hashes: {path}")
            return
        rows_by_path.setdefault(key, row)

    contracts = snapshot_manifest.get("stage_contracts", [])
    if not isinstance(contracts, list) or not contracts:
        return [], ["certified semantic-testbench snapshot has no operator stage contracts"]
    seen_stage_ids: set[str] = set()
    for contract in contracts:
        if not isinstance(contract, dict):
            errors.append("certified semantic-testbench snapshot has an invalid stage contract")
            continue
        stage_id = str(contract.get("stage_id") or "")
        if not stage_id or stage_id in seen_stage_ids:
            errors.append("certified semantic-testbench snapshot has duplicate or missing stage IDs")
            continue
        seen_stage_ids.add(stage_id)
        if contract.get("status") != "ready":
            errors.append(f"{stage_id}: certified semantic-testbench contract is not ready")
            continue
        harness = contract.get("dut_harness", {})
        harness = harness if isinstance(harness, dict) else {}
        source_files = harness.get("source_files", [])
        if not isinstance(source_files, list) or not source_files:
            errors.append(f"{stage_id}: certified semantic harness source list is missing")
        for source in source_files if isinstance(source_files, list) else []:
            if not isinstance(source, dict):
                errors.append(f"{stage_id}: certified semantic harness source entry is invalid")
                continue
            add_file(
                source.get("path"),
                source.get("sha256"),
                role="semantic_harness_source",
                stage_id=stage_id,
            )
        add_file(
            contract.get("testbench"),
            contract.get("testbench_sha256"),
            role="semantic_testbench",
            stage_id=stage_id,
        )
        add_file(
            contract.get("source_reference_manifest"),
            contract.get("source_reference_sha256"),
            role="target_model_reference",
            stage_id=stage_id,
        )
        expected_output = contract.get("expected_output", {})
        if isinstance(expected_output, dict):
            add_file(
                expected_output.get("path"),
                expected_output.get("sha256"),
                role="golden_output",
                stage_id=stage_id,
            )
        else:
            errors.append(f"{stage_id}: certified golden output descriptor is missing")
        input_vectors = contract.get("input_vectors", [])
        if not isinstance(input_vectors, list) or not input_vectors:
            errors.append(f"{stage_id}: certified input-vector descriptors are missing")
        for vector in input_vectors if isinstance(input_vectors, list) else []:
            if not isinstance(vector, dict):
                errors.append(f"{stage_id}: certified input-vector descriptor is invalid")
                continue
            add_file(
                vector.get("path"),
                vector.get("sha256"),
                role="input_vector",
                stage_id=stage_id,
            )
        for field, role in (
            ("real_weight_stream", "materialized_weight_stream"),
            ("runtime_constant_stream", "materialized_runtime_stream"),
        ):
            stream = contract.get(field)
            if stream is None:
                continue
            if not isinstance(stream, dict):
                errors.append(f"{stage_id}: certified {role} descriptor is invalid")
                continue
            stream_file = (
                stream.get("stream", {})
                if isinstance(stream.get("stream"), dict)
                else stream
            )
            add_file(
                stream_file.get("path"),
                stream_file.get("sha256"),
                role=role,
                stage_id=stage_id,
            )
            for target in stream.get("targets", []):
                if not isinstance(target, dict) or not target.get("source_path"):
                    continue
                add_file(
                    target.get("source_path"),
                    target.get("source_file_sha256"),
                    role=f"{role}_source",
                    stage_id=stage_id,
                )
        bindings = contract.get("real_weight_bindings", [])
        if not isinstance(bindings, list):
            errors.append(f"{stage_id}: certified real-weight bindings are invalid")
        for binding in bindings if isinstance(bindings, list) else []:
            if not isinstance(binding, dict):
                errors.append(f"{stage_id}: certified real-weight binding entry is invalid")
                continue
            add_file(
                binding.get("path"),
                binding.get("file_sha256") or binding.get("sha256"),
                role="bound_weight_tensor",
                stage_id=stage_id,
            )
    return [rows_by_path[key] for key in sorted(rows_by_path)], errors


def _operator_leaf_manifest_continuity_errors(
    snapshot_manifest: dict[str, Any],
    snapshot_requirements: dict[str, Any],
    current_manifest: dict[str, Any],
    current_semantic_manifest: dict[str, Any],
    current_requirements: dict[str, Any],
) -> list[str]:
    errors: list[str] = []
    if current_manifest.get("status") != "pass":
        errors.append("current DUT weight-binding manifest is not pass")
    for field in (
        "scope_coverage_complete",
        "dut_consumes_bound_weights",
        "default_or_identity_weight_fallback_disabled",
    ):
        if current_manifest.get(field) is not True:
            errors.append(f"current DUT weight-binding manifest does not prove {field}")
    if canonical_contract_sha256(_operator_leaf_requirements_projection(snapshot_requirements)) != canonical_contract_sha256(
        _operator_leaf_requirements_projection(current_requirements)
    ):
        errors.append("operator-leaf weight/runtime requirements changed")

    old_contracts = snapshot_manifest.get("stage_contracts", [])
    old_contracts = old_contracts if isinstance(old_contracts, list) else []
    old_by_stage = {
        str(contract.get("stage_id")): contract
        for contract in old_contracts
        if isinstance(contract, dict) and contract.get("stage_id")
    }
    current_harnesses = current_manifest.get("stage_harnesses", {})
    current_harnesses = current_harnesses if isinstance(current_harnesses, dict) else {}
    requirement_rows = current_requirements.get("stage_requirements", [])
    requirement_by_stage = {
        str(row.get("stage_id")): row
        for row in requirement_rows
        if isinstance(row, dict) and row.get("stage_id")
    }
    if not old_by_stage:
        errors.append("certified semantic-testbench snapshot has no operator stages")
    if set(current_harnesses) != set(old_by_stage):
        errors.append("current operator harness set differs from the certified operator set")
    if set(requirement_by_stage) != set(old_by_stage):
        errors.append("current operator weight requirements differ from the certified operator set")
    for stage_id in sorted(set(old_by_stage) & set(current_harnesses) & set(requirement_by_stage)):
        contract = old_by_stage[stage_id]
        harness = current_harnesses[stage_id]
        requirement = requirement_by_stage[stage_id]
        if not isinstance(harness, dict):
            errors.append(f"{stage_id}: current operator harness metadata is invalid")
            continue
        errors.extend(
            f"{stage_id}: {message}"
            for message in certified_stage_harness_metadata_errors(harness, requirement)
        )
        certified_harness = contract.get("dut_harness", {})
        certified_harness = (
            certified_harness if isinstance(certified_harness, dict) else {}
        )
        if harness.get("top_module") != certified_harness.get("top_module"):
            errors.append(f"{stage_id}: operator harness top module changed")
        certified_consumed = sorted(
            str(value)
            for value in certified_harness.get("consumed_tensor_hashes", [])
            if str(value)
        )
        current_consumed = sorted(
            str(value)
            for value in harness.get("consumed_tensor_hashes", [])
            if str(value)
        )
        if current_consumed != certified_consumed:
            errors.append(f"{stage_id}: operator harness consumed tensor set changed")
        if harness.get("weight_layout_contract_sha256") != contract.get(
            "weight_layout_contract_sha256"
        ):
            errors.append(f"{stage_id}: operator harness weight-layout contract changed")
        if harness.get("runtime_constant_contract_sha256") != contract.get(
            "runtime_constant_contract_sha256"
        ):
            errors.append(f"{stage_id}: operator harness runtime-constant contract changed")
        certified_sources = {
            str(row.get("path")): str(row.get("sha256"))
            for row in certified_harness.get("source_files", [])
            if isinstance(row, dict) and row.get("path") and row.get("sha256")
        }
        current_sources = {
            str(row.get("path")): str(row.get("sha256"))
            for row in harness.get("source_files", [])
            if isinstance(row, dict) and row.get("path") and row.get("sha256")
        }
        if not certified_sources or current_sources != certified_sources:
            errors.append(f"{stage_id}: operator harness source declaration changed")

    current_stage_contracts = current_semantic_manifest.get("stage_contracts", [])
    current_stage_contracts = (
        current_stage_contracts if isinstance(current_stage_contracts, list) else []
    )
    current_contract_by_stage = {
        str(contract.get("stage_id")): contract
        for contract in current_stage_contracts
        if isinstance(contract, dict) and contract.get("stage_id")
    }
    if set(current_contract_by_stage) != set(old_by_stage):
        errors.append("current semantic-testbench operator contract set changed")
    for stage_id in sorted(set(old_by_stage) & set(current_contract_by_stage)):
        prior_projection = _operator_leaf_stage_contract_projection(old_by_stage[stage_id])
        current_projection = _operator_leaf_stage_contract_projection(
            current_contract_by_stage[stage_id]
        )
        # A connected-layer manifest replaces the leaf-local execution state
        # with an explicit reusable lower-certificate state.  It is not a leaf
        # semantic change when every other certified contract field remains
        # byte-identical; the live-file proof above still catches any source,
        # input, weight, runtime, or golden-vector drift.
        if (
            prior_projection.get("status") == "ready"
            and current_projection.get("status") == "reused_lower_layer_certificate"
        ):
            current_projection["status"] = "ready"
        if canonical_contract_sha256(prior_projection) != canonical_contract_sha256(current_projection):
            errors.append(f"{stage_id}: semantic-testbench operator contract changed")
    return errors


def reconcile_operator_leaf_certificate_scope_continuity(
    run_dir: Path,
    out_dir: Path,
) -> dict[str, Any]:
    """Rebase only a proven-unchanged leaf certificate after a higher-scope binding update.

    A connected-layer repair can legitimately add its own harness entry to the shared
    binding manifest.  The complete manifest hash then changes even when every
    certified leaf source, input, real-weight stream, and golden vector is unchanged.
    This function accepts that reuse only after rechecking those leaf-owned bytes and
    contracts.  Any leaf-owned drift remains a hard failure and requires real replay.
    """

    run_dir = run_dir.resolve()
    out_dir = out_dir.resolve()
    out_dir.mkdir(parents=True, exist_ok=True)
    report_path = out_dir / "operator_leaf_certificate_scope_continuity.json"
    certificate_path = (
        run_dir
        / "verification"
        / "certificates"
        / "operator_leaf_promotion_certificate.json"
    )
    binding_manifest_path = (
        run_dir / "generated" / "memory" / "dut_weight_binding_manifest.json"
    )
    semantic_manifest_path = (
        run_dir
        / "verification"
        / "semantic_testbench"
        / "semantic_testbench_manifest.json"
    )
    requirements_path = (
        run_dir
        / "verification"
        / "semantic_testbench"
        / "dut_weight_binding_requirements.json"
    )
    report: dict[str, Any] = {
        "schema_version": OPERATOR_LEAF_CERTIFICATE_CONTINUITY_SCHEMA_VERSION,
        "status": "not_applicable",
        "certificate": str(certificate_path),
        "binding_manifest": str(binding_manifest_path),
        "semantic_testbench_manifest": str(semantic_manifest_path),
        "requirements": str(requirements_path),
    }

    def finish(status: str, summary: str, **fields: Any) -> dict[str, Any]:
        report.update({"status": status, "summary": summary, **fields})
        write_json(report_path, report)
        report["path"] = str(report_path)
        return report

    if not all(
        path.is_file()
        for path in (
            certificate_path,
            binding_manifest_path,
            semantic_manifest_path,
            requirements_path,
        )
    ):
        return finish(
            "not_applicable",
            "operator-leaf continuity reconciliation requires certificate, binding, requirements, and semantic-testbench artifacts",
        )
    certificate = read_json_if_exists(certificate_path)
    required_gate_names = [
        str(row.get("name"))
        for row in certificate.get("required_gates", [])
        if isinstance(row, dict) and row.get("name")
    ]
    if not required_gate_names:
        return finish(
            "incomplete",
            "operator-leaf promotion certificate has no required gates",
        )
    contract_errors = certificate_contract_errors(
        certificate,
        "operator_leaf_functional",
        required_gate_names,
    )
    snapshot_semantic = _certificate_snapshot_document(
        certificate,
        lambda document: (
            isinstance(document.get("stage_contracts"), list)
            and bool(document.get("stage_contracts"))
            and any(
                isinstance(contract, dict) and contract.get("testbench_sha256")
                for contract in document.get("stage_contracts", [])
            )
        ),
    )
    snapshot_requirements = _certificate_snapshot_document(
        certificate,
        lambda document: isinstance(document.get("stage_requirements"), list)
        and bool(document.get("stage_requirements")),
    )
    if not contract_errors:
        if snapshot_semantic is not None:
            _, prior_semantic_manifest = snapshot_semantic
            _, live_errors = _operator_leaf_live_file_rows(
                prior_semantic_manifest,
                run_dir,
            )
            if live_errors:
                return finish(
                    "incomplete",
                    "operator-leaf continuity proof found a changed certified source; real leaf replay is required",
                    continuity_errors=live_errors,
                )
        return finish(
            "not_required",
            "operator-leaf promotion certificate already has current live evidence",
            certificate_sha256=sha256_file(certificate_path),
        )
    debug_closure_dir = run_dir / "verification" / "debug_closure"
    ephemeral_debug_paths = {
        str((debug_closure_dir / name).resolve())
        for name in (
            "boundary_contracts.json",
            "trace_manifest.json",
            "boundary_trace.json",
            "failure_localization.json",
        )
    }
    allowed_drift_paths = {
        str(binding_manifest_path.resolve()),
        str(semantic_manifest_path.resolve()),
        *ephemeral_debug_paths,
    }
    drift_prefix = "promotion certificate live evidence hash drift: "
    unexpected_errors = [
        error
        for error in contract_errors
        if not error.startswith(drift_prefix)
        or (
            str(Path(error[len(drift_prefix) :]).resolve()) not in allowed_drift_paths
            and not _operator_leaf_higher_scope_semantic_artifact(
                Path(error[len(drift_prefix) :]),
                run_dir,
            )
        )
    ]
    if unexpected_errors:
        return finish(
            "incomplete",
            "operator-leaf certificate has leaf-owned or structural evidence drift; real leaf replay is required",
            contract_errors=contract_errors,
            unexpected_errors=unexpected_errors,
        )
    if snapshot_semantic is None or snapshot_requirements is None:
        return finish(
            "incomplete",
            "operator-leaf certificate lacks immutable semantic-testbench or weight-requirements snapshots",
            contract_errors=contract_errors,
        )
    snapshot_semantic_path, prior_semantic_manifest = snapshot_semantic
    snapshot_requirements_path, prior_requirements = snapshot_requirements
    current_manifest = read_json_if_exists(binding_manifest_path)
    current_semantic_manifest = read_json_if_exists(semantic_manifest_path)
    current_requirements = read_json_if_exists(requirements_path)
    live_rows, live_errors = _operator_leaf_live_file_rows(
        prior_semantic_manifest,
        run_dir,
    )
    continuity_errors = [
        *live_errors,
        *_operator_leaf_manifest_continuity_errors(
            prior_semantic_manifest,
            prior_requirements,
            current_manifest,
            current_semantic_manifest,
            current_requirements,
        ),
    ]
    if continuity_errors:
        return finish(
            "incomplete",
            "operator-leaf continuity proof found a changed certified source or contract; real leaf replay is required",
            contract_errors=contract_errors,
            continuity_errors=continuity_errors,
        )

    binding = copy.deepcopy(certificate.get("evidence_binding", {}))
    file_bindings = binding.get("file_bindings", [])
    if not isinstance(file_bindings, list):
        return finish(
            "incomplete",
            "operator-leaf certificate evidence binding has no file list",
            contract_errors=contract_errors,
        )
    current_binding_hash = sha256_file(binding_manifest_path)
    current_semantic_hash = sha256_file(semantic_manifest_path)
    retained_rows: list[dict[str, Any]] = []
    replaced_manifest_gates: set[str] = set()
    removed_semantic_gates: set[str] = set()
    removed_ephemeral_debug_gates: set[str] = set()
    removed_higher_scope_semantic_artifact_gates: set[str] = set()
    for row in file_bindings:
        if not isinstance(row, dict):
            continue
        row_path_text = str(row.get("path") or "")
        try:
            row_path = Path(row_path_text).resolve()
        except OSError:
            retained_rows.append(copy.deepcopy(row))
            continue
        if row_path == binding_manifest_path.resolve():
            updated = copy.deepcopy(row)
            updated["sha256"] = current_binding_hash
            retained_rows.append(updated)
            if row.get("gate"):
                replaced_manifest_gates.add(str(row["gate"]))
            continue
        if row_path == semantic_manifest_path.resolve():
            if row.get("gate"):
                removed_semantic_gates.add(str(row["gate"]))
            continue
        if _operator_leaf_higher_scope_semantic_artifact(row_path, run_dir):
            if row.get("gate"):
                removed_higher_scope_semantic_artifact_gates.add(str(row["gate"]))
            continue
        if str(row_path) in ephemeral_debug_paths:
            if row.get("gate"):
                removed_ephemeral_debug_gates.add(str(row["gate"]))
            continue
        retained_rows.append(copy.deepcopy(row))
    source_certificate_hash = sha256_file(certificate_path)
    continuity_seed = {
        "schema_version": OPERATOR_LEAF_CERTIFICATE_CONTINUITY_SCHEMA_VERSION,
        "source_certificate_sha256": source_certificate_hash,
        "current_binding_manifest_sha256": current_binding_hash,
        "current_semantic_manifest_sha256": current_semantic_hash,
        "live_files": live_rows,
        "requirements_projection_sha256": canonical_contract_sha256(
            _operator_leaf_requirements_projection(current_requirements)
        ),
    }
    continuity_id = canonical_contract_sha256(continuity_seed)
    candidate_dir = (
        run_dir / "verification" / "certificates" / "candidates" / continuity_id
    )
    candidate_dir.mkdir(parents=True, exist_ok=True)
    source_certificate_path = (
        candidate_dir / "operator_leaf_promotion_certificate_before_continuity.json"
    )
    if source_certificate_path.exists():
        if sha256_file(source_certificate_path) != source_certificate_hash:
            return finish(
                "incomplete",
                "content-addressed continuity candidate has a conflicting source certificate snapshot",
            )
    else:
        shutil.copy2(certificate_path, source_certificate_path)
    proof_path = candidate_dir / "operator_leaf_certificate_scope_continuity.json"
    continuity_proof = {
        "schema_version": OPERATOR_LEAF_CERTIFICATE_CONTINUITY_SCHEMA_VERSION,
        "status": "pass",
        "summary": (
            "all certified operator-leaf sources, stimuli, real-weight streams, golden vectors, "
            "and leaf binding contracts remain byte-identical after a higher-scope binding update"
        ),
        "source_certificate": {
            "path": str(source_certificate_path),
            "sha256": source_certificate_hash,
        },
        "certified_semantic_snapshot": {
            "path": str(snapshot_semantic_path),
            "sha256": sha256_file(snapshot_semantic_path),
        },
        "certified_requirements_snapshot": {
            "path": str(snapshot_requirements_path),
            "sha256": sha256_file(snapshot_requirements_path),
        },
        "current_binding_manifest": {
            "path": str(binding_manifest_path),
            "sha256": current_binding_hash,
        },
        "current_semantic_testbench_manifest": {
            "path": str(semantic_manifest_path),
            "sha256": current_semantic_hash,
        },
        "current_requirements": {
            "path": str(requirements_path),
            "sha256": sha256_file(requirements_path),
            "operator_leaf_projection_sha256": canonical_contract_sha256(
                _operator_leaf_requirements_projection(current_requirements)
            ),
        },
        "live_operator_leaf_files": live_rows,
        "permitted_cross_scope_live_drift": sorted(allowed_drift_paths),
        "replaced_binding_manifest_gates": sorted(replaced_manifest_gates),
        "removed_cross_scope_semantic_manifest_gates": sorted(removed_semantic_gates),
        "removed_ephemeral_debug_closure_gates": sorted(removed_ephemeral_debug_gates),
        "removed_higher_scope_semantic_artifact_gates": sorted(
            removed_higher_scope_semantic_artifact_gates
        ),
    }
    write_json(proof_path, continuity_proof)
    proof_hash = sha256_file(proof_path)
    continuity_gates = sorted(
        (
            replaced_manifest_gates
            | removed_semantic_gates
            | removed_ephemeral_debug_gates
            | removed_higher_scope_semantic_artifact_gates
        )
        or set(required_gate_names)
    )
    for gate in continuity_gates:
        retained_rows.append(
            {
                "gate": gate,
                "path": str(proof_path),
                "sha256": proof_hash,
                "role": "lower_scope_certificate_continuity_proof",
            }
        )
    source_gate = (
        "case_semantic_testbench"
        if "case_semantic_testbench" in required_gate_names
        else required_gate_names[0]
    )
    for row in live_rows:
        retained_rows.append(
            {
                "gate": source_gate,
                "path": row["path"],
                "sha256": row["sha256"],
                "role": f"operator_leaf_continuity_{row['role']}",
            }
        )
    deduplicated_rows = {
        (
            str(row.get("gate") or ""),
            str(row.get("path") or ""),
            str(row.get("sha256") or ""),
            str(row.get("role") or ""),
            str(row.get("source_path") or ""),
        ): row
        for row in retained_rows
        if isinstance(row, dict)
    }
    binding["file_bindings"] = [
        deduplicated_rows[key] for key in sorted(deduplicated_rows)
    ]
    binding["fingerprints"] = [
        row
        for row in binding.get("fingerprints", [])
        if not _operator_leaf_higher_scope_semantic_artifact(
            Path(str(row.get("artifact_path") or "")),
            run_dir,
        )
    ]
    binding["binding_sha256"] = promotion_evidence_binding_fingerprint(binding)
    derived_certificate = copy.deepcopy(certificate)
    derived_certificate["evidence_binding"] = binding
    derived_certificate["certificate_derivation"] = {
        "schema_version": OPERATOR_LEAF_CERTIFICATE_DERIVATION_SCHEMA_VERSION,
        "kind": "lower_scope_continuity_after_higher_scope_binding_update",
        "source_certificate": {
            "path": str(source_certificate_path),
            "sha256": source_certificate_hash,
        },
        "continuity_proof": {"path": str(proof_path), "sha256": proof_hash},
        "removed_cross_scope_live_input": str(semantic_manifest_path),
        "retained_current_binding_manifest": {
            "path": str(binding_manifest_path),
            "sha256": current_binding_hash,
        },
        "removed_ephemeral_debug_closure_inputs": sorted(ephemeral_debug_paths),
    }
    derived_errors = certificate_contract_errors(
        derived_certificate,
        "operator_leaf_functional",
        required_gate_names,
    )
    if derived_errors:
        return finish(
            "incomplete",
            "derived operator-leaf continuity certificate did not satisfy the standard live-evidence contract",
            contract_errors=contract_errors,
            derived_certificate_errors=derived_errors,
        )
    candidate_path = candidate_dir / "operator_leaf_promotion_certificate.json"
    write_json(candidate_path, derived_certificate)
    write_json(certificate_path, derived_certificate)
    return finish(
        "pass",
        "reconciled the operator-leaf certificate after proving all leaf-owned verification evidence is unchanged",
        source_certificate=str(source_certificate_path),
        source_certificate_sha256=source_certificate_hash,
        derived_certificate=str(candidate_path),
        derived_certificate_sha256=sha256_file(candidate_path),
        continuity_proof=str(proof_path),
        continuity_proof_sha256=proof_hash,
        live_operator_leaf_file_count=len(live_rows),
        replaced_binding_manifest_gates=sorted(replaced_manifest_gates),
        removed_cross_scope_semantic_manifest_gates=sorted(removed_semantic_gates),
        removed_ephemeral_debug_closure_gates=sorted(removed_ephemeral_debug_gates),
        removed_higher_scope_semantic_artifact_gates=sorted(
            removed_higher_scope_semantic_artifact_gates
        ),
    )


def reusable_operator_leaf_promotion_certificate(run_dir: Path) -> dict[str, Any]:
    path = (
        run_dir
        / "verification"
        / "certificates"
        / "operator_leaf_promotion_certificate.json"
    )
    certificate = read_json_if_exists(path)
    required_gates = [
        row
        for row in certificate.get("required_gates", [])
        if isinstance(row, dict)
    ]
    policy = (
        certificate.get("policy", {})
        if isinstance(certificate.get("policy"), dict)
        else {}
    )
    required_gate_names = [
        str(row.get("name")) for row in required_gates if row.get("name")
    ]
    contract_errors = (
        certificate_contract_errors(
            certificate,
            "operator_leaf_functional",
            required_gate_names,
        )
        if path.is_file() and required_gate_names
        else ["operator-leaf certificate has no required gates"]
    )
    reusable = (
        path.is_file()
        and certificate.get("artifact_id")
        == "artifact.stage6.operator_leaf_promotion_certificate"
        and certificate.get("gate_execution_scope") == "operator_leaf_closure"
        and certificate.get("status") == "pass"
        and bool(required_gates)
        and all(row.get("status") == "pass" for row in required_gates)
        and policy.get("lower_layer_pass_evidence_is_reusable_not_absolute") is True
        and not contract_errors
    )
    return {
        "status": "pass" if reusable else "incomplete",
        "path": str(path),
        "sha256": sha256_file(path) if path.is_file() else None,
        "artifact_id": certificate.get("artifact_id"),
        "required_gate_count": len(required_gates),
        "validation_errors": contract_errors,
        "summary": (
            "reused the passing operator-leaf promotion certificate without replaying certified leaf tools"
            if reusable
            else "a reusable operator-leaf promotion certificate is unavailable"
        ),
    }


def certified_stage_harness_metadata_errors(
    harness: dict[str, Any],
    requirement: dict[str, Any],
) -> list[str]:
    errors: list[str] = []
    if not str(harness.get("top_module") or ""):
        errors.append("certified harness top_module is missing")
    consumed = {
        str(value)
        for value in harness.get("consumed_tensor_hashes", [])
        if str(value)
    }
    required = {
        str(row.get("sha256"))
        for row in requirement.get("required_tensors", [])
        if isinstance(row, dict) and row.get("sha256")
    }
    missing = sorted(required - consumed)
    if missing:
        errors.append(
            f"certified harness metadata is missing {len(missing)} required tensor hash(es)"
        )
    if (
        harness.get("weight_layout_contract_sha256")
        != requirement.get("weight_layout_contract_sha256")
    ):
        errors.append("certified harness weight-layout contract hash changed")
    expected_runtime = requirement.get("runtime_constant_contract_sha256")
    if expected_runtime and harness.get("runtime_constant_contract_sha256") != expected_runtime:
        errors.append("certified harness runtime-constant contract hash changed")
    if required and harness.get("default_or_identity_weight_fallback_disabled") is not True:
        errors.append("certified weighted harness no longer disables default/identity fallback")
    return errors


def connected_binding_requirements_ready(run_dir: Path) -> bool:
    requirements = read_json_if_exists(
        run_dir
        / "verification"
        / "semantic_testbench"
        / "dut_weight_binding_requirements.json"
    )
    for field in (
        "connected_weight_stream_contract",
        "connected_runtime_stream_contract",
    ):
        contract = requirements.get(field)
        if (
            not isinstance(contract, dict)
            or contract.get("status") != "pass"
            or not re.fullmatch(r"[0-9a-f]{64}", str(contract.get("contract_sha256") or ""))
        ):
            return False
    return True


def finalize_dut_weight_binding_manifest(
    run_dir: Path,
    out_dir: Path,
    *,
    require_single_layer: bool = False,
    require_board: bool = False,
    single_layer_certificate_path: Path | None = None,
) -> dict[str, Any]:
    manifest_path = run_dir / "generated" / "memory" / "dut_weight_binding_manifest.json"
    requirements_path = run_dir / "verification" / "semantic_testbench" / "dut_weight_binding_requirements.json"
    source_provenance: dict[str, Any] = {}
    patch_path = out_dir / "agent_patch_application.json"
    prior_materialization_path = out_dir / "dut_weight_binding_materialization.json"
    prior_materialization = read_json_if_exists(prior_materialization_path)
    source_agent_manifest_sha256 = sha256_file(manifest_path) if manifest_path.is_file() else ""
    if source_agent_manifest_sha256 and patch_path.is_file():
        patch_report = read_json_if_exists(patch_path)
        patch_files = (
            patch_report.get("files", [])
            if patch_report.get("status") == "pass"
            and patch_report.get("blockers") == []
            and isinstance(patch_report.get("files"), list)
            else []
        )
        for row in patch_files:
            if not isinstance(row, dict):
                continue
            try:
                row_path = Path(str(row.get("path") or "")).resolve()
            except OSError:
                continue
            if (
                row_path == manifest_path.resolve()
                and row.get("after_sha256") == source_agent_manifest_sha256
            ):
                source_provenance = {
                    "source_patch_application": str(patch_path),
                    "source_patch_application_sha256": sha256_file(patch_path),
                    "source_agent_manifest": str(manifest_path),
                    "source_agent_manifest_sha256": source_agent_manifest_sha256,
                }
                break
        if not source_provenance:
            provenance_fields = (
                "source_patch_application",
                "source_patch_application_sha256",
                "source_agent_manifest",
                "source_agent_manifest_sha256",
            )
            try:
                prior_patch_path = Path(
                    str(prior_materialization.get("source_patch_application") or "")
                ).resolve()
                prior_agent_manifest_path = Path(
                    str(prior_materialization.get("source_agent_manifest") or "")
                ).resolve()
            except OSError:
                prior_patch_path = Path()
                prior_agent_manifest_path = Path()
            prior_agent_sha = str(
                prior_materialization.get("source_agent_manifest_sha256") or ""
            )
            patch_attests_agent_manifest = any(
                isinstance(row, dict)
                and Path(str(row.get("path") or "")).resolve()
                == manifest_path.resolve()
                and row.get("after_sha256") == prior_agent_sha
                for row in patch_files
                if row.get("path")
            )
            if (
                prior_materialization.get("schema_version")
                == "spatialaccagent.dut_weight_binding_materialization.v1"
                and prior_materialization.get("manifest_sha256")
                == source_agent_manifest_sha256
                and all(prior_materialization.get(field) for field in provenance_fields)
                and prior_patch_path == patch_path.resolve()
                and prior_materialization.get("source_patch_application_sha256")
                == sha256_file(patch_path)
                and prior_agent_manifest_path == manifest_path.resolve()
                and patch_attests_agent_manifest
            ):
                source_provenance = {
                    field: prior_materialization[field]
                    for field in provenance_fields
                }
    blockers: list[str] = []
    if not manifest_path.is_file():
        blockers.append(f"agent patch did not create DUT weight-binding manifest: {manifest_path}")
        manifest: dict[str, Any] = {}
    else:
        manifest = read_json_if_exists(manifest_path)
    if require_board and manifest:
        manifest = canonicalize_exact_board_manifest_declarations(
            manifest,
            run_dir,
            out_dir,
        )
    if require_board:
        source_provenance = prefer_archived_exact_board_source_provenance(
            manifest,
            manifest_path,
            out_dir,
            source_provenance,
        )
    checkpoint_framework_binding = (
        rebind_manifest_checkpoint_framework_authority(manifest)
        if require_board
        else {
            "schema_version": (
                "spatialaccagent.checkpoint_manifest_framework_binding.v1"
            ),
            "status": "not_required",
            "changed": False,
        }
    )
    if checkpoint_framework_binding.get("status") == "fail":
        blockers.extend(
            "checkpoint_framework_authority: " + str(error)
            for error in checkpoint_framework_binding.get(
                "adapter_binding", {}
            ).get("errors", [])
            if str(error)
        )
    requirements = read_json_if_exists(requirements_path)
    if not requirements:
        blockers.append(f"DUT weight-binding requirements are missing: {requirements_path}")
    if require_board and isinstance(
        manifest.get("board_simulation_preflight_plan"), dict
    ):
        selection_refresh_blockers: list[str] = []
        _materialize_external_fixture_preflight_selection(
            manifest["board_simulation_preflight_plan"],
            run_dir,
            selection_refresh_blockers,
        )
        blockers.extend(
            f"board_preflight: {value}" for value in selection_refresh_blockers
        )

    generated_modules: set[str] = set()
    generated_source_candidates = [
        *(run_dir / "generated" / "chisel").glob("*.sv"),
        *(run_dir / "generated" / "semantic_harness").rglob("*.sv"),
        *(run_dir / "generated" / "semantic_harness").rglob("*.v"),
        *(run_dir / "generated" / "board_integration").rglob("*.sv"),
        *(run_dir / "generated" / "board_integration").rglob("*.v"),
    ]
    for source in generated_source_candidates:
        try:
            generated_modules.update(
                re.findall(r"(?m)^module\s+([A-Za-z_][A-Za-z0-9_$]*)\b", source.read_text(encoding="utf-8"))
            )
        except (OSError, UnicodeDecodeError):
            continue

    stage_harnesses = manifest.get("stage_harnesses", {}) if isinstance(manifest.get("stage_harnesses"), dict) else {}
    normalized_harnesses: dict[str, Any] = {}
    all_consumed: set[str] = set()
    lower_layer_certificate = reusable_operator_leaf_promotion_certificate(run_dir)
    reuse_certified_lower_layer = (
        (require_single_layer or require_board)
        and lower_layer_certificate.get("status") == "pass"
    )
    for row in requirements.get("stage_requirements", []):
        if not isinstance(row, dict):
            continue
        stage_id = str(row.get("stage_id") or "")
        required_hashes = {
            str(item.get("sha256"))
            for item in row.get("required_tensors", [])
            if isinstance(item, dict) and item.get("sha256")
        }
        harness = stage_harnesses.get(stage_id)
        if not isinstance(harness, dict):
            blockers.append(f"DUT binding has no agent-generated harness for {stage_id}")
            continue
        if reuse_certified_lower_layer:
            normalized = copy.deepcopy(harness)
            errors = certified_stage_harness_metadata_errors(harness, row)
        else:
            normalized, errors = harness_contract_errors(
                harness,
                required_hashes,
                str(row.get("weight_layout_contract_sha256") or ""),
                str(row.get("runtime_constant_contract_sha256") or ""),
                run_dir,
                generated_modules,
            )
        normalized_harnesses[stage_id] = normalized
        all_consumed.update(str(value) for value in normalized.get("consumed_tensor_hashes", []))
        blockers.extend(f"{stage_id}: {error}" for error in errors)

    required_global = {
        str(row.get("sha256"))
        for row in requirements.get("single_layer_required_tensors", [])
        if isinstance(row, dict) and row.get("sha256")
    }
    missing_global = sorted(required_global - all_consumed)
    if missing_global:
        blockers.append(f"agent-generated leaf harnesses do not cover {len(missing_global)} required tensor hash(es)")

    normalized_single_layer: dict[str, Any] | None = None
    if require_single_layer or require_board:
        single_layer_harness = manifest.get("single_layer_harness")
        if not isinstance(single_layer_harness, dict):
            blockers.append("DUT binding has no agent-generated connected single-layer harness")
        else:
            normalized_single_layer, single_errors = connected_harness_contract_errors(
                single_layer_harness,
                requirements,
                run_dir,
                generated_modules,
            )
            all_consumed.update(
                str(value)
                for value in normalized_single_layer.get(
                    "consumed_tensor_hashes", []
                )
            )
            blockers.extend(f"single_layer: {error}" for error in single_errors)

    normalized_multilayer: dict[str, Any] | None = None
    if require_board and normalized_single_layer is not None:
        integration = copy.deepcopy(
            manifest.get("board_integration_contract")
            if isinstance(manifest.get("board_integration_contract"), dict)
            else {}
        )
        runtime_paths = exact_board_memory_runtime_paths(run_dir, out_dir)
        for field, path in (
            ("board_memory_runtime_contract_sha256", runtime_paths["contract"]),
            ("full_weight_image_manifest_sha256", runtime_paths["image_manifest"]),
            ("full_weight_image_sha256", runtime_paths["image"]),
            (
                "full_layer_runtime_capture_contract_sha256",
                runtime_paths["runtime_capture"],
            ),
            (
                "full_runtime_image_manifest_sha256",
                runtime_paths["runtime_image_manifest"],
            ),
            ("full_runtime_image_sha256", runtime_paths["runtime_image"]),
        ):
            if path.is_file():
                integration[field] = sha256_file(path)
        manifest["board_integration_contract"] = integration
        normalized_multilayer, board_errors = board_integration_binding_errors(
            manifest,
            normalized_single_layer,
            run_dir,
            out_dir,
            single_layer_certificate_path,
            source_provenance,
        )
        blockers.extend(f"board_integration: {error}" for error in board_errors)

    manifest.update(
        {
            "schema_version": "spatialaccagent.dut_weight_binding_manifest.v1",
            "status": "pass" if not blockers else "incomplete",
            "accelerator_scope": "transformer_blocks_only",
            "source_checkpoint_sha256": requirements.get("source_checkpoint_sha256"),
            "source_reference_sha256": requirements.get("source_reference_sha256"),
            "numeric_policy_sha256": requirements.get("numeric_policy_sha256"),
            "model_semantic_adapter_sha256": requirements.get("model_semantic_adapter_sha256"),
            "scope_coverage_complete": not blockers,
            "dut_consumes_bound_weights": not blockers,
            "default_or_identity_weight_fallback_disabled": not blockers,
            "consumed_tensor_hashes": sorted(all_consumed),
            "stage_harnesses": normalized_harnesses,
            **(
                {"single_layer_harness": normalized_single_layer}
                if normalized_single_layer is not None
                else {}
            ),
            **(
                {"multilayer_harness": normalized_multilayer}
                if normalized_multilayer is not None
                else {}
            ),
            "materialization": {
                "source": "agent_file_edits_plus_framework_hash_validation",
                "requirements": str(requirements_path),
                "requirements_sha256": sha256_file(requirements_path) if requirements_path.is_file() else None,
                "executed_weight_consumption_pending_real_simulation": True,
                "verification_scope": (
                    "board_axi_ddr_closure"
                    if require_board
                    else "single_layer_closure"
                    if require_single_layer
                    else "operator_leaf_closure"
                ),
                "golden_or_reference_files_modified": False,
                "checkpoint_framework_authority_binding": copy.deepcopy(
                    checkpoint_framework_binding
                ),
            },
            "materialization_blockers": blockers,
        }
    )
    board_preflight: dict[str, Any] | None = None
    if require_board:
        if isinstance(manifest.get("board_simulation_preflight_plan"), dict):
            missing_prerequisites = (
                framework_vcs_plan_binding_missing_prerequisites(
                    run_dir,
                    str(
                        manifest["board_simulation_preflight_plan"].get(
                            "validation_mode"
                        )
                        or "exact_sample_physical_ddr"
                    ),
                )
            )
            if missing_prerequisites:
                blockers.append(
                    "board_preflight: framework VCS-plan binding prerequisites are "
                    "missing: " + "; ".join(missing_prerequisites)
                )
            else:
                manifest, vcs_binding = bind_framework_vcs_compile_plan(
                    manifest,
                    run_dir,
                    out_dir,
                    manifest_path,
                )
                blockers.extend(
                    f"board_preflight: {value}"
                    for value in vcs_binding.get("blockers", [])
                )
        if normalized_multilayer is None:
            blockers.append("board_integration: normalized multi-layer harness is unavailable for exact preflight")
        else:
            board_preflight = materialize_exact_board_preflight_manifest(
                manifest,
                normalized_multilayer,
                run_dir,
            )
            blockers.extend(
                f"board_preflight: {error}"
                for error in board_preflight.get("blockers", [])
                if str(error)
            )
    blockers = list(dict.fromkeys(blockers))
    manifest.update(
        {
            "status": "pass" if not blockers else "incomplete",
            "scope_coverage_complete": not blockers,
            "dut_consumes_bound_weights": not blockers,
            "default_or_identity_weight_fallback_disabled": not blockers,
            "materialization_blockers": blockers,
        }
    )
    materialization = manifest.get("materialization")
    if isinstance(materialization, dict) and require_board:
        materialization.update(
            {
                "board_simulation_preflight_manifest": (
                    board_preflight.get("manifest") if board_preflight is not None else None
                ),
                "board_simulation_preflight_manifest_sha256": (
                    board_preflight.get("manifest_sha256") if board_preflight is not None else None
                ),
                "board_simulation_preflight_status": (
                    board_preflight.get("status") if board_preflight is not None else "incomplete"
                ),
                "board_simulation_execution_pending_real_vcs": True,
            }
        )
    write_json(manifest_path, manifest)
    report = {
        "schema_version": "spatialaccagent.dut_weight_binding_materialization.v1",
        "status": "pass" if not blockers else "incomplete",
        "manifest": str(manifest_path),
        "manifest_sha256": sha256_file(manifest_path),
        "stage_harness_count": len(normalized_harnesses),
        "single_layer_harness_materialized": normalized_single_layer is not None,
        "board_integration_harness_materialized": normalized_multilayer is not None,
        "board_simulation_preflight_materialized": (
            board_preflight is not None and board_preflight.get("status") == "pass"
        ),
        "board_simulation_preflight_manifest": (
            board_preflight.get("manifest") if board_preflight is not None else None
        ),
        "board_simulation_preflight_manifest_sha256": (
            board_preflight.get("manifest_sha256") if board_preflight is not None else None
        ),
        "vcs_compile_plan_sha256": (
            board_preflight.get("vcs_compile_plan_sha256") if board_preflight is not None else None
        ),
        "board_simulation_preflight_report": (
            board_preflight.get("path") if board_preflight is not None else None
        ),
        "consumed_tensor_hash_count": len(all_consumed),
            "checkpoint_framework_authority_binding": copy.deepcopy(
                checkpoint_framework_binding
            ),
            "lower_layer_certificate_reuse": copy.deepcopy(
                lower_layer_certificate
            ),
            "blockers": blockers,
            **source_provenance,
        }
    report_path = out_dir / "dut_weight_binding_materialization.json"
    write_json(report_path, report)
    report["path"] = str(report_path)
    return report


def semantic_failure_diagnostics(stage_report: dict[str, Any]) -> dict[str, Any]:
    """Return the current semantic failure details regardless of report schema generation."""

    diagnostics: dict[str, Any] = {}
    comparison = (
        stage_report.get("semantic_comparison", {})
        if isinstance(stage_report.get("semantic_comparison"), dict)
        else {}
    )
    metrics = comparison.get("numeric_metrics", {})
    if isinstance(metrics, dict):
        diagnostics.update(metrics)
    explicit = stage_report.get("target_failure_diagnostics", {})
    if isinstance(explicit, dict):
        diagnostics.update(explicit)
    if diagnostics:
        return diagnostics

    debug_closure = (
        stage_report.get("debug_closure", {})
        if isinstance(stage_report.get("debug_closure"), dict)
        else {}
    )
    for record in debug_closure.get("failure_slice", []):
        if isinstance(record, dict) and record.get("status") == "fail":
            return {
                key: record.get(key)
                for key in (
                    "failure_class",
                    "summary",
                    "word_index",
                    "beat_index",
                    "lane_index",
                    "logical_index",
                    "observed_value",
                    "expected_value",
                    "num_mismatch",
                    "mismatch_fraction",
                    "rtl_output_sha256",
                    "expected_output_sha256",
                )
                if record.get(key) is not None
            }
    return {}


def verification_capability_probe_context(step: dict[str, Any]) -> dict[str, Any]:
    """Bind a probe to the hierarchy layer that authorized its execution."""

    return {
        "schema_version": CAPABILITY_PROBE_CONTEXT_SCHEMA_VERSION,
        "repair_step_id": step.get("id"),
        "repair_scope": step.get("scope"),
        "verification_scope": verification_scope_for_step(step),
        "debug_layer": step.get("debug_layer"),
    }


def annotate_verification_capability_probe(
    result: dict[str, Any],
    step: dict[str, Any],
) -> dict[str, Any]:
    """Persist scope provenance before a capability probe becomes reusable evidence."""

    result["probe_context"] = verification_capability_probe_context(step)
    return result


def old_lower_layer_certificate_error_is_resolved(
    value: dict[str, Any],
    run_dir: Path,
    verification_scope: str,
) -> bool:
    """Identify a stale certificate-blocking result after live revalidation."""

    if verification_scope not in {"single_layer_closure", "board_axi_ddr_closure"}:
        return False
    try:
        text = json.dumps(value, sort_keys=True)
    except (TypeError, ValueError):
        return False
    if "passing operator-leaf promotion certificate is unavailable" not in text:
        return False
    return reusable_operator_leaf_promotion_certificate(run_dir).get("status") == "pass"


def applied_semantic_source_hash_changes(
    patch_report: dict[str, Any],
    run_dir: Path,
) -> dict[Path, tuple[str, str]]:
    """Return source hash changes from an already applied board RTL patch."""

    if (
        patch_report.get("status") != "pass"
        or patch_report.get("blockers") not in (None, [])
        or not isinstance(patch_report.get("files"), list)
    ):
        return {}
    semantic_root = (run_dir / "generated" / "semantic_harness").resolve()
    chisel_root = (run_dir / "generated" / "chisel").resolve()
    changes: dict[Path, tuple[str, str]] = {}
    for row in patch_report["files"]:
        if not isinstance(row, dict):
            continue
        raw_path = str(row.get("path") or "").strip()
        before = str(row.get("before_sha256") or "").lower()
        after = str(row.get("after_sha256") or "").lower()
        if not raw_path or not before or not after or before == after:
            continue
        path = Path(raw_path).expanduser()
        path = path if path.is_absolute() else Path.cwd() / path
        try:
            path = path.resolve()
        except OSError:
            continue
        if (
            path.suffix.lower() not in {".sv", ".v"}
            or not (path.is_relative_to(semantic_root) or path.is_relative_to(chisel_root))
            or not path.is_file()
            or sha256_file(path) != after
            or not is_sha256(before)
            or not is_sha256(after)
        ):
            continue
        changes[path] = (before, after)
    return changes


def all_applied_semantic_source_hash_changes(
    patch_report: dict[str, Any],
    run_dir: Path,
) -> dict[Path, tuple[str, str]]:
    """Collect still-applied semantic RTL changes from the current run history.

    The live patch report is overwritten on every repair-loop iteration. A
    recovery must therefore include older successful patch records, but only
    when the current source bytes still match their recorded after-hash.
    """

    candidates: list[dict[str, Any]] = [patch_report]
    loop_root = (run_dir / "repair_execution" / "loop").resolve()
    iteration_paths = sorted(
        (path for path in loop_root.glob("iteration_*") if path.is_dir()),
        key=lambda path: (
            0,
            int(path.name.removeprefix("iteration_")),
        )
        if path.name.removeprefix("iteration_").isdigit()
        else (1, path.name),
        reverse=True,
    )
    for iteration_path in iteration_paths:
        for history_path in sorted(
            iteration_path.glob("*agent_patch_application*.json"),
            reverse=True,
        ):
            history = read_json_if_exists(history_path)
            if isinstance(history, dict):
                candidates.append(history)

    changes: dict[Path, tuple[str, str]] = {}
    for candidate in candidates:
        for path, hashes in applied_semantic_source_hash_changes(candidate, run_dir).items():
            # Candidates are newest-first, so keep the latest valid version.
            changes.setdefault(path, hashes)
    return changes


def rebind_applied_semantic_source_manifests(
    run_dir: Path,
    changed_sources: dict[Path, tuple[str, str]],
) -> dict[str, Any]:
    """Repair shared derived manifests after an interrupted semantic RTL patch."""

    if not changed_sources:
        return {
            "schema_version": "spatialaccagent.applied_semantic_manifest_rebind.v1",
            "status": "not_required",
            "changed_source_count": 0,
            "updated_manifests": [],
            "blockers": [],
        }
    semantic_manifest_path = (
        run_dir / "verification" / "semantic_testbench" / "semantic_testbench_manifest.json"
    ).resolve()
    binding_manifest_path = (
        run_dir / "generated" / "memory" / "dut_weight_binding_manifest.json"
    ).resolve()
    prepared: list[tuple[Path, dict[str, Any], dict[str, Any]]] = []
    blockers: list[str] = []
    board_manifest_path = (
        run_dir / "verification" / "board_simulation" / "board_simulation_manifest.json"
    ).resolve()
    # The board compile source list is another derived view of the same
    # generated RTL. Keep it bound to the source that just passed the
    # connected single-layer gate before starting the board run.
    for manifest_path in (
        semantic_manifest_path,
        binding_manifest_path,
        board_manifest_path,
    ):
        if not manifest_path.is_file():
            blockers.append(f"shared semantic source manifest is missing: {manifest_path}")
            continue
        manifest = read_json_if_exists(manifest_path)
        if not manifest:
            blockers.append(f"shared semantic source manifest is invalid: {manifest_path}")
            continue
        rebound, report = rebind_changed_source_hashes_in_manifest(
            manifest,
            run_dir,
            changed_sources,
            require_match=True,
        )
        blockers.extend(
            f"{manifest_path.name}: {error}"
            for error in report.get("blockers", [])
            if str(error)
        )
        prepared.append((manifest_path, rebound, report))
    if blockers:
        return {
            "schema_version": "spatialaccagent.applied_semantic_manifest_rebind.v1",
            "status": "blocked",
            "changed_source_count": len(changed_sources),
            "updated_manifests": [],
            "blockers": list(dict.fromkeys(blockers)),
        }
    updated_manifests: list[dict[str, Any]] = []
    for manifest_path, rebound, report in prepared:
        if rebound != read_json_if_exists(manifest_path):
            write_json(manifest_path, rebound)
        updated_manifests.append(
            {
                "path": str(manifest_path),
                "sha256": sha256_file(manifest_path),
                "updated_field_count": report.get("updated_field_count", 0),
            }
        )
    return {
        "schema_version": "spatialaccagent.applied_semantic_manifest_rebind.v1",
        "status": "pass",
        "changed_source_count": len(changed_sources),
        "updated_manifests": updated_manifests,
        "reports": [report for _, _, report in prepared],
        "blockers": [],
    }


def scoped_capability_probe_paths(
    out_dir: Path,
    verification_scope: str,
    run_dir: Path | None = None,
) -> tuple[list[Path], dict[str, Any]]:
    """Select only probe evidence produced for the current hierarchy layer.

    Legacy logs are deliberately not guessed into a new scope. Their producer
    layer is unknowable, and treating them as current evidence can send an LLM
    into a later-layer repair loop while an earlier layer remains incomplete.
    """

    selected: list[Path] = []
    excluded_unbound = 0
    excluded_other_scope = 0
    excluded_resolved_certificate = 0
    for path in sorted(out_dir.glob("*_verification_capability_probe*.json")):
        probe = read_json_if_exists(path)
        context = (
            probe.get("probe_context", {})
            if isinstance(probe.get("probe_context"), dict)
            else {}
        )
        observed_scope = str(context.get("verification_scope") or "")
        if observed_scope == verification_scope:
            if run_dir is not None and old_lower_layer_certificate_error_is_resolved(
                probe, run_dir, verification_scope
            ):
                excluded_resolved_certificate += 1
            else:
                selected.append(path)
        elif observed_scope:
            excluded_other_scope += 1
        else:
            excluded_unbound += 1
    return selected, {
        "schema_version": CAPABILITY_PROBE_CONTEXT_SCHEMA_VERSION,
        "required_verification_scope": verification_scope,
        "selected_probe_count": len(selected),
        "excluded_unbound_probe_count": excluded_unbound,
        "excluded_other_scope_probe_count": excluded_other_scope,
        "excluded_resolved_certificate_probe_count": excluded_resolved_certificate,
        "policy": (
            "Only probes with explicit verification_scope equal to the current "
            "hierarchy layer are prompt-eligible. Historical unbound probes are "
            "retained on disk but are not reused as current repair evidence. A "
            "certificate-blocking probe is also excluded after the live lower-layer "
            "certificate has been revalidated."
        ),
    }


def capability_repair_agent_context_matches_scope(
    record: dict[str, Any],
    verification_scope: str,
) -> bool:
    context = (
        record.get("capability_repair_context", {})
        if isinstance(record.get("capability_repair_context"), dict)
        else {}
    )
    return str(context.get("verification_scope") or "") == verification_scope


def repair_execution_context_for_step(
    step: dict[str, Any],
    verification_scope: str,
) -> dict[str, Any]:
    action = step.get("action", {}) if isinstance(step.get("action"), dict) else {}
    return {
        "schema_version": REPAIR_EXECUTION_AGENT_CONTEXT_SCHEMA_VERSION,
        "repair_step_id": step.get("id"),
        "repair_scope": step.get("scope"),
        "verification_scope": verification_scope,
        "debug_layer": step.get("debug_layer") or action.get("debug_layer"),
    }


def prior_capability_producer_evidence(
    state: dict[str, Any],
    *,
    run_dir: Path,
    verification_scope: str,
) -> list[dict[str, Any]]:
    """Load hash-bound completed producers for the next same-layer Agent turn."""

    reports: list[tuple[dict[str, Any], Path]] = []
    try:
        report_path = artifact_path(state, "artifact.stage6.repair_execution_report")
    except Exception:
        report_path = run_dir / "repair_execution" / "repair_execution_report.json"
    if report_path.is_file():
        reports.append((read_json_if_exists(report_path), report_path.parent))

    loop_status_path = run_dir / "repair_execution" / "loop" / "status.json"
    loop_status = read_json_if_exists(loop_status_path)
    iteration_path_value = str(loop_status.get("latest_iteration_record") or "")
    if iteration_path_value:
        iteration_path = Path(iteration_path_value).expanduser()
        if not iteration_path.is_absolute():
            iteration_path = (loop_status_path.parent / iteration_path).resolve()
        iteration = read_json_if_exists(iteration_path)
        embedded_report = iteration.get("repair_execution_report", {})
        if isinstance(embedded_report, dict):
            reports.append((embedded_report, iteration_path.parent))
    # A completed lower-layer capability can be the exact evidence needed by
    # the next board Agent, even after a later board-only iteration has become
    # blocked. Scan newest-first rather than treating the latest iteration as
    # an accidental garbage collector for that completed producer.
    loop_records = sorted(
        loop_status_path.parent.glob("iteration_*/iteration_record.json"),
        reverse=True,
    )
    for iteration_path in loop_records:
        iteration = read_json_if_exists(iteration_path)
        embedded_report = iteration.get("repair_execution_report", {})
        if isinstance(embedded_report, dict):
            reports.append((embedded_report, iteration_path.parent))

    collected_evidence: list[dict[str, Any]] = []
    seen_evidence: set[tuple[str, str]] = set()
    for report, base_dir in reports:
        if report.get("stage") != "repair_execution":
            continue
        evidence: list[dict[str, Any]] = []
        for step in report.get("step_results", []):
            if not isinstance(step, dict):
                continue
            result = step.get("result", {})
            if not isinstance(result, dict) or result.get("requires_agent_followup") is not True:
                continue
            source_scope = verification_scope_for_step(step)
            upward_cctg_evidence = (
                verification_scope == "board_axi_ddr_closure"
                and source_scope == "single_layer_closure"
                and str(result.get("repair_kind") or "")
                in {
                    "cctg_connected_kernel_boundary_replay",
                    "connected_kernel_cctg_contradiction_targeted_replay",
                }
            )
            if source_scope != verification_scope and not upward_cctg_evidence:
                continue
            for reference in result.get("capability_reports", []):
                path_value = reference.get("path") if isinstance(reference, dict) else reference
                if not isinstance(path_value, str) or not path_value:
                    continue
                package_path = Path(path_value).expanduser()
                package_path = (
                    package_path.resolve()
                    if package_path.is_absolute()
                    else (base_dir / package_path).resolve()
                )
                if not package_path.is_file():
                    continue
                package = read_json_if_exists(package_path)
                if package.get("status") != "pass":
                    continue
                cctg = (
                    package.get("cctg_boundary_replay_evidence", {})
                    if isinstance(package.get("cctg_boundary_replay_evidence"), dict)
                    else {}
                )
                if upward_cctg_evidence and not (
                    cctg.get("fresh_remote_vcs_execution_observed") is True
                    and cctg.get("boundary_liveness_status") == "pass"
                ):
                    continue
                item = {
                    "repair_step_id": step.get("step_id"),
                    "repair_kind": result.get("repair_kind"),
                    "path": str(package_path),
                    "sha256": sha256_file(package_path),
                    "package": package,
                    "source_verification_scope": source_scope,
                    "cross_layer_promotion": upward_cctg_evidence,
                }
                identity = (item["path"], str(item["sha256"] or ""))
                if identity not in seen_evidence:
                    seen_evidence.add(identity)
                    collected_evidence.append(item)
    # Put a complete lower-layer CCTG result first, but never hide a newer
    # same-layer producer. The next Agent turn needs both its prior project
    # knowledge and the tool result it just requested to close the loop.
    promoted = [item for item in collected_evidence if item["cross_layer_promotion"]]
    same_layer = [
        item for item in collected_evidence if not item["cross_layer_promotion"]
    ]
    return [*promoted, *same_layer]


def current_dag_boundary_ids_for_signal_map(run_dir: Path) -> list[str]:
    """Return the current board run's incomplete data boundaries, if any."""

    state_path = run_dir / "verification" / "adaptive_observation" / "current.json"
    state = read_json_if_exists(state_path)
    routing = state.get("adaptive_observation_routing", {})
    routing = routing if isinstance(routing, dict) else {}
    decision = state.get("decision", {})
    decision = decision if isinstance(decision, dict) else {}
    coverage = decision.get("boundary_coverage_plan", {})
    coverage = coverage if isinstance(coverage, dict) else {}
    values = routing.get("incomplete_boundary_ids") or coverage.get("boundary_ids") or []
    return list(dict.fromkeys(str(value) for value in values if str(value).strip()))


def _sv_instantiated_module_names(source_text: str) -> list[str]:
    excluded = {
        "always",
        "always_comb",
        "always_ff",
        "assign",
        "case",
        "else",
        "for",
        "function",
        "generate",
        "if",
        "initial",
        "module",
        "task",
        "while",
    }
    pattern = re.compile(
        r"(?m)^\s*([A-Za-z_][A-Za-z0-9_$]*)\s+"
        r"(?:#\s*\([^;]*?\)\s*)?([A-Za-z_][A-Za-z0-9_$]*)\s*\("
    )
    return list(
        dict.fromkeys(
            module
            for module, _instance in pattern.findall(source_text)
            if module not in excluded
        )
    )


def _source_file_for_module(source_roots: list[Path], module: str) -> Path | None:
    for root in source_roots:
        for candidate in sorted(root.rglob(f"{module}.sv")):
            try:
                text = candidate.read_text(encoding="utf-8")
            except (OSError, UnicodeError):
                continue
            if re.search(rf"\bmodule\s+{re.escape(module)}\b", text):
                return candidate
    return None


def connected_kernel_signal_map_source_bundle(
    run_dir: Path,
    target_modules: list[str],
) -> dict[str, Any]:
    """Collect a bounded, source-hash-bound SystemVerilog bundle for an LLM map."""

    source_roots = [
        run_dir / "generated" / "board_integration",
        run_dir / "generated" / "semantic_harness",
        run_dir / "generated" / "chisel",
    ]
    source_roots = [path for path in source_roots if path.is_dir()]
    pending = list(dict.fromkeys(value for value in target_modules if value))
    selected: dict[Path, str] = {}
    seen_modules: set[str] = set()
    byte_limit = 384 * 1024
    total_bytes = 0
    while pending and len(selected) < 24 and total_bytes < byte_limit:
        module = pending.pop(0)
        if module in seen_modules:
            continue
        seen_modules.add(module)
        source_path = _source_file_for_module(source_roots, module)
        if source_path is None or source_path in selected:
            continue
        try:
            source_text = source_path.read_text(encoding="utf-8")
        except (OSError, UnicodeError):
            continue
        if total_bytes + len(source_text.encode("utf-8")) > byte_limit:
            continue
        selected[source_path] = source_text
        total_bytes += len(source_text.encode("utf-8"))
        pending.extend(_sv_instantiated_module_names(source_text))

    source_files: list[dict[str, Any]] = []
    for source_path, source_text in selected.items():
        try:
            relative_path = str(source_path.relative_to(run_dir))
        except ValueError:
            relative_path = str(source_path)
        source_files.append(
            {
                "path": relative_path,
                "sha256": sha256_file(source_path),
                "text": source_text,
            }
        )
    return {
        "source_files": source_files,
        "selected_module_count": len(selected),
        "source_byte_count": total_bytes,
        "source_byte_limit": byte_limit,
    }


def board_semantic_runtime_failure_eligible(
    simulation_evidence: dict[str, Any],
) -> tuple[bool, str]:
    """Accept only a normal failure or a fully proven semantic stall.

    The board runner intentionally terminates a proven no-progress pipeline
    with exit code 86.  That is a real functional failure even though an older
    executed-manifest shape does not populate ``simulation.status``.  Keep the
    exception narrow: the termination classification must explicitly identify
    a semantic pipeline stall and must exclude simulator and deterministic
    testbench failures.
    """

    if simulation_evidence.get("status") == "fail":
        return True, "simulation_status_fail"
    termination = simulation_evidence.get("termination_provenance", {})
    termination = termination if isinstance(termination, dict) else {}
    classification = termination.get("causal_classification", {})
    classification = classification if isinstance(classification, dict) else {}
    exit_code = simulation_evidence.get("exit_code")
    if exit_code is None:
        exit_code = termination.get("exit_code")
    if (
        exit_code == SEMANTIC_STALL_EXIT_CODE
        and classification.get("classification")
        == "proven_semantic_pipeline_stall"
        and classification.get("source_semantic_repair_eligible") is True
        and classification.get("simulator_infrastructure_failure_proven") is False
        and classification.get("deterministic_hdl_or_testbench_failure_proven")
        is False
    ):
        return True, "proven_semantic_pipeline_stall"
    return False, "no_failed_runtime_or_proven_semantic_stall"


def board_axi_protocol_failure_eligible(
    simulation_evidence: dict[str, Any],
) -> tuple[bool, str]:
    """Accept a real, explicit AXI protocol diagnostic for bounded repair.

    A protocol monitor can end a simulator with a normal process exit after
    calling ``$finish``.  In that case the runner quite correctly records a
    deterministic HDL/testbench diagnostic, but the old semantic RTL gate
    treated every such diagnostic as a reason to stop.  Only an explicit
    protocol-violation marker from the current terminal log is accepted here;
    crashes, transport failures, and ordinary testbench diagnostics remain
    ineligible.
    """

    if not isinstance(simulation_evidence, dict):
        return False, "simulation_evidence_is_not_an_object"
    termination = simulation_evidence.get("termination_provenance", {})
    termination = termination if isinstance(termination, dict) else {}
    classification = termination.get("causal_classification", {})
    classification = classification if isinstance(classification, dict) else {}
    terminal_log = termination.get("simulator_terminal_log", {})
    terminal_log = terminal_log if isinstance(terminal_log, dict) else {}
    if termination.get("status") != "complete":
        return False, "protocol_diagnostic_termination_is_incomplete"
    if termination.get("termination_source") != "normal_process_exit":
        return False, "protocol_diagnostic_did_not_use_normal_process_exit"
    if classification.get("simulator_infrastructure_failure_proven") is True:
        return False, "protocol_diagnostic_is_simulator_infrastructure_failure"
    # ``completed`` means that the workload reached its successful end marker;
    # a protocol monitor failure necessarily makes it false.  The terminal log
    # and normal simulator exit already prove that the real run executed far
    # enough to produce actionable AXI evidence.
    if simulation_evidence.get("pass_marker_seen") is True:
        return False, "protocol_diagnostic_has_a_pass_marker"
    if terminal_log.get("status") != "observed":
        return False, "protocol_diagnostic_terminal_log_is_not_observed"

    lines: list[str] = []
    for field in ("failure_lines", "matched_lines", "tail_lines"):
        values = terminal_log.get(field, [])
        if isinstance(values, list):
            lines.extend(str(value) for value in values)
    lines.append(str(termination.get("raw_terminal_log_tail") or ""))
    lines.append(str(simulation_evidence.get("summary") or ""))
    marker_text = "\n".join(lines).lower()
    explicit_marker = (
        "spatialacc_axi_protocol_violation" in marker_text
        or "axi_protocol_violation" in marker_text
    )
    if not explicit_marker:
        return False, "no_explicit_axi_protocol_violation_marker"
    return True, "explicit_axi_protocol_violation_marker"


def board_semantic_rtl_prompt_documents(
    closure: set[Path],
    source_rows_by_path: dict[Path, dict[str, Any]],
    source_text_by_path: dict[Path, str],
    seed_paths: set[Path],
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    """Keep RTL repair prompts small while retaining the full write closure.

    The complete VCS dependency closure can include generated floating-point
    and matrix modules hundreds of megabytes long.  It remains hash-bound in
    ``source_closure`` for write authorization, while the implementation Agent
    receives the source that directly owns the observed boundary plus small
    nearby control modules.  Large modules remain discoverable by path/hash
    but are not copied into the prompt.
    """

    byte_limit = 384 * 1024
    priority_tokens = (
        "gatedmlp",
        "connectedobservablellamastyleblock",
        "elementwisemul",
        "queue",
    )

    def rank(path: Path) -> tuple[int, str]:
        name = path.name.lower()
        if path in seed_paths:
            return 0, name
        for index, token in enumerate(priority_tokens, 1):
            if token in name:
                return index, name
        return len(priority_tokens) + 1, name

    documents: list[dict[str, Any]] = []
    omitted: list[dict[str, Any]] = []
    total_bytes = 0
    for path in sorted(closure, key=rank):
        source_row = source_rows_by_path[path]
        text = source_text_by_path[path]
        byte_count = len(text.encode("utf-8"))
        metadata = {
            "path": display_path(path),
            "source_path": str(path),
            "sha256": sha256_file(path),
            "bytes": byte_count,
            "declared_modules": source_row.get("declared_modules", []),
        }
        if total_bytes + byte_count <= byte_limit:
            documents.append({**metadata, "content": text, "truncated": False})
            total_bytes += byte_count
        else:
            omitted.append(metadata)
    return documents, omitted


def _incomplete_output_frontier_boundary(
    last_boundary: dict[str, Any] | None,
    causal_slice: dict[str, Any],
) -> dict[str, Any] | None:
    """Represent an output stream that started but never completed a token."""

    if not isinstance(last_boundary, dict):
        return None
    frontier = causal_slice.get("earliest_unproven_frontier")
    frontier = frontier if isinstance(frontier, dict) else {}
    observed = frontier.get("observed")
    observed = observed if isinstance(observed, dict) else {}
    if not (
        str(frontier.get("frontier_id") or "").endswith("output_stream_completion")
        and frontier.get("status") == "earliest_unproven"
        and last_boundary.get("kind") == "output"
        and last_boundary.get("transfer_observed") is True
        and isinstance(observed.get("output_started"), int)
        and observed.get("output_started") > 0
        and isinstance(observed.get("output_completed"), int)
        and observed.get("output_completed") == 0
    ):
        return None
    return {
        **copy.deepcopy(last_boundary),
        "status": "incomplete_output_stream",
        "stopped_by": "hash_bound_sacg_cctg_frontier",
    }


def current_layer3_runner_runtime_authority(
    feedback: dict[str, Any],
) -> dict[str, Any]:
    """Return the authoritative facts from the current bound Layer-3 run.

    The persisted execution manifest is written by a completed run, but an
    earlier failed elaboration can leave it stale.  A newer runner report that
    binds the exact source set and records a successful compile plus a real
    runtime terminal failure must remain actionable for the Agent.
    """

    feedback = feedback if isinstance(feedback, dict) else {}
    runner_binding = (
        feedback.get("runner_report", {})
        if isinstance(feedback.get("runner_report"), dict)
        else {}
    )
    runner = (
        runner_binding.get("value", {})
        if isinstance(runner_binding.get("value"), dict)
        else {}
    )
    compile_result = (
        runner.get("compile", {})
        if isinstance(runner.get("compile"), dict)
        else {}
    )
    run_result = (
        runner.get("run", {})
        if isinstance(runner.get("run"), dict)
        else {}
    )
    remote_workdir = str(runner.get("remote_workdir") or "")
    termination = (
        run_result.get("termination_provenance", {})
        if isinstance(run_result.get("termination_provenance"), dict)
        else {}
    )
    terminal_log = (
        termination.get("simulator_terminal_log", {})
        if isinstance(termination.get("simulator_terminal_log"), dict)
        else {}
    )
    bound = bool(
        feedback.get("status") == "ready"
        and runner.get("exact_board_preflight_passed") is True
        and runner.get("exact_job_contract_bound") is True
        and runner.get("verification_layer") == "layer3_real_board_axi_ddr"
        and is_sha256(str(runner.get("input_fingerprint_sha256") or ""))
        and is_sha256(str(runner.get("source_identity_sha256") or ""))
        and is_sha256(str(runner.get("source_closure_sha256") or ""))
        and is_sha256(str(runner.get("compile_source_set_sha256") or ""))
        and bool(remote_workdir)
        and compile_result.get("remote_workdir") == remote_workdir
        and run_result.get("remote_workdir") == remote_workdir
    )
    compile_passed = bool(
        bound
        and compile_result.get("status") == "pass"
        and compile_result.get("returncode") == 0
    )
    runtime_failed = bool(
        bound
        and run_result.get("status") == "fail"
        and str(run_result.get("failure_class") or "")
        in {"simulator_reported_terminal_failure", "vcs_runtime_failure"}
        and termination.get("status") == "complete"
        and terminal_log.get("status") == "observed"
    )
    return {
        "status": "ready" if bound else "unbound",
        "runner": runner,
        "compile": compile_result,
        "run": run_result,
        "bound": bound,
        "compile_passed": compile_passed,
        "runtime_failed": runtime_failed,
        "source_identity_sha256": runner.get("source_identity_sha256"),
        "source_closure_sha256": runner.get("source_closure_sha256"),
    }


def board_semantic_rtl_repair_authority(
    run_dir: Path,
    action: dict[str, Any],
    package: dict[str, Any],
) -> dict[str, Any]:
    """Build the narrow source authority for an internal board-pipeline repair.

    The board manifest is the only source universe.  Boundary observations seed
    the closure, and instantiated-module edges extend it.  This keeps a board
    runtime failure from granting the Agent access to the wrapper, testbench,
    data, or framework merely because those files happen to be in the VCS file
    list.
    """

    root = run_dir.resolve()
    blockers: list[str] = []

    def load(path: Path) -> dict[str, Any]:
        if not path.is_file():
            blockers.append(f"required board repair artifact is missing: {path}")
            return {}
        value = read_json_if_exists(path)
        if not value:
            blockers.append(f"required board repair artifact is empty or invalid: {path}")
        return value

    diagnosis_path = root / "verification" / "case_diagnostics" / "vcs_functional_diagnosis.json"
    manifest_path = root / "verification" / "board_simulation" / "board_simulation_executed_manifest.json"
    causal_path = root / "verification" / "case_diagnostics" / "sacg_cctg_causal_slice.json"
    signal_map_candidates = sorted(
        (root / "repair_execution").glob(
            "repair_step_*connected_kernel_boundary_signal_map.json"
        ),
        key=lambda value: value.stat().st_mtime_ns,
        reverse=True,
    )
    signal_map_path = signal_map_candidates[0] if signal_map_candidates else (
        root / "repair_execution" / "repair_step_00_connected_kernel_boundary_signal_map.json"
    )
    diagnosis = load(diagnosis_path)
    executed_manifest = load(manifest_path)
    causal_slice = load(causal_path)
    signal_map = load(signal_map_path)
    current_feedback = package.get("current_board_vcs_feedback", {})
    current_feedback = current_feedback if isinstance(current_feedback, dict) else {}
    current_runner_authority = current_layer3_runner_runtime_authority(
        current_feedback
    )
    current_runner = current_runner_authority["runner"]
    current_runner_compile = current_runner_authority["compile"]
    current_runner_run = current_runner_authority["run"]
    current_runner_is_bound = current_runner_authority["bound"]
    current_runner_compile_passed = current_runner_authority["compile_passed"]
    current_runner_runtime_failed = current_runner_authority["runtime_failed"]

    # A read-only observation edit is compiled as part of the exact board
    # source set.  If that edit introduces an XMRE, there is no runtime
    # frontier yet, but the compiler has still produced actionable current
    # evidence for the same Layer-3 Agent.  Keep this narrow: only a bound
    # prior observation source, a current compile failure, and a diagnostic
    # that names the generated board testbench qualify for this route.
    adaptive_observation_state = package.get("adaptive_observation_state", {})
    adaptive_observation_state = (
        adaptive_observation_state
        if isinstance(adaptive_observation_state, dict)
        else {}
    )
    compile_log_path = (
        root / "verification" / "board_simulation" / "reports" / "compile.log"
    )
    compile_log = (
        compile_log_path.read_text(encoding="utf-8", errors="replace")
        if compile_log_path.is_file()
        else ""
    )
    compile_observation_repair = bool(
        adaptive_observation_state.get("status") in {"pending_real_tool_evidence", "fail"}
        and isinstance(adaptive_observation_state.get("board_source_edits"), list)
        and bool(adaptive_observation_state.get("board_source_edits"))
        and any(
            isinstance(row, dict)
            and Path(str(row.get("path") or "")).name
            == "spatialacc_exact_board_multilayer_tb.sv"
            for row in adaptive_observation_state.get("board_source_edits", [])
        )
        and re.search(
            r"Error-\[XMRE\]|has not been declared|cross-module reference",
            compile_log,
            flags=re.IGNORECASE,
        )
        and "spatialacc_exact_board_multilayer_tb.sv" in compile_log
    )
    if current_feedback.get("status") != "ready":
        blockers.append("current board runner feedback is unavailable")
        runner_execution_binding = {"status": "blocked", "blockers": []}
    else:
        runner_execution_binding = _current_board_runner_binds_execution_manifest(
            root,
            current_feedback,
            manifest_path,
            executed_manifest,
        )
    # Runner/manifest identity is useful provenance, but it is not a repair
    # gate.  The current VCS result below is the evidence the Agent must fix;
    # old reports often predate the current observation fields.
    boundary_evidence = _current_board_boundary_summary_from_execution_manifest(
        root,
        executed_manifest,
    )
    boundary_summary = (
        boundary_evidence.get("summary", {})
        if boundary_evidence.get("status") == "pass"
        else {}
    )
    if not boundary_summary:
        # A partial trace is exactly what is needed to repair a live pipeline.
        # Do not make a stale cached hash or a missing terminal record hide the
        # current token frontier from the Agent.
        cached_summary_path = root / "verification" / "board_simulation" / (
            "pipeline_boundary_observation_summary.json"
        )
        boundary_summary = read_json_if_exists(cached_summary_path)

    failure_evidence = (
        diagnosis.get("failure_evidence", {})
        if isinstance(diagnosis.get("failure_evidence"), dict)
        else {}
    )
    failure_class = str(
        diagnosis.get("failure_class")
        or diagnosis.get("root_cause_class")
        or ""
    ).lower()
    execution_evidence = (
        executed_manifest.get("execution_evidence", {})
        if isinstance(executed_manifest.get("execution_evidence"), dict)
        else {}
    )
    compile_evidence = (
        execution_evidence.get("compile", {})
        if isinstance(execution_evidence.get("compile"), dict)
        else {}
    )
    simulation_evidence = (
        execution_evidence.get("simulation", {})
        if isinstance(execution_evidence.get("simulation"), dict)
        else {}
    )
    # The runner report is written after a remote VCS job finishes.  The
    # executed manifest can lag it when an earlier elaboration failed.  For a
    # bound current Layer-3 runner, use its compile/runtime facts as the
    # authority for deciding whether the Agent may repair the new evidence.
    # The manifest remains the source-universe record below.
    if current_runner_is_bound:
        compile_evidence = {
            **compile_evidence,
            "exit_code": current_runner_compile.get("returncode"),
            "status": current_runner_compile.get("status"),
        }
        simulation_evidence = {
            **simulation_evidence,
            "exit_code": current_runner_run.get("returncode"),
            "status": current_runner_run.get("status"),
            "termination_provenance": current_runner_run.get(
                "termination_provenance", {}
            ),
        }
    protocol_failure_eligible, protocol_failure_reason = (
        board_axi_protocol_failure_eligible(simulation_evidence)
        if simulation_evidence
        else (False, "simulation_evidence_is_missing")
    )
    run_record = executed_manifest.get("run", {})
    run_record = run_record if isinstance(run_record, dict) else {}
    current_board_vcs_failed = (
        simulation_evidence.get("status") == "fail"
        or executed_manifest.get("status") == "fail"
        or run_record.get("failure_class") == "simulator_reported_terminal_failure"
        or bool(run_record.get("runtime_failure_evidence"))
        or current_runner_runtime_failed
    )
    if failure_class not in {
        "intra_layer_spatial_pipeline_violation",
        "board_output_lifecycle_frontier_violation",
    } and not protocol_failure_eligible and not current_board_vcs_failed \
            and not compile_observation_repair:
        blockers.append(
            "current diagnosis is not an internal board pipeline/lifecycle failure"
        )
    termination = (
        simulation_evidence.get("termination_provenance", {})
        if isinstance(simulation_evidence.get("termination_provenance"), dict)
        else {}
    )
    termination_classification = (
        termination.get("causal_classification", {})
        if isinstance(termination.get("causal_classification"), dict)
        else {}
    )
    if not current_runner_compile_passed and compile_evidence.get("exit_code") != 0 and not compile_observation_repair:
        blockers.append("current exact-board VCS compile did not pass")
    runtime_failure_eligible, runtime_failure_reason = (
        board_semantic_runtime_failure_eligible(simulation_evidence)
    )
    if (
        not runtime_failure_eligible
        and not protocol_failure_eligible
        and not current_board_vcs_failed
        and not compile_observation_repair
    ):
        blockers.append(
            "current exact-board real workload has neither a failed runtime result "
            "nor a proven semantic pipeline stall or explicit AXI protocol diagnostic"
        )
    if (
        termination_classification.get("source_semantic_repair_eligible") is not True
        and not protocol_failure_eligible
        and not current_board_vcs_failed
        and not compile_observation_repair
    ):
        # Some older runner records put this fact in the diagnosis evidence.
        # Accept it only when the same run also proves the semantic stall and
        # explicitly excludes simulator infrastructure failure.
        fallback_eligible = (
            failure_evidence.get("adaptive_semantic_stall_evidence", {}).get("status")
            == "proven_semantic_stall"
            and termination_classification.get("simulator_infrastructure_failure_proven")
            is False
        )
        if not fallback_eligible:
            blockers.append("current termination is not proven eligible for internal RTL repair")
    if termination_classification.get("simulator_infrastructure_failure_proven") is True:
        blockers.append("current failure is attributed to simulator infrastructure")
    # A deterministic monitor diagnostic is still actionable evidence for the
    # current board RTL.  It must not be rejected merely because its exit path
    # is classified as deterministic.
    if executed_manifest.get("exact_sample_wrapper_unmodified") is not True:
        blockers.append("exact sample board wrapper is not proven unchanged")
    hierarchy = (
        executed_manifest.get("elaborated_hierarchy", {})
        if isinstance(executed_manifest.get("elaborated_hierarchy"), dict)
        else {}
    )
    current_hierarchy_path = (
        root / "verification" / "board_simulation" / "reports" / "hierarchy_report.json"
    )
    current_hierarchy = read_json_if_exists(current_hierarchy_path)
    current_hierarchy_is_bound = bool(
        current_runner_is_bound
        and current_hierarchy.get("status") == "pass"
        and current_hierarchy.get("source_identity_sha256")
        == current_runner_authority["source_identity_sha256"]
        and current_hierarchy.get("selected_simulation_source_closure_sha256")
        == current_runner_authority["source_closure_sha256"]
    )
    if current_hierarchy_is_bound:
        hierarchy = current_hierarchy
    if hierarchy.get("status") != "pass" and not compile_observation_repair:
        blockers.append("exact-board elaborated hierarchy is not a passing real-tool result")
    if hierarchy.get("certified_kernel_instance_count") != 1 and not compile_observation_repair:
        blockers.append("exact-board hierarchy does not contain exactly one certified kernel")
    if executed_manifest.get("validation_mode") != EXACT_BOARD_FUNCTIONAL_VALIDATION_MODE:
        blockers.append("exact-board validation mode is not compute_slot_axi")

    # Verify the complete current real source set before deriving any writable
    # subset.  A stale hash must never be silently excluded from the closure.
    manifest_rows = (
        executed_manifest.get("source_files", [])
        if isinstance(executed_manifest.get("source_files"), list)
        else []
    )
    source_rows_by_path: dict[Path, dict[str, Any]] = {}
    source_rows_by_module: dict[str, list[Path]] = {}
    source_rows_by_id: dict[str, dict[str, Any]] = {}
    source_text_by_path: dict[Path, str] = {}
    for index, row in enumerate(manifest_rows):
        if not isinstance(row, dict):
            blockers.append(f"board compile source row {index} is not an object")
            continue
        raw_path = str(row.get("path") or row.get("local_path") or "")
        path = Path(raw_path)
        path = (path if path.is_absolute() else root / path).resolve()
        declared_sha = str(row.get("sha256") or "")
        if not path.is_file():
            blockers.append(f"compiled board source is missing: {path}")
            continue
        # Source hashes describe the run that produced the evidence.  They are
        # informational during repair: use the current local source at this
        # path so a previous observation edit cannot strand the repair loop.
        source_rows_by_path[path] = row
        source_id = str(row.get("source_id") or "")
        if source_id:
            source_rows_by_id[source_id] = row
        try:
            text = path.read_text(encoding="utf-8")
        except (OSError, UnicodeError) as exc:
            blockers.append(f"compiled board source is unreadable: {path}: {exc}")
            continue
        source_text_by_path[path] = text
        declared_modules = row.get("declared_modules", [])
        declared_modules = declared_modules if isinstance(declared_modules, list) else []
        module_names = {
            str(value) for value in declared_modules if str(value)
        }
        module_names.update(
            re.findall(r"(?m)^\s*module\s+([A-Za-z_][A-Za-z0-9_$]*)", text)
        )
        for module in module_names:
            source_rows_by_module.setdefault(module, []).append(path)

    if not source_rows_by_path:
        blockers.append("board execution manifest contains no verified compile sources")

    boundary_rows = (
        boundary_summary.get("boundary_summaries", [])
        if isinstance(boundary_summary.get("boundary_summaries"), list)
        else []
    )
    # A new Layer-3 VCS epoch has no boundary records until the simulator
    # reaches the observation window.  That is the normal entry state for an
    # observation plan, not a failed observation and not a permission gate.
    # Keep this state explicit so a later report cannot describe it as
    # incomplete evidence from a run that has not started collecting signals.
    boundary_observation_state = (
        "not_started"
        if not boundary_rows and not compile_observation_repair
        else "partial_or_complete"
    )

    map_rows = (
        signal_map.get("boundary_signal_map", [])
        if isinstance(signal_map.get("boundary_signal_map"), list)
        else []
    )
    expected_boundary_ids = [
        str(row.get("boundary_id") or "")
        for row in boundary_rows
        if isinstance(row, dict) and row.get("boundary_id")
    ]
    map_by_boundary = {
        str(row.get("boundary_id") or ""): row
        for row in map_rows
        if isinstance(row, dict) and row.get("boundary_id")
    }
    if (
        signal_map.get("status") != "pass"
        or set(expected_boundary_ids) - set(map_by_boundary)
        or len(map_by_boundary) != len(expected_boundary_ids)
    ) and not compile_observation_repair:
        blockers.append("current internal signal map is missing one or more data boundaries")

    # Select the last boundary that transferred and the first boundary after it
    # that stopped.  A ready/valid fire is independent evidence of a transfer;
    # an earlier counter snapshot must not erase that fact.  This is a routing
    # fact, not a hardware diagnosis.
    def boundary_transferred(row: dict[str, Any]) -> bool:
        if row.get("transfer_observed") is True:
            return True
        accepted = row.get("accepted_count_max")
        return isinstance(accepted, (int, float)) and accepted > 0

    def boundary_stopped(row: dict[str, Any]) -> bool:
        if boundary_transferred(row):
            return False
        return (
            row.get("accepted_count_max") == 0
            or int(row.get("trace_record_count") or 0) > 0
        )

    last_index = -1
    last_boundary: dict[str, Any] | None = None
    for index, row in enumerate(boundary_rows):
        if not isinstance(row, dict):
            continue
        if boundary_transferred(row):
            last_index = index
            last_boundary = row
    first_stopped: dict[str, Any] | None = None
    for row in boundary_rows[last_index + 1 :]:
        if isinstance(row, dict) and boundary_stopped(row):
            first_stopped = row
            break
    if first_stopped is None:
        first_stopped = _incomplete_output_frontier_boundary(
            last_boundary,
            causal_slice,
        )
    if (
        (last_boundary is None or first_stopped is None)
        and boundary_observation_state != "not_started"
        and not compile_observation_repair
    ):
        # This remains advisory.  The Agent can add unconditional probes and
        # run the next real Layer-3 epoch to establish the frontier.
        blockers.append("current boundary trace does not provide a transferring/stopped frontier")

    # Build the seed set from the actual signal map.  Every seed must also be a
    # source from the current VCS compile set.
    seed_paths: set[Path] = set()
    allowed_closure_roles = {
        "generated_kernel",
        "compute_slot_adapter",
        "protocol_monitor",
        "testbench",
    }
    # Layer-3 observation plans need access to the generated testbench that
    # owns the read-only probes. Keep the user wrapper and memory model closed.
    generated_board_testbench_paths = {
        path
        for path, row in source_rows_by_path.items()
        if str(row.get("role") or "") == "testbench"
        and path.name == "spatialacc_exact_board_multilayer_tb.sv"
    }
    if generated_board_testbench_paths:
        allowed_closure_roles.add("testbench")
        seed_paths.update(generated_board_testbench_paths)
    if protocol_failure_eligible:
        # The generated compute-slot adapter owns the accelerator-side AXI
        # transaction timing. It is not the immutable user sample wrapper.
        seed_paths.update(
            path
            for path, row in source_rows_by_path.items()
            if str(row.get("role") or "") == "compute_slot_adapter"
        )
    for boundary_id in (
        str(last_boundary.get("boundary_id") or "") if last_boundary else "",
        str(first_stopped.get("boundary_id") or "") if first_stopped else "",
    ):
        row = map_by_boundary.get(boundary_id, {})
        refs = row.get("source_refs", {}) if isinstance(row, dict) else {}
        refs = refs if isinstance(refs, dict) else {}
        for reference in refs.values():
            if not isinstance(reference, dict):
                continue
            raw_path = str(reference.get("path") or "")
            path = Path(raw_path)
            path = (path if path.is_absolute() else root / path).resolve()
            declared_sha = str(reference.get("sha256") or "")
            manifest_row = source_rows_by_path.get(path)
            if manifest_row is None:
                blockers.append(
                    f"signal-map source is not a current compiled source: {path}"
                )
                continue
            seed_paths.add(path)
    if not seed_paths and not compile_observation_repair:
        blockers.append("signal map did not identify current compiled RTL seed sources")
    if compile_observation_repair and generated_board_testbench_paths:
        seed_paths.update(generated_board_testbench_paths)

    closure: set[Path] = set()
    pending_modules: list[str] = []
    pending_paths = list(seed_paths)
    while pending_paths or pending_modules:
        if pending_paths:
            path = pending_paths.pop(0)
        else:
            module = pending_modules.pop(0)
            matches = source_rows_by_module.get(module, [])
            if len(matches) != 1:
                if len(matches) > 1:
                    blockers.append(f"compiled module dependency is ambiguous: {module}")
                continue
            path = matches[0]
        if path in closure:
            continue
        text = source_text_by_path.get(path)
        if text is None:
            blockers.append(f"closure source text is unavailable: {path}")
            continue
        closure.add(path)
        pending_modules.extend(_sv_instantiated_module_names(text))
    if not closure and not compile_observation_repair:
        blockers.append("compiled RTL dependency closure is empty")

    non_kernel_closure_paths = [
        path
        for path in closure
        if str(source_rows_by_path[path].get("role") or "") not in allowed_closure_roles
    ]
    if non_kernel_closure_paths:
        blockers.append(
            "compiled RTL dependency closure includes a source outside the allowed generated repair roles: "
            + ", ".join(str(path) for path in sorted(non_kernel_closure_paths))
        )

    closure_rows = []
    for path in sorted(closure):
        row = source_rows_by_path[path]
        closure_rows.append(
            {
                "path": str(path),
                "relative_path": display_path(path),
                "sha256": str(row.get("sha256")),
                "source_id": row.get("source_id"),
                "role": row.get("role"),
                "declared_modules": row.get("declared_modules", []),
            }
        )
    documents, omitted_prompt_documents = board_semantic_rtl_prompt_documents(
        closure,
        source_rows_by_path,
        source_text_by_path,
        seed_paths,
    )

    compact_evidence = {
        "compile_observation_repair": {
            "status": "ready" if compile_observation_repair else "not_applicable",
            "compile_log_path": str(compile_log_path) if compile_observation_repair else None,
            "compile_log_sha256": sha256_file(compile_log_path)
            if compile_observation_repair and compile_log_path.is_file()
            else None,
            "policy": (
                "send the current observation-source compile diagnostic back to the Layer-3 Agent; "
                "repair only the generated observation source and rerun the same exact board VCS chain"
                if compile_observation_repair
                else "runtime board evidence is required for ordinary board semantic repair"
            ),
        },
        "failure_class": failure_class,
        "failure_summary": diagnosis.get("summary"),
        "current_board_fingerprint_sha256": (
            termination.get("exact_source_replay_fingerprint_sha256")
            or executed_manifest.get("input_fingerprint_sha256")
        ),
        "vcs_compile": {
            "status": "pass" if compile_evidence.get("exit_code") == 0 else "fail",
            "exit_code": compile_evidence.get("exit_code"),
            "source_set_sha256": executed_manifest.get("compile_source_set_sha256"),
        },
        "real_workload": {
            "status": simulation_evidence.get("status"),
            "exit_code": simulation_evidence.get("exit_code"),
            "repair_eligibility_reason": runtime_failure_reason,
            "axi_protocol_repair_eligibility_reason": protocol_failure_reason,
            "explicit_axi_protocol_violation": protocol_failure_eligible,
            "termination_classification": termination_classification.get("classification"),
            "source_semantic_repair_eligible": termination_classification.get(
                "source_semantic_repair_eligible"
            ),
        },
        "boundary_frontier": {
            "observation_state": boundary_observation_state,
            "last_transferring": copy.deepcopy(last_boundary),
            "first_stopped": copy.deepcopy(first_stopped),
            "coverage_status": boundary_summary.get("status"),
            "observed_boundary_count": boundary_summary.get("observed_boundary_count"),
            "required_boundary_count": boundary_summary.get("required_boundary_count"),
            "execution_trace_path": boundary_evidence.get("trace_path"),
            "execution_trace_sha256": boundary_evidence.get("trace_sha256"),
        },
        "signal_map": {
            "path": str(signal_map_path),
            "sha256": sha256_file(signal_map_path) if signal_map_path.is_file() else None,
            "selected_boundary_ids": [
                value for value in (
                    str(last_boundary.get("boundary_id") or "") if last_boundary else "",
                    str(first_stopped.get("boundary_id") or "") if first_stopped else "",
                ) if value
            ],
        },
        "sacg_cctg": {
            "path": str(causal_path),
            "sha256": sha256_file(causal_path) if causal_path.is_file() else None,
            "frontier": copy.deepcopy(causal_slice.get("earliest_unproven_frontier", {})),
        },
        "runner_execution_binding": {
            "status": runner_execution_binding.get("status"),
            "runner_report_sha256": runner_execution_binding.get("runner_sha256"),
        },
        "current_board_vcs_feedback": copy.deepcopy(current_feedback),
    }
    source_bundle = {
        "schema_version": "spatialaccagent.board_semantic_rtl_repair_source_bundle.v1",
        "status": "ready" if not blockers else "blocked",
        "documents": documents,
        "omitted_prompt_documents": omitted_prompt_documents,
        "editable_contract": {
            "board_semantic_rtl_repair_authorized": not blockers,
            "localized_allowed_exact_files": [str(path) for path in sorted(closure)],
            "require_current_sha256_for_existing_edits": False,
            "allowed_source_roles": sorted(allowed_closure_roles),
            "forbidden_targets": [
                "user_sample_testbench",
                "wrapper",
                "axi_ddr",
                "weights",
                "runtime",
                "golden",
                "checker",
                "framework",
            ],
        },
        "compiled_source_universe": [
            {
                "path": str(path),
                "sha256": str(row.get("sha256")),
                "source_id": row.get("source_id"),
                "role": row.get("role"),
            }
            for path, row in sorted(source_rows_by_path.items())
        ],
        "source_closure": closure_rows,
        "prompt_source_byte_limit": 384 * 1024,
        "prompt_source_byte_count": sum(
            int(row.get("bytes") or 0) for row in documents
        ),
        "agent_evidence": compact_evidence,
        "blockers": blockers,
    }
    # Diagnostic evidence completeness must not stop the Layer-3 repair loop.
    # The atomic editor still enforces allowed paths and valid edit anchors;
    # this authority only decides whether the Agent may receive the current
    # evidence and propose the next action.
    diagnostic_advisories = list(dict.fromkeys(blockers))
    blockers = []
    return {
        "schema_version": "spatialaccagent.board_semantic_rtl_repair_authority.v1",
        "status": "ready",
        "blockers": blockers,
        "advisories": diagnostic_advisories,
        "last_transferring_boundary": copy.deepcopy(last_boundary),
        "first_stopped_boundary": copy.deepcopy(first_stopped),
        "signal_map": {
            "path": str(signal_map_path),
            "sha256": sha256_file(signal_map_path) if signal_map_path.is_file() else None,
        },
        "execution_boundary_evidence": {
            "observation_state": boundary_observation_state,
            "status": boundary_evidence.get("status"),
            "summary_path": boundary_evidence.get("summary_path"),
            "summary_sha256": boundary_evidence.get("summary_sha256"),
            "trace_path": boundary_evidence.get("trace_path"),
            "trace_sha256": boundary_evidence.get("trace_sha256"),
        },
        "current_source_closure": closure_rows,
        "allowed_exact_files": [str(path) for path in sorted(closure)],
        "agent_evidence": compact_evidence,
        "current_board_vcs_feedback": copy.deepcopy(current_feedback),
        "source_bundle": source_bundle,
    }


def _latest_hierarchy_for_signal_map(run_dir: Path) -> dict[str, Any]:
    candidates = list(
        (run_dir / "verification").glob("**/*hierarchy_report.json")
    )
    valid: list[Path] = []
    for candidate in candidates:
        report = read_json_if_exists(candidate)
        if report.get("status") == "pass" and report.get("certified_kernel_instance"):
            valid.append(candidate)
    if not valid:
        return {}
    selected = max(valid, key=lambda path: path.stat().st_mtime)
    report = read_json_if_exists(selected)
    return {
        "path": str(selected),
        "sha256": sha256_file(selected),
        "certified_kernel_module": report.get("certified_kernel_module"),
        "certified_kernel_instance": report.get("certified_kernel_instance"),
        "instances": report.get("instances", []),
    }


def _signal_map_reference_is_bound(
    reference: Any,
    expression: str,
    source_files: dict[str, dict[str, Any]],
) -> bool:
    if not isinstance(reference, dict):
        return False
    path_value = str(reference.get("path") or "")
    source = source_files.get(path_value)
    if source is None:
        return False
    if str(reference.get("sha256") or "") != str(source.get("sha256") or ""):
        return False
    # The Agent-facing evidence contract uses explicit names. Keep the older
    # aliases readable so a previously completed, hash-bound map can be
    # revalidated after a framework update instead of asking the model again.
    line = reference.get("line_number", reference.get("line"))
    if not isinstance(line, int) or line < 1:
        return False
    lines = str(source.get("text") or "").splitlines()
    source_line = reference.get("source_line", reference.get("source_text"))
    if line > len(lines) or str(source_line or "") != lines[line - 1]:
        return False
    identifiers = re.findall(r"[A-Za-z_][A-Za-z0-9_$]*", expression)
    return bool(identifiers and identifiers[-1] in lines[line - 1])


def normalize_connected_kernel_boundary_signal_map_source_refs(
    output: dict[str, Any],
    source_bundle: dict[str, Any],
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    """Repair a small line-number drift without relaxing source identity checks.

    The model already returns the complete source line, path, and source hash. A
    line number can nevertheless move by one while it counts a generated blank
    line differently. Normalize only against that exact source line, and only
    when the match is unique or uniquely nearest to the reported line.
    """

    normalized = copy.deepcopy(output)
    source_files = {
        str(item.get("path") or ""): item
        for item in source_bundle.get("source_files", [])
        if isinstance(item, dict) and item.get("path")
    }
    corrections: list[dict[str, Any]] = []
    rows = normalized.get("boundary_signal_map", [])
    for row in rows if isinstance(rows, list) else []:
        if not isinstance(row, dict):
            continue
        references = row.get("source_refs", {})
        if not isinstance(references, dict):
            continue
        for field in ("valid", "ready", "payload"):
            reference = references.get(field)
            if not isinstance(reference, dict):
                continue
            source = source_files.get(str(reference.get("path") or ""))
            if source is None or str(reference.get("sha256") or "") != str(
                source.get("sha256") or ""
            ):
                continue
            source_line = str(
                reference.get("source_line", reference.get("source_text")) or ""
            )
            if not source_line:
                continue
            lines = str(source.get("text") or "").splitlines()
            reported_line = reference.get("line_number", reference.get("line"))
            if (
                isinstance(reported_line, int)
                and 1 <= reported_line <= len(lines)
                and lines[reported_line - 1] == source_line
            ):
                continue
            candidates = [
                index
                for index, line in enumerate(lines, start=1)
                if line == source_line
            ]
            selected_line: int | None = None
            if len(candidates) == 1:
                selected_line = candidates[0]
            elif isinstance(reported_line, int) and candidates:
                nearest_distance = min(abs(candidate - reported_line) for candidate in candidates)
                nearest = [
                    candidate
                    for candidate in candidates
                    if abs(candidate - reported_line) == nearest_distance
                ]
                if len(nearest) == 1 and nearest_distance <= 4:
                    selected_line = nearest[0]
            if selected_line is None:
                continue
            reference["line_number"] = selected_line
            reference["source_line"] = lines[selected_line - 1]
            corrections.append(
                {
                    "boundary_id": str(row.get("boundary_id") or ""),
                    "field": field,
                    "path": str(reference.get("path") or ""),
                    "reported_line": reported_line,
                    "normalized_line": selected_line,
                }
            )
    return normalized, corrections


def validate_connected_kernel_boundary_signal_map(
    output: dict[str, Any],
    expected_boundary_ids: list[str],
    source_bundle: dict[str, Any],
) -> dict[str, Any]:
    """Reject guessed expressions before a later Agent edits the testbench."""

    source_files = {
        str(item.get("path") or ""): item
        for item in source_bundle.get("source_files", [])
        if isinstance(item, dict) and item.get("path")
    }
    rows = output.get("boundary_signal_map", [])
    rows = rows if isinstance(rows, list) else []
    rows_by_boundary = {
        str(row.get("boundary_id") or ""): row
        for row in rows
        if isinstance(row, dict) and str(row.get("boundary_id") or "")
    }
    blockers: list[str] = []
    unresolved = {
        str(value) for value in output.get("unresolved_boundaries", []) if str(value)
    }
    expected = set(expected_boundary_ids)
    if output.get("status") not in {"ready", "complete"}:
        blockers.append("signal-map Agent did not return a complete map")
    if unresolved:
        blockers.append("signal-map Agent left required boundaries unresolved")
    if expected - set(rows_by_boundary):
        blockers.append("signal map is missing one or more current boundaries")
    if set(rows_by_boundary) - expected:
        blockers.append("signal map contains a boundary outside the current plan")
    for boundary_id in sorted(expected):
        row = rows_by_boundary.get(boundary_id)
        if row is None:
            continue
        expressions = {
            "valid": str(row.get("valid_source") or "").strip(),
            "ready": str(row.get("ready_source") or "").strip(),
            "payload": str(row.get("payload_source") or "").strip(),
        }
        if any(
            not value
            or value.lower() in {"null", "none", "unknown", "unavailable"}
            or "." not in value
            for value in expressions.values()
        ):
            blockers.append(f"{boundary_id} has an empty or non-hierarchical signal expression")
            continue
        references = row.get("source_refs", {})
        references = references if isinstance(references, dict) else {}
        for field, expression in expressions.items():
            if not _signal_map_reference_is_bound(
                references.get(field), expression, source_files
            ):
                blockers.append(f"{boundary_id} {field} expression is not bound to a current source line")
        fire_expression = str(row.get("fire_expression") or "")
        if not all(value in fire_expression for value in expressions.values() if value != expressions["payload"]):
            blockers.append(f"{boundary_id} fire expression does not use its valid and ready sources")
        names = [
            str(row.get(field) or "").strip()
            for field in (
                "accepted_count_name",
                "first_payload_name",
                "last_payload_name",
            )
        ]
        if any(not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", value) for value in names):
            blockers.append(f"{boundary_id} has an invalid testbench observation variable name")
    return {
        "schema_version": BOUNDARY_SIGNAL_MAP_SCHEMA_VERSION,
        "status": "pass" if not blockers else "fail",
        "blockers": blockers,
        "mapped_boundary_count": len(rows_by_boundary),
        "required_boundary_count": len(expected),
    }


def _matching_cached_boundary_signal_map_record(
    request: dict[str, Any],
    package_path: Path,
) -> dict[str, Any] | None:
    """Reuse a completed map when its current bindings still prove the rows.

    A later observation request can cover a strict subset of the boundaries
    mapped by an earlier request, and its source bundle can be a different
    traversal of the same generated hierarchy.  Requiring byte-for-byte
    equality of those two containers caused needless repeat LLM calls.  The
    safety boundary is the evidence actually used by the requested rows:
    every referenced source path/hash and the elaborated hierarchy must still
    match, then the selected rows are validated again against the current
    source bundle.
    """

    package = read_json_if_exists(package_path)
    if str(package.get("repair_kind") or "") != (
        "connected_kernel_current_dag_boundary_signal_map"
    ) or package.get("status") != "pass":
        return None
    package_validation = package.get("validation", {})
    if not isinstance(package_validation, dict) or package_validation.get("status") != "pass":
        return None
    requested_boundary_ids = [
        str(value)
        for value in request.get("required_boundary_ids", [])
        if str(value).strip()
    ]
    cached_boundary_ids = {
        str(value)
        for value in package.get("required_boundary_ids", [])
        if str(value).strip()
    }
    if not set(requested_boundary_ids).issubset(cached_boundary_ids):
        return None

    def source_identity(value: Any) -> list[tuple[str, str]]:
        bundle = value if isinstance(value, dict) else {}
        return sorted(
            (str(row.get("path") or ""), str(row.get("sha256") or ""))
            for row in bundle.get("source_files", [])
            if isinstance(row, dict)
        )

    current_sources = {
        path: sha
        for path, sha in source_identity(request.get("source_bundle"))
    }
    cached_sources = {
        path: sha
        for path, sha in source_identity(package.get("source_bundle"))
    }
    cached_output = package.get("boundary_signal_map", [])
    cached_output = cached_output if isinstance(cached_output, list) else []
    cached_rows = {
        str(row.get("boundary_id") or ""): row
        for row in cached_output
        if isinstance(row, dict) and str(row.get("boundary_id") or "")
    }
    if any(boundary_id not in cached_rows for boundary_id in requested_boundary_ids):
        return None
    # Check only source files actually referenced by the selected map rows.
    # Unreferenced files may differ because the source-closure traversal was
    # seeded with a different module list.
    referenced_sources: set[tuple[str, str]] = set()
    for boundary_id in requested_boundary_ids:
        row = cached_rows[boundary_id]
        refs = row.get("source_refs", {})
        if not isinstance(refs, dict):
            return None
        for reference in refs.values():
            if not isinstance(reference, dict):
                return None
            path = str(reference.get("path") or "")
            sha = str(reference.get("sha256") or "")
            if not path or not sha:
                return None
            referenced_sources.add((path, sha))
    if any(current_sources.get(path) != sha for path, sha in referenced_sources):
        return None
    # Keep this check for diagnostics and to reject a cache that claims a
    # referenced file under a stale cached source identity.
    if any(cached_sources.get(path) != sha for path, sha in referenced_sources):
        return None
    cached_hierarchy = package.get("elaborated_hierarchy", {})
    current_hierarchy = request.get("elaborated_hierarchy", {})
    if not isinstance(cached_hierarchy, dict) or not isinstance(current_hierarchy, dict):
        return None
    def normalized_path(value: Any) -> str:
        text = str(value or "").strip()
        return str(Path(text).expanduser().resolve()) if text else ""

    if (
        normalized_path(cached_hierarchy.get("path"))
        != normalized_path(current_hierarchy.get("path"))
        or str(cached_hierarchy.get("sha256") or "")
        != str(current_hierarchy.get("sha256") or "")
    ):
        return None

    # The validated capability package is the durable cache. A later failed
    # retry may overwrite the fixed Agent result path, but it cannot invalidate
    # source-bound rows already stored in this passing package. Revalidate the
    # requested rows below before accepting them.
    agent_record = package.get("agent_record", {})
    record_path = Path(str(agent_record.get("path") or ""))
    record = read_json_if_exists(record_path) if record_path.is_file() else {}
    agent_record_is_reusable = bool(
        record.get("mode") == "llm"
        and record.get("used_fallback") is not True
        and not record.get("error")
        and isinstance(record.get("output"), dict)
        and (
            not str(agent_record.get("sha256") or "")
            or sha256_file(record_path) == str(agent_record.get("sha256") or "")
        )
    )
    # Return a filtered, revalidated Agent record.  The caller can therefore
    # use the normal validator and never pass an out-of-scope cached boundary
    # to the next Agent.
    reused = copy.deepcopy(record) if agent_record_is_reusable else {
        "mode": "validated_capability_cache",
        "used_fallback": False,
        "error": None,
        "result_path": None,
        "cache_source_package": str(package_path.resolve()),
        "cache_source_package_sha256": sha256_file(package_path),
    }
    output = {
        "schema_version": BOUNDARY_SIGNAL_MAP_SCHEMA_VERSION,
        "agent": "connected_kernel_boundary_signal_map_agent",
        "stage": "repair_execution",
        "status": "complete",
        "summary": "reused a previously validated source-bound boundary signal map",
        "boundary_signal_map": [
        copy.deepcopy(cached_rows[boundary_id])
        for boundary_id in requested_boundary_ids
        ],
        "unresolved_boundaries": [],
    }
    normalized, _ = normalize_connected_kernel_boundary_signal_map_source_refs(
        output,
        request.get("source_bundle", {}),
    )
    validation = validate_connected_kernel_boundary_signal_map(
        normalized,
        requested_boundary_ids,
        request.get("source_bundle", {}),
    )
    if validation.get("status") != "pass":
        return None
    reused["output"] = normalized
    return reused


def produce_connected_kernel_boundary_signal_map(
    *,
    step: dict[str, Any],
    run_dir: Path,
    out_dir: Path,
) -> dict[str, Any]:
    """Ask an LLM to bind current boundary names to real generated source lines."""

    action = step.get("action", {}) if isinstance(step.get("action"), dict) else {}
    target_modules = [
        str(value) for value in action.get("target_modules", []) if str(value)
    ]
    boundary_ids = current_dag_boundary_ids_for_signal_map(run_dir)
    source_bundle = connected_kernel_signal_map_source_bundle(run_dir, target_modules)
    hierarchy = _latest_hierarchy_for_signal_map(run_dir)
    request = {
        "schema_version": BOUNDARY_SIGNAL_MAP_SCHEMA_VERSION,
        "required_boundary_ids": boundary_ids,
        "source_bundle": source_bundle,
        "elaborated_hierarchy": hierarchy,
        "policy": {
            "read_only": True,
            "do_not_edit_sources": True,
            "do_not_run_vcs": True,
            "only_current_source_hashes_are_accepted": True,
            "accepted_count_is_a_new_testbench_counter_incremented_by_fire": True,
            "first_and_last_payload_are_captured_from_payload_source_only_when_fire": True,
        },
    }
    if not boundary_ids or not source_bundle.get("source_files") or not hierarchy:
        package = {
            **request,
            "status": "fail",
            "summary": "current boundary plan, generated kernel source, or elaborated hierarchy is unavailable",
        }
        package_path = out_dir / f"{safe_step_id(step)}_connected_kernel_boundary_signal_map.json"
        write_json(package_path, package)
        return {
            "status": "fail",
            "summary": package["summary"],
            "repair_kind": "connected_kernel_current_dag_boundary_signal_map",
            "context_package": str(package_path),
            "capability_reports": [str(package_path)],
        }

    package_path = out_dir / f"{safe_step_id(step)}_connected_kernel_boundary_signal_map.json"
    llm_record = _matching_cached_boundary_signal_map_record(request, package_path)
    reused_agent_record = llm_record is not None
    if llm_record is None:
        llm_record = run_stage_agent(
            agent="connected_kernel_boundary_signal_map_agent",
            stage="repair_execution",
            task=(
                "Build a read-only map from every requested current-DAG data boundary to exact "
                "hierarchical valid, ready, and payload expressions. Use only the supplied generated "
                "SystemVerilog text and the supplied elaborated kernel instance. For every expression, "
                "cite its exact current source path, SHA-256, line number, and complete source line. "
                "Define fire_expression as valid_source and ready_source. Provide legal unique names for "
                "testbench counters and first/last payload capture variables. Do not edit files, infer a "
                "signal absent from the supplied source, diagnose hardware behavior, or request VCS. If "
                "any boundary cannot be mapped from the supplied evidence, return status=blocked and list it "
                "in unresolved_boundaries."
            ),
            inputs={"boundary_signal_map_request": request},
            out_dir=out_dir,
            fallback_summary="current internal signal map requires an evidence-bound LLM response",
            output_schema=BOUNDARY_SIGNAL_MAP_AGENT_SCHEMA,
            prompt_rules=[
                "Act only as a generated-SystemVerilog signal-map specialist.",
                "Use the supplied source text as the sole authority; do not guess a port or wire name.",
                "Return status=complete only when every requested boundary is mapped.",
                "Every source_refs entry must use path, sha256, line_number, and source_line from an exact supplied source line.",
                "The expressions must be hierarchical references below the supplied certified kernel instance.",
                "This is read-only evidence production. Do not propose a hardware repair, testbench edit, or simulation run.",
            ],
        )
    raw_output = llm_record.get("output", {})
    raw_output = raw_output if isinstance(raw_output, dict) else {}
    output, source_reference_corrections = (
        normalize_connected_kernel_boundary_signal_map_source_refs(
            raw_output,
            source_bundle,
        )
    )
    validation = validate_connected_kernel_boundary_signal_map(
        output,
        boundary_ids,
        source_bundle,
    )
    package = {
        **request,
        "status": validation["status"],
        "capability_id": str(
            action.get("requested_capability_id")
            or "connected_kernel_current_dag_boundary_signal_provenance"
        ),
        "canonical_capability_id": (
            "connected_kernel_current_dag_boundary_signal_provenance"
        ),
        "compatible_capability_ids": [
            "connected_kernel_current_dag_boundary_port_provenance",
            "connected_kernel_current_dag_boundary_signal_provenance",
        ],
        "repair_kind": "connected_kernel_current_dag_boundary_signal_map",
        "agent_record": {
            "path": llm_record.get("result_path"),
            "sha256": (
                sha256_file(Path(str(llm_record["result_path"])))
                if llm_record.get("result_path")
                and Path(str(llm_record["result_path"])).is_file()
                else None
            ),
        },
        "reused_agent_record": reused_agent_record,
        "reused_validated_capability_package": bool(
            llm_record.get("mode") == "validated_capability_cache"
        ),
        "source_reference_corrections": source_reference_corrections,
        "boundary_signal_map": output.get("boundary_signal_map", []),
        "validation": validation,
    }
    write_json(package_path, package)
    if validation["status"] != "pass":
        return {
            "status": "fail",
            "summary": "current internal signal map is incomplete or contains an unbound source expression",
            "repair_kind": "connected_kernel_current_dag_boundary_signal_map",
            "context_package": str(package_path),
            "capability_reports": [str(package_path)],
            "llm_record": llm_record.get("result_path"),
        }
    return {
        "status": "pass",
        "summary": "current internal signal map is complete and source-hash-bound; implementation Agent must consume it",
        "stage_passed": False,
        "requires_agent_followup": True,
        "repair_kind": "connected_kernel_current_dag_boundary_signal_map",
        "context_package": str(package_path),
        "capability_reports": [str(package_path)],
        "llm_record": llm_record.get("result_path"),
    }


def current_repair_agent_disposition(
    run_dir: Path,
    step: dict[str, Any],
    verification_scope: str,
) -> dict[str, Any] | None:
    """Return the current planner decision when it authorizes this repair step."""

    repair_plan_path = run_dir / "repair" / "repair_plan.json"
    if not repair_plan_path.is_file():
        return None
    repair_plan = read_json_if_exists(repair_plan_path)
    workflow = repair_plan.get("repair_workflow", {})
    if not isinstance(workflow, dict) or workflow.get("status") != "ready":
        return None
    matching_step = next(
        (
            item
            for item in workflow.get("steps", [])
            if isinstance(item, dict) and item.get("id") == step.get("id")
        ),
        None,
    )
    if matching_step is None:
        return None
    disposition = workflow.get("llm_disposition", {})
    if not isinstance(disposition, dict):
        return None
    actions = disposition.get("executable_actions", [])
    if not isinstance(actions, list) or not actions:
        return None
    return {
        "schema_version": "spatialaccagent.current_repair_agent_disposition.v1",
        "repair_plan": {
            "path": str(repair_plan_path.resolve()),
            "sha256": sha256_file(repair_plan_path),
        },
        "repair_step_id": step.get("id"),
        "repair_scope": step.get("scope"),
        "verification_scope": verification_scope,
        "status": disposition.get("status"),
        "summary": disposition.get("summary"),
        "executable_actions": copy.deepcopy(actions),
        "approval_action_ids": copy.deepcopy(
            disposition.get("approval_action_ids", [])
        ),
        "active_approval_action_ids": copy.deepcopy(
            disposition.get("active_approval_action_ids", [])
        ),
        "deferred_approval_action_ids": copy.deepcopy(
            disposition.get("deferred_approval_action_ids", [])
        ),
    }


def repair_feedback_artifact_reference(
    path: Path | None,
    *,
    kind: str,
    step: dict[str, Any],
    verification_scope: str,
) -> dict[str, Any] | None:
    """Bind a deterministic execution observation for the next LLM repair turn."""

    if path is None or not path.is_file():
        return None
    return {
        "schema_version": REPAIR_FEEDBACK_ARTIFACT_REF_SCHEMA_VERSION,
        "kind": kind,
        "path": str(path.resolve()),
        "sha256": sha256_file(path),
        "repair_execution_context": repair_execution_context_for_step(
            step,
            verification_scope,
        ),
    }


def stamp_repair_execution_agent_context(
    record: dict[str, Any],
    step: dict[str, Any],
    verification_scope: str,
) -> dict[str, Any]:
    """Persist hierarchy provenance for every Stage-6 LLM observation."""

    context = repair_execution_context_for_step(step, verification_scope)
    record["repair_execution_context"] = context
    result_path = Path(str(record.get("result_path") or ""))
    if result_path.is_file():
        persisted = read_json_if_exists(result_path)
        persisted["repair_execution_context"] = context
        write_json(result_path, persisted)
    return record


def stamp_capability_repair_agent_context(
    record: dict[str, Any],
    step: dict[str, Any],
    verification_scope: str,
) -> dict[str, Any]:
    """Keep a reusable implementation-agent observation scoped to its layer."""

    action = step.get("action", {}) if isinstance(step.get("action"), dict) else {}
    context = {
        "schema_version": CAPABILITY_REPAIR_AGENT_CONTEXT_SCHEMA_VERSION,
        "repair_step_id": step.get("id"),
        "repair_scope": step.get("scope"),
        "verification_scope": verification_scope,
        "debug_layer": step.get("debug_layer") or action.get("debug_layer"),
    }
    record["capability_repair_context"] = context
    result_path = Path(str(record.get("result_path") or ""))
    if result_path.is_file():
        persisted = read_json_if_exists(result_path)
        persisted["capability_repair_context"] = context
        write_json(result_path, persisted)
    return record


def capability_repair_source_bundle(
    source_bundle: dict[str, Any],
    run_dir: Path,
    out_dir: Path,
    *,
    focus_stage_ids: set[str] | None = None,
    verification_scope: str = "operator_leaf_closure",
    include_operator_leaf_failure_context: bool = True,
) -> dict[str, Any]:
    """Build the focused, complete source set for harness capability implementation."""

    documents: list[dict[str, Any]] = []
    seen_content: set[str] = set()
    duplicate_documents_removed = 0
    current_board_source_files: list[dict[str, Any]] = []
    current_board_manifest_file: dict[str, Any] | None = None

    def add_document(
        document: dict[str, Any] | None,
        *,
        deduplicate: bool = True,
    ) -> None:
        nonlocal duplicate_documents_removed
        if not isinstance(document, dict):
            return
        content = str(document.get("content") or "")
        if not content or document.get("truncated"):
            return
        content_hash = hashlib.sha256(content.encode("utf-8")).hexdigest()
        if deduplicate and content_hash in seen_content:
            duplicate_documents_removed += 1
            return
        seen_content.add(content_hash)
        documents.append(document)

    def add_path(path: Path, *, deduplicate: bool = True) -> None:
        if not path.is_file():
            return
        add_document(
            source_snapshot(path, path.stat().st_size + 1),
            deduplicate=deduplicate,
        )

    def add_projection(label: str, source: Path, value: Any) -> None:
        content = json.dumps(value, indent=2, sort_keys=True)
        add_document(
            {
                "path": label,
                "source_path": display_path(source),
                "source_sha256": sha256_file(source) if source.is_file() else None,
                "content_sha256": hashlib.sha256(content.encode("utf-8")).hexdigest(),
                "bytes": len(content.encode("utf-8")),
                "content": content,
                "truncated": False,
                "projection": True,
            }
        )

    def failed_stage_reports(directory: Path) -> list[Path]:
        reports: list[Path] = []
        for path in sorted(directory.glob("stage_*.json")):
            report = read_json_if_exists(path)
            if (
                report.get("status") == "fail"
                and report.get("stage_id")
                and isinstance(report.get("module_results"), list)
                and report.get("module_results")
            ):
                reports.append(path)
        return reports

    editable_contract = (
        source_bundle.get("editable_contract", {})
        if isinstance(source_bundle.get("editable_contract"), dict)
        else {}
    )
    declared_template_names = {
        Path(str(value)).name
        for field in (
            "read_only_template_sources",
            "approved_bounded_template_repair_exact_files",
        )
        for value in editable_contract.get(field, [])
        if str(value).endswith(".scala")
    }
    declared_template_paths_by_name: dict[str, set[str]] = {}
    for field in (
        "read_only_template_sources",
        "approved_bounded_template_repair_exact_files",
    ):
        for value in editable_contract.get(field, []):
            path = str(value)
            if path.endswith(".scala"):
                declared_template_paths_by_name.setdefault(Path(path).name, set()).add(path)
    declared_template_identities_by_name = {
        name: {
            str(
                (
                    Path(path)
                    if Path(path).is_absolute()
                    else Path.cwd() / Path(path)
                ).resolve()
            )
            for path in paths
        }
        for name, paths in declared_template_paths_by_name.items()
    }
    for document in materialize_declared_template_documents(
        source_bundle,
        declared_template_names,
    ):
        path = str(document.get("path") or "")
        name = Path(path.split("#", 1)[0]).name
        if name in declared_template_names:
            document_path = Path(path.split("#", 1)[0])
            document_identity = str(
                (
                    document_path
                    if document_path.is_absolute()
                    else Path.cwd() / document_path
                ).resolve()
            )
            if document_identity in declared_template_identities_by_name.get(
                name, set()
            ):
                add_document(document, deduplicate=False)

    golden_failed_reports = failed_stage_reports(run_dir / "verification" / "operator_leaf_golden")
    functional_failed_reports = failed_stage_reports(run_dir / "verification" / "operator_leaf_functional")
    current_failed_report_paths = (
        golden_failed_reports or functional_failed_reports
        if include_operator_leaf_failure_context
        and verification_scope == "operator_leaf_closure"
        else []
    )
    if focus_stage_ids:
        current_failed_report_paths = [
            path
            for path in current_failed_report_paths
            if str(read_json_if_exists(path).get("stage_id") or "") in focus_stage_ids
        ]
    failed_stage_ids = {
        str(read_json_if_exists(path).get("stage_id"))
        for path in current_failed_report_paths
        if read_json_if_exists(path).get("stage_id")
    }
    scope_bound_probe_paths, probe_scope_selection = scoped_capability_probe_paths(
        out_dir,
        verification_scope,
        run_dir,
    )

    authority_paths: set[Path] = set()
    for document in source_bundle.get("documents", []):
        if not isinstance(document, dict) or "#operator_leaf_projection" not in str(document.get("path") or ""):
            continue
        try:
            projection = json.loads(str(document.get("content") or ""))
        except json.JSONDecodeError:
            continue
        semantics = projection.get("reference_operator_semantics", {}) if isinstance(projection, dict) else {}
        adapter = semantics.get("semantic_adapter", {}) if isinstance(semantics, dict) else {}
        implementation = semantics.get("model_implementation", {}) if isinstance(semantics, dict) else {}
        authority_paths.update(
            (Path(str(value)) if Path(str(value)).is_absolute() else Path.cwd() / str(value)).resolve()
            for value in (adapter.get("path"), implementation.get("source_path"))
            if value
        )

    exact_names = {
        "model_config.json",
        "numeric_policy.json",
        "build.sbt",
        "build.properties",
        "dut_weight_binding_manifest.json",
    }
    if verification_scope == "board_axi_ddr_closure":
        exact_names.update(
            {
                "sample_project_index.json",
                "target_board_profile.json",
                "memory_layout.json",
                "single_layer_promotion_certificate.json",
            }
        )
    if verification_scope != "single_layer_closure":
        exact_names.update(
            {
                "fpga_ip_simulation_closure.json",
                "fpga_ip_modules.txt",
                "transcendental_approximation_contract.json",
                "semantic_runtime_constant_contract.json",
            }
        )
    generated_scala_token = "/generated/chisel/src/main/scala/spatialaccagent/"
    for document in source_bundle.get("documents", []):
        if not isinstance(document, dict):
            continue
        path = str(document.get("path") or "")
        normalized_path = "/" + path.lstrip("/")
        name = Path(path.split("#", 1)[0]).name
        document_path = Path(path.split("#", 1)[0])
        document_path = (
            document_path if document_path.is_absolute() else Path.cwd() / document_path
        ).resolve()
        source_path_value = str(document.get("source_path") or "")
        source_path = None
        if source_path_value:
            source_path_candidate = Path(source_path_value)
            source_path = (
                source_path_candidate
                if source_path_candidate.is_absolute()
                else Path.cwd() / source_path_candidate
            ).resolve()
        superseded_board_memory = (
            run_dir / "generated" / "memory" / "memory_layout.json"
        ).resolve()
        if verification_scope == "board_axi_ddr_closure" and (
            document_path == superseded_board_memory
            or source_path == superseded_board_memory
        ):
            continue
        if failed_stage_ids and (
            "dut_weight_binding_requirements.json#hierarchical_binding_requirements_projection" in path
            or "dut_weight_binding_requirements.json#operator_leaf_projection" in path
            or name == "dut_weight_binding_manifest.json"
        ):
            continue
        if (
            verification_scope == "single_layer_closure"
            and "#hierarchical_binding_requirements_projection" in path
        ):
            continue
        keep = (
            "#hierarchical_binding_requirements_projection" in path
            or "#operator_leaf_projection" in path
            or name in exact_names
            or generated_scala_token in normalized_path
            or document_path in authority_paths
            or source_path in authority_paths
        )
        if keep:
            add_document(document)

    semantic_manifest_path = run_dir / "verification" / "semantic_testbench" / "semantic_testbench_manifest.json"
    semantic_manifest = read_json_if_exists(semantic_manifest_path)
    if semantic_manifest:
        single_layer = (
            semantic_manifest.get("single_layer", {})
            if isinstance(semantic_manifest.get("single_layer"), dict)
            else {}
        )

        single_layer_projection = {
            key: single_layer.get(key)
            for key in (
                "status",
                "blockers",
                "testbench",
                "testbench_sha256",
                "input_vector",
                "input_vectors",
                "expected_output",
                "rtl_output_capture",
                "dut_harness",
                "real_weight_binding_manifest",
                "real_weight_binding_verified",
                "pipeline_plan_sha256",
                "pipeline_overlap_contract",
            )
        }
        for key in ("real_weight_stream", "runtime_constant_stream"):
            stream = single_layer.get(key, {}) if isinstance(single_layer.get(key), dict) else {}
            single_layer_projection[key] = {
                field: stream.get(field)
                for field in (
                    "schema_version",
                    "status",
                    "path",
                    "sha256",
                    "word_bits",
                    "word_count",
                    "contract_sha256",
                )
            }
        add_projection(
            f"{display_path(semantic_manifest_path)}#{verification_scope}_execution_projection",
            semantic_manifest_path,
            {
                key: semantic_manifest.get(key)
                for key in (
                    "schema_version",
                    "status",
                    "run_dir",
                    "reference_manifest",
                    "reference_manifest_sha256",
                    "numeric_policy",
                    "numeric_policy_sha256",
                    "numeric_comparison_policy",
                    "numeric_comparison_resolution",
                    "dut_weight_binding_requirements",
                    "dut_weight_binding_requirements_sha256",
                    "random_input",
                    "real_weight_source",
                    "accelerator_scope",
                    "policy",
                    "blockers",
                )
            }
            | {
                "single_layer": single_layer_projection,
                "stage_contracts": (
                    [
                        {
                            key: row.get(key)
                            for key in (
                                "stage_id",
                                "op",
                                "status",
                                "weight_layout_contract_sha256",
                                "runtime_constant_contract_sha256",
                            )
                        }
                        for row in semantic_manifest.get("stage_contracts", [])
                        if isinstance(row, dict)
                    ]
                    if verification_scope == "single_layer_closure"
                    else [
                        row
                        for row in semantic_manifest.get("stage_contracts", [])
                        if isinstance(row, dict)
                        and (not failed_stage_ids or str(row.get("stage_id")) in failed_stage_ids)
                    ]
                ),
            },
        )

    if verification_scope == "board_axi_ddr_closure":
        board_manifest_path = run_dir / "generated" / "memory" / "dut_weight_binding_manifest.json"
        if board_manifest_path.is_file():
            add_path(board_manifest_path, deduplicate=False)
            current_board_manifest_file = {
                "path": display_path(board_manifest_path),
                "sha256": sha256_file(board_manifest_path),
                "bytes": board_manifest_path.stat().st_size,
            }
        board_root = run_dir / "generated" / "board_integration"
        for path in sorted(board_root.rglob("*")):
            if not path.is_file() or path.suffix.lower() not in BOARD_INTEGRATION_SOURCE_SUFFIXES:
                continue
            add_path(path, deduplicate=False)
            current_board_source_files.append(
                {
                    "path": display_path(path),
                    "sha256": sha256_file(path),
                    "bytes": path.stat().st_size,
                }
            )
        board_identity_path = (
            run_dir / "verification" / "board_interface" / "board_source_identity.json"
        )
        board_identity = read_json_if_exists(board_identity_path)
        compile_authority_ref = (
            board_identity.get("simulator_compile_authority", {})
            if isinstance(board_identity.get("simulator_compile_authority"), dict)
            else {}
        )
        compile_authority_path = Path(str(compile_authority_ref.get("path") or ""))
        if compile_authority_ref.get("path") and not compile_authority_path.is_absolute():
            compile_authority_path = board_identity_path.parent / compile_authority_path
        board_authority_paths = (
            board_identity_path,
            run_dir / "verification" / "hierarchy" / "multilayer_pipeline.json",
            run_dir / "verification" / "model_weights" / "transformer_block_weight_catalog.json",
            run_dir / "generated" / "chisel" / "memory" / "memory_layout.json",
            run_dir / "input" / "model_config.json",
            run_dir / "input" / "target_board_profile.json",
            Path.cwd() / "accagent" / "framework" / "board_acceptance_contract.py",
            Path.cwd() / "scripts" / "verification" / "case_board_vcs_functional.py",
        )
        for path in board_authority_paths:
            add_path(path)
        if compile_authority_path.is_file():
            add_path(compile_authority_path)
        selected_source_ids = {
            str(value)
            for value in board_identity.get("discovery_selected_source_ids", [])
            if str(value)
        }
        closure_rows = _exact_board_closure_rows(board_identity)
        for row in closure_rows:
            if not isinstance(row, dict):
                continue
            source_id = str(row.get("source_id") or "")
            role = str(row.get("role") or "").lower()
            if source_id not in selected_source_ids and role not in {
                "wrapper",
                "board_wrapper",
                "sample_wrapper",
            }:
                continue
            source_path = Path(str(row.get("local_path") or row.get("path") or ""))
            if source_path.is_file():
                add_path(source_path)

    requirements_path = run_dir / "verification" / "semantic_testbench" / "dut_weight_binding_requirements.json"
    requirements = read_json_if_exists(requirements_path)
    if requirements:
        add_projection(
            f"{display_path(requirements_path)}#{verification_scope}_requirements_projection",
            requirements_path,
            {
                key: requirements.get(key)
                for key in (
                    "schema_version",
                    "status",
                    "accelerator_scope",
                    "source_checkpoint_sha256",
                    "source_reference_manifest",
                    "source_reference_sha256",
                    "model_semantic_adapter_sha256",
                    "numeric_policy",
                    "numeric_policy_sha256",
                    "canonical_weight_stream_contract",
                    "connected_weight_stream_contract",
                    "connected_runtime_stream_contract",
                    "single_layer_pipeline_overlap_contract",
                    "standard_harness_interface",
                    "stream_metadata_contract",
                    "semantic_runtime_constant_contract",
                    "required_manifest_fields",
                    "agent_manifest_schema",
                    "agent_manifest_example",
                    "single_layer_required_tensors",
                    "policy",
                )
            }
            | {
                "stage_requirements": [
                    row
                    for row in requirements.get("stage_requirements", [])
                    if isinstance(row, dict)
                    and (not failed_stage_ids or str(row.get("stage_id")) in failed_stage_ids)
                ]
            },
        )

    binding_manifest_path = run_dir / "generated" / "memory" / "dut_weight_binding_manifest.json"
    binding_manifest = read_json_if_exists(binding_manifest_path)
    if binding_manifest and verification_scope == "single_layer_closure":
        add_projection(
            f"{display_path(binding_manifest_path)}#single_layer_closure_binding_merge_authority",
            binding_manifest_path,
            {
                "schema_version": binding_manifest.get("schema_version"),
                "status": binding_manifest.get("status"),
                "accelerator_scope": binding_manifest.get("accelerator_scope"),
                "source_checkpoint_sha256": binding_manifest.get(
                    "source_checkpoint_sha256"
                ),
                "source_reference_sha256": binding_manifest.get(
                    "source_reference_sha256"
                ),
                "model_semantic_adapter_sha256": binding_manifest.get(
                    "model_semantic_adapter_sha256"
                ),
                "numeric_policy_sha256": binding_manifest.get(
                    "numeric_policy_sha256"
                ),
                "single_layer_harness": binding_manifest.get(
                    "single_layer_harness"
                ),
                "merge_json_contract": {
                    "target_path": display_path(binding_manifest_path),
                    "target_exists": True,
                    "target_sha256": sha256_file(binding_manifest_path),
                    "operation": "merge_json",
                    "patch_root": "single_layer_harness",
                    "omitted_siblings_are_preserved": True,
                    "preserved_sibling_keys": sorted(
                        key
                        for key in binding_manifest
                        if key != "single_layer_harness"
                    ),
                },
            },
        )
    elif binding_manifest:
        stage_harnesses = (
            binding_manifest.get("stage_harnesses", {})
            if isinstance(binding_manifest.get("stage_harnesses"), dict)
            else {}
        )
        add_projection(
            f"{display_path(binding_manifest_path)}#{verification_scope}_binding_projection",
            binding_manifest_path,
            {
                key: binding_manifest.get(key)
                for key in (
                    "schema_version",
                    "status",
                    "accelerator_scope",
                    "source_checkpoint_sha256",
                    "source_reference_sha256",
                    "model_semantic_adapter_sha256",
                    "numeric_policy_sha256",
                    "scope_coverage_complete",
                    "dut_consumes_bound_weights",
                    "default_or_identity_weight_fallback_disabled",
                    "consumed_tensor_hashes",
                    "materialization_blockers",
                    "single_layer_harness",
                )
            }
            | {
                "stage_harnesses": {
                    stage_id: stage_harnesses.get(stage_id)
                    for stage_id in sorted(failed_stage_ids)
                    if stage_id in stage_harnesses
                }
            },
        )

    implementation_sources = (
        (Path.cwd() / "scripts" / "verification" / "semantic_testbench_generator.py",)
        if verification_scope == "single_layer_closure"
        else (
            Path.cwd() / "scripts" / "verification" / "semantic_testbench_generator.py",
            Path.cwd() / "accagent" / "framework" / "weight_layout.py",
            Path.cwd() / "accagent" / "framework" / "semantic_runtime.py",
            Path.cwd() / "accagent" / "framework" / "semantic_simulator.py",
        )
    )
    prior_execution_artifacts = (
        (
            out_dir / "agent_patch_application.json",
            out_dir / "agent_requested_validation.json",
            out_dir / "dut_weight_binding_materialization.json",
        )
        if verification_scope == "single_layer_closure"
        else (
            out_dir / "semantic_template_repair_progress.json",
            out_dir / "agent_patch_application.json",
            out_dir / "agent_requested_validation.json",
            out_dir / "agent_requested_validation_resource_resume.json",
            out_dir / "dut_weight_binding_materialization.json",
            *(
                ()
                if verification_scope == "board_axi_ddr_closure"
                else (out_dir / "repair_execution_report.json",)
            ),
        )
    )
    for path in (*implementation_sources, *prior_execution_artifacts):
        add_path(path)
    if verification_scope != "single_layer_closure":
        for path in sorted(out_dir.glob("agent_requested_validation_*.json")):
            add_path(path)
        for path in sorted(out_dir.glob("semantic_template_repair_*.json")):
            if path.name != "semantic_template_repair_progress.json":
                add_path(path)
    if verification_scope != "board_axi_ddr_closure":
        for path in scope_bound_probe_paths:
            add_path(path)
    if verification_scope == "single_layer_closure":
        for path in (
            run_dir / "verification" / "single_layer" / "single_layer_functional_report.json",
            run_dir / "verification" / "single_layer" / "single_layer_golden_compare.json",
            run_dir / "verification" / "real_tools" / "case_single_layer_semantic_evidence.json",
        ):
            add_path(path)
    prior_agent_result_path = out_dir / "llm" / "verification_capability_repair_agent_result.json"
    prior_agent_result = read_json_if_exists(prior_agent_result_path)
    if prior_agent_result and capability_repair_agent_context_matches_scope(
        prior_agent_result,
        verification_scope,
    ):
        prior_output = prior_agent_result.get("output", {}) if isinstance(prior_agent_result.get("output"), dict) else {}
        add_projection(
            f"{display_path(prior_agent_result_path)}#prior_agent_feedback_projection",
            prior_agent_result_path,
            {
                "duration_sec": prior_agent_result.get("duration_sec"),
                "error": prior_agent_result.get("error"),
                "retry_errors": prior_agent_result.get("retry_errors", []),
                "output": {
                    key: prior_output.get(key)
                    for key in (
                        "schema_version",
                        "status",
                        "summary",
                        "root_cause",
                        "blocked_reasons",
                        "approval_required_for",
                        "file_edits",
                        "requested_validation",
                    )
                },
            },
        )
    elif prior_agent_result:
        probe_scope_selection["excluded_prior_agent_result_count"] = 1

    editable_scala_root = (
        run_dir
        / "generated"
        / "chisel"
        / "src"
        / "main"
        / "scala"
        / "spatialaccagent"
        / "semantic_harness"
    )
    for path in sorted(editable_scala_root.glob("**/*")):
        if path.is_file():
            add_path(path)
    if verification_scope == "single_layer_closure":
        connected_scala_root = editable_scala_root.parent
        for path in sorted((connected_scala_root / "generated").glob("*.scala")):
            add_path(path)
        for path in sorted((connected_scala_root / "templates").glob("*.scala")):
            add_path(path)

    current_failure_summaries: list[dict[str, Any]] = []
    failed_harness_tops: list[str] = []
    for failed_path in current_failed_report_paths:
        failed_report = read_json_if_exists(failed_path)
        add_path(failed_path)
        contract_path = repo_path(failed_report.get("semantic_contract_path"))
        contract = read_json_if_exists(contract_path)
        add_path(contract_path)
        harness = contract.get("dut_harness", {}) if isinstance(contract.get("dut_harness"), dict) else {}
        harness_top = str(harness.get("top_module") or "")
        if harness_top:
            failed_harness_tops.append(harness_top)
        execution = next(
            (row for row in failed_report.get("module_results", []) if isinstance(row, dict)),
            {},
        )
        for name in ("testbench", "vcs_log", "sim_log"):
            if execution.get(name):
                add_path(repo_path(execution[name]))
        for row in harness.get("source_files", []):
            if not isinstance(row, dict) or not row.get("path"):
                continue
            source_path = repo_path(row["path"])
            if not source_path.is_file():
                continue
            try:
                source_text = source_path.read_text(encoding="utf-8")
            except (OSError, UnicodeDecodeError):
                continue
            if harness_top and re.search(rf"(?m)^module\s+{re.escape(harness_top)}\b", source_text):
                add_path(source_path)
                break
        current_failure_summaries.append(
            {
                "stage_id": failed_report.get("stage_id"),
                "gate": failed_report.get("gate"),
                "failed_report": display_path(failed_path),
                "failed_report_sha256": sha256_file(failed_path),
                "semantic_contract": display_path(contract_path) if contract_path.is_file() else None,
                "harness_top_module": harness_top or None,
                "target_failure_diagnostics": semantic_failure_diagnostics(failed_report),
                "first_failed_module": failed_report.get("first_failed_module"),
                "first_failed_summary": failed_report.get("first_failed_summary"),
                "rtl_output_sha256": execution.get("rtl_output_sha256"),
                "input_fingerprint_sha256": execution.get("input_fingerprint_sha256"),
            }
        )

    harness_scala_path = editable_scala_root / "SemanticHarnesses.scala"
    harness_scala_text = harness_scala_path.read_text(encoding="utf-8") if harness_scala_path.is_file() else ""

    def scala_definition_block(text: str, symbol: str) -> str:
        match = re.search(
            rf"\b(?:final\s+case\s+class|case\s+class|abstract\s+class|class|object|trait)\s+{re.escape(symbol)}\b[^{{]*\{{",
            text,
        )
        if not match:
            return ""
        start = text.find("{", match.start())
        depth = 0
        for index in range(start, len(text)):
            if text[index] == "{":
                depth += 1
            elif text[index] == "}":
                depth -= 1
                if depth == 0:
                    return text[match.start() : index + 1]
        return text[match.start() :]

    template_root = editable_scala_root.parent / "templates"
    template_symbols: dict[str, Path] = {}
    template_texts: dict[Path, str] = {}
    for path in sorted(template_root.glob("*.scala")):
        text = path.read_text(encoding="utf-8")
        template_texts[path] = text
        for symbol in re.findall(
            r"\b(?:final\s+case\s+class|case\s+class|abstract\s+class|class|object|trait)\s+([A-Za-z_][A-Za-z0-9_]*)",
            text,
        ):
            template_symbols[symbol] = path

    referenced_symbols: set[str] = set()
    for harness_top in failed_harness_tops:
        body = scala_definition_block(harness_scala_text, harness_top)
        referenced_symbols.update(re.findall(r"\bnew\s+([A-Za-z_][A-Za-z0-9_]*)", body))
    selected_template_paths: set[Path] = set()
    pending_symbols = list(sorted(referenced_symbols))
    while pending_symbols:
        symbol = pending_symbols.pop()
        path = template_symbols.get(symbol)
        if path is None or path in selected_template_paths:
            continue
        selected_template_paths.add(path)
        text = template_texts[path]
        pending_symbols.extend(
            dependency
            for dependency in re.findall(r"\bnew\s+([A-Za-z_][A-Za-z0-9_]*)", text)
            if dependency in template_symbols
        )
    common_template = template_root / "Common.scala"
    if selected_template_paths and common_template.is_file():
        selected_template_paths.add(common_template)
    for path in sorted(selected_template_paths):
        add_path(path)
    if selected_template_paths:
        add_projection(
            f"{display_path(harness_scala_path)}#failed_harness_template_dependency_projection",
            harness_scala_path,
            {
                "failed_harness_top_modules": sorted(set(failed_harness_tops)),
                "referenced_constructor_symbols": sorted(referenced_symbols),
                "selected_read_only_template_sources": [display_path(path) for path in sorted(selected_template_paths)],
                "policy": "complete compile-validated template bodies are read-only until boundary evidence authorizes a bounded template repair",
            },
        )

    if verification_scope != "single_layer_closure":
        for path in (
            run_dir / "verification" / "debug_closure" / "boundary_contracts.json",
            run_dir / "verification" / "debug_closure" / "trace_manifest.json",
            run_dir / "verification" / "debug_closure" / "failure_localization.json",
        ):
            add_path(path)
    verification_report_paths = (
        ()
        if verification_scope == "single_layer_closure"
        else (
            run_dir / "verification" / "verification_result.json",
            run_dir / "verification" / "verification_report.json",
        )
    )
    for path in verification_report_paths:
        report = read_json_if_exists(path)
        if report:
            add_projection(
                f"{display_path(path)}#current_operator_leaf_failure_projection",
                path,
                {
                    "schema_version": report.get("schema_version"),
                    "status": report.get("status"),
                    "summary": report.get("summary"),
                    "execution_scope": report.get("execution_scope") or report.get("gate_execution_scope"),
                    "hierarchical_gate_summary": report.get("hierarchical_gate_summary", {}),
                    "hierarchical_repair_loop": report.get("hierarchical_repair_loop", {}),
                    "failed_or_current_leaf_results": [
                        {
                            "checker": row.get("checker"),
                            "status": row.get("status"),
                            "summary": str(row.get("summary") or "")[-4000:],
                            "log_path": row.get("log_path"),
                        }
                        for row in report.get("results", [])
                        if isinstance(row, dict)
                        and (
                            row.get("status") == "fail"
                            or "leaf" in str(row.get("checker") or "").lower()
                            or "debug_closure" in str(row.get("checker") or "").lower()
                        )
                    ],
                    "promotion_certificates": report.get("promotion_certificates", {}),
                },
            )
    repair_plan_path = run_dir / "repair" / "repair_plan.json"
    repair_plan = read_json_if_exists(repair_plan_path)
    if repair_plan:
        workflow = repair_plan.get("repair_workflow", {}) if isinstance(repair_plan.get("repair_workflow"), dict) else {}
        add_projection(
            f"{display_path(repair_plan_path)}#current_repair_action_projection",
            repair_plan_path,
            {
                "schema_version": repair_plan.get("schema_version"),
                "status": repair_plan.get("status"),
                "repair_actions": [
                    {
                        key: action.get(key)
                        for key in (
                            "scope",
                            "repair_kind",
                            "debug_layer",
                            "repair_gate",
                            "root_candidate_module",
                            "target_modules",
                            "reason",
                        )
                    }
                    for action in repair_plan.get("repair_actions", [])
                    if isinstance(action, dict)
                ],
                "repair_workflow": {
                    "status": workflow.get("status"),
                    "llm_disposition": workflow.get("llm_disposition", {}),
                    "steps": [
                        {
                            "id": step.get("id"),
                            "scope": step.get("scope"),
                            "status": step.get("status"),
                            "repair_kind": step.get("action", {}).get("repair_kind")
                            if isinstance(step.get("action"), dict)
                            else None,
                            "repair_phase": step.get("action", {}).get("repair_phase")
                            if isinstance(step.get("action"), dict)
                            else None,
                            "llm_disposition_constraint": step.get("llm_disposition_constraint"),
                        }
                        for step in workflow.get("steps", [])
                        if isinstance(step, dict)
                    ],
                },
            },
        )

    failure_context: dict[str, Any] = {}
    failed_report_path: Path | None = None
    probe_paths = sorted(
        (
            path
            for path in scope_bound_probe_paths
            if path.name.endswith("_verification_capability_probe_pre_patch.json")
        ),
        key=lambda path: path.stat().st_mtime,
        reverse=True,
    )
    candidate_report_paths: list[Path] = []
    failure_snapshot = out_dir / "focused_real_tool_failure_snapshot.json"
    candidate_report_paths.extend(current_failed_report_paths)
    if (
        include_operator_leaf_failure_context
        and verification_scope == "operator_leaf_closure"
        and not current_failed_report_paths
        and failure_snapshot.is_file()
    ):
        candidate_report_paths.append(failure_snapshot)
    for probe_path in probe_paths:
        probe = read_json_if_exists(probe_path)
        for row in probe.get("produced_reports", []):
            if isinstance(row, dict) and row.get("status") != "pass" and row.get("path"):
                candidate_report_paths.append(repo_path(row["path"]))
    if (
        include_operator_leaf_failure_context
        and verification_scope == "operator_leaf_closure"
    ):
        candidate_report_paths.extend(sorted((run_dir / "verification" / "operator_leaf_golden").glob("stage_*.json")))
        candidate_report_paths.extend(sorted((run_dir / "verification" / "operator_leaf_functional").glob("stage_*.json")))
    for path in candidate_report_paths:
        report = read_json_if_exists(path)
        if (
            report.get("status") == "fail"
            and isinstance(report.get("module_results"), list)
            and report.get("module_results")
        ):
            failed_report_path = path
            break

    if failed_report_path is not None:
        failed_report = read_json_if_exists(failed_report_path)
        add_path(failed_report_path)
        contract_path = repo_path(failed_report.get("semantic_contract_path"))
        contract = read_json_if_exists(contract_path)
        add_path(contract_path)
        harness = contract.get("dut_harness", {}) if isinstance(contract.get("dut_harness"), dict) else {}
        harness_top = str(harness.get("top_module") or "")
        declared_module_sources: dict[str, Path] = {}
        source_hash_errors: list[str] = []
        for row in harness.get("source_files", []):
            if not isinstance(row, dict) or not row.get("path"):
                continue
            path = repo_path(row["path"])
            if not path.is_file():
                source_hash_errors.append(f"missing source: {display_path(path)}")
                continue
            expected_hash = str(row.get("sha256") or "")
            if expected_hash and sha256_file(path) != expected_hash:
                source_hash_errors.append(f"source hash mismatch: {display_path(path)}")
                continue
            try:
                text = path.read_text(encoding="utf-8")
            except (OSError, UnicodeDecodeError):
                continue
            for module in re.findall(r"(?m)^module\s+([A-Za-z_][A-Za-z0-9_$]*)\b", text):
                declared_module_sources[module] = path
        causal_sources: list[Path] = []
        top_source = declared_module_sources.get(harness_top)
        if top_source is not None:
            causal_sources.append(top_source)
            top_text = top_source.read_text(encoding="utf-8")
            for module, path in sorted(declared_module_sources.items()):
                if module == harness_top:
                    continue
                if re.search(
                    rf"\b{re.escape(module)}\s+(?:#\s*\([^;]*?\)\s*)?[A-Za-z_][A-Za-z0-9_$]*\s*\(",
                    top_text,
                    re.DOTALL,
                ):
                    causal_sources.append(path)
        causal_source_inventory: list[dict[str, Any]] = []
        for path in dict.fromkeys(causal_sources):
            source_bytes = path.stat().st_size
            include_body = path == top_source or source_bytes <= MAX_INLINE_EMITTED_DEPENDENCY_BYTES
            if include_body:
                add_path(path)
            causal_source_inventory.append(
                {
                    "path": display_path(path),
                    "sha256": sha256_file(path),
                    "bytes": source_bytes,
                    "declared_modules": sorted(
                        module
                        for module, source_path in declared_module_sources.items()
                        if source_path == path
                    ),
                    "role": "failed_harness_top" if path == top_source else "direct_emitted_dependency",
                    "body_included": include_body,
                    "body_omission_reason": (
                        None
                        if include_body
                        else (
                            "generated dependency exceeds the bounded inline size; inspect the complete "
                            "compile-validated Scala template source and this immutable path/hash/module inventory"
                        )
                    ),
                }
            )
        if causal_source_inventory:
            add_projection(
                f"{display_path(failed_report_path)}#emitted_causal_source_inventory",
                failed_report_path,
                {
                    "failed_harness_top_module": harness_top or None,
                    "max_inline_dependency_bytes": MAX_INLINE_EMITTED_DEPENDENCY_BYTES,
                    "sources": causal_source_inventory,
                    "policy": (
                        "The failed harness top body is always included. Small direct emitted dependencies are "
                        "included in full. Large generated dependencies remain immutable and fully identified by "
                        "path, SHA-256, byte count, and declared modules; their complete compile-validated Scala "
                        "sources are supplied separately."
                    ),
                },
            )

        evidence_paths: list[Path] = []
        for result in failed_report.get("module_results", []):
            if not isinstance(result, dict):
                continue
            for name in ("testbench", "vcs_log", "sim_log"):
                if result.get(name):
                    evidence_paths.append(repo_path(result[name]))
            downloads = result.get("downloads", {}) if isinstance(result.get("downloads"), dict) else {}
            for value in downloads.values():
                if value:
                    evidence_paths.append(repo_path(value))
        for path in dict.fromkeys(evidence_paths):
            add_path(path)
        failure_context = {
            "failed_report": display_path(failed_report_path),
            "failed_report_sha256": sha256_file(failed_report_path),
            "semantic_contract": display_path(contract_path) if contract_path.is_file() else None,
            "harness_top_module": harness_top or None,
            "causal_source_files": [display_path(path) for path in dict.fromkeys(causal_sources)],
            "real_tool_evidence_files": [
                display_path(path) for path in dict.fromkeys(evidence_paths) if path.is_file()
            ],
            "source_integrity_errors": source_hash_errors,
            "target_failure_diagnostics": semantic_failure_diagnostics(failed_report),
            "first_failed_module": failed_report.get("first_failed_module"),
            "first_failed_summary": failed_report.get("first_failed_summary"),
            "emitted_causal_source_inventory": causal_source_inventory,
            "selection_policy": "first failed current capability report with module-level real-tool evidence",
        }
        add_projection(
            f"{display_path(failed_report_path)}#focused_real_tool_failure_context",
            failed_report_path,
            failure_context,
        )
    if current_failure_summaries:
        failure_context["current_failed_reports"] = current_failure_summaries
        failure_context["failed_stage_ids"] = sorted(failed_stage_ids)
        failure_context["selection_policy"] = "current failed golden reports first, then current failed functional reports"

    consumer_functions = (
        allowed_capability_edit_target,
        apply_agent_file_edits,
        normalize_harness_sources,
        run_agent_requested_validation,
        harness_contract_errors,
        connected_harness_contract_errors,
        *(
            (
                bind_agent_owned_board_source_hashes,
                board_integration_binding_errors,
                _exact_board_closure_rows,
                _safe_board_relative_path,
                _generated_rtl_modules,
                _normalize_exact_board_source,
                _normalize_exact_board_artifact,
                authoritative_board_weight_artifact,
                materialize_exact_board_preflight_manifest,
            )
            if verification_scope == "board_axi_ddr_closure"
            else ()
        ),
        finalize_dut_weight_binding_manifest,
    )
    consumer_source = "\n\n".join(inspect.getsource(function) for function in consumer_functions)
    add_projection(
        f"{display_path(Path(__file__))}#exact_capability_consumer_functions",
        Path(__file__),
        {
            "language": "python",
            "source": consumer_source,
            "functions": [function.__name__ for function in consumer_functions],
        },
    )

    editable = dict(source_bundle.get("editable_contract", {}))
    editable.update(
        {
            "bounded_template_repair_approved": False,
            "semantic_template_repair_approved": False,
            "approved_bounded_template_repair_exact_files": [],
            "templates_read_only_after_compiled_semantic_baseline": True,
            "template_repair_deferred_until_real_localized_failure": True,
        }
    )
    if verification_scope == "board_axi_ddr_closure":
        board_root = run_dir / "generated" / "board_integration"
        board_manifest_path = (
            run_dir / "generated" / "memory" / "dut_weight_binding_manifest.json"
        )
        board_manifest_projection = read_json_if_exists(board_manifest_path)
        projected_plan = board_manifest_projection.get(
            "board_simulation_preflight_plan"
        )
        if isinstance(projected_plan, dict):
            projected_plan["validation_mode"] = "compute_slot_axi"
            projected_plan.pop("external_simulation_fixture", None)
        roots = [str(value) for value in editable.get("allowed_create_or_replace_roots", [])]
        if display_path(board_root) not in roots:
            roots.append(display_path(board_root))
        editable.update(
            {
                "allowed_create_or_replace_roots": roots,
                "board_integration_repair_authorized": True,
                "board_integration_root": display_path(board_root),
                "current_board_manifest_file": current_board_manifest_file,
                "board_manifest_rewrite_authority": (
                    board_manifest_lossless_rewrite_authority(
                        run_dir,
                        out_dir,
                        board_manifest_path,
                        manifest_override=board_manifest_projection,
                    )
                    if current_board_manifest_file
                    else {}
                ),
                "current_board_source_files": current_board_source_files,
                "user_sample_project_sources_read_only": True,
            }
        )
    read_only_templates = [
        str(document.get("path"))
        for document in documents
        if "/generated/chisel/src/main/scala/spatialaccagent/templates/" in ("/" + str(document.get("path") or "").lstrip("/"))
    ]
    editable["read_only_template_sources"] = sorted(read_only_templates)
    document_chars = sum(len(str(document.get("content") or "")) for document in documents)
    return {
        "schema_version": "spatialaccagent.repair_source_bundle.v1",
        "bundle_profile": "semantic_harness_capability_implementation",
        "verification_scope": verification_scope,
        "documents": documents,
        "document_count": len(documents),
        "document_chars": document_chars,
        "all_documents_complete": all(not document.get("truncated") for document in documents),
        "duplicate_content_documents_removed": duplicate_documents_removed,
        "omitted_redundant_context": [
            "byte-identical persistent template bodies after compiled semantic baseline",
            "unrelated emitted SystemVerilog bodies outside the earliest real-tool causal slice",
            f"board and backend case material outside {verification_scope}",
            "superseded broad stage-planning reports already projected into current immutable requirements",
        ],
        "prior_capability_repair_evidence": {
            "patch_application": str(out_dir / "agent_patch_application.json"),
            "requested_validation": str(out_dir / "agent_requested_validation.json"),
            "binding_materialization": str(out_dir / "dut_weight_binding_materialization.json"),
            "repair_execution_report": str(out_dir / "repair_execution_report.json"),
            "policy": "when present, these are authoritative feedback for the next repair iteration",
        },
        "capability_probe_scope_selection": probe_scope_selection,
        "generated_module_inventory": source_bundle.get("generated_module_inventory", []),
        "focused_real_tool_failure_context": failure_context,
        "fpga_ip_repair_closure": source_bundle.get("fpga_ip_repair_closure", {}),
        "editable_contract": editable,
    }


def localized_semantic_report_decision_projection(
    report: dict[str, Any],
    trace_record: dict[str, Any],
    corroborating_numeric_failure: dict[str, Any] | None,
) -> dict[str, Any]:
    internal_trace = [
        row for row in report.get("internal_boundary_trace", []) if isinstance(row, dict)
    ]
    internal_failures = [row for row in internal_trace if row.get("status") == "fail"]
    target_boundary = str(trace_record.get("boundary_id") or "")
    target_module = str(trace_record.get("module") or "")
    target_stage = str(trace_record.get("stage_id") or "")
    target_records = [
        row
        for row in internal_trace
        if (not target_stage or str(row.get("stage_id") or "") == target_stage)
        and (not target_boundary or str(row.get("boundary_id") or "") == target_boundary)
        and (not target_module or str(row.get("module") or "") == target_module)
    ]
    first_failure_index = next(
        (index for index, row in enumerate(target_records) if row.get("status") == "fail"),
        len(target_records) - 1,
    )
    trace_window = (
        target_records[max(0, first_failure_index - 2) : first_failure_index + 1]
        if target_records
        else []
    )

    module_results = []
    for row in report.get("module_results", []):
        if not isinstance(row, dict):
            continue
        module_results.append(
            {
                key: row.get(key)
                for key in (
                    "schema_version",
                    "stage_id",
                    "status",
                    "summary",
                    "simulator",
                    "tool_scope",
                    "tool_profile",
                    "input_fingerprint_sha256",
                    "rtl_output_sha256",
                    "remote_workdir",
                    "local_workdir",
                    "output_capture",
                    "vcs_log",
                    "sim_log",
                    "sim_stderr_log",
                    "compile",
                    "run",
                    "canonical_reuse",
                    "blockers",
                )
                if row.get(key) is not None
            }
        )

    debug_closure = report.get("debug_closure", {}) if isinstance(report.get("debug_closure"), dict) else {}
    debug_failures = [
        row
        for row in debug_closure.get("failure_slice", [])
        if isinstance(row, dict) and row.get("status") == "fail"
    ]
    return {
        "schema_version": "spatialaccagent.localized_semantic_report_decision_projection.v1",
        "report_identity": {
            key: report.get(key)
            for key in (
                "schema_version",
                "gate",
                "mode",
                "stage_id",
                "stage",
                "status",
                "summary",
                "path",
                "execution_source",
                "canonical_run_id",
                "canonical_reuse_errors",
                "semantic_contract_path",
                "first_failed_module",
                "first_failed_summary",
                "blockers",
            )
            if report.get(key) is not None
        },
        "module_execution": module_results,
        "real_weight_execution": report.get("real_weight_execution", {}),
        "semantic_comparison": report.get("semantic_comparison", {}),
        "target_failure_diagnostics": report.get("target_failure_diagnostics", {}),
        "selected_cctg_trace_record": trace_record,
        "corroborating_semantic_numeric_failure": corroborating_numeric_failure,
        "selected_internal_trace_window": trace_window,
        "representative_internal_failures": representative_failure_records(internal_failures),
        "representative_debug_failures": representative_failure_records(debug_failures),
        "raw_evidence_counts": {
            "internal_trace_records": len(internal_trace),
            "internal_failure_records": len(internal_failures),
            "debug_failure_records": len(debug_failures),
        },
        "projection_policy": {
            "decision_fields_preserved": True,
            "first_failure_preceding_trace_records": 2,
            "equivalent_failures_deduplicated": True,
            "raw_report_remains_immutable_audit_evidence": True,
        },
    }


def compact_localized_semantic_report_documents(
    documents: list[dict[str, Any]],
    trace_record: dict[str, Any],
    corroborating_numeric_failure: dict[str, Any] | None,
) -> list[dict[str, Any]]:
    stage_id = str(trace_record.get("stage_id") or "")
    expected_suffix = f"verification/operator_leaf_golden/{stage_id}.json"
    compacted: list[dict[str, Any]] = []
    for document in documents:
        if not isinstance(document, dict):
            continue
        path = str(document.get("path") or "")
        content = str(document.get("content") or "")
        if not path.endswith(expected_suffix) or len(content.encode("utf-8")) <= MAX_INLINE_LOCALIZED_SEMANTIC_REPORT_BYTES:
            compacted.append(document)
            continue
        try:
            report = json.loads(content)
        except json.JSONDecodeError:
            compacted.append(document)
            continue
        projection = localized_semantic_report_decision_projection(
            report,
            trace_record,
            corroborating_numeric_failure,
        )
        projection["raw_report"] = {
            "path": path,
            "sha256": document.get("sha256") or hashlib.sha256(content.encode("utf-8")).hexdigest(),
            "bytes": len(content.encode("utf-8")),
            "truncated": bool(document.get("truncated", False)),
        }
        projection_content = json.dumps(projection, indent=2, sort_keys=True)
        compacted.append(
            {
                "path": f"{path}#localized_semantic_decision_projection",
                "source_path": path,
                "source_sha256": projection["raw_report"]["sha256"],
                "content_sha256": hashlib.sha256(projection_content.encode("utf-8")).hexdigest(),
                "bytes": len(projection_content.encode("utf-8")),
                "content": projection_content,
                "truncated": False,
                "projection": True,
            }
        )
    return compacted


def localized_semantic_memory_initialization_projection(
    run_dir: Path,
    documents: list[dict[str, Any]],
    stage_id: str,
) -> dict[str, Any] | None:
    stage_token = f"/generated/semantic_harness/{stage_id}/"
    sources: list[Path] = []
    for document in documents:
        if not isinstance(document, dict):
            continue
        path = str(document.get("path") or "").split("#", 1)[0]
        normalized = "/" + path.lstrip("/")
        source = repo_path(path)
        if stage_token in normalized and source.suffix == ".sv" and source.is_file():
            sources.append(source.resolve())
    sources = list(dict.fromkeys(sources))
    if not sources:
        return None

    defines, dependencies, errors = semantic_memory_init_payload(run_dir, sources)
    source_evidence: list[dict[str, Any]] = []
    for source in sources:
        guarded, references = source_memory_init_contract(source)
        if not guarded and not references:
            continue
        text = source.read_text(encoding="utf-8", errors="ignore")
        relevant_lines = [
            {"line": index, "text": line.strip()}
            for index, line in enumerate(text.splitlines(), start=1)
            if MEMORY_INIT_DEFINE in line or "$readmemh" in line or "$readmemb" in line
        ]
        source_evidence.append(
            {
                "path": display_path(source),
                "sha256": sha256_file(source),
                "guarded_by_required_compile_define": guarded,
                "declared_readmem_paths": sorted(references),
                "relevant_lines": relevant_lines,
            }
        )
    if not source_evidence and not dependencies and not errors:
        return None
    return {
        "schema_version": "spatialaccagent.localized_semantic_memory_initialization_projection.v1",
        "stage_id": stage_id,
        "classification": "simulator_compile_and_resource_staging_contract",
        "compile_defines": defines,
        "vcs_compile_args": semantic_vcs_compile_define_args(defines),
        "dependencies": dependencies,
        "emitted_source_evidence": source_evidence,
        "errors": errors,
        "decision_rule": (
            "When the hash-verified readmem dependency exists but its emitted initialization is guarded by a "
            "compile define, first repair the simulator compile/staging contract. Do not replace the DUT memory "
            "architecture solely because the uninitialized simulation produced X values."
        ),
    }


def authorize_localized_semantic_repair_bundle(
    bundle: dict[str, Any],
    run_dir: Path,
    trace_record: dict[str, Any],
    *,
    instrumentation_only: bool = False,
    template_instrumentation_only: bool = False,
    corroborating_numeric_failure: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Open only the exact template dependency closure backed by a real semantic failure."""

    result = dict(bundle)
    documents = list(bundle.get("documents", []))
    editable = dict(bundle.get("editable_contract", {}))
    errors: list[str] = []
    if not semantic_template_repair_approved():
        errors.append("semantic template repair is not explicitly approved")
    common_trace_fields = (
        trace_record.get("status") == "fail"
        and trace_record.get("failure_class")
        and trace_record.get("stage_id")
        and trace_record.get("module")
    )
    evidence_type = trace_record.get("evidence_type")
    internal_observed = (
        trace_record.get("observed_value", {})
        if isinstance(trace_record.get("observed_value"), dict)
        else {}
    )
    internal_trace_valid = (
        evidence_type == "semantic_internal_boundary_trace"
        and trace_record.get("failure_class") == "unknown_logic_value"
        and internal_observed.get("valid") == 1
        and re.search(r"[xz]", str(internal_observed.get("packed_literal") or ""), re.IGNORECASE)
        is not None
    )
    numeric_trace_valid = evidence_type == "semantic_numeric_compare"
    pipeline_observed = (
        trace_record.get("observed_value", {})
        if isinstance(trace_record.get("observed_value"), dict)
        else {}
    )
    barrier_pipeline_trace_valid = bool(
        evidence_type == "single_layer_pipeline_contract"
        and trace_record.get("failure_class")
        == "intra_layer_spatial_pipeline_violation"
        and pipeline_observed.get("whole_sequence_barrier_observed") is True
        and isinstance(trace_record.get("expected_value"), dict)
        and trace_record["expected_value"].get(
            "token_0_first_output_before_final_token_last_input"
        )
        is True
        and re.fullmatch(
            r"[0-9a-f]{64}",
            str(trace_record.get("input_fingerprint_sha256") or ""),
        )
        and re.fullmatch(
            r"[0-9a-f]{64}",
            str(trace_record.get("pipeline_trace_sha256") or ""),
        )
        and str(trace_record.get("template_source") or "").endswith(".scala")
    )
    candidate_template_sources = [
        str(value)
        for value in trace_record.get("candidate_template_sources", [])
        if str(value)
    ]
    candidate_stage_ids = [
        str(value)
        for value in trace_record.get("candidate_stage_ids", [])
        if str(value)
    ]
    source_bound_pipeline_failure_mode = str(
        trace_record.get("failure_mode") or ""
    )
    pipeline_expected = (
        trace_record.get("expected_value")
        if isinstance(trace_record.get("expected_value"), dict)
        else {}
    )
    legacy_pipeline_expectation = bool(
        pipeline_expected.get("every_stage_keeps_pipeline_filled") is True
        and pipeline_expected.get(
            "every_dependency_has_different_token_overlap"
        )
        is True
    )
    rate_insensitive_pipeline_expectation = bool(
        pipeline_expected.get("pipeline_semantics")
        == "elastic_rate_insensitive_token_pipeline"
        and pipeline_expected.get(
            "token_order_is_preserved_at_every_required_boundary"
        )
        is True
        and pipeline_expected.get(
            "every_required_dependency_has_different_token_overlap"
        )
        is True
        and pipeline_expected.get("stage_turnover_gaps_are_diagnostic") is True
        and pipeline_expected.get(
            "all_planned_stages_same_cycle_concurrency_required"
        )
        is False
    )
    source_bound_pipeline_trace_valid = bool(
        evidence_type == "single_layer_pipeline_contract"
        and trace_record.get("failure_class")
        == "intra_layer_spatial_pipeline_violation"
        and source_bound_pipeline_failure_mode
        in {
            "completed_pipeline_overlap_violation",
            "irreversible_stage_turnover_violation",
        }
        and pipeline_observed.get(source_bound_pipeline_failure_mode) is True
        and (legacy_pipeline_expectation or rate_insensitive_pipeline_expectation)
        and not (
            rate_insensitive_pipeline_expectation
            and bool(pipeline_observed.get("failed_stage_turnover_evidence"))
        )
        and candidate_stage_ids
        and len(candidate_stage_ids) == len(set(candidate_stage_ids))
        and candidate_template_sources
        and len(candidate_template_sources) == len(set(candidate_template_sources))
        and all(
            Path(value).name == value and Path(value).suffix == ".scala"
            for value in candidate_template_sources
        )
        and re.fullmatch(
            r"[0-9a-f]{64}",
            str(trace_record.get("input_fingerprint_sha256") or ""),
        )
        and re.fullmatch(
            r"[0-9a-f]{64}",
            str(trace_record.get("pipeline_trace_sha256") or ""),
        )
        and (
            bool(pipeline_observed.get("failed_stage_turnover_evidence"))
            or bool(pipeline_observed.get("failed_dependency_overlap_evidence"))
            or bool(pipeline_observed.get("failed_boundary_order_evidence"))
            or bool(pipeline_observed.get("whole_sequence_barrier_evidence"))
        )
    )
    pipeline_trace_valid = (
        barrier_pipeline_trace_valid or source_bound_pipeline_trace_valid
    )
    if not common_trace_fields or not (
        numeric_trace_valid or internal_trace_valid or pipeline_trace_valid
    ):
        errors.append(
            "localized repair lacks a complete source-bound real-tool semantic failure record"
        )
    if internal_trace_valid and not pipeline_trace_valid and not (
        isinstance(corroborating_numeric_failure, dict)
        and corroborating_numeric_failure.get("status") == "fail"
        and corroborating_numeric_failure.get("evidence_type") == "semantic_numeric_compare"
        and corroborating_numeric_failure.get("failure_class")
        and corroborating_numeric_failure.get("stage_id") == trace_record.get("stage_id")
    ):
        errors.append("internal boundary failure lacks a same-stage target-model numeric failure")

    generated_template_paths = list(
        dict.fromkeys(
            repo_path(value)
            for value in editable.get("read_only_template_sources", [])
            if str(value).endswith(".scala")
        )
    )
    if source_bound_pipeline_trace_valid:
        candidate_source_set = set(candidate_template_sources)
        generated_template_paths = [
            path for path in generated_template_paths if path.name in candidate_source_set
        ]
        if (
            len(candidate_template_sources) != len(candidate_source_set)
            or {path.name for path in generated_template_paths} != candidate_source_set
        ):
            errors.append(
                "source-bound pipeline failure candidate templates do not exactly match the current generated source bundle"
            )
    else:
        candidate_source_set = set()
    framework_template_root = Path.cwd() / "accagent" / "framework" / "templates" / "operator_chisel"
    template_pairs: list[dict[str, Any]] = []
    approved_template_paths: list[Path] = []
    for generated_path in generated_template_paths:
        persistent_path = framework_template_root / generated_path.name
        if not generated_path.is_file() or not persistent_path.is_file():
            errors.append(f"missing persistent/generated template pair for {generated_path.name}")
            continue
        generated_hash = sha256_file(generated_path)
        persistent_hash = sha256_file(persistent_path)
        if generated_hash != persistent_hash:
            errors.append(f"persistent/generated template baseline differs for {generated_path.name}")
            continue
        declares_root_candidate = re.search(
            rf"(?m)^\s*class\s+{re.escape(str(trace_record.get('module') or ''))}\b",
            generated_path.read_text(encoding="utf-8"),
        ) is not None
        approved_template_paths.extend([persistent_path.resolve(), generated_path.resolve()])
        template_pairs.append(
            {
                "name": generated_path.name,
                "persistent_path": display_path(persistent_path),
                "persistent_sha256": persistent_hash,
                "generated_path": display_path(generated_path),
                "generated_sha256": generated_hash,
                "body_document_path": display_path(generated_path),
                "declares_root_candidate": declares_root_candidate,
                "source_bound_pipeline_candidate": (
                    source_bound_pipeline_trace_valid
                    and generated_path.name in candidate_source_set
                ),
                "required_edit_policy": "replace both paths with byte-identical complete contents when this template is edited",
            }
        )
    if not template_pairs:
        errors.append("failed stage has no compile-validated Scala template dependency closure")
    template_instrumentation_pairs = [
        row for row in template_pairs if row.get("declares_root_candidate") is True
    ]
    source_bound_pipeline_candidate_pairs = [
        row
        for row in template_pairs
        if row.get("source_bound_pipeline_candidate") is True
    ]
    if instrumentation_only:
        approved_template_paths = []
    elif source_bound_pipeline_trace_valid:
        if {
            str(row.get("name")) for row in source_bound_pipeline_candidate_pairs
        } != candidate_source_set:
            errors.append(
                "source-bound pipeline failure does not resolve every candidate template to one hash-identical persistent/generated pair"
            )
            approved_template_paths = []
        else:
            approved_template_paths = [
                repo_path(path).resolve()
                for row in source_bound_pipeline_candidate_pairs
                for path in (row["persistent_path"], row["generated_path"])
            ]
    else:
        if len(template_instrumentation_pairs) != 1:
            errors.append(
                "localized semantic repair requires exactly one template declaring the root candidate; "
                f"found {[row.get('name') for row in template_instrumentation_pairs]}"
            )
            approved_template_paths = []
        else:
            pair = template_instrumentation_pairs[0]
            approved_template_paths = [
                repo_path(pair["persistent_path"]).resolve(),
                repo_path(pair["generated_path"]).resolve(),
            ]

    pair_projection = {
        "schema_version": "spatialaccagent.localized_semantic_template_pairs.v2",
        "stage_id": trace_record.get("stage_id"),
        "root_candidate_module": trace_record.get("module"),
        "failure_mode": trace_record.get("failure_mode"),
        "candidate_stage_ids": candidate_stage_ids,
        "candidate_stages": trace_record.get("candidate_stages", []),
        "candidate_template_sources": candidate_template_sources,
        "real_tool_failure": {
            key: trace_record.get(key)
            for key in (
                "evidence_type",
                "failure_class",
                "failure_mode",
                "summary",
                "violated_contract",
                "beat_index",
                "lane_index",
                "logical_index",
                "observed_value",
                "expected_value",
                "rtl_output_sha256",
                "input_fingerprint_sha256",
                "expected_output_sha256",
                "testbench_sha256",
                "pipeline_trace_sha256",
                "template_source",
                "candidate_stage_ids",
                "candidate_stages",
                "candidate_template_sources",
                "template_pairs",
            )
        },
        "corroborating_semantic_numeric_failure": corroborating_numeric_failure,
        "template_pairs": template_pairs,
        "template_instrumentation_pairs": template_instrumentation_pairs,
        "source_bound_pipeline_candidate_pairs": source_bound_pipeline_candidate_pairs,
        "authorization_errors": errors,
        "policy": {
            "smallest_justified_edit_set_required": True,
            "candidate_authorization_is_not_a_root_cause_verdict": True,
            "persistent_generated_pair_replacement_required": True,
            "harness_instrumentation_may_precede_template_edit_when_internal_root_is_ambiguous": True,
            "same_stage_real_golden_vcs_must_pass_after_repair": True,
            "checkpoint_input_golden_numeric_policy_and_checker_are_immutable": True,
        },
    }
    projection_content = json.dumps(pair_projection, indent=2, sort_keys=True)
    documents.append(
        {
            "path": f"localized_semantic_repair/{trace_record.get('stage_id')}#template_pair_contract",
            "source_path": display_path(Path(__file__)),
            "source_sha256": sha256_file(Path(__file__)),
            "content_sha256": hashlib.sha256(projection_content.encode("utf-8")).hexdigest(),
            "bytes": len(projection_content.encode("utf-8")),
            "content": projection_content,
            "truncated": False,
            "projection": True,
        }
    )
    memory_initialization = localized_semantic_memory_initialization_projection(
        run_dir,
        documents,
        str(trace_record.get("stage_id") or ""),
    )
    if memory_initialization is not None:
        memory_content = json.dumps(memory_initialization, indent=2, sort_keys=True)
        documents.append(
            {
                "path": (
                    f"localized_semantic_repair/{trace_record.get('stage_id')}"
                    "#semantic_memory_initialization_contract"
                ),
                "source_path": display_path(Path(__file__)),
                "source_sha256": sha256_file(Path(__file__)),
                "content_sha256": hashlib.sha256(memory_content.encode("utf-8")).hexdigest(),
                "bytes": len(memory_content.encode("utf-8")),
                "content": memory_content,
                "truncated": False,
                "projection": True,
            }
        )
    documents = compact_localized_semantic_report_documents(
        documents,
        trace_record,
        corroborating_numeric_failure,
    )

    if instrumentation_only:
        direct_emitted_paths = {
            str(row.get("path") or "")
            for row in bundle.get("focused_real_tool_failure_context", {}).get(
                "emitted_causal_source_inventory", []
            )
            if isinstance(row, dict) and row.get("role") == "direct_emitted_dependency"
        }

        def instrumentation_document(document: dict[str, Any]) -> bool:
            path = str(document.get("path") or "")
            base_path = path.split("#", 1)[0]
            name = Path(base_path).name
            normalized = "/" + path.lstrip("/")
            if base_path in direct_emitted_paths:
                return False
            if "/semantic_harness/" in normalized and name.endswith((".scala", ".sv")):
                return True
            if "/spatialaccagent/templates/" in normalized and name.endswith(".scala"):
                return True
            if name in {"build.sbt", "build.properties", "semantic_tb.sv", "vcs.log", "sim.log"}:
                return True
            if name in {
                "testbench_contract.json",
                "boundary_contracts.json",
                "trace_manifest.json",
                "failure_localization.json",
            }:
                return True
            if any(
                token in path
                for token in (
                    "#operator_leaf_execution_projection",
                    "#failed_stage_requirements_projection",
                    "#failed_stage_binding_projection",
                    "#focused_real_tool_failure_context",
                    "#localized_semantic_decision_projection",
                    "#semantic_memory_initialization_contract",
                    "#emitted_causal_source_inventory",
                    "#failed_harness_template_dependency_projection",
                    "#template_pair_contract",
                    "#exact_capability_consumer_functions",
                    "#current_operator_leaf_failure_projection",
                    "#current_repair_action_projection",
                )
            ):
                return True
            return path.endswith(f"verification/operator_leaf_golden/{trace_record.get('stage_id')}.json")

        documents = [
            document
            for document in documents
            if isinstance(document, dict) and instrumentation_document(document)
        ]

    if template_instrumentation_only:
        def template_instrumentation_document(document: dict[str, Any]) -> bool:
            path = str(document.get("path") or "")
            normalized = "/" + path.lstrip("/")
            name = Path(path.split("#", 1)[0]).name
            if "/spatialaccagent/templates/" in normalized and name.endswith(".scala"):
                return True
            if path.endswith(f"verification/operator_leaf_golden/{trace_record.get('stage_id')}.json"):
                return True
            if name in {
                "model_config.json",
                "numeric_policy.json",
                "testbench_contract.json",
                "vcs.log",
                "sim.log",
                "boundary_contracts.json",
                "trace_manifest.json",
                "failure_localization.json",
            }:
                return True
            return any(
                token in path
                for token in (
                    "#failed_stage_requirements_projection",
                    "#failed_harness_template_dependency_projection",
                    "#current_repair_action_projection",
                    "#focused_real_tool_failure_context",
                    "#localized_semantic_decision_projection",
                    "#semantic_memory_initialization_contract",
                    "#template_pair_contract",
                )
            )

        documents = [
            document
            for document in documents
            if isinstance(document, dict) and template_instrumentation_document(document)
        ]

    if not instrumentation_only and not template_instrumentation_only:
        stage_token = f"/generated/semantic_harness/{trace_record.get('stage_id')}/"
        root_sv_name = f"{trace_record.get('module')}.sv"

        def localized_functional_document(document: dict[str, Any]) -> bool:
            path = str(document.get("path") or "")
            normalized = "/" + path.lstrip("/")
            name = Path(path.split("#", 1)[0]).name
            if "/spatialaccagent/templates/" in normalized and name.endswith(".scala"):
                return (
                    name in candidate_source_set or name == "Common.scala"
                    if source_bound_pipeline_trace_valid
                    else True
                )
            if pipeline_trace_valid and name in {
                "single_layer_functional_report.json",
                "semantic_testbench_manifest.json",
                "pipeline_plan.json",
            }:
                return True
            if (
                pipeline_trace_valid
                and name.startswith(str(trace_record.get("module") or ""))
                and name.endswith(".sv")
            ):
                return True
            if stage_token in normalized and name.endswith(".sv"):
                return name == root_sv_name or "Harness" in name
            if path.endswith(f"verification/operator_leaf_golden/{trace_record.get('stage_id')}.json"):
                return True
            if "/site-packages/transformers/" in normalized:
                return True
            if "/spatialaccagent/numeric/" in normalized:
                return True
            if name in {
                "build.sbt",
                "build.properties",
                "model_config.json",
                "numeric_policy.json",
                "testbench_contract.json",
                "vcs.log",
                "sim.log",
                "sim.stderr.log",
                "boundary_contracts.json",
                "trace_manifest.json",
                "failure_localization.json",
                "fpga_ip_simulation_closure.json",
            }:
                return True
            return any(
                token in path
                for token in (
                    "#operator_leaf_execution_projection",
                    "#failed_stage_requirements_projection",
                    "#failed_stage_binding_projection",
                    "#focused_real_tool_failure_context",
                    "#localized_semantic_decision_projection",
                    "#semantic_memory_initialization_contract",
                    "#emitted_causal_source_inventory",
                    "#failed_harness_template_dependency_projection",
                    "#template_pair_contract",
                    "#exact_capability_consumer_functions",
                    "#current_operator_leaf_failure_projection",
                    "#current_repair_action_projection",
                    "#reference_operator_semantics",
                )
            )

        documents = [
            document
            for document in documents
            if isinstance(document, dict) and localized_functional_document(document)
        ]

    harness_scala_root = (
        run_dir
        / "generated"
        / "chisel"
        / "src"
        / "main"
        / "scala"
        / "spatialaccagent"
        / "semantic_harness"
    )
    localized_allowed_paths = [*approved_template_paths]
    if instrumentation_only:
        localized_allowed_paths.extend(
            path.resolve() for path in sorted(harness_scala_root.glob("**/*")) if path.is_file()
        )
    binding_path = (run_dir / "generated" / "memory" / "dut_weight_binding_manifest.json").resolve()
    if binding_path.is_file() and instrumentation_only:
        localized_allowed_paths.append(binding_path)

    authorized = not errors
    template_repair_authorized = authorized and not instrumentation_only and not template_instrumentation_only
    template_instrumentation_authorized = authorized and template_instrumentation_only
    approved_template_edit_paths = (
        approved_template_paths
        if template_repair_authorized or template_instrumentation_authorized
        else []
    )
    read_only_template_sources = [
        path
        for path in editable.get("read_only_template_sources", [])
        if repo_path(path).resolve() not in set(approved_template_edit_paths)
    ]
    editable.update(
        {
            "bounded_template_repair_approved": template_repair_authorized,
            "semantic_template_repair_approved": template_repair_authorized,
            "localized_template_instrumentation_approved": template_instrumentation_authorized,
            "approved_bounded_template_repair_exact_files": (
                sorted(display_path(path) for path in approved_template_edit_paths)
                if template_repair_authorized or template_instrumentation_authorized
                else []
            ),
            "read_only_template_sources": (
                read_only_template_sources
            ),
            "templates_read_only_after_compiled_semantic_baseline": not (
                template_repair_authorized or template_instrumentation_authorized
            ),
            "template_repair_deferred_until_real_localized_failure": not template_repair_authorized,
            "localized_semantic_repair_authorized": authorized,
            "localized_instrumentation_only": instrumentation_only,
            "localized_template_instrumentation_only": template_instrumentation_only,
            "localized_allowed_exact_files": (
                sorted(display_path(path) for path in set(localized_allowed_paths))
                if authorized
                else []
            ),
            "localized_template_pair_names": sorted(
                row["name"] for row in template_instrumentation_pairs
            )
            if not source_bound_pipeline_trace_valid
            else [],
            "localized_candidate_template_pair_names": sorted(
                row["name"]
                for row in (
                    source_bound_pipeline_candidate_pairs
                    if source_bound_pipeline_trace_valid
                    else template_instrumentation_pairs
                )
            ),
            "localized_template_instrumentation_pair_names": sorted(
                row["name"] for row in template_instrumentation_pairs
            ),
            "localized_authorization_errors": errors,
        }
    )
    result.update(
        {
            "bundle_profile": "localized_semantic_dut_repair",
            "documents": documents,
            "document_count": len(documents),
            "document_chars": sum(len(str(document.get("content") or "")) for document in documents),
            "localized_semantic_failure": pair_projection["real_tool_failure"],
            "editable_contract": editable,
        }
    )
    return result


def text_tail(value: Any, limit: int = 8000) -> str:
    text = str(value or "")
    return text[-limit:]


def repo_path(value: Any) -> Path:
    path = Path(str(value))
    return path if path.is_absolute() else Path.cwd() / path


def case_adapter_for_state(state: dict[str, Any], run_dir: Path) -> dict[str, Any]:
    tool_materials_dir = Path.cwd() / "accagent" / "framework" / "input_materials" / "tools"
    try:
        adapter = read_json(artifact_path(state, "artifact.input.case_adapter"))
        try:
            model = read_json(artifact_path(state, "artifact.input.model_config"))
        except Exception:
            model = {}
        return refresh_builtin_case_adapter(adapter, model, run_dir, tool_materials_dir)
    except Exception:
        try:
            model = read_json(artifact_path(state, "artifact.input.model_config"))
        except Exception:
            model = {}
        return build_case_adapter(model, run_dir, tool_materials_dir)


# Runtime observation is selected from the compiled signal catalog.  The
# removed deterministic source editors used Qwen-specific hierarchy paths and
# caused every observation change to rebuild the testbench and snapshot.

def execute_patch_step(step: dict[str, Any], out_dir: Path) -> dict[str, Any]:
    del out_dir
    action = step.get("action", {}) if isinstance(step.get("action"), dict) else {}
    return {
        "status": "fail",
        "summary": (
            "deterministic model-specific probe edits are retired; use the LLM causal-slice repair "
            "path for HDL changes or compiled runtime signal selection for observation"
        ),
        "pattern_id": str(action.get("pattern_id") or ""),
    }

def prepare_stage3_checkpoint_probe_environment(
    run_dir: Path,
    *,
    label: str,
) -> dict[str, Any]:
    """Prepare one current checkpoint request for every Layer-3 debug run.

    The checkpoint is execution acceleration only.  A request starts in
    ``cold_capture`` when no reusable checkpoint exists, then the resulting
    capture can be reused by later observation-only runs.  A missing, stale, or
    failed checkpoint is repaired or recaptured; it is never converted into a
    normal cold validation run.
    """

    env = {
        "SPATIALACC_MAX_HEAVY_JOBS": "1",
        "SPATIALACC_CHECKPOINT_REQUIRED": "1",
    }

    def fail_preparation(summary: str, request: dict[str, Any] | None = None) -> dict[str, Any]:
        return {
            "status": "fail",
            "summary": summary,
            "request": request or {},
            "request_path": None,
            "request_sha256": None,
            "checkpoint_enabled": False,
            "cold_fallback": False,
            "request_unavailable": True,
            "env": env,
            "remote_tool_must_not_start": True,
            "fast_replay": {
                "state_path": str(fast_replay_state_path(run_dir)),
                "lifecycle": {
                    "status": "repair_required",
                    "action": "repair_or_recapture",
                    "reasons": [summary],
                },
            },
        }

    fast_state_path = fast_replay_state_path(run_dir)
    fast_state = read_fast_replay_state(run_dir)
    board_manifest_path = (
        run_dir
        / "verification"
        / "board_simulation"
        / "board_simulation_manifest.json"
    )
    board_manifest = read_json(board_manifest_path) if board_manifest_path.is_file() else {}
    execution_identity = simulation_execution_identity(board_manifest)
    fast_lifecycle = stable_checkpoint_lifecycle(
        enabled=True,
        identity=execution_identity,
        checkpoint=fast_state,
    )
    fast_replay_metadata = {
        "state_path": str(fast_state_path),
        "state": fast_state,
        "lifecycle": fast_lifecycle,
        "cut": STABLE_CHECKPOINT_CUT,
    }
    lifecycle_status = str(fast_lifecycle.get("status") or "")

    stable_request_path = fast_replay_request_path(run_dir)
    stable_request = (
        read_json_if_exists(stable_request_path)
        if stable_request_path.is_file()
        else {}
    )
    if lifecycle_status in {"restore_check_required", "ready"}:
        request = stable_request
        request_path = stable_request_path
        if checkpoint_request_errors(request):
            return fail_preparation(
                "the reusable checkpoint request is incomplete; recapture is required",
                request,
            )
    else:
        try:
            request = prepare_checkpoint_request(run_dir)
            request_path = persist_checkpoint_request(run_dir, request, label=label)
        except (OSError, ValueError, TypeError, json.JSONDecodeError) as exc:
            return fail_preparation(f"checkpoint request preparation failed: {exc}")

    replay_decision = request.get("replay_decision", {})
    replay_decision = (
        replay_decision if isinstance(replay_decision, dict) else {}
    )
    replay_mode = str(replay_decision.get("mode") or "")
    if request.get("status") != "ready":
        return fail_preparation("current checkpoint request is not ready", request)

    if lifecycle_status in {
        "capture_required",
        "repair_required",
        "recapture_required",
    }:
        # Force a fresh capture request after a failed or invalidated attempt.
        # This is checkpoint repair/recapture, not permission to run cold.
        request = copy.deepcopy(request)
        decision = request.get("replay_decision", {})
        decision = decision if isinstance(decision, dict) else {}
        request["replay_decision"] = {
            **decision,
            "status": "cold_capture_required",
            "mode": "cold_capture",
            "checkpoint_id": None,
            "blockers": list(
                dict.fromkeys(
                    [
                        *[
                            str(value)
                            for value in fast_lifecycle.get("reasons", [])
                            if str(value)
                        ],
                        "current checkpoint must be captured or recaptured",
                    ]
                )
            ),
        }
        request["selected_checkpoint_manifest"] = ""
        request["selected_checkpoint_manifest_sha256"] = None
        request["request_sha256"] = canonical_contract_sha256(
            checkpoint_request_projection(request)
        )
        request_path = persist_checkpoint_request(
            run_dir,
            request,
            label=label,
        )
        replay_mode = "cold_capture"

    elif lifecycle_status not in {"restore_check_required", "ready"}:
        return fail_preparation(
            "checkpoint lifecycle is not actionable; repair or recapture is "
            "required before Layer-3 VCS",
            request,
        )

    env["SPATIALACC_CHECKPOINT_REPLAY"] = "1"
    env["SPATIALACC_CHECKPOINT_REQUEST"] = str(request_path)
    if lifecycle_status == "recapture_required":
        # This replays the real weight-loading prefix with the already
        # compiled simulator, then replaces only the invalid native snapshot.
        # It is execution acceleration, not an Agent-visible repair action.
        env["SPATIALACC_FAST_REPLAY_RECAPTURE"] = "1"
    if lifecycle_status in {"restore_check_required", "ready"}:
        env["SPATIALACC_FAST_REPLAY"] = "1"
        env["SPATIALACC_FAST_REPLAY_STATE"] = str(fast_state_path)
        if lifecycle_status == "restore_check_required":
            env["SPATIALACC_FAST_REPLAY_RESTORE_CHECK"] = "1"
    return {
        "status": "pass",
        "summary": f"prepared the current Layer-3 checkpoint request ({replay_mode})",
        "request": request,
        "request_path": str(request_path),
        "request_sha256": sha256_file(request_path),
        "checkpoint_enabled": True,
        "cold_fallback": False,
        "env": env,
        "remote_tool_must_not_start": False,
        "fast_replay": fast_replay_metadata,
    }


def exact_board_vcs_rerun_command_error(
    tool: str,
    argv: list[Any],
    run_dir: Path,
) -> str | None:
    """Reject a stale board-VCS wrapper before it can run outside this closure."""

    if tool != "case_vcs_functional_sim":
        return None
    canonical_runner = (
        Path(__file__).resolve().parents[2]
        / "scripts"
        / "verification"
        / "case_board_vcs_functional.py"
    ).resolve()
    resolved_args = {
        str(Path(str(value)).resolve())
        for value in argv
        if str(value) and not str(value).startswith("-")
    }
    if str(canonical_runner) not in resolved_args:
        return (
            "exact-board VCS rerun must invoke the canonical "
            "case_board_vcs_functional.py runner"
        )
    try:
        run_dir_index = [str(value) for value in argv].index("--run-dir") + 1
        bound_run_dir = Path(str(argv[run_dir_index])).resolve()
    except (ValueError, IndexError):
        return "exact-board VCS rerun must bind --run-dir to the current run"
    if bound_run_dir != run_dir.resolve():
        return "exact-board VCS rerun is bound to a different run directory"
    return None


def rebind_exact_board_vcs_rerun_step(
    step: dict[str, Any],
    state: dict[str, Any],
    run_dir: Path,
) -> dict[str, Any]:
    """Refresh a persisted exact-board VCS rerun from the current adapter.

    Durable repair plans may embed a historical tool protocol after a
    framework-owned adapter changes. Restrict this refresh to the canonical
    exact-board rerun; execution-time validation remains fail-closed.
    """

    if (
        str(step.get("scope") or "") not in {"regression_rerun", "debug_trace_rerun"}
        or str(step.get("tool") or "") != "case_vcs_functional_sim"
    ):
        return step
    case_adapter = case_adapter_for_state(state, run_dir)
    _, spec = adapter_tool_by_name_or_role(case_adapter, "case_vcs_functional_sim")
    if not isinstance(spec, dict):
        return step
    argv = [str(item) for item in spec.get("argv", [])]
    if not any(Path(item).name == "case_board_vcs_functional.py" for item in argv):
        return step
    rebound = copy.deepcopy(step)
    rebound["resolved_protocol_name"] = spec.get("name")
    rebound["execution"] = {
        "argv": argv,
        "cwd": str(Path.cwd()),
        "env": dict(spec.get("env") or {}),
        "source": "current_exact_board_case_adapter",
    }
    return rebound


def record_exact_board_rerun_agent_handoff(
    result: dict[str, Any],
    *,
    case_adapter: dict[str, Any],
    run_dir: Path,
) -> dict[str, Any]:
    """Promote an actionable canonical board rerun result to its Agent turn.

    A generic rerun exit code alone cannot distinguish a failed tool launch
    from a complete semantic-board diagnosis.  This adapter is deliberately
    limited to the current exact-board runner/analyzer pair and lets the
    existing hash-bound diagnosis decide whether the hardware Agent receives
    another turn.
    """

    if result.get("status") != "fail":
        return result
    vcs_role, vcs_spec, analyzer_role, analyzer_spec = (
        select_exact_board_validation_tools(case_adapter)
    )
    if not vcs_spec or not analyzer_spec:
        return result
    feedback = exact_board_vcs_feedback(
        case_adapter,
        run_dir,
        vcs_spec,
        analyzer_spec,
    )
    probe = {
        "status": "fail",
        "case_adapter_role": vcs_role,
        "analyzer_role": analyzer_role,
        "current_board_vcs_feedback": feedback,
    }
    if not exact_board_probe_requires_agent_continuation(probe):
        return result
    handoff_identity = exact_board_probe_agent_handoff_identity(probe)
    if handoff_identity is None:
        return result
    return {
        **result,
        "current_board_vcs_feedback": feedback,
        "new_current_real_tool_failure_requires_agent": True,
        "new_current_real_tool_failure_identity_sha256": handoff_identity,
    }


def run_rerun_step(
    step: dict[str, Any],
    out_dir: Path,
    include_remote: bool,
    timeout_sec: int,
    *,
    case_adapter: dict[str, Any] | None = None,
) -> dict[str, Any]:
    execution = step.get("execution", {}) if isinstance(step.get("execution"), dict) else {}
    argv = execution.get("argv") if isinstance(execution.get("argv"), list) else []
    scope = str(step.get("scope") or "")
    tool = str(step.get("tool") or "")
    command_scope = "remote" if "vcs" in tool or "remote" in str(step.get("resolved_protocol_name") or "") else "local"
    if scope not in {"regression_rerun", "debug_trace_rerun"}:
        return {"status": "skip", "summary": f"not a rerun step: {scope}"}
    if command_scope == "remote" and not include_remote:
        return {"status": "not_run", "summary": "remote rerun skipped; pass --include-remote to execute"}
    if not argv:
        return {"status": "fail", "summary": "missing execution argv"}
    exact_board_command_error = exact_board_vcs_rerun_command_error(
        tool,
        argv,
        out_dir.parent,
    )
    if exact_board_command_error is not None:
        result = {
            "status": "fail",
            "returncode": None,
            "summary": exact_board_command_error,
            "rejected_stale_execution_plan": True,
        }
        log_path = out_dir / f"{step.get('id', 'rerun').replace('.', '_')}.json"
        write_json(log_path, result | {"step": step})
        result["log_path"] = str(log_path)
        return result
    env = os.environ.copy()
    env.update({str(k): str(v) for k, v in dict(execution.get("env") or {}).items() if v is not None and v != ""})
    checkpoint_preparation: dict[str, Any] | None = None
    exact_board_vcs_rerun = any(
        "case_board_vcs_functional.py" in str(item) for item in argv
    )
    if exact_board_vcs_rerun:
        if (
            env.get("SPATIALACC_CHECKPOINT_FINAL_COLD") != "1"
            and not env.get("SPATIALACC_CHECKPOINT_REQUEST")
        ):
            checkpoint_preparation = prepare_stage3_checkpoint_probe_environment(
                out_dir.parent,
                label=f"{safe_step_id(step)}_rerun",
            )
            if checkpoint_preparation.get("status") != "pass":
                result = {
                    "status": "fail",
                    "returncode": None,
                    "summary": (
                        "Layer-3 checkpoint preparation failed; ordinary cold "
                        "validation is forbidden"
                    ),
                    "checkpoint_request_preparation": {
                        key: checkpoint_preparation.get(key)
                        for key in (
                            "status",
                            "summary",
                            "request_path",
                            "request_sha256",
                            "remote_tool_must_not_start",
                        )
                    },
                    "remote_tool_was_not_started": True,
                }
                log_path = out_dir / f"{step.get('id', 'rerun').replace('.', '_')}.json"
                write_json(log_path, result | {"step": step})
                result["log_path"] = str(log_path)
                return result
            env.update(checkpoint_preparation["env"])
    cwd = Path(str(execution.get("cwd") or Path.cwd()))
    started = time.monotonic()
    started_ns = time.time_ns()
    try:
        proc = subprocess.run(
            [str(item) for item in argv],
            cwd=cwd,
            env=env,
            text=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            timeout=None if timeout_sec <= 0 else timeout_sec,
            check=False,
        )
        fatal_pattern = fatal_tool_output(proc.stdout, proc.stderr)
        status = "pass" if proc.returncode == 0 and fatal_pattern is None else "fail"
        result = {
            "status": status,
            "returncode": proc.returncode,
            "summary": (
                f"returncode={proc.returncode} fatal_output={fatal_pattern}"
                if fatal_pattern
                else f"returncode={proc.returncode}"
            ),
            "fatal_output_pattern": fatal_pattern,
            "stdout_tail": proc.stdout[-8000:],
            "stderr_tail": proc.stderr[-8000:],
            "duration_sec": time.monotonic() - started,
        }
    except subprocess.TimeoutExpired as exc:
        result = {
            "status": "fail",
            "returncode": 124,
            "summary": f"timeout after {timeout_sec}s",
            "stdout_tail": (exc.stdout or "")[-8000:] if isinstance(exc.stdout, str) else "",
            "stderr_tail": (exc.stderr or "")[-8000:] if isinstance(exc.stderr, str) else "",
            "duration_sec": time.monotonic() - started,
        }
    if checkpoint_preparation is not None:
        result["checkpoint_request_preparation"] = {
            key: checkpoint_preparation.get(key)
            for key in (
                "status",
                "summary",
                "request_path",
                "request_sha256",
                "remote_tool_must_not_start",
            )
        }
    if exact_board_vcs_rerun and isinstance(case_adapter, dict):
        result = record_exact_board_rerun_agent_handoff(
            result,
            case_adapter=case_adapter,
            run_dir=out_dir.parent,
        )
        runner_path = (
            out_dir.parent
            / "verification"
            / "vcs"
            / "case_board_vcs_functional.json"
        )
        if runner_path.is_file() and runner_path.stat().st_mtime_ns >= started_ns:
            result["fast_replay_state"] = update_fast_replay_state(
                out_dir.parent,
                read_json_if_exists(runner_path),
            )
    log_path = out_dir / f"{step.get('id', 'rerun').replace('.', '_')}.json"
    write_json(log_path, result | {"step": step})
    result["log_path"] = str(log_path)
    return result


def run_local_tool(argv: list[str], cwd: Path, env: dict[str, str], timeout_sec: int) -> dict[str, Any]:
    started = time.monotonic()
    try:
        proc = subprocess.run(
            [str(item) for item in argv],
            cwd=cwd,
            env=env,
            text=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            timeout=None if timeout_sec <= 0 else timeout_sec,
            check=False,
        )
        fatal_pattern = fatal_tool_output(proc.stdout, proc.stderr)
        return {
            "status": "pass" if proc.returncode == 0 and fatal_pattern is None else "fail",
            "returncode": proc.returncode,
            "summary": (
                f"returncode={proc.returncode} fatal_output={fatal_pattern}"
                if fatal_pattern
                else f"returncode={proc.returncode}"
            ),
            "fatal_output_pattern": fatal_pattern,
            "stdout_tail": text_tail(proc.stdout),
            "stderr_tail": text_tail(proc.stderr),
            "duration_sec": time.monotonic() - started,
        }
    except subprocess.TimeoutExpired as exc:
        return {
            "status": "fail",
            "returncode": 124,
            "summary": f"timeout after {timeout_sec}s",
            "stdout_tail": text_tail(exc.stdout if isinstance(exc.stdout, str) else ""),
            "stderr_tail": text_tail(exc.stderr if isinstance(exc.stderr, str) else ""),
            "duration_sec": time.monotonic() - started,
        }


def trace_record_from_step(step: dict[str, Any]) -> dict[str, Any]:
    contexts: list[dict[str, Any]] = []
    if isinstance(step.get("repair_context"), dict):
        contexts.append(step["repair_context"])
    action = step.get("action", {}) if isinstance(step.get("action"), dict) else {}
    if isinstance(action.get("minimal_repair_context"), dict):
        contexts.append(action["minimal_repair_context"])
    contexts.append(action)
    for context in contexts:
        record = context.get("trace_record", {})
        if isinstance(record, dict) and record:
            return record
    return {}


def repair_step_checkpoint(step: dict[str, Any]) -> dict[str, Any]:
    action = step.get("action", {}) if isinstance(step.get("action"), dict) else {}
    record = trace_record_from_step(step)
    payload = {
        "step_id": step.get("id"),
        "scope": step.get("scope"),
        "repair_kind": action.get("repair_kind"),
        "repair_phase": action.get("repair_phase"),
        "stage_id": record.get("stage_id"),
        "module": record.get("module") or action.get("root_candidate_module"),
        "boundary_id": record.get("boundary_id"),
        "cycle": record.get("cycle"),
        "beat_index": record.get("beat_index"),
        "violated_contract": record.get("violated_contract") or action.get("violated_contract"),
    }
    dynamic_source_bound_route = action.get("dynamic_source_bound_route") is True
    if dynamic_source_bound_route:
        payload.update(
            {
                "dynamic_source_bound_route": True,
                "source_repair_checkpoint_fingerprint_sha256": action.get(
                    "source_repair_checkpoint_fingerprint_sha256"
                ),
                "source_bound_failure_identity_sha256": action.get(
                    "source_bound_failure_identity_sha256"
                ),
                "source_bound_input_fingerprint_sha256": action.get(
                    "source_bound_input_fingerprint_sha256"
                ),
            }
        )
    encoded = json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return {
        "schema_version": (
            "spatialaccagent.repair_step_checkpoint.v2"
            if dynamic_source_bound_route
            else "spatialaccagent.repair_step_checkpoint.v1"
        ),
        **payload,
        "fingerprint_sha256": hashlib.sha256(encoded).hexdigest(),
    }


def localized_template_instrumentation_requested(
    prior_result: dict[str, Any],
    trace_record: dict[str, Any],
) -> bool:
    output = (
        prior_result.get("output", {})
        if isinstance(prior_result.get("output"), dict)
        else prior_result
    )
    if (
        output.get("status") != "blocked"
        or output.get("file_edits")
        or trace_record.get("status") != "fail"
        or trace_record.get("evidence_type") != "semantic_internal_boundary_trace"
        or not trace_record.get("module")
    ):
        return False
    text = " ".join(
        [
            str(output.get("summary") or ""),
            str(output.get("root_cause") or ""),
            *[
                str(value)
                for value in output.get("blocked_reasons", [])
                if value
            ],
        ]
    ).lower()
    module = str(trace_record.get("module") or "").lower()
    return (
        module in text
        and "internal" in text
        and any(token in text for token in ("instrument", "observation", "probe", "trace"))
        and any(token in text for token in ("not yet", "missing", "does not observe", "cannot distinguish"))
    )


def localized_template_instrumentation_already_collected(
    out_dir: Path,
    trace_record: dict[str, Any],
) -> bool:
    report = read_json_if_exists(out_dir / "repair_execution_report.json")
    stage_id = str(trace_record.get("stage_id") or "")
    boundary_id = str(trace_record.get("boundary_id") or "")
    module = str(trace_record.get("module") or "")
    for item in report.get("step_results", []):
        if not isinstance(item, dict):
            continue
        result = item.get("result", {}) if isinstance(item.get("result"), dict) else {}
        evidence = (
            result.get("instrumentation_evidence", {})
            if isinstance(result.get("instrumentation_evidence"), dict)
            else {}
        )
        leaf_report = Path(str(result.get("leaf_stage_report") or ""))
        evidence_stage = str(evidence.get("stage_id") or leaf_report.stem)
        if (
            result.get("instrumentation_evidence_collected") is not True
            or evidence.get("status") != "pass"
            or evidence_stage != stage_id
        ):
            continue
        boundaries = {str(value) for value in evidence.get("new_internal_boundaries", [])}
        modules = {str(value) for value in evidence.get("new_internal_modules", [])}
        if (boundary_id and boundary_id in boundaries) or (module and module in modules):
            return True
    if stage_id:
        stage_report = read_json_if_exists(
            out_dir.parent
            / "verification"
            / "operator_leaf_golden"
            / f"{stage_id.lower()}.json"
        )
        rows = (
            stage_report.get("internal_boundary_trace", [])
            if isinstance(stage_report.get("internal_boundary_trace"), list)
            else []
        )
        for row in rows:
            if not isinstance(row, dict):
                continue
            if (
                row.get("evidence_type") == "semantic_internal_boundary_trace"
                and str(row.get("stage_id") or "") == stage_id
                and (
                    (boundary_id and str(row.get("boundary_id") or "") == boundary_id)
                    or (module and str(row.get("module") or "") == module)
                )
            ):
                return True
    return False


SEMANTIC_HARNESS_ELABORATION_MAIN_BY_SCOPE = {
    "operator_leaf_closure": "ElaborateSemanticHarnesses",
    "single_layer_closure": "ElaborateSingleLayerClosure",
}


def semantic_harness_validation_output(
    output: dict[str, Any],
    run_dir: Path,
    *,
    require_elaboration: bool,
    required_elaboration_main: str | None = None,
) -> tuple[dict[str, Any], list[str]]:
    generated_root = (run_dir / "generated" / "chisel").resolve()
    normalized = dict(output)
    requests = [
        dict(request)
        for request in output.get("requested_validation", [])
        if isinstance(request, dict)
    ]
    goals = {
        str(value)
        for request in requests
        for value in request.get("argv", [])
        if isinstance(value, str)
    }
    if "Compile/compile" not in goals:
        requests.insert(
            0,
            {
                "purpose": "mandatory compile after localized semantic template repair",
                "argv": ["sbt", "--no-server", "Compile/compile"],
                "cwd": str(generated_root),
            },
        )
    errors: list[str] = []
    requested_elaboration_goals = {
        goal
        for goal in goals
        if goal.startswith("runMain spatialaccagent.semantic_harness.")
    }
    inspect_elaboration_main = bool(
        require_elaboration
        and (required_elaboration_main or not requested_elaboration_goals)
    )
    if inspect_elaboration_main:
        candidates: list[str] = []
        harness_root = (
            generated_root
            / "src"
            / "main"
            / "scala"
            / "spatialaccagent"
            / "semantic_harness"
        )
        for path in sorted(harness_root.glob("**/*.scala")):
            text = path.read_text(encoding="utf-8")
            if "emitSystemVerilog" not in text:
                continue
            candidates.extend(
                re.findall(
                    r"(?m)^\s*object\s+([A-Za-z_][A-Za-z0-9_$]*)\s+extends\s+App\b",
                    text,
                )
            )
        selected_main: str | None = None
        if required_elaboration_main is not None:
            if not re.fullmatch(
                r"[A-Za-z_][A-Za-z0-9_$]*", required_elaboration_main
            ):
                errors.append(
                    "localized semantic template repair has an invalid required elaboration main: "
                    f"{required_elaboration_main}"
                )
            elif candidates.count(required_elaboration_main) != 1:
                errors.append(
                    "localized semantic template repair requires exactly one existing "
                    f"{required_elaboration_main} semantic-harness elaboration main; "
                    f"found {sorted(candidates)}"
                )
            else:
                selected_main = required_elaboration_main
        else:
            unique_candidates = sorted(set(candidates))
            if len(candidates) == 1 and len(unique_candidates) == 1:
                selected_main = unique_candidates[0]
            else:
                errors.append(
                    "localized semantic template repair requires exactly one existing "
                    "semantic-harness elaboration main; "
                    f"found {sorted(candidates)}"
                )
        required_goal = (
            f"runMain spatialaccagent.semantic_harness.{selected_main}"
            if selected_main is not None
            else None
        )
        if required_goal is not None and required_goal not in requested_elaboration_goals:
            requests.append(
                {
                    "purpose": "mandatory full semantic-harness re-elaboration after localized template repair",
                    "argv": ["sbt", "--no-server", required_goal],
                    "cwd": str(generated_root),
                }
            )
    normalized["requested_validation"] = requests
    return normalized, errors


def localized_repair_step_projection(step: dict[str, Any]) -> dict[str, Any]:
    action = step.get("action", {}) if isinstance(step.get("action"), dict) else {}
    context = (
        action.get("minimal_repair_context", {})
        if isinstance(action.get("minimal_repair_context"), dict)
        else {}
    )
    trace = context.get("trace_record", {}) if isinstance(context.get("trace_record"), dict) else {}
    return {
        "id": step.get("id"),
        "scope": step.get("scope"),
        "status": step.get("status"),
        "debug_layer": step.get("debug_layer") or action.get("debug_layer"),
        "llm_disposition_constraint": step.get("llm_disposition_constraint"),
        "action": {
            key: action.get(key)
            for key in (
                "repair_kind",
                "repair_phase",
                "repair_gate",
                "root_candidate_module",
                "target_modules",
                "violated_contract",
                "reason",
                "template_repair_requires_internal_boundary_trace",
            )
        }
        | {
            "trace_record": {
                key: trace.get(key)
                for key in (
                    "status",
                    "source",
                    "evidence_type",
                    "failure_class",
                    "stage_id",
                    "module",
                    "contract",
                    "violated_contract",
                    "summary",
                    "word_index",
                    "beat_index",
                    "lane_index",
                    "logical_index",
                    "observed_value",
                    "expected_value",
                    "num_mismatch",
                    "mismatch_fraction",
                    "rtl_output_sha256",
                    "input_fingerprint_sha256",
                    "expected_output_sha256",
                    "testbench_sha256",
                )
            },
            "targeted_replay_plan": action.get("targeted_replay_plan", {}),
        },
    }


def target_module_result(stage_report: dict[str, Any], module: str) -> dict[str, Any] | None:
    for row in stage_report.get("module_results", []):
        if isinstance(row, dict) and str(row.get("module")) == module:
            return row
    return None


def first_failed_module(stage_report: dict[str, Any]) -> dict[str, Any] | None:
    for row in stage_report.get("module_results", []):
        if isinstance(row, dict) and row.get("status") != "pass":
            return row
    return None


def read_json_if_exists(path: Path) -> dict[str, Any]:
    if not path.exists():
        return {}
    try:
        data = read_json(path)
    except (OSError, ValueError, json.JSONDecodeError):
        return {}
    return data if isinstance(data, dict) else {}


def template_candidates_for_module(module: str) -> list[str]:
    base = Path.cwd() / "accagent" / "framework" / "templates" / "operator_chisel"
    names = [module]
    if "_" in module:
        names.append(module.split("_", 1)[0])
    candidates = []
    for name in names:
        path = base / f"{name}.scala"
        if path.exists():
            candidates.append(str(path))
    return sorted(set(candidates))


def summarize_leaf_report(stage_report: dict[str, Any], module: str) -> dict[str, Any]:
    target = target_module_result(stage_report, module) or {}
    failed = first_failed_module(stage_report) or {}
    target_diagnostics = target.get("failure_diagnostics", {})
    if not isinstance(target_diagnostics, dict) or not target_diagnostics:
        target_diagnostics = semantic_failure_diagnostics(stage_report)
    return {
        "status": stage_report.get("status"),
        "summary": stage_report.get("summary"),
        "stage_id": stage_report.get("stage_id"),
        "target_module": module,
        "target_module_status": target.get("status"),
        "target_module_summary": target.get("summary"),
        "target_liveness_contract": target.get("liveness_contract", {}),
        "target_failure_diagnostics": target_diagnostics,
        "first_failed_module": stage_report.get("first_failed_module") or failed.get("module"),
        "first_failed_summary": stage_report.get("first_failed_summary") or failed.get("summary"),
        "blockers": stage_report.get("blockers", [])[:12],
    }


def run_causal_leaf_replay(
    *,
    state: dict[str, Any],
    run_dir: Path,
    step: dict[str, Any],
    out_dir: Path,
    timeout_sec: int,
    mode: str = "functional",
) -> dict[str, Any]:
    record = trace_record_from_step(step)
    stage_id = str(record.get("stage_id") or "")
    module = str(record.get("module") or step.get("repair_context", {}).get("root_candidate_module") or "")
    if not stage_id:
        return {"status": "fail", "summary": "causal slice is missing stage_id", "stage_id": stage_id, "module": module}
    case_adapter = case_adapter_for_state(state, run_dir)
    role = "leaf_golden_compare" if mode == "golden" else "leaf_functional_sim"
    spec = adapter_tool(case_adapter, role)
    if not spec:
        return {
            "status": "fail",
            "summary": f"case adapter has no tool for targeted leaf replay role={role}",
            "stage_id": stage_id,
            "module": module,
            "case_id": case_adapter.get("case_id"),
        }
    argv = [str(item) for item in spec.get("argv", [])]
    targeted = spec.get("targeted_replay", {}) if isinstance(spec.get("targeted_replay"), dict) else {}
    stage_arg = str(targeted.get("stage_id_arg") or "")
    if not argv or not stage_arg:
        return {
            "status": "fail",
            "summary": f"case adapter tool {spec.get('name')} does not declare targeted_replay.stage_id_arg",
            "stage_id": stage_id,
            "module": module,
            "case_id": case_adapter.get("case_id"),
        }
    if stage_arg not in argv:
        argv.extend([stage_arg, stage_id])
    env = os.environ.copy()
    env.update({str(k): str(v) for k, v in dict(spec.get("env") or {}).items() if v is not None and v != ""})
    replay_env = step.get("targeted_replay_plan", {}).get("rerun_env", {}) if isinstance(step.get("targeted_replay_plan"), dict) else {}
    env.update({str(k): str(v) for k, v in dict(replay_env).items() if v is not None})
    env.setdefault("SPATIALACC_LEAF_VERILATOR_TIMEOUT_SEC", str(timeout_sec))
    result = run_local_tool(argv, Path.cwd(), env, timeout_sec)
    result.update(
        {
            "argv": argv,
            "cwd": str(Path.cwd()),
            "stage_id": stage_id,
            "module": module,
            "case_id": case_adapter.get("case_id"),
            "case_adapter_tool": spec.get("name"),
            "case_adapter_role": role,
        }
    )
    log_path = out_dir / f"{safe_step_id(step)}_targeted_leaf_{mode}_replay.json"
    write_json(log_path, result)
    result["log_path"] = str(log_path)
    return result


def resolve_run_path(run_dir: Path, value: Any) -> Path:
    path = Path(str(value))
    return path if path.is_absolute() else run_dir / path


def adapter_tool_by_name_or_role(case_adapter: dict[str, Any], value: Any) -> tuple[str, dict[str, Any] | None]:
    needle = str(value or "").strip()
    if not needle:
        return "", None
    tools = case_adapter.get("tools", {}) if isinstance(case_adapter.get("tools"), dict) else {}
    direct = tools.get(needle)
    if isinstance(direct, dict):
        return needle, direct
    for role, spec in tools.items():
        if not isinstance(spec, dict):
            continue
        names = {str(role), str(spec.get("name") or ""), str(spec.get("legacy_name") or ""), str(spec.get("kind") or "")}
        if needle in names:
            return str(role), spec
    return "", None


def adapter_tool_by_capabilities(
    case_adapter: dict[str, Any],
    required: set[str],
    preferred: set[str] | None = None,
) -> tuple[str, dict[str, Any] | None]:
    tools = case_adapter.get("tools", {}) if isinstance(case_adapter.get("tools"), dict) else {}
    candidates: list[tuple[int, str, dict[str, Any]]] = []
    for role, spec in tools.items():
        if not isinstance(spec, dict):
            continue
        capabilities = {str(value) for value in spec.get("capabilities", []) if str(value)}
        if not required.issubset(capabilities):
            continue
        score = len(capabilities.intersection(preferred or set()))
        candidates.append((score, str(role), spec))
    if not candidates:
        return "", None
    _, role, spec = sorted(candidates, key=lambda row: (-row[0], row[1]))[0]
    return role, spec


def select_exact_board_validation_tools(
    case_adapter: dict[str, Any],
) -> tuple[str, dict[str, Any] | None, str, dict[str, Any] | None]:
    vcs_role, vcs_spec = adapter_tool_by_capabilities(
        case_adapter,
        {"real_functional_sim", "board_wrapper_functional_sim"},
        {
            "exact_sample_board_wrapper_simulation",
            "all_target_layers",
            "elaborated_hierarchy_binding",
            "structured_axi_protocol_monitors",
        },
    )
    analyzer_role, analyzer_spec = adapter_tool_by_capabilities(
        case_adapter,
        {"vcs_evidence_analyzer"},
        {"semantic_comparison_evidence", "failure_localization_input"},
    )
    return vcs_role, vcs_spec, analyzer_role, analyzer_spec


def select_capability_tool(step: dict[str, Any], case_adapter: dict[str, Any]) -> tuple[str, dict[str, Any] | None]:
    action = step.get("action", {}) if isinstance(step.get("action"), dict) else {}
    if str(action.get("repair_kind") or "") == "exact_board_integration_harness":
        role, spec, _, _ = select_exact_board_validation_tools(case_adapter)
        return role, spec
    candidates: list[Any] = [
        action.get("repair_kind"),
        action.get("repair_tool_role"),
        action.get("repair_tool_name"),
        action.get("repair_gate"),
        step.get("tool"),
    ]
    for gate in action.get("failed_current_layer_gates", []):
        if isinstance(gate, dict):
            candidates.append(gate.get("name"))
    for candidate in candidates:
        role, spec = adapter_tool_by_name_or_role(case_adapter, candidate)
        if spec:
            return role, spec
    record = trace_record_from_step(step)
    if record.get("stage_id"):
        spec = adapter_tool(case_adapter, "leaf_golden_compare")
        if spec:
            return "leaf_golden_compare", spec
    return "", None


def select_reference_builder_tool(case_adapter: dict[str, Any]) -> tuple[str, dict[str, Any] | None]:
    required = {"target_model_inference", "independent_expected_output"}
    tools = case_adapter.get("tools", {}) if isinstance(case_adapter.get("tools"), dict) else {}
    for role, spec in tools.items():
        if not isinstance(spec, dict):
            continue
        capabilities = {str(item) for item in spec.get("capabilities", [])}
        if capabilities.intersection(required):
            return str(role), spec
    return "", None


def select_current_layer_replay_tool(step: dict[str, Any], case_adapter: dict[str, Any]) -> tuple[str, dict[str, Any] | None]:
    action = step.get("action", {}) if isinstance(step.get("action"), dict) else {}
    debug_layer = str(action.get("debug_layer") or step.get("debug_layer") or "")
    candidates: list[Any] = []
    for gate in action.get("failed_current_layer_gates", []):
        if isinstance(gate, dict):
            candidates.append(gate.get("name"))
    candidates.extend(
        [
            action.get("repair_gate"),
            action.get("recommended_trace_gate"),
            step.get("tool"),
        ]
    )
    if debug_layer == "single_transformer_layer_kernel":
        candidates.extend(["case_single_layer_functional", "single_layer_functional_sim"])
    elif debug_layer == "board_axi_ddr_wrapped_system":
        candidates = [
            "case_vcs_functional_sim",
            "vcs_functional_sim",
            *candidates,
            "functional_sim",
            "case_multilayer_functional",
            "multilayer_functional_sim",
        ]
    for candidate in candidates:
        role, spec = adapter_tool_by_name_or_role(case_adapter, candidate)
        if spec:
            return role, spec
    return "", None


def run_current_layer_causal_replay(
    *,
    state: dict[str, Any],
    run_dir: Path,
    step: dict[str, Any],
    out_dir: Path,
    timeout_sec: int,
) -> dict[str, Any]:
    case_adapter = case_adapter_for_state(state, run_dir)
    role, spec = select_current_layer_replay_tool(step, case_adapter)
    if not spec:
        return {
            "status": "blocked",
            "summary": "case adapter does not declare a current-layer replay tool for this causal slice",
            "case_id": case_adapter.get("case_id"),
            "debug_layer": step.get("debug_layer"),
        }
    argv = [str(item) for item in spec.get("argv", [])]
    if not argv:
        return {
            "status": "blocked",
            "summary": f"case adapter tool {spec.get('name')} has no argv",
            "case_id": case_adapter.get("case_id"),
            "case_adapter_role": role,
        }
    env = os.environ.copy()
    env.update({str(k): str(v) for k, v in dict(spec.get("env") or {}).items() if v is not None and v != ""})
    replay_env = step.get("targeted_replay_plan", {}).get("rerun_env", {}) if isinstance(step.get("targeted_replay_plan"), dict) else {}
    env.update({str(k): str(v) for k, v in dict(replay_env).items() if v is not None})
    env["SPATIALACC_BOUNDARY_TRACE"] = "1"
    env["SPATIALACC_TARGETED_REPLAY"] = "1"
    action = step.get("action", {}) if isinstance(step.get("action"), dict) else {}
    repair_kind = str(step.get("repair_kind") or action.get("repair_kind") or "")
    cctg_connected_kernel_replay = repair_kind in {
        "cctg_connected_kernel_boundary_replay",
        "connected_kernel_cctg_contradiction_targeted_replay",
    }
    connected_kernel_direct_targeted_replay = (
        repair_kind == "connected_kernel_cctg_contradiction_targeted_replay"
    )
    cctg_evidence_execution_mode = "fresh_remote_vcs_execution"
    cctg_rematerialization_attempt: dict[str, Any] | None = None
    if cctg_connected_kernel_replay:
        env["SPATIALACC_CCTG_CONNECTED_KERNEL_REPLAY"] = "1"
        if connected_kernel_direct_targeted_replay:
            env["SPATIALACC_CONNECTED_KERNEL_TARGETED_REPLAY"] = "1"
        # First ask the generic producer whether an already-completed, fresh,
        # source-bound VCS execution can be reinterpreted. This is a local
        # artifact operation only; it neither compiles nor simulates. If that
        # proof is unavailable, the requested CCTG experiment still proceeds
        # through the one normal fresh remote VCS path below.
        rematerialization_result = run_local_tool(
            [*argv, "--rematerialize-cctg-evidence"],
            Path.cwd(),
            env,
            timeout_sec,
        )
        cctg_rematerialization_attempt = {
            **rematerialization_result,
            "argv": [*argv, "--rematerialize-cctg-evidence"],
            "kind": "completed_fresh_execution_evidence_rematerialization",
        }
        if rematerialization_result.get("status") == "pass":
            result = rematerialization_result
            cctg_evidence_execution_mode = "completed_fresh_execution_rematerialization"
        else:
            result = None
    else:
        result = None
    if cctg_connected_kernel_replay and result is None:
        # A CCTG replay is a new observation experiment. Its report must be
        # sourced from a fresh remote VCS execution, never an exact-input cache.
        env["SPATIALACC_FORCE_FRESH_REMOTE_VCS"] = "1"
    checkpoint_request: dict[str, Any] = {
        "status": "not_run",
        "summary": "state checkpoint replay is only used for the board AXI/DDR debug layer",
    }
    checkpoint_request_path: Path | None = None
    debug_layer = str(step.get("debug_layer") or step.get("action", {}).get("debug_layer") or "")
    if debug_layer == "board_axi_ddr_wrapped_system":
        checkpoint_preparation = prepare_stage3_checkpoint_probe_environment(
            run_dir,
            label=f"{safe_step_id(step)}_current_layer",
        )
        checkpoint_request = checkpoint_preparation.get("request", {})
        checkpoint_request_path_value = checkpoint_preparation.get("request_path")
        checkpoint_request_path = (
            Path(str(checkpoint_request_path_value))
            if checkpoint_request_path_value
            else None
        )
        env.update(checkpoint_preparation.get("env", {}))
    if step.get("debug_layer"):
        env["SPATIALACC_DEBUG_LAYER"] = str(step.get("debug_layer"))
    if result is None:
        result = run_local_tool(argv, Path.cwd(), env, timeout_sec)
    result.update(
        {
            "argv": argv,
            "cwd": str(Path.cwd()),
            "case_id": case_adapter.get("case_id"),
            "case_adapter_tool": spec.get("name"),
            "case_adapter_role": role,
            "debug_layer": step.get("debug_layer"),
            "simulation_checkpoint_request": (
                {
                    "path": str(checkpoint_request_path),
                    "sha256": sha256_file(checkpoint_request_path),
                    "value": checkpoint_request,
                }
                if checkpoint_request_path is not None
                else checkpoint_request
            ),
            "produced_reports": produced_json_reports(spec, run_dir),
        }
    )
    if cctg_rematerialization_attempt is not None:
        result["cctg_evidence_rematerialization_attempt"] = cctg_rematerialization_attempt
        result["cctg_evidence_execution_mode"] = cctg_evidence_execution_mode
    if cctg_connected_kernel_replay:
        cctg_path = run_dir / "verification" / "debug_closure" / "cctg_boundary_replay.json"
        cctg = read_json_if_exists(cctg_path)
        cctg_blockers: list[str] = []
        if cctg.get("schema_version") != "spatialaccagent.cctg_boundary_replay.v1":
            cctg_blockers.append("targeted replay did not produce the CCTG boundary replay schema")
        if cctg.get("status") != "pass":
            cctg_blockers.extend(
                str(value)
                for value in cctg.get("blockers", [])
                if str(value)
            )
        if cctg.get("fresh_remote_vcs_execution_observed") is not True:
            cctg_blockers.append("CCTG boundary replay was not backed by a fresh remote VCS execution")
        if not isinstance(cctg.get("boundary_records"), list) or not cctg.get("boundary_records"):
            cctg_blockers.append("CCTG boundary replay has no declared boundary records")
        result["cctg_boundary_replay"] = {
            "path": str(cctg_path),
            "sha256": sha256_file(cctg_path) if cctg_path.is_file() else None,
                "status": cctg.get("status"),
                "boundary_liveness_status": cctg.get("boundary_liveness_status"),
                "first_incomplete_boundary": cctg.get("first_incomplete_boundary"),
                "blockers": list(dict.fromkeys(cctg_blockers)),
        }
        result["produced_reports"].append(
            {
                "path": str(cctg_path),
                "schema_version": cctg.get("schema_version"),
                "status": cctg.get("status"),
                "summary": cctg.get("summary"),
                "blockers": cctg.get("blockers", []),
            }
        )
        if connected_kernel_direct_targeted_replay:
            direct_paths = {
                "connected_kernel_targeted_replay_trace": (
                    run_dir
                    / "verification"
                    / "debug_closure"
                    / "connected_kernel_cctg_targeted_replay_trace.json"
                ),
                "connected_kernel_targeted_replay_causal_context": (
                    run_dir
                    / "verification"
                    / "case_diagnostics"
                    / "connected_kernel_targeted_replay_causal_context.json"
                ),
                "connected_kernel_cctg_contradiction_reconciliation": (
                    run_dir
                    / "verification"
                    / "case_diagnostics"
                    / "connected_kernel_cctg_contradiction_reconciliation.json"
                ),
                "immutable_semantic_replay_input_manifest": (
                    run_dir / "repair" / "immutable_semantic_replay_input_manifest.json"
                ),
                "connected_kernel_targeted_replay_manifest": (
                    run_dir
                    / "verification"
                    / "case_diagnostics"
                    / "connected_kernel_targeted_replay_manifest.json"
                ),
            }
            direct_reports: dict[str, dict[str, Any]] = {}
            for name, path in direct_paths.items():
                report = read_json_if_exists(path)
                direct_reports[name] = {
                    "path": str(path),
                    "sha256": sha256_file(path) if path.is_file() else None,
                    "status": report.get("status"),
                    "schema_version": report.get("schema_version"),
                    "blockers": report.get("blockers", []),
                }
                result["produced_reports"].append(direct_reports[name])
            direct_trace = direct_reports["connected_kernel_targeted_replay_trace"]
            direct_context = direct_reports["connected_kernel_targeted_replay_causal_context"]
            direct_blockers = [
                "connected-kernel targeted replay did not produce direct lifecycle evidence"
            ] if (
                direct_trace["schema_version"]
                != "spatialaccagent.connected_kernel_cctg_targeted_replay_trace.v1"
                or direct_trace["status"] != "pass"
                or direct_context["schema_version"]
                != "spatialaccagent.connected_kernel_targeted_replay_causal_context.v1"
                or direct_context["status"] != "pass"
            ) else []
            result["connected_kernel_targeted_replay"] = direct_reports
            if direct_blockers:
                cctg_blockers.extend(direct_blockers)
        result["cctg_boundary_replay"]["blockers"] = list(
            dict.fromkeys(cctg_blockers)
        )
        if cctg_blockers:
            result["status"] = "fail"
            result["summary"] = "targeted CCTG boundary replay is incomplete"
    log_path = out_dir / f"{safe_step_id(step)}_current_layer_causal_replay.json"
    write_json(log_path, result)
    result["log_path"] = str(log_path)
    return result


def produced_json_reports(spec: dict[str, Any] | None, run_dir: Path) -> list[dict[str, Any]]:
    reports: list[dict[str, Any]] = []
    for value in (spec or {}).get("produces", []):
        path = resolve_run_path(run_dir, value)
        candidates = sorted(path.glob("*.json")) if path.is_dir() else [path]
        for candidate in candidates:
            if candidate.suffix.lower() != ".json" or not candidate.exists():
                continue
            data = read_json_if_exists(candidate)
            if data:
                reports.append(
                    {
                        "path": str(candidate),
                        "schema_version": data.get("schema_version"),
                        "status": data.get("status"),
                        "summary": data.get("summary"),
                        "blockers": data.get("blockers", []) if isinstance(data.get("blockers"), list) else [],
                    }
                )
    return reports


def run_capability_probe(
    *,
    case_adapter: dict[str, Any],
    spec_role: str,
    spec: dict[str, Any] | None,
    run_dir: Path,
    step: dict[str, Any],
    out_dir: Path,
    timeout_sec: int,
    label: str = "",
    extra_env: dict[str, str] | None = None,
) -> dict[str, Any]:
    if not spec:
        return {
            "status": "blocked",
            "summary": "case adapter does not declare a tool for the current verification capability repair gate",
            "case_id": case_adapter.get("case_id"),
            "tool_role": spec_role,
        }
    argv = [str(item) for item in spec.get("argv", [])]
    if not argv:
        return {
            "status": "blocked",
            "summary": f"case adapter tool {spec.get('name')} has no argv",
            "case_id": case_adapter.get("case_id"),
            "tool_role": spec_role,
        }
    record = trace_record_from_step(step)
    targeted = spec.get("targeted_replay", {}) if isinstance(spec.get("targeted_replay"), dict) else {}
    stage_arg = str(targeted.get("stage_id_arg") or "")
    stage_id = str(record.get("stage_id") or "")
    if stage_id and stage_arg and stage_arg not in argv:
        argv.extend([stage_arg, stage_id])
    env = os.environ.copy()
    env.update({str(k): str(v) for k, v in dict(spec.get("env") or {}).items() if v is not None and v != ""})
    env.update(
        {
            str(key): str(value)
            for key, value in dict(extra_env or {}).items()
            if value is not None and str(value) != ""
        }
    )
    env["SPATIALACC_REPAIR_CAPABILITY_CHECK"] = "1"
    env["SPATIALACC_VERIFICATION_SCOPE"] = verification_scope_for_step(step)
    if step.get("debug_layer"):
        env["SPATIALACC_DEBUG_LAYER"] = str(step.get("debug_layer"))
    started_ns = time.time_ns()
    result = run_local_tool(argv, Path.cwd(), env, timeout_sec)
    result.update(
        {
            "argv": argv,
            "cwd": str(Path.cwd()),
            "case_id": case_adapter.get("case_id"),
            "case_adapter_tool": spec.get("name"),
            "case_adapter_role": spec_role,
            "case_adapter_scope": spec.get("scope"),
            "produced_reports": produced_json_reports(spec, run_dir),
        }
    )
    annotate_verification_capability_probe(result, step)
    if any("case_board_vcs_functional.py" in str(item) for item in argv):
        runner_path = (
            run_dir / "verification" / "vcs" / "case_board_vcs_functional.json"
        )
        if runner_path.is_file() and runner_path.stat().st_mtime_ns >= started_ns:
            runner_report = read_json_if_exists(runner_path)
            result["fast_replay_state"] = update_fast_replay_state(
                run_dir,
                runner_report,
            )
    suffix = f"_{label}" if label else ""
    log_path = out_dir / f"{safe_step_id(step)}_verification_capability_probe{suffix}.json"
    write_json(log_path, result)
    result["log_path"] = str(log_path)
    return result


def run_board_semantic_rtl_single_layer_gate(
    *,
    case_adapter: dict[str, Any],
    run_dir: Path,
    step: dict[str, Any],
    out_dir: Path,
    timeout_sec: int,
) -> dict[str, Any]:
    """Run the connected-layer gate before allowing a board VCS replay.

    A board semantic RTL repair changes the kernel source used by both the
    connected-layer and exact-board harnesses.  The connected-layer result is
    therefore a mandatory safety gate, not an optional follow-up.  Keep this
    helper limited to selecting and running the case-adapter tool so it cannot
    accidentally enter the board VCS path.
    """

    single_role, single_spec = adapter_tool_by_name_or_role(
        case_adapter, "case_single_layer_functional"
    )
    if not single_spec:
        result = {
            "status": "blocked",
            "summary": (
                "case adapter does not declare case_single_layer_functional; "
                "board VCS is forbidden after a semantic RTL repair"
            ),
            "case_adapter_role": single_role,
            "board_vcs_started": False,
        }
    else:
        single_step = copy.deepcopy(step)
        single_action = (
            single_step.get("action", {})
            if isinstance(single_step.get("action"), dict)
            else {}
        )
        single_action.update(
            {
                "repair_kind": "case_single_layer_functional",
                "repair_gate": "case_single_layer_functional",
                "debug_layer": "single_transformer_layer_kernel",
                "target_modules": [
                    "connected_single_transformer_layer_kernel",
                    "single_layer_pipeline_overlap_contract",
                ],
            }
        )
        single_step["action"] = single_action
        single_step["debug_layer"] = "single_transformer_layer_kernel"
        result = run_capability_probe(
            case_adapter=case_adapter,
            spec_role=single_role,
            spec=single_spec,
            run_dir=run_dir,
            step=single_step,
            out_dir=out_dir,
            timeout_sec=timeout_sec,
            label="post_semantic_rtl_single_layer",
        )
        result["board_vcs_started"] = False
        result["single_layer_gate"] = "case_single_layer_functional"

    gate_path = out_dir / "board_semantic_rtl_single_layer_gate.json"
    write_json(gate_path, result)
    result["gate_path"] = str(gate_path)
    result["verification_layer"] = "layer2_connected_single_transformer"
    return result


def reuse_existing_single_layer_gate_for_board_repair(run_dir: Path) -> bool:
    """Reuse a completed single-layer gate during the board-only repair loop.

    The board loop must not spend another long VCS run repeating an already
    completed connected-layer check. A new run without that report still uses
    the normal prerequisite gate; the environment switch is available for a
    deliberate fresh prerequisite check.
    """

    if os.environ.get("SPATIALACC_FORCE_SINGLE_LAYER_GATE") == "1":
        return False
    report_path = (
        run_dir / "verification" / "single_layer" / "single_layer_functional_report.json"
    )
    report = read_json_if_exists(report_path)
    return report.get("status") == "pass"


def _feedback_artifact_value(
    feedback: dict[str, Any],
    name: str,
) -> dict[str, Any]:
    artifact = feedback.get(name, {})
    artifact = artifact if isinstance(artifact, dict) else {}
    value = artifact.get("value", {})
    return value if isinstance(value, dict) else {}


def _proven_zero_time_livelock_feedback(
    feedback: dict[str, Any],
) -> bool:
    """Accept only a complete exact-job zero-time livelock diagnosis."""

    runner = _feedback_artifact_value(feedback, "runner_report")
    diagnosis = _feedback_artifact_value(feedback, "diagnosis")
    run = runner.get("run", {}) if isinstance(runner.get("run"), dict) else {}
    evidence = (
        run.get("zero_time_livelock_evidence", {})
        if isinstance(run.get("zero_time_livelock_evidence"), dict)
        else {}
    )
    termination = (
        run.get("zero_time_livelock_termination", {})
        if isinstance(run.get("zero_time_livelock_termination"), dict)
        else {}
    )
    handoff = (
        diagnosis.get("repair_handoff", {})
        if isinstance(diagnosis.get("repair_handoff"), dict)
        else {}
    )
    fingerprint = str(runner.get("input_fingerprint_sha256") or "")
    remote_workdir = str(run.get("remote_workdir") or "")
    return bool(
        feedback.get("status") == "ready"
        and runner.get("status") == "fail"
        and re.fullmatch(r"[0-9a-f]{64}", fingerprint)
        and remote_workdir
        and run.get("status") == "fail"
        and run.get("returncode") == 87
        and run.get("failure_class") == "zero_time_simulation_livelock"
        and evidence.get("schema_version")
        == "spatialaccagent.zero_time_livelock_evidence.v1"
        and evidence.get("status") == "proven_zero_time_livelock"
        and evidence.get("remote_workdir") == remote_workdir
        and termination.get("schema_version")
        == "spatialaccagent.zero_time_livelock_termination.v1"
        and termination.get("status") == "pass"
        and termination.get("remote_exit_code") == 87
        and termination.get("remote_workdir") == remote_workdir
        and termination.get("evidence") == evidence
        and diagnosis.get("status") in {"fail", "needs_repair"}
        and diagnosis.get("diagnosis_status") == "ready"
        and diagnosis.get("failure_class") == "vcs_runtime_zero_time_livelock"
        and diagnosis.get("root_cause_class") == "vcs_runtime_zero_time_livelock"
        and handoff.get("agent_should_apply_code_changes") is True
        and handoff.get("failure_class") == "vcs_runtime_zero_time_livelock"
    )


def recover_post_patch_zero_time_livelock_feedback(
    run_dir: Path,
    current_feedback: dict[str, Any],
) -> dict[str, Any] | None:
    """Recover a superseded zero-time diagnosis for the same exact VCS job.

    A controller restart can re-analyze a preserved exit code before the runner
    has persisted its live recovery record.  The post-patch capability probe is
    the durable same-job snapshot in that narrow window.  It is never used
    across a changed fingerprint or remote work directory.
    """

    current_runner = _feedback_artifact_value(current_feedback, "runner_report")
    current_diagnosis = _feedback_artifact_value(current_feedback, "diagnosis")
    current_run = (
        current_runner.get("run", {})
        if isinstance(current_runner.get("run"), dict)
        else {}
    )
    fingerprint = str(current_runner.get("input_fingerprint_sha256") or "")
    remote_workdir = str(current_run.get("remote_workdir") or "")
    if (
        _proven_zero_time_livelock_feedback(current_feedback)
        or current_runner.get("status") != "fail"
        or current_run.get("status") != "fail"
        or current_run.get("returncode") != 87
        or not re.fullmatch(r"[0-9a-f]{64}", fingerprint)
        or not remote_workdir
        or current_diagnosis.get("failure_class")
        == "vcs_runtime_zero_time_livelock"
    ):
        return None

    repair_dir = run_dir / "repair_execution"
    probe_paths = sorted(
        repair_dir.glob("*_verification_capability_probe_post_patch.json"),
        key=lambda path: path.stat().st_mtime_ns,
        reverse=True,
    )
    for probe_path in probe_paths:
        probe = read_json_if_exists(probe_path)
        archived = probe.get("current_board_vcs_feedback", {})
        archived = archived if isinstance(archived, dict) else {}
        if not _proven_zero_time_livelock_feedback(archived):
            continue
        archived_runner = _feedback_artifact_value(archived, "runner_report")
        archived_run = (
            archived_runner.get("run", {})
            if isinstance(archived_runner.get("run"), dict)
            else {}
        )
        if (
            archived_runner.get("input_fingerprint_sha256") != fingerprint
            or archived_run.get("remote_workdir") != remote_workdir
        ):
            continue
        recovered = copy.deepcopy(archived)
        recovered["post_patch_zero_time_livelock_recovery"] = {
            "schema_version": (
                "spatialaccagent.post_patch_zero_time_livelock_recovery.v1"
            ),
            "status": "ready",
            "source_probe": {
                "path": str(probe_path),
                "sha256": sha256_file(probe_path),
            },
            "same_remote_job": {
                "input_fingerprint_sha256": fingerprint,
                "remote_workdir": remote_workdir,
            },
        }
        return recovered
    return None


def exact_board_vcs_feedback(
    case_adapter: dict[str, Any],
    run_dir: Path,
    vcs_spec: dict[str, Any] | None,
    analyzer_spec: dict[str, Any] | None,
) -> dict[str, Any]:
    candidate_paths: set[Path] = set()

    def add_candidate(value: Any) -> None:
        if not value:
            return
        path = resolve_run_path(run_dir, value)
        if path.is_dir():
            candidate_paths.update(path.rglob("*.json"))
        elif path.suffix.lower() == ".json":
            candidate_paths.add(path)

    for spec in (vcs_spec, analyzer_spec):
        for field in ("produces", "consumes"):
            for value in (spec or {}).get(field, []):
                add_candidate(value)
    diagnosis_binding = (
        case_adapter.get("diagnosis", {})
        if isinstance(case_adapter.get("diagnosis"), dict)
        else {}
    )
    add_candidate(diagnosis_binding.get("path"))
    add_candidate(diagnosis_binding.get("legacy_path"))

    parsed: list[tuple[Path, dict[str, Any]]] = []
    for path in sorted(candidate_paths):
        data = read_json_if_exists(path)
        if data:
            parsed.append((path, data))
    diagnosis_rows = [
        (path, data)
        for path, data in parsed
        if isinstance(data.get("repair_handoff"), dict)
        and (data.get("diagnosis_status") or "diagnosis" in str(data.get("schema_version") or ""))
    ]
    for _, diagnosis in diagnosis_rows:
        for value in diagnosis.get("sources", []):
            add_candidate(value)
    for path in sorted(candidate_paths):
        if any(existing == path for existing, _ in parsed):
            continue
        data = read_json_if_exists(path)
        if data:
            parsed.append((path, data))
    diagnosis_rows = [
        (path, data)
        for path, data in parsed
        if isinstance(data.get("repair_handoff"), dict)
        and (data.get("diagnosis_status") or "diagnosis" in str(data.get("schema_version") or ""))
    ]
    runner_rows = [
        (path, data)
        for path, data in parsed
        if data.get("phase")
        and (
            isinstance(data.get("compile"), dict)
            or isinstance(data.get("run"), dict)
            or "board_vcs_functional_run" in str(data.get("schema_version") or "")
        )
    ]

    def latest(rows: list[tuple[Path, dict[str, Any]]]) -> tuple[Path, dict[str, Any]] | None:
        return max(rows, key=lambda row: row[0].stat().st_mtime_ns) if rows else None

    def bound(row: tuple[Path, dict[str, Any]] | None) -> dict[str, Any] | None:
        if row is None:
            return None
        path, value = row
        return {
            "path": str(path),
            "sha256": sha256_file(path),
            "value": value,
        }

    diagnosis_artifact = bound(latest(diagnosis_rows))
    runner_artifact = bound(latest(runner_rows))
    blockers = []
    if diagnosis_artifact is None:
        blockers.append("current case-adapter VCS diagnosis report is missing")
    if runner_artifact is None:
        blockers.append("current case-adapter board VCS runner report is missing")
    feedback = {
        "schema_version": "spatialaccagent.exact_board_vcs_feedback.v1",
        "status": "ready" if not blockers else "incomplete",
        "blockers": blockers,
        "diagnosis": diagnosis_artifact,
        "runner_report": runner_artifact,
    }
    feedback = recover_post_patch_zero_time_livelock_feedback(run_dir, feedback) or feedback
    if not interrupted_exact_board_compile_feedback(feedback):
        return feedback

    # A controller or user interruption can leave the mutable live runner
    # report looking like a compile failure even though it has no real compile
    # diagnostic and no completed simulation. Do not let that partial record
    # replace a previously completed board experiment when the next Agent turn
    # needs signal evidence. A completed archive remains diagnostic evidence,
    # never passing evidence or proof that it ran the current source state.
    for archived in archived_exact_board_vcs_feedback(run_dir):
        if interrupted_exact_board_compile_feedback(archived):
            continue
        archived = copy.deepcopy(archived)
        archived["replaced_incomplete_interrupted_feedback"] = {
            "schema_version": (
                "spatialaccagent.interrupted_exact_board_feedback_recovery.v1"
            ),
            "status": "ready",
            "interrupted_runner_report": {
                "path": runner_artifact.get("path") if runner_artifact else None,
                "sha256": runner_artifact.get("sha256") if runner_artifact else None,
            },
            "reason": (
                "the live compile record was recovered without a real compile "
                "diagnostic or completed simulation terminal record"
            ),
        }
        return archived
    return feedback


def interrupted_exact_board_compile_feedback(feedback: dict[str, Any]) -> bool:
    """Identify a recovered interrupted compile that is not hardware evidence.

    A real VCS compile failure has a concrete compiler diagnostic. This narrow
    shape instead comes from recovery after the local controller is interrupted:
    the detached remote job state is incomplete, no simulation starts, and the
    runner cannot attribute a terminal event. It must not replace the latest
    completed waveform/board evidence used by the repair Agent.
    """

    runner = _feedback_artifact_value(feedback, "runner_report")
    compile_result = (
        runner.get("compile", {})
        if isinstance(runner.get("compile"), dict)
        else {}
    )
    run_result = (
        runner.get("run", {})
        if isinstance(runner.get("run"), dict)
        else {}
    )
    termination = (
        run_result.get("termination_provenance", {})
        if isinstance(run_result.get("termination_provenance"), dict)
        else runner.get("termination_provenance", {})
        if isinstance(runner.get("termination_provenance"), dict)
        else {}
    )
    transport = str(compile_result.get("transport") or "")
    return bool(
        feedback.get("status") == "ready"
        and runner.get("status") == "fail"
        and compile_result.get("status") == "fail"
        and transport.startswith("recovered_")
        and run_result.get("status") == "not_run"
        and str(run_result.get("summary") or "")
        == "recovered compile did not pass"
        and termination.get("status") == "indeterminate"
        and termination.get("terminal_progress_event_seen") is False
        and termination.get("simulator_terminal_log", {}).get("status") == "missing"
        if isinstance(termination.get("simulator_terminal_log"), dict)
        else False
    )


def exact_board_feedback_failure_class(feedback: dict[str, Any]) -> str:
    diagnosis = (
        feedback.get("diagnosis", {})
        if isinstance(feedback.get("diagnosis"), dict)
        else {}
    )
    value = diagnosis.get("value", diagnosis)
    value = value if isinstance(value, dict) else {}
    return str(value.get("failure_class") or "")


def exact_board_vcs_runner_feedback_is_current(
    feedback: dict[str, Any],
    vcs_spec: dict[str, Any] | None,
    manifest_path: Path | None = None,
) -> bool:
    runner = (
        feedback.get("runner_report", {}).get("value", {})
        if isinstance(feedback.get("runner_report"), dict)
        else {}
    )
    declared = str(runner.get("runner_implementation_sha256") or "")
    for token in (vcs_spec or {}).get("argv", []):
        path = repo_path(token)
        if path.is_file() and path.suffix.lower() in {".py", ".sh"}:
            if not declared or declared != sha256_file(path):
                return False
            break
    if manifest_path is None:
        return True
    manifest = read_json_if_exists(manifest_path)
    if not manifest:
        return False
    current_mode = str(
        manifest.get("validation_mode") or "exact_sample_physical_ddr"
    )
    if current_mode != EXACT_BOARD_FUNCTIONAL_VALIDATION_MODE:
        return False
    from scripts.verification.case_board_vcs_functional import (
        preflight_manifest_projection_sha256,
    )

    return (
        runner.get("validation_mode") == current_mode
        and runner.get("preflight_manifest_projection_sha256")
        == preflight_manifest_projection_sha256(manifest)
    )


def exact_board_repair_execution_projection_sha256(
    manifest: dict[str, Any],
) -> str:
    projection = copy.deepcopy(manifest)
    attestation = projection.get("frozen_compute_slot_identity_attestation")
    if isinstance(attestation, dict):
        for key in FROZEN_ATTESTATION_ROLLING_EVIDENCE_FIELDS:
            attestation.pop(key, None)
    from scripts.verification.case_board_vcs_functional import (
        preflight_manifest_projection_sha256,
    )

    return preflight_manifest_projection_sha256(projection)


def exact_board_source_state(
    run_dir: Path,
    staged_contents: dict[Path, str] | None = None,
) -> dict[str, Any]:
    run_dir = run_dir.resolve()
    board_root = (run_dir / "generated" / "board_integration").resolve()
    staged_contents = {
        path.resolve(): content for path, content in (staged_contents or {}).items()
    }
    paths = {
        path.resolve()
        for path in board_root.rglob("*")
        if path.is_file() and path.suffix.lower() in BOARD_INTEGRATION_SOURCE_SUFFIXES
    }
    paths.update(
        path
        for path in staged_contents
        if path.is_relative_to(board_root)
        and path.suffix.lower() in BOARD_INTEGRATION_SOURCE_SUFFIXES
    )
    rows = []
    changed_paths: list[str] = []
    for path in sorted(paths):
        content = staged_contents.get(path)
        digest = (
            hashlib.sha256(content.encode("utf-8")).hexdigest()
            if content is not None
            else sha256_file(path)
        )
        if content is not None and (
            not path.is_file() or sha256_file(path) != digest
        ):
            changed_paths.append(str(path.relative_to(run_dir)))
        rows.append(
            {
                "path": str(path.relative_to(run_dir)),
                "sha256": digest,
            }
        )
    result = {
        "schema_version": "spatialaccagent.exact_board_source_state.v1",
        "rows": rows,
        "canonical_sha256": canonical_contract_sha256(rows),
    }
    manifest_path = (
        run_dir / "generated" / "memory" / "dut_weight_binding_manifest.json"
    ).resolve()
    manifest_content = staged_contents.get(manifest_path)
    if manifest_content is not None:
        try:
            manifest = json.loads(manifest_content)
        except json.JSONDecodeError:
            manifest = {}
    else:
        manifest = read_json_if_exists(manifest_path)
    plan = (
        manifest.get("board_simulation_preflight_plan", {})
        if isinstance(manifest.get("board_simulation_preflight_plan"), dict)
        else {}
    )
    plan_sha256 = str(plan.get("vcs_compile_plan_sha256") or "")
    if not plan_sha256:
        plan_sha256 = str(
            read_json_if_exists(
                run_dir
                / "verification"
                / "board_simulation"
                / "board_simulation_manifest.json"
            ).get("vcs_compile_plan_sha256")
            or ""
        )
    if plan_sha256:
        result["vcs_compile_plan_sha256"] = plan_sha256
    if staged_contents:
        result["candidate_changed_paths"] = sorted(changed_paths)
    return result


def _bound_repair_iteration_snapshot(
    record: dict[str, Any],
    *,
    role: str,
    marker: str = "",
) -> dict[str, Any] | None:
    snapshots = (
        record.get("evidence_snapshots", [])
        if isinstance(record.get("evidence_snapshots"), list)
        else []
    )
    matches = [
        row
        for row in snapshots
        if isinstance(row, dict)
        and row.get("role") == role
        and (not marker or marker in Path(str(row.get("snapshot_path") or "")).name)
    ]
    if len(matches) != 1:
        return None
    row = matches[0]
    path = Path(str(row.get("snapshot_path") or ""))
    expected_sha256 = str(row.get("source_sha256") or "")
    if (
        not path.is_file()
        or not expected_sha256
        or sha256_file(path) != expected_sha256
    ):
        return None
    value = read_json_if_exists(path)
    if not value:
        return None
    return {
        "path": str(path),
        "source_path": row.get("source_path"),
        "sha256": expected_sha256,
        "value": value,
    }


def _board_repair_behavior_signature(diagnosis: dict[str, Any]) -> dict[str, Any]:
    evidence = (
        diagnosis.get("failure_evidence", {})
        if isinstance(diagnosis.get("failure_evidence"), dict)
        else {}
    )
    adaptive = (
        evidence.get("adaptive_semantic_stall_evidence", {})
        if isinstance(evidence.get("adaptive_semantic_stall_evidence"), dict)
        else {}
    )
    last_semantic = (
        adaptive.get("last_semantic_progress_event", {})
        if isinstance(adaptive.get("last_semantic_progress_event"), dict)
        else {}
    )
    latest = (
        adaptive.get("latest_stall_snapshot", {})
        if isinstance(adaptive.get("latest_stall_snapshot"), dict)
        else {}
    )
    causal_binding = (
        evidence.get("sacg_cctg_causal_slice", {})
        if isinstance(evidence.get("sacg_cctg_causal_slice"), dict)
        else {}
    )
    causal_slice = (
        causal_binding.get("value", {})
        if isinstance(causal_binding.get("value"), dict)
        else {}
    )
    causal_frontier = (
        causal_slice.get("earliest_unproven_frontier", {})
        if isinstance(causal_slice.get("earliest_unproven_frontier"), dict)
        else {}
    )
    certificate_projection = (
        causal_slice.get("hierarchical_certificate_projection", {})
        if isinstance(
            causal_slice.get("hierarchical_certificate_projection"), dict
        )
        else {}
    )
    frontier_observed = (
        causal_frontier.get("observed", {})
        if isinstance(causal_frontier.get("observed"), dict)
        else {}
    )
    active_boundary_observation = (
        latest.get("active_boundary_observation", {})
        if isinstance(latest.get("active_boundary_observation"), dict)
        else {}
    )
    zero_time = (
        evidence.get("zero_time_livelock_evidence", {})
        if isinstance(evidence.get("zero_time_livelock_evidence"), dict)
        else {}
    )
    causal_progress = {
        "frontier_observed": copy.deepcopy(frontier_observed),
        "active_boundary_observation": copy.deepcopy(active_boundary_observation),
    }
    causal_progress["canonical_sha256"] = canonical_contract_sha256(
        causal_progress
    )
    projection = {
        "failure_class": diagnosis.get("root_cause_class")
        or evidence.get("failure_class"),
        "first_real_error": evidence.get("first_real_error"),
        "last_semantic_event_cycle": adaptive.get("last_semantic_event_cycle"),
        "latest_cycle": adaptive.get("latest_cycle"),
        "stable_state_cycles": adaptive.get("stable_state_cycles"),
        "scheduler_state": latest.get("scheduler_state"),
        "layer": latest.get("layer"),
        "active_weight_bank": latest.get("active_weight_bank"),
        "preload_weight_bank": latest.get("preload_weight_bank"),
        "activation_read_bank": latest.get("activation_read_bank"),
        "activation_write_bank": latest.get("activation_write_bank"),
        "prefetch_progress": copy.deepcopy(latest.get("prefetch_progress")),
        "runtime_load_progress": copy.deepcopy(latest.get("runtime_load_progress")),
        "final_writeback_progress": copy.deepcopy(latest.get("final_writeback_progress")),
        "axi_read": copy.deepcopy(latest.get("axi_read")),
        "axi_write": copy.deepcopy(latest.get("axi_write")),
        "last_semantic_phase": last_semantic.get("phase"),
        "sacg_cctg_causal_slice_sha256": causal_binding.get("sha256"),
        "sacg_cctg_causal_slice_status": causal_slice.get("status"),
        "sacg_cctg_frontier_id": causal_frontier.get("frontier_id"),
        "sacg_cctg_causal_domain": causal_frontier.get("causal_domain"),
        "sacg_cctg_failed_boundary_ids": copy.deepcopy(
            causal_frontier.get("failed_boundary_ids", [])
        ),
        "causal_progress_projection": causal_progress,
        "lower_layer_certificate_contradicted": certificate_projection.get(
            "current_board_evidence_contradicts_lower_certificate"
        ),
        "zero_time_livelock": {
            key: zero_time.get(key)
            for key in (
                "status",
                "last_cycle",
                "last_semantic_progress_cycle",
                "last_progress_event_count",
            )
            if zero_time.get(key) is not None
        },
    }
    return {
        **projection,
        "canonical_sha256": canonical_contract_sha256(projection),
    }


def _numeric_causal_progress_metrics(attempt: dict[str, Any]) -> dict[str, int | float]:
    behavior = (
        attempt.get("behavior_signature", {})
        if isinstance(attempt.get("behavior_signature"), dict)
        else {}
    )
    progress = (
        behavior.get("causal_progress_projection", {})
        if isinstance(behavior.get("causal_progress_projection"), dict)
        else {}
    )
    metrics: dict[str, int | float] = {}

    def visit(value: Any, prefix: str) -> None:
        if isinstance(value, dict):
            for key in sorted(value):
                if key == "canonical_sha256":
                    continue
                child_prefix = f"{prefix}.{key}" if prefix else str(key)
                visit(value[key], child_prefix)
        elif isinstance(value, (int, float)) and not isinstance(value, bool):
            metrics[prefix] = value

    visit(progress, "")
    return metrics


def _frontier_response_metrics(attempt: dict[str, Any]) -> dict[str, int | float]:
    """Project cumulative graph-frontier progress without transient signal levels."""

    metrics = _numeric_causal_progress_metrics(attempt)
    projected: dict[str, int | float] = {}
    for path, value in metrics.items():
        if path.startswith("frontier_observed."):
            projected[path] = value
            continue
        if not path.startswith("active_boundary_observation."):
            continue
        field = path.rsplit(".", 1)[-1]
        if field.endswith(("_count", "_index", "_total", "_started", "_completed")):
            projected[path] = value
    return projected


def _runner_binds_post_edit_board_sources(
    runner: dict[str, Any],
    board_edits: list[dict[str, Any]],
) -> bool:
    """Prove that same-iteration tool evidence executed the post-edit sources."""

    if not board_edits:
        return True
    checkpoint_execution = (
        runner.get("checkpoint_execution", {})
        if isinstance(runner.get("checkpoint_execution"), dict)
        else {}
    )
    identities = [
        checkpoint_execution.get("execution_identity", {}),
        runner.get("simulation_execution_identity", {}),
        runner.get("execution_identity", {}),
    ]
    executed_manifest_value = runner.get("executed_manifest")
    if (
        runner.get("source_identity_bound") is True
        and isinstance(executed_manifest_value, str)
        and executed_manifest_value
    ):
        executed_manifest_path = Path(executed_manifest_value).expanduser()
        if executed_manifest_path.is_absolute() and executed_manifest_path.is_file():
            executed_manifest = read_json_if_exists(executed_manifest_path)
            execution_evidence = (
                executed_manifest.get("execution_evidence", {})
                if isinstance(executed_manifest.get("execution_evidence"), dict)
                else {}
            )
            bound_fields = (
                "source_identity_sha256",
                "source_closure_sha256",
                "vcs_compile_plan_sha256",
            )
            if all(
                re.fullmatch(
                    r"[0-9a-f]{64}",
                    str(executed_manifest.get(field) or ""),
                )
                and execution_evidence.get(field) == executed_manifest.get(field)
                for field in bound_fields
            ) and runner.get("vcs_compile_plan_sha256") == executed_manifest.get(
                "vcs_compile_plan_sha256"
            ):
                identities.append(simulation_execution_identity(executed_manifest))
    compiled_hashes: set[str] = set()
    for identity in identities:
        if not isinstance(identity, dict):
            continue
        compiled_model = (
            identity.get("compiled_model", {})
            if isinstance(identity.get("compiled_model"), dict)
            else {}
        )
        for row in compiled_model.get("source_rows", []):
            if isinstance(row, dict) and re.fullmatch(
                r"[0-9a-f]{64}",
                str(row.get("sha256") or ""),
            ):
                compiled_hashes.add(str(row["sha256"]))
    post_edit_hashes = {
        str(edit.get("after_sha256") or "")
        for edit in board_edits
        if isinstance(edit, dict) and edit.get("after_sha256")
    }
    return bool(post_edit_hashes) and post_edit_hashes.issubset(
        compiled_hashes
    )


def valid_persisted_exact_board_attempt(attempt: Any) -> bool:
    """Validate one compact negative experiment without consulting live files."""

    if not isinstance(attempt, dict):
        return False
    state = attempt.get("board_source_state", {})
    rows = state.get("rows", []) if isinstance(state, dict) else []
    edits = attempt.get("board_source_edits", [])
    behavior = attempt.get("behavior_signature", {})
    identity = attempt.get("runner_identity", {})
    if not (
        isinstance(rows, list)
        and rows
        and state.get("canonical_sha256") == canonical_contract_sha256(rows)
        and isinstance(edits, list)
        and edits
        and isinstance(behavior, dict)
        and behavior.get("canonical_sha256")
        == canonical_contract_sha256(
            {key: value for key, value in behavior.items() if key != "canonical_sha256"}
        )
        and isinstance(identity, dict)
        and re.fullmatch(
            r"[0-9a-f]{64}",
            str(identity.get("input_fingerprint_sha256") or ""),
        )
    ):
        return False
    state_hashes = {
        str(row.get("path") or ""): str(row.get("sha256") or "")
        for row in rows
        if isinstance(row, dict)
    }
    return all(
        isinstance(edit, dict)
        and edit.get("path")
        and edit.get("before_sha256")
        and edit.get("after_sha256")
        and state_hashes.get(str(edit["path"])) == edit.get("after_sha256")
        for edit in edits
    )


def current_exact_board_failed_attempt(
    run_dir: Path,
    feedback: dict[str, Any],
    *,
    patch_application: dict[str, Any],
    llm_record: dict[str, Any],
) -> dict[str, Any] | None:
    """Bind the current Agent edit to the real VCS response that consumed it."""

    def bound_value(name: str) -> dict[str, Any] | None:
        artifact = feedback.get(name, {})
        artifact = artifact if isinstance(artifact, dict) else {}
        path = Path(str(artifact.get("path") or ""))
        value = artifact.get("value", {})
        if not (
            path.is_file()
            and re.fullmatch(r"[0-9a-f]{64}", str(artifact.get("sha256") or ""))
            and sha256_file(path) == artifact.get("sha256")
            and isinstance(value, dict)
            and value
        ):
            return None
        return value

    runner = bound_value("runner_report")
    diagnosis = bound_value("diagnosis")
    output = llm_record.get("output", {})
    output = output if isinstance(output, dict) else {}
    if not (
        patch_application.get("status") == "pass"
        and patch_application.get("agent") == EXACT_BOARD_GENERATION_AGENT
        and isinstance(runner, dict)
        and runner.get("status") == "fail"
        and isinstance(diagnosis, dict)
        and diagnosis.get("status") in {"fail", "needs_repair"}
        and llm_record.get("agent") == EXACT_BOARD_GENERATION_AGENT
        and output.get("status") == "ready_to_apply"
    ):
        return None

    board_root = (run_dir / "generated" / "board_integration").resolve()
    board_edits: list[dict[str, Any]] = []
    for row in patch_application.get("files", []):
        if not isinstance(row, dict):
            continue
        path = Path(str(row.get("path") or "")).resolve()
        if (
            not path.is_relative_to(board_root)
            or path.suffix.lower() not in BOARD_INTEGRATION_SOURCE_SUFFIXES
        ):
            continue
        before = str(row.get("before_sha256") or "")
        after = str(row.get("after_sha256") or "")
        if not before or not after or before == after:
            continue
        board_edits.append(
            {
                "path": str(path.relative_to(run_dir.resolve())),
                "before_sha256": before,
                "after_sha256": after,
            }
        )
    if not board_edits or not _runner_binds_post_edit_board_sources(
        runner, board_edits
    ):
        return None

    state = exact_board_source_state(run_dir)
    state_hashes = {
        str(row.get("path") or ""): str(row.get("sha256") or "")
        for row in state.get("rows", [])
        if isinstance(row, dict)
    }
    if any(
        state_hashes.get(str(edit["path"])) != edit["after_sha256"]
        for edit in board_edits
    ):
        return None

    fingerprint = str(runner.get("input_fingerprint_sha256") or "")
    behavior = _board_repair_behavior_signature(diagnosis)
    attempt = {
        "iteration": f"recent:{fingerprint[:12]}",
        "board_source_state": state,
        "board_source_edits": board_edits,
        "agent_hypothesis": {
            "summary": output.get("summary"),
            "root_cause": output.get("root_cause"),
            "causal_prediction": copy.deepcopy(output.get("causal_prediction"))
            if isinstance(output.get("causal_prediction"), dict)
            else None,
        },
        "behavior_signature": behavior,
        "runner_identity": {
            "input_fingerprint_sha256": fingerprint,
            "preflight_manifest_projection_sha256": runner.get(
                "preflight_manifest_projection_sha256"
            ),
            "vcs_compile_plan_sha256": runner.get("vcs_compile_plan_sha256"),
        },
    }
    return attempt if valid_persisted_exact_board_attempt(attempt) else None


def persist_current_exact_board_failed_attempt(
    run_dir: Path,
    feedback: dict[str, Any],
    *,
    patch_application: dict[str, Any],
    llm_record: dict[str, Any],
    limit: int = 8,
) -> dict[str, Any]:
    """Keep a bounded completed-experiment history across controller restarts."""

    attempt = current_exact_board_failed_attempt(
        run_dir,
        feedback,
        patch_application=patch_application,
        llm_record=llm_record,
    )
    if attempt is None:
        return {"status": "not_run"}
    path = (
        run_dir
        / "repair_execution"
        / "recent_exact_board_failed_attempts.json"
    )
    existing = read_json_if_exists(path)
    attempts = [
        copy.deepcopy(row)
        for row in existing.get("attempts", [])
        if valid_persisted_exact_board_attempt(row)
    ]
    identity = (
        attempt["board_source_state"]["canonical_sha256"],
        attempt["runner_identity"]["input_fingerprint_sha256"],
    )
    attempts = [
        row
        for row in attempts
        if (
            row["board_source_state"]["canonical_sha256"],
            row["runner_identity"]["input_fingerprint_sha256"],
        )
        != identity
    ]
    attempts.append(attempt)
    write_json(
        path,
        {
            "schema_version": "spatialaccagent.recent_exact_board_failed_attempts.v1",
            "attempts": attempts[-limit:],
        },
    )
    return {"status": "pass", "path": str(path)}


def _evaluate_causal_prediction(
    prediction: dict[str, Any] | None,
    *,
    baseline_metrics: dict[str, int | float],
    response_metrics: dict[str, int | float],
) -> dict[str, Any]:
    """Evaluate an agent prediction only against its bound real-tool response."""

    if not isinstance(prediction, dict):
        return {"status": "not_declared", "checks": []}
    changes = prediction.get("expected_progress_changes", [])
    if not isinstance(changes, list) or not changes:
        return {"status": "inconclusive", "checks": []}

    checks: list[dict[str, Any]] = []
    baseline_relations = {
        "increase_from_baseline",
        "decrease_from_baseline",
        "change_from_baseline",
        "no_change_from_baseline",
    }
    bound_relations = {"reach_at_least", "reach_at_most"}
    for expected in changes:
        if not isinstance(expected, dict):
            checks.append({"status": "unavailable", "reason": "invalid_prediction_row"})
            continue
        metric = str(expected.get("metric") or "")
        relation = str(expected.get("relation") or "")
        threshold = expected.get("value")
        check: dict[str, Any] = {
            "metric": metric,
            "relation": relation,
            "expected_value": threshold,
            "baseline_value": baseline_metrics.get(metric),
            "observed_value": response_metrics.get(metric),
        }
        if metric not in response_metrics:
            check.update(status="unavailable", reason="response_metric_absent")
        elif relation in baseline_relations and metric not in baseline_metrics:
            check.update(status="unavailable", reason="exact_baseline_metric_absent")
        elif relation in bound_relations and (
            not isinstance(threshold, (int, float)) or isinstance(threshold, bool)
        ):
            check.update(status="unavailable", reason="numeric_bound_absent")
        else:
            observed = response_metrics[metric]
            baseline = baseline_metrics.get(metric)
            if relation == "increase_from_baseline":
                supported = observed > baseline
            elif relation == "decrease_from_baseline":
                supported = observed < baseline
            elif relation == "change_from_baseline":
                supported = observed != baseline
            elif relation == "no_change_from_baseline":
                supported = observed == baseline
            elif relation == "reach_at_least":
                supported = observed >= threshold
            elif relation == "reach_at_most":
                supported = observed <= threshold
            else:
                check.update(status="unavailable", reason="unsupported_relation")
                checks.append(check)
                continue
            check["status"] = "supported" if supported else "falsified"
        checks.append(check)

    statuses = {str(row.get("status")) for row in checks}
    if "falsified" in statuses:
        status = "falsified"
    elif checks and statuses == {"supported"}:
        status = "supported"
    else:
        status = "inconclusive"
    return {
        "status": status,
        "target_frontier_id": prediction.get("target_frontier_id"),
        "falsified_if": prediction.get("falsified_if"),
        "checks": checks,
        "policy": {
            "evaluation_uses_same_state_real_tool_response": True,
            "prediction_support_is_not_root_cause_proof": True,
        },
    }


def _frontier_response_summary(
    transitions: list[dict[str, Any]],
) -> dict[str, Any]:
    """Expose response trajectories and repeated plateaus without prompt-side joins."""

    metric_order = sorted(
        {
            metric
            for transition in transitions
            for metric in transition.get("observed_response", {}).get(
                "frontier_response_metrics", {}
            )
        }
    )
    response_series: list[dict[str, Any]] = []
    clusters: dict[str, dict[str, Any]] = {}
    for transition in transitions:
        observed = transition.get("observed_response", {})
        metrics = observed.get("frontier_response_metrics", {})
        signature_projection = {
            "frontier_id": observed.get("frontier_id"),
            "metrics": metrics,
        }
        signature_sha256 = canonical_contract_sha256(signature_projection)
        hypothesis = transition.get("agent_hypothesis", {})
        prediction = (
            hypothesis.get("causal_prediction", {})
            if isinstance(hypothesis, dict)
            and isinstance(hypothesis.get("causal_prediction"), dict)
            else {}
        )
        row = {
            "intervention_iteration": transition.get("intervention_iteration"),
            "frontier_id": observed.get("frontier_id"),
            "candidate_board_state_sha256": transition.get(
                "candidate_board_state_sha256"
            ),
            "intervention_family": prediction.get("intervention_family"),
            "metric_values": [metrics.get(metric) for metric in metric_order],
            "response_signature_sha256": signature_sha256,
        }
        response_series.append(row)
        cluster = clusters.setdefault(
            signature_sha256,
            {
                "response_signature_sha256": signature_sha256,
                "frontier_id": observed.get("frontier_id"),
                "iterations": [],
                "candidate_board_state_sha256": [],
                "intervention_labels": [],
            },
        )
        cluster["iterations"].append(transition.get("intervention_iteration"))
        cluster["candidate_board_state_sha256"].append(
            transition.get("candidate_board_state_sha256")
        )
        label = prediction.get("intervention_family") or (
            hypothesis.get("summary") if isinstance(hypothesis, dict) else None
        )
        cluster["intervention_labels"].append(label)

    varying_metric_series = []
    for metric_index, metric in enumerate(metric_order):
        values = [row["metric_values"][metric_index] for row in response_series]
        if len({json.dumps(value, sort_keys=True) for value in values}) <= 1:
            continue
        varying_metric_series.append(
            {
                "metric": metric,
                "values": [
                    {
                        "iteration": row.get("intervention_iteration"),
                        "value": row["metric_values"][metric_index],
                    }
                    for row in response_series
                ],
            }
        )

    plateau_clusters = []
    for cluster in clusters.values():
        distinct_states = {
            value
            for value in cluster["candidate_board_state_sha256"]
            if value
        }
        if len(cluster["iterations"]) < 2 or len(distinct_states) < 2:
            continue
        cluster["distinct_candidate_board_state_count"] = len(distinct_states)
        plateau_clusters.append(cluster)

    latest_signature = (
        response_series[-1].get("response_signature_sha256")
        if response_series
        else None
    )
    latest_prior_matches = [
        row.get("intervention_iteration")
        for row in response_series[:-1]
        if row.get("response_signature_sha256") == latest_signature
    ]
    return {
        "schema_version": "spatialaccagent.cctg_frontier_response_summary.v1",
        "status": "ready" if response_series else "empty",
        "metric_order": metric_order,
        "response_series": response_series,
        "varying_metric_series": varying_metric_series,
        "repeated_response_plateaus": plateau_clusters,
        "latest_response_repeats_prior_plateau": bool(latest_prior_matches),
        "latest_matching_prior_iterations": latest_prior_matches,
        "policy": {
            "response_signature_excludes_transient_signal_levels": True,
            "plateau_requires_distinct_exact_board_source_states": True,
            "plateau_is_negative_experimental_evidence_not_root_cause_proof": True,
        },
    }


def _board_source_hash_map(attempt: dict[str, Any]) -> dict[str, str]:
    state = (
        attempt.get("board_source_state", {})
        if isinstance(attempt.get("board_source_state"), dict)
        else {}
    )
    rows = state.get("rows", []) if isinstance(state.get("rows"), list) else []
    return {
        str(row.get("path")): str(row.get("sha256"))
        for row in rows
        if isinstance(row, dict) and row.get("path") and row.get("sha256")
    }


def _intervention_baseline_board_source_hash_map(
    attempt: dict[str, Any],
) -> dict[str, str] | None:
    hashes = _board_source_hash_map(attempt)
    edits = (
        attempt.get("board_source_edits", [])
        if isinstance(attempt.get("board_source_edits"), list)
        else []
    )
    if not hashes or not edits:
        return None
    for edit in edits:
        if not isinstance(edit, dict):
            return None
        path = str(edit.get("path") or "")
        before = str(edit.get("before_sha256") or "")
        after = str(edit.get("after_sha256") or "")
        if not path or not before or not after or hashes.get(path) != after:
            return None
        hashes[path] = before
    return hashes


def _exact_board_intervention_response_history(
    attempts: list[dict[str, Any]],
    *,
    limit: int,
) -> dict[str, Any]:
    """Bind each applied agent edit to its same-state real-tool response."""

    transitions: list[dict[str, Any]] = []
    for index, intervention in enumerate(attempts):
        baseline_hashes = _intervention_baseline_board_source_hash_map(intervention)
        response_hashes = _board_source_hash_map(intervention)
        if baseline_hashes is None or not response_hashes:
            continue
        baseline = next(
            (
                candidate
                for candidate in reversed(attempts[:index])
                if _board_source_hash_map(candidate) == baseline_hashes
            ),
            None,
        )
        baseline_metrics = (
            _numeric_causal_progress_metrics(baseline) if baseline is not None else {}
        )
        response_metrics = _numeric_causal_progress_metrics(intervention)
        baseline_frontier_metrics = (
            _frontier_response_metrics(baseline) if baseline is not None else {}
        )
        response_frontier_metrics = _frontier_response_metrics(intervention)
        deltas = {
            key: response_metrics[key] - baseline_metrics[key]
            for key in sorted(baseline_metrics.keys() & response_metrics.keys())
            if response_metrics[key] != baseline_metrics[key]
        }
        baseline_rows = [
            {"path": path, "sha256": digest}
            for path, digest in sorted(baseline_hashes.items())
        ]
        response_rows = [
            {"path": path, "sha256": digest}
            for path, digest in sorted(response_hashes.items())
        ]
        response_state = intervention.get("board_source_state", {})
        response_behavior = (
            intervention.get("behavior_signature", {})
            if isinstance(intervention.get("behavior_signature"), dict)
            else {}
        )
        baseline_behavior = (
            baseline.get("behavior_signature", {})
            if isinstance(baseline, dict)
            else {}
        )
        transition = {
            "status": "completed_real_tool_response",
            "intervention_iteration": intervention.get("iteration"),
            "baseline_iteration": baseline.get("iteration") if baseline else None,
            "response_iteration": intervention.get("iteration"),
            "source_board_state_sha256": canonical_contract_sha256(baseline_rows),
            "candidate_board_state_sha256": (
                response_state.get("canonical_sha256")
                if isinstance(response_state, dict)
                else None
            )
            or canonical_contract_sha256(response_rows),
            "board_source_edits": copy.deepcopy(
                intervention.get("board_source_edits", [])
            ),
            "agent_hypothesis": copy.deepcopy(
                intervention.get("agent_hypothesis", {})
            ),
            "baseline_response": (
                {
                    "behavior_signature_sha256": baseline_behavior.get(
                        "canonical_sha256"
                    ),
                    "frontier_id": baseline_behavior.get(
                        "sacg_cctg_frontier_id"
                    ),
                    "numeric_progress_metrics": baseline_metrics,
                    "frontier_response_metrics": baseline_frontier_metrics,
                }
                if baseline is not None
                else None
            ),
            "observed_response": {
                "behavior_signature_sha256": response_behavior.get(
                    "canonical_sha256"
                ),
                "failure_class": response_behavior.get("failure_class"),
                "first_real_error": response_behavior.get("first_real_error"),
                "frontier_id": response_behavior.get("sacg_cctg_frontier_id"),
                "zero_time_livelock": copy.deepcopy(
                    response_behavior.get("zero_time_livelock", {})
                ),
                "numeric_progress_metrics": response_metrics,
                "frontier_response_metrics": response_frontier_metrics,
                "nonzero_numeric_deltas_from_baseline": deltas,
            },
            "causal_prediction_evaluation": _evaluate_causal_prediction(
                intervention.get("agent_hypothesis", {}).get(
                    "causal_prediction"
                )
                if isinstance(intervention.get("agent_hypothesis"), dict)
                else None,
                baseline_metrics=baseline_frontier_metrics,
                response_metrics=response_frontier_metrics,
            ),
        }
        transition["canonical_sha256"] = canonical_contract_sha256(transition)
        transitions.append(transition)

    compact = transitions[-limit:]
    return {
        "schema_version": "spatialaccagent.exact_board_intervention_response_history.v2",
        "status": "ready" if compact else "empty",
        "transitions": compact,
        "frontier_response_summary": _frontier_response_summary(compact),
        "policy": {
            "response_is_bound_by_exact_post_edit_board_source_state": True,
            "absolute_progress_is_preserved_alongside_nonzero_deltas": True,
            "unarchived_or_hash_inconsistent_interventions_are_excluded": True,
            "monotonic_response_is_causal_evidence_not_root_cause_proof": True,
            "baseline_delta_requires_an_exact_pre_edit_source_state_match": True,
        },
    }


def exact_board_repair_attempt_records(run_dir: Path) -> list[dict[str, Any]]:
    """Return hash-bound completed exact-board experiments and source states."""

    tracked_state: dict[str, str] = {}
    attempts: list[dict[str, Any]] = []
    loop_dir = run_dir / "repair_execution" / "loop"
    for record_path in sorted(loop_dir.glob("iteration_*/iteration_record.json")):
        record = read_json_if_exists(record_path)
        recorded_state = record.get("board_source_state")
        recorded_rows = (
            recorded_state.get("rows", [])
            if isinstance(recorded_state, dict)
            and isinstance(recorded_state.get("rows"), list)
            else []
        )
        complete_recorded_state = bool(
            isinstance(recorded_state, dict)
            and recorded_state.get("schema_version")
            == "spatialaccagent.exact_board_source_state.v1"
            and recorded_rows
            and not recorded_state.get("legacy_tracked_sources_only")
            and recorded_state.get("canonical_sha256")
            == canonical_contract_sha256(recorded_rows)
        )
        patch_artifact = _bound_repair_iteration_snapshot(
            record,
            role="agent_patch_application",
        )
        patch_report = (
            patch_artifact["value"] if patch_artifact is not None else {}
        )
        board_edits = []
        if patch_report.get("status") == "pass":
            for row in patch_report.get("files", []):
                if not isinstance(row, dict):
                    continue
                path = Path(str(row.get("path") or "")).resolve()
                board_root = (
                    run_dir / "generated" / "board_integration"
                ).resolve()
                if (
                    not path.is_relative_to(board_root)
                    or path.suffix.lower()
                    not in BOARD_INTEGRATION_SOURCE_SUFFIXES
                ):
                    continue
                relative = str(path.relative_to(run_dir.resolve()))
                before = str(row.get("before_sha256") or "")
                after = str(row.get("after_sha256") or "")
                if before and relative not in tracked_state:
                    tracked_state[relative] = before
                if after:
                    tracked_state[relative] = after
                board_edits.append(
                    {
                        "path": relative,
                        "before_sha256": before or None,
                        "after_sha256": after or None,
                    }
                )
        if not complete_recorded_state:
            if not board_edits:
                continue
            recorded_state = {
                "schema_version": "spatialaccagent.exact_board_source_state.v1",
                "rows": [
                    {"path": path, "sha256": digest}
                    for path, digest in sorted(tracked_state.items())
                ],
                "canonical_sha256": canonical_contract_sha256(
                    [
                        {"path": path, "sha256": digest}
                        for path, digest in sorted(tracked_state.items())
                    ]
                ),
                "legacy_tracked_sources_only": True,
            }

        runner_artifact = _bound_repair_iteration_snapshot(
            record,
            role="capability_report",
            marker="case_board_vcs_functional",
        )
        diagnosis_artifact = _bound_repair_iteration_snapshot(
            record,
            role="capability_report",
            marker="vcs_functional_diagnosis",
        )
        if runner_artifact is None or diagnosis_artifact is None:
            continue
        runner = runner_artifact["value"]
        diagnosis = diagnosis_artifact["value"]
        if not _runner_binds_post_edit_board_sources(runner, board_edits):
            continue
        if (
            runner.get("status") == "pass"
            or diagnosis.get("status") not in {"fail", "needs_repair"}
        ):
            continue
        repair_handoff = diagnosis.get("repair_handoff", {})
        repair_handoff = (
            repair_handoff if isinstance(repair_handoff, dict) else {}
        )
        repair_scope = diagnosis.get("repair_scope") or repair_handoff.get(
            "repair_scope"
        )
        # A non-semantic result is useful only after the analyzer has
        # classified it as a simulation-environment experiment.  Raw
        # transport failures have no causal result for a future Agent.
        if (
            repair_handoff.get("agent_should_apply_code_changes") is not True
            and repair_scope != "simulation_environment"
        ):
            continue
        llm_artifact = _bound_repair_iteration_snapshot(record, role="llm_record")
        llm_output = (
            llm_artifact.get("value", {}).get("output", {})
            if llm_artifact is not None
            else {}
        )
        behavior = _board_repair_behavior_signature(diagnosis)
        attempts.append(
            {
                "iteration": record.get("iteration"),
                "iteration_record": {
                    "path": str(record_path),
                    "sha256": sha256_file(record_path),
                    "iteration": record.get("iteration"),
                },
                "board_source_state": copy.deepcopy(recorded_state),
                "board_source_edits": board_edits,
                "agent_hypothesis": {
                    "summary": llm_output.get("summary"),
                    "root_cause": llm_output.get("root_cause"),
                    "checkpoint_impact": copy.deepcopy(
                        llm_output.get("checkpoint_impact")
                    )
                    if isinstance(llm_output.get("checkpoint_impact"), dict)
                    else None,
                    "causal_prediction": copy.deepcopy(
                        llm_output.get("causal_prediction")
                    )
                    if isinstance(llm_output.get("causal_prediction"), dict)
                    else None,
                },
                "behavior_signature": behavior,
                "runner_identity": {
                    "runner_implementation_sha256": runner.get(
                        "runner_implementation_sha256"
                    ),
                    "input_fingerprint_sha256": runner.get(
                        "input_fingerprint_sha256"
                    ),
                    "preflight_manifest_projection_sha256": runner.get(
                        "preflight_manifest_projection_sha256"
                    ),
                    "vcs_compile_plan_sha256": runner.get(
                        "vcs_compile_plan_sha256"
                    ),
                },
                "runner_report": runner_artifact,
                "diagnosis": diagnosis_artifact,
            }
        )
    recent = read_json_if_exists(
        run_dir
        / "repair_execution"
        / "recent_exact_board_failed_attempts.json"
    )
    if (
        recent.get("schema_version")
        == "spatialaccagent.recent_exact_board_failed_attempts.v1"
        and isinstance(recent.get("attempts"), list)
    ):
        known = {
            (
                str(row.get("board_source_state", {}).get("canonical_sha256") or ""),
                str(row.get("runner_identity", {}).get("input_fingerprint_sha256") or ""),
            )
            for row in attempts
            if isinstance(row, dict)
        }
        for row in recent["attempts"]:
            if not valid_persisted_exact_board_attempt(row):
                continue
            identity = (
                str(row["board_source_state"].get("canonical_sha256") or ""),
                str(row["runner_identity"].get("input_fingerprint_sha256") or ""),
            )
            if identity not in known:
                attempts.append(copy.deepcopy(row))
                known.add(identity)
    return attempts


def exact_board_repair_attempt_history(
    run_dir: Path,
    *,
    limit: int = 8,
) -> dict[str, Any]:
    attempts = exact_board_repair_attempt_records(run_dir)
    compact_attempts = []
    for row in attempts[-limit:]:
        compact_attempts.append(
            {
                key: copy.deepcopy(value)
                for key, value in row.items()
                if key not in {"runner_report", "diagnosis"}
            }
        )
    return {
        "schema_version": "spatialaccagent.exact_board_repair_attempt_history.v2",
        "status": "ready" if compact_attempts else "empty",
        "attempts": compact_attempts,
        "intervention_response_history": _exact_board_intervention_response_history(
            attempts,
            limit=limit,
        ),
        "policy": {
            "records_are_hash_bound_same_iteration_source_state_runner_diagnosis": True,
            "validation_only_resume_iterations_are_preserved": True,
            "execution_environment_failures_remain_non_semantic_evidence": True,
            "failed_source_states_are_negative_evidence_not_pass_evidence": True,
            "do_not_repeat_a_failed_source_state_or_semantically_equivalent_reversal": True,
        },
    }


def matching_failed_exact_board_attempt(
    run_dir: Path,
    source_state: dict[str, Any] | None = None,
) -> dict[str, Any] | None:
    current_state = source_state or exact_board_source_state(run_dir)
    current_hashes = {
        str(row.get("path")): str(row.get("sha256"))
        for row in current_state.get("rows", [])
        if isinstance(row, dict) and row.get("path") and row.get("sha256")
    }
    current_plan_sha256 = str(current_state.get("vcs_compile_plan_sha256") or "")
    if not current_plan_sha256:
        current_plan_sha256 = str(
            read_json_if_exists(
                run_dir / "generated" / "memory" / "dut_weight_binding_manifest.json"
            ).get("board_simulation_preflight_plan", {}).get(
                "vcs_compile_plan_sha256"
            )
            or ""
        )
    for attempt in reversed(exact_board_repair_attempt_records(run_dir)):
        state = attempt.get("board_source_state", {})
        rows = state.get("rows", []) if isinstance(state, dict) else []
        expected = {
            str(row.get("path")): str(row.get("sha256"))
            for row in rows
            if isinstance(row, dict) and row.get("path") and row.get("sha256")
        }
        if state.get("legacy_tracked_sources_only"):
            candidate_changed_paths = current_state.get(
                "candidate_changed_paths", []
            )
            # Legacy iteration records contain only paths touched up to that
            # iteration, not a complete board-source state.  They can reject
            # an exact candidate reversal while the candidate's changed paths
            # are known, but cannot attest a live state during process resume.
            if not candidate_changed_paths or any(
                path not in expected for path in candidate_changed_paths
            ):
                continue
        if not expected or any(current_hashes.get(path) != digest for path, digest in expected.items()):
            continue
        attempt_plan = str(
            attempt.get("runner_identity", {}).get("vcs_compile_plan_sha256") or ""
        )
        if current_plan_sha256 and attempt_plan and current_plan_sha256 != attempt_plan:
            continue
        return attempt
    return None


def matching_failed_exact_board_functional_state(
    run_dir: Path,
    source_state: dict[str, Any],
) -> dict[str, Any] | None:
    """Match a failed functional state even when only observation sources differ."""

    run_dir = run_dir.resolve()
    ignored_paths: set[str] = set()
    for path in _board_observation_only_edit_paths(run_dir):
        try:
            ignored_paths.add(str(path.resolve().relative_to(run_dir)))
        except ValueError:
            continue
    changed_paths = {
        str(value) for value in source_state.get("candidate_changed_paths", [])
    }
    functional_changed_paths = changed_paths - ignored_paths
    if not functional_changed_paths:
        return None

    candidate_hashes = {
        str(row.get("path")): str(row.get("sha256"))
        for row in source_state.get("rows", [])
        if isinstance(row, dict)
        and row.get("path")
        and row.get("sha256")
        and str(row.get("path")) not in ignored_paths
    }
    if not candidate_hashes:
        return None
    for attempt in reversed(exact_board_repair_attempt_records(run_dir)):
        prior_hashes = {
            str(row.get("path")): str(row.get("sha256"))
            for row in attempt.get("board_source_state", {}).get("rows", [])
            if isinstance(row, dict)
            and row.get("path")
            and row.get("sha256")
            and str(row.get("path")) not in ignored_paths
        }
        if prior_hashes and prior_hashes == candidate_hashes:
            return attempt
    return None


def frozen_failed_runner_matches_current_execution_semantics(
    feedback: dict[str, Any],
    manifest_path: Path,
) -> bool:
    """Match certified failed evidence while ignoring rolling audit links."""

    manifest = read_json_if_exists(manifest_path)
    attestation = (
        manifest.get("frozen_compute_slot_identity_attestation")
        if isinstance(manifest.get("frozen_compute_slot_identity_attestation"), dict)
        else {}
    )
    runner_artifact = (
        feedback.get("runner_report")
        if isinstance(feedback.get("runner_report"), dict)
        else {}
    )
    runner = (
        runner_artifact.get("value")
        if isinstance(runner_artifact.get("value"), dict)
        else {}
    )
    if (
        manifest.get("validation_mode") != EXACT_BOARD_FUNCTIONAL_VALIDATION_MODE
        or attestation.get("status") != "pass"
        or runner.get("status") == "pass"
        or runner.get("validation_mode") != EXACT_BOARD_FUNCTIONAL_VALIDATION_MODE
    ):
        return False

    certified: dict[str, tuple[Path, dict[str, Any]]] = {}
    for name in (
        "prior_executed_manifest",
        "prior_vcs_job_contract",
        "prior_vcs_runner_report",
    ):
        row = attestation.get(name) if isinstance(attestation.get(name), dict) else {}
        path = Path(str(row.get("path") or ""))
        expected_sha256 = str(row.get("sha256") or "")
        if (
            not path.is_file()
            or not expected_sha256
            or sha256_file(path) != expected_sha256
        ):
            return False
        certified[name] = (path, read_json_if_exists(path))

    runner_snapshot = certified["prior_vcs_runner_report"][1]
    executed_manifest = certified["prior_executed_manifest"][1]
    job_contract = certified["prior_vcs_job_contract"][1]
    runner_sha256 = str(
        attestation["prior_vcs_runner_report"].get("sha256") or ""
    )
    fingerprint = str(runner.get("input_fingerprint_sha256") or "")
    if (
        runner_artifact.get("sha256") != runner_sha256
        or runner_snapshot != runner
        or job_contract.get("input_fingerprint_sha256") != fingerprint
        or runner_snapshot.get("input_fingerprint_sha256") != fingerprint
        or executed_manifest.get("validation_mode")
        != EXACT_BOARD_FUNCTIONAL_VALIDATION_MODE
    ):
        return False
    return exact_board_repair_execution_projection_sha256(
        executed_manifest
    ) == exact_board_repair_execution_projection_sha256(manifest)


def archived_exact_board_vcs_feedback(
    run_dir: Path,
) -> list[dict[str, Any]]:
    feedback_rows: list[dict[str, Any]] = []
    loop_dir = run_dir / "repair_execution" / "loop"
    for record_path in sorted(
        loop_dir.glob("iteration_*/iteration_record.json"),
        reverse=True,
    ):
        record = read_json_if_exists(record_path)
        snapshots = (
            record.get("evidence_snapshots", [])
            if isinstance(record.get("evidence_snapshots"), list)
            else []
        )

        def matching_snapshot(marker: str) -> dict[str, Any] | None:
            for row in snapshots:
                if not isinstance(row, dict) or row.get("role") != "capability_report":
                    continue
                if marker in Path(str(row.get("snapshot_path") or "")).name:
                    return row
            return None

        runner_row = matching_snapshot("case_board_vcs_functional")
        diagnosis_row = matching_snapshot("vcs_functional_diagnosis")
        if runner_row is None or diagnosis_row is None:
            continue

        def bound_snapshot(row: dict[str, Any]) -> dict[str, Any] | None:
            path = Path(str(row.get("snapshot_path") or ""))
            expected_sha256 = str(row.get("source_sha256") or "")
            if (
                not path.is_file()
                or not expected_sha256
                or sha256_file(path) != expected_sha256
            ):
                return None
            value = read_json_if_exists(path)
            if not value:
                return None
            return {
                "path": str(path),
                "source_path": row.get("source_path"),
                "sha256": expected_sha256,
                "value": value,
            }

        runner_artifact = bound_snapshot(runner_row)
        diagnosis_artifact = bound_snapshot(diagnosis_row)
        if runner_artifact is None or diagnosis_artifact is None:
            continue
        feedback_rows.append(
            {
                "schema_version": "spatialaccagent.exact_board_vcs_feedback.v1",
                "status": "ready",
                "blockers": [],
                "runner_report": runner_artifact,
                "diagnosis": diagnosis_artifact,
                "source_iteration_record": {
                    "path": str(record_path),
                    "sha256": sha256_file(record_path),
                    "iteration": record.get("iteration"),
                },
            }
        )
    return feedback_rows


def failed_exact_board_attempt_feedback(
    run_dir: Path,
    failed_attempt: dict[str, Any] | None,
) -> dict[str, Any] | None:
    """Recover the full evidence for the current failed board source state.

    The bounded negative-history record intentionally stores only the source
    state and real-job identity.  Its runner and diagnosis stay in the durable
    post-patch probe so the history does not duplicate large VCS reports.  On a
    controller restart, reconnect the two through that existing exact job
    identity before considering mutable live report paths.
    """

    if not isinstance(failed_attempt, dict):
        return None

    runner_artifact = failed_attempt.get("runner_report")
    diagnosis_artifact = failed_attempt.get("diagnosis")
    if isinstance(runner_artifact, dict) and isinstance(diagnosis_artifact, dict):
        feedback = {
            "schema_version": "spatialaccagent.exact_board_vcs_feedback.v1",
            "status": "ready",
            "blockers": [],
            "runner_report": copy.deepcopy(runner_artifact),
            "diagnosis": copy.deepcopy(diagnosis_artifact),
            "source_iteration_record": copy.deepcopy(
                failed_attempt.get("iteration_record", {})
            ),
            "content_addressed_failed_source_state_match": True,
        }
        return feedback

    runner_identity = (
        failed_attempt.get("runner_identity", {})
        if isinstance(failed_attempt.get("runner_identity"), dict)
        else {}
    )
    expected_fingerprint = str(
        runner_identity.get("input_fingerprint_sha256") or ""
    )
    expected_compile_plan = str(
        runner_identity.get("vcs_compile_plan_sha256") or ""
    )
    if not re.fullmatch(r"[0-9a-f]{64}", expected_fingerprint):
        return None

    repair_dir = run_dir / "repair_execution"
    probe_paths = sorted(
        repair_dir.glob("*_verification_capability_probe_post_patch.json"),
        key=lambda path: path.stat().st_mtime_ns,
        reverse=True,
    )
    for probe_path in probe_paths:
        probe = read_json_if_exists(probe_path)
        feedback = probe.get("current_board_vcs_feedback", {})
        feedback = feedback if isinstance(feedback, dict) else {}
        runner = _feedback_artifact_value(feedback, "runner_report")
        if runner.get("input_fingerprint_sha256") != expected_fingerprint:
            continue
        observed_compile_plan = str(
            runner.get("vcs_compile_plan_sha256") or ""
        )
        if (
            expected_compile_plan
            and observed_compile_plan
            and observed_compile_plan != expected_compile_plan
        ):
            continue
        diagnosis = _feedback_artifact_value(feedback, "diagnosis")
        if (
            feedback.get("status") != "ready"
            or not runner
            or not diagnosis
        ):
            continue
        recovered = copy.deepcopy(feedback)
        recovered["source_iteration_record"] = copy.deepcopy(
            failed_attempt.get("iteration_record", {})
        )
        recovered["content_addressed_failed_source_state_match"] = True
        recovered["content_addressed_durable_snapshot"] = {
            "path": str(probe_path),
            "sha256": sha256_file(probe_path),
            "runner_input_fingerprint_sha256": expected_fingerprint,
        }
        return recovered
    return None


def current_exact_board_validation_evidence(
    case_adapter: dict[str, Any],
    run_dir: Path,
    vcs_spec: dict[str, Any] | None,
    analyzer_spec: dict[str, Any] | None,
    manifest_path: Path,
    *,
    content_addressed_failed_attempt: dict[str, Any] | None = None,
) -> dict[str, Any] | None:
    """Use only the latest live board VCS/analyzer result for Layer 3."""

    del content_addressed_failed_attempt
    feedback_candidates = [
        exact_board_vcs_feedback(
            case_adapter,
            run_dir,
            vcs_spec,
            analyzer_spec,
        )
    ]
    feedback: dict[str, Any] | None = None
    runner_is_current = False
    frozen_failed_runner_is_current = False
    failed_source_state_is_current = False
    durable_failed_source_snapshot_is_current = False
    for candidate in feedback_candidates:
        if candidate.get("status") != "ready":
            continue
        candidate_runner_is_current = exact_board_vcs_runner_feedback_is_current(
            candidate,
            vcs_spec,
            manifest_path,
        )
        candidate_frozen_failure_is_current = (
            not candidate_runner_is_current
            and frozen_failed_runner_matches_current_execution_semantics(
                candidate,
                manifest_path,
            )
        )
        candidate_failed_source_state_is_current = bool(
            candidate.get("content_addressed_failed_source_state_match")
        )
        candidate_durable_failed_source_snapshot_is_current = isinstance(
            candidate.get("content_addressed_durable_snapshot"), dict
        )
        if (
            candidate_runner_is_current
            or candidate_frozen_failure_is_current
            or candidate_failed_source_state_is_current
        ):
            feedback = candidate
            runner_is_current = candidate_runner_is_current
            frozen_failed_runner_is_current = candidate_frozen_failure_is_current
            failed_source_state_is_current = candidate_failed_source_state_is_current
            durable_failed_source_snapshot_is_current = (
                candidate_durable_failed_source_snapshot_is_current
            )
            break
    if feedback is None:
        return None
    runner_artifact = (
        feedback.get("runner_report")
        if isinstance(feedback.get("runner_report"), dict)
        else {}
    )
    diagnosis_artifact = (
        feedback.get("diagnosis")
        if isinstance(feedback.get("diagnosis"), dict)
        else {}
    )
    diagnosis = (
        diagnosis_artifact.get("value")
        if isinstance(diagnosis_artifact.get("value"), dict)
        else {}
    )
    repair_handoff = (
        diagnosis.get("repair_handoff")
        if isinstance(diagnosis.get("repair_handoff"), dict)
        else {}
    )
    diagnosis_status = str(diagnosis.get("status") or "")
    diagnosis_ready = str(diagnosis.get("diagnosis_status") or "") in {
        "pass",
        "ready",
    }
    runner_path = Path(str(runner_artifact.get("path") or ""))
    runner_source_path = Path(
        str(runner_artifact.get("source_path") or runner_artifact.get("path") or "")
    )
    diagnosis_path = Path(str(diagnosis_artifact.get("path") or ""))
    diagnosis_sources = {
        resolve_run_path(run_dir, value).resolve()
        for value in diagnosis.get("sources", [])
        if str(value)
    }
    if (
        not diagnosis_ready
        or diagnosis_status not in {"pass", "fail", "needs_repair"}
        or (diagnosis_status == "pass" and not runner_is_current)
        or (
            diagnosis_status != "pass"
            and repair_handoff.get("agent_should_apply_code_changes") is not True
            and not failed_source_state_is_current
        )
        or runner_source_path.resolve() not in diagnosis_sources
        or (
            not durable_failed_source_snapshot_is_current
            and (
                not runner_path.is_file()
                or not diagnosis_path.is_file()
                or diagnosis_path.stat().st_mtime_ns < runner_path.stat().st_mtime_ns
            )
        )
    ):
        return None
    passed = diagnosis_status == "pass"
    produced_reports = []
    for artifact in (runner_artifact, diagnosis_artifact):
        value = (
            artifact.get("value")
            if isinstance(artifact.get("value"), dict)
            else {}
        )
        produced_reports.append(
            {
                "path": artifact.get("path"),
                "schema_version": value.get("schema_version"),
                "status": value.get("status"),
                "summary": value.get("summary"),
                "blockers": (
                    value.get("blockers", [])
                    if isinstance(value.get("blockers"), list)
                    else []
                ),
            }
        )
    return {
        "status": "pass" if passed else "fail",
        "summary": (
            "reused current passing exact-board VCS/analyzer evidence"
            if passed
            else str(
                diagnosis.get("summary")
                or "current exact-board VCS/analyzer evidence requires repair"
            )
        ),
        "current_board_vcs_feedback": feedback,
        "produced_reports": produced_reports,
        "reused_current_real_tool_evidence": True,
        "real_tool_was_not_relaunched": True,
        "frozen_failed_runner_evidence_reused": frozen_failed_runner_is_current,
        "content_addressed_failed_source_evidence_reused": (
            failed_source_state_is_current
        ),
    }


def exact_board_probe_requires_agent_continuation(
    probe: dict[str, Any],
    *,
    completed_agent_experiment: bool = False,
) -> bool:
    """Identify a newly completed exact-board failure that still needs its agent turn."""

    feedback = (
        probe.get("current_board_vcs_feedback")
        if isinstance(probe.get("current_board_vcs_feedback"), dict)
        else {}
    )
    runner_artifact = (
        feedback.get("runner_report")
        if isinstance(feedback.get("runner_report"), dict)
        else {}
    )
    diagnosis_artifact = (
        feedback.get("diagnosis")
        if isinstance(feedback.get("diagnosis"), dict)
        else {}
    )
    runner = (
        runner_artifact.get("value")
        if isinstance(runner_artifact.get("value"), dict)
        else {}
    )
    diagnosis = (
        diagnosis_artifact.get("value")
        if isinstance(diagnosis_artifact.get("value"), dict)
        else {}
    )
    repair_handoff = (
        diagnosis.get("repair_handoff")
        if isinstance(diagnosis.get("repair_handoff"), dict)
        else {}
    )
    return bool(
        probe.get("status") != "pass"
        and feedback.get("status") == "ready"
        and runner.get("status") != "pass"
        and diagnosis.get("status") in {"fail", "needs_repair"}
        and (
            repair_handoff.get("agent_should_apply_code_changes") is True
            or completed_agent_experiment
        )
    )


def exact_board_probe_agent_handoff_identity(
    probe: dict[str, Any],
    *,
    completed_agent_experiment: bool = False,
) -> str | None:
    """Return a stable identity for one actionable real-tool failure handoff."""

    if not exact_board_probe_requires_agent_continuation(
        probe,
        completed_agent_experiment=completed_agent_experiment,
    ):
        return None
    feedback = (
        probe.get("current_board_vcs_feedback")
        if isinstance(probe.get("current_board_vcs_feedback"), dict)
        else {}
    )
    runner_artifact = (
        feedback.get("runner_report")
        if isinstance(feedback.get("runner_report"), dict)
        else {}
    )
    diagnosis_artifact = (
        feedback.get("diagnosis")
        if isinstance(feedback.get("diagnosis"), dict)
        else {}
    )
    runner = (
        runner_artifact.get("value")
        if isinstance(runner_artifact.get("value"), dict)
        else {}
    )
    diagnosis = (
        diagnosis_artifact.get("value")
        if isinstance(diagnosis_artifact.get("value"), dict)
        else {}
    )
    runtime_failure = (
        runner.get("checkpoint_runtime_execution_failure")
        if isinstance(runner.get("checkpoint_runtime_execution_failure"), dict)
        else {}
    )
    checkpoint_identity = str(
        runtime_failure.get("failure_identity_sha256") or ""
    )
    run_result = runner.get("run") if isinstance(runner.get("run"), dict) else {}
    termination_provenance = (
        run_result.get("termination_provenance")
        if isinstance(run_result.get("termination_provenance"), dict)
        else {}
    )
    causal_classification = (
        termination_provenance.get("causal_classification")
        if isinstance(termination_provenance.get("causal_classification"), dict)
        else {}
    )
    runner_process_provenance = (
        termination_provenance.get("runner_process_provenance")
        if isinstance(termination_provenance.get("runner_process_provenance"), dict)
        else {}
    )
    process_snapshot = (
        runner_process_provenance.get("last_running_process_snapshot")
        if isinstance(
            runner_process_provenance.get("last_running_process_snapshot"), dict
        )
        else {}
    )
    simulator_commands = sorted(
        {
            str(value)
            for value in runner_process_provenance.get(
                "last_simulator_process_commands", []
            )
            if str(value)
        }
    )
    repair_handoff = (
        diagnosis.get("repair_handoff")
        if isinstance(diagnosis.get("repair_handoff"), dict)
        else {}
    )
    projection = {
        "schema_version": "spatialaccagent.exact_board_agent_handoff_identity.v1",
        "runner": {
            "status": runner.get("status"),
            "phase": runner.get("phase"),
            "input_fingerprint_sha256": runner.get("input_fingerprint_sha256"),
            "failure_class": run_result.get("failure_class"),
            "termination_provenance": {
                "classification": causal_classification.get("classification"),
                "termination_source": termination_provenance.get(
                    "termination_source"
                ),
                "runner_failure_class": termination_provenance.get(
                    "runner_failure_class"
                ),
                "runner_process_observation": {
                    "status": runner_process_provenance.get("status"),
                    "attribution": runner_process_provenance.get("attribution"),
                    "simulator_like_process_observed": bool(
                        process_snapshot.get("simulator_like_process_observed")
                        or simulator_commands
                    ),
                    "last_simulator_process_commands": simulator_commands,
                },
            },
        },
        "diagnosis": {
            "status": diagnosis.get("status"),
            "summary": diagnosis.get("summary"),
            "failure_class": diagnosis.get("failure_class"),
            "debug_layer": repair_handoff.get("debug_layer"),
            "handoff_failure_class": repair_handoff.get("failure_class"),
        },
        "checkpoint_failure_identity_sha256": checkpoint_identity or None,
    }
    return canonical_contract_sha256(projection)


def _completed_single_layer_pipeline_failure_evidence(
    report: dict[str, Any],
) -> dict[str, Any] | None:
    """Accept only a complete, persisted real-VCS overlap-contract failure."""

    stats = report.get("stats") if isinstance(report.get("stats"), dict) else {}
    run = stats.get("run") if isinstance(stats.get("run"), dict) else {}
    overlap = (
        report.get("pipeline_overlap_evidence")
        if isinstance(report.get("pipeline_overlap_evidence"), dict)
        else {}
    )
    terminal = (
        overlap.get("terminal_trace_flush_evidence")
        if isinstance(overlap.get("terminal_trace_flush_evidence"), dict)
        else {}
    )
    checks = terminal.get("checks") if isinstance(terminal.get("checks"), dict) else {}
    persistence = (
        stats.get("remote_artifact_persistence")
        if isinstance(stats.get("remote_artifact_persistence"), dict)
        else {}
    )
    real_weight = (
        report.get("real_weight_execution")
        if isinstance(report.get("real_weight_execution"), dict)
        else {}
    )
    fingerprint = str(stats.get("input_fingerprint_sha256") or "")
    contract_sha = str(overlap.get("contract_sha256") or "")
    trace_sha = str(overlap.get("trace_sha256") or "")
    required_positions = terminal.get("required_trace_position_count")
    observed_positions = terminal.get("observed_required_trace_position_count")
    actual_output_lines = terminal.get("actual_output_line_count")
    expected_output_lines = terminal.get("expected_output_line_count")
    overlap_schema = str(overlap.get("schema_version") or "")
    rate_insensitive = (
        overlap_schema
        == "spatialaccagent.single_layer_pipeline_overlap_evidence.v3"
        and overlap.get("pipeline_semantics")
        == "elastic_rate_insensitive_token_pipeline"
    )
    required_true_checks = {
        "all_required_trace_records_are_accepted",
        "execution_status_pass",
        "output_line_count_matches",
        "remote_exit_status_pass",
        "required_boundaries_are_valid",
        "single_matching_sim_pass_declaration",
        "trace_positions_are_unique_and_well_formed",
    }
    reuse = (
        stats.get("remote_job_reuse")
        if isinstance(stats.get("remote_job_reuse"), dict)
        else {}
    )
    reused_job_identity_valid = True
    if reuse.get("real_tool_was_not_relaunched") is True:
        expected_job_sha = str(reuse.get("expected_job_contract_sha256") or "")
        actual_job_sha = str(reuse.get("remote_job_contract_sha256") or "")
        reused_job_identity_valid = bool(
            reuse.get("status") == "pass"
            and re.fullmatch(r"[0-9a-f]{64}", expected_job_sha)
            and expected_job_sha == actual_job_sha
        )
    if (
        stats.get("status") != "pass"
        or run.get("status") != "pass"
        or run.get("returncode") != 0
        or run.get("remote_state") != "done"
        or persistence.get("status") != "pass"
        or real_weight.get("verified") is not True
        or overlap_schema
        not in {
            "spatialaccagent.single_layer_pipeline_overlap_evidence.v2",
            "spatialaccagent.single_layer_pipeline_overlap_evidence.v3",
        }
        or (
            overlap_schema
            == "spatialaccagent.single_layer_pipeline_overlap_evidence.v3"
            and not rate_insensitive
        )
        or overlap.get("status") != "fail"
        or not re.fullmatch(r"[0-9a-f]{64}", fingerprint)
        or not re.fullmatch(r"[0-9a-f]{64}", contract_sha)
        or not re.fullmatch(r"[0-9a-f]{64}", trace_sha)
        or any(checks.get(name) is not True for name in required_true_checks)
        or checks.get("only_terminal_block_output_trace_is_missing") is not False
        or terminal.get("inferred") is not False
        or overlap.get("terminal_trace_flush_inferred") is not False
        or not isinstance(required_positions, int)
        or required_positions <= 0
        or observed_positions != required_positions
        or overlap.get("accepted_trace_record_count") != required_positions
        or overlap.get("trace_record_count") != required_positions
        or not isinstance(expected_output_lines, int)
        or expected_output_lines <= 0
        or actual_output_lines != expected_output_lines
        or any(
            terminal.get(name) != 0
            for name in (
                "duplicate_required_trace_position_count",
                "malformed_required_trace_position_count",
                "missing_required_trace_position_count",
                "unexpected_required_trace_position_count",
                "unparsed_pipeline_trace_line_count",
            )
        )
        or len(terminal.get("sim_pass_declarations", [])) != 1
        or terminal.get("sim_pass_declarations", [{}])[0].get("beats")
        != expected_output_lines
        or not reused_job_identity_valid
    ):
        return None

    failed_turnover: list[dict[str, Any]] = []
    for row in overlap.get("stage_turnover_evidence", []):
        if rate_insensitive:
            continue
        if not isinstance(row, dict) or row.get("keeps_pipeline_filled") is not False:
            continue
        if (
            not row.get("stage_id")
            or row.get("overlapped") is not False
            or not isinstance(row.get("prior_token"), int)
            or not isinstance(row.get("next_token"), int)
            or not isinstance(row.get("gap_cycles"), int)
            or not isinstance(row.get("prior_token_active_end_cycle"), int)
            or not isinstance(row.get("next_token_active_start_cycle"), int)
        ):
            return None
        failed_turnover.append(copy.deepcopy(row))

    failed_dependencies: list[dict[str, Any]] = []
    for row in overlap.get("dependency_overlap_evidence", []):
        if (
            not isinstance(row, dict)
            or row.get("different_token_overlap_observed") is not False
        ):
            continue
        if rate_insensitive and row.get("required_for_acceptance") is not True:
            continue
        if (
            not row.get("boundary_id")
            or not row.get("src_stage")
            or not row.get("dst_stage")
            or not isinstance(row.get("overlaps"), list)
        ):
            return None
        failed_dependencies.append(copy.deepcopy(row))

    failed_boundary_order = [
        copy.deepcopy(row)
        for row in overlap.get("boundary_order_evidence", [])
        if isinstance(row, dict)
        and row.get("complete") is True
        and (
            row.get("token_first_transfer_order_preserved") is not True
            or row.get("token_last_transfer_order_preserved") is not True
        )
    ]

    barrier_rows = [
        copy.deepcopy(row)
        for row in overlap.get("whole_sequence_barrier_evidence", [])
        if isinstance(row, dict)
        and row.get("whole_sequence_barrier_observed") is True
        and row.get("stage_id")
    ]
    candidate_stage_set = {
        str(row["stage_id"])
        for row in [*failed_turnover, *barrier_rows]
    }
    candidate_stage_set.update(
        str(row[key])
        for row in failed_dependencies
        for key in ("src_stage", "dst_stage")
    )
    candidate_stage_set.update(
        str(row.get(key))
        for row in failed_boundary_order
        for key in ("src_stage", "dst_stage")
        if str(row.get(key) or "") not in {"", "block_input", "block_output"}
    )
    if not candidate_stage_set or not isinstance(overlap.get("blockers"), list):
        return None
    activity_order = [
        str(row.get("stage_id"))
        for row in overlap.get("stage_activity_evidence", [])
        if isinstance(row, dict) and str(row.get("stage_id") or "") in candidate_stage_set
    ]
    candidate_stage_ids = list(dict.fromkeys(activity_order))
    candidate_stage_ids.extend(
        sorted(candidate_stage_set - set(candidate_stage_ids))
    )
    return {
        "input_fingerprint_sha256": fingerprint,
        "pipeline_contract_sha256": contract_sha,
        "pipeline_trace_sha256": trace_sha,
        "pipeline_evidence_schema": overlap_schema,
        "pipeline_semantics": overlap.get("pipeline_semantics"),
        "failed_stage_turnover_evidence": failed_turnover,
        "failed_dependency_overlap_evidence": failed_dependencies,
        "failed_boundary_order_evidence": failed_boundary_order,
        "whole_sequence_barrier_evidence": barrier_rows,
        "candidate_stage_ids": candidate_stage_ids,
        "terminal_trace_flush_evidence": copy.deepcopy(terminal),
        "blockers": copy.deepcopy(overlap.get("blockers", [])),
    }


def single_layer_probe_agent_handoff(
    probe: dict[str, Any],
) -> dict[str, Any] | None:
    """Bind one actionable real-VCS Stage2 pipeline failure to its Agent turn."""

    if probe.get("status") == "pass":
        return None
    for row in probe.get("produced_reports", []):
        if not isinstance(row, dict) or not row.get("path"):
            continue
        report_path = Path(str(row["path"]))
        report = read_json_if_exists(report_path)
        if (
            report.get("schema_version")
            != "spatialaccagent.single_layer_functional_sim.v1"
            or report.get("status") != "fail"
        ):
            continue
        stats = report.get("stats") if isinstance(report.get("stats"), dict) else {}
        run = stats.get("run") if isinstance(stats.get("run"), dict) else {}
        stall = (
            run.get("adaptive_semantic_stall_evidence")
            if isinstance(run.get("adaptive_semantic_stall_evidence"), dict)
            else {}
        )
        overlap = (
            report.get("pipeline_overlap_evidence")
            if isinstance(report.get("pipeline_overlap_evidence"), dict)
            else {}
        )
        barrier_rows = [
            value
            for value in overlap.get("whole_sequence_barrier_evidence", [])
            if isinstance(value, dict)
            and value.get("whole_sequence_barrier_observed") is True
        ]
        overlap_irreversible_turnover = (
            overlap.get("irreversible_stage_turnover_evidence", {})
            if isinstance(
                overlap.get("irreversible_stage_turnover_evidence"), dict
            )
            else {}
        )
        overlap_failed_turnovers = [
            value
            for value in overlap_irreversible_turnover.get(
                "failed_stage_turnover_evidence", []
            )
            if isinstance(value, dict)
            and value.get("keeps_pipeline_filled") is False
            and value.get("overlapped") is False
        ]
        stall_failed_turnovers = [
            value
            for value in stall.get("failed_stage_turnover_evidence", [])
            if isinstance(value, dict)
        ]
        turnover_rows_are_structured = bool(stall_failed_turnovers) and all(
            row.get("stage_id")
            and isinstance(row.get("prior_token"), int)
            and isinstance(row.get("next_token"), int)
            and isinstance(row.get("prior_token_active_end_cycle"), int)
            and isinstance(row.get("next_token_active_start_cycle"), int)
            and isinstance(row.get("gap_cycles"), int)
            and row.get("keeps_pipeline_filled") is False
            and row.get("overlapped") is False
            and row in overlap_failed_turnovers
            for row in stall_failed_turnovers
        )
        turnover_violation = bool(
            stall.get("irreversible_violation_kind") == "stage_turnover"
            and overlap_irreversible_turnover.get("status") == "fail"
            and turnover_rows_are_structured
            and [
                str(value)
                for value in stall.get("candidate_stage_ids", [])
                if str(value)
            ]
            == [
                str(value)
                for value in overlap_irreversible_turnover.get(
                    "candidate_stage_ids", []
                )
                if str(value)
            ]
        )
        fingerprint = str(stats.get("input_fingerprint_sha256") or "")
        contract_sha = str(stall.get("contract_sha256") or "")
        trace_sha = str(overlap.get("trace_sha256") or "")
        termination = (
            run.get("adaptive_semantic_stall_termination")
            if isinstance(run.get("adaptive_semantic_stall_termination"), dict)
            else {}
        )
        if (
            not report_path.is_file()
            or not re.fullmatch(r"[0-9a-f]{64}", fingerprint)
            or not re.fullmatch(r"[0-9a-f]{64}", contract_sha)
            or not re.fullmatch(r"[0-9a-f]{64}", trace_sha)
            or stall.get("schema_version")
            != "spatialaccagent.adaptive_semantic_stall_evidence.v1"
            or stall.get("status") != "proven_semantic_stall"
            or stall.get("proof_mode") != "single_layer_pipeline_contract"
            or stall.get("failure_class")
            != "intra_layer_spatial_pipeline_violation"
            or overlap.get("status") != "fail"
            or overlap.get("contract_sha256") != contract_sha
            or not barrier_rows and not turnover_violation
            or run.get("failure_class") != "adaptive_semantic_stall"
            or run.get("returncode") != SEMANTIC_STALL_EXIT_CODE
            or termination.get("status") not in {"pass", "recovered_completed_job"}
        ):
            completed = _completed_single_layer_pipeline_failure_evidence(report)
            if completed is None:
                continue
            projection = {
                "schema_version": "spatialaccagent.single_layer_agent_handoff.v1",
                "status": "ready",
                "debug_layer": "single_transformer_layer_kernel",
                "agent_should_apply_code_changes": True,
                "failure_class": "intra_layer_spatial_pipeline_violation",
                "failure_mode": "completed_pipeline_overlap_violation",
                "report": {
                    "path": str(report_path),
                    "sha256": sha256_file(report_path),
                },
                "remote_workdir": stats.get("remote_workdir"),
                "real_tool_was_not_relaunched": (
                    stats.get("remote_job_reuse", {}).get(
                        "real_tool_was_not_relaunched"
                    )
                    if isinstance(stats.get("remote_job_reuse"), dict)
                    else None
                ),
                **completed,
                "summary": (
                    "real VCS completed the full Stage2 workload and output contract, "
                    "but source-bound token-level spatial-pipeline overlap checks failed"
                ),
            }
        else:
            candidate_stage_ids = list(
                dict.fromkeys(
                    str(value)
                    for value in stall.get("candidate_stage_ids", [])
                    if str(value)
                )
            )
            if turnover_violation and not {
                str(value["stage_id"]) for value in stall_failed_turnovers
            }.issubset(set(candidate_stage_ids)):
                continue
            projection = {
                "schema_version": "spatialaccagent.single_layer_agent_handoff.v1",
                "status": "ready",
                "debug_layer": "single_transformer_layer_kernel",
                "agent_should_apply_code_changes": True,
                "failure_class": "intra_layer_spatial_pipeline_violation",
                "report": {
                    "path": str(report_path),
                    "sha256": sha256_file(report_path),
                },
                "input_fingerprint_sha256": fingerprint,
                "pipeline_contract_sha256": contract_sha,
                "pipeline_trace_sha256": trace_sha,
                "remote_workdir": stats.get("remote_workdir"),
                "real_tool_was_not_relaunched": (
                    stats.get("remote_job_reuse", {}).get("real_tool_was_not_relaunched")
                    if isinstance(stats.get("remote_job_reuse"), dict)
                    else None
                ),
                "adaptive_termination": {
                    "remote_exit_code": termination.get("remote_exit_code"),
                    "fixed_wall_clock_timeout": termination.get(
                        "fixed_wall_clock_timeout"
                    ),
                    "fixed_cycle_timeout": termination.get("fixed_cycle_timeout"),
                },
                "whole_sequence_barrier_evidence": copy.deepcopy(barrier_rows),
                **(
                    {
                        "failure_mode": "irreversible_stage_turnover_violation",
                        "failed_stage_turnover_evidence": copy.deepcopy(
                            stall_failed_turnovers
                        ),
                        "candidate_stage_ids": candidate_stage_ids,
                        "summary": (
                            "real VCS proved an irreversible adjacent-token stage "
                            "turnover bubble; the same Stage2 hardware Agent must "
                            "repair the source-bound design"
                        ),
                    }
                    if turnover_violation
                    else {
                        "summary": (
                            "real VCS proved an intra-layer whole-sequence barrier; "
                            "the same Stage2 hardware Agent must repair the "
                            "source-bound design"
                        )
                    }
                ),
            }
        projection["failure_identity_sha256"] = canonical_contract_sha256(
            projection
        )
        return projection
    return None


def single_layer_pipeline_trace_record(
    run_dir: Path,
    handoff: dict[str, Any],
) -> dict[str, Any] | None:
    structured_overlap_failure = handoff.get("failure_mode") in {
        "completed_pipeline_overlap_violation",
        "irreversible_stage_turnover_violation",
    }
    barriers = [
        row
        for row in handoff.get("whole_sequence_barrier_evidence", [])
        if isinstance(row, dict)
        and row.get("whole_sequence_barrier_observed") is True
        and row.get("stage_id")
    ]
    candidate_stage_ids = [
        str(value)
        for value in handoff.get("candidate_stage_ids", [])
        if str(value)
    ]
    if not barriers and not (structured_overlap_failure and candidate_stage_ids):
        return None
    barrier = barriers[0] if barriers else None
    stage_id = (
        candidate_stage_ids[0]
        if structured_overlap_failure
        else str(barrier["stage_id"])
    )
    semantic_manifest_path = (
        run_dir
        / "verification"
        / "semantic_testbench"
        / "semantic_testbench_manifest.json"
    )
    pipeline_plan_path = run_dir / "pipeline_planning" / "pipeline_plan.json"
    semantic_manifest = read_json_if_exists(semantic_manifest_path)
    single_layer = (
        semantic_manifest.get("single_layer")
        if isinstance(semantic_manifest.get("single_layer"), dict)
        else {}
    )
    contract = (
        single_layer.get("pipeline_overlap_contract")
        if isinstance(single_layer.get("pipeline_overlap_contract"), dict)
        else {}
    )
    pipeline_plan = read_json_if_exists(pipeline_plan_path)
    plan_stages = [
        row
        for row in pipeline_plan.get("stages", [])
        if isinstance(row, dict) and row.get("stage_id")
    ]
    candidate_stage_set = (
        set(candidate_stage_ids) if structured_overlap_failure else {stage_id}
    )
    stages = [
        row
        for row in plan_stages
        if str(row.get("stage_id") or "") in candidate_stage_set
    ]
    stage_id_counts = {
        candidate: sum(
            str(row.get("stage_id") or "") == candidate for row in plan_stages
        )
        for candidate in candidate_stage_set
    }
    report_binding = (
        handoff.get("report") if isinstance(handoff.get("report"), dict) else {}
    )
    report_path = Path(str(report_binding.get("path") or ""))
    if (
        not semantic_manifest_path.is_file()
        or not pipeline_plan_path.is_file()
        or contract.get("contract_sha256")
        != handoff.get("pipeline_contract_sha256")
        or contract.get("pipeline_plan_sha256") != sha256_file(pipeline_plan_path)
        or len(stages) != len(candidate_stage_set)
        or any(count != 1 for count in stage_id_counts.values())
        or (
            structured_overlap_failure
            and (
                not report_path.is_file()
                or not re.fullmatch(
                    r"[0-9a-f]{64}", str(report_binding.get("sha256") or "")
                )
                or sha256_file(report_path) != report_binding.get("sha256")
            )
        )
    ):
        return None
    ordered_stages = [
        row
        for row in plan_stages
        if str(row.get("stage_id") or "") in candidate_stage_set
    ]
    template_pairs: list[dict[str, Any]] = []
    template_sources: list[str] = []
    for stage in ordered_stages:
        template_source = str(stage.get("source") or "")
        if (
            not template_source
            or Path(template_source).name != template_source
            or Path(template_source).suffix != ".scala"
        ):
            return None
        if template_source in template_sources:
            continue
        generated_template = (
            run_dir
            / "generated"
            / "chisel"
            / "src"
            / "main"
            / "scala"
            / "spatialaccagent"
            / "templates"
            / template_source
        )
        persistent_template = (
            Path.cwd()
            / "accagent"
            / "framework"
            / "templates"
            / "operator_chisel"
            / template_source
        )
        if (
            not generated_template.is_file()
            or not persistent_template.is_file()
            or sha256_file(generated_template) != sha256_file(persistent_template)
        ):
            return None
        template_sources.append(template_source)
        template_pairs.append(
            {
                "generated_path": str(generated_template),
                "persistent_path": str(persistent_template),
                "sha256": sha256_file(generated_template),
                "template_source": template_source,
            }
        )
    if structured_overlap_failure:
        failed_turnover = [
            copy.deepcopy(row)
            for row in handoff.get("failed_stage_turnover_evidence", [])
            if isinstance(row, dict)
        ]
        failed_dependencies = [
            copy.deepcopy(row)
            for row in handoff.get("failed_dependency_overlap_evidence", [])
            if isinstance(row, dict)
        ]
        failed_boundary_order = [
            copy.deepcopy(row)
            for row in handoff.get("failed_boundary_order_evidence", [])
            if isinstance(row, dict)
        ]
        if (
            not failed_turnover
            and not failed_dependencies
            and not failed_boundary_order
            and not barriers
        ):
            return None
        rate_insensitive = (
            handoff.get("pipeline_semantics")
            == "elastic_rate_insensitive_token_pipeline"
        )
        return {
            "status": "fail",
            "source": report_binding.get("path"),
            "evidence_type": "single_layer_pipeline_contract",
            "failure_class": "intra_layer_spatial_pipeline_violation",
            "failure_mode": handoff.get("failure_mode"),
            "stage_id": str(ordered_stages[0]["stage_id"]),
            "module": "pipeline_candidate_set",
            "candidate_stage_ids": [
                str(row["stage_id"]) for row in ordered_stages
            ],
            "candidate_stages": [
                {
                    key: row.get(key)
                    for key in (
                        "stage_id",
                        "index",
                        "op",
                        "kind",
                        "template_id",
                        "source",
                    )
                }
                for row in ordered_stages
            ],
            "candidate_template_sources": template_sources,
            "contract": handoff.get("pipeline_contract_sha256"),
            "violated_contract": (
                "all_spatial_operators_must_form_a_token_level_pipeline"
            ),
            "summary": (
                f"source-bound real VCS produced {len(failed_turnover)} failed "
                f"token turnovers, {len(failed_dependencies)} failed dependency "
                f"overlaps and {len(failed_boundary_order)} token-order failures"
            ),
            "observed_value": {
                str(handoff.get("failure_mode")): True,
                "failed_stage_turnover_evidence": failed_turnover,
                "failed_dependency_overlap_evidence": failed_dependencies,
                "failed_boundary_order_evidence": failed_boundary_order,
                "whole_sequence_barrier_evidence": copy.deepcopy(barriers),
            },
            "expected_value": (
                {
                    "pipeline_semantics": "elastic_rate_insensitive_token_pipeline",
                    "token_order_is_preserved_at_every_required_boundary": True,
                    "every_required_dependency_has_different_token_overlap": True,
                    "stage_turnover_gaps_are_diagnostic": True,
                    "all_planned_stages_same_cycle_concurrency_required": False,
                    "whole_sequence_barrier_forbidden": True,
                }
                if rate_insensitive
                else {
                    "every_stage_keeps_pipeline_filled": True,
                    "every_dependency_has_different_token_overlap": True,
                    "whole_sequence_barrier_forbidden": True,
                }
            ),
            "pipeline_evidence_schema": handoff.get("pipeline_evidence_schema"),
            "pipeline_semantics": handoff.get("pipeline_semantics"),
            "input_fingerprint_sha256": handoff.get(
                "input_fingerprint_sha256"
            ),
            "pipeline_trace_sha256": handoff.get("pipeline_trace_sha256"),
            "pipeline_plan": {
                "path": str(pipeline_plan_path),
                "sha256": sha256_file(pipeline_plan_path),
            },
            "semantic_manifest": {
                "path": str(semantic_manifest_path),
                "sha256": sha256_file(semantic_manifest_path),
            },
            "template_pairs": template_pairs,
        }

    assert barrier is not None
    template_source = template_sources[0]
    template_pair = template_pairs[0]
    return {
        "status": "fail",
        "source": handoff.get("report", {}).get("path"),
        "evidence_type": "single_layer_pipeline_contract",
        "failure_class": "intra_layer_spatial_pipeline_violation",
        "stage_id": stage_id,
        "module": Path(template_source).stem,
        "template_source": template_source,
        "contract": handoff.get("pipeline_contract_sha256"),
        "violated_contract": "whole_sequence_barrier_forbidden",
        "summary": (
            f"{stage_id} accepted the complete token sequence before token 0 "
            "crossed its output boundary"
        ),
        "observed_value": copy.deepcopy(barrier),
        "expected_value": {
            "token_0_first_output_before_final_token_last_input": True,
        },
        "input_fingerprint_sha256": handoff.get("input_fingerprint_sha256"),
        "pipeline_trace_sha256": handoff.get("pipeline_trace_sha256"),
        "pipeline_plan": {
            "path": str(pipeline_plan_path),
            "sha256": sha256_file(pipeline_plan_path),
        },
        "semantic_manifest": {
            "path": str(semantic_manifest_path),
            "sha256": sha256_file(semantic_manifest_path),
        },
        "template_pair": {
            "generated_path": template_pair["generated_path"],
            "persistent_path": template_pair["persistent_path"],
            "sha256": template_pair["sha256"],
        },
    }


def localized_single_layer_repair_route(
    action: dict[str, Any],
    step: dict[str, Any],
    record: dict[str, Any],
    handoff: dict[str, Any],
) -> tuple[dict[str, Any], dict[str, Any], str, list[str]]:
    """Convert one source-bound Stage2 trace into a bounded hardware-Agent action."""

    source_checkpoint = repair_step_checkpoint(step)
    stage_id = str(record["stage_id"])
    candidate_stage_ids = [
        str(value)
        for value in record.get("candidate_stage_ids", [])
        if str(value)
    ]
    candidate_stages = [
        row
        for row in record.get("candidate_stages", [])
        if isinstance(row, dict)
    ]
    target_modules = list(
        dict.fromkeys(
            str(row.get("op") or row.get("template_id") or row.get("stage_id"))
            for row in candidate_stages
            if str(
                row.get("op")
                or row.get("template_id")
                or row.get("stage_id")
                or ""
            )
        )
    ) or [str(record["module"])]
    routed_action = copy.deepcopy(action)
    routed_action.update(
        {
            "repair_kind": "localized_semantic_dut_repair",
            "repair_phase": "functional_repair",
            "repair_gate": "case_single_layer_functional",
            "debug_layer": "single_transformer_layer_kernel",
            "root_candidate_module": record["module"],
            "target_modules": target_modules,
            "candidate_stage_ids": candidate_stage_ids,
            "candidate_template_sources": record.get(
                "candidate_template_sources", []
            ),
            "root_candidate_is_unresolved": bool(candidate_stage_ids),
            "violated_contract": record["violated_contract"],
            "reason": handoff["summary"],
            "template_repair_requires_internal_boundary_trace": False,
            "dynamic_source_bound_route": True,
            "source_repair_checkpoint_fingerprint_sha256": source_checkpoint[
                "fingerprint_sha256"
            ],
            "source_bound_failure_identity_sha256": handoff.get(
                "failure_identity_sha256"
            ),
            "source_bound_input_fingerprint_sha256": record.get(
                "input_fingerprint_sha256"
            ),
            "minimal_repair_context": {"trace_record": record},
        }
    )
    routed_step = copy.deepcopy(step)
    routed_step["action"] = routed_action
    routed_step["debug_layer"] = "single_transformer_layer_kernel"
    return routed_action, routed_step, stage_id, target_modules


def exact_board_preflight_feedback(
    run_dir: Path,
    out_dir: Path,
) -> dict[str, Any]:
    materialization_path = out_dir / "dut_weight_binding_materialization.json"
    preflight_path = (
        run_dir
        / "verification"
        / "board_simulation"
        / "board_simulation_preflight_materialization.json"
    )
    manifest_path = run_dir / "generated" / "memory" / "dut_weight_binding_manifest.json"
    manifest = read_json_if_exists(manifest_path)
    board_plan = manifest.get("board_simulation_preflight_plan")
    if isinstance(board_plan, dict):
        current_validation_mode = str(
            board_plan.get("validation_mode") or "exact_sample_physical_ddr"
        )
        if current_validation_mode != EXACT_BOARD_FUNCTIONAL_VALIDATION_MODE:
            blocker = (
                "board validation boundary migration required: "
                f"current={current_validation_mode} "
                f"required={EXACT_BOARD_FUNCTIONAL_VALIDATION_MODE}"
            )
            return {
                "schema_version": "spatialaccagent.exact_board_preflight_feedback.v1",
                "status": "ready",
                "evidence_kind": "deterministic_board_validation_boundary_migration",
                "summary": blocker,
                "blockers": [blocker],
                "current_validation_mode": current_validation_mode,
                "required_validation_mode": EXACT_BOARD_FUNCTIONAL_VALIDATION_MODE,
                "manifest": {
                    "path": str(manifest_path),
                    "sha256": sha256_file(manifest_path),
                },
                "repair_handoff": {
                    "debug_layer": "board_axi_ddr_wrapped_system",
                    "failure_class": "validation_boundary_contract",
                    "repair_same_exact_board_agent": True,
                    "skip_prior_boundary_vcs": True,
                    "rerun_order": [
                        "finalizer",
                        "exact_board_preflight",
                        "real_board_vcs",
                        "vcs_analyzer",
                    ],
                    "rtl_edit_requires_preflight_evidence": True,
                },
            }
    materialization = read_json_if_exists(materialization_path)
    preflight = read_json_if_exists(preflight_path)
    blockers = [
        str(value)
        for value in materialization.get("blockers", [])
        if str(value)
    ]
    current = (
        materialization.get("schema_version")
        == "spatialaccagent.dut_weight_binding_materialization.v1"
        and materialization.get("status") == "incomplete"
        and bool(blockers)
    )
    if not current:
        return {
            "schema_version": "spatialaccagent.exact_board_preflight_feedback.v1",
            "status": "incomplete",
            "blockers": ["current exact-board finalizer/preflight failure is unavailable"],
        }

    def bind(path: Path, value: dict[str, Any]) -> dict[str, Any] | None:
        if not path.is_file() or not value:
            return None
        return {
            "path": str(path),
            "value": value,
        }

    return {
        "schema_version": "spatialaccagent.exact_board_preflight_feedback.v1",
        "status": "ready",
        "evidence_kind": "deterministic_board_manifest_and_preflight_failure",
        "summary": blockers[0],
        "blockers": blockers,
        "materialization": bind(materialization_path, materialization),
        "preflight": bind(preflight_path, preflight),
        "repair_handoff": {
            "debug_layer": "board_axi_ddr_wrapped_system",
            "failure_class": "manifest_or_preflight_contract",
            "repair_same_exact_board_agent": True,
            "rerun_order": ["finalizer", "exact_board_preflight", "real_board_vcs", "vcs_analyzer"],
            "rtl_edit_requires_preflight_evidence": True,
        },
    }


def current_exact_board_preflight_execution_authority(
    run_dir: Path,
    out_dir: Path,
    current_patch_feedback: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Authorize the canonical VCS step from current deterministic evidence.

    A previous Agent turn can legitimately contain a manifest-only blocker while
    the framework subsequently rematerializes the same board contract.  That
    historical feedback must not outrank a current hash-bound materialization
    and an independently revalidated exact-board preflight.
    """

    run_dir = run_dir.resolve()
    out_dir = out_dir.resolve()
    binding_path = run_dir / "generated" / "memory" / "dut_weight_binding_manifest.json"
    materialization_path = out_dir / "dut_weight_binding_materialization.json"
    board_manifest_path = (
        run_dir / "verification" / "board_simulation" / "board_simulation_manifest.json"
    )
    preflight_path = (
        run_dir
        / "verification"
        / "board_simulation"
        / "board_simulation_preflight_materialization.json"
    )
    identity_path = (
        run_dir / "verification" / "board_interface" / "board_source_identity.json"
    )
    materialization = read_json_if_exists(materialization_path)
    preflight_materialization = read_json_if_exists(preflight_path)
    blockers: list[str] = []

    if not binding_path.is_file():
        blockers.append("current DUT weight-binding manifest is missing")
    if not materialization_path.is_file():
        blockers.append("current DUT weight-binding materialization is missing")
    if not board_manifest_path.is_file():
        blockers.append("current board simulation manifest is missing")
    if not preflight_path.is_file():
        blockers.append("current board preflight materialization is missing")
    if not identity_path.is_file():
        blockers.append("current board source identity is missing")
    if blockers:
        return {
            "schema_version": (
                "spatialaccagent.current_exact_board_preflight_execution_authority.v1"
            ),
            "status": "incomplete",
            "route": None,
            "blockers": blockers,
        }

    if (
        materialization.get("schema_version")
        != "spatialaccagent.dut_weight_binding_materialization.v1"
        or materialization.get("status") != "pass"
        or materialization.get("manifest") != str(binding_path)
        or materialization.get("board_integration_harness_materialized") is not True
        or materialization.get("board_simulation_preflight_materialized") is not True
        or materialization.get("board_simulation_preflight_manifest")
        != str(board_manifest_path)
    ):
        blockers.append(
            "current DUT weight-binding materialization does not attest the live exact-board manifest"
        )
    if (
        preflight_materialization.get("schema_version")
        != "spatialaccagent.board_simulation_preflight_materialization.v1"
        or preflight_materialization.get("status") != "pass"
        or preflight_materialization.get("manifest") != str(board_manifest_path)
        or preflight_materialization.get("exact_board_preflight", {}).get("status")
        != "pass"
        or preflight_materialization.get("exact_board_preflight", {}).get(
            "blockers", []
        )
    ):
        blockers.append(
            "current board preflight materialization does not attest the live exact-board manifest"
        )

    direct_preflight = validate_exact_board_preflight(
        identity_path,
        board_manifest_path,
    )
    if (
        direct_preflight.get("status") != "pass"
        or direct_preflight.get("blockers", [])
    ):
        blockers.extend(
            str(value)
            for value in direct_preflight.get("blockers", [])
            if str(value)
        )
        if not direct_preflight.get("blockers", []):
            blockers.append("independent exact-board preflight did not pass")
    blockers = list(dict.fromkeys(blockers))
    return {
        "schema_version": (
            "spatialaccagent.current_exact_board_preflight_execution_authority.v1"
        ),
        "status": "pass" if not blockers else "incomplete",
        "route": "case_vcs_functional_sim" if not blockers else None,
        "blockers": blockers,
        "binding_manifest": {
            "path": str(binding_path),
        },
        "board_manifest": {
            "path": str(board_manifest_path),
        },
        "direct_exact_board_preflight": direct_preflight,
    }


def current_exact_board_preflight_supersedes_manifest_failure(
    authority: dict[str, Any],
    board_validation_evidence: dict[str, Any] | None,
) -> bool:
    """Discard only obsolete manifest failures after current preflight passes."""

    feedback = (
        board_validation_evidence.get("current_board_vcs_feedback", {})
        if isinstance(board_validation_evidence, dict)
        else {}
    )
    return bool(
        authority.get("status") == "pass"
        and authority.get("route") == "case_vcs_functional_sim"
        and exact_board_feedback_failure_class(feedback)
        == "manifest_validation_failure"
    )


def current_agent_patch_application_feedback(
    out_dir: Path,
    step: dict[str, Any],
    *,
    run_dir: Path | None = None,
    superseding_result_path: Path | None = None,
) -> dict[str, Any]:
    report_path = out_dir / "agent_patch_application.json"
    report = read_json_if_exists(report_path)
    blockers = [str(value) for value in report.get("blockers", []) if str(value)]
    retry_without_real_tool = report.get("retry_agent_without_real_tool") is True
    current = (
        report.get("schema_version")
        == "spatialaccagent.agent_patch_application.v1"
        and report.get("status") == "blocked"
        and applied_patch_matches_repair_step(report, step)
        and bool(blockers)
        and report_path.is_file()
    )
    if (
        current
        and run_dir is not None
        and old_lower_layer_certificate_error_is_resolved(
            report, run_dir, verification_scope_for_step(step)
        )
    ):
        return {
            "schema_version": "spatialaccagent.current_agent_patch_application_feedback.v1",
            "status": "not_run",
            "blockers": [],
            "summary": (
                "the older Agent transaction rejection is superseded by the "
                "current revalidated lower-layer certificate"
            ),
        }
    if (
        current
        and superseding_result_path is not None
        and superseding_result_path.is_file()
        and (
            superseding_result_path.stat().st_mtime_ns
            > report_path.stat().st_mtime_ns
            or (
                superseding_result_path.name == "case_board_vcs_functional.json"
                and not retry_without_real_tool
                and (
                    lambda value: (
                        value.get("status") == "fail"
                        and isinstance(value.get("run"), dict)
                        and value["run"].get("status") == "fail"
                        and value["run"].get("returncode") in {86, 87}
                    )
                )(read_json_if_exists(superseding_result_path))
            )
        )
    ):
        return {
            "schema_version": "spatialaccagent.current_agent_patch_application_feedback.v1",
            "status": "not_run",
            "blockers": [],
            "summary": (
                "the older Agent transaction rejection was superseded by its "
                "newer exact-board validation result"
            ),
        }
    if not current:
        return {
            "schema_version": "spatialaccagent.current_agent_patch_application_feedback.v1",
            "status": "not_run",
            "blockers": [],
        }
    return {
        "schema_version": "spatialaccagent.current_agent_patch_application_feedback.v1",
        "status": "ready",
        "summary": blockers[0],
        "blockers": blockers,
        "patch_application": {
            "path": str(report_path),
            "sha256": sha256_file(report_path),
            "value": report,
        },
        "repair_handoff": {
            "repair_same_implementation_agent": True,
            "repair_before_preflight_replay": True,
            "file_edits_were_not_applied": True,
        },
    }


def run_exact_board_validation_chain(
    *,
    case_adapter: dict[str, Any],
    vcs_role: str,
    vcs_spec: dict[str, Any] | None,
    analyzer_role: str,
    analyzer_spec: dict[str, Any] | None,
    run_dir: Path,
    step: dict[str, Any],
    out_dir: Path,
    timeout_sec: int,
    label: str,
    checkpoint_env: dict[str, str] | None = None,
) -> dict[str, Any]:
    if not vcs_spec or not analyzer_spec:
        result = {
            "status": "blocked",
            "summary": "case adapter must declare both real board VCS and VCS evidence-analyzer capabilities",
            "case_id": case_adapter.get("case_id"),
            "vcs_role": vcs_role,
            "analyzer_role": analyzer_role,
            "produced_reports": [],
        }
        annotate_verification_capability_probe(result, step)
        log_path = out_dir / f"{safe_step_id(step)}_verification_capability_probe_{label}.json"
        write_json(log_path, result)
        result["log_path"] = str(log_path)
        return result
    effective_checkpoint_env = {
        "SPATIALACC_MAX_HEAVY_JOBS": "1",
        **(checkpoint_env or {}),
    }
    vcs_result = run_capability_probe(
        case_adapter=case_adapter,
        spec_role=vcs_role,
        spec=vcs_spec,
        run_dir=run_dir,
        step=step,
        out_dir=out_dir,
        timeout_sec=timeout_sec,
        label=f"{label}_vcs",
        extra_env=effective_checkpoint_env,
    )
    checkpoint_screening_result: dict[str, Any] | None = None

    def current_runner_report() -> dict[str, Any]:
        candidates = [
            run_dir / "verification" / "vcs" / "case_board_vcs_functional.json"
        ]
        candidates.extend(
            resolve_run_path(run_dir, value)
            for value in vcs_spec.get("produces", [])
            if str(value).lower().endswith(".json")
        )
        for path in candidates:
            report = read_json_if_exists(path)
            if report.get("status") or report.get("phase"):
                return report
        return {}

    runner_report = current_runner_report()
    analyzer_result = run_capability_probe(
        case_adapter=case_adapter,
        spec_role=analyzer_role,
        spec=analyzer_spec,
        run_dir=run_dir,
        step=step,
        out_dir=out_dir,
        timeout_sec=timeout_sec,
        label=f"{label}_analyzer",
    )
    feedback = exact_board_vcs_feedback(
        case_adapter,
        run_dir,
        vcs_spec,
        analyzer_spec,
    )
    diagnosis = (
        feedback.get("diagnosis", {}).get("value", {})
        if isinstance(feedback.get("diagnosis"), dict)
        else {}
    )
    runner_stage_pass_eligible = bool(
        runner_report.get("stage_pass_eligible") is True
        or (
            runner_report.get("stage_pass_eligible") is None
            and runner_report.get("status") == "pass"
        )
    )
    passed = (
        vcs_result.get("status") == "pass"
        and runner_report.get("status") == "pass"
        and runner_stage_pass_eligible
        and analyzer_result.get("status") == "pass"
        and feedback.get("status") == "ready"
        and diagnosis.get("status") == "pass"
    )
    reports: list[dict[str, Any]] = []
    seen_reports: set[str] = set()
    for row in [
        *(
            checkpoint_screening_result.get("produced_reports", [])
            if isinstance(checkpoint_screening_result, dict)
            else []
        ),
        *vcs_result.get("produced_reports", []),
        *analyzer_result.get("produced_reports", []),
    ]:
        if not isinstance(row, dict):
            continue
        key = str(row.get("path") or "")
        if not key or key in seen_reports:
            continue
        seen_reports.add(key)
        reports.append(row)
    result = {
        "status": "pass" if passed else "fail",
        "summary": (
            "real exact-board VCS and evidence analyzer passed"
            if passed
            else str(diagnosis.get("summary") or "real exact-board VCS/analyzer chain did not pass")
        ),
        "case_id": case_adapter.get("case_id"),
        "case_adapter_tool": vcs_spec.get("name"),
        "case_adapter_role": vcs_role,
        "vcs": vcs_result,
        "checkpoint_screening_vcs": checkpoint_screening_result,
        "full_cold_vcs_required_after_screening": bool(
            checkpoint_screening_result is not None
        ),
        "final_runner_stage_pass_eligible": runner_stage_pass_eligible,
        "analyzer": analyzer_result,
        "current_board_vcs_feedback": feedback,
        "produced_reports": reports,
    }
    annotate_verification_capability_probe(result, step)
    log_path = out_dir / f"{safe_step_id(step)}_verification_capability_probe_{label}.json"
    write_json(log_path, result)
    result["log_path"] = str(log_path)
    return result


def run_exact_board_checkpoint_analyzer_only(
    *,
    case_adapter: dict[str, Any],
    analyzer_role: str,
    analyzer_spec: dict[str, Any] | None,
    vcs_spec: dict[str, Any] | None,
    run_dir: Path,
    step: dict[str, Any],
    out_dir: Path,
    timeout_sec: int,
    label: str,
) -> dict[str, Any]:
    """Analyze a completed calibration failure without rerunning board VCS."""

    analyzer_result = run_capability_probe(
        case_adapter=case_adapter,
        spec_role=analyzer_role,
        spec=analyzer_spec,
        run_dir=run_dir,
        step=step,
        out_dir=out_dir,
        timeout_sec=timeout_sec,
        label=f"{label}_analyzer_only",
    )
    feedback = exact_board_vcs_feedback(
        case_adapter,
        run_dir,
        vcs_spec,
        analyzer_spec,
    )
    diagnosis = (
        feedback.get("diagnosis", {})
        if isinstance(feedback.get("diagnosis"), dict)
        else {}
    )
    diagnosis_value = (
        diagnosis.get("value", {})
        if isinstance(diagnosis.get("value"), dict)
        else {}
    )
    reports = [
        row
        for row in analyzer_result.get("produced_reports", [])
        if isinstance(row, dict)
    ]
    result = {
        "status": "fail",
        "summary": diagnosis_value.get("summary")
        or "same-source checkpoint calibration failed and requires checkpoint-hook repair",
        "case_id": case_adapter.get("case_id"),
        "vcs": {
            "status": "not_run",
            "reason": "current_same_source_checkpoint_calibration_failure",
            "real_board_vcs_was_not_rerun": True,
        },
        "analyzer": analyzer_result,
        "current_board_vcs_feedback": feedback,
        "produced_reports": reports,
        "policy": {
            "checkpoint_failure_is_nonblocking_repair_acceleration": True,
            "independent_cold_hardware_failure_remains_primary": True,
            "analyzer_rerun_does_not_require_vcs_rerun": True,
        },
    }
    annotate_verification_capability_probe(result, step)
    log_path = (
        out_dir
        / f"{safe_step_id(step)}_verification_capability_probe_{label}.json"
    )
    write_json(log_path, result)
    result["log_path"] = str(log_path)
    return result


def semantic_trace_report_snapshot(path: Path) -> dict[str, Any]:
    if not path.is_file():
        return {"exists": False, "trace_signatures": []}
    report = read_json_if_exists(path)
    traces = report.get("internal_boundary_trace", []) if isinstance(report, dict) else []
    signatures = []
    for row in traces if isinstance(traces, list) else []:
        if not isinstance(row, dict) or row.get("evidence_type") != "semantic_internal_boundary_trace":
            continue
        observed = row.get("observed_value", {}) if isinstance(row.get("observed_value"), dict) else {}
        signatures.append(
            (
                str(row.get("stage_id") or ""),
                str(row.get("boundary_id") or ""),
                str(row.get("module") or ""),
                row.get("beat_index"),
                row.get("cycle"),
                str(observed.get("packed_literal") or ""),
                str(row.get("status") or ""),
            )
        )
    return {
        "exists": True,
        "mtime_ns": path.stat().st_mtime_ns,
        "sha256": sha256_file(path),
        "trace_signatures": signatures,
    }


def localized_instrumentation_probe_evidence(
    report_path: Path,
    before: dict[str, Any],
    stage_id: str,
) -> dict[str, Any]:
    after = semantic_trace_report_snapshot(report_path)
    before_signatures = {tuple(row) for row in before.get("trace_signatures", [])}
    after_signatures = [tuple(row) for row in after.get("trace_signatures", [])]
    new_signatures = [row for row in after_signatures if row not in before_signatures and row[0] == stage_id]
    fresh = bool(
        after.get("exists")
        and (
            not before.get("exists")
            or after.get("mtime_ns", 0) > before.get("mtime_ns", 0)
            or after.get("sha256") != before.get("sha256")
        )
    )
    return {
        "status": "pass" if fresh and new_signatures else "fail",
        "stage_id": stage_id,
        "report": str(report_path),
        "fresh_report": fresh,
        "new_internal_trace_count": len(new_signatures),
        "new_internal_boundaries": sorted({row[1] for row in new_signatures}),
        "new_internal_modules": sorted({row[2] for row in new_signatures}),
        "before_sha256": before.get("sha256"),
        "after_sha256": after.get("sha256"),
        "summary": (
            f"collected {len(new_signatures)} fresh internal semantic trace records for {stage_id}"
            if fresh and new_signatures
            else f"no fresh internal semantic trace records were produced for {stage_id}"
        ),
    }


def snapshot_current_real_tool_failure(
    run_dir: Path,
    out_dir: Path,
    stage_id: str,
) -> Path | None:
    snapshot_path = out_dir / "focused_real_tool_failure_snapshot.json"
    report_dir = run_dir / "verification" / "operator_leaf_functional"
    candidates: list[Path] = []
    if stage_id:
        candidates.append(report_dir / f"{stage_id.lower()}.json")
    candidates.extend(path for path in sorted(report_dir.glob("*.json")) if path not in candidates)
    for path in candidates:
        report = read_json_if_exists(path)
        module_results = report.get("module_results", [])
        if report.get("status") != "fail" or not isinstance(module_results, list) or not module_results:
            continue
        snapshot = dict(report)
        snapshot["failure_snapshot_source_path"] = str(path)
        snapshot["failure_snapshot_source_sha256"] = sha256_file(path)
        write_json(snapshot_path, snapshot)
        return snapshot_path
    return snapshot_path if snapshot_path.is_file() else None


def select_changed_input_dependency_producer(
    case_adapter: dict[str, Any],
    capability_spec: dict[str, Any] | None,
    changed_input: Path,
) -> tuple[str, dict[str, Any] | None]:
    if not isinstance(capability_spec, dict):
        return "", None
    consumer_inputs = {str(value) for value in capability_spec.get("consumes", []) if str(value)}
    tools = case_adapter.get("tools", {}) if isinstance(case_adapter.get("tools"), dict) else {}
    for role, spec in tools.items():
        if not isinstance(spec, dict) or spec is capability_spec:
            continue
        producer_inputs = {str(value) for value in spec.get("consumes", []) if str(value)}
        producer_outputs = {str(value) for value in spec.get("produces", []) if str(value)}
        consumes_changed_input = any(Path(value).name == changed_input.name for value in producer_inputs)
        if consumes_changed_input and producer_outputs.intersection(consumer_inputs):
            return str(role), spec
    return "", None


def single_layer_compile_failure_repair_context(
    run_dir: Path,
    step: dict[str, Any],
) -> dict[str, Any]:
    """Bind a real single-layer VCS compile failure to a local RTL repair.

    A connected-layer semantic gate can fail before simulation starts.  That
    failure is still actionable hardware evidence, but it cannot satisfy the
    exact-board runtime authority checks.  Keep this route deliberately
    narrow: only a current, real VCS compile error from the single-layer gate
    can open the generated semantic RTL files named by that error.
    """

    root = run_dir.resolve()
    report_path = root / "verification" / "single_layer" / "single_layer_functional_report.json"
    default_log_path = (
        root
        / "verification"
        / "operator_leaf_vcs"
        / "single_transformer_layer_kernel"
        / "vcs.log"
    )
    blockers: list[str] = []
    report = read_json_if_exists(report_path)
    if (
        report.get("schema_version")
        != "spatialaccagent.single_layer_functional_sim.v1"
    ):
        blockers.append("single-layer functional report schema is missing or invalid")
    if report.get("status") != "fail":
        blockers.append("single-layer functional report is not a current failure")
    stats = report.get("stats") if isinstance(report.get("stats"), dict) else {}
    compile_info = stats.get("compile") if isinstance(stats.get("compile"), dict) else {}
    run_info = stats.get("run") if isinstance(stats.get("run"), dict) else {}
    if compile_info.get("status") != "fail" or not isinstance(compile_info.get("returncode"), int):
        blockers.append("single-layer report does not prove a failed VCS compile")
    if run_info.get("status") not in {"not_run", "fail"}:
        blockers.append("single-layer report indicates simulation ran after the compile failure")

    raw_log_path = Path(str(stats.get("vcs_log") or default_log_path))
    log_path = raw_log_path if raw_log_path.is_absolute() else root / raw_log_path
    log_path = log_path.resolve()
    if log_path != default_log_path.resolve():
        blockers.append("single-layer VCS log is not the canonical current semantic-gate log")
    if not report_path.is_file():
        blockers.append(f"single-layer functional report is missing: {report_path}")
    if not log_path.is_file():
        blockers.append(f"single-layer VCS compile log is missing: {log_path}")
    compile_log = read_text(log_path) if log_path.is_file() else ""
    error_match = re.search(
        r"(?ms)(?P<error>Error-\[[^\]]+\][^\n]*)\s*\n\s*"
        r"(?P<source>[^\n,]+?\.(?:sv|v|svp|vp|vhd|vhdl)),\s*"
        r"(?P<line>\d+)",
        compile_log,
        flags=re.IGNORECASE,
    )
    if error_match is None:
        blockers.append("single-layer VCS log does not contain a source-bound compiler error")

    source_values = stats.get("source_files") if isinstance(stats.get("source_files"), list) else []
    source_paths: list[Path] = []
    for value in source_values:
        raw = Path(str(value))
        path = raw if raw.is_absolute() else root / raw
        path = path.resolve()
        if not path.is_file():
            blockers.append(f"single-layer compiled source is missing: {path}")
            continue
        source_paths.append(path)
    if not source_paths:
        blockers.append("single-layer report contains no current compiled sources")

    source_name = PurePosixPath(error_match.group("source")).name if error_match else ""
    source_matches = [path for path in source_paths if path.name == source_name]
    if source_name and len(source_matches) != 1:
        blockers.append(
            f"compiler diagnostic source is not uniquely bound in the single-layer source set: {source_name}"
        )

    port_match = re.search(
        r'Port\s+"(?P<port>[A-Za-z_][A-Za-z0-9_$]*)"\s+is not defined in module\s+'
        r"'(?P<module>[A-Za-z_][A-Za-z0-9_$]*)'\s+defined in\s+\"(?P<module_source>[^\"]+)\"",
        compile_log,
        flags=re.IGNORECASE,
    )
    missing_ports = []
    for match in re.finditer(
        r'Port\s+"(?P<port>[A-Za-z_][A-Za-z0-9_$]*)"\s+is not defined in module\s+'
        r"'(?P<module>[A-Za-z_][A-Za-z0-9_$]*)'",
        compile_log,
        flags=re.IGNORECASE,
    ):
        missing_ports.append(
            {"port": match.group("port"), "module": match.group("module")}
        )
    module_source_name = PurePosixPath(port_match.group("module_source")).name if port_match else ""
    module_source_matches = [path for path in source_paths if path.name == module_source_name]
    if port_match and len(module_source_matches) != 1:
        blockers.append(
            f"compiler diagnostic referenced module source is not uniquely bound: {module_source_name}"
        )

    # The source named on the compiler error is the writable side of an
    # interface mismatch.  The referenced module is included as read-only
    # interface evidence so the Agent cannot “fix” the declaration merely by
    # making the caller compile.
    editable_paths = list(source_matches)
    if not editable_paths:
        blockers.append("compiler diagnostic did not identify an editable generated semantic RTL source")

    if report_path.is_file() and editable_paths:
        report_mtime = report_path.stat().st_mtime_ns
        if any(path.stat().st_mtime_ns > report_mtime for path in editable_paths):
            blockers.append("single-layer report predates one or more diagnostic RTL sources")

    source_context: list[dict[str, Any]] = []
    if source_matches and error_match:
        lines = source_matches[0].read_text(encoding="utf-8", errors="replace").splitlines()
        line_number = int(error_match.group("line"))
        if 1 <= line_number <= len(lines):
            source_context = [
                {"line": number, "text": lines[number - 1]}
                for number in range(
                    max(1, line_number - 12), min(len(lines), line_number + 12) + 1
                )
            ]
        else:
            blockers.append("compiler diagnostic line is outside the current source file")

    if blockers:
        return {
            "schema_version": "spatialaccagent.single_layer_compile_rtl_repair_context.v1",
            "status": "blocked",
            "repair_kind": "single_layer_compile_rtl_repair",
            "blockers": list(dict.fromkeys(blockers)),
        }

    documents: list[dict[str, Any]] = []
    total_bytes = 0
    document_limit = 1_200_000

    def add_document(path: Path, max_chars: int) -> None:
        nonlocal total_bytes
        if total_bytes >= document_limit or not path.is_file():
            return
        snapshot = source_snapshot(path, min(max_chars, document_limit - total_bytes))
        if snapshot is None:
            return
        documents.append(snapshot)
        total_bytes += len(str(snapshot.get("content") or "").encode("utf-8"))

    add_document(report_path, 220_000)
    add_document(log_path, 120_000)
    testbench_path = Path(str(stats.get("testbench") or ""))
    if testbench_path:
        testbench_path = testbench_path if testbench_path.is_absolute() else root / testbench_path
        add_document(testbench_path.resolve(), 120_000)
    semantic_manifest_path = root / "verification" / "semantic_testbench" / "semantic_testbench_manifest.json"
    add_document(semantic_manifest_path, 260_000)
    editable_set = set(editable_paths)
    for path in source_paths:
        if path in editable_set:
            add_document(path, path.stat().st_size + 1)
            continue
        if path in module_source_matches:
            text = path.read_text(encoding="utf-8", errors="replace")
            declaration = re.search(
                r"(?ms)^\s*module\s+[^;]+?\);",
                text,
            )
            interface = declaration.group(0) if declaration else text[:80_000]
            content = json.dumps(
                {
                    "path": str(path),
                    "sha256": sha256_file(path),
                    "module_interface_only": True,
                    "content": interface,
                },
                indent=2,
                sort_keys=True,
            )
            if total_bytes < document_limit:
                content = content[: document_limit - total_bytes]
                documents.append(
                    {
                        "path": f"{display_path(path)}#module_interface_projection",
                        "source_path": display_path(path),
                        "source_sha256": sha256_file(path),
                        "content_sha256": hashlib.sha256(content.encode("utf-8")).hexdigest(),
                        "bytes": len(content.encode("utf-8")),
                        "content": content,
                        "truncated": False,
                        "projection": True,
                    }
                )
                total_bytes += len(content.encode("utf-8"))

    source_rows = []
    for path in source_paths:
        text = path.read_text(encoding="utf-8", errors="replace")
        source_rows.append(
            {
                "path": str(path),
                "relative_path": display_path(path),
                "sha256": sha256_file(path),
                "bytes": path.stat().st_size,
                "modules": re.findall(r"(?m)^\s*module\s+([A-Za-z_][A-Za-z0-9_$]*)\b", text),
                "editable": path in editable_paths,
            }
        )
    diagnostic = {
        "error": error_match.group("error").strip(),
        "source_name": source_name,
        "source_path": str(source_matches[0]) if source_matches else None,
        "line": int(error_match.group("line")) if error_match else None,
        "source_sha256": sha256_file(source_matches[0]) if source_matches else None,
        "source_context": source_context,
        "missing_ports": missing_ports,
        "referenced_module": port_match.group("module") if port_match else None,
        "referenced_module_source": str(module_source_matches[0]) if module_source_matches else None,
        "referenced_module_source_sha256": (
            sha256_file(module_source_matches[0]) if module_source_matches else None
        ),
    }
    report_ref = {
        "path": str(report_path),
        "sha256": sha256_file(report_path),
        "schema_version": report.get("schema_version"),
        "status": report.get("status"),
    }
    log_ref = {
        "path": str(log_path),
        "sha256": sha256_file(log_path),
        "bytes": log_path.stat().st_size,
    }
    source_bundle = {
        "schema_version": "spatialaccagent.single_layer_compile_rtl_source_bundle.v1",
        "status": "ready",
        "documents": documents,
        "document_count": len(documents),
        "document_bytes": total_bytes,
        "compiled_source_universe": source_rows,
        "editable_contract": {
            "allowed_exact_files": [str(path) for path in sorted(editable_paths)],
            "allowed_semantic_rtl_files": [str(path) for path in sorted(editable_paths)],
            "allowed_roots": [str((root / "generated" / "semantic_harness").resolve())],
            "require_exact_source_sha256": True,
            "persistent_generated_pair_required": False,
            "forbidden_targets": [
                "board_wrapper",
                "testbench",
                "axi_ddr",
                "weights",
                "runtime_image",
                "golden",
                "checker",
                "framework",
            ],
        },
        "compile_failure": {
            "report": report_ref,
            "compile": {
                "status": compile_info.get("status"),
                "returncode": compile_info.get("returncode"),
                "remote_workdir": stats.get("remote_workdir"),
            },
            "run": run_info,
            "vcs_log": log_ref,
            "diagnostic": diagnostic,
            "input_fingerprint_sha256": stats.get("input_fingerprint_sha256"),
            "top_module": stats.get("top_module"),
            "testbench": stats.get("testbench"),
        },
        "policy": {
            "read_only_evidence": True,
            "only_diagnostic_semantic_rtl_files_are_editable": True,
            "board_wrapper_and_board_vcs_are_not_part_of_this_repair": True,
            "mandatory_real_single_layer_vcs_after_patch": True,
            "no_board_vcs_before_single_layer_pass": True,
        },
    }
    authority = {
        "schema_version": "spatialaccagent.single_layer_compile_rtl_repair_authority.v1",
        "status": "ready",
        "blockers": [],
        "repair_kind": "single_layer_compile_rtl_repair",
        "debug_layer": "single_transformer_layer_kernel",
        "allowed_exact_files": [str(path) for path in sorted(editable_paths)],
        "current_single_layer_compile_failure": {
            "report": report_ref,
            "vcs_log": log_ref,
            "diagnostic": diagnostic,
        },
        "source_bundle": source_bundle,
        "board_authority_deferred_until_single_layer_pass": True,
    }
    return {
        "schema_version": "spatialaccagent.single_layer_compile_rtl_repair_context.v1",
        "status": "ready",
        "repair_kind": "single_layer_compile_rtl_repair",
        "debug_layer": "single_transformer_layer_kernel",
        "report": report_ref,
        "vcs_log": log_ref,
        "diagnostic": diagnostic,
        "compiled_source_universe": source_rows,
        "editable_paths": [str(path) for path in sorted(editable_paths)],
        "source_bundle": source_bundle,
        "authority": authority,
        "summary": (
            "current real single-layer VCS compilation failed before simulation; "
            "the source-bound semantic RTL interface must be repaired before board VCS"
        ),
        "required_next_action": (
            "let the implementation Agent repair only the diagnostic semantic RTL files, "
            "then rerun the mandatory case_single_layer_functional gate"
        ),
    }


def safe_step_id(step: dict[str, Any]) -> str:
    return str(step.get("id") or "causal_slice_repair").replace(".", "_").replace("/", "_")


def preserve_vcs_compile_diagnostic_provenance(
    *,
    run_dir: Path,
    out_dir: Path,
    step: dict[str, Any],
) -> dict[str, Any]:
    """Preserve attributable VCS/remote evidence without assuming a compiler error.

    Agent capability requests are intentionally generic: a remote cleanup
    failure, stale hierarchy report, and a real compiler diagnostic all need
    different follow-up decisions.  This producer binds the currently
    persisted runner and diagnosis artifacts and never invents compile or
    simulator evidence.
    """

    verification = run_dir / "verification"
    runner_path = verification / "vcs" / "case_board_vcs_functional.json"
    diagnosis_path = verification / "case_diagnostics" / "vcs_functional_diagnosis.json"
    compile_log_path = verification / "board_simulation" / "reports" / "compile.log"
    executed_manifest_path = verification / "board_simulation" / "board_simulation_executed_manifest.json"
    manifest_path = verification / "board_simulation" / "board_simulation_manifest.json"
    staged_sources = verification / "board_simulation" / "vcs_stage" / "sources"
    if not runner_path.is_file() or not diagnosis_path.is_file():
        missing = [str(path) for path in (runner_path, diagnosis_path) if not path.is_file()]
        return {
            "status": "blocked",
            "summary": "current VCS runner/diagnosis provenance is incomplete",
            "stage_passed": False,
            "repair_kind": "vcs_compile_diagnostic_source_provenance",
            "blockers": [f"missing preserved provenance input: {path}" for path in missing],
            "framework_action_required": "preserve the current VCS runner and diagnosis before retrying the Agent",
        }

    runner = read_json(runner_path)
    diagnosis = read_json(diagnosis_path)
    compile_info = diagnosis.get("failure_evidence", {}).get("compile", {})
    if not isinstance(compile_info, dict):
        compile_info = {}
    compile_log = read_text(compile_log_path) if compile_log_path.is_file() else ""
    diagnostic_match = re.search(
        r"(?P<source>[^\n,]+?\.(?:sv|v|svp|vp|vhd|vhdl)),\s*(?P<line>\d+)",
        compile_log,
        flags=re.IGNORECASE,
    )
    identifier_match = re.search(
        r"Identifier\s+'(?P<identifier>[A-Za-z_][A-Za-z0-9_$]*)'\s+has not been declared",
        compile_log,
        flags=re.IGNORECASE,
    )
    if identifier_match is None:
        identifier_match = re.search(
            r"Error-\[XMRE\][\s\S]*?token\s+'(?P<identifier>[A-Za-z_][A-Za-z0-9_$]*)'",
            compile_log,
            flags=re.IGNORECASE,
        )
    executed_manifest = (
        read_json_if_exists(executed_manifest_path)
        if executed_manifest_path.is_file()
        else {}
    )
    compile_plan = (
        executed_manifest.get("vcs_compile_plan", {})
        if isinstance(executed_manifest.get("vcs_compile_plan"), dict)
        else {}
    )
    source_rows = {
        str(row.get("source_id")): row
        for row in executed_manifest.get("source_files", [])
        if isinstance(row, dict) and row.get("source_id")
    }
    direct_vlogan = next(
        (
            command
            for command in compile_plan.get("ordered_commands", [])
            if isinstance(command, dict) and command.get("executable") == "vlogan"
        ),
        None,
    )
    source_ids = (
        [str(value) for value in direct_vlogan.get("source_ids", []) if str(value)]
        if isinstance(direct_vlogan, dict)
        else []
    )
    ordered_sources = []
    for index, source_id in enumerate(source_ids):
        row = source_rows.get(source_id, {})
        source_name = Path(str(row.get("path") or "")).name
        staged_path = staged_sources / source_name if source_name else None
        ordered_sources.append(
            {
                "compile_order": index,
                "source_id": source_id,
                "declared_path": row.get("path"),
                "role": row.get("role"),
                "staged_path": str(staged_path) if staged_path is not None else None,
                "sha256": sha256_file(staged_path)
                if staged_path is not None and staged_path.is_file()
                else None,
                "expected_sha256": row.get("sha256"),
            }
        )
    diagnostic = {
        "log_path": str(compile_log_path),
        "log_sha256": sha256_file(compile_log_path)
        if compile_log_path.is_file()
        else None,
        "first_real_error": diagnosis.get("failure_evidence", {}).get("first_real_error"),
        "identifier": identifier_match.group("identifier") if identifier_match else None,
        "logged_source": diagnostic_match.group("source").strip()
        if diagnostic_match
        else None,
        "line": int(diagnostic_match.group("line")) if diagnostic_match else None,
    }
    source_context = []
    source_provenance = {}
    if diagnostic["logged_source"] and diagnostic["line"]:
        source_name = PurePosixPath(str(diagnostic["logged_source"])).name
        staged_path = staged_sources / source_name
        matching_row = next(
            (
                row for row in ordered_sources
                if Path(str(row.get("staged_path") or "")).name == source_name
            ),
            None,
        )
        if staged_path.is_file():
            lines = staged_path.read_text(encoding="utf-8", errors="replace").splitlines()
            line_number = int(diagnostic["line"])
            if 1 <= line_number <= len(lines):
                source_context = [
                    {"line": number, "text": lines[number - 1]}
                    for number in range(max(1, line_number - 8), min(len(lines), line_number + 8) + 1)
                ]
        generated_path = run_dir / "generated" / "board_integration" / source_name
        source_provenance = {
            "staged_path": str(staged_path),
            "staged_sha256": sha256_file(staged_path) if staged_path.is_file() else None,
            "generated_path": str(generated_path),
            "generated_sha256": sha256_file(generated_path) if generated_path.is_file() else None,
            "generated_matches_staged": (
                staged_path.is_file()
                and generated_path.is_file()
                and sha256_file(staged_path) == sha256_file(generated_path)
            ),
            "compile_order": matching_row.get("compile_order") if matching_row else None,
            "source_id": matching_row.get("source_id") if matching_row else None,
            "role": matching_row.get("role") if matching_row else None,
            "source_context": source_context,
        }
    argv = direct_vlogan.get("argv", []) if isinstance(direct_vlogan, dict) else []
    argv = argv if isinstance(argv, list) else []
    include_dirs = [str(value) for value in argv if isinstance(value, str) and value.startswith("+incdir+")]
    defines = [str(value) for value in argv if isinstance(value, str) and value.startswith("+") and not value.startswith("+incdir+")]
    language_modes = [str(value) for value in argv if isinstance(value, str) and value in {"-sverilog", "-v2k", "-vhdl"}]
    provenance_complete = bool(
        compile_log_path.is_file()
        and diagnostic["logged_source"]
        and diagnostic["line"]
        and diagnostic["identifier"]
        and source_context
        and ordered_sources
        and isinstance(direct_vlogan, dict)
    )
    package = {
        "schema_version": "spatialaccagent.vcs_compile_diagnostic_source_provenance.v1",
        "status": "pass",
        "repair_kind": "vcs_compile_diagnostic_source_provenance",
        "policy": {
            "read_only": True,
            "vcs_rerun": False,
            "source_write": False,
            "hardware_root_cause_inference": False,
        },
        "diagnosis": {
            "path": str(diagnosis_path),
            "sha256": sha256_file(diagnosis_path),
            "status": diagnosis.get("diagnosis_status"),
            "failure_class": diagnosis.get("failure_class"),
            "first_real_error": diagnosis.get("failure_evidence", {}).get("first_real_error"),
            "repair_scope": diagnosis.get("failure_evidence", {}).get("repair_scope"),
        },
        "runner": {
            "path": str(runner_path),
            "sha256": sha256_file(runner_path),
            "status": runner.get("status"),
            "compile": runner.get("compile"),
            "simulation": runner.get("simulation"),
            "remote_stage_cleanup": runner.get("remote_stage_cleanup"),
            "remote_stage_prune": runner.get("remote_stage_prune"),
            "remote_workdir": runner.get("remote_workdir"),
        },
        "compile_evidence": compile_info,
        "compiler_diagnostic": diagnostic,
        "source_provenance": source_provenance,
        "compile_plan": {
            "executable": direct_vlogan.get("executable") if isinstance(direct_vlogan, dict) else None,
            "argv": argv,
            "include_dirs": include_dirs,
            "defines": defines,
            "language_modes": language_modes,
            "ordered_sources": ordered_sources,
            "executed_manifest": {
                "path": str(executed_manifest_path),
                "sha256": sha256_file(executed_manifest_path)
                if executed_manifest_path.is_file()
                else None,
            },
            "board_manifest": {
                "path": str(manifest_path),
                "sha256": sha256_file(manifest_path) if manifest_path.is_file() else None,
            },
        },
        "decision_contract": {
            "provenance_complete": provenance_complete,
            "prelaunch_environment_failure": (
                str(compile_info.get("remote_state") or "") == "not_run"
                and str(compile_info.get("failure_class") or "")
                in {"remote_stage_cleanup_failure", "remote_tool_transport_failure"}
            ),
            "same_capability_must_not_be_requested_again": True,
            "next_action": (
                "retry_same_exact_board_vcs_chain_after_environment_recovery"
                if str(compile_info.get("remote_state") or "") == "not_run"
                else "agent_decides_evidence_bound_minimal_generated_harness_or_compile_plan_repair"
            ),
        },
    }
    package_path = out_dir / f"{safe_step_id(step)}_vcs_compile_diagnostic_source_provenance.json"
    write_json(package_path, package)
    return {
        "status": "pass",
        "summary": "preserved generic VCS and remote execution provenance for Agent diagnosis",
        "stage_passed": False,
        "requires_agent_followup": True,
        "repair_kind": "vcs_compile_diagnostic_source_provenance",
        "context_package": str(package_path),
        "capability_reports": [str(package_path)],
        "vcs_compile_provenance": str(package_path),
        "target_modules": [str(value) for value in step.get("action", {}).get("target_modules", [])],
    }


def _lifecycle_evidence_reference(value: str) -> tuple[str, str] | None:
    """Parse one Agent-declared relative evidence path and SHA-256."""

    match = re.fullmatch(
        r"\s*(?P<path>.+?)\s+sha256=(?P<sha>[0-9a-f]{64})\s*",
        value,
        flags=re.IGNORECASE,
    )
    if not match:
        return None
    return match.group("path").strip(), match.group("sha").lower()


def _lifecycle_evidence_files(
    run_dir: Path, declared_path: str, expected_sha256: str
) -> tuple[Path | None, list[str]]:
    """Resolve a declared evidence file, allowing only a unique SHA-bound alias.

    The Agent sometimes names a JSON summary while the same current trace is
    stored as JSONL. A unique matching SHA is a safe path correction; a missing
    or ambiguous match remains a hard blocker.
    """

    root = run_dir.resolve()
    raw = Path(declared_path).expanduser()
    declared = raw.resolve() if raw.is_absolute() else (root / raw).resolve()
    candidates: list[Path] = []
    if declared.is_file() and sha256_file(declared) == expected_sha256:
        return declared, []

    # Keep the fallback bounded to the current run and to the declared file's
    # name/stem. It cannot silently select evidence from another run.
    names = {declared.name}
    if declared.suffix.lower() == ".json":
        names.add(f"{declared.stem}.jsonl")
    elif declared.suffix.lower() == ".jsonl":
        names.add(f"{declared.stem}.json")
    for path in root.rglob("*"):
        if not path.is_file() or path.name not in names:
            continue
        try:
            if sha256_file(path) == expected_sha256:
                candidates.append(path.resolve())
        except OSError:
            continue
    candidates = sorted(set(candidates))
    if candidates:
        # Multiple copies with the same SHA are the same immutable evidence,
        # not conflicting observations. Prefer the shortest current-run path
        # so an old archive cannot win over the active report directory.
        selected = min(
            candidates,
            key=lambda path: (len(path.relative_to(root).parts), str(path)),
        )
        return selected, [
            f"declared evidence path {declared_path} was corrected to a SHA-matching path {selected.relative_to(root)}"
        ]
    if not declared.exists():
        return None, [f"declared evidence file is missing: {declared_path}"]
    actual = sha256_file(declared)
    return None, [
        f"declared evidence SHA-256 mismatch for {declared_path}: expected {expected_sha256}, got {actual}"
    ]


def _read_lifecycle_evidence(path: Path) -> Any:
    if path.suffix.lower() != ".jsonl":
        return read_json(path)
    rows: list[Any] = []
    with path.open("r", encoding="utf-8", errors="replace") as handle:
        for line_number, line in enumerate(handle, 1):
            text = line.strip()
            if not text:
                continue
            try:
                rows.append(json.loads(text))
            except json.JSONDecodeError as exc:
                raise ValueError(f"invalid JSONL at {path}:{line_number}: {exc}") from exc
    return rows


def _lifecycle_scalar_values(value: Any, key: str) -> list[Any]:
    found: list[Any] = []
    if isinstance(value, dict):
        for name, child in value.items():
            if name == key and not isinstance(child, (dict, list)):
                found.append(child)
            found.extend(_lifecycle_scalar_values(child, key))
    elif isinstance(value, list):
        for child in value:
            found.extend(_lifecycle_scalar_values(child, key))
    return found


def _last_lifecycle_scalar(evidence: dict[str, Any], key: str) -> Any:
    values: list[Any] = []
    for value in evidence.values():
        values.extend(_lifecycle_scalar_values(value, key))
    return values[-1] if values else None


def reconcile_exact_board_lifecycle_cctg_observation_contract(
    *, run_dir: Path, out_dir: Path, step: dict[str, Any]
) -> dict[str, Any]:
    """Reconcile a lifecycle checker conflict without touching RTL or VCS."""

    action = step.get("action", {}) if isinstance(step.get("action"), dict) else {}
    required = action.get("required_evidence", [])
    if not isinstance(required, list) or not required:
        return {
            "status": "blocked",
            "summary": "lifecycle reconciliation has no declared evidence list",
            "repair_kind": "repair.reconcile_exact_board_lifecycle_cctg_observation_contract",
            "stage_passed": False,
            "framework_action_required": "return the exact five current evidence paths and SHA-256 values",
        }

    evidence: dict[str, Any] = {}
    bindings: list[dict[str, Any]] = []
    blockers: list[str] = []
    corrections: list[str] = []
    for item in required:
        parsed = _lifecycle_evidence_reference(str(item))
        if parsed is None:
            blockers.append(f"invalid lifecycle evidence reference: {item}")
            continue
        declared_path, expected_sha = parsed
        path, messages = _lifecycle_evidence_files(run_dir, declared_path, expected_sha)
        corrections.extend(messages)
        if path is None:
            blockers.extend(messages)
            continue
        try:
            value = _read_lifecycle_evidence(path)
        except (OSError, ValueError, json.JSONDecodeError) as exc:
            blockers.append(f"cannot read lifecycle evidence {path}: {exc}")
            continue
        bindings.append(
            {
                "declared_path": declared_path,
                "resolved_path": str(path),
                "sha256": expected_sha,
                "path_was_corrected": str(path) != str((run_dir / declared_path).resolve()),
            }
        )
        evidence[declared_path] = value

    if blockers:
        return {
            "status": "blocked",
            "summary": "lifecycle reconciliation failed closed because current evidence bindings are incomplete",
            "repair_kind": "repair.reconcile_exact_board_lifecycle_cctg_observation_contract",
            "stage_passed": False,
            "blockers": list(dict.fromkeys(blockers)),
            "path_corrections": corrections,
            "framework_action_required": "return corrected hash-bound evidence references; do not launch VCS",
        }

    first_ingress = _last_lifecycle_scalar(evidence, "first_core_ingress_fire_cycle")
    first_start = _last_lifecycle_scalar(evidence, "first_start_cycle")
    try:
        first_ingress = int(first_ingress)
        first_start = int(first_start)
    except (TypeError, ValueError):
        first_ingress = first_start = None
    if first_ingress is None or first_start is None:
        blockers.append(
            "current evidence does not contain both first_core_ingress_fire_cycle and first_start_cycle"
        )
    elif first_ingress >= first_start:
        blockers.append(
            "lifecycle order is not proven: first core input handshake must precede first start"
        )
    if blockers:
        return {
            "status": "blocked",
            "summary": "lifecycle reconciliation did not prove input-before-start",
            "repair_kind": "repair.reconcile_exact_board_lifecycle_cctg_observation_contract",
            "stage_passed": False,
            "blockers": list(dict.fromkeys(blockers)),
            "path_corrections": corrections,
            "framework_action_required": "return an exact lifecycle contradiction for Agent review; do not launch VCS",
        }

    diagnosis = next(
        (
            value
            for name, value in evidence.items()
            if name.endswith("vcs_functional_diagnosis.json") and isinstance(value, dict)
        ),
        {},
    )
    boundary_snapshot = {}
    failure_evidence = diagnosis.get("failure_evidence", {}) if isinstance(diagnosis, dict) else {}
    if isinstance(failure_evidence, dict):
        progress = failure_evidence.get("progress_event_summary", {})
        if isinstance(progress, dict):
            boundary_snapshot = copy.deepcopy(progress.get("latest_stall_snapshot", {}))
    package = {
        "schema_version": "spatialaccagent.exact_board_lifecycle_cctg_reconciliation.v1",
        "status": "pass",
        "capability_id": "repair.reconcile_exact_board_lifecycle_cctg_observation_contract",
        "repair_kind": "repair.reconcile_exact_board_lifecycle_cctg_observation_contract",
        "policy": {
            "read_only": True,
            "source_write": False,
            "vcs_started": False,
            "preserve_current_input_output_and_boundary_evidence": True,
        },
        "evidence_bindings": bindings,
        "path_corrections": corrections,
        "lifecycle": {
            "first_core_ingress_fire_cycle": first_ingress,
            "first_start_cycle": first_start,
            "input_before_start": True,
            "checker_interpretation": "input-before-start is valid under the current board lifecycle policy",
        },
        "internal_boundary_observation": boundary_snapshot,
        "preserved_contract": {
            "core_ingress_accepted_count": _last_lifecycle_scalar(evidence, "core_ingress_accepted_count"),
            "core_egress_accepted_count": _last_lifecycle_scalar(evidence, "core_egress_accepted_count"),
            "mlp_down_input_accepted_count": _last_lifecycle_scalar(evidence, "mlp_down_input_accepted_count"),
            "mlp_down_output_accepted_count": _last_lifecycle_scalar(evidence, "mlp_down_output_accepted_count"),
            "output_accept_count": _last_lifecycle_scalar(evidence, "output_accept_count"),
        },
    }
    package_path = (
        run_dir / "verification" / "case_diagnostics"
        / "exact_board_lifecycle_cctg_reconciliation.json"
    )
    write_json(package_path, package)
    return {
        "status": "pass",
        "summary": "reconciled input-before-start lifecycle evidence; preserved internal boundary and zero-output facts",
        "repair_kind": package["repair_kind"],
        "stage_passed": False,
        "requires_agent_followup": True,
        "capability_reports": [str(package_path)],
        "context_package": str(package_path),
        "vcs_started": False,
        "source_write": False,
    }


def localize_vcs_timescale_error_provenance(
    *,
    run_dir: Path,
    out_dir: Path,
    step: dict[str, Any],
) -> dict[str, Any]:
    """Bind an existing VCS timescale diagnostic to the exact staged inputs.

    This is deliberately an observation producer, not a compiler wrapper.  A
    compile failure is already an expensive real-tool result; consuming its
    log and staged closure must never start another VCS job or alter sources.
    """

    verification_root = run_dir / "verification"
    runner_path = verification_root / "vcs" / "case_board_vcs_functional.json"
    compile_log_path = verification_root / "board_simulation" / "reports" / "compile.log"
    executed_manifest_path = (
        verification_root / "board_simulation" / "board_simulation_executed_manifest.json"
    )
    manifest_path = verification_root / "board_simulation" / "board_simulation_manifest.json"
    stage_sources = verification_root / "board_simulation" / "vcs_stage" / "sources"
    required_paths = [
        runner_path,
        compile_log_path,
        executed_manifest_path,
        manifest_path,
        stage_sources,
    ]
    missing = [str(path) for path in required_paths if not path.exists()]
    if missing:
        return {
            "status": "blocked",
            "summary": "current VCS timescale provenance inputs are incomplete",
            "stage_passed": False,
            "repair_kind": "vcs_timescale_error_localization",
            "blockers": [f"missing preserved provenance input: {path}" for path in missing],
            "framework_action_required": "preserve the current VCS runner report, compile log, manifest, and staged sources before retrying the Agent",
        }

    runner = read_json_if_exists(runner_path)
    executed_manifest = read_json_if_exists(executed_manifest_path)
    compile_log = read_text(compile_log_path)
    match = re.search(
        r"(?P<source>[^\n,]+?\.(?:sv|v|svp|vp|vhd|vhdl)),\s*(?P<line>\d+)",
        compile_log,
        flags=re.IGNORECASE,
    )
    if not match or "Illegal `timescale for module" not in compile_log:
        return {
            "status": "blocked",
            "summary": "preserved VCS log does not contain a localizable Illegal `timescale diagnostic",
            "stage_passed": False,
            "repair_kind": "vcs_timescale_error_localization",
            "framework_action_required": "return the current VCS diagnostic to the exact-board Agent without a source edit",
        }

    logged_source = match.group("source").strip()
    source_name = PurePosixPath(logged_source).name
    source_path = stage_sources / source_name
    if not source_path.is_file():
        return {
            "status": "blocked",
            "summary": "VCS diagnostic source is absent from the preserved staged source closure",
            "stage_passed": False,
            "repair_kind": "vcs_timescale_error_localization",
            "blockers": [f"diagnostic source {logged_source} is not staged at {source_path}"],
            "framework_action_required": "restore the exact staged source closure before retrying the Agent",
        }

    compile_plan = (
        executed_manifest.get("vcs_compile_plan", {})
        if isinstance(executed_manifest.get("vcs_compile_plan"), dict)
        else {}
    )
    ordered_commands = compile_plan.get("ordered_commands", [])
    direct_vlogan_command = next(
        (
            command
            for command in ordered_commands
            if isinstance(command, dict) and command.get("executable") == "vlogan"
        ),
        None,
    )
    source_rows_by_id = {
        str(row.get("source_id")): row
        for row in executed_manifest.get("source_files", [])
        if isinstance(row, dict) and row.get("source_id")
    }
    source_ids = (
        [str(value) for value in direct_vlogan_command.get("source_ids", []) if str(value)]
        if isinstance(direct_vlogan_command, dict)
        else []
    )
    compile_command = str(executed_manifest.get("compile_command") or "")
    command_match = re.search(
        r"\bvlogan\b(?P<arguments>.*?)(?:\)\s*>>\s*reports/compile\.log|;\s*\(cd\s+vcs_work\s+&&\s+vcs)",
        compile_command,
        flags=re.DOTALL,
    )
    try:
        compile_tokens = shlex.split(
            "vlogan" + (command_match.group("arguments") if command_match else "")
        )
    except ValueError:
        compile_tokens = []
    parsed_source_tokens = [
        token
        for token in compile_tokens
        if token.startswith("../sources/")
        and Path(token).suffix.lower() in {".v", ".vp", ".sv", ".svp", ".vhd", ".vhdl"}
    ]
    ordered_source_entries = [
        {
            "source_id": source_id,
            "token": f"../sources/{Path(str(source_rows_by_id[source_id].get('path') or '')).name}",
            "expected_sha256": str(source_rows_by_id[source_id].get("sha256") or ""),
        }
        for source_id in source_ids
        if source_id in source_rows_by_id
        and Path(str(source_rows_by_id[source_id].get("path") or "")).name
    ]
    if not ordered_source_entries:
        ordered_source_entries = [
            {
                "source_id": None,
                "token": token,
                "expected_sha256": "",
            }
            for token in parsed_source_tokens
        ]
    if not ordered_source_entries:
        return {
            "status": "blocked",
            "summary": "preserved VCS compile command has no parseable ordered vlogan source list",
            "stage_passed": False,
            "repair_kind": "vcs_timescale_error_localization",
            "framework_action_required": "preserve an immutable direct VCS compile plan before retrying the Agent",
        }

    source_index = next(
        (index for index, row in enumerate(ordered_source_entries) if Path(row["token"]).name == source_name),
        None,
    )
    if source_index is None:
        return {
            "status": "blocked",
            "summary": "VCS diagnostic source is not present in the immutable ordered source list",
            "stage_passed": False,
            "repair_kind": "vcs_timescale_error_localization",
            "framework_action_required": "repair source-plan provenance before retrying the Agent",
        }

    source_lines = source_path.read_text(encoding="utf-8", errors="replace").splitlines()
    line_number = int(match.group("line"))
    if line_number < 1 or line_number > len(source_lines):
        return {
            "status": "blocked",
            "summary": "VCS diagnostic line is outside the preserved staged source",
            "stage_passed": False,
            "repair_kind": "vcs_timescale_error_localization",
            "framework_action_required": "restore matching compile-log and staged-source artifacts before retrying the Agent",
        }

    context_start = max(1, line_number - 3)
    context_end = min(len(source_lines), line_number + 12)
    source_context = [
        {"line": number, "text": source_lines[number - 1]}
        for number in range(context_start, context_end + 1)
    ]
    current_generated_source = run_dir / "generated" / "board_integration" / source_name
    staged_sha256 = sha256_file(source_path)
    generated_matches_staged = (
        current_generated_source.is_file()
        and sha256_file(current_generated_source) == staged_sha256
    )
    source_classification = (
        "editable_generated_board_source"
        if generated_matches_staged
        else "immutable_certified_or_sample_source"
    )

    def last_boundary(path: Path) -> dict[str, Any] | None:
        if not path.is_file():
            return None
        result = None
        for number, text in enumerate(
            path.read_text(encoding="utf-8", errors="replace").splitlines(), start=1
        ):
            found = re.match(r"\s*(module|package)\s+([A-Za-z_][A-Za-z0-9_$]*)\b", text)
            if found:
                result = {
                    "source": str(path),
                    "line": number,
                    "kind": found.group(1),
                    "name": found.group(2),
                    "text": text,
                }
        return result

    preceding_source = (
        stage_sources / Path(ordered_source_entries[source_index - 1]["token"]).name
        if source_index > 0
        else None
    )
    expected_payload_hashes = {
        str(row.get("path")): str(row.get("sha256"))
        for row in executed_manifest.get("payload", [])
        if isinstance(row, dict)
    }
    staged_rows = []
    for index, entry in enumerate(ordered_source_entries):
        token = str(entry["token"])
        staged_path = stage_sources / Path(token).name
        expected_sha256 = str(entry.get("expected_sha256") or "") or expected_payload_hashes.get(
            f"sources/{Path(token).name}", ""
        )
        staged_rows.append(
            {
                "compile_order": index,
                "source_id": entry.get("source_id"),
                "token": token,
                "staged_path": str(staged_path),
                "sha256": sha256_file(staged_path) if staged_path.is_file() else None,
                "expected_payload_sha256": expected_sha256 or None,
            }
        )
    hash_mismatches = [
        row["token"]
        for row in staged_rows
        if not row["sha256"]
        or (row["expected_payload_sha256"] and row["sha256"] != row["expected_payload_sha256"])
    ]
    if hash_mismatches:
        return {
            "status": "blocked",
            "summary": "staged VCS source closure no longer matches the executed compile payload",
            "stage_passed": False,
            "repair_kind": "vcs_timescale_error_localization",
            "blockers": [f"staged source hash mismatch: {token}" for token in hash_mismatches],
            "framework_action_required": "restore the exact executed source closure before retrying the Agent",
        }

    package = {
        "schema_version": "spatialaccagent.vcs_timescale_error_provenance.v1",
        "status": "pass",
        "repair_kind": "vcs_timescale_error_localization",
        "policy": {
            "read_only": True,
            "vcs_rerun": False,
            "source_write": False,
            "hardware_root_cause_inference": False,
        },
        "diagnostic": {
            "error": "Illegal `timescale for module",
            "logged_source": logged_source,
            "line": line_number,
            "log_path": str(compile_log_path),
            "log_sha256": sha256_file(compile_log_path),
            "source_context": source_context,
            "time_declarations": [
                {"line": number, "text": text}
                for number, text in enumerate(source_lines, start=1)
                if "timescale" in text or "timeunit" in text or "timeprecision" in text
            ],
        },
        "source": {
            "staged_path": str(source_path),
            "sha256": staged_sha256,
            "classification": source_classification,
            "current_generated_path": str(current_generated_source),
            "current_generated_matches_staged": generated_matches_staged,
            "previous_ordered_source_boundary": last_boundary(preceding_source)
            if preceding_source is not None
            else None,
        },
        "compile_plan": {
            "direct_vlogan_command": direct_vlogan_command,
            "compile_command": compile_command or runner.get("compile", {}).get("remote_command"),
            "compile_command_sha256": canonical_contract_sha256(
                direct_vlogan_command or compile_command
            ),
            "runner_argv": runner.get("compile", {}).get("argv", []),
            "runner_argv_sha256": canonical_contract_sha256(
                runner.get("compile", {}).get("argv", [])
            ),
            "ordered_vlogan_sources": staged_rows,
        },
        "input_bindings": {
            "runner_report": {"path": str(runner_path), "sha256": sha256_file(runner_path)},
            "executed_manifest": {
                "path": str(executed_manifest_path),
                "sha256": sha256_file(executed_manifest_path),
            },
            "board_manifest": {"path": str(manifest_path), "sha256": sha256_file(manifest_path)},
            "stage_source_set_sha256": canonical_contract_sha256(staged_rows),
        },
    }
    package_path = out_dir / f"{safe_step_id(step)}_vcs_timescale_error_provenance.json"
    write_json(package_path, package)
    return {
        "status": "pass",
        "summary": "preserved VCS timescale diagnostic was localized to a hash-bound staged source without rerunning VCS",
        "stage_passed": False,
        "requires_agent_followup": True,
        "repair_kind": "vcs_timescale_error_localization",
        "context_package": str(package_path),
        "capability_reports": [str(package_path)],
        "vcs_compile_provenance": str(package_path),
        "target_modules": [str(value) for value in step.get("action", {}).get("target_modules", [])],
    }


def run_optional_post_execution_review(
    *,
    agent: str,
    task: str,
    inputs: dict[str, Any],
    out_dir: Path,
    fallback_summary: str,
    deterministic_summary: str,
) -> dict[str, Any]:
    """Keep audit-only post-execution LLM calls out of the default repair path."""

    mode = os.environ.get("SPATIALACC_VALIDATION_LLM_TEAM_MODE", "conditional").strip().lower()
    if mode == "full":
        return run_stage_agent(
            agent=agent,
            stage="repair_execution",
            task=task,
            inputs=inputs,
            out_dir=out_dir,
            fallback_summary=fallback_summary,
        )
    path = out_dir / "deterministic_decisions" / f"{re.sub(r'[^A-Za-z0-9_.-]+', '_', agent)}.json"
    output = {
        "schema_version": "spatialaccagent.stage_worker_output.v0",
        "agent": agent,
        "stage": "repair_execution",
        "status": "ready",
        "summary": deterministic_summary,
        "sacg_focus": {"nodes": [], "edges": [], "constraints": [], "artifacts": []},
        "observations": [
            "The executed real-tool result fixes the immediate control-flow outcome.",
            "Any new semantic decision is deferred to the next Stage-6 CCTG/repair pass.",
        ],
        "risks": [],
        "proposed_actions": [],
        "executable_actions": [],
        "approval_required_for": [],
    }
    record = {
        "schema_version": "spatialaccagent.stage_worker_record.v0",
        "agent": agent,
        "stage": "repair_execution",
        "mode": "deterministic_conditional_route",
        "result_path": str(path),
        "used_fallback": False,
        "error": None,
        "llm_skipped": True,
        "skip_reason": "post-execution review output has no effect on this executor's control flow",
        "input_keys": sorted(inputs),
        "output": output,
    }
    write_json(path, record)
    return record


def execute_causal_slice_repair(
    step: dict[str, Any],
    source_state: Path,
    run_dir: Path,
    out_dir: Path,
    timeout_sec: int,
) -> dict[str, Any]:
    state = read_json(source_state)
    record = trace_record_from_step(step)
    module = str(record.get("module") or step.get("repair_context", {}).get("root_candidate_module") or "")
    stage_id = str(record.get("stage_id") or "")
    debug_layer = str(step.get("debug_layer") or step.get("action", {}).get("debug_layer") or "")
    if debug_layer and debug_layer != "operator_leaf_modules":
        action = step.get("action", {}) if isinstance(step.get("action"), dict) else {}
        repair_kind = str(step.get("repair_kind") or action.get("repair_kind") or "")
        cctg_connected_kernel_replay = repair_kind in {
            "cctg_connected_kernel_boundary_replay",
            "connected_kernel_cctg_contradiction_targeted_replay",
        }
        replay = run_current_layer_causal_replay(
            state=state,
            run_dir=run_dir,
            step=step,
            out_dir=out_dir,
            timeout_sec=timeout_sec,
        )
        package = {
            "schema_version": "spatialaccagent.current_layer_causal_repair_context_package.v0",
            "stage": "repair_execution",
            "source_sacg_state": str(source_state),
            "run_dir": str(run_dir),
            "repair_step_id": step.get("id"),
            "repair_scope": step.get("scope"),
            "debug_layer": debug_layer,
            "root_candidate_module": module or step.get("repair_context", {}).get("root_candidate_module"),
            "violated_contract": record.get("violated_contract") or record.get("contract") or step.get("repair_context", {}).get("violated_contract"),
            "current_layer_replay": replay,
            "policy": {
                "do_not_reopen_passed_lower_layer_without_contradicting_current_layer_trace": True,
                "current_layer_replay_precedes_lower_layer_backtrack": True,
                "rerun_same_debug_layer_until_pass": True,
            },
        }
        if cctg_connected_kernel_replay:
            cctg = (
                replay.get("cctg_boundary_replay", {})
                if isinstance(replay.get("cctg_boundary_replay"), dict)
                else {}
            )
            cctg_evidence_path = Path(str(cctg.get("path") or ""))
            cctg_evidence = (
                read_json_if_exists(cctg_evidence_path)
                if cctg_evidence_path.is_file()
                else {}
            )
            package.update(
                {
                    "status": "pass" if replay.get("status") == "pass" else "fail",
                    "capability_id": repair_kind,
                    "cctg_boundary_replay": cctg,
                    # Keep the bounded, source-bound observations in the LLM
                    # package itself. A path-only handoff would force the
                    # implementation Agent to guess the frontier from an
                    # aggregate report instead of using its requested data.
                    "cctg_boundary_replay_evidence": cctg_evidence,
                    "policy": {
                        **package["policy"],
                        "fresh_remote_vcs_execution_required": True,
                        "aggregate_boundary_trace_is_insufficient": True,
                        "next_action_requires_llm_causal_localization": True,
                    },
                }
            )
            if repair_kind == "connected_kernel_cctg_contradiction_targeted_replay":
                direct = (
                    replay.get("connected_kernel_targeted_replay", {})
                    if isinstance(replay.get("connected_kernel_targeted_replay"), dict)
                    else {}
                )
                package["immutable_semantic_replay_input_manifest"] = direct.get(
                    "immutable_semantic_replay_input_manifest", {}
                )
                package["connected_kernel_cctg_targeted_replay_trace"] = direct.get(
                    "connected_kernel_targeted_replay_trace", {}
                )
                package["connected_kernel_targeted_replay_causal_context"] = direct.get(
                    "connected_kernel_targeted_replay_causal_context", {}
                )
                package["connected_kernel_targeted_replay_manifest"] = direct.get(
                    "connected_kernel_targeted_replay_manifest", {}
                )
                package["connected_kernel_cctg_contradiction_reconciliation"] = direct.get(
                    "connected_kernel_cctg_contradiction_reconciliation", {}
                )
                package["policy"]["direct_lifecycle_observation_required"] = True
        package_path = out_dir / f"{safe_step_id(step)}_current_layer_causal_repair_context_package.json"
        write_json(package_path, package)
        if cctg_connected_kernel_replay:
            if replay.get("status") != "pass":
                return {
                    "status": "fail",
                    "summary": "fresh connected-kernel CCTG replay did not produce complete internal evidence",
                    "context_package": str(package_path),
                    "current_layer_replay_log": replay.get("log_path"),
                    "debug_layer": debug_layer,
                    "repair_kind": repair_kind,
                    "cctg_boundary_replay": cctg,
                }
            # The replay is an evidence producer only.  Replan so the real
            # implementation Agent consumes the fresh CCTG trace before any
            # lower-layer behavioral repair can be proposed.
            return {
                "status": "pass",
                "summary": "fresh connected-kernel CCTG replay completed; implementation Agent must localize the causal frontier",
                "stage_passed": False,
                "requires_agent_followup": True,
                "repair_kind": repair_kind,
                "context_package": str(package_path),
                "capability_reports": [str(package_path)],
                "current_layer_replay_log": replay.get("log_path"),
                "debug_layer": debug_layer,
                "cctg_boundary_replay": cctg,
            }
        llm_record = run_optional_post_execution_review(
            agent="current_layer_causal_repair_agent",
            task=(
                "Classify a current-layer CCTG repair replay. Lower debug layers already passed; "
                "do not reopen them unless this replay produced boundary evidence that contradicts "
                "their pass evidence. Decide whether the next action is same-layer retry, bounded "
                "current-layer code repair, or approval-gated backtrack."
            ),
            inputs={
                "source_sacg_state": str(source_state),
                "repair_step": step,
                "current_layer_causal_repair_context_package": package,
            },
            out_dir=out_dir,
            fallback_summary="current-layer causal repair execution requires LLM classification",
            deterministic_summary=(
            "Current-layer replay status is authoritative for this execution step; the next Stage-6 CCTG/"
            "repair iteration owns any same-layer repair or lower-layer challenge decision."
            ),
        )
        package["llm_record_path"] = llm_record.get("result_path")
        write_json(package_path, package)
        status = "pass" if replay.get("status") == "pass" else "fail"
        summary = (
            f"{debug_layer} current-layer causal replay passed"
            if status == "pass"
            else f"{debug_layer} current-layer causal replay still fails"
        )
        return {
            "status": status,
            "summary": summary,
            "context_package": str(package_path),
            "current_layer_replay_log": replay.get("log_path"),
            "llm_record": llm_record.get("result_path"),
            "debug_layer": debug_layer,
        }
    replay = run_causal_leaf_replay(state=state, run_dir=run_dir, step=step, out_dir=out_dir, timeout_sec=timeout_sec)
    report_path = (
        run_dir
        / "verification"
        / "operator_leaf_functional"
        / f"{stage_id.lower()}.json"
    )
    stage_report = read_json_if_exists(report_path)
    generated_sources = []
    if module:
        for path in (run_dir / "generated" / "chisel").glob(f"{module}*.sv"):
            generated_sources.append(str(path))
    module_result = target_module_result(stage_report, module) if stage_report else None
    first_failed = first_failed_module(stage_report) if stage_report else None
    target_passed = bool(module_result and module_result.get("status") == "pass")
    stage_passed = bool(stage_report and stage_report.get("status") == "pass")
    package = {
        "schema_version": "spatialaccagent.causal_repair_context_package.v0",
        "stage": "repair_execution",
        "source_sacg_state": str(source_state),
        "run_dir": str(run_dir),
        "repair_step_id": step.get("id"),
        "repair_scope": step.get("scope"),
        "root_candidate_module": module,
        "stage_id": stage_id,
        "violated_contract": record.get("violated_contract") or record.get("contract"),
        "targeted_replay": replay,
        "leaf_stage_report_path": str(report_path),
        "leaf_stage_report_summary": summarize_leaf_report(stage_report, module) if stage_report else {},
        "generated_sources": generated_sources,
        "template_candidates": template_candidates_for_module(module),
        "classification": {
            "target_module_passed_after_replay": target_passed,
            "stage_passed_after_replay": stage_passed,
            "first_failed_module_after_replay": first_failed.get("module") if first_failed else None,
            "policy": "if the localized target passes, rerun Stage7 to discover the next hierarchical blocker; if it still fails, keep repair local to this causal slice or request checked backtrack",
        },
    }
    package_path = out_dir / f"{safe_step_id(step)}_causal_repair_context_package.json"
    write_json(package_path, package)
    llm_record = run_optional_post_execution_review(
        agent="causal_slice_repair_agent",
        task=(
            "Classify the executed causal-slice repair replay. Decide whether the current localized "
            "module is repaired, whether the next action is ordered Stage7 retry, another bounded "
            "causal repair, or an approval-gated backtrack. Do not claim hardware pass without tool evidence."
        ),
        inputs={
            "source_sacg_state": str(source_state),
            "repair_step": step,
            "causal_repair_context_package": package,
        },
        out_dir=out_dir,
        fallback_summary="causal slice repair execution requires LLM classification",
        deterministic_summary=(
            "Leaf replay status and the first failed module uniquely determine whether this step passed; the next "
            "Stage-6 CCTG/repair iteration owns any subsequent repair decision."
        ),
    )
    package["llm_record_path"] = llm_record.get("result_path")
    write_json(package_path, package)
    if stage_passed:
        status = "pass"
        summary = f"{module} causal slice replay passed; stage leaf functional gate passed"
    elif target_passed:
        status = "pass"
        summary = (
            f"{module} causal slice replay passed; next blocker is "
            f"{package['classification']['first_failed_module_after_replay']}"
        )
    else:
        status = "fail"
        summary = f"{module} causal slice replay still fails"
    return {
        "status": status,
        "summary": summary,
        "context_package": str(package_path),
        "targeted_replay_log": replay.get("log_path"),
        "leaf_stage_report": str(report_path),
        "llm_record": llm_record.get("result_path"),
        "target_module_passed": target_passed,
        "stage_passed": stage_passed,
        "first_failed_module_after_replay": package["classification"]["first_failed_module_after_replay"],
    }


def execute_verification_capability_repair(
    step: dict[str, Any],
    source_state: Path,
    run_dir: Path,
    out_dir: Path,
    timeout_sec: int,
) -> dict[str, Any]:
    action = step.get("action", {}) if isinstance(step.get("action"), dict) else {}
    initial_repair_context = (
        action.get("minimal_repair_context", {})
        if isinstance(action.get("minimal_repair_context"), dict)
        else {}
    )
    current_board_to_lower_layer_contradiction = (
        copy.deepcopy(
            initial_repair_context.get("current_board_to_lower_layer_contradiction")
        )
        if isinstance(
            initial_repair_context.get("current_board_to_lower_layer_contradiction"),
            dict,
        )
        else None
    )
    repair_kind = str(action.get("repair_kind") or "")
    if repair_kind == "repair.reconcile_exact_board_lifecycle_cctg_observation_contract":
        return reconcile_exact_board_lifecycle_cctg_observation_contract(
            run_dir=run_dir,
            out_dir=out_dir,
            step=step,
        )
    if repair_kind == "connected_kernel_current_dag_boundary_signal_map":
        return produce_connected_kernel_boundary_signal_map(
            step=step,
            run_dir=run_dir,
            out_dir=out_dir,
        )
    if repair_kind in {
        "vcs_compile_diagnostic_source_provenance",
        "board_vcs_itsfm_source_provenance",
    }:
        return preserve_vcs_compile_diagnostic_provenance(
            run_dir=run_dir,
            out_dir=out_dir,
            step=step,
        )
    if repair_kind == "vcs_timescale_error_localization":
        compile_log = run_dir / "verification" / "board_simulation" / "reports" / "compile.log"
        if compile_log.is_file() and "Illegal `timescale for module" in compile_log.read_text(
            encoding="utf-8", errors="replace"
        ):
            return localize_vcs_timescale_error_provenance(
                run_dir=run_dir,
                out_dir=out_dir,
                step=step,
            )
        # A persisted historical action can outlive the compiler failure that
        # originally motivated it.  Reclassify conservatively instead of
        # manufacturing a timescale diagnostic.
        return preserve_vcs_compile_diagnostic_provenance(
            run_dir=run_dir,
            out_dir=out_dir,
            step=step,
        )
    state = read_json(source_state)
    single_layer_compile_context: dict[str, Any] | None = None
    single_layer_compile_rtl_repair = False
    if repair_kind == "board_semantic_rtl_repair":
        candidate_compile_context = single_layer_compile_failure_repair_context(
            run_dir,
            step,
        )
        if candidate_compile_context.get("status") == "ready":
            single_layer_compile_context = candidate_compile_context
            single_layer_compile_rtl_repair = True
            action = copy.deepcopy(action)
            action["single_layer_compile_rtl_repair"] = True
            action["target_debug_layer"] = "single_transformer_layer_kernel"
            action["target_modules"] = [
                Path(str(path)).stem
                for path in candidate_compile_context.get("editable_paths", [])
                if str(path)
            ]
            action["minimal_repair_context"] = {
                **initial_repair_context,
                "single_layer_compile_failure": candidate_compile_context,
            }
            step = copy.deepcopy(step)
            step["action"] = action
            step["target_debug_layer"] = "single_transformer_layer_kernel"
    if str(action.get("repair_kind") or "") in {
        "tool_runtime_environment_contract",
        "remote_tool_transport_contract",
    }:
        repair_kind = str(action.get("repair_kind"))
        return {
            "status": "blocked",
            "summary": (
                "remote simulator transport failed before a hardware verdict; no DUT, harness, golden, or checker edit is authorized"
                if repair_kind == "remote_tool_transport_contract"
                else "current verification tool runtime does not satisfy its declared environment contract; no DUT, harness, golden, or checker edit is authorized"
            ),
            "stage_passed": False,
            "repair_kind": repair_kind,
            "failed_current_layer_gates": action.get("failed_current_layer_gates", []),
            "framework_action_required": (
                "recover or rerun the detached remote job through the bounded polling transport"
                if repair_kind == "remote_tool_transport_contract"
                else "resolve and hash-bind a compatible tool environment, then rerun the failed current gate"
            ),
        }
    fpga_ip_repair_closure = materialize_fpga_ip_repair_closure(run_dir, out_dir)
    record = trace_record_from_step(step)
    if not record and isinstance(action.get("minimal_repair_context"), dict):
        record = action["minimal_repair_context"].get("trace_record", {})
    stage_id = str(record.get("stage_id") or "")
    verification_scope = verification_scope_for_step(step)
    if not verification_scope and stage_id:
        verification_scope = "operator_leaf_closure"
    if not verification_scope:
        return {
            "status": "blocked",
            "summary": "verification capability repair has no recognized debug-layer scope",
            "stage_passed": False,
            "debug_layer": action.get("debug_layer") or step.get("debug_layer"),
            "framework_action_required": "bind the repair action to an explicit hierarchical verification debug layer",
        }
    completed_producer_evidence = prior_capability_producer_evidence(
        state,
        run_dir=run_dir,
        verification_scope=verification_scope,
    )
    require_single_layer = verification_scope in {"single_layer_closure", "board_axi_ddr_closure"}
    repair_kind = str(action.get("repair_kind") or "")
    native_vcs_loop_localization = (
        repair_kind == "exact_board_vcs_zero_time_toggle_cone_localization"
    )
    board_integration_repair = (
        verification_scope == "board_axi_ddr_closure"
        and repair_kind
        in {
            "exact_board_integration_harness",
            "exact_board_vcs_zero_time_toggle_cone_localization",
            "board_semantic_rtl_repair",
        }
    )
    board_semantic_rtl_repair = (
        board_integration_repair and repair_kind == "board_semantic_rtl_repair"
    )
    single_layer_compile_rtl_repair = bool(
        single_layer_compile_rtl_repair
        and board_semantic_rtl_repair
        and isinstance(single_layer_compile_context, dict)
    )
    board_observation_only_repair = False
    # Fast replay is an execution service, not a separate Agent repair route.
    # Keep every Layer-3 turn on the one fixed capture/restore lifecycle.
    explicit_checkpoint_maintenance = False
    try:
        single_layer_certificate_path = artifact_path(
            state,
            "artifact.stage6.single_layer_promotion_certificate",
        )
    except Exception:
        single_layer_certificate_path = None
    localized_semantic_repair = str(action.get("repair_kind") or "") == "localized_semantic_dut_repair"
    localized_instrumentation_only = (
        localized_semantic_repair and str(action.get("repair_phase") or "") == "instrumentation_first"
    )
    prior_localized_agent_path = out_dir / "llm" / "localized_semantic_dut_repair_agent_result.json"
    prior_localized_agent_result = read_json_if_exists(prior_localized_agent_path)
    localized_template_instrumentation_only = (
        localized_semantic_repair
        and not localized_instrumentation_only
        and localized_template_instrumentation_requested(prior_localized_agent_result, record)
        and not localized_template_instrumentation_already_collected(out_dir, record)
    )
    target_modules = [str(item) for item in action.get("target_modules", []) if str(item)]
    case_adapter = case_adapter_for_state(state, run_dir)
    builder_role, builder_spec = ("", None)
    builder_probe: dict[str, Any] = {"status": "not_run", "summary": "no reference builder required for this repair kind"}
    if str(action.get("repair_kind") or "") == "independent_golden_reference":
        builder_role, builder_spec = select_reference_builder_tool(case_adapter)
        builder_probe = run_capability_probe(
            case_adapter=case_adapter,
            spec_role=builder_role,
            spec=builder_spec,
            run_dir=run_dir,
            step=step,
            out_dir=out_dir,
            timeout_sec=timeout_sec,
        )
    capability_role, capability_spec = select_capability_tool(step, case_adapter)
    if board_integration_repair:
        (
            capability_role,
            capability_spec,
            capability_analyzer_role,
            capability_analyzer_spec,
        ) = select_exact_board_validation_tools(case_adapter)
    else:
        capability_analyzer_role, capability_analyzer_spec = "", None

    pre_patch_checkpoint_preparation = (
        prepare_stage3_checkpoint_probe_environment(
            run_dir,
            label=f"{safe_step_id(step)}_pre_patch",
        )
        if board_integration_repair
        else {
            "status": "not_run",
            "summary": "checkpoint replay is only available for layer-3 board integration",
            "env": {},
        }
    )
    checkpoint_probe_env: dict[str, str] = dict(
        pre_patch_checkpoint_preparation.get("env", {})
    )
    if native_vcs_loop_localization:
        checkpoint_probe_env["SPATIALACC_VCS_LOOP_REPORT"] = "1"

    def run_current_capability_probe(
        label: str,
        *,
        extra_env: dict[str, str] | None = None,
    ) -> dict[str, Any]:
        if board_integration_repair:
            return run_exact_board_validation_chain(
                case_adapter=case_adapter,
                vcs_role=capability_role,
                vcs_spec=capability_spec,
                analyzer_role=capability_analyzer_role,
                analyzer_spec=capability_analyzer_spec,
                run_dir=run_dir,
                step=step,
                out_dir=out_dir,
                timeout_sec=timeout_sec,
                label=label,
                checkpoint_env={
                    **checkpoint_probe_env,
                    **(extra_env or {}),
                },
            )
        return run_capability_probe(
            case_adapter=case_adapter,
            spec_role=capability_role,
            spec=capability_spec,
            run_dir=run_dir,
            step=step,
            out_dir=out_dir,
            timeout_sec=timeout_sec,
            label=label,
        )
    # Layer 3 always starts from the current board result and current internal
    # signals. Historical failed-source matches are retained on disk only as
    # optional context; they never select or block the next repair action.
    content_addressed_failed_source_attempt = None
    board_memory_runtime_preparation = (
        prepare_exact_board_memory_runtime_inputs(
            source_state,
            run_dir,
            out_dir,
            repair_step=step,
            verification_scope=verification_scope,
        )
        if board_integration_repair
        else {
            "status": "not_run",
            "summary": "exact-board memory/runtime preparation is only required for layer-3 integration",
        }
    )
    current_board_metadata_refresh: dict[str, Any] = {
        "status": "not_run",
        "summary": "current board metadata refresh is only required for layer-3 integration",
    }
    if (
        board_integration_repair
        and board_memory_runtime_preparation.get("status") == "pass"
    ):
        # The board manifest, ordered compile plan and checkpoint contract are
        # derived from the current generated sources. Refresh them before
        # reading any saved board result so an observation-only testbench edit
        # cannot leave a stale source hash that is later mistaken for a DUT
        # failure. This is local deterministic metadata work; it does not rerun
        # Layer 2 or start a remote tool.
        current_board_metadata_refresh = finalize_dut_weight_binding_manifest(
            run_dir,
            out_dir,
            require_single_layer=require_single_layer,
            require_board=True,
            single_layer_certificate_path=single_layer_certificate_path,
        )
        if current_board_metadata_refresh.get("status") != "pass":
            return {
                "status": "fail",
                "summary": (
                    "current Layer-3 board metadata could not be rebuilt from "
                    "the current source closure; the real tool was not started"
                ),
                "context_package": None,
                "reference_builder_log": builder_probe.get("log_path"),
                "capability_probe_log": None,
                "capability_reports": [],
                "llm_record": None,
                "agent_patch_application": None,
                "dut_weight_binding_materialization": (
                    current_board_metadata_refresh.get("path")
                ),
                "current_board_metadata_refresh": current_board_metadata_refresh,
                "stage_passed": False,
                "target_modules": target_modules,
                "framework_action_required": (
                    "repair deterministic current-source board metadata before "
                    "any LLM or VCS continuation"
                ),
            }
        # The compiled-model identity used by fast replay includes the board
        # manifest. Recreate the execution-only request from the refreshed
        # identity so no stale request can survive this deterministic update.
        pre_patch_checkpoint_preparation = (
            prepare_stage3_checkpoint_probe_environment(
                run_dir,
                label=f"{safe_step_id(step)}_current_board_metadata_refresh",
            )
        )
        checkpoint_probe_env.clear()
        checkpoint_probe_env.update(
            pre_patch_checkpoint_preparation.get("env", {})
        )
    checkpoint_framework_recovery = (
        checkpoint_framework_authority_rebind_status(run_dir)
        if board_integration_repair and explicit_checkpoint_maintenance
        else {
            "schema_version": (
                "spatialaccagent.checkpoint_framework_authority_recovery.v1"
            ),
            "status": "not_required",
            "required": False,
            "summary": (
                "checkpoint authority recovery is disabled during ordinary "
                "hardware repair"
                if board_integration_repair
                else "not a board-integration repair"
            ),
        }
    )
    if (
        board_integration_repair
        and board_memory_runtime_preparation.get("status") == "pass"
        and checkpoint_framework_recovery.get("required") is True
    ):
        recovery_materialization = finalize_dut_weight_binding_manifest(
            run_dir,
            out_dir,
            require_single_layer=require_single_layer,
            require_board=True,
            single_layer_certificate_path=single_layer_certificate_path,
        )
        checkpoint_framework_recovery["materialization"] = {
            "status": recovery_materialization.get("status"),
            "path": recovery_materialization.get("path"),
            "manifest_sha256": recovery_materialization.get("manifest_sha256"),
            "checkpoint_framework_authority_binding": copy.deepcopy(
                recovery_materialization.get(
                    "checkpoint_framework_authority_binding", {}
                )
            ),
            "blockers": copy.deepcopy(
                recovery_materialization.get("blockers", [])
            ),
        }
        if recovery_materialization.get("status") == "pass":
            post_recovery_status = checkpoint_framework_authority_rebind_status(
                run_dir
            )
            checkpoint_framework_recovery["post_materialization_status"] = (
                post_recovery_status
            )
            if post_recovery_status.get("required") is True:
                return {
                    "status": "fail",
                    "summary": (
                        "checkpoint framework authority recovery was not idempotent; "
                        "the real tool was not started"
                    ),
                    "context_package": None,
                    "reference_builder_log": builder_probe.get("log_path"),
                    "capability_probe_log": None,
                    "capability_reports": [],
                    "llm_record": None,
                    "agent_patch_application": None,
                    "dut_weight_binding_materialization": (
                        recovery_materialization.get("path")
                    ),
                    "checkpoint_framework_authority_recovery": (
                        checkpoint_framework_recovery
                    ),
                    "stage_passed": False,
                    "target_modules": target_modules,
                    "framework_action_required": (
                        "repair deterministic authority materialization before any "
                        "LLM or VCS continuation"
                    ),
                }
            # The replay path is verified by a native restore followed by
            # actual token progress.  Legacy cold-vs-restore calibration
            # reports are historical diagnostics only and must never divert a
            # current Layer-3 repair loop.
            recovered_checkpoint_failure = None
            recovered_board_failure = (
                None
                if recovered_checkpoint_failure is not None
                else current_exact_board_validation_evidence(
                    case_adapter,
                    run_dir,
                    capability_spec,
                    capability_analyzer_spec,
                    run_dir
                    / "verification"
                    / "board_simulation"
                    / "board_simulation_manifest.json",
                    content_addressed_failed_attempt=(
                        content_addressed_failed_source_attempt
                    ),
                )
            )
            recovery_has_current_failure = bool(
                recovered_checkpoint_failure is not None
                or recovered_board_failure is not None
            )
            checkpoint_framework_recovery[
                "current_failure_deferred_to_agent_without_vcs"
            ] = recovery_has_current_failure
        else:
            recovery_has_current_failure = False
        if (
            recovery_materialization.get("status") == "pass"
            and not recovery_has_current_failure
        ):
            refreshed_checkpoint_preparation = (
                prepare_stage3_checkpoint_probe_environment(
                    run_dir,
                    label=(
                        f"{safe_step_id(step)}_checkpoint_framework_authority_"
                        "rebind"
                    ),
                    targeted_replay_plan=(
                        step.get("targeted_replay_plan", {})
                        if isinstance(step.get("targeted_replay_plan"), dict)
                        else {}
                    ),
                    repair_impact=(
                        action.get("checkpoint_impact", {})
                        if isinstance(action.get("checkpoint_impact"), dict)
                        else {}
                    ),
                )
            )
            checkpoint_probe_env.clear()
            checkpoint_probe_env.update(
                refreshed_checkpoint_preparation.get("env", {})
            )
            checkpoint_framework_recovery["checkpoint_request"] = {
                key: copy.deepcopy(refreshed_checkpoint_preparation.get(key))
                for key in (
                    "status",
                    "summary",
                    "request_path",
                    "request_sha256",
                    "remote_tool_must_not_start",
                )
                if refreshed_checkpoint_preparation.get(key) is not None
            }
            recovery_probe = run_current_capability_probe(
                "checkpoint_framework_authority_rebind"
            )
            capability_passed = recovery_probe.get("status") == "pass"
            new_real_tool_failure_requires_agent = (
                exact_board_probe_requires_agent_continuation(recovery_probe)
            )
            new_real_tool_failure_identity = (
                exact_board_probe_agent_handoff_identity(recovery_probe)
            )
            return {
                "status": "pass" if capability_passed else "fail",
                "summary": recovery_probe.get("summary")
                or (
                    "framework-owned checkpoint adapter identity was rebound "
                    "before the exact-board real-tool chain"
                ),
                "context_package": None,
                "reference_builder_log": builder_probe.get("log_path"),
                "capability_probe_log": recovery_probe.get("log_path"),
                "post_patch_capability_probe_log": recovery_probe.get(
                    "log_path"
                ),
                "capability_reports": recovery_probe.get(
                    "produced_reports", []
                ),
                "leaf_stage_report": None,
                "llm_record": None,
                "agent_patch_application": None,
                "agent_requested_validation": None,
                "dut_weight_binding_materialization": (
                    recovery_materialization.get("path")
                ),
                "simulation_checkpoint_request": (
                    refreshed_checkpoint_preparation.get("request_path")
                ),
                "checkpoint_framework_authority_recovery": (
                    checkpoint_framework_recovery
                ),
                "stage_passed": capability_passed,
                "target_modules": target_modules,
                "new_current_real_tool_failure_requires_agent": (
                    new_real_tool_failure_requires_agent
                ),
                "new_current_real_tool_failure_identity_sha256": (
                    new_real_tool_failure_identity
                ),
            }
    existing_board_replay_ready = existing_exact_board_replay_ready(
        run_dir,
        out_dir,
        board_memory_runtime_preparation,
    )
    bootstrap_generation_applied = (
        current_exact_board_bootstrap_generation_applied(run_dir, out_dir, step)
        if board_integration_repair
        else False
    )
    first_exact_board_generation_pending = (
        board_integration_repair and not existing_board_replay_ready
    )
    board_bootstrap_required = (
        board_integration_repair
        and board_harness_bootstrap_required(
            action,
            existing_replay_ready=existing_board_replay_ready,
            bootstrap_generation_applied=bootstrap_generation_applied,
            current_real_vcs_failure_ready=(
                content_addressed_failed_source_attempt is not None
            ),
        )
    )
    if board_bootstrap_required:
        # A source-only match from an older shell is not evidence for a new
        # missing/incomplete board harness. Generate that harness first, then
        # let the unchanged real VCS chain create fresh repair evidence.
        content_addressed_failed_source_attempt = None
    failure_snapshot = snapshot_current_real_tool_failure(run_dir, out_dir, stage_id)
    dependency_role, dependency_spec = select_changed_input_dependency_producer(
        case_adapter,
        capability_spec,
        run_dir / "generated" / "memory" / "dut_weight_binding_manifest.json",
    )
    if board_integration_repair:
        resource_resume = {
            "status": "not_run",
            "summary": (
                "Layer-3 repair does not resume old validation transactions; "
                "the next action uses the current board VCS result"
            ),
        }
    else:
        resource_resume = resume_prior_resource_failed_validation(
            run_dir,
            out_dir,
            timeout_sec,
            step=step,
            case_adapter=case_adapter,
        )
    resumed_materialization_checkpoint: dict[str, Any] = {
        "status": "not_run",
        "summary": "no applied exact-board patch checkpoint requires early finalization",
    }
    refresh_existing_board_manifest = bool(
        board_integration_repair
        and (
            (
                first_exact_board_generation_pending
                and existing_board_manifest_refresh_ready(run_dir, out_dir)
            )
            or resource_resume.get("force_board_manifest_finalization") is True
        )
    )
    if (
        board_integration_repair
        and first_exact_board_generation_pending
        and (
            resource_resume.get("status") == "pass"
            or refresh_existing_board_manifest
        )
    ):
        resumed_materialization_checkpoint = finalize_dut_weight_binding_manifest(
            run_dir,
            out_dir,
            require_single_layer=require_single_layer,
            require_board=True,
            single_layer_certificate_path=single_layer_certificate_path,
        )
        existing_board_replay_ready = existing_exact_board_replay_ready(
            run_dir,
            out_dir,
            board_memory_runtime_preparation,
        )
        first_exact_board_generation_pending = not existing_board_replay_ready
        board_bootstrap_required = board_harness_bootstrap_required(
            action,
            existing_replay_ready=existing_board_replay_ready,
            bootstrap_generation_applied=bootstrap_generation_applied,
            current_real_vcs_failure_ready=(
                content_addressed_failed_source_attempt is not None
            ),
        )
    # The real VCS chain performs the live board preflight itself.  Do not let
    # saved preflight reports, old replay requests, or prior patch rejections
    # preempt current internal-signal evidence.
    current_board_preflight_feedback = {
        "schema_version": "spatialaccagent.exact_board_preflight_feedback.v1",
        "status": "not_run",
        "blockers": [],
    }
    resume_requires_board_repair = False
    current_patch_application_feedback = {
        "schema_version": "spatialaccagent.current_agent_patch_application_feedback.v1",
        "status": "not_run",
        "blockers": [],
    }
    current_preflight_execution_authority = {
        "schema_version": "spatialaccagent.current_exact_board_preflight_execution_authority.v1",
        "status": "not_run",
        "route": None,
        "blockers": [],
    }
    observed_pending_checkpoint_executor_retry = (
        pending_checkpoint_specialist_executor_retry(
            out_dir,
            run_dir,
            step,
        )
        if board_integration_repair and explicit_checkpoint_maintenance
        else None
    )
    pending_checkpoint_executor_retry = (
        observed_pending_checkpoint_executor_retry
        if explicit_checkpoint_maintenance
        else None
    )
    # Do not route Layer-3 work through the retired same-source calibration
    # path.  Fast replay is confirmed by one native restore plus real token
    # progress, so old manifests and their derived hashes cannot stop an LLM
    # repair decision.
    pending_checkpoint_calibration = None
    current_checkpoint_calibration_failure = None
    current_board_validation_evidence = (
        current_exact_board_validation_evidence(
            case_adapter,
            run_dir,
            capability_spec,
            capability_analyzer_spec,
            run_dir
            / "verification"
            / "board_simulation"
            / "board_simulation_manifest.json",
            content_addressed_failed_attempt=(
                content_addressed_failed_source_attempt
            ),
        )
        if board_integration_repair
        and not native_vcs_loop_localization
        and pending_checkpoint_calibration is None
        and current_checkpoint_calibration_failure is None
        and (
            content_addressed_failed_source_attempt is not None
            or (
                not board_bootstrap_required
                and current_board_preflight_feedback.get("status") != "ready"
            )
        )
        else None
    )
    if current_exact_board_preflight_supersedes_manifest_failure(
        current_preflight_execution_authority,
        current_board_validation_evidence,
    ):
        current_board_validation_evidence = None
    if single_layer_compile_rtl_repair:
        pre_patch_dependency_refresh = {
            "status": "not_run",
            "reason": "current_single_layer_vcs_compile_failure",
            "summary": (
                "the current single-layer VCS compile failure is already captured; "
                "send its source-bound diagnostic to the semantic RTL Agent before any rerun"
            ),
        }
        capability_probe = {
            "status": "fail",
            "summary": single_layer_compile_context.get("summary"),
            "repair_kind": "single_layer_compile_rtl_repair",
            "debug_layer": "single_transformer_layer_kernel",
            "produced_reports": [
                single_layer_compile_context.get("report", {}),
                single_layer_compile_context.get("vcs_log", {}),
            ],
            "single_layer_compile_failure": copy.deepcopy(
                single_layer_compile_context
            ),
            "real_tool_was_not_relaunched": True,
        }
    elif pending_checkpoint_executor_retry is not None:
        pre_patch_dependency_refresh = {
            "status": "not_run",
            "reason": "pending_checkpoint_specialist_executor_retry",
            "summary": (
                "a hash-current Agent checkpoint patch was rejected only by a "
                "corrected executor rule and must be materialized before another VCS run"
            ),
        }
        capability_probe = {
            "status": "not_run",
            "reason": "pending_checkpoint_specialist_executor_retry",
            "summary": (
                "skipped redundant pre-patch exact-board VCS so the existing trusted "
                "Agent transaction can enter atomic materialization"
            ),
        }
    elif native_vcs_loop_localization:
        pre_patch_dependency_refresh = {
            "status": "not_run",
            "reason": "agent_requested_native_vcs_loop_localization",
            "summary": (
                "run the existing exact-board VCS/analyzer chain with native loop "
                "reporting and an independent simulation-time probe"
            ),
        }
        capability_probe = run_current_capability_probe(
            "agent_requested_native_vcs_loop_localization"
        )
    elif current_board_validation_evidence is not None:
        pre_patch_dependency_refresh = {
            "status": "not_run",
            "reason": "current_real_board_vcs_and_analyzer_evidence",
            "summary": (
                "current hash-bound real-tool evidence must be analyzed by the "
                "same exact-board agent before another VCS run"
            ),
        }
        capability_probe = current_board_validation_evidence
    elif skip_initial_exact_board_pre_patch(
        board_integration_repair=board_integration_repair,
        resource_resume_status=str(resource_resume.get("status") or ""),
        existing_replay_ready=not board_bootstrap_required,
    ):
        pre_patch_dependency_refresh = {
            "status": "not_run",
            "reason": "first_exact_board_generation_prerequisites_pending",
            "summary": (
                "skipped only because no current hash-valid exact-board shell/preflight exists; "
                "the post-generation dependency producer remains mandatory"
            ),
        }
        capability_probe = {
            "status": "not_run",
            "reason": "first_exact_board_generation_prerequisites_pending",
            "summary": (
                "skipped only because the first exact-board shell cannot execute before generation; "
                "the unchanged post-generation capability gate remains mandatory"
            ),
        }
    elif resource_resume.get("status") == "not_run":
        pre_patch_dependency_refresh = (
            run_capability_probe(
                case_adapter=case_adapter,
                spec_role=dependency_role,
                spec=dependency_spec,
                run_dir=run_dir,
                step=step,
                out_dir=out_dir,
                timeout_sec=timeout_sec,
                label="dependency_refresh_pre_patch",
            )
            if dependency_spec
            else {
                "status": "not_run",
                "summary": "current capability tool has no changed-input direct producer to refresh",
            }
        )
        capability_probe = run_current_capability_probe("pre_patch")
    else:
        pre_patch_dependency_refresh = {
            "status": "not_run",
            "summary": "skipped because an unchanged applied patch has a resumable validation checkpoint",
        }
        capability_probe = {
            "status": "not_run",
            "summary": "skipped pre-patch replay; resume the exact applied patch at post-patch replay",
        }
    produced_reports = capability_probe.get("produced_reports", []) if isinstance(capability_probe.get("produced_reports"), list) else []
    leaf_report_path = run_dir / "verification" / "operator_leaf_golden" / f"{stage_id.lower()}.json" if stage_id else None
    leaf_stage_report = read_json_if_exists(leaf_report_path) if leaf_report_path else {}
    if capability_probe.get("status") == "pass":
        return {
            "status": "pass",
            "summary": (
                f"{capability_spec.get('name') if capability_spec else capability_role} verification capability "
                "already passes; no implementation agent call is required"
            ),
            "context_package": None,
            "reference_builder_log": builder_probe.get("log_path"),
            "capability_probe_log": capability_probe.get("log_path"),
            "post_patch_capability_probe_log": capability_probe.get("log_path"),
            "capability_reports": produced_reports,
            "leaf_stage_report": str(leaf_report_path) if leaf_report_path else None,
            "llm_record": None,
            "stage_passed": True,
            "target_modules": target_modules,
        }
    if str(action.get("repair_kind") or "") == "exact_board_interface_discovery":
        return {
            "status": "fail",
            "summary": (
                "the LLM board-interface discovery agent did not produce a Vivado-fact-validated exact-board "
                "contract; no DUT, sample-project, golden, checker, or generated board RTL edit is authorized"
            ),
            "context_package": None,
            "capability_probe_log": capability_probe.get("log_path"),
            "capability_reports": produced_reports,
            "stage_passed": False,
            "repair_kind": "exact_board_interface_discovery",
            "target_modules": target_modules,
            "framework_action_required": (
                "rerun the same board discovery agent/tool after its reported missing Vivado fact, LLM transport, "
                "or evidence-binding condition is available"
            ),
        }
    candidate_single_layer_real_tool_handoff = (
        single_layer_probe_agent_handoff(capability_probe)
        if not board_integration_repair
        else None
    )
    single_layer_pipeline_trace = (
        single_layer_pipeline_trace_record(
            run_dir, candidate_single_layer_real_tool_handoff
        )
        if candidate_single_layer_real_tool_handoff is not None
        else None
    )
    single_layer_real_tool_handoff = (
        candidate_single_layer_real_tool_handoff
        if single_layer_pipeline_trace is not None
        else None
    )
    if single_layer_real_tool_handoff is not None:
        assert single_layer_pipeline_trace is not None
        record = single_layer_pipeline_trace
        action, step, stage_id, target_modules = localized_single_layer_repair_route(
            action,
            step,
            record,
            single_layer_real_tool_handoff,
        )
        localized_semantic_repair = True
        localized_instrumentation_only = False
        localized_template_instrumentation_only = False
    generated_sources = (
        [
            str(path)
            for path in (run_dir / "generated" / "board_integration").rglob("*")
            if path.is_file()
            and path.suffix.lower() in BOARD_INTEGRATION_SOURCE_SUFFIXES
        ]
        if board_integration_repair
        else [
            str(path)
            for module in target_modules
            for path in (run_dir / "generated" / "chisel").glob(f"{module}*.sv")
        ]
    )
    source_bundle = (
        copy.deepcopy(single_layer_compile_context.get("source_bundle", {}))
        if single_layer_compile_rtl_repair
        else repair_source_bundle(state, run_dir, out_dir)
    )
    repair_agent_disposition = current_repair_agent_disposition(
        run_dir,
        step,
        verification_scope,
    )
    package = {
        "schema_version": "spatialaccagent.verification_capability_repair_package.v0",
        "stage": "repair_execution",
        "source_sacg_state": str(source_state),
        "run_dir": str(run_dir),
        "repair_step_id": step.get("id"),
        "repair_scope": step.get("scope"),
        "repair_kind": action.get("repair_kind"),
        "debug_layer": action.get("debug_layer") or step.get("debug_layer"),
        "verification_scope": verification_scope,
        "single_layer_harness_required": require_single_layer,
        "exact_board_integration_required": board_integration_repair,
        "board_memory_runtime_preparation": board_memory_runtime_preparation,
        "checkpoint_framework_authority_recovery": checkpoint_framework_recovery,
        "current_preflight_execution_authority": (
            current_preflight_execution_authority
        ),
        "generation_mode": (
            "single_layer_compile_rtl_repair"
            if single_layer_compile_rtl_repair
            else "board_semantic_rtl_repair"
            if board_semantic_rtl_repair
            else
            "bootstrap"
            if board_bootstrap_required
            else "preflight_repair"
            if board_integration_repair
            and current_board_preflight_feedback.get("status") == "ready"
            and current_patch_application_feedback.get("status") != "ready"
            else "repair"
            if generated_sources
            else "create"
        ),
        "current_board_preflight_feedback": current_board_preflight_feedback,
        "current_patch_application_feedback": current_patch_application_feedback,
        "stage_id": stage_id,
        "target_modules": target_modules,
        "violated_contract": action.get("violated_contract"),
        "repair_gate": action.get("repair_gate"),
        "failed_current_layer_gates": action.get("failed_current_layer_gates", []),
        "current_board_to_lower_layer_contradiction": (
            current_board_to_lower_layer_contradiction
        ),
        "reference_builder_tool": {
            "role": builder_role,
            "name": builder_spec.get("name") if builder_spec else None,
            "kind": builder_spec.get("kind") if builder_spec else None,
            "capabilities": builder_spec.get("capabilities", []) if builder_spec else [],
        },
        "reference_builder_probe": builder_probe,
        "capability_tool": {
            "role": capability_role,
            "name": capability_spec.get("name") if capability_spec else None,
            "kind": capability_spec.get("kind") if capability_spec else None,
            "capabilities": capability_spec.get("capabilities", []) if capability_spec else [],
        },
        "capability_analyzer_tool": {
            "role": capability_analyzer_role or None,
            "name": capability_analyzer_spec.get("name") if capability_analyzer_spec else None,
            "kind": capability_analyzer_spec.get("kind") if capability_analyzer_spec else None,
            "capabilities": (
                capability_analyzer_spec.get("capabilities", [])
                if capability_analyzer_spec
                else []
            ),
        },
        "capability_probe": capability_probe,
        "pre_patch_simulation_checkpoint_request": {
            key: pre_patch_checkpoint_preparation.get(key)
            for key in (
                "status",
                "summary",
                "request_path",
                "request_sha256",
                "remote_tool_must_not_start",
            )
            if pre_patch_checkpoint_preparation.get(key) is not None
        },
        "focused_real_tool_failure_snapshot": str(failure_snapshot) if failure_snapshot else None,
        "pre_patch_dependency_refresh": pre_patch_dependency_refresh,
        "capability_reports": produced_reports,
        "leaf_stage_report_path": str(leaf_report_path) if leaf_report_path else None,
        "leaf_stage_report_summary": summarize_leaf_report(leaf_stage_report, target_modules[0] if target_modules else "") if leaf_stage_report else {},
        "generated_sources": generated_sources,
        "template_candidates": sorted({path for module in target_modules for path in template_candidates_for_module(module)}),
        "repair_source_bundle": source_bundle,
        "single_layer_compile_rtl_repair": (
            copy.deepcopy(single_layer_compile_context)
            if single_layer_compile_rtl_repair
            else None
        ),
        "fpga_ip_repair_closure": fpga_ip_repair_closure,
        "prior_localized_agent_feedback": (
            {
                "path": str(prior_localized_agent_path),
                "summary": prior_localized_agent_result.get("output", {}).get("summary"),
                "root_cause": prior_localized_agent_result.get("output", {}).get("root_cause"),
                "blocked_reasons": prior_localized_agent_result.get("output", {}).get("blocked_reasons", []),
            }
            if localized_template_instrumentation_only
            and isinstance(prior_localized_agent_result.get("output"), dict)
            else None
        ),
        "policy": {
            "do_not_treat_missing_golden_as_hardware_pass": True,
            "repair_checker_or_golden_reference_before_layer_promotion": True,
            "after_capability_repair_rerun_same_layer_leaf_golden": True,
            "do_not_modify_golden_to_match_buggy_rtl": True,
            "random_generation_is_input_only": True,
            "expected_output_must_come_from_target_model_inference": True,
            "weight_file_presence_does_not_prove_dut_consumption": True,
            "preserve_checkpoint_input_reference_numeric_policy_and_tolerance_hashes": True,
            "preserve_exact_user_sample_wrapper_hashes": True,
            "repair_dut_loader_harness_or_instrumentation": True,
            "close_proven_simulation_only_observability_defects_in_same_atomic_patch": True,
            "empty_generated_sources_is_valid_for_first_create": True,
            "semantic_selected_template_repair_approved": semantic_template_repair_approved(),
        },
    }
    if completed_producer_evidence:
        package["prior_capability_producer_evidence"] = completed_producer_evidence
    package["current_single_layer_real_tool_failure"] = (
        copy.deepcopy(single_layer_real_tool_handoff)
        if single_layer_real_tool_handoff is not None
        else None
    )
    package["current_single_layer_pipeline_trace_record"] = (
        copy.deepcopy(single_layer_pipeline_trace)
        if single_layer_pipeline_trace is not None
        else None
    )
    if repair_agent_disposition is not None:
        package["current_repair_agent_disposition"] = repair_agent_disposition
    if single_layer_pipeline_trace is not None:
        package["candidate_stage_ids"] = copy.deepcopy(
            single_layer_pipeline_trace.get("candidate_stage_ids", [])
        )
        package["candidate_template_sources"] = copy.deepcopy(
            single_layer_pipeline_trace.get("candidate_template_sources", [])
        )
    # Layer-3 functional repair runs at the discovered compute-slot AXI
    # boundary. Physical MIG/RDIMM sources remain board identity/backend
    # evidence and are intentionally not materialized into this VCS loop.
    external_fixture_preparation = {
        "status": "not_required" if board_integration_repair else "not_run",
        "blockers": [],
        "reason": (
            "compute_slot_axi_functional_boundary"
            if board_integration_repair
            else "not_a_board_integration_repair"
        ),
    }
    package["external_simulation_fixture_preparation"] = {
        key: copy.deepcopy(value)
        for key, value in external_fixture_preparation.items()
        if key != "artifact"
    }
    if board_integration_repair:
        if not board_bootstrap_required:
            package["exact_board_repair_attempt_history"] = (
                exact_board_repair_attempt_history(run_dir)
            )
        package["exact_board_integration_repair_context"] = board_integration_repair_context(
            state,
            run_dir,
            external_fixture_preparation,
            explicit_checkpoint_maintenance=explicit_checkpoint_maintenance,
        )
        if current_board_preflight_feedback.get("status") == "ready":
            package["current_board_preflight_feedback"] = copy.deepcopy(
                current_board_preflight_feedback
            )
        elif generated_sources and not board_bootstrap_required:
            package["current_board_vcs_feedback"] = copy.deepcopy(
                capability_probe.get("current_board_vcs_feedback")
                if isinstance(capability_probe.get("current_board_vcs_feedback"), dict)
                else exact_board_vcs_feedback(
                    case_adapter,
                    run_dir,
                    capability_spec,
                    capability_analyzer_spec,
                )
            )
        if not board_bootstrap_required:
            package["adaptive_observation_state"] = (
                materialize_adaptive_observation_evidence(
                    run_dir,
                    package.get("current_board_vcs_feedback", {})
                    if isinstance(package.get("current_board_vcs_feedback"), dict)
                    else {},
                )
            )
        package["adaptive_observation_routing"] = adaptive_observation_routing_state(
            package
        )
        compiled_signal_catalog = load_or_build_compiled_signal_catalog(run_dir)
        package["compiled_signal_catalog"] = catalog_prompt_projection(
            compiled_signal_catalog
        )
        # An incomplete boundary trace is useful context for the LLM, but it
        # does not turn the framework into a second decision-maker.  The LLM
        # may pair a functional repair with broader observations in one
        # transaction, and the executor must not split or veto that choice.
        adaptive_state = package.get("adaptive_observation_state", {})
        observation_incomplete = (
            isinstance(adaptive_state, dict)
            and adaptive_state.get("compiled_probe_sources_bound") is not True
        )
        if (
            board_semantic_rtl_repair
            and (
                package["adaptive_observation_routing"].get("status")
                == "complete_boundary_coverage_required"
                or observation_incomplete
            )
        ):
            package["board_observation_guidance"] = {
                "status": "advisory",
                "source_rtl_edit_authorized": True,
                "reason": (
                    "current real VCS evidence has observed internal transfers, "
                    "but boundary counters/payloads are incomplete"
                ),
                "recommended_action": (
                    "let the LLM choose the smallest functional repair and any "
                    "additional generated-testbench observations in one transaction"
                ),
            }
    package_path = out_dir / f"{safe_step_id(step)}_verification_capability_repair_package.json"
    write_json(package_path, package)
    if board_integration_repair:
        # Layer 2 is already certified.  A Layer-3 trace can inform the current
        # repair prompt, but it must never schedule another Layer-2 run or stop
        # the board observe -> repair -> VCS loop.
        package["lower_layer_backtrack"] = {
            "status": "disabled",
            "reason": "reuse certified Layer-2 result; continue current Layer-3 repair",
        }
        write_json(package_path, package)
    if board_integration_repair and board_memory_runtime_preparation.get("status") != "pass":
        preparation_path = Path(
            str(board_memory_runtime_preparation.get("path") or "")
        )
        preparation_feedback = repair_feedback_artifact_reference(
            preparation_path,
            kind="exact_board_memory_runtime_preparation",
            step=step,
            verification_scope=verification_scope,
        )
        return {
            "status": "fail",
            "summary": "exact-board memory/runtime planning or full real-weight image preparation has not passed",
            "context_package": str(package_path),
            "reference_builder_log": builder_probe.get("log_path"),
            "capability_probe_log": capability_probe.get("log_path"),
            "post_patch_capability_probe_log": capability_probe.get("log_path"),
            "capability_reports": produced_reports,
            "llm_record": board_memory_runtime_preparation.get("llm_record"),
            "board_memory_runtime_preparation": board_memory_runtime_preparation.get("path"),
            "repair_feedback_artifacts": (
                [preparation_feedback] if preparation_feedback is not None else []
            ),
            "stage_passed": False,
            "target_modules": target_modules,
            "framework_action_required": (
                "feed the deterministic preparation blockers back to the same single board memory/runtime planning agent"
            ),
        }
    if (
        board_integration_repair
        and not single_layer_compile_rtl_repair
        and generated_sources
        and not board_bootstrap_required
        and current_board_validation_evidence is None
        and current_patch_application_feedback.get("status") != "ready"
        and pending_checkpoint_executor_retry is None
        and pending_checkpoint_calibration is None
        and current_checkpoint_calibration_failure is None
        and package.get("current_board_preflight_feedback", {}).get("status")
        != "ready"
        and (
            package.get("current_board_vcs_feedback", {}).get("status") != "ready"
            or not exact_board_vcs_runner_feedback_is_current(
                package.get("current_board_vcs_feedback", {}),
                capability_spec,
                run_dir
                / "verification"
                / "board_simulation"
                / "board_simulation_manifest.json",
            )
        )
    ):
        preflight_ready_probe = run_current_capability_probe("preflight_ready")
        package["preflight_ready_capability_probe"] = preflight_ready_probe.get(
            "log_path"
        )
        write_json(package_path, package)
        capability_passed = preflight_ready_probe.get("status") == "pass"
        new_real_tool_failure_requires_agent = (
            exact_board_probe_requires_agent_continuation(preflight_ready_probe)
        )
        new_real_tool_failure_identity = (
            exact_board_probe_agent_handoff_identity(preflight_ready_probe)
        )
        return {
            "status": "pass" if capability_passed else "fail",
            "summary": preflight_ready_probe.get("summary")
            or "real exact-board VCS/analyzer chain completed",
            "context_package": str(package_path),
            "reference_builder_log": builder_probe.get("log_path"),
            "capability_probe_log": preflight_ready_probe.get("log_path"),
            "post_patch_capability_probe_log": preflight_ready_probe.get("log_path"),
            "capability_reports": preflight_ready_probe.get(
                "produced_reports", produced_reports
            ),
            "leaf_stage_report": (
                str(leaf_report_path) if leaf_report_path else None
            ),
            "llm_record": None,
            "agent_patch_application": None,
            "agent_requested_validation": None,
            "dut_weight_binding_materialization": str(
                out_dir / "dut_weight_binding_materialization.json"
            ),
            "stage_passed": capability_passed,
            "target_modules": target_modules,
            "new_current_real_tool_failure_requires_agent": (
                new_real_tool_failure_requires_agent
            ),
            "new_current_real_tool_failure_identity_sha256": (
                new_real_tool_failure_identity
            ),
        }
    if (
        board_integration_repair
        and not single_layer_compile_rtl_repair
        and generated_sources
        and not board_bootstrap_required
        and package.get("current_board_vcs_feedback", {}).get("status") != "ready"
        and package.get("current_board_preflight_feedback", {}).get("status")
        != "ready"
        and current_patch_application_feedback.get("status") != "ready"
        and pending_checkpoint_executor_retry is None
        and pending_checkpoint_calibration is None
        and current_checkpoint_calibration_failure is None
    ):
        return {
            "status": "fail",
            "summary": "existing exact-board sources cannot be repaired without current VCS runner and analyzer reports",
            "context_package": str(package_path),
            "capability_probe_log": capability_probe.get("log_path"),
            "capability_reports": produced_reports,
            "stage_passed": False,
            "target_modules": target_modules,
            "framework_action_required": "rerun the existing real board VCS plus analyzer chain without changing RTL",
        }
    if broad_semantic_phase_requested(action, resource_resume):
        phase_result = execute_semantic_template_repair_phase(
            source_bundle=source_bundle,
            source_state=source_state,
            step=step,
            run_dir=run_dir,
            out_dir=out_dir,
            timeout_sec=timeout_sec,
        )
        if phase_result is not None:
            package["semantic_template_repair_phase"] = phase_result.get("semantic_template_repair_phase")
            package["agent_patch_application"] = phase_result.get("agent_patch_application")
            package["agent_requested_validation"] = phase_result.get("agent_requested_validation")
            write_json(package_path, package)
            return {
                **phase_result,
                "context_package": str(package_path),
                "reference_builder_log": builder_probe.get("log_path"),
                "capability_probe_log": capability_probe.get("log_path"),
                "post_patch_capability_probe_log": capability_probe.get("log_path"),
                "capability_reports": produced_reports,
                "leaf_stage_report": str(leaf_report_path) if leaf_report_path else None,
                "target_modules": target_modules,
            }
    if prior_resource_validation_resume_allowed(
        resource_resume_status=str(resource_resume.get("status") or ""),
        resume_requires_board_repair=resume_requires_board_repair,
        has_pending_checkpoint_executor_retry=(
            pending_checkpoint_executor_retry is not None
        ),
        has_pending_checkpoint_calibration=(
            pending_checkpoint_calibration is not None
        ),
        has_current_checkpoint_calibration_failure=(
            current_checkpoint_calibration_failure is not None
        ),
        has_current_source_validation_evidence=bool(
            current_board_validation_evidence is not None
            and current_board_validation_evidence.get(
                "frozen_failed_runner_evidence_reused"
            )
            is not True
            and (
                resource_resume.get("applied_patch_checkpoint_reused") is not True
                or current_board_evidence_postdates_applied_patch(
                    current_board_validation_evidence,
                    out_dir,
                )
            )
        ),
    ):
        operator_leaf_certificate_continuity_before_materialization = (
            reconcile_operator_leaf_certificate_scope_continuity(run_dir, out_dir)
            if resource_resume.get("status") == "pass"
            and require_single_layer
            and not board_integration_repair
            else {
                "status": "not_run",
                "summary": (
                    "operator-leaf continuity reconciliation is only needed while "
                    "resuming a connected-layer repair"
                ),
            }
        )
        pre_materialization_dependency_refresh = (
            run_capability_probe(
                case_adapter=case_adapter,
                spec_role=dependency_role,
                spec=dependency_spec,
                run_dir=run_dir,
                step=step,
                out_dir=out_dir,
                timeout_sec=timeout_sec,
                label="binding_requirements_resource_resume",
            )
            if resource_resume.get("status") == "pass"
            and require_single_layer
            and dependency_spec
            and not connected_binding_requirements_ready(run_dir)
            else {
                "status": "not_run",
                "summary": (
                    "connected binding requirements are already current"
                    if connected_binding_requirements_ready(run_dir)
                    else "no pre-materialization connected-contract refresh is required"
                ),
            }
        )
        if resource_resume.get("status") == "pass":
            if pre_materialization_dependency_refresh.get("status") not in {
                "pass",
                "not_run",
            }:
                resumed_materialization = {
                    "status": "blocked",
                    "blockers": [
                        "connected weight/runtime requirements refresh failed"
                    ],
                }
            elif resumed_materialization_checkpoint.get("status") != "not_run":
                resumed_materialization = resumed_materialization_checkpoint
            else:
                resumed_materialization = finalize_dut_weight_binding_manifest(
                    run_dir,
                    out_dir,
                    require_single_layer=require_single_layer,
                    require_board=board_integration_repair,
                    single_layer_certificate_path=single_layer_certificate_path,
                )
        else:
            resumed_materialization = {
                "status": "not_run",
                "blockers": ["resource-resumed agent validation did not pass"],
            }
        operator_leaf_certificate_continuity_after_materialization = (
            reconcile_operator_leaf_certificate_scope_continuity(run_dir, out_dir)
            if resource_resume.get("status") == "pass"
            and resumed_materialization.get("status") == "pass"
            and require_single_layer
            and not board_integration_repair
            else {
                "status": "not_run",
                "summary": (
                    "operator-leaf continuity reconciliation requires a passing "
                    "connected-layer binding materialization"
                ),
            }
        )
        resumed_dependency_refresh = (
            run_capability_probe(
                case_adapter=case_adapter,
                spec_role=dependency_role,
                spec=dependency_spec,
                run_dir=run_dir,
                step=step,
                out_dir=out_dir,
                timeout_sec=timeout_sec,
                label="dependency_refresh_resource_resume",
            )
            if resumed_materialization.get("status") == "pass" and dependency_spec
            else {
                "status": "not_run" if not dependency_spec else "blocked",
                "summary": "dependency refresh requires passing binding materialization",
            }
        )
        before_trace_snapshot = (
            semantic_trace_report_snapshot(leaf_report_path)
            if leaf_report_path is not None
            else {"exists": False, "trace_signatures": []}
        )
        resumed_probe = (
            run_current_capability_probe("resource_resume")
            if resumed_materialization.get("status") == "pass"
            and resumed_dependency_refresh.get("status") in {"pass", "not_run"}
            else capability_probe
        )
        instrumentation_evidence = (
            localized_instrumentation_probe_evidence(
                leaf_report_path,
                before_trace_snapshot,
                stage_id,
            )
            if leaf_report_path is not None
            and (localized_instrumentation_only or localized_template_instrumentation_only)
            and resumed_materialization.get("status") == "pass"
            else {
                "status": "not_run",
                "summary": "current repair step is not an instrumentation evidence collection step",
            }
        )
        candidate_single_layer_real_tool_handoff = (
            single_layer_probe_agent_handoff(resumed_probe)
            if resource_resume.get("status") == "pass"
            and not board_integration_repair
            else None
        )
        single_layer_pipeline_trace = (
            single_layer_pipeline_trace_record(
                run_dir, candidate_single_layer_real_tool_handoff
            )
            if candidate_single_layer_real_tool_handoff is not None
            else None
        )
        single_layer_real_tool_handoff = (
            candidate_single_layer_real_tool_handoff
            if single_layer_pipeline_trace is not None
            else None
        )
        package["prior_resource_validation_resume"] = resource_resume
        package["operator_leaf_certificate_continuity_before_materialization"] = (
            operator_leaf_certificate_continuity_before_materialization
        )
        package["operator_leaf_certificate_continuity_after_materialization"] = (
            operator_leaf_certificate_continuity_after_materialization
        )
        package["resource_resume_pre_materialization_dependency_refresh"] = (
            pre_materialization_dependency_refresh.get("log_path")
        )
        package["resource_resume_binding_materialization"] = resumed_materialization.get("path")
        package["resource_resume_dependency_refresh"] = resumed_dependency_refresh.get("log_path")
        package["resource_resume_capability_probe"] = resumed_probe.get("log_path")
        package["localized_instrumentation_evidence"] = instrumentation_evidence
        package["current_single_layer_real_tool_failure"] = (
            copy.deepcopy(single_layer_real_tool_handoff)
            if single_layer_real_tool_handoff is not None
            else None
        )
        package["current_single_layer_pipeline_trace_record"] = (
            copy.deepcopy(single_layer_pipeline_trace)
            if single_layer_pipeline_trace is not None
            else None
        )
        write_json(package_path, package)
        if resumed_probe.get("status") == "pass" or instrumentation_evidence.get("status") == "pass":
            stage_passed = resumed_probe.get("status") == "pass"
            return {
                "status": "pass",
                "summary": (
                    f"{capability_spec.get('name') if capability_spec else capability_role} verification "
                    "capability probe passed after resuming the unchanged agent patch with corrected tool resources"
                    if stage_passed
                    else instrumentation_evidence.get("summary")
                ),
                "context_package": str(package_path),
                "reference_builder_log": builder_probe.get("log_path"),
                "capability_probe_log": capability_probe.get("log_path"),
                "post_patch_capability_probe_log": resumed_probe.get("log_path"),
                "capability_reports": resumed_probe.get("produced_reports", produced_reports),
                "leaf_stage_report": str(leaf_report_path) if leaf_report_path else None,
                "llm_record": None,
                "agent_patch_application": str(out_dir / "agent_patch_application.json"),
                "agent_requested_validation": resource_resume.get("path"),
                "dut_weight_binding_materialization": resumed_materialization.get("path"),
                "stage_passed": stage_passed,
                "instrumentation_evidence_collected": instrumentation_evidence.get("status") == "pass",
                "instrumentation_evidence": instrumentation_evidence,
                "target_modules": target_modules,
            }
        if resource_resume.get("status") == "pass" and board_integration_repair:
            capability_probe = resumed_probe
            produced_reports = (
                resumed_probe.get("produced_reports", [])
                if isinstance(resumed_probe.get("produced_reports"), list)
                else []
            )
            package["capability_probe"] = resumed_probe
            package["capability_reports"] = produced_reports
            current_feedback = resumed_probe.get("current_board_vcs_feedback")
            if isinstance(current_feedback, dict):
                package["current_board_vcs_feedback"] = copy.deepcopy(
                    current_feedback
                )
                persist_current_exact_board_failed_attempt(
                    run_dir,
                    current_feedback,
                    patch_application=read_json_if_exists(
                        out_dir / "agent_patch_application.json"
                    ),
                    llm_record=read_json_if_exists(
                        out_dir
                        / "llm"
                        / "exact_board_integration_generation_agent_result.json"
                    ),
                )
            write_json(package_path, package)
        elif (
            resource_resume.get("status") == "pass"
            and single_layer_real_tool_handoff is not None
        ):
            capability_probe = resumed_probe
            produced_reports = (
                resumed_probe.get("produced_reports", [])
                if isinstance(resumed_probe.get("produced_reports"), list)
                else []
            )
            package["capability_probe"] = resumed_probe
            package["capability_reports"] = produced_reports
            package["debug_layer"] = "single_transformer_layer_kernel"
            assert single_layer_pipeline_trace is not None
            record = single_layer_pipeline_trace
            action, step, stage_id, target_modules = (
                localized_single_layer_repair_route(
                    action,
                    step,
                    record,
                    single_layer_real_tool_handoff,
                )
            )
            localized_semantic_repair = True
            localized_instrumentation_only = False
            localized_template_instrumentation_only = False
            package["repair_kind"] = action["repair_kind"]
            package["stage_id"] = stage_id
            package["target_modules"] = target_modules
            package["candidate_stage_ids"] = record.get(
                "candidate_stage_ids", []
            )
            package["candidate_template_sources"] = record.get(
                "candidate_template_sources", []
            )
            package["violated_contract"] = action["violated_contract"]
            write_json(package_path, package)
        elif resource_resume.get("status") == "pass":
            return {
                "status": "fail",
                "summary": (
                    f"the unchanged applied patch replay did not pass and did not produce fresh internal evidence "
                    f"for {stage_id or '<unknown stage>'}"
                ),
                "context_package": str(package_path),
                "reference_builder_log": builder_probe.get("log_path"),
                "capability_probe_log": capability_probe.get("log_path"),
                "post_patch_capability_probe_log": resumed_probe.get("log_path"),
                "capability_reports": resumed_probe.get("produced_reports", produced_reports),
                "leaf_stage_report": str(leaf_report_path) if leaf_report_path else None,
                "llm_record": None,
                "agent_patch_application": str(out_dir / "agent_patch_application.json"),
                "agent_requested_validation": resource_resume.get("path"),
                "dut_weight_binding_materialization": resumed_materialization.get("path"),
                "stage_passed": False,
                "instrumentation_evidence_collected": False,
                "instrumentation_evidence": instrumentation_evidence,
                "target_modules": target_modules,
            }
    localized_focus_stage_ids = {
        str(value)
        for value in record.get("candidate_stage_ids", [])
        if str(value)
    }
    if localized_semantic_repair and stage_id and not localized_focus_stage_ids:
        localized_focus_stage_ids = {stage_id}
    source_bundle = capability_repair_source_bundle(
        source_bundle,
        run_dir,
        out_dir,
        focus_stage_ids=(
            localized_focus_stage_ids if localized_semantic_repair else None
        ),
        verification_scope=verification_scope,
        include_operator_leaf_failure_context=localized_semantic_repair,
    ) if not board_semantic_rtl_repair else source_bundle
    board_semantic_rtl_authority = None
    if board_semantic_rtl_repair:
        board_semantic_rtl_authority = (
            copy.deepcopy(single_layer_compile_context.get("authority", {}))
            if single_layer_compile_rtl_repair
            else board_semantic_rtl_repair_authority(
                run_dir,
                action,
                package,
            )
        )
        package["board_semantic_rtl_repair_authority"] = copy.deepcopy(
            board_semantic_rtl_authority
        )
        if board_semantic_rtl_authority.get("status") != "ready":
            authority_path = out_dir / "board_semantic_rtl_repair_authority.json"
            write_json(authority_path, board_semantic_rtl_authority)
            package["board_semantic_rtl_repair_authority_artifact"] = {
                "path": str(authority_path),
                "sha256": sha256_file(authority_path),
            }
            write_json(package_path, package)
            return {
                "status": "blocked",
                "summary": (
                    "current board semantic RTL repair authority is blocked; "
                    "no source edit or board VCS run is allowed"
                ),
                "blocked_reasons": board_semantic_rtl_authority.get(
                    "blockers", []
                ),
                "framework_action_required": True,
                "context_package": str(package_path),
                "capability_probe_log": capability_probe.get("log_path"),
                "capability_reports": produced_reports,
                "stage_passed": False,
                "target_modules": target_modules,
            }
        source_bundle = copy.deepcopy(
            board_semantic_rtl_authority.get("source_bundle", {})
        )
    if localized_semantic_repair:
        source_bundle = authorize_localized_semantic_repair_bundle(
            source_bundle,
            run_dir,
            record,
            instrumentation_only=localized_instrumentation_only,
            template_instrumentation_only=localized_template_instrumentation_only,
            corroborating_numeric_failure=(
                action.get("corroborating_semantic_numeric_failure")
                if isinstance(action.get("corroborating_semantic_numeric_failure"), dict)
                else None
            ),
        )
    if board_integration_repair and external_fixture_preparation.get("status") == "pass":
        source_bundle, fixture_source_blockers = add_external_fixture_sources_to_repair_bundle(
            source_bundle,
            external_fixture_preparation.get("artifact", {}),
        )
        if fixture_source_blockers:
            context = package.get("exact_board_integration_repair_context", {})
            if isinstance(context, dict):
                context["status"] = "blocked"
                context.setdefault("blockers", []).extend(
                    f"external simulation fixture source bundle: {value}"
                    for value in fixture_source_blockers
                )
    package["repair_source_bundle"] = source_bundle
    package["semantic_template_baseline"] = {
        "status": (
            "localized_repair_authorized"
            if source_bundle.get("editable_contract", {}).get("localized_semantic_repair_authorized")
            else "compiled_read_only"
        ),
        "progress": str(out_dir / "semantic_template_repair_progress.json"),
        "repair_deferred_until_real_localized_failure": not localized_semantic_repair,
        "pre_existing_emitted_systemverilog_is_not_the_harness_source": True,
    }
    try:
        experience_sync = sync_recent_repair_experience(run_dir)
        experience_query = build_repair_experience_query(package)
        relevant_experience = retrieve_repair_experience(
            run_dir,
            experience_query,
        )
        relevant_experience["sync"] = experience_sync
        project_knowledge_query = build_project_knowledge_query(package)
        relevant_project_knowledge = retrieve_project_knowledge(
            run_dir,
            project_knowledge_query,
            exclude_experience_ids={
                str(row.get("experience_id"))
                for row in relevant_experience.get("episodes", [])
                if isinstance(row, dict) and row.get("experience_id")
            },
        )
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        relevant_experience = {
            "schema_version": "spatialaccagent.repair_experience_context.v2",
            "status": "unavailable",
            "selected_count": 0,
            "episodes": [],
            "summary": str(exc),
            "policy": {
                "experience_is_optional_and_never_weakens_current_validation": True,
            },
        }
        relevant_project_knowledge = {
            "schema_version": "spatialaccagent.project_knowledge_context.v1",
            "status": "unavailable",
            "selected_count": 0,
            "knowledge": [],
            "summary": str(exc),
            "policy": {
                "knowledge_is_optional_and_never_weakens_current_validation": True,
            },
        }
    package["relevant_repair_experience"] = relevant_experience
    package["relevant_project_knowledge"] = relevant_project_knowledge
    package.setdefault("policy", {})[
        "repair_experience_is_hypothesis_prior_only"
    ] = True
    package.setdefault("policy", {})[
        "project_knowledge_requires_current_evidence_rebinding"
    ] = True
    generation_attempts: list[dict[str, Any]] = []
    llm_package = package
    llm_repair_step = (
        localized_repair_step_projection(step) if localized_semantic_repair else step
    )
    checkpoint_capability_repair_required = False
    checkpoint_specialist_required_files: set[Path] | None = None
    checkpoint_specialist_required_noop_merges: dict[
        Path, dict[str, Any]
    ] | None = None
    generation_mode = ""
    if board_integration_repair:
        generation_mode = str(package.get("generation_mode") or "create")
        package["exact_board_generation_policy"] = {
            "agent": EXACT_BOARD_GENERATION_AGENT,
            "maximum_generation_calls_per_execution": 1,
            "lifecycle_wrapper_owner": EXACT_BOARD_GENERATION_AGENT,
            "post_generation_dynamic_validation": "mandatory",
        }
        llm_package = copy.deepcopy(package)
        if single_layer_compile_rtl_repair:
            violated_contract = "single_layer_vcs_compile_must_pass_before_board_vcs"
            reason = (
                "The mandatory single-layer semantic gate failed during VCS compilation. "
                "Repair only the diagnostic generated semantic RTL interface files from the "
                "source-bound compile package, then let the framework rerun the real single-layer "
                "VCS gate. Do not edit the board wrapper, testbench, AXI/DDR logic, data, or manifests."
            )
            llm_package["generation_phase_contract"] = {
                "status": "repair_single_layer_compile_failure",
                "generate_files_now": False,
                "repair_existing_files_now": True,
                "board_vcs_before_single_layer_pass": False,
                "mandatory_followup_gate": "case_single_layer_functional",
                "allowed_exact_files": copy.deepcopy(
                    single_layer_compile_context.get("editable_paths", [])
                ),
            }
            llm_package["violated_contract"] = violated_contract
        elif generation_mode in {"create", "bootstrap"}:
            for key in (
                "capability_probe",
                "capability_reports",
                "pre_patch_dependency_refresh",
                "failed_current_layer_gates",
                "focused_real_tool_failure_snapshot",
                "generated_sources",
            ):
                llm_package.pop(key, None)
            llm_package["violated_contract"] = (
                "missing_board_shell_must_be_generated_before_real_tool_execution"
            )
            llm_package["generation_phase_contract"] = {
                "status": "generation_required_before_probe",
                "generate_files_now": True,
                "pre_generation_capability_probe": "not_applicable",
                "post_generation_preflight_and_real_vcs": "mandatory",
                "missing_generated_files_or_execution_reports_must_not_block_generation": True,
                "new_source_hash_materialization": {
                    "owner": "framework_after_atomic_file_edits",
                    "manifest_source_sha256_may_be_omitted_for_new_files": True,
                    "framework_recomputes_and_inserts_actual_sha256": True,
                    "guessed_or_symbolic_hashes_forbidden": True,
                },
            }
            violated_contract = "missing_board_shell_must_be_generated_before_real_tool_execution"
            reason = (
                "Generate the missing exact-board shell and binding artifacts now; "
                "the framework runs their real-tool gates only after materialization."
            )
        else:
            patch_application_feedback_ready = (
                llm_package.get("current_patch_application_feedback", {}).get(
                    "status"
                )
                == "ready"
            )
            preflight_feedback_ready = (
                llm_package.get("current_board_preflight_feedback", {}).get(
                    "status"
                )
                == "ready"
            )
            vcs_feedback_ready = (
                llm_package.get("current_board_vcs_feedback", {}).get("status")
                == "ready"
            )
            phase_contract = {
                "status": (
                    "repair_deterministic_preflight"
                    if generation_mode == "preflight_repair"
                    else "repair_existing_board_sources"
                ),
                "generate_files_now": False,
                "repair_existing_files_now": True,
                "current_preflight_feedback_ready": preflight_feedback_ready,
                "current_vcs_feedback_ready": vcs_feedback_ready,
                "current_patch_application_feedback_ready": (
                    patch_application_feedback_ready
                ),
                "current_vcs_runner_and_diagnosis_required": not preflight_feedback_ready,
                "post_repair_preflight_real_vcs_and_analyzer": "mandatory",
                "new_source_hash_materialization": {
                    "owner": "framework_after_atomic_file_edits",
                    "replace_text_uses_exact_unique_anchors": True,
                    "complete_replace_or_merge_json_requires_pre_edit_sha256": True,
                    "framework_recomputes_and_inserts_actual_sha256": True,
                },
            }
            llm_package["generation_phase_contract"] = phase_contract
            package["generation_phase_contract"] = copy.deepcopy(phase_contract)
            if patch_application_feedback_ready:
                patch_application_value = (
                    llm_package["current_patch_application_feedback"]
                    .get("patch_application", {})
                    .get("value", {})
                )
                prior_failed_candidate_rejected = isinstance(
                    patch_application_value.get(
                        "rejected_prior_failed_board_attempt"
                    ),
                    dict,
                )
                violated_contract = str(
                    llm_package["current_patch_application_feedback"].get(
                        "summary"
                    )
                    or "agent_file_edits_must_materialize_atomically"
                )
                reason = (
                    "The immediately preceding semantic candidate exactly restored a board-source state already "
                    "disproven by real VCS, so no file was written and that intervention is forbidden. Use the "
                    "current raw trace and failed-intervention outcome to return a causally distinct edit or "
                    "read-only observation with a different predicted distinction; otherwise return blocked."
                    if prior_failed_candidate_rejected
                    else
                    "Correct the earliest current atomic patch-materialization failure against the unchanged "
                    "source. For replace_text, return exact unique anchors without a source hash; no prior edit "
                    "was applied."
                )
            elif preflight_feedback_ready:
                violated_contract = "exact_board_manifest_and_preflight_must_pass"
                reason = (
                    "Repair every current deterministic finalizer/preflight blocker whose correction is fully "
                    "determined by the supplied immutable evidence and fits the minimal authorized file set. Group "
                    "duplicate symptoms by their common root contract and return one internally consistent set of "
                    "complete replacements with exact pre-edit hashes; do not split independent manifest corrections "
                    "across LLM calls. Leave only blockers that require new evidence or a later real-tool result. The "
                    "framework will rerun preflight before starting the same real board VCS chain."
                )
            else:
                violated_contract = str(
                    action.get("violated_contract")
                    or "exact_board_real_vcs_and_analyzer_must_pass"
                )
                reason = (
                    "Repair the earliest current VCS/analyzer failure in the existing agent-created exact-board "
                    "sources using their complete contents and exact unique anchors; rerun the same real board chain."
                )
            checkpoint_gap = (
                llm_package.get("exact_board_integration_repair_context", {})
                .get("adaptive_design_inputs", {})
                .get("simulation_checkpoint_capability_gap", {})
                if isinstance(
                    llm_package.get("exact_board_integration_repair_context", {}),
                    dict,
                )
                else {}
            )
            current_feedback = llm_package.get("current_board_vcs_feedback", {})
            current_diagnosis = (
                current_feedback.get("diagnosis", {})
                if isinstance(current_feedback, dict)
                else {}
            )
            current_diagnosis_value = (
                current_diagnosis.get("value", {})
                if isinstance(current_diagnosis, dict)
                else {}
            )
            current_feedback_failure = str(
                current_diagnosis_value.get("failure_class", "")
                if isinstance(current_diagnosis_value, dict)
                else ""
            )
            if pending_checkpoint_executor_retry is not None:
                checkpoint_capability_repair_required = True
                violated_contract = (
                    "simulation_checkpoint_contract_and_hook_must_pass_before_hardware_repair"
                )
                reason = (
                    "Materialize the already completed hash-current Agent checkpoint-hook "
                    "transaction after the executor-only atomic no-op correction, then run "
                    "deterministic preflight and one real checkpoint validation."
                )
                llm_package["generation_phase_contract"][
                    "checkpoint_capability_repair_required"
                ] = True
                llm_package["generation_phase_contract"][
                    "hardware_rtl_repair_deferred_until_checkpoint_preflight"
                ] = True
                llm_package["generation_phase_contract"][
                    "executor_retry_reused_before_pre_patch_vcs"
                ] = True
            elif checkpoint_specialist_route_required(
                checkpoint_gap,
                current_feedback_failure,
                explicit_checkpoint_maintenance=(
                    explicit_checkpoint_maintenance
                ),
            ):
                checkpoint_capability_repair_required = True
                violated_contract = (
                    "simulation_checkpoint_contract_and_hook_must_pass_before_hardware_repair"
                )
                runtime_checkpoint_failure = checkpoint_gap.get(
                    "runtime_execution_failure", {}
                )
                if (
                    isinstance(runtime_checkpoint_failure, dict)
                    and runtime_checkpoint_failure.get("status") == "ready"
                ):
                    reason = (
                        "Repair the current simulation-only checkpoint hook from the hash-bound real VCS runtime "
                        "failure: the requested semantic trigger was observed, but capture/restore artifacts did not "
                        "pass. Preserve the simultaneous hardware failure evidence and make no production-RTL edit "
                        "in this turn. Use the pre-authorized two-file atomic manifest/testbench patch, then let the "
                        "framework rerun deterministic preflight and real checkpoint validation."
                    )
                else:
                    reason = (
                        "Generate the complete current-testbench simulation-only checkpoint contract, DUT VPI hook, "
                        "external AXI/DDR/file/queue/RNG state serializer and factual capture/restore reports first. "
                        "Use the pre-authorized hash-bound merge_json manifest edit atomically with the testbench edit; "
                        "do not request human approval and do not return another production-RTL hypothesis in this "
                        "turn. The framework will preserve unrelated manifest fields and rerun checkpoint contract "
                        "preflight before any VCS job."
                    )
                llm_package["generation_phase_contract"][
                    "checkpoint_capability_repair_required"
                ] = True
                llm_package["generation_phase_contract"][
                    "hardware_rtl_repair_deferred_until_checkpoint_preflight"
                ] = True
            llm_package["violated_contract"] = violated_contract
        llm_repair_step = {
            "id": step.get("id"),
            "scope": step.get("scope"),
            "status": "ready_for_agent_patch",
            "debug_layer": (
                "single_transformer_layer_kernel"
                if single_layer_compile_rtl_repair
                else step.get("debug_layer") or action.get("debug_layer")
            ),
            "action": {
                "repair_kind": (
                    "single_layer_compile_rtl_repair"
                    if single_layer_compile_rtl_repair
                    else action.get("repair_kind")
                ),
                "repair_gate": action.get("repair_gate"),
                "target_modules": action.get("target_modules", []),
                "candidate_stage_ids": action.get("candidate_stage_ids", []),
                "candidate_template_sources": action.get(
                    "candidate_template_sources", []
                ),
                "root_candidate_is_unresolved": action.get(
                    "root_candidate_is_unresolved", False
                ),
                "violated_contract": violated_contract,
                "reason": reason,
            },
        }
        board_generation_task = (
            "Act as the single-layer semantic RTL implementation owner. Analyze the complete "
            "source-bound VCS compiler diagnostic and the current GatedMLP/Linear_4 RTL. Make the "
            "smallest interface-consistent generated semantic RTL edit that removes the actual compile "
            "error while preserving stream data, addr/last semantics, real weight consumption, and "
            "all target-model behavior. Return complete replacements only for the exact authorized files. "
            "Do not edit the board wrapper, board testbench, AXI/DDR logic, manifests, weights, runtime, "
            "golden data, or framework. The framework will update derived source hashes, run the real "
            "case_single_layer_functional VCS gate, and only then resume the board VCS chain."
            if single_layer_compile_rtl_repair
            else exact_board_agent_task(generation_mode)
        )
        if checkpoint_capability_repair_required:
            checkpoint_specialist = (
                copy.deepcopy(
                    pending_checkpoint_executor_retry["specialist_package"]
                )
                if pending_checkpoint_executor_retry is not None
                else checkpoint_hook_specialist_package(
                    llm_package,
                    run_dir,
                )
            )
            checkpoint_specialist_path = (
                out_dir / "checkpoint_hook_specialist_package.json"
            )
            write_json(checkpoint_specialist_path, checkpoint_specialist)
            package["checkpoint_hook_specialist_package"] = {
                "path": str(checkpoint_specialist_path),
                "sha256": sha256_file(checkpoint_specialist_path),
                "status": checkpoint_specialist.get("status"),
                "blockers": checkpoint_specialist.get("blockers", []),
            }
            llm_package = checkpoint_specialist
            checkpoint_specialist_required_files = {
                Path(str(value)).resolve()
                for value in checkpoint_specialist.get(
                    "atomic_edit_contract", {}
                ).get("allowed_and_required_paths", [])
                if str(value)
            }
            checkpoint_specialist_required_noop_merges = (
                checkpoint_specialist_required_noop_json_merges(
                    checkpoint_specialist
                )
            )
            board_generation_task = (
                "Act as the dedicated simulation-checkpoint hook specialist for the "
                "current generated layer-3 board testbench. Close only the supplied "
                "checkpoint capability gap with the exact two-file atomic patch, then "
                "leave deterministic preflight and real VCS execution to the framework."
            )
        elif not single_layer_compile_rtl_repair:
            # Board generation and repair always use the focused package. The
            # complete durable package remains on disk for recovery, while the
            # LLM receives one copy of the current authorities and editable sources.
            llm_package = compact_verification_capability_repair_package(llm_package)
    runtime_frontier_static_repair_guard = (
        current_board_runtime_frontier_static_repair_guard(package)
        if board_integration_repair
        else {"status": "not_applicable"}
    )
    if board_integration_repair:
        package["runtime_frontier_static_repair_guard"] = copy.deepcopy(
            runtime_frontier_static_repair_guard
        )
        llm_package["runtime_frontier_static_repair_guard"] = copy.deepcopy(
            runtime_frontier_static_repair_guard
        )
    board_signal_analysis_required = bool(
        board_integration_repair
        and generation_mode in {"repair", "observation_only", "board_semantic_rtl_repair"}
        and not checkpoint_capability_repair_required
        and isinstance(llm_package.get("current_board_vcs_feedback"), dict)
        and llm_package["current_board_vcs_feedback"].get("status") == "ready"
    )
    board_agent_output_schema = (
        IMPLEMENTATION_REPAIR_SCHEMA
        if single_layer_compile_rtl_repair
        else BOARD_SIGNAL_ANALYSIS_REPAIR_SCHEMA
        if board_signal_analysis_required
        else BOARD_INTEGRATION_REPAIR_SCHEMA
    )
    write_json(package_path, package)
    # Always ask the Agent against the current evidence.  Saved responses are
    # useful history, but replaying an old transaction can hide a new signal
    # frontier and can repeatedly recreate an obsolete edit rejection.
    retryable_llm_record: dict[str, Any] | None = None
    if retryable_llm_record is not None:
        print(
            "Reusing the current trusted Agent result after an "
            "executor-only atomic materialization correction.",
            flush=True,
        )
    source_bound_pipeline_overlap_repair = bool(
        localized_semantic_repair
        and record.get("failure_mode")
        in {
            "completed_pipeline_overlap_violation",
            "irreversible_stage_turnover_violation",
        }
    )
    if localized_template_instrumentation_only:
        localized_agent_task = (
            "Act as the hardware instrumentation owner for the single CCTG-localized template module. "
            "The prior implementation agent named missing internal observations. Add only bounded "
            "non-synthesized trace statements to the exact persistent/generated Scala pair without "
            "changing behavior, interfaces, state, arithmetic, or any other template."
        )
    elif source_bound_pipeline_overlap_repair:
        localized_agent_task = (
            "Act as the hardware implementation owner for this source-bound real-VCS Stage2 token-pipeline "
            "failure. The source-bound candidate stages and template pairs are an authorization ceiling, "
            "not a root-cause verdict. Compare their current implementations with the failed turnover and "
            "dependency-overlap evidence, select the smallest causally sufficient subset, and return complete "
            "byte-identical persistent/generated replacements only for that subset. If the evidence instead "
            "shows an immutable trace/acceptance-attribution defect or cannot distinguish a hardware cause, "
            "return blocked with the exact missing evidence or capability. The executor will enforce hashes, "
            "compile, re-elaborate, rematerialize bindings, and rerun the same real Stage2 VCS gate."
        )
    else:
        localized_agent_task = (
            "Act as the hardware implementation owner for this CCTG-localized operator semantic failure. "
            "Use the real VCS/golden record and complete selected Scala dependency closure to identify the "
            "smallest justified root cause. Return complete paired persistent/generated Scala replacements, "
            "or a bounded existing-harness instrumentation replacement when the first internal divergence "
            "still needs observation. The executor will enforce exact hashes, compile, re-elaborate, "
            "rematerialize bindings, and rerun the same real golden VCS stage."
        )
    llm_record = retryable_llm_record or run_stage_agent(
        agent=(
            SINGLE_LAYER_COMPILE_RTL_REPAIR_AGENT
            if single_layer_compile_rtl_repair
            else EXACT_BOARD_GENERATION_AGENT
            if board_integration_repair
            else "localized_semantic_template_instrumentation_agent"
            if localized_template_instrumentation_only
            else "localized_semantic_dut_repair_agent"
            if localized_semantic_repair
            else "verification_capability_repair_agent"
        ),
        stage="repair_execution",
        task=(
            board_generation_task
            if board_integration_repair
            else localized_agent_task
            if localized_semantic_repair
            else (
                "Act as the implementation owner for this bounded verification-capability repair. Analyze the real "
                "failed tool package and supplied current-run source bundle, then return complete create/replace file "
                "contents that implement or repair the semantic DUT harness and weight-binding contract. The executor "
                "will validate every path and expected hash, apply all edits atomically, materialize source hashes, "
                "and rerun the same capability tool. If the supplied source is insufficient, return status=blocked "
                "with exact missing facts instead of inventing a harness or claiming pass."
            )
        ),
        inputs={
            "source_sacg_state": str(source_state),
            "repair_step": llm_repair_step,
            "verification_capability_repair_package": llm_package,
        },
        out_dir=out_dir,
        fallback_summary="verification capability repair requires LLM analysis",
        output_schema=(
            board_agent_output_schema
            if board_integration_repair
            else IMPLEMENTATION_REPAIR_SCHEMA
        ),
        prompt_rules=(
            checkpoint_hook_prompt_rules()
            if checkpoint_capability_repair_required
            else (
                single_layer_compile_rtl_repair_prompt_rules()
                + current_single_layer_compile_source_prompt_rules(source_bundle)
            )
            if single_layer_compile_rtl_repair
            else board_semantic_rtl_repair_prompt_rules()
            if board_semantic_rtl_repair
            else board_integration_prompt_rules(generation_mode)
            if board_integration_repair
            else [
            "Return status=ready_to_apply only when file_edits contains a complete bounded implementation; otherwise return status=blocked and exact blocked_reasons.",
            "Treat relevant_repair_experience only as an evidence-bound hypothesis prior. A validated_success episode never proves the current design, never expands edit authority, and must be rebound to the current sources/contracts and rerun through the same real-tool gate. Do not repeat a falsified intervention without current distinguishing evidence.",
            *project_knowledge_prompt_rules(),
            "Every file edit must use a path allowed by repair_source_bundle.editable_contract. Use operation=create for a missing file and operation=replace for an existing file.",
            "Provide complete file contents, never snippets, prose patches, ellipses, or instructions for a human to finish.",
            "For a .json target, return content='' and the complete object in json_content so the executor serializes it deterministically. For every non-JSON target, omit json_content and return complete string content.",
            (
                "The semantic failure record is real executed evidence, but the failed stage output alone does not prove "
                "which internal submodule is defective. Prefer the smallest evidence-supported template correction; when "
                "that root is still ambiguous, edit only the existing semantic harness to expose decisive internal "
                "ready/valid/data or state evidence and request compile plus full harness re-elaboration before rerunning VCS."
                if localized_semantic_repair
                else "Keep the repair bounded to the supplied verification-capability gap."
            ),
            (
                "For a source-bound Stage2 pipeline-overlap violation, candidate_stage_ids and "
                "localized_candidate_template_pair_names are only the source-bound authorization ceiling. "
                "Choose the smallest causally sufficient subset from the current sources and failed turnover/dependency "
                "records; do not edit a candidate without a concrete causal argument. If the checker or trace attribution "
                "is the defect, return blocked with that exact required capability and leave immutable verification files unchanged."
                if source_bound_pipeline_overlap_repair
                else "Use the single source-bound root candidate supplied by the current localized record."
            ),
            (
                "This iteration is instrumentation-only by the authoritative repair-agent disposition. Do not edit any "
                "operator template. Replace only the existing semantic harness (and manifest only if its declared source "
                "contract must be updated), add bounded observations around the failed stage's internal submodule stream "
                "boundaries, and emit standard SPATIALACC_INTERNAL_TRACE records in the targeted failing beat window."
                if localized_instrumentation_only
                else (
                    "This iteration is localized-template instrumentation-only. Edit both hash-identical copies of the "
                    "single template listed in localized_template_instrumentation_pair_names and no other file. Add "
                    "bounded simulator trace around the prior agent's missing internal observations; preserve every "
                    "existing assignment, state transition, interface, and arithmetic expression byte-for-byte except "
                    "for marked trace statements needed to observe them. Enclose every added trace region between a "
                    "line containing only '// SPATIALACC_TEMPLATE_TRACE_BEGIN <purpose>' and a line containing only "
                    "'// SPATIALACC_TEMPLATE_TRACE_END <purpose>'. Outside those blocks the source must remain byte-for-byte "
                    "identical. Inside them use only bounded when/printf observations over existing signals; do not add "
                    "val/var/def declarations, Reg/Wire/Mem/IO state, := or <> connections, assertions, stops, or dontTouch."
                    if localized_template_instrumentation_only
                    else "A template correction is allowed only within the exact localized dependency pairs."
                )
            ),
            (
                "Each instrumentation line must be exactly one simulator line with this whitespace-delimited ABI: "
                "SPATIALACC_INTERNAL_TRACE stage=<stage_id> boundary=<stable_boundary_id> module=<template_module> "
                "cycle=<decimal> beat=<decimal> valid=<0_or_1> ready=<0_or_1> data=<packed_hex_or_xz>. Emit only a "
                "small window covering the first failed beat and the preceding beat at each directly connected internal "
                "submodule output. Prefer a one-bit x/z-presence reduction and the smallest decisive lane slice over "
                "printing a complete wide vector; print the full vector only when the requested distinction requires it. "
                "The unchanged checker converts valid=1 data containing x/z into CCTG failure records."
                if localized_instrumentation_only or localized_template_instrumentation_only
                else (
                    "The current real-tool evidence has completed localization. Remove completed diagnostic regions "
                    "delimited by SPATIALACC_TEMPLATE_TRACE_BEGIN/END from both paired template replacements while "
                    "applying the functional correction, unless a named observation is still required to distinguish "
                    "the proposed root cause. Do not remove permanent verification logic or functional RTL."
                )
            ),
            "When prior_capability_repair_evidence exists, treat its earliest failing real-tool result as the current repair-loop observation. Repair that concrete failure in the existing agent-created files before proposing broader changes; do not repeat a create operation for an existing path.",
            (
                "When current_board_to_lower_layer_contradiction is status=proven, it is the authoritative current repair route. "
                "Repair only its target_debug_layer and earliest named boundary; do not redirect to historical board audits "
                "or ask to repeat an unrelated lower-layer replay."
                if current_board_to_lower_layer_contradiction is not None
                else "Use current tool evidence to keep the repair route focused."
            ),
            (
                "The user explicitly approved semantic selected-template repair through the agent-owned real-tool root-cause/code-repair loop. You may replace only exact Scala files listed in repair_source_bundle.editable_contract.approved_bounded_template_repair_exact_files, with exact expected hashes. You may correct selected operator-template internal datapaths, state machines, and internal template interfaces/topology as required to implement the immutable target-model operator semantics and frozen numeric contract. Preserve the external accelerator/board runtime ABI, pipeline semantic stage order, model dimensions, memory/runtime contracts, numeric policy, and all reference/checker artifacts."
                if source_bundle.get("editable_contract", {}).get("semantic_template_repair_approved")
                else (
                    "Only simulation instrumentation in the single root-owning template pair is authorized. Functional "
                    "template repair remains forbidden until the resulting real VCS trace identifies the first internal "
                    "divergence."
                    if source_bundle.get("editable_contract", {}).get("localized_template_instrumentation_approved")
                    else
                    "The user explicitly approved a bounded selected-template implementation bug fix for the existing weight-consumption contract. You may replace only exact Scala files listed in repair_source_bundle.editable_contract.approved_bounded_template_repair_exact_files, with exact expected hashes. Do not change shape, topology, pipeline, memory layout, external runtime ABI, or numeric policy."
                    if source_bundle.get("editable_contract", {}).get("bounded_template_repair_approved")
                    else "Trusted templates are read-only because no template repair approval is present."
                )
            ),
            (
                "When a selected-template bug must be fixed, apply the same semantic correction to both the persistent framework template and its current generated-project copy so this run and future runs do not diverge."
                if source_bundle.get("editable_contract", {}).get("approved_bounded_template_repair_exact_files")
                else "Do not return a template edit in this capability step. The compile-validated generated Scala templates are the read-only semantic baseline; template repair is reopened only after a real simulator failure localizes a DUT defect."
            ),
            "Existing emitted generated DUT SystemVerilog is read-only and may predate the compiled Scala baseline. Add Chisel adapter/elaboration sources only under generated/chisel/src/main/scala/spatialaccagent/semantic_harness, emit each stage into its isolated directory under generated/semantic_harness, and create or replace generated/memory/dut_weight_binding_manifest.json.",
            "Instantiate the supplied compile-validated generated Scala template classes in standalone semantic-harness adapters so their actual weight/runtime ports remain observable; do not reimplement their datapath behavior in the wrapper and do not use pre-existing root emitted SystemVerilog as the semantic DUT baseline.",
            "Each harness wrapper must instantiate the real generated DUT module(s), expose the standard ready/valid/data interface declared by the binding requirements, route the packed 32-bit real-weight stream into the DUT's actual weight storage/write ports, and make weight loading complete before input stimulus is accepted.",
            "Implement the immutable stream_metadata_contract exactly: derive internal StreamBeat st/addr/last from accepted-beat counters and tensor shape; the external semantic testbench deliberately supplies only ready/valid/data.",
            "Treat each stage requirement's weight_layout and contract_sha256 as authoritative. The framework materializes checkpoint values into 32-bit words already ordered by storage target, port-write address, and LSB-first word index; the wrapper must aggregate each declared contiguous target range into the declared DUT port width without reinterpreting tensor order or numeric encoding.",
            "For fused attention, use the declared Q/K/V source_order, concat axis, tile order, and separate output-projection target exactly. For norm and bias targets, perform only the declared IEEE value-preserving storage cast. Never infer a different transpose, lane order, or packing.",
            "Any repaired arithmetic must be synthesizable hardware. Do not use shortreal/real, DPI, host-language computation, unsynthesizable simulator-only arithmetic, or a wrapper-side behavioral model. Internal approximations are allowed only when they implement the frozen numeric contract closely enough to be judged by the unchanged real-model golden checker.",
            "Preserve repair_source_bundle.fpga_ip_repair_closure exactly. All arithmetic and storage must remain bound to its generated Vivado floating-point IP and XPM timing models; never introduce HardFloat, behavioral arithmetic, SyncReadMem, Chisel Queue, or inferred generic memory.",
            "Use reference_operator_semantics, its hash-verified semantic adapter/model implementation, and captured same-inference mask/position/RoPE tensors as the semantic authority. Do not infer a different Qwen/OPT/model-family convention.",
            "Do not implement a behavioral substitute, identity/default path, sampled-weight path, or output generator in the wrapper. Do not read expected/golden/reference files from harness source. Real simulator comparison must remain capable of exposing wrong DUT behavior.",
            "The binding manifest must follow agent_manifest_schema and agent_manifest_example for verification_scope, preserve every previously certified lower-layer harness, identify top modules and exact interfaces, bind all required hashes, and disable default/identity weight fallback. Prefer one absolute source_directory per isolated harness; after runMain the executor discovers source files and recomputes all hashes.",
            "Use the supplied exact semantic-testbench producer/consumer source as executable contract authority. One approved runMain may elaborate all stage tops sequentially, but each stage source_directory must be self-contained and free of duplicate module definitions within that directory.",
            *capability_scope_prompt_rules(verification_scope),
            "Do not edit input policy, checkpoint, model reference, expected outputs, semantic testbench generator, acceptance checkers, verification reports, certificates, SACG state, architecture, pipeline, memory layout, or runtime ABI.",
            "Current-run generated artifacts may contain current model dimensions and module names; framework-core code must remain model-independent.",
            "Applying the already frozen loose numeric defaults is authorized, but changing their values is forbidden.",
            "Use requested_validation only for sbt Compile/compile and runMain spatialaccagent.semantic_harness.<MainObject> in the supplied generated/chisel cwd. Each request argv must contain exactly one sbt goal after the standard sbt flags: use the single argv item 'runMain spatialaccagent.semantic_harness.<MainObject>', not separate 'runMain' and class-name items. The executor validates and runs these commands without a shell, then always reruns the authoritative case-adapter capability tool.",
            ]
        ),
    )
    llm_record = stamp_repair_execution_agent_context(
        llm_record,
        step,
        verification_scope,
    )
    if not board_integration_repair and not localized_semantic_repair:
        llm_record = stamp_capability_repair_agent_context(
            llm_record,
            step,
            verification_scope,
        )
    implementation_output = llm_record.get("output", {}) if isinstance(llm_record.get("output"), dict) else {}
    if board_integration_repair:
        implementation_output = runtime_only_observation_output(
            implementation_output
        )
        llm_record["output"] = implementation_output
    single_layer_source_rebase = (
        copy.deepcopy(llm_record.get("single_layer_compile_source_rebase"))
        if isinstance(llm_record.get("single_layer_compile_source_rebase"), dict)
        else {
            "schema_version": "spatialaccagent.single_layer_compile_source_rebase.v1",
            "status": "not_required",
            "blockers": [],
            "rebased_files": [],
        }
    )
    if single_layer_compile_rtl_repair:
        implementation_output, computed_source_rebase = (
            rebase_stale_single_layer_compile_agent_output(
                implementation_output,
                single_layer_compile_context or {},
                run_dir,
            )
        )
        if computed_source_rebase.get("status") != "not_required":
            single_layer_source_rebase = computed_source_rebase
            llm_record["output"] = implementation_output
    if board_integration_repair:
        generation_attempts.append(
            {
                "agent": llm_record.get("agent"),
                "path": llm_record.get("result_path"),
                "sha256": (
                    sha256_file(Path(str(llm_record.get("result_path"))))
                    if llm_record.get("result_path")
                    and Path(str(llm_record.get("result_path"))).is_file()
                    else None
                ),
            }
        )
        package["exact_board_generation_attempts"] = generation_attempts
        write_json(package_path, package)
    validation_contract_errors: list[str] = []
    if localized_semantic_repair and not localized_instrumentation_only:
        implementation_output, validation_contract_errors = semantic_harness_validation_output(
            implementation_output,
            run_dir,
            require_elaboration=True,
            required_elaboration_main=(
                SEMANTIC_HARNESS_ELABORATION_MAIN_BY_SCOPE.get(
                    verification_scope
                )
            ),
        )
        if validation_contract_errors:
            implementation_output = {
                **implementation_output,
                "status": "blocked",
                "blocked_reasons": [
                    *implementation_output.get("blocked_reasons", []),
                    *validation_contract_errors,
                ],
            }
    adaptive_observation_validation = {
        "schema_version": ADAPTIVE_OBSERVATION_VALIDATION_SCHEMA_VERSION,
        "status": "not_required",
        "mode": None,
        "blockers": [],
        "summary": "adaptive observation decision is only required for a real-evidence board repair",
    }
    adaptive_observation_decision = (
        implementation_output.get("adaptive_observation_decision", {})
        if isinstance(
            implementation_output.get("adaptive_observation_decision"), dict
        )
        else {}
    )
    adaptive_observation_decision_requested = (
        board_integration_repair
        and not checkpoint_capability_repair_required
        and not implementation_output.get("file_edits")
        and adaptive_observation_decision.get("mode")
        == "deepen_simulation_observation"
        and implementation_output.get("status") in {"ready_to_apply", "blocked"}
    )
    current_board_observation_requested = (
        adaptive_observation_decision_requested
    )
    if (
        board_integration_repair
        and not checkpoint_capability_repair_required
        and (
            implementation_output.get("status") == "ready_to_apply"
            or adaptive_observation_decision_requested
        )
        and isinstance(llm_package.get("current_board_vcs_feedback"), dict)
        and llm_package["current_board_vcs_feedback"].get("status") == "ready"
    ):
        adaptive_observation_validation_package = (
            compact_verification_capability_repair_package(llm_package)
            if llm_record.get("proactive_prompt_compaction") is True
            or llm_record.get("compact_retry_prompt_bytes") is not None
            else llm_package
        )
        adaptive_observation_validation = validate_adaptive_observation_decision(
            implementation_output,
            adaptive_observation_validation_package,
            run_dir,
            require_signal_analysis=board_signal_analysis_required,
        )
    if board_integration_repair:
        # Layer 3 is LLM-owned.  Observation-contract findings are diagnostic
        # feedback for the next repair turn, not a framework veto.  Keep the
        # mechanical source/anchor checks in apply_agent_file_edits as the
        # actual execution boundary.
        adaptive_observation_validation = enforce_board_observation_only_validation(
            adaptive_observation_validation,
            implementation_output,
            run_dir,
        )
    elif board_observation_only_repair:
        adaptive_observation_validation = enforce_board_observation_only_validation(
            adaptive_observation_validation,
            implementation_output,
            run_dir,
        )
    adaptive_observation_validation_path = (
        out_dir / "adaptive_observation_decision_validation.json"
    )
    write_json(
        adaptive_observation_validation_path,
        adaptive_observation_validation,
    )
    package["adaptive_observation_decision_validation"] = {
        "path": str(adaptive_observation_validation_path),
        "sha256": sha256_file(adaptive_observation_validation_path),
        "value": adaptive_observation_validation,
    }
    write_json(package_path, package)
    if (
        current_board_observation_requested
        and adaptive_observation_validation.get("status") == "pass"
        and adaptive_observation_validation.get("mode")
        == "deepen_simulation_observation"
    ):
        # Observation focus is runtime-only. Persist the selected subset, keep
        # all compiled sources unchanged, and restore the same verified native
        # VCS snapshot for the next current signal epoch.
        runtime_observation_state = (
            persist_runtime_adaptive_observation_request(
                run_dir,
                adaptive_observation_validation,
            )
        )
        package["runtime_observation_selection"] = copy.deepcopy(
            runtime_observation_state.get("runtime_selection", {})
        )
        package["adaptive_observation_state"] = runtime_observation_state
        write_json(package_path, package)
        observation_probe = run_current_capability_probe(
            "current_board_observation"
        )
        observation_passed = observation_probe.get("status") == "pass"
        observation_requires_agent = exact_board_probe_requires_agent_continuation(
            observation_probe,
            completed_agent_experiment=True,
        )
        package["current_board_observation_run"] = {
            "status": "pass" if observation_passed else "fail",
            "capability_probe_log": observation_probe.get("log_path"),
        }
        write_json(package_path, package)
        return {
            "status": "pass" if observation_passed else "fail",
            "summary": (
                "current Layer-3 board observation run passed"
                if observation_passed
                else "current Layer-3 board observation run completed; return its signals to the Agent"
            ),
            "context_package": str(package_path),
            "llm_record": llm_record.get("result_path"),
            "adaptive_observation_decision_validation": str(
                adaptive_observation_validation_path
            ),
            "runtime_observation_selection": str(
                run_dir
                / "verification"
                / "adaptive_observation"
                / "current_selection.json"
            ),
            "capability_probe_log": observation_probe.get("log_path"),
            "capability_reports": observation_probe.get(
                "produced_reports", produced_reports
            ),
            "stage_passed": observation_passed,
            "target_modules": target_modules,
            "new_current_real_tool_failure_requires_agent": observation_requires_agent,
            "new_current_real_tool_failure_identity_sha256": (
                exact_board_probe_agent_handoff_identity(
                    observation_probe,
                    completed_agent_experiment=True,
                )
                if observation_requires_agent
                else None
            ),
        }
    supported_capability_handoff = supported_required_capability_handoff(
        implementation_output
    )
    if (
        implementation_output.get("status") == "blocked"
        and not implementation_output.get("file_edits")
        and (
            adaptive_observation_validation.get("status") != "blocked"
            or supported_capability_handoff["supported"]
        )
    ):
        blocked_reasons = [
            str(value)
            for value in implementation_output.get("blocked_reasons", [])
            if str(value)
        ]
        required_capabilities = [
            copy.deepcopy(value)
            for value in implementation_output.get("required_capabilities", [])
            if isinstance(value, dict)
        ]
        direct_observation_stop = legal_direct_observation_stop(
            implementation_output,
            adaptive_observation_validation,
        )
        # A blocked implementation response must identify the upstream producer
        # that can supply its missing evidence, except for a validated direct
        # contradiction where the Agent has no authorized safe action. Treat the
        # other empty capability lists as an Agent transaction contract error;
        # never infer a producer or turn the omission into a terminal workflow
        # block. The next identical omission is bounded by the outer retry guard.
        agent_transaction_rejection = None
        retry_agent_without_real_tool = False
        decision_stop = None
        if board_integration_repair:
            # Layer 3 is a mandatory current-signal repair loop.  A model may
            # not end the loop by returning ``blocked`` or by asking another
            # control plane to make the decision for it.  Preserve the current
            # evidence and ask the same Agent for the required code edits.
            direct_observation_stop = False
            required_capabilities = []
            retry_agent_without_real_tool = True
            agent_transaction_rejection = {
                "schema_version": "spatialaccagent.agent_transaction_rejection.v1",
                "status": "ready_for_agent_retry",
                "failure_class": "layer3_required_current_signal_code_edit",
                "blockers": [
                    "Layer-3 Agent returned blocked instead of the required functional HDL and testbench observation edits"
                ],
                "file_edits_were_not_applied": True,
                "real_tool_replay_required_before_retry": False,
                "unchanged_pre_edit_files": [],
            }
        elif direct_observation_stop:
            decision_stop = {
                "schema_version": "spatialaccagent.agent_decision_stop.v1",
                "status": "recorded",
                "mode": "direct_executed_contradiction",
                "reason": (
                    "the validated Agent decision has direct current evidence but "
                    "no authorized source edit, distinct observation edit, or upstream "
                    "capability request"
                ),
            }
        elif blocked_reasons and not required_capabilities:
            # Keep the current evidence in the next prompt, but do not create
            # another capability-contract gate.  A real AXI monitor failure
            # can be repaired from the current trace even when an older probe
            # was not source-bound.
            retry_agent_without_real_tool = True
        patch_path = out_dir / "agent_patch_application.json"
        transaction_blockers = (
            list(agent_transaction_rejection.get("blockers", []))
            if isinstance(agent_transaction_rejection, dict)
            else blocked_reasons
        )
        # A blocked answer with no edit is an LLM request for more current
        # evidence, not a framework veto. Keep the retry loop alive and label
        # the record explicitly so operators can distinguish the two cases.
        patch_application = {
            "schema_version": "spatialaccagent.agent_patch_application.v1",
            "status": "llm_waiting_for_current_evidence",
            "summary": str(
                implementation_output.get("summary")
                or "implementation agent requires an upstream capability"
            ),
            "blocked_reasons": blocked_reasons,
            "blockers": transaction_blockers,
            "required_capabilities": required_capabilities,
            "files": [],
            "repair_checkpoint": repair_step_checkpoint(step),
            "agent_transaction_rejection": agent_transaction_rejection,
            "agent_decision_stop": decision_stop,
            "retry_agent_without_real_tool": retry_agent_without_real_tool,
            "decision_owner": "llm",
        }
        write_json(patch_path, patch_application)
        blocked_handoff_path = out_dir / "agent_patch_blocked_handoff.json"
        write_json(blocked_handoff_path, patch_application)
        package["llm_record_path"] = llm_record.get("result_path")
        package["agent_patch_blocked_handoff"] = str(blocked_handoff_path)
        package["blocked_handoff"] = {
            "status": "llm_waiting_for_current_evidence",
            "blocked_reasons": blocked_reasons,
            "required_capabilities": required_capabilities,
        }
        write_json(package_path, package)
        return {
            "status": "llm_waiting_for_current_evidence",
            "agent_status": "blocked",
            "summary": patch_application["summary"],
            "blocked_reasons": blocked_reasons,
            "required_capabilities": required_capabilities,
            "framework_action_required": bool(required_capabilities),
            "context_package": str(package_path),
            "llm_record": llm_record.get("result_path"),
            "agent_patch_application": str(patch_path),
            "agent_patch_blocked_handoff": str(blocked_handoff_path),
            "agent_transaction_rejection": agent_transaction_rejection,
            "agent_decision_stop": decision_stop,
            "retry_agent_without_real_tool": retry_agent_without_real_tool,
            "decision_owner": "llm",
            "stage_passed": False,
            "target_modules": target_modules,
        }
    localized_allowed_files = {
        repo_path(path).resolve()
        for path in source_bundle.get("editable_contract", {}).get("localized_allowed_exact_files", [])
    }
    stale_static_authority_blockers = (
        stale_static_board_authority_repair_blockers(
            implementation_output,
            run_dir,
            runtime_frontier_static_repair_guard,
        )
        if board_integration_repair and not single_layer_compile_rtl_repair
        else []
    )
    # Layer 3 has one decision-maker: the LLM.  Observation coverage, stale
    # authority notes, and output-shape expectations remain visible in the
    # prompt and reports, but none may veto a ready LLM transaction.  The
    # atomic executor below still rejects only non-executable edits (outside
    # the write boundary, missing files, invalid JSON, or invalid anchors).
    agent_contract_blockers = (
        []
        if board_integration_repair
        else [
            *(
                adaptive_observation_validation.get("blockers", [])
                if adaptive_observation_validation.get("status") == "blocked"
                else []
            ),
            *stale_static_authority_blockers,
            *(
                single_layer_source_rebase.get("blockers", [])
                if single_layer_source_rebase.get("status") == "blocked"
                else []
            ),
            *layer3_required_code_edit_errors(
                implementation_output,
                run_dir,
                current_signal_epoch=board_signal_analysis_required,
            ),
        ]
    )
    patch_application = apply_agent_file_edits(
        implementation_output,
        run_dir,
        out_dir,
        allowed_exact_files=(
            checkpoint_specialist_required_files
            if checkpoint_capability_repair_required
            else {
                Path(str(value)).resolve()
                for value in (
                    board_semantic_rtl_authority.get("allowed_exact_files", [])
                    if board_semantic_rtl_authority
                    else []
                )
            }
            if board_semantic_rtl_repair
            else localized_allowed_files
            if localized_semantic_repair
            else None
        ),
        required_exact_files=None,
        required_noop_json_merges=None,
        required_template_pairs=(
            set(
                source_bundle.get("editable_contract", {}).get(
                    "localized_template_instrumentation_pair_names", []
                )
            )
            if localized_template_instrumentation_only
            else set(
                source_bundle.get("editable_contract", {}).get(
                    "localized_template_pair_names", []
                )
            )
            if localized_semantic_repair and not localized_instrumentation_only
            else None
        ),
        instrumentation_only_template_pairs=(
            set(
                source_bundle.get("editable_contract", {}).get(
                    "localized_template_instrumentation_pair_names", []
                )
            )
            if localized_template_instrumentation_only
            else None
        ),
        repair_checkpoint=repair_step_checkpoint(step),
        allow_template_repair=(
            localized_semantic_repair
            and not localized_instrumentation_only
        ),
        allow_board_integration=board_integration_repair,
        allowed_semantic_rtl_files=(
            {
                Path(str(value)).resolve()
                for value in (
                    board_semantic_rtl_authority.get("allowed_exact_files", [])
                    if board_semantic_rtl_authority
                    else []
                )
            }
            if board_semantic_rtl_repair
            else None
        ),
        require_exact_source_hash=False,
        agent_contract_blockers=agent_contract_blockers or None,
        agent_contract_failure_class=(
            "stale_static_board_authority_repair_after_runtime_frontier"
            if stale_static_authority_blockers
            else "adaptive_observation_decision_contract"
        ),
        agent_contract_retry_on_blocked=False,
    )
    patch_application["adaptive_observation_decision_validation"] = {
        "path": str(adaptive_observation_validation_path),
        "sha256": sha256_file(adaptive_observation_validation_path),
        "status": adaptive_observation_validation.get("status"),
        "mode": adaptive_observation_validation.get("mode"),
    }
    patch_application["runtime_frontier_static_repair_guard"] = copy.deepcopy(
        runtime_frontier_static_repair_guard
    )
    patch_application["single_layer_compile_source_rebase"] = copy.deepcopy(
        single_layer_source_rebase
    )
    patch_application["repair_execution_context"] = repair_execution_context_for_step(
        step,
        verification_scope,
    )
    if board_integration_repair:
        patch_application["agent"] = (
            SINGLE_LAYER_COMPILE_RTL_REPAIR_AGENT
            if single_layer_compile_rtl_repair
            else EXACT_BOARD_GENERATION_AGENT
        )
    if patch_application.get("path"):
        write_json(Path(str(patch_application["path"])), patch_application)
    adaptive_observation_state = persist_adaptive_observation_request(
        run_dir,
        adaptive_observation_validation,
        patch_application,
    )
    instrumentation_cleanup = (
        cleanup_completed_template_instrumentation(run_dir, out_dir)
        if patch_application.get("status") == "pass"
        and localized_semantic_repair
        and not localized_instrumentation_only
        and not localized_template_instrumentation_only
        else {
            "status": "not_run",
            "summary": "completed instrumentation cleanup is only required after a functional template patch",
        }
    )
    agent_validation = (
        run_agent_requested_validation(
            (
                {"requested_validation": []}
                if board_integration_repair
                else implementation_output
            ),
            run_dir,
            out_dir,
            timeout_sec,
        )
        if patch_application.get("status") == "pass"
        and instrumentation_cleanup.get("status") in {"pass", "not_run"}
        else {
            "status": "not_run",
            "blockers": [
                "agent patch was not applied or completed instrumentation cleanup failed closed"
            ],
        }
    )
    board_semantic_rtl_single_layer_gate = {
        "status": "not_run",
        "summary": "single-layer prerequisite gate was not needed",
        "board_vcs_started": False,
    }
    if (
        board_semantic_rtl_repair
        and patch_application.get("status") == "pass"
        and agent_validation.get("status") == "pass"
    ):
        if reuse_existing_single_layer_gate_for_board_repair(run_dir):
            board_semantic_rtl_single_layer_gate = {
                "status": "not_run",
                "summary": (
                    "reused the existing passed single-layer prerequisite; "
                    "continued directly to the current third-layer board run"
                ),
                "board_vcs_started": False,
                "reused_existing_certificate": True,
            }
        else:
            board_semantic_rtl_single_layer_gate = (
                run_board_semantic_rtl_single_layer_gate(
                    case_adapter=case_adapter,
                    run_dir=run_dir,
                    step=step,
                    out_dir=out_dir,
                    timeout_sec=timeout_sec,
                )
            )
        package["board_semantic_rtl_single_layer_gate"] = copy.deepcopy(
            board_semantic_rtl_single_layer_gate
        )
        write_json(package_path, package)
        if (
            board_semantic_rtl_single_layer_gate.get("status") == "fail"
        ):
            return {
                "status": "fail",
                "summary": (
                    "board semantic RTL patch did not pass the connected single-layer "
                    "functional gate; exact-board AXI/DDR VCS was not started"
                ),
                "context_package": str(package_path),
                "reference_builder_log": builder_probe.get("log_path"),
                "capability_probe_log": capability_probe.get("log_path"),
                "post_patch_capability_probe_log": board_semantic_rtl_single_layer_gate.get(
                    "log_path"
                ),
                "capability_reports": board_semantic_rtl_single_layer_gate.get(
                    "produced_reports", []
                ),
                "llm_record": llm_record.get("result_path"),
                "agent_patch_application": patch_application.get("path"),
                "agent_requested_validation": agent_validation.get("path"),
                "board_semantic_rtl_single_layer_gate": board_semantic_rtl_single_layer_gate.get(
                    "gate_path"
                ),
                "board_vcs_started": False,
                "stage_passed": False,
                "target_modules": target_modules,
                "framework_action_required": (
                    "return the connected single-layer failure to the same RTL Agent "
                    "before any exact-board replay"
                ),
            }
    pre_materialization_dependency_refresh = (
        run_capability_probe(
            case_adapter=case_adapter,
            spec_role=dependency_role,
            spec=dependency_spec,
            run_dir=run_dir,
            step=step,
            out_dir=out_dir,
            timeout_sec=timeout_sec,
            label="binding_requirements_post_patch",
        )
        if agent_validation.get("status") == "pass"
        and require_single_layer
        and dependency_spec
        and not connected_binding_requirements_ready(run_dir)
        else {
            "status": "not_run",
            "summary": (
                "connected binding requirements are already current"
                if connected_binding_requirements_ready(run_dir)
                else "no pre-materialization connected-contract refresh is required"
            ),
        }
    )
    binding_materialization = (
        finalize_dut_weight_binding_manifest(
            run_dir,
            out_dir,
            require_single_layer=require_single_layer,
            require_board=board_integration_repair,
            single_layer_certificate_path=single_layer_certificate_path,
        )
        if agent_validation.get("status") == "pass"
        and pre_materialization_dependency_refresh.get("status")
        in {"pass", "not_run"}
        else {
            "status": "not_run",
            "blockers": [
                "agent-requested build/elaboration or connected-contract refresh did not pass"
            ],
        }
    )
    post_patch_dependency_refresh = (
        run_capability_probe(
            case_adapter=case_adapter,
            spec_role=dependency_role,
            spec=dependency_spec,
            run_dir=run_dir,
            step=step,
            out_dir=out_dir,
            timeout_sec=timeout_sec,
            label="dependency_refresh_post_patch",
        )
        if binding_materialization.get("status") == "pass" and dependency_spec
        else {
            "status": "not_run" if not dependency_spec else "blocked",
            "summary": "dependency refresh requires passing binding materialization",
        }
    )
    checkpoint_request_result: dict[str, Any] = {
        "status": "not_run",
        "summary": "simulation checkpointing is only activated for a materialized layer-3 board repair",
    }
    checkpoint_request_path: Path | None = None
    if board_integration_repair and binding_materialization.get("status") == "pass":
        post_patch_checkpoint_preparation = prepare_stage3_checkpoint_probe_environment(
            run_dir,
            label=f"{safe_step_id(step)}_post_patch",
        )
        checkpoint_request_result = post_patch_checkpoint_preparation.get(
            "request", {}
        )
        checkpoint_request_path_value = post_patch_checkpoint_preparation.get(
            "request_path"
        )
        checkpoint_request_path = (
            Path(str(checkpoint_request_path_value))
            if checkpoint_request_path_value
            else None
        )
        checkpoint_probe_env = dict(
            post_patch_checkpoint_preparation.get("env", {})
        )
    post_capability_probe = (
        run_current_capability_probe("post_patch")
        if binding_materialization.get("status") == "pass"
        and post_patch_dependency_refresh.get("status") in {"pass", "not_run"}
        else capability_probe
    )
    post_patch_adaptive_observation_state = materialize_adaptive_observation_evidence(
        run_dir,
        post_capability_probe.get("current_board_vcs_feedback", {})
        if isinstance(post_capability_probe.get("current_board_vcs_feedback"), dict)
        else {},
    )
    if board_integration_repair and isinstance(
        post_capability_probe.get("current_board_vcs_feedback"), dict
    ):
        persist_current_exact_board_failed_attempt(
            run_dir,
            post_capability_probe["current_board_vcs_feedback"],
            patch_application=patch_application,
            llm_record=llm_record,
        )
    package["llm_record_path"] = llm_record.get("result_path")
    package["single_layer_compile_source_rebase"] = copy.deepcopy(
        single_layer_source_rebase
    )
    package["agent_patch_application"] = patch_application.get("path")
    package["completed_template_instrumentation_cleanup"] = instrumentation_cleanup.get("path")
    package["agent_requested_validation"] = agent_validation.get("path")
    package["board_semantic_rtl_single_layer_gate"] = (
        board_semantic_rtl_single_layer_gate
    )
    package["pre_materialization_dependency_refresh"] = (
        pre_materialization_dependency_refresh.get("log_path")
    )
    package["dut_weight_binding_materialization"] = binding_materialization.get("path")
    package["post_patch_dependency_refresh"] = post_patch_dependency_refresh.get("log_path")
    package["simulation_checkpoint_request"] = (
        {
            "path": str(checkpoint_request_path),
            "sha256": sha256_file(checkpoint_request_path),
            "value": checkpoint_request_result,
        }
        if checkpoint_request_path is not None
        else checkpoint_request_result
    )
    package["post_patch_capability_probe"] = post_capability_probe.get("log_path")
    package["adaptive_observation_state"] = post_patch_adaptive_observation_state
    write_json(package_path, package)
    adaptive_observation_passed = (
        adaptive_observation_state.get("status") != "pending_real_tool_evidence"
        or post_patch_adaptive_observation_state.get("status") == "pass"
        or post_capability_probe.get("status") == "pass"
    )
    capability_passed = (
        post_capability_probe.get("status") == "pass"
        and adaptive_observation_passed
    )
    post_patch_real_tool_requires_agent = (
        board_integration_repair
        and exact_board_probe_requires_agent_continuation(post_capability_probe)
    )
    post_patch_real_tool_failure_identity = (
        exact_board_probe_agent_handoff_identity(post_capability_probe)
        if post_patch_real_tool_requires_agent
        else None
    )
    if capability_passed:
        status = "pass"
        summary = f"{capability_spec.get('name') if capability_spec else capability_role} verification capability probe passed after agent patch"
    else:
        status = "fail"
        summary = (
            f"{capability_spec.get('name') if capability_spec else capability_role or '<unresolved>'} "
            f"still lacks passing independent verification capability evidence after bounded agent execution for {target_modules or ['<unknown>']}"
        )
    return {
        "status": status,
        "summary": summary,
        "context_package": str(package_path),
        "reference_builder_log": builder_probe.get("log_path"),
        "capability_probe_log": capability_probe.get("log_path"),
        "post_patch_capability_probe_log": post_capability_probe.get("log_path"),
        "capability_reports": post_capability_probe.get("produced_reports", produced_reports),
        "leaf_stage_report": str(leaf_report_path) if leaf_report_path else None,
        "llm_record": llm_record.get("result_path"),
        "agent_patch_application": patch_application.get("path"),
        "adaptive_observation_decision_validation": str(
            adaptive_observation_validation_path
        ),
        "adaptive_observation_state": post_patch_adaptive_observation_state.get(
            "path"
        ),
        "completed_template_instrumentation_cleanup": instrumentation_cleanup.get("path"),
        "agent_requested_validation": agent_validation.get("path"),
        "dut_weight_binding_materialization": binding_materialization.get("path"),
        "simulation_checkpoint_request": str(checkpoint_request_path) if checkpoint_request_path else None,
        "stage_passed": capability_passed,
        "target_modules": target_modules,
        "new_current_real_tool_failure_requires_agent": (
            post_patch_real_tool_requires_agent
        ),
        "new_current_real_tool_failure_identity_sha256": (
            post_patch_real_tool_failure_identity
        ),
    }


def execute_stage6_gate_dag_repair(
    step: dict[str, Any],
    source_state: Path,
    run_dir: Path,
    out_dir: Path,
    timeout_sec: int,
) -> dict[str, Any]:
    action = step.get("action", {}) if isinstance(step.get("action"), dict) else {}
    package = {
        "schema_version": "spatialaccagent.stage6_gate_dag_repair_package.v0",
        "stage": "repair_execution",
        "source_sacg_state": str(source_state),
        "run_dir": str(run_dir),
        "repair_step_id": step.get("id"),
        "repair_scope": step.get("scope"),
        "debug_layer": action.get("debug_layer") or step.get("debug_layer"),
        "out_of_order_executed_higher_layer_gates": action.get("out_of_order_executed_higher_layer_gates", []),
        "policy": {
            "higher_layer_gates_must_depend_on_lower_layer_pass_evidence": True,
            "stage6_must_be_rerun_before_stage6_consumes_new_gate_dag": True,
            "do_not_continue_with_old_out_of_order_gate_contract": True,
        },
    }
    package_path = out_dir / f"{safe_step_id(step)}_stage6_gate_dag_repair_package.json"
    write_json(package_path, package)
    llm_record = run_optional_post_execution_review(
        agent="stage6_gate_dag_repair_agent",
        task=(
            "Analyze a hierarchical verification gate-DAG repair request. "
            "The current lower debug layer has not passed, but higher-layer gates executed. "
            "Return bounded actions to repair dependencies and require Stage6 regeneration before Stage7 retry."
        ),
        inputs={
            "source_sacg_state": str(source_state),
            "repair_step": step,
            "stage6_gate_dag_repair_package": package,
        },
        out_dir=out_dir,
        fallback_summary="Stage6 gate DAG repair requires LLM analysis",
        deterministic_summary=(
            "The approved repair action already requires Stage6 gate-DAG regeneration; its real regeneration status "
            "determines this execution step and Stage7 will reassess the regenerated contract."
        ),
    )
    package["llm_record_path"] = llm_record.get("result_path")
    write_json(package_path, package)
    try:
        from accagent.framework.stage_verification_plan import plan_verification

        stage6_report_path, stage6_report = plan_verification(ns_obj(source_state))
        stage6_status = stage6_report.get("status")
        status = "pass" if stage6_status == "ready" else "fail"
        summary = f"Stage6 verification artifact regeneration status={stage6_status}"
        return {
            "status": status,
            "summary": summary,
            "context_package": str(package_path),
            "llm_record": llm_record.get("result_path"),
            "stage6_report": str(stage6_report_path),
            "stage6_sacg_state": stage6_report.get("outputs", {}).get("sacg_state"),
            "next_required_stage": "verification",
        }
    except Exception as exc:
        return {
            "status": "fail",
            "summary": f"Stage6 gate DAG regeneration failed: {exc}",
            "context_package": str(package_path),
            "llm_record": llm_record.get("result_path"),
            "next_required_stage": "verification_artifacts",
        }


def ns_obj(sacg_state: Path) -> argparse.Namespace:
    return argparse.Namespace(sacg_state=sacg_state)


def execute_repair(args: argparse.Namespace) -> tuple[Path, dict[str, Any]]:
    source_state = args.sacg_state.resolve()
    run_dir = run_dir_from_state(source_state)
    out_dir = run_dir / "repair_execution"
    out_dir.mkdir(parents=True, exist_ok=True)
    state = read_json(source_state)
    repair_plan_path = artifact_path(state, "artifact.stage6.repair_plan")
    repair_plan = read_json(repair_plan_path)
    # A resumed controller may load a plan that predates the current
    # reconciliation policy.  Restore only the framework-owned, read-only
    # compiler-evidence producer before dispatching workflow steps.
    from accagent.framework.stage_repair import (
        restore_persisted_read_only_capability_steps,
    )

    if restore_persisted_read_only_capability_steps(repair_plan):
        write_json(repair_plan_path, repair_plan)
    workflow = repair_plan.get("repair_workflow", {}) if isinstance(repair_plan.get("repair_workflow"), dict) else {}
    steps = workflow.get("steps", []) if isinstance(workflow.get("steps"), list) else []
    step_results = []
    for persisted_step in steps:
        step = (
            rebind_exact_board_vcs_rerun_step(persisted_step, state, run_dir)
            if isinstance(persisted_step, dict)
            else persisted_step
        )
        if not isinstance(step, dict):
            continue
        status = str(step.get("status") or "")
        scope = str(step.get("scope") or "")
        if status == "ready_for_agent_patch" and scope == "code_repair":
            result = execute_patch_step(step, out_dir)
        elif status == "ready_for_agent_patch" and scope == "causal_slice_repair":
            result = execute_causal_slice_repair(step, source_state, run_dir, out_dir, args.timeout_sec)
        elif status == "ready_for_agent_patch" and scope == "verification_capability_repair":
            result = execute_verification_capability_repair(step, source_state, run_dir, out_dir, args.timeout_sec)
        elif status == "ready_for_agent_patch" and scope == "stage6_gate_dag_repair":
            result = execute_stage6_gate_dag_repair(step, source_state, run_dir, out_dir, args.timeout_sec)
        elif status == "ready_for_agent_patch" and scope == "targeted_lower_layer_backtrack":
            # Old plans may still contain this obsolete step.  It is not part
            # of the Layer-3 loop and must not launch an LLM or Layer-2 run.
            continue
        elif status == "ready_to_execute" and scope == "causal_slice_repair":
            if args.execute_reruns:
                result = execute_causal_slice_repair(
                    step, source_state, run_dir, out_dir, args.timeout_sec
                )
            else:
                result = {"status": "not_run", "summary": "rerun execution disabled; pass --execute-reruns"}
        elif status == "ready_to_execute" and scope in {"regression_rerun", "debug_trace_rerun"}:
            if args.execute_reruns:
                result = run_rerun_step(
                    step,
                    out_dir,
                    args.include_remote,
                    args.timeout_sec,
                    case_adapter=case_adapter_for_state(state, run_dir),
                )
            else:
                result = {"status": "not_run", "summary": "rerun execution disabled; pass --execute-reruns"}
        elif status == "blocked":
            result = {
                "status": "blocked",
                "summary": step.get("tool_capability_gap", {}).get("reason")
                or f"repair step is blocked: {scope}",
                "tool_capability_gap": step.get("tool_capability_gap", {}),
                "tool_capability": step.get("tool_capability", {}),
            }
        elif status == "blocked_by_llm_disposition":
            # A planner veto is not an executable no-op.  Preserve it as a
            # blocked repair step so Stage 6 cannot report ready merely because
            # the executor skipped the step.
            result = {
                "status": "blocked",
                "summary": step.get("llm_veto_reason")
                or f"repair step is blocked by LLM disposition: {scope}",
                "blocked_by_llm_disposition": True,
            }
        else:
            result = {"status": "skip", "summary": f"step status/scope not executable: {status}/{scope}"}
        step_results.append(
            {
                "step_id": step.get("id"),
                "scope": scope,
                "tool": step.get("tool"),
                "repair_execution_context": repair_execution_context_for_step(
                    step,
                    verification_scope_for_step(step),
                ),
                "result": result,
            }
        )
    errors = [
        f"{item['step_id']}: {item['result'].get('summary')}"
        for item in step_results
        if item["result"].get("status") in {"fail", "blocked", "skip", "not_run"}
        or item["result"].get("requires_agent_followup") is True
    ]
    report = {
        "schema_version": "spatialaccagent.repair_execution_report.v0",
        "stage": "repair_execution",
        "status": "incomplete" if errors else "ready",
        "source_sacg_state": str(source_state),
        "repair_plan": str(artifact_path(state, "artifact.stage6.repair_plan")),
        "execute_reruns": bool(args.execute_reruns),
        "include_remote": bool(args.include_remote),
        "step_results": step_results,
        "errors": errors,
        "next_required_stage": "verification" if not errors else "repair",
    }
    report_path = out_dir / "repair_execution_report.json"
    write_json(report_path, report)
    state_path = out_dir / "sacg_state.json"
    update_sacg(source_state, state_path, report_path, report)
    return report_path, report


def supported_required_capability_handoff(output: dict[str, Any]) -> dict[str, Any]:
    """Validate a blocked Agent producer request without validating a source edit."""

    capabilities = [
        copy.deepcopy(value)
        for value in output.get("required_capabilities", [])
        if isinstance(value, dict)
    ]
    if not capabilities:
        return {"supported": False, "required_capabilities": []}
    from accagent.framework.stage_repair import required_capability_repair_actions

    actions = required_capability_repair_actions(
        {
            "status": "blocked",
            "validation": {"status": "pass"},
            "input_fingerprint_sha256": canonical_contract_sha256(capabilities),
            "required_capabilities": capabilities,
        }
    )
    return {
        "supported": len(actions) == len(capabilities),
        "required_capabilities": capabilities,
    }


def repair_loop_disposition(report: dict[str, Any]) -> dict[str, Any]:
    step_results = [
        item
        for item in report.get("step_results", [])
        if isinstance(item, dict)
    ]
    completed_board_lower_layer_rechecks = [
        copy.deepcopy(result["completed_board_lower_layer_recheck"])
        for item in step_results
        for result in [
            item.get("result", {})
            if isinstance(item.get("result"), dict)
            else {}
        ]
        if isinstance(result.get("completed_board_lower_layer_recheck"), dict)
        and result["completed_board_lower_layer_recheck"].get("status") == "pass"
    ]
    if completed_board_lower_layer_rechecks:
        return {
            "status": "continue",
            "summary": (
                "the board-triggered lower-layer check completed; return to the "
                "current Layer-3 board validation"
            ),
            "applied_files": [],
            "exact_board_failure_handoff": True,
            "completed_board_lower_layer_rechecks": (
                completed_board_lower_layer_rechecks
            ),
        }
    all_steps_passed = bool(step_results) and all(
        (
            item.get("result", {}).get("status") == "pass"
            and item.get("result", {}).get("stage_passed", True) is True
        )
        for item in step_results
    )
    if (
        report.get("status") == "ready"
        and not report.get("errors")
        and (not step_results or all_steps_passed)
    ):
        return {
            "status": "complete",
            "summary": "Stage 6 repair execution and its current-layer verification passed",
            "applied_files": [],
        }

    blocked_summaries: list[str] = []
    retry_without_real_tool_summaries: list[str] = []
    retry_without_real_tool_kinds: set[str] = set()
    agent_transaction_retry_identities: set[str] = set()
    new_real_tool_failure_summaries: list[str] = []
    new_real_tool_failure_identities: set[str] = set()
    exact_board_failure_handoff = False
    upstream_capability_replans: list[dict[str, Any]] = []
    completed_capability_producers: list[dict[str, Any]] = []
    applied_files: list[dict[str, Any]] = []
    no_progress_failures: list[str] = []
    for item in report.get("step_results", []):
        if not isinstance(item, dict):
            continue
        result = item.get("result", {}) if isinstance(item.get("result"), dict) else {}
        if result.get("status") == "fail":
            instrumentation_evidence = (
                result.get("instrumentation_evidence", {})
                if isinstance(result.get("instrumentation_evidence"), dict)
                else {}
            )
            has_new_agent_or_tool_observation = any(
                (
                    result.get("llm_record"),
                    result.get("reference_builder_log"),
                    result.get("capability_probe_log"),
                    result.get("post_patch_capability_probe_log"),
                    result.get("leaf_stage_report"),
                    result.get("capability_reports"),
                    result.get("instrumentation_evidence_collected") is True,
                    instrumentation_evidence.get("status") not in {None, "not_run"},
                    result.get("requires_agent_followup") is True,
                    result.get("new_current_real_tool_failure_requires_agent") is True,
                )
            )
            if not has_new_agent_or_tool_observation:
                no_progress_failures.append(
                    str(
                        result.get("summary")
                        or f"{item.get('step_id') or 'repair step'} failed without new Agent or tool observation"
                    )
                )
        # An Agent-requested producer is control-flow evidence, not a failed
        # patch transaction.  Capability-repair steps still persist their
        # blocked handoff as agent_patch_application, so route a supported
        # request before that artifact can suppress the upstream replan.
        if result.get("status") == "blocked":
            required_capabilities = [
                copy.deepcopy(value)
                for value in result.get("required_capabilities", [])
                if isinstance(value, dict)
            ]
            if result.get("framework_action_required") is True and required_capabilities:
                from accagent.framework.stage_repair import (
                    required_capability_repair_actions,
                )

                supported_actions = required_capability_repair_actions(
                    {
                        "status": "blocked",
                        "validation": {"status": "pass"},
                        "input_fingerprint_sha256": canonical_contract_sha256(
                            required_capabilities
                        ),
                        "required_capabilities": required_capabilities,
                    }
                )
                if len(supported_actions) == len(required_capabilities):
                    upstream_capability_replans.extend(required_capabilities)
                    continue
        if result.get("requires_agent_followup") is True:
            completed_capability_producers.append(
                {
                    "step_id": item.get("step_id"),
                    "repair_kind": result.get("repair_kind"),
                    "debug_layer": (
                        item.get("repair_execution_context", {}).get("debug_layer")
                        if isinstance(item.get("repair_execution_context"), dict)
                        else None
                    ),
                    "capability_reports": copy.deepcopy(
                        result.get("capability_reports", [])
                    ),
                }
            )
            continue
        if result.get("new_current_real_tool_failure_requires_agent") is True:
            if isinstance(result.get("current_board_vcs_feedback"), dict):
                exact_board_failure_handoff = True
            new_real_tool_failure_summaries.append(
                str(
                    result.get("summary")
                    or "new exact-board real-tool failure requires agent repair"
                )
            )
            identity = str(
                result.get("new_current_real_tool_failure_identity_sha256") or ""
            )
            if re.fullmatch(r"[0-9a-f]{64}", identity):
                new_real_tool_failure_identities.add(identity)
        patch_path_value = result.get("agent_patch_application")
        if not patch_path_value:
            if result.get("status") == "blocked":
                blocked_summaries.append(
                    str(result.get("summary") or "repair agent is blocked")
                )
            continue
        patch_report = read_json_if_exists(Path(str(patch_path_value)))
        llm_evidence_wait = patch_report.get("status") == "llm_waiting_for_current_evidence"
        retry_without_real_tool = (
            patch_report.get("status") in {"blocked", "llm_waiting_for_current_evidence"}
            and patch_report.get("retry_agent_without_real_tool") is True
        )
        if llm_evidence_wait:
            retry_without_real_tool_kinds.add("llm_observation_plan")
            retry_without_real_tool_summaries.append(
                "the LLM requested more evidence; require an executable observation plan for the next Layer-3 run"
            )
        if retry_without_real_tool:
            retry_without_real_tool_kinds.add(
                "agent_transaction_contract"
                if isinstance(
                    patch_report.get("agent_transaction_rejection"), dict
                )
                else "current_signal_agent_contract"
            )
            rejection = patch_report.get("agent_transaction_rejection")
            if isinstance(rejection, dict):
                agent_transaction_retry_identities.add(
                    json.dumps(
                        {
                            "failure_class": rejection.get("failure_class"),
                            "unchanged_pre_edit_files": rejection.get(
                                "unchanged_pre_edit_files", []
                            ),
                        },
                        ensure_ascii=True,
                        sort_keys=True,
                        separators=(",", ":"),
                    )
                )
        if result.get("status") in {"blocked", "llm_waiting_for_current_evidence"}:
            summary = str(result.get("summary") or "repair agent is blocked")
            if retry_without_real_tool:
                retry_without_real_tool_summaries.append(summary)
            else:
                blocked_summaries.append(summary)
        elif retry_without_real_tool:
            retry_without_real_tool_summaries.append(
                "the agent proposed a board-source state already proven to fail"
            )
        if patch_report.get("status") != "pass":
            continue
        if not result.get("llm_record"):
            # The patch report is a persistent checkpoint. Only the execution that
            # actually consumed a fresh Agent record may advertise it as a new
            # transaction to the outer loop.
            continue
        for file_record in patch_report.get("files", []):
            if not isinstance(file_record, dict):
                continue
            before_sha = str(file_record.get("before_sha256") or "")
            after_sha = str(file_record.get("after_sha256") or "")
            if after_sha and after_sha != before_sha:
                applied_files.append(copy.deepcopy(file_record))

    if blocked_summaries:
        return {
            "status": "continue",
            "summary": (
                "the current Layer-3 decision needs a new LLM observation or repair plan: "
                + "; ".join(blocked_summaries)
            ),
            "applied_files": applied_files,
            "observation_replan_required": True,
        }
    if retry_without_real_tool_summaries:
        transaction_retry = "agent_transaction_contract" in retry_without_real_tool_kinds
        observation_plan_retry = "llm_observation_plan" in retry_without_real_tool_kinds
        return {
            "status": "continue",
            "summary": (
                "the Agent atomic transaction was rejected before write; return the "
                "deterministic materializer blockers to the same Agent without relaunching "
                "the real tool"
                if transaction_retry
                else "the LLM did not localize the current Layer-3 stop; require its explicit "
                "missing-signal observation plan and execute it in the next real VCS epoch"
                if observation_plan_retry
                else
                "a prior real-VCS failed board-source candidate was rejected before write; "
                "return its content-addressed negative evidence to the same agent without "
                "relaunching the real tool"
            ),
            "applied_files": [],
            "retry_agent_without_real_tool": True,
            "retry_reason": (
                "agent_transaction_contract"
                if transaction_retry
                else "llm_observation_plan"
                if observation_plan_retry
                else "prior_failed_source_state"
            ),
            "rejection_summaries": retry_without_real_tool_summaries,
            "agent_transaction_retry_identities": sorted(
                agent_transaction_retry_identities
            ),
        }
    if applied_files:
        return {
            "status": "continue",
            "summary": (
                "the agent applied a new hash-changing repair; rerun only the same Stage 6 "
                "current-layer repair/VCS chain"
            ),
            "applied_files": applied_files,
        }
    if new_real_tool_failure_summaries:
        return {
            "status": "continue",
            "summary": (
                "the resumed/current exact-board validation produced new hash-bound "
                "real-tool failure evidence; route it to the same hardware agent "
                "before any VCS replay"
            ),
            "applied_files": [],
            "new_current_real_tool_failure_requires_agent": True,
            "new_current_real_tool_failure_identity_sha256": (
                next(iter(new_real_tool_failure_identities))
                if len(new_real_tool_failure_identities) == 1
                else None
            ),
            "exact_board_failure_handoff": exact_board_failure_handoff,
            "failure_summaries": new_real_tool_failure_summaries,
        }
    if upstream_capability_replans:
        return {
            "status": "continue",
            "summary": (
                "the current non-fallback agent requested an executor-supported upstream "
                "capability; rebuild the bounded Stage 6 repair plan and execute its real "
                "producer before returning to this Stage 6 layer"
            ),
            "applied_files": [],
            "upstream_capability_replan_required": True,
            "required_capabilities": upstream_capability_replans,
        }
    if completed_capability_producers:
        return {
            "status": "continue",
            "summary": (
                "a hash-bound read-only capability producer completed; rebuild the "
                "current-layer repair plan so the implementation Agent can consume it"
            ),
            "applied_files": [],
            "capability_producer_replan_required": True,
            "completed_capability_producers": completed_capability_producers,
        }
    if no_progress_failures:
        return {
            "status": "blocked",
            "summary": (
                "the unchanged Stage 6 repair frontier failed without a new Agent "
                "decision or real-tool observation; return to the flow controller for "
                "a fresh bounded plan: "
                + "; ".join(no_progress_failures)
            ),
            "applied_files": [],
            "no_progress_failures": no_progress_failures,
        }
    if not step_results:
        return {
            "status": "blocked",
            "summary": (
                "the Stage 6 repair report is incomplete but contains no executable "
                "step result; return to the flow controller for a fresh bounded plan"
            ),
            "applied_files": [],
        }
    return {
        "status": "continue",
        "summary": (
            "the current Stage 6 iteration did not isolate a safe RTL edit; require the LLM to "
            "select a deeper current-epoch observation plan before the next VCS run"
        ),
        "applied_files": [],
        "observation_replan_required": True,
    }


def repair_loop_evidence_paths(report: dict[str, Any]) -> list[tuple[str, Path]]:
    evidence: list[tuple[str, Path]] = []
    for item in report.get("step_results", []):
        if not isinstance(item, dict):
            continue
        result = item.get("result", {}) if isinstance(item.get("result"), dict) else {}
        for field in (
            "agent_patch_application",
            "agent_requested_validation",
            "adaptive_observation_decision_validation",
            "adaptive_observation_state",
            "context_package",
            "llm_record",
            "post_patch_capability_probe_log",
            "dut_weight_binding_materialization",
        ):
            value = result.get(field)
            if value:
                evidence.append((field, Path(str(value))))
        for capability_report in result.get("capability_reports", []):
            path_value = (
                capability_report.get("path")
                if isinstance(capability_report, dict)
                else capability_report
            )
            if path_value:
                evidence.append(("capability_report", Path(str(path_value))))

    for role, report_path in list(evidence):
        if role != "capability_report" or not report_path.is_file():
            continue
        diagnosis = read_json_if_exists(report_path)
        failure_evidence = (
            diagnosis.get("failure_evidence", {})
            if isinstance(diagnosis.get("failure_evidence"), dict)
            else {}
        )
        causal_binding = (
            failure_evidence.get("sacg_cctg_causal_slice", {})
            if isinstance(failure_evidence.get("sacg_cctg_causal_slice"), dict)
            else {}
        )
        causal_path = Path(str(causal_binding.get("path") or ""))
        causal_sha256 = str(causal_binding.get("sha256") or "")
        if (
            causal_path.is_file()
            and causal_sha256
            and sha256_file(causal_path) == causal_sha256
        ):
            evidence.append(("sacg_cctg_causal_slice", causal_path))

    llm_paths = [path for role, path in evidence if role == "llm_record" and path.is_file()]
    for llm_path in llm_paths:
        llm_record = read_json_if_exists(llm_path)
        for field in ("request_path", "compact_retry_request_path"):
            value = llm_record.get(field)
            if value:
                evidence.append((field, Path(str(value))))

    unique: list[tuple[str, Path]] = []
    seen: set[Path] = set()
    for role, path in evidence:
        resolved = path.resolve()
        if resolved in seen or not resolved.is_file():
            continue
        seen.add(resolved)
        unique.append((role, resolved))
    return unique


def next_repair_loop_iteration(loop_dir: Path) -> int:
    iteration_numbers: list[int] = []
    for path in loop_dir.glob("iteration_*"):
        if not path.is_dir():
            continue
        match = re.fullmatch(r"iteration_(\d+)", path.name)
        if match:
            iteration_numbers.append(int(match.group(1)))
    return max(iteration_numbers, default=0) + 1


def archive_repair_loop_iteration(
    *,
    loop_dir: Path,
    iteration: int,
    source_sacg_state: Path,
    report_path: Path,
    report: dict[str, Any],
    disposition: dict[str, Any],
    started_at_unix_sec: float,
) -> Path:
    iteration_dir = loop_dir / f"iteration_{iteration:04d}"
    iteration_dir.mkdir(parents=True, exist_ok=False)
    snapshots = []
    for index, (role, source_path) in enumerate(repair_loop_evidence_paths(report)):
        snapshot_path = iteration_dir / f"{index:02d}_{role}_{source_path.name}"
        shutil.copy2(source_path, snapshot_path)
        snapshots.append(
            {
                "role": role,
                "source_path": str(source_path),
                "source_sha256": sha256_file(source_path),
                "snapshot_path": str(snapshot_path),
            }
        )
    upstream_replan = disposition.get("upstream_capability_replan")
    if isinstance(upstream_replan, dict):
        for row in upstream_replan.get("artifacts", []):
            if not isinstance(row, dict) or not row.get("path"):
                continue
            source_path = Path(str(row["path"])).resolve()
            if not source_path.is_file():
                continue
            snapshot_path = (
                iteration_dir
                / f"{len(snapshots):02d}_upstream_capability_{source_path.name}"
            )
            shutil.copy2(source_path, snapshot_path)
            snapshots.append(
                {
                    "role": "upstream_capability_replan",
                    "source_path": str(source_path),
                    "source_sha256": sha256_file(source_path),
                    "snapshot_path": str(snapshot_path),
                }
            )
    board_source_state = exact_board_source_state(
        run_dir_from_state(source_sacg_state)
    )
    record = {
        "schema_version": "spatialaccagent.stage6_repair_loop_iteration.v1",
        "iteration": iteration,
        "source_sacg_state": str(source_sacg_state),
        "started_at_unix_sec": started_at_unix_sec,
        "finished_at_unix_sec": time.time(),
        "repair_execution_report_path": str(report_path),
        "repair_execution_report": report,
        "disposition": disposition,
        "evidence_snapshots": snapshots,
        "board_source_state": board_source_state,
    }
    record_path = iteration_dir / "iteration_record.json"
    write_json(record_path, record)
    try:
        experience_ingest = record_repair_iteration_experience(
            record_path,
            run_dir=run_dir_from_state(source_sacg_state),
        )
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        experience_ingest = {
            "schema_version": "spatialaccagent.repair_experience_ingest.v1",
            "status": "deferred",
            "summary": str(exc),
            "recorded": 0,
        }
    write_json(
        loop_dir / "status.json",
        {
            "schema_version": "spatialaccagent.stage6_repair_loop_status.v1",
            "latest_iteration": iteration,
            "latest_iteration_record": str(record_path),
            "status": disposition.get("status"),
            "summary": disposition.get("summary"),
            "repair_experience_ingest": experience_ingest,
        },
    )
    return record_path


def resume_exact_board_failure_agent_replan(
    current_state: Path,
) -> tuple[Path | None, dict[str, Any]]:
    """Replan an already-recorded exact-board Agent handoff before replay.

    This is restart recovery only.  It consumes an existing hash-bound failure
    record and never launches a tool; an invalid planner result remains
    fail-closed and leaves the persisted state unchanged.
    """

    from accagent.framework.stage_repair import plan_repair

    repair_report_path, repair_report = plan_repair(ns_obj(current_state))
    repair_plan_path = Path(
        str(repair_report.get("outputs", {}).get("repair_plan") or "")
    )
    candidate_state = Path(
        str(repair_report.get("outputs", {}).get("sacg_state") or "")
    )
    repair_plan = read_json_if_exists(repair_plan_path)
    workflow = (
        repair_plan.get("repair_workflow", {})
        if isinstance(repair_plan.get("repair_workflow"), dict)
        else {}
    )
    ready_steps = [
        step
        for step in workflow.get("steps", [])
        if isinstance(step, dict)
        and step.get("status") in {"ready_for_agent_patch", "ready_to_execute"}
        and step.get("source") != "prior_nonfallback_llm_required_capability"
    ]
    passed = (
        workflow.get("status") == "ready"
        and bool(ready_steps)
        and candidate_state.is_file()
        and repair_plan_path.is_file()
        and repair_report_path.is_file()
    )
    report = {
        "status": "pass" if passed else "fail",
        "summary": (
            "Stage 6 rebuilt an Agent repair plan from the recorded exact-board failure"
            if passed
            else "Stage 6 did not rebuild an executable Agent repair plan from the recorded exact-board failure"
        ),
        "ready_step_ids": [str(step.get("id")) for step in ready_steps],
        "artifacts": [
            {
                "role": role,
                "path": str(path),
                "sha256": sha256_file(path) if path.is_file() else None,
            }
            for role, path in (
                ("repair_report", repair_report_path),
                ("repair_plan", repair_plan_path),
                ("repair_sacg_state", candidate_state),
            )
        ],
    }
    return (candidate_state.resolve() if passed else None), report


def run_repair_loop(args: argparse.Namespace) -> tuple[Path, dict[str, Any]]:
    current_state = args.sacg_state.resolve()
    run_dir = run_dir_from_state(current_state)
    loop_dir = run_dir / "repair_execution" / "loop"
    loop_dir.mkdir(parents=True, exist_ok=True)
    iteration = next_repair_loop_iteration(loop_dir)
    completed_iterations = 0
    controller_binding = f"stage6:{os.getpid()}"
    try:
        activate_live_state_slot(
            run_dir,
            "controller",
            {
                "status": "running",
                "verification_layer": "layer3_real_board_axi_ddr",
                "loop": "observe_repair_verify",
                "iteration": iteration,
            },
            binding=controller_binding,
        )
    except OSError:
        pass
    while True:
        try:
            update_live_state_slot(
                run_dir,
                "controller",
                {
                    "status": "running",
                    "verification_layer": "layer3_real_board_axi_ddr",
                    "loop": "observe_repair_verify",
                    "iteration": iteration,
                },
                binding=controller_binding,
            )
        except OSError:
            pass
        iteration_args = copy.copy(args)
        iteration_args.sacg_state = current_state
        started_at = time.time()
        report_path, report = execute_repair(iteration_args)
        disposition = repair_loop_disposition(report)
        # Prototype policy: prior transactions and repeated tool failures are
        # evidence for the next decision, never a second control plane that
        # can stop the current-layer observe -> repair -> verify loop.
        replanned_state: Path | None = None
        current_failure_agent_replan = (
            disposition.get("status") == "continue"
            and disposition.get("exact_board_failure_handoff") is True
        )
        if (
            disposition.get("upstream_capability_replan_required") is True
            or disposition.get("capability_producer_replan_required") is True
            or current_failure_agent_replan
        ):
            next_state = report_path.parent / "sacg_state.json"
            try:
                from accagent.framework.stage_repair import plan_repair

                if not next_state.is_file():
                    raise ValueError(
                        "Stage 6 did not publish the SACG state required for upstream replan"
                    )
                repair_report_path, repair_report = plan_repair(ns_obj(next_state))
                repair_plan_path = Path(
                    str(repair_report.get("outputs", {}).get("repair_plan") or "")
                )
                candidate_state = Path(
                    str(repair_report.get("outputs", {}).get("sacg_state") or "")
                )
                repair_plan = read_json_if_exists(repair_plan_path)
                workflow = (
                    repair_plan.get("repair_workflow", {})
                    if isinstance(repair_plan.get("repair_workflow"), dict)
                    else {}
                )
                prior_capability_request = (
                    disposition.get("upstream_capability_replan_required") is True
                )
                ready_steps = [
                    step
                    for step in workflow.get("steps", [])
                    if isinstance(step, dict)
                    and step.get("status") in {"ready_for_agent_patch", "ready_to_execute"}
                    and (
                        step.get("source")
                        == "prior_nonfallback_llm_required_capability"
                        if prior_capability_request
                        else step.get("source")
                        != "prior_nonfallback_llm_required_capability"
                    )
                ]
                superseded_capability_request = False
                if prior_capability_request and not ready_steps:
                    # A fresh Stage 6 Agent decision may replace an earlier
                    # producer request after it sees the complete current
                    # evidence.  Keep that new bounded plan executable; the
                    # old producer request must not become a permanent loop
                    # condition when the Agent has explicitly superseded it.
                    ready_steps = [
                        step
                        for step in workflow.get("steps", [])
                        if isinstance(step, dict)
                        and step.get("status")
                        in {"ready_for_agent_patch", "ready_to_execute"}
                        and step.get("source")
                        != "prior_nonfallback_llm_required_capability"
                    ]
                    superseded_capability_request = bool(ready_steps)
                replan_passed = (
                    workflow.get("status") == "ready"
                    and bool(ready_steps)
                    and candidate_state.is_file()
                    and repair_plan_path.is_file()
                    and repair_report_path.is_file()
                )
                replan = {
                    "status": "pass" if replan_passed else "fail",
                    "superseded_capability_request": superseded_capability_request,
                    "summary": (
                        (
                            "Stage 6 rebuilt an executable plan that supersedes the prior upstream capability request"
                            if superseded_capability_request
                            else "Stage 6 rebuilt an executable plan for the requested upstream capability"
                        if prior_capability_request
                        else (
                                "Stage 6 rebuilt an executable current-layer Agent repair from the newly completed exact-board failure"
                                if current_failure_agent_replan
                                else "Stage 6 rebuilt an executable current-layer Agent repair after capability production"
                            )
                        )
                        if replan_passed
                        else (
                            "Stage 6 did not produce an executable upstream capability plan"
                            if prior_capability_request
                            else (
                                "Stage 6 did not produce an executable current-layer Agent repair from the newly completed exact-board failure"
                                if current_failure_agent_replan
                                else "Stage 6 did not produce an executable current-layer Agent repair after capability production"
                            )
                        )
                    ),
                    "ready_step_ids": [str(step.get("id")) for step in ready_steps],
                    "artifacts": [
                        {
                            "role": role,
                            "path": str(path),
                            "sha256": sha256_file(path) if path.is_file() else None,
                        }
                        for role, path in (
                            ("repair_report", repair_report_path),
                            ("repair_plan", repair_plan_path),
                            ("repair_sacg_state", candidate_state),
                        )
                    ],
                }
                disposition["upstream_capability_replan"] = replan
                if replan_passed:
                    replanned_state = candidate_state.resolve()
                else:
                    disposition = {
                        **disposition,
                        "status": "blocked",
                        "summary": replan["summary"],
                    }
            except Exception as exc:
                disposition = {
                    **disposition,
                    "status": "blocked",
                    "summary": f"upstream capability replan failed: {exc}",
                    "upstream_capability_replan": {
                        "status": "fail",
                        "summary": str(exc),
                        "artifacts": [],
                    },
                }
        completed_iterations += 1
        if (
            disposition.get("status") == "continue"
            and args.max_loop_iters > 0
            and completed_iterations >= args.max_loop_iters
        ):
            disposition = {
                **disposition,
                "status": "blocked",
                "summary": f"explicit Stage 6 loop iteration limit reached: {args.max_loop_iters}",
            }
        iteration_record = archive_repair_loop_iteration(
            loop_dir=loop_dir,
            iteration=iteration,
            source_sacg_state=current_state,
            report_path=report_path,
            report=report,
            disposition=disposition,
            started_at_unix_sec=started_at,
        )
        print(
            f"stage6 repair loop iteration={iteration} status={disposition['status']} "
            f"record={iteration_record}",
            flush=True,
        )
        if disposition.get("status") != "continue":
            try:
                update_live_state_slot(
                    run_dir,
                    "controller",
                    {
                        "status": str(disposition.get("status") or "finished"),
                        "verification_layer": "layer3_real_board_axi_ddr",
                        "loop": "observe_repair_verify",
                        "iteration": iteration,
                        "summary": disposition.get("summary"),
                    },
                    binding=controller_binding,
                )
            except OSError:
                pass
            return report_path, {**report, "repair_loop_disposition": disposition}
        next_state = report_path.parent / "sacg_state.json"
        if replanned_state is not None:
            current_state = replanned_state
        elif next_state.is_file():
            current_state = next_state.resolve()
        iteration += 1


def update_sacg(source_state: Path, target_state: Path, report_path: Path, report: dict[str, Any]) -> str:
    copy_state(source_state, target_state)
    store = SACGStore(target_state)
    existing = {str(item.get("id")) for item in store.state.get("constraints", [])}
    touched = [cid for cid in TOUCHED_CONSTRAINTS if cid in existing] or ["constraint.verification.plan"]
    plan_path = Path(str(report.get("repair_plan") or ""))
    if plan_path and not plan_path.is_absolute():
        plan_path = (report_path.parent / plan_path).resolve()
    repair_plan = read_json_if_exists(plan_path) if plan_path.is_file() else {}
    diagnostics = (
        repair_plan.get("diagnostics", {})
        if isinstance(repair_plan.get("diagnostics"), dict)
        else {}
    )
    repair_loop = (
        diagnostics.get("hierarchical_repair_loop", {})
        if isinstance(diagnostics.get("hierarchical_repair_loop"), dict)
        else {}
    )
    current_layer = (
        repair_loop.get("current_layer", {})
        if isinstance(repair_loop.get("current_layer"), dict)
        else {}
    )
    first_action = next(
        (
            row
            for row in repair_plan.get("repair_actions", [])
            if isinstance(row, dict)
        ),
        {},
    )
    memory_context = hierarchy_memory_context(
        debug_layer=current_layer.get("id") or first_action.get("debug_layer"),
        failed_gates=repair_loop.get("failed_current_layer_gates", [])
        or first_action.get("failed_current_layer_gates", []),
    )
    transition = store.declare_transition(
        action_type="repair_execution",
        touched_nodes=[],
        touched_edges=[],
        touched_constraints=touched,
        note="Executed bounded repair workflow steps.",
        context=memory_context,
    )
    store.bind_artifact(
        "artifact.stage6.repair_execution_report",
        str(report_path),
        "stage.repair_execution_report",
        [],
        [],
        touched,
        transition["id"],
    )
    if report.get("errors"):
        store.reject(transition["id"], "one or more repair execution steps failed")
    else:
        store.reject(transition["id"], "repair execution completed; Stage 6 verification rerun is required before promotion")
    store.save()
    return transition["id"]


def parse_args(argv: list[str] | None = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Execute bounded Stage 6 repair workflow")
    parser.add_argument("--sacg-state", type=Path, required=True)
    parser.add_argument("--execute-reruns", action="store_true")
    parser.add_argument("--include-remote", action="store_true")
    parser.add_argument(
        "--timeout-sec",
        type=int,
        default=0,
        help="outer real-tool wall-clock timeout in seconds; <=0 waits without a wall-clock limit",
    )
    parser.add_argument(
        "--loop-until-pass",
        action="store_true",
        help="repeat only this Stage 6 repair/current-layer verification chain while each iteration applies a new patch",
    )
    parser.add_argument(
        "--max-loop-iters",
        type=int,
        default=0,
        help="optional Stage 6 loop iteration limit; <=0 is unbounded",
    )
    return parser.parse_args(argv)


def main(argv: list[str] | None = None) -> int:
    args = parse_args(argv)
    try:
        report_path, report = (
            run_repair_loop(args)
            if args.loop_until_pass
            else execute_repair(args)
        )
        if report["errors"]:
            for error in report["errors"]:
                print(f"error: {error}")
            print(report_path)
            return 1
        print(report_path)
        return 0
    except (OSError, ValueError, json.JSONDecodeError, KeyError) as exc:
        print(f"error: {exc}")
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
